comms.text:
@1 וּמַלִיל יְיָ עִם משֶׁה בְּמַדְבְּרָא דְסִינַי בְּמַשְׁכַּן זִמְנָא בְּחַד לְיַרְחָא תִנְיָנָא בְּשַׁתָּא תִנְיֵתָא לְמִפַּקְהוֹן מֵאַרְעָא דְמִצְרַיִם לְמֵימָר:
@2 קַבִּילוּ יָת חֻשְׁבַּן כָּל כְּנִשְׁתָּא דִּבְנֵי יִשְׂרָאֵל לְזַרְעֲ יַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן כָּל דְכוּרָא לְגֻלְגְלַתְהוֹן:
@3 מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כָּל נָפֵק חֵילָא בְּיִשְׂרָאֵל תִּמְנוּן יָתְהוֹן לְחֵילֵיהוֹן אַתְּ וְאַהֲרֹן:
@4 וְעִמְכוֹן יְהוֹן גַבְרָא גַבְרָא לְשִׁבְטָא גְבַר רֵישׁ לְבֵית אֲבָהָתוֹהִי הוּא:
@5 וְאִלֵין שְׁמָהַת גֻבְרַיָא דִי יְקוּמוּן עִמְכוֹן לִרְאוּבֵן אֶלִיצוּר בַּר שְׁדֵיאוּר:
@6 לְשִׁמְעוֹן שְׁלֻמִיאֵל בַּר צוּרִישַׁדָי:
@7 לִיהוּדָה נַחְשׁוֹן בַּר עַמִינָדָב:
@8 לְיִשָׂשׂכָר נְתַנְאֵל בַּר צוּעָר:
@9 לִזְבוּלֻן אֱלִיאָב בַּר חֵלֹן:
@10 לִבְנֵי יוֹסֵף לְאֶפְרַיִם אֱלִישָׁמָע בַּר עַמִיהוּד לִמְנַשֶׁה גַמְלִיאֵל בַּר פְּדָהצוּר:
@11 לְבִנְיָמִן אֲבִידָן בַּר גִדְעֹנִי:
@12 לְדָן אֲחִיעֶזֶר בַּר עַמִישַׁדָי:
@13 לְאָשֵׁר פַּגְעִיאֵל בַּר עָכְרָן:
@14 לְגָד אֶלְיָסָף בַּר דְעוּאֵל:
@15 לְנַפְתָּלִי אֲחִירַע בַּר עֵינָן:
@16 אִלֵין מְעַרְעֵי כְנִשְׁתָּא רַבְרְבֵי שִׁבְטֵי אֲבָהַתְהוֹן רֵישֵׁי אַלְפַיָא דְיִשְׂרָאֵל אִנוּן:
@17 וּדְבַר משֶׁה וְאַהֲרֹן יָת גֻבְרַיָא הָאִלֵין דִי אִתְפָּרָשׁוּ בִּשְׁמָהָן:
@18 וְיָת כָּל כְּנִשְׁתָּא אַכְנָשׁוּ בְּחַד לְיַרְחָא תִנְיָנָא וְאִתְיַחֲסוּ עַל זַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא לְגֻלְגְלַתְהוֹן:
@19 כְּמָא דִי פַקֵד יְיָ יָת משֶׁה וּמְנָנוּן בְּמַדְבְּרָא דְסִינָי:
@20 וַהֲווֹ בְנֵי רְאוּבֵן בּוּכְרָא דְיִשְׂרָאֵל תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן לְגֻלְגְלַתְהוֹן כָּלּ דְכוּרָא מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@21 מִנְיָנֵיהוֹן לְשִׁבְטָא דִרְאוּבֵן אַרְבְּעִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@22 לִבְנֵי שִׁמְעוֹן תּוּלְדַתְהוֹן לְזַרְעֲ יַתְהוֹן לְבֵית אֲבָהַתְהוֹן מִנְיָנוֹהִי בְּמִנְיַן שְׁמָהָן לְגֻלְגְלַתְהוֹן כָּל דְכוּרָא מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@23 מִנְיָנֵיהוֹן לְשִׁבְטָּא דְשִׁמְעוֹן חַמְשִׁין וּתְשַׁע אַלְפִין וּתְלַת מְאָה:
@24 לִבְנֵי גָד תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@25 מִנְיָנֵיהוֹן לְשִׁבְטָא דְּגָד אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְשִׁית מְאָה וְחַמְשִׁין:
@26 לִבְנֵי יְהוּדָה תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@27 מִנְיָנֵיהוֹן לְשִׁבְטָּא דִיהוּדָה שַׁבְעִין וְאַרְבְּעָא אַ:לפִין וְשִׁית מְאָה:
@28 לִבְנֵי יִשָׂשכָר תּוּלְדַתְהוֹן לְזַרְעֲ יַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@29 מִנְיָנֵיהוֹן לְשִׁבְטָא דְיִשָׂשכָר חַמְשִׁין וְאַרְבְּעָא אַלְפִין וְאַרְבַּע מְאָה:
@30 לִבְנֵי זְבוּלֻן תּוּלְדַתְהוֹן לְזַ רְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָּא כֹל נָפֵק חֵילָא:
@31 מִנְיָנֵיהוֹן לְשִׁבְטָא דִזְבוּלֻן חַמְשִׁין וּשְׁבַע אַלְפִין וְאַרְבַּע מְאָה:
@32 לִבְנֵי יוֹסֵף לִבְנֵי אֶפְרַיִם תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@33 מִנְיָנֵיהוֹן לְשִׁבְטָא דְאֶפְרָיִם אַרְבְּעִין אַלְפִין וַחֲמֵשׁ מְאָה:
@34 לִבְנֵי מְנַשֶׁה תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@35 מִנְיָנֵיהוֹן לְשִׁבְטָא דִמְנַשֶׁה תְּלָתִין וּתְרֵין אַלְפִין וּמָאתָן:
@36 לִבְנֵי בִנְיָמִן תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@37 מִנְיָנֵיהוֹן לְשִׁבְטָא דְבִנְיָמִן תְּלָתִין וְחַמְשָׁא אַלְפִין וְאַרְבַּע מְאָה:
@38 לִבְנֵי דָן תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@39 מִנְיָנֵיהוֹן לְשִׁבְטָּא דְדָן שִׁתִּין וּתְרֵין אַלְפִין וּשְׁבַע מְאָה:
@40 לִבְנֵי אָשֵׁר תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כֹּל נָפֵק חֵילָא:
@41 מִנְיָנֵיהוֹן לְשִׁבְטָא דְאָשֵׁר אַרְבְּעִין וְחַד אַלְפִין וַחֲמֵשׁ מְאָה:
@42 בְּנֵי נַפְתָּלִי תּוּלְדַתְהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן בְּמִנְיַן שְׁמָהָן מִבַּר עַשְׂרִין שְׁנִין לְעֵלָא כֹּל נָפֵק חֵילָא:
@43 מִנְּיָנֵיהוֹן לְשִׁבְטָא דְנַפְתָּלִי חַמְשִׁין וּתְלָתָא אַלְפִין וְאַרְבַּע מְאָה:
@44 אִלֵין מִנְיָנַיָא דִי מְנָא משֶׁה וְאַהֲרֹן וְרַבְרְבֵי יִשְׂרָאֵל תְּרֵי עֲשַׂר גֻבְרִין גַבְרָא חַד לְבֵית אֲבָהָתוֹהִי הֲווֹ:
@45 וַהֲווֹ כָּל מִנְיָנֵי בְנֵי יִשְׂרָאֵל לְבֵית אֲבָהַתְהוֹן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא כָּל נָפֵק חֵילָא בְּיִשְׂרָאֵל:
@46 וַהֲווֹ כָּל מִנְיָנַיָא שִׁית מְאָה וּתְלָתָא אַלְפִין וַחֲמֵשׁ מְאָה וְחַמְשִׁין:
@47 וְלֵוָאֵי לְשִׁבְטָא דַאֲבָהַתְהוֹן לָא אִתְמְנִיאוּ בֵּינֵיהוֹן:
@48 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@49 בְּרַם יָת שִׁבְטָא דְלֵוִי לָא תִמְנֵי וְיָת חֻשְׁבַּנְהוֹן לָא תְקַבֵּל בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@50 וְאַתְּ מַנִי יָת לֵוָאֵי עַל מַשְׁכְּנָא דְסַהֲדוּתָא וְעַל כָּל מָנוֹהִי וְעַל כָּל דִּי לֵהּ אִנּוּן יִטְלוּן יָת מַשְׁכְּנָא וְיָת כָּל מָנוֹהִי וְאִנוּן יְשַׁמְשֻׁנֵהּ וּסְחוֹר סְחוֹר לְמַשְׁכְּנָא יִשְׁרוּן:
@51 וּבְמֵטַל מַשְׁכְּנָא יְפַרְקוּן יָתֵהּ לֵוָאֵי וּבְמִשְׁרֵי מַשְׁכְּנָא יְקִימוּן יָתֵהּ לֵוָאֵי וְחִלוֹנַי דְיִקְרַב יִתְקְטֵל:
@52 וְיִשְׁרוּן בְּנֵי יִשְׂרָאֵל גְבַר עַל מַשְׁרוֹהִי וּגְבַר עַל טִּקְסֵהּ לְחֵילֵיהוֹן:
@53 וְלֵוָאֵי יִשְׁרוּן סְחוֹר סְחוֹר לְמַשְׁכְּנָא דְסַהַדוּתָא וְלָא יְהֵי רוּגְזָא עַל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְיִטְרוּן לֵוָאֵי יָת מַטְרַת מַשְׁכְּנָא דְסַהֲדוּתָא:
@54 וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּכֹל דִּי פַּקֵיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ:
@55 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@56 גְבַר עַל טִּקְסֵהּ בְּאַתְוָן לְבֵית אֲבָהַתְהוֹן יִשְׁרוּן בְּנֵי יִשְׂרָאֵל מִלָקֳבֵל סְחוֹר סְחוֹר לְמַשְׁכַּן זִמְנָא יִשְׁרוּן:
@57 וְדִי שְׁרַן קִדוּמָא מַדִינְחָא טֵקַס מַשְׁרִית יְהוּדָה לְחֵילֵיהוֹן וְרַבָּא לִבְנֵי יְהוּדָה נַחְשׁוֹן בַּר עַמִינָדָב:
@58 וְחֵילֵיהּ וּמִנְיָנֵיהוֹן שַׁבְעִין וְאַרְבְּעָא אַלְפִין וְשִׁית מְאָה:
@59 וְדִי שְׁרַן סְמִיכִין עֲלוֹהִי שִׁבְטָא דְיִשָׂשכָר וְרַבָּא לִבְנֵי יִשָׂשכָר נְתַנְאֵל בַּר צוּעָר:
@60 וְחֵילֵהּ וּמִנְיָנוֹהִי חַמְשִׁין וְאַרְבְּעָא אַלְפִין וְאַרְבַּע מְאָה:
@61 שִׁבְטָא דִזְבוּלֻן וְרַבָּא לִבְנֵי זְבוּלֻן אֱלִיאָב בַּר חֵלוֹן:
@62 וְחֵילֵהּ וּמִנְיָנוֹהִי חַמְשִׁין וְשַׁבְעָא אַלְפִין וְאַרְבַּע מְאָה:
@63 כָּל מִנְיָנַיָא לְמַשְׁרִית יְהוּדָה מְאָה וּתְמָנָן וְשִׁתָּא אַלְפִין וְאַרְבַּע מְאָה לְחֵילֵיהוֹן בְּקַדְמֵיתָא נַטְלִין:
@64 טֵקַס מַשְׁרִית רְאוּבֵן דָרוֹמָא לְחֵילֵיהוֹן וְרַבָּא לִבְנֵי רְאוּבֵן אֱלִיצוּר בַּר שְׁדֵיאוּר:
@65 וְחֵילֵהּ וּמִנְיָנוֹהִי אַרְבְּעִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@66 וְדִי שְׁרַן סְמִיכִין עֲלוֹהִי שִׁבְטָא דְשִׁמְעוֹן וְרַבָּא לִבְנֵי שִׁמְעוֹן שְׁלֻמִיאֵל בַּר צוּרִישַׁדָי:
@67 וְחֵילֵהּ וּמִנְיָנֵיהוֹן חַמְשִׁין וּתְשַׁע אַלְפִין וּתְלַת מְאָה:
@68 וְשִׁבְטָא דְגָד וְרַבָּא לִבְנֵי גָד אֶלְיָסָף בַּר רְעוּאֵל:
@69 וְחֵילֵהּ וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְשִׁית מְאָה וְחַמְשִׁין:
@70 כָּל מִנְיָנַיָא לְמַשְׁרִית רְאוּבֵן מְאָה וְחַמְשִׁין וְחַד אַלְפִין וְאַרְבַּע מְאָה וְחַמְשִׁין לְחֵילֵיהוֹן בְּתִנְיֵתָא נַטְלִין:
@71 וְנַטֵל מַשְׁכַּן זִמְנָא מַשְׁרִית לֵוָאֵי בְּגוֹ מַשִּׁרְיָתָא כְּמָא דְשָׁרַן כֵּן נָטְלִין גְבַר עַל אַתְרֵהּ לְטִקְסֵיהוֹן:
@72 טֵּקַס מַשְׁרִית אֶפְרַיִם לְחֵילֵיהוֹן מַעַרְבָא וְרַבָּא לִבְנֵי אֶפְרַיִם אֱלִישָׁמָע בַּר עַמִיהוּד:
@73 וְחֵילֵהּ וּמִנְיָנֵיהוֹן אַרְבְּעִין אַלְפִין וַחֲמֵשׁ מְאָה:
@74 וְדִסְמִיכִין עֲלוֹהִי שִׁבְטָא דִמְנַשֶׁה וְרַבָּא לִבְנֵי מְנַשֶׁה גַמְלִיאֵל בַּר פְדָהצוּר:
@75 וְחֵילֵהּ וּמִנְיָנֵיהוֹן תְּלָתִין וּתְרֵין אַלְפִין וּמָאתָן:
@76 וְשִׁבְטָא דְבִנְיָמִן וְרַבָּא לִבְנֵי בִנְיָמִן אֲבִידָן בַּר גִדְעוֹנִי:
@77 וְחֵילֵהּ וּמִנְיָנֵיהוֹן תְּלָתִין וְחַמְשָׁא אַלְפִין וְאַרְבַּע מְאָה:
@78 כָּל מִנְיָנַיָא לְמַשְׁרִית אֶפְרַיִם מְאָה וְתַמְנֵי אַלְפִין וּמְאָה לְחֵילֵיהוֹן בִּתְלִיתֵתָא נָטְלִין:
@79 טֵקַס מַשְׁרִית דָן צִפּוּנָא לְחֵילֵיהוֹן וְרַבָּא לִבְנֵי דָן אֲחִיעֶזֶר בַּר עַמִישַׁדָי:
@80 וְחֵילֵהּ וּמִנְיָנֵיהוֹן שִׁתִּין וּתְרֵין אַלְפִין וּשְׁבַע מְאָה:
@81 וְדִי שְׁרַן םְמִכִין עֲלוֹהִי שִׁבְטָא דְאָשֵׁר וְרַבָּא לִבְנֵי אָשֵׁר פַּגְעִיאֵל בַּר עָכְרָן:
@82 וְחֵילֵהּ וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַד אַלְפִין וַחֲמֵשׁ מְאָה:
@83 וְשִׁבְטָא דְנַפְתָּלִי וְרַבָּא לִבְנֵי נַפְתָּלִי אֲחִירַע בַּר עֵינָן:
@84 וְחֵילֵהּ וּמִנְיָנֵיהוֹן חַמְשִׁין וּתְלָתָא אַלְפִין וְאַרְבַּע מְאָה:
@85 כָּל מִנְיָנַיָא לְמַשְׁרִית דָן מְאָה וְחַמְשִׁין וְשַׁבְעָא אַלְפִין וְשִׁית מְאָה בְּבַתְרֵתָא נָטְלִין לְטִקְסֵיהוֹן:
@86 אִלֵין מִנְיָנֵי בְנֵי יִשְׂרָאֵל לְבֵית אֲבָהַתְהוֹן כָּל מִנְיָנֵי מַשִׁרְיָתָא לְחֵילֵיהוֹן שִׁית מְאָהּ וּתְלָתָא אַלְפִין וַחֲמֵשׁ מְאָה וְחַמְשִׁין:
@87 וְלֵוָאֵי לָא אִתְמְנִיאוּ בְּגוֹ בְּנֵי יִשְׂרָאֵל כְּמָא דְפַקֵיד יְיָ יָת משֶׁה:
@88 וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּכֹל דִי פַקֵיד יְיָ יָת משֶׁה כֵּן שָׁרַן לְטִּקְסֵיהוֹן וְכֵן נָטְלִין גְבַר לְזַרְעִיתֵיהּ עַל בֵּית אֲבָהָתוֹהִי:
@89 וְאִלֵין תּוּלְדַת אַהֲרֹן וּמשֶׁה בְּיוֹמָא דְמַלִיל יְיָ עִם משֶׁה בְּטוּרָא דְסִינָי:
@90 וְאִלֵין שְׁמָהַת בְּנֵי אַהֲרֹן בּוּכְרָא נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר:
@91 אִלֵין שְׁמָהַת בְּנֵי אַהֲרֹן כַּהֲנַיָא דְאִתְרַבִּיאוּ דִי אִתְקָרֵב קֻרְבַּנְהוֹן לְשַׁמָשָׁא:
@92 וּמִית נָדָב וַאֲבִיהוּא קֳדָם יְיָ בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ בְּמַדְבְּרָא דְסִינַי וּבְנִין לָא הֲווֹ לְהוֹן וְשַׁמֵּשׁ אֶלְעָזָר וְאִיתָמָר עַל אַפֵּי אַהֲרֹן אֲבוּהוֹן:
@93 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@94 קָרֵב יָת שִׁבְטָּא דְלֵוִי וּתְקֵים יָתֵהּ קֳדָם אַהֲרֹן כַּהֲנָא וִישַׁמְשׁוּן יָתֵהּ:
@95 וְיִטְרוּן יָת מַטַרְתֵּהּ וְיָת מַטְרַת כָּל כְּנִשְׁתָּא קֳדָם מַשְׁכַּן זִמְנָא לְמִפְלַח יָת פָּלְחַן מַשְׁכְּנָא:
@96 וְיִטְרוּן יָת כָּל מָאנֵי מַשְׁכַּן זִמְנָא וְיָת מַטְּרַת בְּנֵי יִשְׂרָאֵל לְמִפְלַח יָת פָּלְחַן מַשְׁכְּנָא:
@97 וְתִתֵּן יָת לֵוָאֵי לְאַהֲרֹן וְלִבְנוֹהִי מְסִירִין יְהִיבִין אִנוּן לֵהּ מִן בְּנֵי יִשְׂרָאֵל:
@98 וְיָת אַהֲרֹן וְיָת בְּנוֹהִי תְּמַנֵי וְיִטְרוּן יָת כְּהֻנַתְהוֹן וְחִלוֹנַי דְיִקְרַב יִתְקְטֵל:
@99 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@100 וַאֲנָא הָא קְרֵבִית יָת לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל חֲלַף כָּל בּוּכְרָא פְּתַח וַלְדָא מִבְּנֵי יִשְׂרָאֵל וִיהוֹן מְשַׁמְשִׁין קֳדָמַי לֵוָאֵי:
@101 אֲרֵי דִילִי כָּל בּוּכְרָא בְּיוֹמָא דִקְטָלִית כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם אַקְדֵשִׁית קֳדָמַי כָּל בּוּכְרָא בְּיִשְׂרָאֵל מֵאֱנָשָׁא עַד בְּעִירָא דִילִי יְהוֹן אֲנָא יְיָ:
@102 וּמַלִיל יְיָ עִם משֶׁה בְּמַדְבְּרָא דְסִינַי לְמֵימָר:
@103 מְנֵי יָת בְּנֵי לֵוִי לְבֵית אֲבָהַתְהוֹן לְזַרְעֲיַתְהוֹן כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵלָא תִּמְנִנוּן:
@104 וּמְנָא יָתְהוֹן משֶׁה עַל מֵימְרָא דַיְיָ כְּמָא דְאִתְפַּקָד:
@105 וַהֲווֹ אִלֵין בְּנֵי לֵוִי בִּשְׁמָהַתְהוֹן גֵרְשׁוֹן וּקְהָת וּמְרָרִי:
@106 וְאִלֵין שְׁמָהַת בְּנֵי גֵרְשׁוֹן לְזַרְעֲיַתְהוֹן לִבְנִי וְשִׁמְעִי:
@107 וּבְנֵי קְהָת לְזַרְעֲיַתְהוֹן עַמְרָם וְיִצְהָר חֶבְרוֹן וְעֻזִיאֵל:
@108 וּבְנֵי מְרָרִי לְזַרְעֲיַתְהוֹן מַחְלִי וּמוּשִׁי אִלֵין אִנוּן זַרְעֲיַת לֵוָאֵי לְבֵית אֲבָהַתְהוֹן:
@109 לְגֵרְשׁוֹן זַרְעִית לִבְנִי וְזַרְעִית שִׁמְעִי אִלֵין אִנוּן זַרְעֲיַת גֵרְשׁוֹן:
@110 מִנְיָנֵיהוֹן בְּמִנְיַן כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵלָא מִנְיָנֵיהוֹן שַׁבְעָא אַלְפִין וַחֲמֵשׁ מְאָה:
@111 זַרְעֲיַת גֵרְשׁוֹן אֲחוֹרֵי מַשְׁכְּנָא יִשְּׁרוּן מַעַרְבָא:
@112 וְרַב בֵּית אַבָּא לְבֵית גֵרְשׁוֹן אֶלְיָסָף בַּר לָאֵל:
@113 וּמַטְרַת בְּנֵי גֵרְשׁוֹן בְּמַשְׁכַּן זִמְנָא מַשְׁכְּנָא וּפְרָסָא חוֹפָאֵהּ וּפְרָסָא דִתְרַע מַשְׁכַן זִמְנָא:
@114 וּסְרָדֵי דְדַרְתָּא וְיָת פְּרָסָא דִתְרַע דַרְתָּא דִי עַל מַשְׁכְּנָא וְעַל מַדְבְּחָא סְחוֹר סְחוֹר וְיָת אַטוּנוֹהִי לְכֹל פּוּלְחָנֵהּ:
@115 וְלִקְהָת זַרְעִית עַמְרָם וְזַרְעִית יִצְהָר וְזַרְעִית חֶבְרוֹן וְזַרְעִית עֻזִיאֵל אִלֵין אִנוּן זַרְעֲיַת קְהָת:
@116 בְּמִנְיַן כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵלָא תְּמַנְיָא אַלְפִין וְשִׁית מְאָה נַטְּרֵי מַטַרְתָּא דְקוּדְשָׁא:
@117 זַרְעֲיַת בְּנֵי קְהָת יִשְׁרוּן עַל צִדָא דְמַשְׁכְּנָא דָרוֹמָא:
@118 וְרַב בֵּית אַבָּא לְזַרְעֲיַת קְהָת אֱלִיצָפָן בַּר עֻזִיאֵל:
@119 וּמַטַרְתְּהוֹן אֲרוֹנָא וּפְתוֹרָא וּמְנַרְתָּא וּמַדְבְּחַיָא וּמָנֵי קוּדְשָׁא דִי יְשַׁמְשׁוּן בְּהוֹן וּפְרָסָא וְכֹל פוּלְחָנֵהּ:
@120 וַאֲמַרְכְּלָא דִמְמַנָא עַל רַבְרְבֵי לֵוָאֵי אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא דְמִתְּחוֹת יְדוֹהִי מְמַנָן נָטְרֵי מַטְרַת קוּדְשָׁא:
@121 לִמְרָרִי זַרְעִית מַחְלִי וְזַרְעִית מוּשִׁי אִלֵין אִנוּן זַרְעֲיַת מְרָרִי:
@122 וּמִנְיָנֵיהוֹן בְּמִנְיַן כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵלָא שִׁתָּא אַלְפִין וּמָאתָן:
@123 וְרַב בֵּית אַבָּא לְזַרְעֲיַת מְרָרִי צוּרִיאֵל בַּר אֲבִיחָיִל עַל צִדָא דְמַשְׁכְּנָא יִשְׁרוּן צִפּוּנָא:
@124 וְדִי מְסִיר לְמַטְרַת בְּנֵי מְרָרִי דַפֵּי מַשְׁכְּנָא וְעַבְרוֹהִי וְעַמוּדוֹהִי וְסַמְכוֹהִי וְכָל מָנוֹהִי וְכֹל פּוּלְחָנֵהּ:
@125 וְעַמוּדֵי דְדַרְתָּא סְחוֹר סְחוֹר וְסַמְכֵיהוֹן וְסִכֵּיהוֹן וְאַטוּנֵיהוֹן:
@126 וְדִי שְׁרַן קֳדָם מַשְׁכְּנָא קִדוּמָא קֳדָם מַשְׁכַּן זִמְנָא מַדִינְחָא משֶׁה וְאַהֲרֹן וּבְנוֹהִי נָטְרִין מַטְרַת מַקְדְשָׁא לְמַטְרַת בְּנֵי יִשְׂרָאֵל וְחִילוֹנַי דְיִקְרַב יִתְקְטֵל:
@127 כָּל מִנְיָנֵי לֵוָאֵי דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ לְזַרְעֲיַתְהוֹן כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵלָא עַשְׂרִין וּתְרֵין אַלְפִין:
@128 וַאֲמַר יְיָ לְמשֶׁה מְנֵי כָּל בּוּכְרַיָא דִכְרַיָא לִבְנֵי יִשְׂרָאֵל מִבַּר יַרְחָא וּלְעֵלָא וְקַבֵּל יָת מִנְיַן שְׁמָהַתְהוֹן:
@129 וּתְקָרֵב יָת לֵוָאֵי קֳדָמַי אֲנָא יְיָ חֲלַף כָּל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל וְיָת בְּעִירָא דְלֵוָאֵי חֲלַף כָּל בּוּכְרָא בִּבְעִירָא דִבְנֵי יִשְׂרָאֵל:
@130 וּמְנָא משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵהּ יָת כָּל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל:
@131 וַהֲווֹ כָל בּוּכְרַיָא דִכְרַיָא בְּמִנְיַן שְׁמָהָן מִבַּר יַרְחָא וּלְעֵלָא לְמִנְיָנֵיהוֹן עַשְׂרִין וּתְרֵין אַלְפִין מָאתָן וְשַׁבְעִין וּתְלָתָא:
@132 וּמַלִיל יְיָ עִם משֶׁה לְּמֵימָר:
@133 קָרֵב יָת לֵוָאֵי חֲלַף כָּל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל וְיָת בְּעִירָא דְלֵוָאֵי חֲלַף בְּעִירְהוֹן וִיהוֹן מְשַּׁמְשִׁין קֳדָמַי לֵוָאֵי אֲנָא יְיָ:
@134 וְיָת פּוּרְקַן מָאתָן וְשַׁבְעִין וּתְלָתָא דְיַתִּירִין עַל לֵוָאֵי מִבּוּכְרַיָא דִבְנֵי יִשְׂרָאֵל:
@135 וְתִסַב חָמֵשׁ חָמֵשׁ סִלְעִין לְגֻלְגַלְתָּא בְּסִלְעֵי קוּדְשָׁא תִּסַב עַשְׂרִין מָעִין סִלְעָא:
@136 וְתִתֵּן כַּסְפָּא לְאַהֲרֹן וְלִבְנוֹהִי פֻּרְקַן דְיַתִּירִין בְּהוֹן:
@137 וּנְסֵיב משֶׁה יָת כְּסַף פּוּרְקָנָא מִן דְיַתִּירִין עַל פְּרִיקֵי לֵוָאֵי:
@138 מִן בּוּכְרַיָא דִבְנֵי יִשְׂרָאֵל נְסִיב יָת כַּסְפָּא אֲלַף וּתְלַת מְאָה וְשִׁתִּין וְחָמֵשׁ סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@139 וִיהַב משֶׁה יָת כְּסַף פְּרִיקַיָא לְאַהֲרֹן וְלִבְנוֹהִי עַל מֵימְרָא דַיְיָ כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@140 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@141 קַבִּילוּ יָת חֻשְׁבַּן בְּנֵי קְהָת מִגוֹ בְּנֵי לֵוִי לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן:
@142 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְמֶעְבַּד עִבִדְתָּא בְּמַשְׁכַּן זִ מְ נָא:
@143 דֵין פּוּלְחַן בְּנֵי קְהָת בְּמַשְׁכַּן זִמְנָא קוֹדֶשׁ קוּדְשַׁיָא:
@144 וְיֵיעוֹל אַהֲרֹן וּבְנוֹהִי בְּמֵטַל מַשְׁרִיתָא וִיפָרְקוּן יָת פָּרֻכְתָּא דִפְרָסָא וִיכַסוּן בַּהּ יָת אֲרוֹנָא דְסַהֲדוּתָא:
@145 וְיִתְּנוּן עֲלוֹהִי חוֹפָאָה דִמְשַׁךְ סַסְגוֹנָא וְיִפְרְסוּן לְבוּשׁ גְמִיר תִּכְלָא מִלְעֵלָא וִישַׁוּוּן אֲרִיחוֹהִי:
@146 וְעַל פָּתוֹרָא דִלְחֵם אַפַּיָא יִפְרְסוּן לְבוּשׁ תִּכְלָא וְיִתְּנוּן עֲלוֹהִי יָת מָגִּיסַיָא וְיָת בָּזִיכַיָא וְיָת מְכִילָתָא וְיָת קַסְווֹת נִסוּכָא וְלַחְמָא תְּדִירָא עֲלוֹהִי יְהֵי:
@147 וְיִפְרְסוּן עֲלֵיהוֹן לְבוּשׁ צְבַע זְהוֹרִי וִיכַסוּן יָתֵהּ בְּחוֹפָאָה דִמְשַׁךְ סַסְגוֹנָא וִישַׁוּוּן יָת אֲרִיחוֹהִי:
@148 וְיִסְבוּן לְבוּשׁ תִּכְלָא וִיכַסוּן יָת מְנַרְתָּא דְאַנְהוֹרֵי וְיָת בּוֹצִינָהָא וְיָת צִבְתָהָא וְיָת מַחְתְּיָתָהָא וְיָת כָּל מָנֵי מִשְׁחָא דִי יְשַׁמְשׁוּן לָהּ בְּהוֹן:
@149 וְיִתְּנוּן יָתָהּ וְיָת כָּל מָנָהָא לְחוֹפָאָה דִמְשַׁךְ סַסְגוֹנָא וְיִתְּנוּן עַל אֲרִיחָא:
@150 וְעַל מַדְבְּחָא דְדַהֲבָא יִפְרְסוּן לְבוּשׁ תִּכְלָא וִיכַסוּן יָתֵהּ בְּחוֹפָאָה דִמְשַׁךְ סַסְגוֹנָא וִישַׁוּוּן יָת אֲרִיחוֹהִי:
@151 וְיִסְבוּן יָת כָּל מָנֵי שִׁמוּשָׁא דִי יְשַׁמְשׁוּן בְּהוֹן בְּקוּדְשָׁא וְיִתְּנוּן לִלְבוּשׁ תִּכְלָא וִיכַסוּן יָתְהוֹן בְּחוֹפָאָה דִמְשַׁךְ סַסְגוֹנָא וְיִתְּנוּן עַל אֲרִיחָא:
@152 וְיִסְפוּן יָת קִטְמָא דְמַדְבְּחָא וְיִפְרְסוּן עֲלוֹהִי לְבוּשׁ אַרְגְוָן:
@153 וְיִתְּנוּן עֲלוֹהִי יָת כָּל מָנוֹהִי דִי יְשַׁמְשׁוּן עֲלוֹהִי בְהוֹן יָת מַחְתְּיָתָא וְיָת צִנוֹרְיָתָא וְיָת מַגְרוֹפְיָתָא וְיָת מִזְרְקַיָא כֹּל מָנֵי מַדְבְּחָא וְיִפְרְסוּן עֲלוֹהִי חוֹפָאָה דִמְשַׁךְ סַסְגוֹנָא וִישַׁווּן אֲרִיחוֹהִי:
@154 וִישֵׁיצֵי אַהֲרֹן וּבְנוֹהִי לְכַסָאָה יָת קוּדְשָׁא וְיָת כָּל מָנֵי קוּדְשָׁא בְּמֵטַל מַשְׁרִיתָא וּבָתַר כֵּן יַעֲלוּן בְּנֵי קְהָת לְמִטַּל וְלָא יִקְרְבוּן לְקוּדְשָׁא וְלָא יְמוּתוּן אִלֵין מַטוּל בְּנֵי קְהָת בְּמַשְׁכַּן זִמְנָא:
@155 וְדִי מְסִיר לְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא מִשְׁחָא דְאַנְהָרוּתָא וּקְטוֹרֶת בּוּסְמַיָא וּמִנְחָתָּא תְדִירָא וּמִשְׁחָא דִרְבוּתָא מַטְרַת כָּל מַשְׁכְּנָא וְכָל דִי בֵהּ בְּקוּדְשָׁא וּבְמָנוֹהִי:
@156 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@157 לָא תְשֵׁיצוּן יָת שִׁבְטָא זַרְעֲיַת קְהָת מִגוֹ לֵוָאֵי:
@158 וְדָא עִבִידוּ לְהוֹן וְיֵחוּן וְלָא יְמוּתוּן בְּמִקְרַבְהוֹן לְקֹדֶשׁ קוּדְשַּׁיָא אַהֲרֹן וּבְנוֹהִי יַעֲלוּן וִימַנוּן יָתְהוֹן גְבַר גְבַר עַל פֻּלְחָנֵהּ וּלְמַטוּלֵהּ:
@159 וְלָא יֵעֲלוּן לְמֶחֱזֵי כַּד מְכַסָן יָת מָנֵי קוּדְשָׁא וְלָא יְמוּתוּן: פפפ:
@160 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@161 קַבֵּל יָת חֻשְׁבַּן בְּנֵי גֵרְשׁוֹן אַף אִנוּן לְבֵית אֲבָהַתְהוֹן לְזַרְעֲיַתְהוֹן:
@162 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא עַד בַּר חַמְשִׁין שְׁנִין תִּמְנֵי יַתְהוֹן כָּל דְאָתֵי לְחַיָלָא חֵילָא לְמִפְלַח פּוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@163 דֵין פּוּלְחַן זַרְעֲיַת גֵרְשׁוֹן לְמִפְלַח וּלְמַטוּל:
@164 וְיִטְלוּן יָת יְרִיעַת מַשְׁכְּנָא וְיָת מַשְׁכַּן זִמְנָא חוֹפָאֵהּ וְחוֹפָאָה דְסַסְגוֹנָא דִי עֲלוֹהִי מִלְעֵלָא וְיָת פְּרָסָא דִתְרַע מַשְׁכַּן זִמְנָא:
@165 וְיָת סְרָדֵי דְדַרְתָּא וְיָת פְּרָסָא דְמַעֲלָנָא דִתְרַע דַרְתָּא דִי עַל מַשְׁכְּנָא וְעַל מַדְבְּחָא סְחוֹר סְחוֹר וְיָת אַטוּנֵיהוֹן וְיָת כָּל מָנֵי פּוּלְּחַנְהוֹן וְיַת כָּל דִי יִתְמְסַר לְהוֹן וְיִפְלְחוּן:
@166 עַל מֵימַר אַהֲרֹן וּבְנוֹהִי יְהֵי כָּל פּוּלְחַן בְּנֵי גֵרְשׁוֹן לְכָל מַטוּלְהוֹן וּלְכֹל פּוּלְחַנְהוֹן וּתְמַנוּן עֲלֵיהוֹן בְּמַטָרָא יָת כָּל מַטוּלְהוֹן:
@167 דֵין פּוּלְחַן זַרְעֲיַת בְּנֵי גֵרְשּׁוֹן בְּמַשְׁכַּן זִמְנָא וּמַטַרְתְּהוֹן בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@168 בְּנֵי מְרָרִי לְזַרְעֲיַתְהוֹן לְבֵית אֲבָּהַתְהוֹן תִּמְנֵי יַתְהוֹן:
@169 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין תִּמְנִנוּן כָּל דְאָתֵי לְחֵילָא לְמִפְלָח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@170 וְדָא מַטְרַת מַטוּלְהוֹן לְכָל פּוּלְחַנְהוֹן בְּמַשְׁכַּן זִמְנָא דַפֵּי מַשְׁכְּנָא וְעַבְרוֹהִי וְעַמוּדוֹהִי וְסַמְכוֹהִי:
@171 וְעֲמוּדֵי דְדַרְתָּא סְחוֹר סְחוֹר וְסַמְכֵיהוֹן וְסִכֵּיהוֹן וְאַטוּנֵיהוֹן לְכָל מָנֵיהוֹן וּלְכֹל פּוּלְחַנְהוֹן וּבִשְׁמָהָן תְּמַנוּן יָת מָנֵי מַטְרַת מַטוּלְהוֹן:
@172 דֵין פּוּלְחַן זַרְעֲיַת בְּנֵי מְרָרִי לְכָל פּוּלְחַנְהוֹן בְּמַשְׁכַּן זִמְנָא בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@173 וּמְנָא משֶׁה וְאַהֲרֹן וְרַבְרְבֵי כְנִשְׁתָּא יָת בְּנֵי קְהָת לְזַרְעֲיַתְהוֹן וּלְבֵית אֲבָהַתְהוֹן:
@174 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְפוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@175 וַהֲווֹ מִנְיָנֵיהוֹן לְזַרְעֲיַתְהוֹן תְּרֵין אַלְפִין שְׁבַע מְאָה וְחַמְשִׁין:
@176 אִלֵין מִנְיָנֵי זַרְעֲיַת קְהָת כָּל דְפָלַח בְּמַשְׁכַּן זִמְנָּא דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@177 וּמִנְיָנֵי בְּנֵי גֵרְשׁוֹן לְזַרְעֲיַתְהוֹן וּלְבֵית אֲבָהַתְהוֹן:
@178 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְפוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@179 וַהֲווֹ מִנְיָנֵהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן תְּרֵין אַלְפִין וְשִׁית מְאָה וּתְלָתִין:
@180 אִלֵין מִנְיָנֵי זַרְעֲיַת בְּנֵי גֵרְשׁוֹן כָּל דְפָלַח בְּמַשְׁכַּן זִמְנָא דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ:
@181 וּמִנְיָנֵי זַרְעֲיַת בְּנֵי מְרָרִי לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן:
@182 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְפוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@183 וַהֲווֹ מִנְיָנֵיהוֹן לְזַרְעֲיַתְהוֹן תְּלָתָא אַלְפִין וּמָאתָן:
@184 אִלֵין מִנְיָנֵי זַרְעֲיַת בְּנֵי מְרָרִי דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@185 כָּל מִנְיָנַיָא דִי מְנָא משֶׁה וְאַהֲרֹן וְרַבְרְבֵי יִשְׂרָאֵל יָת לֵוָאֵי לְזַרְעֲיַתְהוֹן וּלְבֵית אֲבָהַתְהוֹן:
@186 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְמִפְלַח פּוּלְחַן פּוּלְחָנָא וּפוּלְחַן מַטוּל בְּמַשְׁכַּן זִמְנָא:
@187 וַהֲווֹ מִנְיָנֵיהוֹן תְּמַנְיָא אַלְפִין וַחֲמֵשׁ מְאָה וְתַמְנָן:
@188 עַל מֵימְרָא דַיְיָ מְנָא יָתְהוֹן בִּידָא דְמשֶׁה גְבַר גְבַר עַל פּוּלְחָנֵהּ וְעַל מַטוּלֵהּ וּמִנְיָנוֹהִי דִי פַקִיד יְיָ יָת משֶׁה:
@189 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@190 פַּקֵיד יָת בְּנֵי יִשְׂרָאֵל וִישַׁלְחוּן מִן מַשְׁרִיתָא כָּל דִסְגִיר וְכָל דְדָאֵב וְכֹל דִמְסָאָב לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא:
@191 מִדְכַר עַד נוּקְבָא תְּשַׁלְחוּן לְמִבָּרָא לְמַשְׁרִיתָא תְּשַׁלְחֻנוּן וְלָא יְסַאֲבוּן יָת מַשְׁרִיתְהוֹן דִי שְׁכִינְתִּי שַׁרְיָא בֵינֵיהוֹן:
@192 וַעֲבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וְשַׁלְחוּ יָתְהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִיל יְיָ עִם משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל:
@193 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@194 מַלֵל עִם בְּנֵי יִשְׂרָאֵל גְבַר אוֹ אִתְּתָא אֲרֵי יַעְבְּדוּן מִכָּל חוֹבֵי אֱנָשָׁא לְשַׁקָרָא שְׁקָר קֳדָם יְיָ וְיֵחוֹב אֱנָשָׁא הַהוּא:
@195 וִיוַדוּן יָת חוֹבֵיהוֹן דִי עֲבָדוּ וְיָתֵב יָת חוֹבְתֵהּ בְּרֵישֵׁהּ וְחֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי וְיִתֵּן לִדְחָב לֵהּ:
@196 וְאִם לֵית לִגְבַר פָּרִיק לַאֲתָבָא חוֹבְתָא לֵהּ חוֹבְתָא דִמְתֵב קֳדָם יְיָ לְכַהֲנָא בַּר מִדְכַר כִּפּוּרַיָא דִי יְכַפֵּר בֵּהּ עֲלוֹהִי:
@197 וְכָל אַפְרָשׁוּתָא לְכָל קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל דִי יְקָרְבוּן לְכַהֲנָא דִלֵהּ יְהֵא:
@198 וּגְבַר יָת מַעֲשַׂר קוּדְשֵׁהּ דִלֵהּ יְהוֹן גְבַר דְיִתֵּן לְכַהֲנָא דִלֵהּ יְהֵא:
@199 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@200 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר גְבַר אֲרֵי תִסְטֵי אִתְּתֵהּ וּתְשַׁקֵר בֵּהּ שְׁקָר:
@201 וְיִשְׁכֻּב גְבַר יָתַהּ שָׁכְבַת זַרְעָא וִיהֵי מְכַסָא מֵעֵינֵי בַעְלַהּ וּמִטַמְרָא וְהִיא מְסָאֲבָא וְסָהִיד לֵית בַּהּ וְהִיא לָא אִתַּחָדַת:
@202 וְיֶעְבַּר עֲלוֹהִי רוּחַ קִנְאָה וִיקַנֵי יָת אִתְּתֵהּ וְהִיא מְסָאֲבָא אוֹ עֲבַר עֲלוֹהִי רוּחַ קִנְאָה וִיקַנֵי יָת אִתְּתֵהּ וְהִיא לָא מְסָאֲבָא:
@203 וְיַיְתֵי גַבְרָא יָת אִתְּתֵהּ לְוַת כַּהֲנָא וְיַיְתֵי יָת קֻרְבָּנַהּ עֲלַהּ חַד מִן עַסְרָא בִּתְלַת סְאִין קִמְחָא שְׂעָרִין לָא יְרִיק עֲלוֹהִי מִשְׁחָא וְלָא יִתֵּן עֲלוֹהִי לְבֻנְתָּא אֲרֵי מִנְחַת קִנְאָתָא הוּא מִנְחַת דוּכְרָנָא מַדְכָּרַת חוֹבָא:
@204 וִיקָרֵב יָתַהּ כַּהֲנָא וִיקִימִנַהּ קֳדָם יְיָ:
@205 וְיִסַב כַּהֲנָא מֵי כִיוֹר בְּמַן דַחֲסָף וּמִן עַפְרָא דִי יְהֵי בִּיסוֹדֵי מַשְׁכְּנָא יִסַב כַּהֲנָא וְיִתֵּן לְמַיָא:
@206 וִיקֵים כַּהֲנָא יָת אִתְּתָא קֳדָם יְיָ וְיִפְרַע יָת רֵישָׁא דְאִתְּתָא וְיתֵּן עַל יְדָהָא יָת מִנְחַת דוּכְרָנָא מִנְחַת קִנְאָתָא הִיא וּבִידָא דְכַהֲנָא יְהוֹן מַיָא מְרִירַיָא מְלַטְטַיָא:
@207 וְיוֹמֵי יָתַהּ כַּהֲנָא וְיֵימַר לְאִתְּתָא אִם לָא שְׁכִיב גְבַר יָתִיךְ וְאִם לָא סְטִּית לְאִסְתְּאָבָא בַּר מִבַּעֲלִיךְ הֱוֵי זַכָּאָה מִמַיָא מְרִירַיָא מְלַטְטַיָא הָאִלֵין:
@208 וְאַתְּ אֲרֵי סְטִית בַּר מִבַּעֲלִיךְ וַאֲרֵי אִסְתָּאָבְתְּ וִיהַב גְבַר בִּיךְ יָת שְׁכֻבְתֵּהּ בַּר מִבַּעֲלִיךְ:
@209 וְיוֹמֵי כַהֲנָא יָת אִתְּתָא בְּמוֹמָתָא דִלְוָטָּא וְיֵימַר כַּהֲנָא לְאִתְּתָא יִתֵּן יְיָ יָתִיךְ לִלְוַטּ וּלְמוֹמֵי בְּגוֹ עַמִיךְ בִּדְיִתֵּן יְיָ יָת יַרְכִּיךְ מַסְיָא וְיָת מְעַיְכִי נְפִיחִין:
@210 וְיֵעֲלוּן מַיָא מְלַטְטַיָא הָאִלֵין בִּמְעַיְכִי לַאֲפָחָא מְעִין וּלְאַמְסָאָה יַרְכָּא וְתֵימַר אִתְּתָא אָמֵן אָמֵן:
@211 וְיִכְתּוֹב יָת לְוָטַיָא הָאִלֵין כַּהֲנָא בְּסִפְרָא וְיִמְחוֹק לְמַיָא מְרִירַיָא:
@212 וְיַשְׁקֵי יָת אִתְּתָא יָת מַיָא מְרִירַיָא מְלַטְטַיָא וְיֵעֲלוּן בַּהּ מַיָא מְלַטְטַיָא לִמְרִירוּ:
@213 וְיִסַב כַּהֲנָא מִידָא דְאִתְּתָא יָת מִנְחַת קִנְאָתָא וִירֵים יָת מִנְחָתָא קָדָם יְיָ וִיקָרֵב יָתַהּ לְמַדְבְּחָא:
@214 וְיִקְמוֹץ כַּהֲנָא מִן מִנְחָתָא יָת אַדְכַּרְתָּהּ וְיַסֵק לְמַדְבְּחָא וּבָתַר כֵּן יַשְׁקֵי יָת אִתְּתָא יָת מַיָא:
@215 וְיַשְׁקִנָהּ יָת מַיָא וּתְהֵי אִם אִסְתָּאָבַת וְשַׁקָרַת שְׁקָר בְּבַעֲלַהּ וְיֵעֲלוּן בַּה מַיָא מְלַטְטַיָא לִמְרִירוּ וְיִפְּחוּן מְעָהָא וְתִתְמְסֵי יַרְכַהּ וּתְהֵי אִתְּתָא לִלְוַט בְּגוֹ עַמָהּ:
@216 וְאִם לָא אִסתָּאָבַת:אִתְּתָא וְדַכְוָאָה הִיא וְתִפּוֹק זַכָּאָה וְתַעְדִי עִדוּי:
@217 דָא אוֹרַיְתָא דְקִנְאָתָא דִי תִסְטֵי אִתְּתָא בַּר מִבַּעֲלַהּ וְתִסְתָּאָב:
@218 אוֹ גְבַר דִי תֶעְבַּר עֲלוֹהִי רוּחַ קִנְאָה וִיקַנֵי יָת אִתְּתֵהּ וִיקֵם יָת אִתְּתָא קֳדָם יְיָ וְיַעֲבֵד לַהּ כַּהֲנָא יָת כָּל אוֹרַיְתָא הָדָא:
@219 וִיהֵי זַכָּאָה גַבְרָא מֵחוֹבָא וְאִתְּתָא הַהִיא תְּקַבֵּל יָת חוֹבָהּ:
@220 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@221 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר אוֹ אִתְּתָא אֲרֵי יְפָרֵשׁ לְמִדַר נְדַר נְזִירוּ לְמֵיזַר קֳדָם יְיָ:
@222 מֵחֲמַר חֲדַת וְעַתִּיק יַנְזִיר חַל דַחֲמַר חֲדַת וְחַל דַחֲמַר עַתִּיק לָא יִשְׁתֵּי וְכָל מַתְרוּת עִנְבִין לָא יִשְׁתֵּי וְעִנְבִין רַטִיבִין וִיבֵשִׁין לָא יֵיכוּל:
@223 כֹּל יוֹמֵי נִזְרֵהּ מִכֹּל דְיִתְעֲבֵד מִגֻפְנָא דְחַמְרָא מִפּוּרְצְנִין וְעַד עִצוּרִין לָא יֵיכוּל:
@224 כָּל יוֹמֵי נְדַר נִזְרֵהּ מַסְפַּר לָא יֶעְבַּר עַל רֵישֵׁהּ עַד מִשְׁלַם יוֹמַיָא דְיַנְזֵר קֳדָם יְיָ קַדִישׁ יְהֵי מַרְבֵּי פֵרוּעַ שְׂעַר רֵישֵׁהּ:
@225 כָּל יוֹמִין דְיַנְזֵר קֳדָם יְיָ עַל נַפְשָׁא דְמֵתָא לָא יֵיעוּלּ:
@226 לְאָבוּהִי וּלְאִמֵהּ לְאַחוֹהִי וּלְאַחָתֵהּ לָא יִסְתָּאַב לְהוֹן בְּמוֹתְהּוֹן אֲרֵי כְּלִילָא דֶאֱלָהֵהּ עַל רֵישֵׁהּ:
@227 כֹּל יוֹמֵי נִזְרֵהּ קַדִישׁ הוּא קֳדָם יְיָ:
@228 וַאֲרֵי יְמוּת מֵתָא עֲלוֹהִי בִּתְכֵּף שָׁלוּ וִיסָאֵב רֵישׁ נִזְרֵהּ וִיגַלַח רֵישֵׁהּ בְּיוֹמָא דִדְכוּתֵהּ בְּיוֹמָא שְׁבִיעָאָה יְגַלְחִנֵהּ:
@229 וּבְיוֹמָא תְמִינָאָה יַיְתֵי תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא:
@230 וְיַעְבֵּד כַּהֲנָא חַד לְחַטָאתָא וְחַד לַעֲלָתָא וִיכַפֵּר עֲלוֹהִי מִדְחָב עַל מִתָא וִיקַדַשׁ יָת רֵישֵׁהּ בְּיוֹמָא הַּהוּא:
@231 וְיַזֵר קֳדָם יְיָ יָת יוֹמֵי נִזְרֵהּ וְיַיְתִי אִמַר בַּר שַׁתֵּהּ לַאֲשָׁמָא וְיוֹמַיָא קַדְמָאֵי יִבְטְלוּן אֲרֵי אִסְתָּאַב נִזְרֵהּ:
@232 וְדָא אוֹרַיְתָא דִנְזִירָא בְּיוֹם מִשְׁלַם יוֹמֵי נִזְרֵהּ יַיְתִי יָתֵהּ לִתְרַע מַשְׁכַּן זִמְנָא:
@233 וִיקָרֵב יָת קֻרְבָּנֵהּ קֳדָם יְיָ אִמַר בַּר שַׁתֵּהּ שְׁלִים חַד לַעֲלָתָא וְאִמַרְתָּא חֲדָא בַּת שַׁתָּהּ שְׁלֶמְתָּא לְחַטָאתָא וּדְכַר חַד שְׁלִים לְנִכְסַת קוּדְשַׁיָא:
@234 וְסַלָא דְפַּטִרִיָא סֻלְּתָּא גְרִיצַן דְפִילָן בִּמְשַׁח וְאִסְפּוֹגִין פַּטִירִין דִמְשִׁיחִין בִּמְשָׁח וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן:
@235 וִיקָרֵב כַּהֲנָא קֳדָם יְיָ וְיַעְבֵּד יָת חַטָאתֵהּ וְיָת עֲלָתֵהּ:
@236 וְיָת דִכְרָא יַעְבֵּד נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ עַל סַלָא דְפַטִּירַיָא וְיַעְבֵּד כַּהֲנָא יָת מִנְחָתֵהּ וְיָת נִסְכֵּהּ:
@237 וִיגַלַח נְזִירָא בִּתְרַע מַשְׁכַּן זִמְנָא יָת רֵישׁ נִזְרֵהּ וְיִסַב יָת שְׂעַר רֵישׁ נִזְרֵהּ וְיִתֵּן עַל אֶשָׁתָא דִי תְחוֹת דוּדָא דְנִכְסַת קוּדְשַׁיָא:
@238 וְיִסַב כַּהֲנָא יָת דְרָעָא בְּשֵׁלָא מִן דִכְרָא וּגְרִצְתָּא פַטִּירְתָּא חֲדָא מִן סַלָא וְאִסְפּוֹג פַּטִיר חָד וְיִתֵּן עַל יְדֵי נְזִירָא בָּתַר דְגַלַח יָת נִזְרֵהּ:
@239 וִירִים יָתְהוֹן כַּהֲנָא אֲרָמָא קֳדָם יְיָ קוּדְשָׁא הוּא לְכַהֲנָא עַל חַדְיָא דַאֲרָמוּתָא וְעַל שַׁקָא דְאַפְרָשׁוּתָא וּבָתַר כֵּן יִשְׁתֵּי נְזִירָא חַמְרָא:
@240 דָא אוֹרַיְתָא דִנְזִירָא דִי יִדַר קֻרְבָּנֵהּ קֳדָם יְיָ עַל נִזְרֵהּ בַּר מִדְתַדְבֵּק יְדֵהּ כְּפוּם נִדְרֵהּ דִי יִדַר כֵּן יַעְבֵּד עַל אוֹרַיְתָא דְנִזְרֵהּ:
@241 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@242 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימַר כְּדֵין תְּבָרְכוּן יָת בְּנֵי יִשְׂרָאֵל תֵּימְרוּן לְהוֹן:
@243 יְבָרְכִינָךְ יְיָ וְיִטְרִינָךְ:
@244 יַנְהַר יְיָ שְׁכִנְתֵּהּ לְוָתָךְ וִירַחֵם יָתָךְ:
@245 יִסַב יְיָ אַפֵּהּ לְוָתָךְ וִישַׁוֵי לָךְ שְׁלָם:
@246 וִישַׁווּן יָת בִּרְכַּת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנָא אֲבָרֵכִנוּן:
@247 וַהֲוָה בְּיוֹמָא דְשֵׁיצֵי משֶׁה לַאֲקָמָא יָת מַשְׁכְּנָא וְרַבִּי יָתֵהּ וְקַדִישׁ יָתֵהּ וְיָת כָּל מָנוֹהִי וְיָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְרַבִּנוּן וְקַדֵישׁ יָתְהוֹן:
@248 וּקְרִיבוּ רַבְרְבֵי יִשְׂרָאֵל רֵישֵׁי בֵּית אֲבָהַתְהוֹן אִנוּן רַבְרְבֵי שִׁבְטַיָא אִנוּן דְקַיְמִין עַל מִנְיָנַיָא:
@249 וְאַיְתִיוּ יָת קֻרְבָּנֵיהוֹן קֳדָם יְיָ שִׁית עֶגְלָן כַּד מְחַפְיָן וּתְרֵי עֲשַׂר תּוֹרִין עֶגְלְתָא עַל תְּרֵין רַבְרְבַיָא וְתוֹר לְחַד וְקָרִיבוּ יָתְהוֹן לָקֳדָם מַשְׁכְּנָא:
@250 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@251 קַבֵּל מִנְהוֹן וִיהוֹן לְמִפְלַח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא וְתִתֵּן יָתְהוֹן לְלֵוָאֵי גְבַר כְּמִסַת פּוּלְחָנֵהּ:
@252 וּנְסֵיב משֶׁה יָת עֶגְלָתָא וְיָת תּוֹרִין וִיהַב יָתְהוֹן לְלֵוָאֵי:
@253 יָת תַּרְתֵּין עֶגְלָתָא וְיָת אַרְבַּעַת תוֹרֵי יְהַב לִבְנֵי גֵרְשׁוֹן כְּמִסַת פּוּלְחַנְהוֹן:
@254 וְיָת אַרְבַּע עֶגְלָתָא וְיָת תְּמַנְיָא תוֹרֵי יְהַב לִבְנֵי מְרָרִי כְּמִסַת פּוּלְחַנְהוֹן בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@255 וְלִבְנֵי קְהָת לָא יְהָב אֲרֵי פוּלְחַן קוּדְשָׁא עֲלֵיהוֹן בְּכַתְפָּא נָטְלִין:
@256 וְקָרִיבוּ רַבְרְבַיָא יָת חֲנֻכַּת מַדְבְּחָא בְּיוֹמָא דְרַבִּיוּ יָתֵהּ וְקָרִיבוּ רַבְרְבַיָא יָת קֻרְבַּנְהוֹן לְּקֳדָם מַדְבְּחָא:
@257 וַאֲמַר יְיָ לְמשֶׁה רַבָּא חַד לְיוֹמָא רַבָּא חַד לְיוֹמָא יְקָרְבוּן יָת קֻרְבַּנְהוֹן לַחֲנֻכַּת מַדְבְּחָא:
@258 וַהֲוָה דִמְקָרַב בְּיוֹמָא קַדְמָאָה יָת קֻרְבָּנֵהּ נַחְשׁוֹן בַּר עַמִינָדָב לְשִׁבְטָא דִיהוּדָה:
@259 וְקֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְּפִילָא בִמְשַׁח לְמִנְחָתָא:
@260 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטוֹרֶת בּוּסְמַיָא:
@261 תּוֹר חַד בַּר תּוֹרֵי דְּכַר חַד אִמַּר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@262 צְפִיר בַּר עִזִּין חַד לְחַטָּאתָא:
