@316 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@317 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן אֲחִיעֶזֶר בַּר עַמִישַׁדָי:
@318 בְּיוֹמָא חַד עֲשַׂר יוֹמָא רַבָא לִבְנֵי אָשֵׁר פַּגְעִיאֵל בַּר עָכְרָן:
@319 קֻרְבָּנֵה מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@320 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטֹרֶת בּוּסְמַיָא:
@321 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@322 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@323 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן פַּגְעִיאֵל בַּר עָכְרָן:
@324 בְּיוֹמָא תְּרֵי עֲשַׂר יוֹמָא רַבָּא לִבְנֵי נַפְתָּלִי אֲחִירַע בַּר עֵינָן:
@325 קֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@326 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטֹרֶת בּוּסְמַיָא:
@327 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@328 צְפִיר בַּר עִזִין חַד לְחַטָּאתָא:
@329 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן אֲחִירַע בַּר עֵינָן:
@330 דָא חֲנֻכַּת מַדְבְּחָא בְּיוֹמָא דְרַבִּיוּ יָתֵהּ מִן רַבְרְבֵי יִשְׂרָאֵל מְגִיסֵי כַסְפָּא תַּרְתָּא עַשְׂרֵי מִזְרְקֵי כַסְפָּא תְּרֵין עֲשַׂר בָּזִיכֵי דְדַהֲבָא תַּרְתָּא עַשְׂרֵי:
@331 מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלָא דִמְגִיסְתָּא חֲדָא דְכַסְפָּא וְשַׁבְעִין דְמִזְרְקָא חָד כֹּל כְּסַף מָנַיָא תְּרֵין אַלְפִין וְאַרְבַּע מְאָה בְּסִלְעֵי קוּדְשָׁא:
@332 בָּזִיכֵי דְדַהֲבָא תַּרְתֵּי עַשְׂרֵי מַלְיָן קְטֹרֶת בּוּסְמַיָא מַתְקַל עֲשַׂר סִלְעִין הֲוָה מַתְקְלָא דְבָזִיכָא בְּסִלְעֵי קוּדְשָׁא כָּל דְהַב בָּזִיכַיָא מְאָה וְעַשְׂרִין:
@333 כָּל תּוֹרֵי לַעֲלָתָא תְּרֵי עֲשַׂר תּוֹרִין דִכְרִין תְּרֵי עֲשַׂר אִמְרִין בְּנֵי שַׁתָּא תְּרֵי עֲשַׂר וּמִנְחַתְהוֹן וּצְפִירֵי בַּר עִזִין תְּרֵי עֲשַׂר לְחַטָאתָא:
@334 וְכֹל תּוֹרֵי לְנִכְסַת קוּדְשַׁיָא עַשְׂרִין וְאַרְבְּעָא תּוֹרִין דִכְרִין שִׁתִּין גַדְיַן שִׁתִּין אִמְרִין בְּנֵי שַׁתָּא שִׁתִּין דָא חֲנֻכַּת מַדְבְּחָא בָּתַר דְרַבִּיוּ יָתֵהּ:
@335 וְכַד עָלִיל משֶׁה לְמַשְׁכַּן זִמְנָא לְמַלָלָא עִמֵהּ וּשְׁמַע יָת קָלָא דְמִתְמַלֵל עִמֵהּ מֵעִלָוֵי כַפֻּרְתָּא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא מִבֵּין תְּרֵין כְּרוּבַיָא וּמִתְמַלֵל עִמֵהּ: פפפ:
@336 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@337 מַלֵל עִם אַהֲרֹן וְתֵימַר לֵהּ בְּאַדְלָקוּתָךְ יָת בּוֹצִינַיָא לָקֳבֵל אַפֵּי מְנַרְתָּא יְהוֹן מְנַהֲרִין שִׁבְעָא בוֹצִינַיָא:
@338 וַעֲבַד כֵּן אַהֲרֹן לָקֳבֵל אַפֵּי מְנַרְתָּא אַדְלֵק בּוֹצִינָהָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@339 וְדֵין עוֹבַד מְנַרְתָּא נְגִידָא דְהַב עַד שִׁידַהּ עַד שׁוֹשַׁנַהּ נְגִידָא הִיא כְּחֶזְוָא דִי אַחֲזֵי יְיָ יָת משֶׁה כֵּן עֲבַד יָת מְנַרְתָּא:
@340 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@341 קָרֵב יָת לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל וּתְדַכֵּי יָתְהוֹן:
@342 וּכְדֵין תַּעְבֵּד לְהוֹן לְדַכּוֹאֵיהוֹן אֲדֵי עֲלֵיהוֹן מַיָא דְחַטָאתָא וְיַעְבְּרוּן מַסְפַּר עַל כָּל בִּשְׂרְהוֹן וִיחַוְרוּן לְבוּשֵׁיהוֹן וְיִדְכּוּן:
@343 וְיִסְבוּן תּוֹר בַּר תּוֹרֵי וּמִנְחָתֵהּ סֻלְתָּא דְפִילָא בִמְשָׁח וְתוֹר תִּנְיָן בַּר תּוֹרֵי תִּסַב לְחַטָאתָא:
@344 וּתְקָרֵב יָת לֵוָאֵי לִקְדָם מַשְׁכַּן זִמְנָא וְתִכְנוֹשׁ יָת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@345 וּתְקָרֵב יָת לֵוָאֵי קֳדָם יְיָ וְיִסְמְכוּן בְּנֵי יִשְׂרָאֵל יָת יְדֵיהוֹן עַל לֵוָאֵי:
@346 וִירִים אַהֲרֹן יָת לֵוָאֵי אֲרָמָא קֳדָם יְיָ מִן בְּנֵי יִשְׂרָאֵל וִיהוֹן לְמִפְלַח יָת פֻּלְחָנָא דַיְיָ:
@347 וְלֵוָאֵי יִסְמְכוּן יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרַיָא וַעֲבֵיד יָת חַד חַטָאתָא וְיָת חַד עֲלָתָא קֳדָם יְיָ לְכַפָּרָא עַל לֵוָאֵי:
@348 וּתְקֵם יָת לֵוָאֵי קֳדָם אַהֲרֹן וְקֳדָם בְּנוֹהִי וּתְרֵים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@349 וְתַפְרֵישׁ יָת לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל וִיהוֹן מְשַׁמְשִׁין קֳדָמַי לֵוָאֵי:
@350 וּבָתַר כֵּן יַעֲלוּן לֵוָאֵי לְמִפְלַח יָת מַשְׁכַּן זִמְנָא וּתְדַכֵּי יָתְהוֹן וּתְרֵים יָתְהוֹן אֲרָמָא:
@351 אֲרֵי אַפְרָשָׁא מַפְרְשִׁין אִנוּן לִי מִגוֹ בְּנֵי יִשְׂרָאֵל חֲלַף פְּתַח כָּל וַלְדָא בּוּכְרָא כֹלָא מִבְּנֵי יִשְׂרָאֵל קָרֵבִית יָתְהוֹן קֳדָמָי:
@352 אֲרֵי דִילִי כָל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל בֶּאֱנָשָׁא וּבִבְעִירָא בְּיוֹמָא דִקְטָּלִית כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם אַקְדֵשִׁית יָתְהוֹן קֳדָמַי:
@353 וְקָרֵבִית יָת לֵוָאֵי חֲלַף כָּל בּוּכְרָא בִּבְנֵי יִשְׂרָאֵל:
@354 וִיהָבִית יָת לֵוָאֵי מְסִירִין לְאַהֲרֹן וְלִבְנוֹהִי מִגוֹ בְּנֵי יִשְׂרָאֵל לְמִפְלַח יָת פּוּלְחָן בְּנֵי יִשְׂרָאֵל בְּמַשְׁכַּן זִמְנָא וּלְכַפָרָא עַל בְּנֵי יִשְׂרָאֵל וְלָא יְהֵי בִּבְנֵי יִשְׂרָאֵל מוֹתָא בְּמִקְרַב בְּנֵי יִשְׂרָאֵל לְקוּדְשָׁא:
@355 וַעֲבַד משֶׁה וְאַהֲרֹן וְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְלֵוָאֵי כְּכֹל דִי פַקֵיד יְיָ יָת משֶׁה לְלֵוָאֵי כֵּן עֲבָדוּ לְהוֹן בְּנֵי יִשְׂרָאֵל:
@356 וְאִדַכִּיוּ לֵוָאֵי וְחַוָרוּ לְבוּשֵׁיהוֹן וַאֲרֵם אַהֲרֹן יָתְהוֹן אֲרָמָא קֳדָם יְיָ וְכַפֵּר עֲלֵיהוֹן אַהֲרֹן לְדַכּוֹאֵיהוֹן:
@357 וּבָתַר כֵּן עֲלוּ לֵוָאֵי לְמִפְלַח יָת פּוּלְחַנְהוֹן בְּמַשְׁכַּן זִמְנָא קֳדָם אַהֲרֹן וְקָדָם בְּנוֹהִי כְּמָא דִי פַקִיד יְיָ יָת משֶׁה עַל לֵוָאֵי כֵּן עֲבָדוּ לְהוֹן:
@358 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@359 דָא דִי לְלֵוָאֵי מִבַּר חָמֵשׁ וְעַשְׂרִין שְׁנִין וּלְעֵלָא יֵיתֵי לְחֲיָלָא חֵילָא בְּפוּלְחַן מַשְׁכַּן זִמְנָא:
@360 וּמִבַּר חַמְשִׁין שְׁנִין יְתוּב מֵחֵיל פּוּלְחָנָא וְלָא יִפְלַח עוֹד:
@361 וִישַׁמֵשׁ עִם אֲחוֹהִי בְּמַשְׁכַּן זִמְנָא לְמִטַּר מַטָרָא וּפוּלְחָנָא לָא יִפְלָח כְּדֵין תַּעֲבֵיד לְלֵוָאֵי בְּמַטְרַתְהוֹן:
@362 וּמַלִיל יְיָ עִם משֶׁה בְּמַדְבְּרָא דְסִינַי בְּשַׁתָּא תִנְיֵתָא לְמִפַּקְהוֹן מֵאַרְעָא דְמִצְרַיִם בְּיַרְחָא קַדְמָאָה לְמֵימָר:
@363 וְיַעְבְּדוּן בְּנֵי יִשְׂרָאֵל יָת פִּסְחָא בְּזִמְנֵיהּ:
@364 בְּאַרְבַּעַת עַשְׂרָא יוֹמָא בְּיַרְחָא הָדֵין בֵּין שִׁמְשַׁיָא תַּעְבְּדוּן יָתֵהּ בְּזִמְנֵהּ כְּכָל גְזֵרָתֵהּ וּכְכָל דְחָזֵי לֵהּ תַּעְבְּדוּן יָתֵהּ:
@365 וּמַלִיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל לְמֶעְבַּד פִּסְחָא:
@366 וַעֲבָדוּ יָת פִּסְחָא בְּנִיסָן בְּאַרְבַּעַת עַשְׂרָא יוֹמָא לְיַרְחָא בֵּין שִׁמְשַׁיָא בְּמַדְבְּרָא דְסִינָי כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל:
@367 וַהֲווֹ גֻבְרַיָא דִי הֲווֹ מְסָאֲבִין לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא וְלָא יְכִילוּ לְמֶעְבַּד פִּסְחָא בְּיוֹמָא הַהוּא וּקְרִיבוּ קֳדָם משֶׁה וְקָדָם אַהֲרֹן בְּיוֹמָא הַהוּא:
@368 וַאֲמָרוּ גֻבְרַיָא הָאִנוּן לֵהּ אֲנַחְנָא מְסָאֲבִין לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא לְמָא נִתְמְנַע בְּדִיל דְלָא לְקָרָבָא יָת קֻרְבָּנָא דַיְיָ בִּזִמְנֵיה בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@369 וַאֲמַר לְהוֹן משֶׁה אוֹרִיכוּ עַד דְאֶשְׁמָע מָה דְיִתְפַּקֵד מִן קֳדָם יְיָ עַל דִילְכוֹן:
@370 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@371 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר גְבַר גְבַר אֲרֵי יְהֵי מְסָאָב לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא אוֹ בְאָרְחָא רְחִיקָא לְכוֹן אוֹ לְדָרֵיכוֹן וְיַעְבֵּד פִּסְחָא קֳדָם יְיָ:
@372 בְּיַרְחָא תִנְיָנָא בְּאַרְבְּעַת עַשְׂרָא יוֹמָא בֵּין שִׁמְשַׁיָא יַעְבְּדוּן יָתֵהּ עַל פַּטִּיר וּמְרָרִין יֵיכְלִנֵהּ:
@373 לָא יַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא וְגַרְמָא לָא יִתְבְּרוּן בֵּהּ כְּכָל גְזֵרַת פִּסְחָא יַעְבְּדוּן יָתֵהּ:
@374 וְגַבְרָא דְהוּא דְכֵי וּבְאֹרַח לָא הֲוָה וְיִתְמְנַע לְמֶעְבַּד פִּסְחָא וְיִשְׁתֵּצֵי אֲנָשָׁא הַהִיא מֵעַמֵהּ אֲרֵי קֻרְבָּנָא דַיְיָ לָא קָרִיב בְּזִמְנֵהּ חוֹבֵהּ יְקַבֵּל גַבְרָא הַהוּא:
@375 וַאֲרֵי יִתְגַיַר עִמְכוֹן גִיוֹרָא וְיַעְבֵּד פִּסְחָא קֳדָם יְיָ כִּגְזֵרַת פִּסְחָא וְכִדְחָזֵי לֵהּ כֵּן יַעְבֵּד קְיָמָא חַד יְהֵי לְכוֹן וּלְגִיוֹרָא וּלְיַצִיבָא דְאַרְעָא:
@376 וּבְיוֹמָא דְאִתָּקַם יָת מַשְׁכְּנָא חֲפָא עֲנָנָא יָת מַשְׁכְּנָא לְמַשְׁכְּנָא דְסַהֲדוּתָא וּבְרַמְשָׁא הֲוָה עַל מַשְׁכְּנָא כְּחֵזוּ אֶשָׁתָא עַד צַפְרָא:
@377 כֵּן הֲוָה תְדִירָא עֲנָנָא חָפֵי לֵּהּ וְחֵיזוּ אֵשָׁתָא בְּלֵילְיָא:
@378 וּלְפוּם אִסְתַּלָקוּת עֲנָנָא מֵעִלָוֵי מַשְׁכְּנָא וּבָתַר כֵּן נָטְלִין בְּנֵי יִשְׂרָאֵל וּבְאַתְרָא דְשָׁרֵי תַמָן עֲנָנָא תַּמָן שָׁרָן בְּנֵי יִשְׂרָאֵל:
@379 עַל מֵימְרָא דַיְיָ נָטְלִין בְּנֵי יִשְׂרָאֵל וְעַל מֵימְרָא דַיְיָ שָׁרָן כָּל יוֹמִין דִי שָׁרֵי עֲנָנָא עַל מַשְׁכְּנָא שָׁרָן:
@380 וּבְאוֹרָכוּת עֲנָנָא עַל מַשְׁכְּנָא יוֹמִין סַגִיאִין וְיִטְרוּן בְּנֵי יִשְׂרָאֵל יָת מַטְרַת מֵימְרָא דַיְיָ וְלָא נָטְלִין:
@381 וְאִית דִי הֲוָה עֲנָנָא יוֹמֵי דְמִנְיָן עַל מַשְׁכְּנָא עַל מֵימְרָא דַיְיָ שָׁרָן וְעַל מֵימְרָא דַיְיָ נָטְלִין:
@382 וְאִית דִי הֲוָה עֲנָנָא מֵרַמְשָׁא וְעַד צַפְרָא וּמִסְתַּלֵק עֲנָנָא בְּצַפְרָא וְנָטְלִין אוֹ יֵמָם וְלֵילֵי וּמִסְתַּלֵק עֲנָנָא וְנָטְלִין:
@383 אוֹ תְרֵין יוֹמִין אוֹ יַרְחָא אוֹ עִדָן בְּעִדָן בְּאוֹרָכוּת עֲנָנָא עַל מַשְׁכְּנָא לְמִשְׁרֵי עֲלוֹהִי שָׁרָן בְּנֵי יִשְׂרָאֵל וְלָא נָטְלִין וּבְאִסְתַּלָקוּתֵהּ נָטְלִין:
@384 עַל מֵימְרָא דַיְיָ שָׁרָן:ועַל מֵימְרָא דַיְיָ נָטְלִין יָת מַטְרַת מֵימְרָא דַיְיָ נָטְרִין עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@385 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@386 עֲבֵיד לָךְ תַּרְתֵּין חֲצוֹצְרָן דִכְסַף נְגִיד תַּעְבֵּד יַתְהוֹן וִיהֶוְיָן לָךְ לְעַרְעָא כְנִשְׁתָּא וּלְאַטָלָא יָת מַשִׁרְיָתָא:
@387 וְיִתְקְעוּן בְּהוֹן וְיִזְדַמְנוּן לְוָתָךְ כָּל כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@388 וְאִם בַּחֲדָא יִתְקְעוּן וְיִזְדַמְנוּן לְוָתָךְ רַבְרְבַיָא רֵישֵׁי אַלְפַיָא דְיִשְׂרָאֵל:
@389 וְתִתְקְעוּן יַבֶּבְתָּא וְיִטְלוּן מַשִׁרְיָתָא דְשָׁרָן קִדוּמָא:
@390 וְתִתְקְעוּן יַבֶּבְתָּא תִּנְיָנוּת וְיִטְלוּן מַשִׁרְיָתָא דְשָׁרָן דָרוֹמָא יַבָּבָא יִתְקְעוּן לְמַטְלָנֵיהוֹן:
@391 וּבְמִכְנַשׁ יָת קְהָלָא תִּתְקְעוּן וְלָא תְיַבְּבוּן:
@392 וּבְנֵי אַהֲרֹן כַּהֲנַיָא יִתְקְעוּן בַּחֲצוֹצְרָתָא וִיהֶוְיָן לְכוֹן לִקְיַם עֲלָם לְדָרֵיכוֹן:
@393 וַאֲרֵי תֵעֲלוּן לְאַגָחָא קְרָבָא בְּאַרְעַכוֹן עַל מְעִיקֵי דִמְעִיקִין לְכוֹן וּתְיַבְּבוּן בַּחֲצוֹצְרָתָא וְיֵיעוֹל דוּכְרָנֵיכוֹן לְטָּבָא קֳדָם יְיָ אֱלָהָכוֹן וְתִתְפָּרְקוּן מִסַנְאֵיכוֹן:
@394 וּבְיוֹם חֶדְוַתְכוֹן וּבְמוֹעֲדֵיכוֹן וּבְרֵישֵׁי יַרְחֵיכוֹן וְתִתְקְעוּן בַּחֲצוֹצְרָתָא עַל עֲלָוַתְכוֹן וְעַל נִכְסַת קוּדְשֵׁיכוֹן וִיהֶוְיָן לְכוֹן לְדוּכְרָנָא קֳדָם אֱלָהָכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@395 וַהֲוָה בְּשַׁתָּא תִנְיֵתָא בְּיַרְחָא תִנְיָנָא בְּעַשְׂרִין לְיַרְחָא אִסְתַּלֵק עֲנָנָא מֵעִלַוֵי מַשְׁכְּנָא דְסַהֲדוּתָא:
@396 וּנְטָלוּ בְנֵי יִשְׂרָאֵל לְמַטְלָנֵיהוֹן מִמַדְבְּרָא דְסִינַי וּשְׁרָא עֲנָנָא בְּמַדְבְּרָא דְפָארָן:
@397 וּנְטָלוּ בְקַדְמֵיתָא עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@398 וּנְטַל טֵקַס מַשְׁרִית בְּנֵי יְהוּדָה בְּקַדְמֵיתָא לְחֵילֵיהוֹן וְעַל חֵילֵהּ נַחְשׁוֹן בַּר עַמִינָדָב:
@399 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי יִשָׂשׂכָר נְתַנְאֵל בַּר צוּעָר:
@400 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי זְבוּלֻן אֱלִיאָב בַּר חֵלוֹן:
@401 וּמִתְפְּרַק מַשְׁכְּנָא וְנָטְלִין בְּנֵי גֵרְשׁוֹן וּבְנֵי מְרָרִי נָטְלֵי מַשְׁכְּנָא:
@402 וּנְטַל טֵקַס מַשְׁרִית רְאוּבֵן לְחֵילֵיהוֹן וְעַל חֵילֵהּ אֱלִיצוּר בַּר שְׁדֵיאוּר:
@403 וְעַל חֵילָא דְשִׁבְטָּא דִבְנֵי שִׁמְעוֹן שְׁלֻמִיאֵל בַּר צוּרִישַׁדָי:
@404 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי גָד אֶלְיָסָף בַּר דְעוּאֵל:
@405 וְנָטְלִין בְּנֵי קְהָת נָטְלֵי מַקְדְשָׁא וּמְקִימִין יָת מַשְׁכְּנָא עַד מֵיתֵיהוֹן:
@406 וּנְטַּל טֵקַס מַשְׁרִית בְּנֵי אֶפְרַיִם לְחֵילֵיהוֹן וְעַל חֵילֵהּ אֱלִישָׁמָע בַּר עַמִהוּד:
@407 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי מְנַשֶׁה גַמְלִיאֵל בַּר פְּדָהצוּר:
@408 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי בִנְיָמִן אֲבִידָן בַּר גִדְעוֹנִי:
@409 וּנְטַל טֵקַס מַשְׁרִית בְּנֵי דָן מַכְנִישׁ לְכָל מַשִׁרְיָתָא לְחֵילֵיהוֹן וְעַל חֵילֵהּ אֲחִיעֶזֶר בַּר עַמִישַׁדָי:
@410 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי אָשֵׁר פַּגְעִיאֵל בַּר עָכְרָן:
@411 וְעַל חֵילָא דְשִׁבְטָא דִבְנֵי נַפְתָּלִי אֲחִירַע בַּר עֵינָן:
@412 אִלֵין מַטְלָנֵי בְּנֵי יִשְׂרָאֵל לְחֵילֵיהוֹן וּנְטָלוּ:
@413 וַאֲמַר משֶׁה לְחוֹבָב בַּר רְעוּאֵל מִדְיָנָאָה חֲמוֹהִי דְמשֶׁה נָטְלִין אֲנַחְנָא לְאַתְרָא דִי אֲמַר יְיָ יָתֵהּ אֶתֵּן לְכוֹן אִיתָא עִמָנָא וְנוֹטֵיב לָךְ אֲרֵי יְיָ מַלֵיל לְאַיְתָאָה טָּבָא עַל יִשְׂרָאֵל:
@414 וַאֲמַר לֵהּ לָא אֵזִל אֶלָהֵן לְאַרְעִי וּלְיַלָדוּתִי אֵזִל:
@415 וַאֲמַר לָא כְעַן תִּשְׁבּוֹק יָתָנָא אֲרֵי עַל כֵּן יְדַעַתְּ כַּד הֲוֵינָא שָׁרַן בְּמַדְבְּרָא וּגְבוּרָן דְאִתְעֲבִידָן לָנָא חֲזֵיתָא בְעֵינָיִךְ:
@416 וִיהֵי אֲרֵי תֵזִל עִמָנָא וִיהֵי טָבָא הַהוּא דִי יוֹטִיב יְיָ עִמָנָא וְנוֹטִיב לָךְ:
@417 וּנְטָּלוּ מִטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ מַהֲלַךְ תְּלָתָא יוֹמִין וַאֲרוֹן קְיָמָא דַיְיָ נְטַּל קֳדָמֵיהוֹן מַהֲלַךְ תְּלָתָא יוֹמִין לְאַתְקְנָאָה לְהוֹן אֲתַר בֵּית מֵישְׁרֵי:
@418 וַעֲנַן יְקָרָא דַיְיָ מַטֵיל עֲלֵיהוֹן בִּימָמָא בְּמֵטַלְהוֹן מִן מַשְׁרִיתָא:
@419 וַהֲוָה בְּמֵטַל אֲרוֹנָא וַאֲמַר משֶׁה אִתְגְלֵי יְיָ וְיִתְבַּדְרוּן סַנְאָיךְ וִיעַרְקוּן בַּעֲלֵּי דְבָבָךְ מִן קֳדָמָךְ:
@420 וּבְמַשְׁרוֹהִי אֲמַר תּוּב יְיָ שְׁרֵי בִיקָרָךְ בְּגוֹ רִבְבָן אַלְפַיָא דְיִשְׂרָאֵל:
@421 וַהֲוָה עַמָא כַּד מִסְתַּקְפִין בִּישׁ קֳדָם יְיָ וּשְׁמִיעַ קֳדָם יְיָ וּתְקֵף רוּגְזֵיהּ וּדְלֵקַת בְּהוֹן אֶשָׁתָא מִן קֳדָם יְיָ וְשֵׁצִיאַת בִּסְיָפֵי מַשְׁרִיתָא:
@422 וּצְוַח עַמָא עַל משֶׁה וְצַלִי משֶׁה קֳדָם יְיָ וְאִשְׁתְּקַעַת אֶשָׁתָא:
@423 וּקְרָא שְׁמָא דְאַתְרָא הַהוּא דְלֶקְתָּא אֲרֵי דְלֵקַת בְּהוֹן אֶשָׁתָא מִן קֳדָם יְיָ:
@424 וַעָרַבְרְבִין דִי בֵּינֵיהוֹן שְׁאִילוּ שְׁאֶלְתָּא וְתָבוּ וּבְכוֹ אַף בְּנֵי יִשְׂרָאֵל וַאֲמָרוּ מַאן יֵיכְלִנָנָא בִּשְׂרָא:
@425 דְכִירִין אֲנַחְנָא יָת נוּנַיָא דַהֲוֵינָא אָכְלִין בְּמִצְרַיִם מַגָן יָת בּוֹצִינַיָא וְיָת אֲבַטִיחַיָא וּכְרָתֵי וּבוּצְלֵי וְתוּמֵי:
@426 וּכְעַן נַפְשָׁנָא תְאִיבָא לֵית כָּל מִדָעַם אֶלָהֵן לְמַנָא עֵינָנָא:
@427 וּמַנָא כְּבַר זְרַע גִדָא הוּא וְחֶזְוֵהּ כְּחֵזוּ בְדֹלְחָא:
@428 שַׁיְטִין עַמָא וְלָקְטִין דְצָבֵי טָחִין בְּרֵיחַיָא אוֹ דְצָבֵי דָאִיךְ בִּמְדֻכְתָּא וּמְבַשְׁלִין לֵהּ בְּקִדְרָא וְעָבְדִין יָתֵהּ גְרִיצָן וַהֲוָה טַּעֲמֵהּ כִּטְעֵם דְלִישׁ בְּמִשְׁחָא:
@429 וְכַד נַחִית טַלָא עַל מַשְׁרִיתָא לֵילְיָא נָחִית מַנָא עֲלוֹהִי:
@430 וּשְׁמַע משֶׁה יָת עַמָא בָּכַן לְזַרְעֲיַתְהוֹן גְבַר בִּתְרַע מַשְׁכְּנֵה וּתְקֵף רוּגְזָא דַיְיָ לַחֲדָא וּבְעֵינֵי משֶׁה בִּישׁ:
@431 וַאֲמַר משֶׁה קֳדָם יְיָ לְמָא אַבְאֶשְׁתָּא לְעַבְדָךְ וּלְמָא לָא אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ לְשַׁוָאָה יָת מַטוּל כָּלּ עַמָא הָדֵין עָלָי:
@432 הֲאַב אֲנָא לְכָל עַמָא הָדֵין אִם בְּנַי אִנוּן דְאָמְרֵתּ לִי סוֹבַרְהִי בְתוּקְפָךְ כְּמָא דִמְסוֹבַר תֻּרְבְּיָנָא יָת יַנְקָא עַל אַרְעָא דִי קַיֵמְתָּא לַאֲבָהָתוֹהִי:
@433 מְנַן לִי בִּשְׂרָא לְמִיתַּן לְכָל עַמָא הָדֵין אֲרֵי בָּכַן עֲלַי לְמֵימַר הַב לָנָא בִשְׂרָא וְנֵיכוּל:
@434 לֵית אֲנָא יָכִיל בִּלְחוֹדִי לְסוֹבָרָא יָת כָּל עַמָא הָדֵין אֲרֵי יַקִיר מִנִי:
@435 וְאִם כְּדֵין אַתְּ עָבֵד לִי קְטָלְנִי כְעַן קְטוֹל אִם אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ וְלָא אֶחֱזֵי בְּבִישְׁתִּי:
@436 וַאֲמַר יְיָ לְמשֶׁה כְּנוֹשׁ קֳדָמַי שַׁבְעִין גַבְרָא מִסָבֵי יִשְׂרָאֵל דִי יְדַעַתְּ אֲרֵי אִנוּן סָבֵי עַמָא וְסַרְכוֹהִי וְתַדְבֵּר יָתְהוֹן לְמַשְׁכַּן זִמְנָא וְיִתְעַתְּדוּן תַּמָן עִמָךְ:
@437 וְאִתְגְלֵי וַאֲמַלֵל עִמָךְ תַּמָן וַאֲרַבֵּי מִן רוּחָא דִי עֲלָךְ וֶאֱשַׁוֵּי עֲלֵיהוֹן וִיסוֹבְרוּן עִמָךְ בְּמַטוּל עַמָא וְלָא תְסוֹבַר אַתְּ בִּלְחוֹדָךְ:
@438 וּלְעַמָא תֵימַר אִזְדַמְנוּ לִמְחַר וְתֵיכְלוּן בִּשְׂרָא אֲרֵי בְּכִיתוּן קֳדָם יְיָ לְמֵימַר מָן יֵכְלִנָנָא בִּשְׂרָא אֲרֵי טַב לָנָא בְּמִצְרָיִם וְיִתֵּן יְיָ לְכוֹן בִּשְׂרָא וְתֵיכְלוּן:
@439 לָא יוֹמָא חַד תֵּיכְלוּן וְלָא תְרֵין יוֹמִין וְלָא חַמְשָׁא יוֹמִין וְלָא עַשְׂרָא יוֹמִין וְלָא עַשְׂרִין יוֹמִין:
@440 עַד יְרַח יוֹמִין עַד דִי תְקוּצוּן בֵּהּ וִיהֵי לְכוֹן לְתַקְלָא חֲלַף דְקַצְתּוּן יָת מֵימְרָא דַיְיָ דִשְׁכִנְתֵּהּ שַׁרְיַת בֵּינֵיכוֹן וּבְכִיתוּן קֳדָמוֹהִי לְמֵימַר לְמָא דְנַן נְפַקְנָא מִמִצְרָיִם:
@441 וַאֲמַר משֶׁה שִׁית מְאָה אַלְפִין גַבְרָא רִגְלָאָה עַמָא דִי אֲנָא בֵינֵיהוֹן וְאַתְּ אֲמַרְתְּ בִּשְׂרָא אֶתֵּן לְהוֹן וְיֵיכְלוּן יְרַח יוֹמִין:
@442 הֲעָן וְתוֹרִין יִתְנַכְסוּן לְהוֹן הַיְסַפְּקוּן לְהוֹן אִם יָת כָּל נוּנֵי יַמָא יִתְכַנְשׁוּן לְהוֹן הַיְסַפְּקוּן לְהוֹן:
@443 וַאֲמַר יְיָ לְמשֶׁה הֲמֵימְרָא דַיְיָ יִתְעַכָּב כְּעַן תֶּחֱזֵי הַיְעַרְעִנָךְ פִּתְגָמִי אִם לָא:
@444 וּנְפַק משֶׁה וּמַלִיל לְעַמָא יָת פִּתְגָמַיָא דַיְיָ וּכְנַשׁ שַׁבְעִין גַבְרָא מִסָבֵי עַמָא וַאֲקֵים יָתְהוֹן סְחוֹר סְחוֹר לְמַשְׁכְּנָא:
@445 וְאִתְגְלִי יְיָ בַּעֲנָנָא וּמַלִיל עִמֵהּ וְרַבֵּי מִן רוּחָא דִי עֲלוֹהִי וִיהַב עַל שַׁבְעִין גַבְרָא סָבַיָא וַהֲוָה כַּד שְׁרַת עֲלֵיהוֹן רוּחַ נְבוּאָה וּמִתְנַבְּאִין וְלָא פָסְקִין:
@446 וְאִשְׁתַּאֲרוּ תְּרֵין גַבְרִין בְּמַשְׁרִיתָא שׁוּם חָד אֶלְדָד וְשׁוּם תִּנְיָנָא מֵידָד וּשְׁרַת עֲלֵיהוֹן רוּחַ נְבוּאָה וְאִנוּן בַּכְּתִיבַיָא וְלָא נְפָקוּ לְמַשְׁכְּנָא וְאִתְנַבִּיאוּ בְּמַשְׁרִיתָא:
@447 וּרְהַט עוּלֵמָא וְחַוֵי לְמשֶׁה וַאֲמַר אֶלְדָד וּמֵידָד מִתְנַבְּאִין בְּמַשְׁרִיתָא:
@448 וַאֲתֵב יְהוֹשֻׁעַ בַּר נוּן מְשֻׁמְשִׁנֵהּ דְמשֶׁה מֵעוּלֵמוֹהִי וַאֲמַר רִבּוֹנִי משֶׁה אֲסָרִנוּן:
@449 וַאֲמַר לֵהּ משֶׁה הֲקִנְאָתִי אַתְּ מְקַנֵא לִי רְעֵינָא פוּן דִיהוֹן כָּל עַמָא דַיְיָ נְבִיאִין אֲרֵי יִתֵּן יְיָ יָת רוּחַ נְבוּאֲתֵהּ עֲלֵיהוֹן:
@450 וְאִתְכְּנֵשׁ משֶׁה לְמַשְׁרִיתָא הוּא וְסָבֵי יִשְׂרָאֵל:
@451 וְרוּחָא נְטַל מִן קֳדָם יְיָ וְאַפְרַח שְׂלָיו מִן יַמָא וּרְמָא עַל מַשְׁרִיתָא כְּמַהֲלַךְ יוֹמָא לְכָא וּכְמַהֲלַךְ יוֹמָא לְכָא סְחוֹר סְחוֹר לְמַשְׁרִיתָא וּכְרוּם תַּרְתֵּין אַמִין עַל אַפֵּי אַרְעָא:
@452 וְקָם עַמָא כָּל יוֹמָא הַהוּא וְכָל לֵילְיָא וְכָל יוֹמָא דְבַתְרוֹהִי וּכְנָשׁוּ יָת שְׂלָיו דְאַזְעַר כְּנַשׁ עַשְׂרָא דְגוֹרִין וּשְׁטָחוּ לְהוֹן מַשְׁטִיחִין סְחוֹר סְחוֹר לְמַשְׁרִיתָא:
@453 בִּשְׂרָא עַד כְּעַן בֵּין שִׁנֵיהוֹן עַד לָא פְסַק וְרָגְזָא דַיְיָ תְּקֵיף בְּעַמָא וּקְטַל יְיָ בְּעַמָא קְטוֹל סַגִי לַחֲדָא:
@454 וּקְרָא יָת שְׁמָא דְאַתְרָא הַהוּא קִבְרֵי דִמְשַׁאֲלֵי אֲרֵי תַמָן קְבָרוּ יָת עַמָא דְשָׁאִילוּ:
@455 מִקִבְרֵי דִמְשַׁאֲלֵי נְטָּלוּ עַמָא לַחֲצֵרוֹת וַהֲווֹ בַּחֲצֵרוֹת:
@456 וּמַלֵלַת מִרְיָם וְאַהֲרֹן בְּמשֶׁה עַל עֵסַק אִתְּתָא שַׁפִּרְתָּא דִי נְסִיב אֲרֵי אִתְּתָא שַׁפֻּרְתָּא דִנְסִיב רָחִיק:
@457 וַאֲמָרוּ הַלְחוֹד בְּרַם בְּמשֶׁה מַלִיל יְיָ הֲלָא אַף עִמָנָא מַלִיל וּשְׁמִיעַ קֳדָם יְיָ:
@458 וְגַבְרָא משֶׁה עִנְוְתָן לַחֲדָא מִכֹּל אֱנָשָׁא דִי עַל אַפֵי אַרְעָא:
@459 וַאֲמַר יְיָ בִּתְכֵּף לְמשֶׁה וּלְאַהֲרֹן וּלְמִרְיָם פּוּקוּ תְלָתֵיכוֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ תְּלָתֵיהוֹן:
@460 וְאִתְגְלֵי יְיָ בְּעַמוּדָא דַעֲנָנָא וְקָם בִּתְרַע מַשְׁכְּנָא וּקְרָא אַהֲרֹן וּמִרְיָם וּנְפָקוּ תַּרְוֵיהוֹן:
@461 וַאֲמַר שְׁמָעוּ כְעַן פִּתְגָמָי אִם יְהוֹן לְכוֹן נְבִיאִין אֲנָא יְיָ בְּחֶזְוָן אֲנָא מִתְגְלֵי לְהוֹן בְּחֶלְמִין אֲנָא מְמַלֵל עִמְהוֹן:
@462 לָא כֵן עַבְדִי משֶׁה בְּכָל בֵּיתִי מְהֵימָן הוּא:
@463 מַמְלַל עִם מַמְלַל מַלֶלְנָא עִמֵהּ בְּחֵזוּ וְלָא בְחִדְוָן וּדְמוּת יְקָרָא דַיְיָ מִסְתַּכַּל וּמָא דֵין לָא דְחֶלְתּוּן לְמַלָלָא בְּעַבְדִי בְמשֶׁה:
@464 וּתְקֵיף רוּגְזָא דַיְיָ בְּהוֹן וְאִסְתַּלֵק:
@465 וַעֲנָנָא אִסְתַּלַק מֵעִלָוֵי מַשְׁכְּנָא וְהָא מִרְיָם חַוְרָא כְּתַלְגָא וְאִתְפְּנֵי אַהֲרֹן לְוָת מִרְיָם וְהָא סְגִירָת:
@466 וַאֲמַר אַהֲרֹן לְמשֶׁה בְּבָעוּ רִבּוֹנִי לָא כְעַן תְּשַׁוִי עֲלָנָא חוֹבָא דְאִטְפַּשְׁנָא וְדִי סָרֲחְנָא:
@467 לָא כְעַן תִּתְרַחֵק דָא מִבֵּינָנָא אֲרֵי אֲחַתָנָא הִיא צַלִי כְעַן עַל בִּסְרָא מִיתָא הָדֵין דִי בָהּ וְיִתָּסֵי:
@468 וְצַלִי משֶׁה קֳדָם יְיָ לְמֵימָר אֱלָהָא בְּבָעוּ אַסֵי כְעַן יָתָהּ:
@469 וַאֲמַר יְיָ לְמשֶׁה וְאִלוּ אָבוּהָא מִנְזַף נְזִיף בָּהּ הֲלָא תִתְכְּלֵם שַׁבְעָא יוֹמִין תִּסְתַּגֵר שַׁבְעָא יוֹמִין מִבָּרָא לְמַשְׁרִיתָא וּבָתַר כֵּן תִּתְכְּנֵשׁ:
@470 וְאִסְתְּגָרַת מִרְיָם מִבָּרָא לְמַשְׁרִיתָא שַׁבְעָא יוֹמִין וְעַמָא לָא נְטַל עַד דְאִתְכְּנֵשַׁת מִרְיָם:
@471 וּבָתַר כֵּן נְטָלוּ עַמָא מֵחֲצֵרוֹת וּשְׁרוֹ בְּמַדְבְּרָא דְפָארָן: פפפ:
@472 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@473 שְׁלַח לָךְ גֻבְרִין וִיאַלְלוּן יָת אַרְעָא דִכְנָעַן דִי אֲנִי יָהֵב לִבְנֵי יִשְׂרָאֵל גַבְרָא חַד גַבְרָא חַד לְשִׁבְטָא דַאֲבָהָתוֹהִי תְּשַׁלְחוּן כֹּל רַבָּא דִבְהוֹן:
@474 וּשְׁלַח יָתְהוֹן משֶׁה מִמַדְבְּרָא דְפָארָן עַל מֵימְרָא דַיְיָ כֻּלְהוֹן גֻבְרִין רֵישֵׁי בְנֵי יִשְׂרָאֵל אִנוּן:
@475 וְאִלֵין שְׁמָהַתְהוֹן לְשִׁבְטָא דִרְאוּבֵן שַׁמוּעַ בַּר זַכּוּר:
@476 לְשִׁבְטָא דְשִׁמְעוֹן שָׁפָטּ בַּר חוֹרִי:
@477 לְשִׁבְטָא דִיהוּדָה כָּלֵבּ בַּר יְפֻנֶה:
@478 לְשִׁבְטָא דְיִשָׂשׂכָר יִגְאָל בַּר יוֹסֵף:
@479 לְשִׁבְטָא דְאֶפְרַיִם הוֹשֵׁעַ בַּר נוּן:
@480 לְשִׁבְטָא דְבִנְיָמִן פַּלְטִי בַּר רָפוּא:
@481 לְשִׁבְטָא דִזְבוּלֻן גַדִיאֵל בַּר סוֹדִי:
@482 לְשִׁבְטָא דְיוֹסֵף לְשִׁבְטָא דִמְנַשֶׁה גַדִי בַּר סוּסִי:
@483 לְשִׁבְטָא דְדָן עַמִיאֵל בַּר גְמַלִי:
@484 לְשִׁבְטָא דְאָשֵׁר סְתוּר בַּר מִיכָאֵל:
@485 לְשִׁבְטָא דְנַפְתָּלִי נַחְבִּי בַּר וָפְסִי:
@486 לְשִׁבְטָּא דְגָד גְאוּאֵל בַּר מָכִי:
@487 אִלֵין שְׁמָהַת גֻבְרַיָא דִי שְׁלַח משֶׁה לְאַלָלָא יָת אַרְעָא וּקְרָא משֶׁה לְהוֹשֵׁעַ בַּר נוּן יְהוֹשֻׁעַ:
@488 וּשְׁלַח יָתְהוֹן משֶׁה לְאַלָלָא יָת אַרְעָא דִכְנָעַן וַאֲמַר לְהוֹן סָקוּ דָא בִּדְרוֹמָא וְתִסְקוּן לְטוּרָא:
@489 וְתֶחֱזוּן יָת אַרְעָא מָה הִיא וְיָת עַמָא דְיָתֵב עֲלַהּ הֲתַקִיף הוּא אִם חֲלָשׁ הַזְעֵר הוּא אִם סַגִי:
@490 וּמָה אַרְעָא דִי הוּא יָתֵב בָּהּ הֲטָבָא הִיא אִם בִּישָׁא וּמָה קִרְוַיָא דִי הוּא יָתֵב בְהוֹן הַבְּפַצְחִין אִם בִּכְרַכִּין:
@491 וּמָה אַרְעָא הֲעַתִּירָא הִיא אִם מִסְכֵּנָא הֲאִית בַּהּ אִילָנִין אִם לָא וְתִתְקְפוּן וְתִסְבוּן מֵאִבָּא דְאַרְעָא וְיוֹמַיָא יוֹמֵי בִּכּוּרֵי עִנְבִין:
@492 וסְלִיקוּ וְאַלִילוּ יָת אַרְעָא מִמַדְבְּרָא דְצִין עַד רְחוֹב לִמְטֵי חֲמָת:
@493 וּסְלִיקוּ בְדָרוֹמָא וַאֲתָא עַד חֶבְרוֹן וְתַמָן אֲחִימָן שֵׁשַׁי וְתַלְמַי בְּנֵי גִבָּרַיָא וְחֶבְרוֹן שְׁבַע שְׁנִין אִתְבְּנִיאַת קֳדָם טָנֵס דְמִצְרָיִם:
@494 וַאֲתוֹ עַד נַחֲלָא דְאִתְכָּלָא וּקְצוֹ מִתַּמָן עוֹבַרְתָּא וְאַתְכַּל עִנְבִין חַד וּנְטָלוֹהִי בַאֲרִיחָא בִּתְרֵין וּמִן רִמוֹנַיָא וּמִן תְּאֵנַיָא:
@495 לְאַתְרָא הַהוּא קְרָא נַחְלָא דְאִתְכָּלָא עַל עֵסַק אִתְכָּלָא דִקְצוֹ מִתַּמָן בְּנֵי יִשְׂרָאֵל:
@496 וְתָבוּ מִלְאַלָלָא יָת אַרְעָא מִסוֹף אַרְבְּעִין יוֹמִין:
@497 וַאֲזָלוּ וְאָתוּ לְוַת משֶׁה וּלְוַת אַהֲרֹן וּלְוַת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמַדְבְּרָא דְפָארָן לִרְקָם וַאֲתִיבוּ יָתְהוֹן פִּתְגָמָא וְיָת כָּל כְּנִשְׁתָּא וְאַחֲזֵיאֻנוּן יָת אִבָּא דְאַרְעָא:
@498 וְאִשְׁתָּעִיאוּ לֵהּ וַאֲמָרוּ אֲתֵינָא לְאַרְעָא דִי שְׁלַחְתָּנָא וְאַף עַבְדָא חֲלַב וּדְבַשׁ הִיא וְדֵין אִבַּהּ:
@499 לְחוֹד אֲרֵי תַקִיף עַמָא דְיָתֵב בְּאַרְעָא וְקִרְוַיָא כְּרִיכָן רַבְרְבִין לַחֲדָא וְאַף בְּנֵי גִבָּרַיָא חֲזֵינָא תַמָן:
@500 עֲמַלְקָאָה יָתֵב בַּאֲרַע דָרוֹמָא וְחִתָּאָה וִיבוּסָאָה וֶאֱמוֹרָאָה יָתֵב בְּטּוּרָא וּכְנַעֲנָאָה יָתֵב עַל יַמָא וְעַל כֵּיף יַרְדְנָא:
@501 וַאֲצֵית כָּלֵב יָת עַמָא לְמשֶׁה וַאֲמַר מֵיסַק נִיסַק וְנִירַת יָתַהּ אֲרֵי מֵיכַל נֵיכוּל לָהּ:
@502 וְגֻבְרַיָא דִי סְלִיקוּ עִמֵהּ אֲמָרוּ לָא נֵיכוֹל לְמֵיסַק לְוַת עַמָא אֲרֵי תַּקִיף הוּא מִנָנָא:
@503 וְאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא דִי אַלִילוּ יָתָהּ לְוַת בְּנֵי יִשְׂרָאֵל לְמֵימָר אַרְעָא דִי עֲבַרְנָא בָהּ לְאַלָלָא יָתָהּ אַרְעָא מְקַטְלָא יַתְבָהָא הִיא וְכָל עַמָא דִי חֲזֵינָא בְגַוָהּ אֱנָשִׁין דְמִשְׁחָן:
@504 וְתַמָן חֲזֵינָא יָת גִבָּרַיָא בְּנֵי עֲנָק מִן גִבָּרַיָא וַהֲוֵינָא בְעֵינֵי נַפְשָׁנָא כְּקַמְצִין וְכֵן הֲוֵינָא בְּעֵינֵיהוֹן:
@505 וַאֲרֵימַת כָּל כְּנִשְׁתָּא וִיהָבוּ יָת קָלְהוֹן וּבְכוֹ עַמָא בְּלֵילְיָא הַהוּא:
@506 וְאִתְרַעֲמוּ עַל משֶׁה וְעַל אַהֲרֹן כֹּל בְּנֵי יִשְׂרָאֵל וַאֲמָרוּ לְהוֹן כָּל כְּנִשְׁתָּא לְוַי דְמִיתְנָא בְּאַרְעָא דְמִצְרַיִם אוֹ בְּמַדְבְּרָא הָדֵין לְוַי דְמִיתְנָא:
@507 וּלְמָא יְיָ מָעֵל יָתָנָא לְּאַרְעָא הָדָא לְּמִנְפַּלּ בְּחַרְבָּא נְשָׁנָא וְטַּפְלָנָא יְהוֹן לְבִזָא הֲלָא טַב לָנָא דִי נְתוּב לְמִצְרָיִם:
@508 וַאֲמָרוּ גְבַר לַאֲחוֹהִי נְמַנֵי רֵישָׁא וּנְתוּב לְמִצְרָיִם:
@509 וּנְפַל משֶׁה וְאַהֲרֹן עַל אַפֵּיהוֹן קֳדָם כָּל קְהַל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@510 וִיהוֹשֻׁעַ בַּר נוּן וְכָלֵב בַּר יְפֻנֶה מִן מְאַלְלֵי יָת אַרְעָא בְּזָעוּ לְבוּשֵׁיהוֹן:
@511 וַאֲמָרוּ לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמֵימָר אַרְעָא דִי עֲבַרְנָא בָהּ לְאַלָלָא יָתַהּ טָבָא אַרְעָא לְחֲדָא לַחֲדָא:
@512 אִם רַעֲוָא בָנָא קֳדָם יְיָ וְיָעֵל יָתָנָא לְאַרְעָא הָדָא וְיִתְּנִנַהּ לָנָא אַרְעָא דִי הִיא עַבְדָא חֲלַב וּדְבָשׁ:
@513 בְּרַם בְּמֵימְרָא דַיְיָ לָא תִמְרְדוּן וְאַתּוּן לָא תִדַחֲלוּן מִן עַמָא דְאַרְעָא אֲרֵי בִידָנָא מְסִירִין אִנוּן עֲדָא תָקְפְהוֹן מִנְהוֹן וּמֵימְרָא דַיְיָ בְּסַעְדָנָא לָא תִדְחֲלוּן מִנְהוֹן:
@514 וַאֲמָרוּ כָּל כְּנִשְׁתָּא לְמִרְגַם יַתְהוֹן בְּאַבְנַיָא וִיקָרָא דַיְיָ אִתְגְלֵי בְּמַשְׁכַּן זִמְנָא לְכָל בְּנֵי יִשְׂרָאֵל:
@515 וַאֲמַר יְיָ לְמשֶׁה עַד אֵימָתַי יְהוֹן מְרַגְזִין קֳדָמַי עַמָא הָדֵין וְעַד אֵימָתַי לָא יְהֵימְנוּן בְּמֵימְרִי בְּכֹל אָתַיָא דִי עֲבָדִית בֵּינֵיהוֹן:
@516 אֶמְחִנוּן בְּמוֹתָא וַאֲשֵׁצִנוּן וְאֶעְבֵּד יָתָךְ לְעַם רַב וְתַקִיף מִנְהוֹן:
@517 וַאֲמַר משֶׁה קֳדָם יְיָ וְיִשְׁמְעוּן מִצְרָאֵי אֲרֵי אַסֶקְתָּא בְחֵילָךְ יָת עַמָא הָדֵין מִבֵּינֵיהוֹן:
@518 וְיֵימְרוּן לְיָתֵב אַרְעָא הָדָא דִשְׁמָעוּ אֲרֵי אַתְּ יְיָ דִשְׁכִנְתָּךְ שַׁרְיַת בְּגוֹ עַמָא הָדֵין דִי בְעֵינֵיהוֹן חָזַן שְׁכִינַת:יְקָרָא דַיְיָ וַעֲנָנָךְ מַטֵל עִלַוֵהוֹן וּבְעַמוּדָא דַעֲנָנָא אַתְּ מְדַבַּר קֳדָמֵיהוֹן בִּימָמָא וּבְעַמוּדָא דְאֵשָׁתָא בְּלֵילְיָא:
@519 וּתְקַטֵּל יָת עַמָא הָדֵין כְּגַבְרָא חָד וְיֵימְרוּן עַמְמַיָא דִי שְׁמָעוּ יָת שְׁמַע גְבֻרְתָּךְ לְמֵימָר:
@520 מִדְלֵית יוּכְלָא קֳדָם יְיָ לְאָעָלָא יָת עַמָא הָדֵין לְאַרְעָא דִי קַיֵם לְהוֹן וְקַטְלִנוּן בְּמַדְבְּרָא:
@521 וּכְעַן סַגִי כְעַן חֵילָא (מִן) קֳדָם יְיָ כְּמָא דִי מַלֵילְתָּא לְמֵימָר:
@522 יְיָ מַרְחֵק רְגַז וּמַסְגֵי לְמֶעְבַּד טַבְוָן (וּקְשׁוֹט) שָׁבֵק לַעֲוָיָן וְלִמְרוֹד וּלְחוֹבִין סַלַח לִדְתַיְיבִין לְאוֹרַיְתֵהּ וּדְלָא תַיְיבִין לָא מְזַכֵּי מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתָאֵי וְעַל דַר רְבִיעָאֵי:
@523 שְׁבוֹק כְּעַן לְחוֹבֵי עַמָא הָדֵין כִּסְגִיאוּת טַבְוָתָךְ וּכְמָא דִי שְׁבַקְתָּא לְעַמָא הָדֵין מִמִצְרַיִם וְעַד כְּעָן:
@524 וַאֲמַר יְיָ שְׁבָקִית כְּפִתְגָמָךְ:
@525 וּבְרַם קַיָים אֲנָא וּמַלְיָא יְקָרָא דַיְיָ יָת כָּל אַרְעָא:
@526 אֲרֵי כָל גֻבְרַיָא דַחֲזוֹ יָת יְקָרִי וְיָת אַתְוָתַי דִי עֲבָדִית בְּמִצְרַיִם וּבְמַדְבְּרָא וְנַסִיאוּ קֳדָמַי דְנַן עֲשַׂר זִמְנִין וְלָא קַבִּילוּ בְּמֵימְרִי:
@527 אִם יֶחֶזוּן יָת אַרְעָא דִי קַיֵמִית לַאֲבָהַתְהוֹן וְכָל דְאַרְגִיזוּ קֳדָמַי לָא יֶחֱזִנַהּ:
@528 וְעַבְדִי כָלֵב חֲלַף דַהֲוָה רוּחַ אוֹחֲרִי עִמֵהּ וְאַשְׁלֵם בָּתַר דַחַלְתִּי וְאַעֵלִנֵהּ לְאַרְעָא דִי עַאל לְתַמָן וּבְנוֹהִי יְתַרְכִנַהּ:
@529 וַעֲמַלְקָאָה וּכְנַעֲנָאָה יָתֵב בְּמֵישְׁרָא מְחַר אִתְפְּנוּ וְטוּלוּ לְכוֹן לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף:
@530 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@531 עַד אֵימָתַי לִכְנִשְׁתָּא בִישָׁתָא הָדָא דִי אִנוּן מִתְרַעֲמִין עָלָי יָת תֻּרְעֲמַת בְּנֵי יִשְׂרָאֵל דִי אִנוּן מִתְרַעֲמִין עֲלַי שְׁמִיעַ קֳדָמָי:
@532 אֱמַר לְהוֹן קַיָם אֲנָא אֲמַר יְיָ אִם לָא כְּמָא דִי מַלֵילְתּוּן קֳדָמָי כֵּן אֶעְבֵּד לְכוֹן:
@533 בְּמַדְבְּרָא הָדֵין יִפְּלוּן פִּגְרֵיכוֹן וְכָל מִנְיָנֵיכוֹן לְכָל חֻשְׁבַּנְכוֹן מִבַּר עַשְׂרִין שְׁנִין וּלְעֵלָא דִי אִתְרַעַמְתּוּן עֲלָי:
@534 אִם אַתּוּן תֵּעֲלוּן לְאַרְעָא דִי קַיֵמִית בְמֵימְרִי לְאַשְׁרָאָה יַתְכוֹן בַּהּ אֱלָהֵן כָּלֵב בַּר יְפֻנֶה וִיהוֹשֻׁעַ בַּר נוּן:
@535 וְטַּפְלְכוֹן דִי אֲמַרְתּוּן לְבִזָא יְהֵי וְאָעֵל יַתְהוֹן וְיֵדְעוּן יָת אַרְעָא דִי קַצְתּוּן בַּהּ:
@536 וּפִגְרֵיכוֹן דִי לְכוֹן יִפְּלוּן בְּמַדְבְּרָא הָדֵין:
@537 וּבְנֵיכוֹן יְהוֹן מְאַחֲרִין בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין וִיקַבְּלוּן יָת חוֹבֵיכוֹן עַד דִיסוּפוּן פִגְרֵיכוֹן בְּמַדְבְּרָא:
@538 בְּמִנְיַן יוֹמַיָא דִי אַלֶלְתּוּן יָת אַרְעָא אַרְבְּעִין יוֹמִין יוֹמָא לְשַׁתָּא יוֹמָא לְשַּׁתָּא תְּקַבְּלוּן יָת חוֹבֵיכוֹן אַרְבְּעִין שְׁנִין וְתִדְעוּן יָת דְאִתְרַעַמְתּוּן עֲלָי:
@539 אֲנָא יְיָ גְזָרִית בְּמֵימְרִי אִם לָא דָא אֶעְבֵּד לְכָל כְּנִשְׁתָּא בִישְׁתָא הָדָא דְאִזְדַמְנוּ עֲלָי בְּמַדְבְּרָא הָדֵין יְסוּפוּן וְתַמָן יְמוּתוּן:
@540 וְגֻבְרַיָא דִי שְׁלַח משֶׁה לְאַלָלָא יָת אַרְעָא וְתָבוּ וְאַרְעִימוּ עֲלוֹהִי יָת כָּל כְּנִשְׁתָּא לְאַפָּקָא שׁוּם בִּישׁ עַל אַרְעָא:
@541 וּמִיתוּ גֻבְרַיָא דְאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא בְּמוֹתָנָא קֳדָם יְיָ:
@542 וִיהוֹשֻׁעַ בַּר נוּן וְכָלֵב בַּר יְפֻנֶה אִתְקַיְימוּ מִן גֻבְרַיָא הָאִנוּן דַאֲזָלוּ לְאַלָלָא יָת אַרְעָא:
@543 וּמַלִיל משֶׁה יָת פִּתְגָמַיָא הָאִלֵין לְכָל בְּנֵי יִשְׂרָאֵל וְאִתְאַבָּלוּ עַמָא לַחֲדָא:
@544 וְאַקְדִימוּ בְצַפְרָא וּסְלִיקוּ לְרֵישׁ טוּרָא לְמֵימָר הָא אֲנַחְנָא סָלְקִין לְאַתְרָא דִי אֲמַר יְיָ אֲרֵי חַבְנָא:
@545 וַאֲמַר משֶׁה לְמָא דְנַן אַתּוּן עָבְרִין עַל גְזֵרַת מֵימְרָא דַיְיָ וְהִיא לָא תַצְלָח:
@546 לָא תִסְקוּן אֲרֵי לֵית שְׁכִנְתָּא דַיְיָ בֵּינֵיכוֹן וְלָא תִתַּבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@547 אֲרֵי עֲמַלְקָאָה וּכְנַעֲנָאָה תַמָן קֳדָמֵיכוֹן וְתִפְּלוּן בְּחַרְבָּא אֲרֵי עַל כֵּן תַּבְתּוּן מִבָּתַר פּוּלְחָנָא דַיְיָ וְלָא יְהֵי מֵימְרָא דַיְיָ בְּסַעְדְכוֹן:
@548 וְאַרְשָׁעוּ לְמִסַק לְרֵישׁ טוּרָא וַאֲרוֹן קְיָמָא דַיְיָ וּמשֶׁה לָא עֲדוֹ מִגוֹ מַשְׁרִיתָא:
@549 וּנְחַת עֲמַלְקָאָה וּכְנַעֲנָאָה דְיָתֵב בְּטוּרָא הַהוּא וּמְחֻנוּן וּטְרָדֻנוּן עַד חָרְמָה:
@550 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@551 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לַאֲרַע מוֹתְבָנֵיכוֹן דִי אֲנָא יָהֵב לְכוֹן:
@552 וְתַעְבְּדוּן קֻרְבָּנָא קָדָם יְיָ עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָא לְאַפְרָשָׁא נִדְרָא אוֹ בִנְדַבְתָּא אוֹ בְּמוֹעֲדֵיכוֹן לְמֶעְבַּד לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ מִן תּוֹרֵי אוֹ מִן עָנָא:
@553 וִיקָרֵב דִמְקָרֵב קֻרְבָּנֵהּ קֳדָם יְיָ מִנְחָתָא סֻלְתָּא עַשְׂרוֹנָא דְפִילָא בְּרַבְעוּת הִינָא מִשְׁחָא:
@554 וְחַמְרָא לְנִסְכָּא רַבְעוּת הִינָא תַּעְבֵּד עַל עֲלָתָא אוֹ לְנִכְסַת קוּדְשַׁיָא לְאִמְרָא חָד:
@555 אוֹ לְדִכְרָא תַּעְבֵּד מִנְחָתָא סֻלְתָּא תְּרֵין עַשְׂרוֹנִין דְפִילָא בִמְשַׁח תַּלְתּוּת הִינָא:
@556 וְחַמְרָא לְנִסְכָּא תַּלְתּוּת הִינָא תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@557 וַאֲרֵי תַעְבֵּד בַּר תּוֹרֵי עֲלָתָא אוֹ נִכְסַת קוּדְשַּׁיָא לְפָרָשָׁא נִדְרָא אוֹ נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ:
@558 וִיקָרֵב עַל בַּר תּוֹרֵי מִנְחָתָא סֻלְתָּא תְּלָתָא עַשְׂרוֹנִין דְפִילָא בִמְשַׁח פַּלְגוּת הִינָא:
@559 וְחַמְרָא תְּקָרֵב לְנִסְכָּא פַּלְגוּת הִינָא קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@560 כְּדֵין יִתְעֲבֵיד לְתוֹרָא חַד אוֹ לְּדִכְרָא חָד אוֹ לְאִמַר בְּאִמְרַיָא אוֹ בְעִזַיָא:
@561 כְּמִנְיָן דִי תַעְבְּדוּן כְּדֵין תַּעְבְּדוּן לְחַד כְּמִנְיָנֵהוֹן:
@562 כָּל יַצִיבָא יַעְבֵּד כְדֵין יָת אִלֵין לְקָרָבָא קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@563 וַאֲרֵי יִתְגַיַר עִמְכוֹן גִיוֹרָא אוֹ דִי בֵינֵיכוֹן לְדָרֵיכוֹן וְיַעְבֵּד קֻרְבַּן דְמִתְקַּבֵּל בְּרַעֲוָא קֳדָם יְיָ כְּמָא דִי תַעְבְּדוּן כֵּן יַעְבֵּד:
@564 קְהָלָא קְיָמָא חַד לְכוֹן וּלְגִיוֹרָא דְיִתְגַיָר קְיַם עָלָם לְדָרֵיכוֹן כְּוַתְכוֹן כְּגִיוֹרָא יְהֵי:קָדָם יְיָ:
@565 אוֹרַיְתָא חֲדָא וְדִינָא חַד יְהֵי לְכוֹן וּלְגִיוֹרָא דְיִתְגַיַר עִמְכוֹן:
@566 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@567 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן בְּמֵעַלְכוֹן לְאַרְעָא דִי אֲנָא מָעֵל יָתְכוֹן לְתַמָן:
@568 וִיהֵי בְמֵיכַלְכוֹן מִלַחְמָא דְאַרְעָא תַּפְרְשׁוּן אַפְרָשׁוּתָא קֳדָם יְיָ:
@569 רֵישׁ אַצְוַתְכוֹן חַלְתָא תַּפְרְשׁוּן אַפְרָשׁוּתָא כְּמָא דִי מַפְרְשִׁין מִן אִדְרָא כֵּן תַּפְרְשׁוּן יָתַהּ:
@570 מֵרֵישׁ אַצְוַתְכוֹן תִּתְּנוּן קֳדָם יְיָ אַפְרָשׁוּתָא לְדָרֵיכוֹן:
@571 וַאֲרֵי תִשְׁתְּלוּן וְלָא תַעְבְּדוּן יָת כָּל פִּקוֹדַיָא הָאִלֵין דִי מַלִיל יְיָ עִם משֶׁה:
@572 יָת כָּל דִי פַקִיד יְיָ יָתְכוֹן בִּידָא דְמשֶׁה מִן יוֹמָא דִי פָקִיד יְיָ וּלְהָלָא לְדָרֵיכוֹן:
@573 וִיהֵי אִם מֵעֵינֵי כְנִשְׁתָּא אִתְעֲבִדַת לְשָׁלוּ וְיַעְבְּדוּן כָּל כְּנִשְׁתָּא תּוֹר בַּר תּוֹרֵי חַד לַעֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ וּמִנְחָתֵהּ וְנִסְכֵּהּ כִּדְחָזֵי וּצְפִיר בַּר עִזֵי חַד לְחַטָּאתָא:
@574 וִיכַפַּר כַּהֲנָא עַל כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְיִשְׁתְּבֵק לְהוֹן אֲרֵי שָׁלוּתָא הִיא וְאִנוּן אַיְתִיאוּ יָת קֻרְבַּנְהוֹן קֻרְבָּנָא קֳדָם יְיָ וְחוֹבַתְהוֹן קֳדָם יְיָ עַל שָׁלוּתְהוֹן:
@575 וְיִשְׁתְּבֵק לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וּלְגִיוֹרָא דְיִתְגַיַר בֵּינֵיהוֹן אֲרֵי לְכָל עַמָא בְּשָׁלוּתָא:
@576 וְאִם אֱנַשׁ חַד יֵחוֹב בְּשָׁלוּ וִיקָרֵב עִזָא בַּת שַׁתַּהּ לְחַטָאתָא:
@577 וִיכַפַּר כַּהֲנָא עַל אֱנַשׁ דְאִשְׁתְּלֵי בְּמֵחֲבֵהּ בְּשָׁלוּ קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי וְיִשְׁתְּבֵק לֵהּ:
@578 יַצִיבָא בִּבְנֵי יִשְׂרָאֵל וּלְגִיוֹרָא דְיִתְגַיַר בֵּינֵיהוֹן אוֹרַיְתָא חֲדָא יְהֵי לְכוֹן לִדְיַעְבֵּד בְּשָׁלוּ:
@579 וֶאֱנַשׁ דְיַעְבֵּד בְּרֵישׁ גְלֵי מִן יַצִיבַיָא וּמִן גִיוֹרַיָא קֳדָם יְיָ הוּא מַרְגֵז וְיִשְׁתֵּצֵי אֲנָשָׁא הַהִיא מִגוֹ עַמֵהּ:
@580 אֲרֵי עַל מֵימְרָא דַיְיָ בְּסַר וְיָת פִּקוּדוֹהִי אַשְׁנֵי אִשְׁתֵּצָאָה תִשְׁתֵּצֵי אֲנָשָׁא הַהִיא חוֹבֵיהּ בֵּיהּ:
@581 וַהֲווֹ בְנֵי יִשְׂרָאֵל בְּמַדְבְּרָא וְאַשְׁכָּחוּ גַבְרָא כַּד מְגַבֵּב אָעִין בְּיוֹמָא דְשַׁבְּתָא:
@582 וְקָרִיבוּ יָתֵהּ דְאַשְׁכַּחוּ יָתֵהּ כַּד מְגַבֵּב אָעִין לְוָת משֶׁה וּלְוָת אַהֲרֹן וּלְוָת כָּל כְּנִשְׁתָּא:
@583 וַאֲסָרוּ יָתֵהּ בְּבֵית מַטְרָא אֲרֵי לָא אִתְפְּרֵשׁ לְהוֹן מָה דְיַעֲבְּדוּן לֵהּ:
@584 וַאֲמַר יְיָ לְמשֶׁה אִתְקְטָלָא יִתְקְטֵל גַבְרָא רְגוּמוּ יָתֵיהּ בְּאַבְנַיָא כָּל כְּנִשְׁתָּא מִבָּרָא לְמַשְׁרִיתָא:
@585 וְאַפִּיקוּ יָתֵיהּ כָּל כְּנִשְׁתָּא לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵהּ בְּאַבְנַיָא וּמִית כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@586 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@587 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן וְיַעֲבְּדוּן לְהוֹן כְּרוּסְפְּדִין עַל כַּנְפֵי כְסוּתְהוֹן לְדָרֵיהוֹן וְיִתְּנוּן עַל כְּרוּסְפְּדָא דְכַנְפָא חוּטָא דִתְכֶלְתָּא:
@588 וִיהוֹן לְכוֹן לִכְרוּסְפְּדִין וְתֶחֱזוּן יָתֵיהּ וְתִדְכְּרוּן יָת כָּל פִּקוּדַיָא דַיְיָ וְתַעְבְּדוּן יָתְהוֹן וְלָא תִטְעוּן בָּתַר הִרְהוּר לִבְּכוֹן וּבָתַר חֵיזוּ עֵינֵיכוֹן דִי אַתּוּן טָּעַן בַּתְרֵיהוֹן:
@589 בְּדִיל דְתִדְכְּרוּן וְתַעְבְּדוּן יָת כָּל פִּקוּדָי וּתְהוֹן קַדִישִׁין קֳדָם אֱלָּהָכוֹן:
@590 אֲנָא יְיָ אֱלָהָכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֵהֲוֵי לְכוֹן לֶאֱלָהָא אֲנָא יְיָ אֱלָהָכוֹן: פפפ:
@591 וְאִתְפְּלֵג קֹרַח בַּר יִצְהָר בַּר קְהָת בַּר לֵוִי וְדָתָן וַאֲבִירָם בְּנֵי אֱלִיאָב וְאוֹן בַּר פֶּלֶת בְּנֵי רְאוּבֵן:
@592 וְקָמוּ לְאַפֵּי משֶׁה וְגֻבְרַיָא מִבְּנֵי יִשְׂרָאֵל מָאתָן וְחַמְשִׁין רַבְרְבֵי כְנִשְׁתָּא מְעַרְעֵי זְמַן אֱנָשִׁין דִשְׁמָא:
@593 וְאִתְכְּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן וַאֲמָרוּ לְהוֹן סַגִי לְכוֹן אֲרֵי כָל כְּנִשְׁתָּא כֻּלְהוֹן קַדִישִׁין וּבֵינֵיהוֹן שַׁרְיָא שְׁכִנְתָּא דַיְיָ וּמָא דֵין אַתּוּן מִתְרַבְרְבִין עַל קְהָלָא דַיְיָ:
@594 וּשְׁמַע משֶׁה וּנְפַל עַל אַפּוֹהִי:
@595 וּמַלִיל עִם קֹרַח וְעִם כָּל כְּנִשְׁתֵּהּ לְמֵימַר בְּצַפְרָא וִיהוֹדַע יְיָ יָת דְכָשַׁר לֵהּ וְיָת דְקַדִישׁ וִיקָרֵב לָקֳדָמוֹהִי וְיָת דִי יִתְרְעֵי בֵהּ יְקָרֵב לְשִׁמוּשֵׁהּ:
@596 דָא עַבִידוּ סָבוּ לְכוֹן מַחְתְּיָן קֹרַח וְכָל כְּנִשְׁתֵּהּ:
@597 וְהָבוּ בְהוֹן אֵשָׁתָא וְשַׁוִיאוּ עֲלֵיהוֹן קְטוֹרֶת בּוּסְמִין קֳדָם יְיָ מְחַר וִיהֵי גַבְרָא דְיִתְרְעֵי יְיָ הוּא קַדִישּׁ סַגִי לְכּוֹן בְּנֵי לֵוִי:
@598 וַאֲמַר משֶׁה לְקֹרַח שְׁמָעוּ כְעַן בְּנֵי לֵוִי:
@599 הַזְעֵר לְכוֹן אֲרֵי אַפְרֵשׁ אֱלָהָא דְיִשְׂרָאֵל יָתְכוֹן מִכְּנִשְׁתָּא דְיִשְׂרָאֵל לְקֳרָבָא יָתְכוֹן קֳדָמוֹהִי לְמִפְלַח יָת פּוּלְחַן מַשְׁכְּנָא דַיְיָ וּלְמֵקַם קֳדָם כְּנִשְׁתָּא לְשַׁמָשׁוּתְהוֹן:
@600 וְקָרֵב יָתָךְ וְיַת כָּל אֲחָךְ בְּנֵי לְוֵי עִמָךְ וּכְעַן אַתּוּן בָּעָן אַף כְּהוּנְתָא רַבְּתָא:
@601 בְּכֵן אַתְּ וְכָל כְּנִשְׁתָּךְ דְאִזְדַמַנְתּוּן עַל יְיָ וְאַהֲרֹן מַה הוּא אֲרֵי אִתְרַעַמְתּוּן עֲלוֹהִי:
@602 וּשְׁלַח משֶׁה לְמִקְרֵי לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב וַאֲמָרוּ לָא נִסָק:
@603 הַזְעֵיר אֲרֵי אַסֵקְתָּנָא מֵאַרְעָא עָבְדָא חֲלַב וּדְבָשׁ לְקַטָלוּתָנָא בְּמַדְבְּרָא אֲרֵי אִתְרַבְרַבְתְּ עֲלָנָא אַף אִתְרַבְרָבָא:
@604 בְּרַם לָא לְאַרְעָא עָבְדָא חֲלָב וּדְבָשׁ אַעֵלְתָּנָא וִיהַבְתְּ לָנָא אַחֲסָנַת חַקְלִין וְכַרְמִין הַעֵינֵי גֻבְרַיָא הָאִינוּן תְּשַׁלַח לְעַוָרָא לָא נִסָק:
@605 וּתְקֵף לְמשֶׁה לַחֲדָא וַאֲמַר קֳדָם יְיָ לָא תְקַבֵּל בְּרַעֲוָא קוּרְבַּנְהוֹן לָא חֲמָרָא דְחַד מִנְהוֹן שְׁחָרִית וְלָא אַבְאֵישִׁית יַת חָד מִנְהוֹן:
@606 וַאֲמַר משֶׁה לְקֹרַח אַתְּ וְכָל כְּנִשְׁתָּךְ הֱווֹ זְמִינִין לָקֳדָם יְיָ אַתְּ וְאִינוּן וְאַהֲרֹן מְחָר:
@607 וּסְבוּ גְבַר מַחְתִּיתֵיהּ וּתְשַׁווּן עֲלֵיהוֹן קְטוֹרֶת בּוּסְמִין וְתִקָרְבוּן קֳדָם יְיָ גְבַר מַחְתִּיתֵיהּ מָאתָן וְחַמְשִׁין מַחְתְּיָן וְאַתְּ וְאַהֲרֹן גְבַר מַחְתִּיתֵהּ:
@608 וּנְסִיבוּ גְבַר מַחְתִּיתֵהּ וִיהָבוּ עֲלֵיהוֹן אֵשָׁתָא וְשַׁוִיאוּ עֲלֵיהוֹן קְטֹרֶת בּוּסְמִין וְקָמוּ בִּתְרַע מַשְׁכַּן זִמְנָא וּמשֶׁה וְאַהֲרֹן:
@609 וְאַכְנֵשׁ עֲלֵיהוֹן קֹרַח יָת כָּל כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא וְאִתְגְלֵי יְקָרָא דַיְיָ לְכָל כְּנִשְׁתָּא:
@610 וּמַלֵיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@611 אִתְפְּרָשׁוּ מִגוֹ כְּנִשְׁתָּא הָדָא וֶאֱשֵׁיצֵי יַתְהוֹן כְּשָׁעָה:
@612 וּנְפָלוּ עַל אַפֵּיהוֹן וַאֲמָרוּ אֵל אֱלָהָא רוּחַיָא לְכָל בִּשְׂרָא גַבְרָא חָד יֵיחוֹב וְעַל כָּל כְּנִשְׁתָּא יְהֵי רוּגְזָא:
@613 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@614 מַלֵל עִם כְּנִשְׁתָּא לְמֵימָר אִסְתַּלָקוּ מִסְחוֹר סְחוֹר לְמַשְׁכְּנָא דְקֹרַח דָתָן וַאֲבִירָם:
@615 וְקָם משֶׁה וַאֲזַל לְוַת דָתָן וַאֲבִירָם וַאֲזָלוּ בַּתְרוֹהִי סָבֵי יִשְׂרָאֵל:
@616 וּמַלֵיל עִם כְּנִשְׁתָּא לְמֵימָר זוּרוּ כְעַן מֵעִלַוֵי מַשְׁכְּנֵי גֻבְרַיָא חַיָיבַיָא הָאִלֵין וְלָא תְקָרְבוּן בְּכָל דִי לְהוֹן דִלְמָא תִלְקוּן בְּכָל חוֹבֵיהוֹן:
@617 וְאִסְתַּלָקוּ מֵעִלַוֵי מַשְׁכְּנָא דְקֹרַח דָתָן וַאֲבִירָם מִסְחוֹר סְחוֹר וְדָתָן וַאֲבִירָם נְפָקוּ קַיְימִין בִּתְרַע מַשְׁכְּנֵיהוֹן וּנְשֵׁיהוֹן וּבְנֵיהוֹן וְטַפְלְהוֹן:
@618 וַאֲמַר משֶׁה בְּדָא תִדְעוּן אֲרֵי יְיָ שַׁלְחַנִי לְמֶעְבַּד יָת כָּל עוֹבָדַיָא הָאִלֵין אֲרֵי לָא מֵרְעוּתִי:
@619 אִם כְּמוֹתָא דְכָל אֱנָשָׁא יְמוּתוּן אִלֵין וּסְעָרָא דְכָל אֱנָשָׁא יִסְתְּעַר עֲלֵיהוֹן לָא יְיָ שַׁלְחַנִי:
@620 וְאִם בְּרִיאָה יִבְרֵי יְיָ וּפְתָחַת אַרְעָא יָת פּוּמַהּ וְתִבְלַע יַתְהוֹן וְיַת כָּל דִי לְהוֹן וְיֶחֱתוּן כַּד חַיִין לִשְׁאוֹל וְתִדְעוּן אֲרֵי אַרְגִיזוּ גוּבְרַיָא הָאִלֵין קֳדָם יְיָ:
@621 וַהֲוָה כַּד שֵׁיצֵי לְמַלָלָא יָת כָּל פִּתְגָמַיָא הָאִלֵין וְאִתְבְּזָעַת אַרְעָא דִי תְּחוֹתֵיהוֹן:
@622 וּפְתָחַת אַרְעָא יָת פּוּמָהּ וּבְלָעַת יַתְהוֹן וְיַת אֱנַשׁ בָּתֵּיהוֹן וְיַת כָּל אֱנָשָׁא דִי לְקֹרַח וְיַת כָּל קִנְיָנָא:
@623 וּנְחָתוּ אִינוּן וְכָל דִי לְהוֹן כַּד חַיִין לִשְׁאוֹל וַחֲפַת עֲלֵיהוֹן אַרְעָא וַאֲבָדוּ מִגוֹ קְהָלָא:
@624 וְכָל יִשְׂרָאֵל דִי בְסַחֲרָנֵיהוֹן עֲרָקוּ לְקַלְהוֹן אֲרֵי אֲמָרוּ דִלְמָא תִבְלְעִנָנָא אַרְעָא:
@625 וְאֶשָׁתָא נְפָקַת מִן קֳדָם יְיָ וַאֲכָלַת יָת מָאתָן וְחַמְשִׁין גַבְרָא מְקַרְבֵי קְטוֹרֶת בּוּסְמַיָא:
@626 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@627 אֱמַר לְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְיַפְרֵשׁ יָת מַחְתְּיָתָא מִבֵּין יְקִידַיָא וְיָת אֶשָׁתָא יַרְחִיק לְהָלָא אֲרֵי אִתְקַדָשׁוּ:
@628 יָת מַחְתְּיַת חַיָיבַיָא הָאִלֵין דְאִתְחַיְיבוּ בְּנַפְשָׁתֵיהוֹן וְיַעְבְּדוּן יַתְהוֹן טַסִין רְדִידִין חוֹפָאָה לְמַדְבְּחָא אֲרֵי קָרֵבֻנוּן קֳדָם יְיָ וְאִתְקַדָשׁוּ וִיהֶוְיָן לְאָת לִבְּנֵי יִשְׂרָאֵל:
@629 וּנְסִיב אֶלְעָזָר כַּהֲנָא יָת מַחְתְּיָתָא דִנְחָשָׁא דְקָרִיבוּ יוֹקִידַיָא וְרַדִידֻנוּן חוֹפָאָה לְמַדְבְּחָא:
@630 דָכְרָנָא לִבְנֵי יִשְׂרָאֵל בְּדִיל דִי לָא יִקְרַב גְבַר חִלוֹנַי דִי לָא מִזַרְעָא דְאַהֲרֹן הוּא לְאַסָקָא קְטוֹרֶת בּוּסְמִין קֳדָם יְיָ וְלָא יְהֵי כְקֹרַח וְכִכְנִשְׁתֵּיהּ כְּמָא דִי מַלֵיל יְיָ בִּידָא דְמשֶׁה לֵיהּ:
@631 וְאִתְרַעֲמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִיוֹמָא דְבַתְרוֹהִי עַל משֶׁה וְעַל אַהֲרֹן לְמֵימָר אַתּוּן גְרַמְתּוּן דְמִית עַמָא דַיְיָ:
@632 וַהֲוָה בְּאִתְכַּנָשׁוּת כְּנִשְׁתָּא עַל משֶׁה וְעַל אַהֲרֹן וְאִתְפְּנִיאוּ לְמַשְׁכַּן זִמְנָא וְהָא חֲפָהִי עֲנָנָא וְאִתְגְלִי יְקָרָא דַיְיָ:
@633 וְעָאל משֶׁה וְאַהֲרֹן לָקֳדָם מַשְׁכַּן זִמְנָא:
@634 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@635 אִתְפְרָשׁוּ מִגוֹ כְּנִשְׁתָּא הָדָא וְאֱשֵׁיצֵי יָתְהוֹן כְּשָׁעָה וּנְפָלוּ עַל אַפֵּיהוֹן:
@636 וַאֲמַר משֶׁה לְאַהֲרֹן סַב יָת מַחְתִּיתָא וְהַב עֲלַהּ אֶשָׁתָא מֵעִלָוֵי מַדְבְּחָא וְשַׁו קְטוֹרֶת בּוּסְמַיָא וְאוֹבִיל בִּפְרִיעַ לִכְנִשְׁתָּא וְכַפֵּר עֲלֵיהוֹן אֲרֵי נְפַק רָגְזָא מִן קֳדָם יְיָ שָׁרֵי מוֹתָנָא:
@637 וּנְסֵיב אַהֲרֹן כְּמָא דְמַלֵיל משֶׁה וּרְהַט לְגוֹ קְהָלָא וְהָא שָׁרֵי מוֹתָנָא בְּעַמָא וִיהַב יָת קְטּוֹרֶת בּוּסְמַיָא וְכַפֵּר עַל עַמָא:
@638 וְקָם בֵּין מֵתַיָא וּבֵין חַיַיָא וְאִתְכְּלִי מוֹתָנָא:
@639 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא אַרְבַּעַת עֲשַׂר אַלְפִין וּשְׁבַע מְאָה בַּר מִדְמִיתוּ עַל פְּלֻגְתָּא דְקֹרַח:
@640 וְתָב אַהֲרֹן לְמשֶׁה לִתְרַע מַשְׁכַּן זִמְנָא וּמוֹתָנָא אִתְכְּלִי:
@641 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@642 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְסַב מִנְהוֹן חוּטְרָא חוּטְרָא לְבֵית אַבָּא מִן כָּל רַבְרְבָנֵיהוֹן לְבֵית אֲבָהַתְהוֹן תְּרֵי עֲשַׂר חוּטְרִין גְבַר יָת שְׁמֵיהּ תִּכְתּוֹב עַל חוּטְרֵיהּ:
@643 וְיָת שְׁמָא דְאַהֲרֹן תִּכְתּוֹב עַל חוּטְרָא דְלֵוִי אֲרֵי חוּטְרָא חָד לְרֵישׁ בֵּית אֲבָהַתְהוֹן:
@644 וְתַצְנְעִינוּן בְּמַשְׁכַּן זִמְנָא קֳדָם סַהֲדוּתָא דִי אֲזַמִין מֵימְרִי לְכוֹן תַּמָן:
@645 וִיהֵי גַבְרָא דִי אִתְרְעֵי בֵּהּ חוּטְרֵיהּ יִנְעֵי וַאֲנִיחַ מִן קֳדָמַי יָת תּוּרְעֲמַת בְּנֵי יִשְׂרָאֵל דִי אִנוּן מִתְרַעֲמִין עֲלֵיכוֹן:
@646 וּמַלֵיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל וִיהָבוּ לֵיהּ כָּל רַבְרְבָנֵיהוֹן חוּטְרָא לְרַבָּא חָד חוּטְרָא לְרַבָּא חָד לְבֵית אֲבָהַתְהוֹן תְּרֵי עֲשַׂר חוּטְרִין וְחוּטְרָא דְאַהֲרֹן בְּגוֹ חוּטְרֵיהוֹן:
@647 וְאַצְנַע משֶׁה יָת חוּטְּרַיָא קֳדָם יְיָ בְּמַשְׁכְּנָא דְסַהֲדוּתָא:
@648 וַהֲוָה בְּיוֹמָא דְבַתְרוֹהִי וְעַאל משֶׁה לְמַשְׁכְּנָא דְסַהֲדוּתָא וְהָא נְעָא חוּטְרָא דְאַהֲרֹן לְבֵית לְוֵי וְאַפֵּק לַבְלְבִין וְאָנֵץ נֵץ וְכָפֵית שִׁיגְדִין:
@649 וְאַפֵיק משֶׁה יָת כָּל חוּטְרַיָא מִן קֳדָם יְיָ לְוָת כָּל בְּנֵי יִשְׂרָאֵל וְאִשְׁתְּמוֹדָעוּ וּנְסִיבוּ גְבַר חוּטְרֵיהּ:
@650 וַאֲמַר יְיָ לְמשֶׁה אָתֵיב יַת חוּטְרָא דְאַהֲרֹן לְקֳדָם סַהֲדוּתָא לְמַטָרָא לְאָת לְעַמָא סַרְבָנָא וִיסוּפַן תּוּרְעֲמַתְהוֹן מִן קֳדָמַי וְלָא יְמוּתוּן:
@651 וַעֲבַד משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵיה כֵּן עֲבָד:
@652 וַאֲמָרוּ בְּנֵי יִשְׂרָאֵל לְמשֶׁה לְמֵימָר הָא מִנָנָא קְטָלַת חַרְבָּא הָא מִנָנָא בְּלָעַת אַרְעָא וְהָא מִנָנָא דְמִיתוּ בְמוֹתָנָא:
@653 כֹּל דְקָרֵב מִקְרַב לְמַשְׁכְּנָא דַיְיָ מָאִית הָא אַנַחְנָא סַיְפִין לִמְמָת:
@654 וַאֲמַר יְיָ לְאַהֲרֹן אַתְּ וּבְנָךְ וּבֵית אֲבוּךְ עִמָךְ תְּסַלְחוּן עַל חוֹבֵי מַקְדְשָׁא וְאַתְּ וּבְנָךְ עִמָךְ תְּסַלְחוּן עַל חוֹבֵי כְּהוּנַתְכוֹן:
@655 וְאַף יָת אֲחָיךְ שִׁבְטָא דְלֵוִי שִׁבְטָא דַאֲבוּךְ קָרֵיב לְוָתָךְ וְיִתּוֹסְפוּן עֲלָךְ וִישַׁמְשׁוּנָךְ וְאַתְּ וּבְנָךְ עִמָךְ קֳדָם מַשְׁכְּנָא דְסַהֲדוּתָא:
@656 וְיִטְרוּן מַטַרְתָּךְ וּמַטְרַת כָּל מַשְׁכְּנָא בְּרַם לְמָנֵי קוּדְשָׁא וּלְמַדְבְּחָא לָא יִקְרְבוּן וְלָא יְמוּתוּן אַף אִינוּן אַף אַתּוּן:
@657 וְיִתּוֹסְפוּן עֲלָךְ וְיִטְרוּן יָת מַטְרַת מַשְׁכַּן זִמְנָא לְכָל פּוּלְחַן מַשְׁכְּנָא וְחִילוֹנֵי לָא יִקְרַב לְוָתְכוֹן:
@658 וְתִטְרוּן יָת מַטְרַת קוּדְשָׁא וְיָת מַטְרַת מַדְבְּחָא וְלָא יְהֵי עוֹד רוּגְזָא עַל בְּנֵי יִשְׂרָאֵל:
@659 וַאֲנָא הָא קְרֵיבִית יָת אֲחֵיכוֹן לֵוָאֵי מִגוֹ בְּנֵי יִשְׂרָאֵל לְכוֹן מַתְּנָא יְהִיבִין קֳדָם יְיָ לְמִפְלַח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@660 וְאַתְּ וּבְנָךְ עִמָךְ תִּטְרוּן יָת כְּהוּנַתְכוֹן לְכָל פִּתְגַם מַדְבְּחָא וּלְמִגָיו לְפָרוּכְתָּא וְתִפְלְחוּן פוּלְחַן מַתְּנָא אֵיהַב יָת כְּהוּנַתְכוֹן וְחִילוֹנֵי דְיִקְרַב יִתְקְטֵיל:
@661 וּמַלֵיל יְיָ עִם אַהֲרֹן וַאֲנָא הָא יְהָבִית לָךְ יָת מַטְרַת אַפְרָשׁוּתָי לְכָל קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל לָךְ יְהַבְתִּינוּן לִרְבוּ וְלִבְנָךְ לִקְיָם עֲלָם:
@662 דֵין יְהֵי לָךְ מִקוֹדֶשׁ קוּדְשַׁיָא מוֹתַר מִן אֶשָׁתָא כָּל קוּרְבַּנְהוֹן לְכָל מִנְחַתְהוֹן וּלְכָל חַטְוַתְהוֹן וּלְכָל אֲשַׁמְהוֹן דִי יְתִיבוּן קֳדָמַי קוֹדֶשׁ קוּדְשִׁין דִילָךְ הִיא וְלִבְנָךְ:
@663 בְּקֹדֶשׁ קוּדְשִׁין תֵּיכְלוּנֵיהּ כָּל דְכוּרָא יֵיכוֹל יָתֵיהּ קוּדְשָׁא יְהֵי לָךְ:
@664 וְדֵין לָךְ אַפְרָשׁוּת מַתְּנַתְהוֹן לְכָל אֲרָמוּת בְּנֵי יִשְׂרָאֵל לָךְ יְהַבְתִּינוּן וְלִבְנָיךְ וְלִבְנְתָיךְ עִמָךְ לִקְיַם עֲלָם כָּל דִדְכֵי בְּבֵיתָךְ יֵיכוֹל יָתֵיהּ:
@665 כָּל טוּב מְשַׁח וְכָל טוּב חֲמַר וְעִבּוּר רֵאשִׁיתְהוֹן דִי יִתְּנוּן קֳדָם יְיָ לָךְ יְהַבְתִּינוּן:
@666 בִּכּוּרֵי כָּל דִי בְאַרְעֲהוֹן דִי יַיְתוּן קֳדָם יְיָ דִילָךְ יְהֵי כָּל דִדְכֵי בְּבֵיתָךְ יֵיכְלִנֵיהּ:
@667 כָּל חֶרְמָא בְּיִשְׂרָאֵל דִילָךְ יְהֵי:
@668 כָּל פְּתַח וַלְדָא לְכָל בִּשְׂרָא דִי יְקָרְבוּן קֳדָם יְיָ בֶּאֱנָשָׁא וּבִבְעִירָא יְהֵי לָךְ בְּרַם מִפְרַק תִּפְרוֹק יָת בּוּכְרָא דֶאֱנָשָׁא וְיָת בּוּכְרָא דִבְעִירָא מְסַאֲבָא תִּפְרוֹק:
@669 וּפוּרְקָנֵיהּ מִבַּר יַרְחָא תִּפְרוֹק בְּפוּרְסָנֵיהּ כְּסַף חַמְשָׁא סִלְעִין בְּסִלְעֵי קוּדְשָׁא עַשְׂרִין מָעִין הוּא:
@670 בְּרַם בּוּכְרָא דְתוֹרָא אוֹ בּוּכְרָא דְאִמְרָא אוֹ בּוּכְרָא דְעִזָא לָא תִפְרוֹק קוּדְשָׁא אִינוּן יָת דִמְהוֹן תִּזְרוֹק עַל מַדְבְּחָא וְיָת תַּרְבְּהוֹן תַּסֵיק קוּרְבַּן לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ:
@671 וּבִשְׂרְהוֹן יְהֵי לָךְ כְּחַדְיָא דַאֲרָמוּתָא וּכְשַׁקָא דְיַמִינָא דִילָךְ יְהֵי:
@672 כָּל אַפְרָשׁוּת קוּדְשַׁיָא דִי יִפְרְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ יְהָבִית לָךְ וְלִבְנָיךְ וְלִבְנָתָיךְ עִמָךְ לִקְיַם עֲלָם קְיַים מְלַח עֲלָם הִיא קֳדָם יְיָ לָךְ וְלִבְנָךְ עִמָךְ:
@673 וַאֲמַר יְיָ לְאַהֲרֹן בְּאַרְעֲהוֹן לָא תַחֲסִין וְחוּלַק לָא יְהֵי לָךְ בֵּינֵיהוֹן מַתְּנָן דִי יְהָבִית לָךְ אִנוּן חוּלְקָךְ וְאַחֲסַנְתָּךְ בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@674 וְלִבְנֵי לֵוִי הָא יְהָבִית כָּל מַעַשְׂרָא בְּיִשְׂרָאֵל לְאַחֲסָנָא חֲלַף פּוּלְחַנְהוֹן דִי אִינוּן פָּלְחִין יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@675 וְלָא יִקְרְבוּן עוֹד בְּנֵי יִשְׂרָאֵל לְמַשְׁכַּן זִמְנָא לְקַבָּלָא חוֹבָא לִמְמָת:
@676 וְיִפְלְחוּן לֵוָאֵי אִינוּן יָת פּוּלְחַן מַשְׁכַּן זִמְנָא וְאִינוּן יְקַבְּלוּן חוֹבֵיהוֹן קְיַם עֲלָם לְדָרֵיכוֹן וּבְגוֹ בְּנֵי יִשְׂרָאֵל לָא יַחְסְנוּן אַחְסָנָא:
@677 אֲרֵי יָת מַעַשְׂרָא דִבְנֵי יִשְׂרָאֵל דִי יִפְרְשׁוּן קֳדָם יְיָ אַפְרָשׁוּתָא יְהָבִית לְלֵוָאֵי לְאַחֲסָנָא עַל כֵּן אֲמָרִית לְהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל לָא יַחְסְנוּן אַחֲסָנָא:
@678 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@679 וּלְלֵוָאֵי תְּמַלֵיל וְתֵימַר לְהוֹן אֲרֵי תִסְבוּן מִן בְּנֵי יִשְׂרָאֵל יָת מַעַשְׂרָא דִי יְהָבִית לְכוֹן מִנְהוֹן בְּאַחֲסַנְתְּכוֹן וְתַפְרְשׁוּן מִנֵיהּ אַפְרָשׁוּתָא קֳדָם יְיָ מַעַשְׂרָא מִן מַעַשְׂרָא:
@680 וְתִתְחַשֵׁב לְכוֹן אַפְרָשׁוּתְכוֹן כְּעִבּוּרָא מִן אִדְרָא וְכִמְלֵאָתָא מִן מַעְצַרְתָּא:
@681 כֵּן תַּפְרְשׁוּן אַף אַתּוּן אַפְרָשׁוּתָא קֳדָם יְיָ מִכֹּל מַעַשְׂרָתֵיכוֹן דִי תִסְבוּן מִן בְּנֵי יִשְׂרָאֵל וְתִתְּנוּן מִנֵיהּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ לְאַהֲרֹן כַּהֲנָא:
@682 מִכֹּל מַתְּנָתֵכוֹן תִּפְרְשׁוּן יָת כָּל אַפְרָשׁוּתָא דַיְיָ מִכָּל שׁוּפְרֵיהּ יָת מַקְדְשֵׁיהּ מִנֵיהּ:
@683 וְתֵימַר לְהוֹן בְּאַפְרָשׁוּתְכוֹן יָת שׁוּפְרֵיהּ מִנֵיהּ וְיִתְחַשֵׁב לְלֵּוָאֵי כַּעֲלָלַת אִדְרָא וְכַעֲלָלַת מַעֲצַרְתָּא:
@684 וְתֵיכְלוּן יָתֵיהּ בְּכָל אֲתַר אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן אֲרֵי אַגְרָא הוּא לְכוֹן חֲלַף פָּלְחַנְכוֹן בְּמַשְׁכַּן זִמְנָא:
@685 וְלָא תְקַבְּלוּן עֲלוֹהִי חוֹבָא בְּאַפְרָשׁוּתְכוֹן יָת שׁוּפְרֵיהּ מִנֵיהּ וְיָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל לָא תְחַלְלוּן וְלָא תְמוּתוּן: פפפ:
@686 וּמַלִיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@687 דָא גְזֵירַת אוֹרַיְתָא דִי פַקִיד יְיָ לְמֵימָר מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ תּוֹרְתָא סִמוּקְתָּא שְׁלֶמְתָּא דִי לֵית בָּהּ מוּמָא דְלָא סְלִיק עֲלַהּ נִירָא:
@688 וְתִתְּנוּן יָתַהּ לְאֶלְעָזָר כַּהֲנָא וְיַפֵּק יָתַהּ לְמִבָּרָא לְמַשְׁרִיתָא וְיִכּוֹס יָתַהּ קֳדָמוֹהִי:
@689 וְיִסַב אֶלְעָזָר כַּהֲנָא מִדְמַהּ בְּאֶצְבְּעֵיהּ וְיַדֵי לָקֳבֵל אַפֵּי מַשְׁכַּן זִמְנָא מִדְמַהּ שְׁבַע זִמְנִין:
@690 וְיוֹקֵד יָת תּוֹרְתָא לְעֵינוֹהִי יָת מַשְׁכַּהּ וְיָת בִּשְׂרַהּ וְיָת דְמַהּ עַל אָכְלַהּ יוֹקֵיד:
@691 וְיִסַב כַּהֲנָא אָעָא דְאַרְזָא וְאֵזוֹבָא וּצְבַע זְהוֹרִי וְיִרְמֵי לְגוֹ יְקִידַת תּוֹרְתָא:
@692 וִיצַבַּע לְבוּשׁוֹהִי כַּהֲנָא וְיַסְחֵי בִשְׂרֵיהּ בְמַיָא וּבָתַר כֵּן יֵיעוּל לְמַשְׁרִיתָא וִיהֵי מְסָאָב כַּהֲנָא עַד רַמְשָׁא:
@693 וּדְמוֹקֵד יָתַהּ יְצַבַּע לְבוּשׁוֹהִי בְּמַיָא וְיַסְחֵי בִשְׂרֵיהּ בְּמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@694 וְיִכְנוֹשׁ גְבַר דְכֵי יָת קִטְמָא דְתוֹרְתָא וְיַצְנַע לְמִבָּרָא לְמַשְׁרִיתָא בַּאֲתַר דְכֵי וּתְהֵי לִכְנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמַטָּרָא לְמֵי אַדָיוּתָא חַטָאתָא הִיא:
@695 וִיצַבַּע דְכַנֵישׁ יָת קִטְמָא דְתוֹרְתָא יָת לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּתְהֵי לִבְנֵי יִשְׂרָאֵל וּלְגִיוֹרַיָא דְיִתְגַיְירוּן בֵּינֵיהוֹן לִקְיַים עֲלָם:
@696 דְיִקְרַב בְּמִיתָא לְכָל נַפְשָׁא דֶאֱנָשָׁא וִיהֵי מְסָאָב שַׁבְעָא יוֹמִין:
@697 הוּא יַדֵי עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה יִדְכֵּי וְאִם לָא יַדֵי עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה לָּא יִדְכֵּי:
@698 כָּלּ דְיִקְרַבּ בְּמִיתָא בְּנַפְשָׁא דֶאֱנָשָׁא דִי יְמוּת וְלָא יַדֵי עֲלוֹהִי יָת מַשְׁכְּנָא דַיְיָ סָאֵב וְיִשְׁתֵּצֵי אֱנָשָׁא הַהוּא מִיִשְׂרָאֵל אֲרֵי מֵי אַדָיוּתָא לָא אִזְדְרִיקוּ עֲלוֹהִי מְסָאָב יְהֵי עוֹד סְאוֹבְתֵּיהּ בֵּיהּ:
@699 דָא אוֹרַיְתָא אֱנַשׁ אֲרֵי יְמוּת בְּמַשְׁכְּנָא כָּל דְעָלֵל לְמַשְׁכְּנָא וְכָל דִי בְמַשְׁכְּנָא יְהֵי מְסָאָב שַׁבְעָא יוֹמִין:
@700 וְכָל מַן דַחֲסַף פְּתִיחַ דְלֵית מִגוּפַת שְׁיִיעַ מַקַף עַלוֹהִי מְסָאָב הוּא:
@701 וְכֹל דִי יִקְרַב עַל אַפֵּי חַקְלָא בִּקְטֵל חַרְבָּא אוֹ בְמִיתָא אוֹ בְגַרְמָא דֶאֱנָשָׁא אוֹ בְקִבְרָא יְהֵי מְסָאָב שַׁבְעָא יוֹמִין:
@702 וְיִסְבוּן לְדִמְסָאָב מֵעֲפַר יְקִידַת חַטָאתָא וְיִתֵּן עֲלוֹהִי מֵי מַבּוּעַ לְמָן:
@703 וְיִסַב אֵזוֹבָא וְיִטְבּוֹל בְּמַיָא גְבַר דְכֵי וְיַדֵי עַל מַשְׁכְּנָא וְעַל כָּל מָנַיָא וְעַל נַפְשָׁתָא דִי הֲווֹ תַמָן וְעַל דְיִקְרַב בְּגַרְמָא אוֹ בְקָטִילָא אוֹ בְמִיתָא אוֹ בְקִבְרָא:
@704 וְיַדֵי דַכְיָא עַל מְסָאֲבָא בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה וִידַכִּינֵיהּ בְּיוֹמָא שְׁבִיעָאָה וִיצַבַּע לְבּוּשׁוֹהִי וְיַסְחֵי בְמַיָא וְיִדְכֵּי בְרַמְשָׁא:
@705 וּגְבַר דִי יִסְתָּאֵב וְלָא יַדֵי עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מִגוֹ קְהָלָא אֲרֵי יָת מַקְדְשָׁא דַיְיָ סָאֵיב מֵי אַדָיוּתָא לָא אִזְדְרִיקוּ עֲלוֹהִי מְסָאָבּ הוּא:
@706 וּתְהֵי לְהוֹן לִקְיַם עֲלָם וּדְיַדֵי מֵי אַדָיוּתָא יְצַבַּע לְבוּשׁוֹהִי וּדְיִקְרַב בְּמֵי אַדָיוּתָא יְהֵי מְסָאָב עַד רַמְשָׁא:
@707 וְכָל דִי יִקְרַב בֵּיהּ מְסָאָבָא יְהֵי מְסָאָב וֶאֱנַשׁ דְיִקְרַב בֵּיהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@708 וַאֲתוֹ בְנֵי יִשְׂרָאֵל כָּל כְּנִשְׁתָא לְמַדְבְּרָא דְצִין בְּיַרְחָא קַדְמָאָה וִיתֵיב עַמָא בִּרְקָם וּמִיתַת תַּמָן מִרְיָם וְאִתְקְבָרַת תַּמָן:
@709 וְלָא הֲוָה מַיָא לִכְנִשְׁתָּא וְאִתְכַּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן:
@710 וּנְצָא עַמָא עִם משֶׁה וַאֲמָרוּ לְמֵימָר וּלְוַי דְמִתְנָא בְּמוֹתָא דַאֲחָנָא קֳדָם יְיָ:
@711 וּלְמָא אַעֶלְתּוּן יָת קְהָלָא דַיְיָ לְמַדְבְּרָא הָדֵין לִמְמַת תַּמָן אֲנַחְנָא וּבְעִירָנָא:
@712 וּלְמָא אַסֶקְתּוּנָא מִמִצְרַיִם לְאַיְתָאָה יָתָנָא לְאַתְּרָא בִישָׁא הָדֵין לָא אֲתַר כְּשַׁר לְבֵית זְרַע וְאַף לָא תְּאֵנִין וְגוּפְנִין וְרִמוֹנִין וּמַיָא לֵית לְמִשְׁתֵּי:
@713 וְעַאל משֶׁה וְאַהֲרֹן מִן קֳדָם קְהָלָא לִתְרַע מַשְׁכַּן זִמְנָא וּנְפָלוּ עַל אַפֵּיהוֹן וְאִתְגְלֵי יְקָרָא דַיְיָ לְהוֹן:
@714 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@715 סַב יָת חוּטְרָא וְאַכְנֵשׁ יָת כְּנִשְׁתָּא אַתְּ וְאַהֲרֹן אָחוּךְ וּתְמַלְלוּן עִם כֵּיפָא לְעֵינֵיהוֹן וְיִתֵּן מוֹהִי וְתַפֵּיק לְהוֹן מַיָא מִן כֵּיפָא וְתַשְׁקֵי יָת כְּנִשְׁתָּא וְיָת בְּעִירְהוֹן:
@716 וּנְסִיב משֶׁה יָת חוּטְרָא מִן קֳדָם יְיָ כְּמָא דִי פַקְדֵיהּ:
@717 וְאַכְנִישׁוּ משֶׁה וְאַהֲרֹן יָת קְהָלָא לְקֳדָם כֵּיפָא וַאֲמַר לְהוֹן שְׁמָעוּ כְעַן סַרְבָנַיָא הֲמִן כֵּיפָא הָדֵין נַפֵּיק לְכוֹן מַיָא:
@718 וַאֲרֵם משֶׁה יָת יְדֵיהּ וּמְחָא יָת כֵּיפָא בְּחוּטְּרֵיהּ תְּרֵין זִמְנִין וּנְפָקוּ מַיָא סַגִיאֵי וּשְׁתִיאַת כְּנִשְׁתָּא וּבְעִירְהוֹן:
@719 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן חֲלַף דִי לָא הֵימַנְתּוּן בְּמֵימְרִי לְקַדָשׁוּתִי לְעֵינֵי בְּנֵי יִשְׂרָאֵל בְּכֵן לָא תֵעֲלוּן יָת קְהָלָא הָדֵין לְאַרְעָא דִי יְהָבִית לְהוֹן:
@720 אִינוּן מֵי מַצוּתָא דִנְצוֹ בְנֵי יִשְׂרָאֵל קֳדָם יְיָ וְאִתְקַדַשׁ בְּהוֹן:
@721 וּשְׁלַח משֶׁה אִזְגַדִין מֵרְקָם לְוַת מַלְכָּא דֶאֱדוֹם כִּדְנַן אֲמַר אָחוּךְ יִשְׂרָאֵל אַתְּ יְדַעְתְּ יָת כָּל עָקְתָא דִי אַשְׁכַּחְתָּנָא:
@722 וּנְחָתוּ אֲבָהָתָנָא לְמִצְרַיִם וִיתֵיבְנָא בְמִצְרַיִם יוֹמִין סַגִיאִין וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְלַאֲבָהָתָנָא:
@723 וְצַלֵינָא קֳדָם יְיָ וְקַבִּיל צְלוֹתָנָא וּשְׁלַח מַלְאָכָא וְאַפְקָנָא מִמִצְרָיִם וְהָא אֲנַחְנָא בִּרְקַם קַרְתָּא דְבִסְטַר תְּחוּמָךְ:
@724 נְעִיבַּר כְּעַן בְּאַרְעָךְ לָא נְעִיבֵּר בַּחֲקַל וּבִכְרָם וְלָא נִשְׁתֵּי מֵי גוֹב בְּאֹרַח מַלְכָּא נֵיזֵיל לָא נִסְטֵּי לְיַמִינָא וְלִשְׂמָאלָא עַד דִנְעִיבַּר תְּחוּמָךְ:
@725 וַאֲמַר לֵיהּ אֱדוֹמָאָה לָא תְעִבַּר בִּתְחוּמִי דִלְמָא בִדְקָטְלִין בְּחַרְבָּא אֶפּוֹק לָקָדָמוּתָךְ:
@726 וַאֲמָרוּ לֵיהּ בְּנֵי יִשְׂרָאֵל בְּאֹרַח כְּבִישָׁא נִסַק וְאִם מֵימַךְ נִשְׁתֵּי אֲנָא וּבְעִירַי וְאֶתֵּן דְמֵיהוֹן לְחוֹד לֵית פִּתְגַם דְבִישׁ בְּרַגְלַי אֵעִיבַּר:
@727 וַאֲמַר לָא תְעִבָּר וּנְפַק אֱדוֹמָאָה לָקֳדָמוּתֵיהּ בְּחֵיל רַב וּבִידָא תַקִיפָא:
@728 וְסָרֵיב אֱדוֹמָאָה לְמִשְׁבַּק יָת יִשְׂרָאֵל לְמֶעֱבַר בִּתְחוּמֵיהּ וּסְטָּא יִשְׂרָאֵל מִלְוָתֵיהּ:
@729 וּנְטָלוּ מֵרְקָם וַאֲתוֹ בְנֵי יִשְׂרָאֵל כָּל כְּנִשְׁתָּא לְהֹר טוּרָא:
@730 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן בְּהוֹר טוּרָא עַל תְּחוּם אַרְעָא דֶאֱדוֹם לְמֵימָר:
@731 יִתְכְּנֵשׁ אַהֲרֹן לְעַמֵיהּ אֲרֵי לָא יֵעוֹל לְאַרְעָא דִי יְהָבִית לִבְנֵי יִשְׂרָאֵל עַל דִי סְרֵיבְתּוּן עַל מֵימְרִי לְמֵי מַצוּתָא:
@732 דְבַר יָת אַהֲרֹן וְיָת אֶלְעָזָר בְּרֵיהּ וְאַסֵיק יָתְהוֹן לְהֹר טּוּרָא:
@733 וְאַשְׁלַח יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְתַלְבֵּישִׁנוּן יָת אֶלְעָזָר בְּרֵיהּ וְאַהֲרֹן יִתְכְּנֵישׁ וִימוּת תַּמָן:
@734 וַעֲבַד משֶׁה כְּמָא דִי פַקִיד יְיָ וּסְלִיקוּ לְהֹר טוּרָא לְעֵינֵי כָּל כְּנִשְׁתָּא:
@735 וְאַשְׁלַח משֶׁה יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְאַלְבִּישׁ יָתְהוֹן יָת אֶלְעָזָר בְּרֵיהּ וּמִית אַהֲרֹן תַּמָן בְּרֵישׁ טוּרָא וּנְחַת משֶׁה וְאֶלְעָזָר מִן טוּרָא:
@736 וַחֲזוֹ כָּל כְּנִשְׁתָּא אֲרֵי מִית אַהֲרֹן וּבְכוֹ יָת אַהֲרֹן תְּלָתִין יוֹמִין כֹּל בֵּית יִשְׂרָאֵל:
@737 וּשְׁמַע כְּנַעֲנָאָה מַלְכָּא דַעֲרָד יָתֵיב דָרוֹמָא אֲרֵי אֲתָא יִשְׂרָאֵל אֹרַח מְאַלְלַיָא וְאַגַח קְרָבָא בְּיִשְׂרָאֵל וּשְׁבָא מִנֵיהּ שִׁבְיָא:
@738 וְקַיֵים יִשְׂרָאֵל קְיָים קֳדָם יְיָ וַאֲמַר אִם מִמְסַר תִּמְסַר יָת עַמָא הָדֵין בִּידִי וַאֲגַמַר יָת קִרְוֵיהוֹן:
@739 וְקַבֵּיל יְיָ צְלוֹתֵיהּ דְיִשְׂרָאֵל וּמְסַר יָת כְּנַעֲנָאָה וְגַמַר יָתְהוֹן וְיָת קִרְוֵיהוֹן וּקְרָא שְׁמָא דְאַתְרָא חָרְמָה:
@740 וּנְטָלוּ מֵהֹר טוּרָא אֹרַח יַמָא דְסוּף לְאַקָפָא יָת אַרְעָא דֶאֱדוֹם וַעֲקַת נַפְשָׁא דְעַמָא בְּאוֹרְחָא:
@741 וְאִתְרַעַם עַמָא בְּמֵימְרָא דַיְיָ וְעִם משֶׁה נְצוֹ לְמָא אַסֵקְתּוּנָא מִמִצְרַיִם לִמְמָת בְּמַדְבְּרָא אֲרֵי לֵית לַחְמָא וְלֵית מַיָא וְנַפְשָׁנָא עָקַת בְּמַנָא הָדֵין דְמֵיכְלֵיהּ קָלֵיל:
@742 וְגָרֵי יְיָ בְּעַמָא יָת חִיוַן קָלָן וּנְכִיתוּ יָת עַמָא וּמִית עַם סַגִי מִיִשְׂרָאֵל:
@743 וַאֲתָא עַמָא לְמשֶׁה וַאֲמָרוּ חַבְנָא אֲרֵי אִתְרַעַמְנָא קֳדָם יְיָ וְעִמָךְ נְצֵינָא צַלִי קֲדָם יְיָ וְיַעֲדִי מִנָנָא יָת חִוְיָא וְצַלִי משֶׁה עַל עַמָא:
@744 וַאֲמַר יְיָ לְמשֶׁה עֲבֵיד לָךְ קַלְיָא וְשַׁוִי יָתֵיהּ עַל אָת וִיהֵי כָּל דְיִתְנְכִית וְיֶחֱזֵי יָתֵהּ וְיִתְקַיָם:
@745 וַעֲבַד משֶׁה חִוְיָא דִנְחָשָׁא וְשַׁוְיֵהּ עַל אָת וַהֲוָה כַּד נְכֵית חִוְיָא יָת גַבְרָא וּמִסְתַּכֵּל לְחִוְיָא דִנְחָשָׁא וּמִתְקַיָם:
@746 וּנְטָלוּ בְּנֵי יִשְׂרָאֵל וּשְׁרוֹ בְּאוֹבוֹת:
@747 וּנְטָלוּ מֵאוֹבוֹת וּשְׁרוֹ בִמְגִיזַת עֲבָרָאֵי בְּמַדְבְּרָא דִי עַל אַפֵּי מוֹאָב מִמַדְנַח שִׁמְשָׁא:
@748 מִתַּמָן נְטָלוּ וּשְׁרוֹ בְּנַחֲלָא דְזָרֶד:
@749 מִתַּמָן נְטָלוּ וּשְׁרוֹ מֵעִבְרָא דְאַרְנוֹן דִי בְּמַדְבְּרָא דְנָפֵיק מִתְּחוּם אֱמוֹרָאָה אֲרֵי אַרְנוֹן תְּחוּם מוֹאָב בֵּין מוֹאָב וּבֵין אֱמוֹרָאָה:
@750 עַל כֵּן יִתְאַמַר בְּסִפְרָא קְרָבִין דַעֲבַד יְיָ עַל יַמָא דְסוּף וּגְבוּרָן דְעַל נַחֲלֵי אַרְנוֹן:
@751 וְשָׁפוּךְ נַחֲלַיָא דְמִדַבְּרִין לְקָבֵל לְחָיַת וּמִסְתְּמִיךְ לִתְחוּם מוֹאָב:
@752 וּמִתַּמָן אִתְיְהִיבַת לְהוֹן בֵּירָא הִיא בֵירָא דִי אֲמַר יְיָ לְמשֶׁה כְּנוֹשׁ יָת עַמָא וְאֶתֵּן לְהוֹן מַיָא:
@753 בְּכֵן שַׁבַּח יִשְׂרָאֵל יָת תּוּשְׁבַּחְתָּא הָדָא סַקִי בֵירָא שַׁבָּחוּ לָהּ:
@754 בֵּירָא דְחָפְרוּהָ רַבְרְבַיָא כְּרוּהָ רֵישֵׁי עַמָא סַפְרַיָא בְּחוּטְרֵיהוֹן וּמִמַדְבְּרָא אִתְיְהִיבַת לְהוֹן:
@755 וּמִדְאִתְיְהִיבַת לְהוֹן נַחֲתָא עִמְהוֹן לְנַחֲלַיָא וּמִנַחֲלַיָא סָלְקָא עִמְהוֹן לְרָמָתָא:
@756 וּמֵרָמָתָא לְחֵילַיָא דִי בְּחַקְלֵי מוֹאָב רֵישׁ רָמָתָא וּמִסְתַּכְיָא עַל אַפֵּי בֵּית יְשִׁימוֹן:
@757 וּשְׁלַח יִשְׂרָאֵל אִזְגַדִין לְוָת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה לְמֵימָר:
@758 אֵעִיבַּר בְּאַרְעָךְ לָא נִסְטֵי בַּחֲקַל וּבִכְרַם לָא נִשְׁתֵּי מֵי גוֹב בְּאֹרַח מַלְכָּא נֵיזֵיל עַד דִי נְעִבַּר תְּחוּמָךְ:
@759 וְלָא שְׁבַק סִיחוֹן יָת יִשְׂרָאֵל לְמֶעְבַּר בִּתְחוּמֵיהּ וּכְנַשׁ סִיחוֹן יָת כָּל עַמֵיהּ וּנְפַק לָקֳדָמוּת יִשְׂרָאֵל לְמַדְבְּרָא וַאֲתָא לְיָהַץ וְאַגִיחַ קְרָבָא בְּיִשְׂרָאֵל:
@760 וּמְחָהִי יִשְׂרָאֵל לְפִתְגַם דְחָרֶב וִירֵת יָת אַרְעֵיהּ מֵאַרְנוֹנָא עַד יוּבְקָא עַד בְּנֵי עַמוֹן אֲרֵי תַקִיף תְּחוּמָא דִבְנֵי עַמוֹן:
@761 וּכְבַשׁ יִשְׂרָאֵל יָת כָּל קִרְוַיָא הָאִלֵין וִיתֵיב יִשְׂרָאֵל בְּכָל קִרְוֵי אֱמוֹרָאָה בְּחֶשְׁבּוֹן וּבְכָל כַּפְרָנָהָא:
@762 אֲרֵי חֶשְׁבּוֹן קַרְתָּא דְסִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה הִיא וְהוּא אַגַח קְרָבָא בְּמַלְכָּא דְמוֹאָב קַדְמָאָה וּנְסֵיב יָת כָּל אַרְעֵיהּ מִידֵיהּ עַד אַרְנוֹן:
@763 עַל כֵּן יֵימְרוּן מְתָלַיָא עוּלוּ לְחֶשְׁבּוֹן תִּתְבְּנֵי וְתִשְׁתַּכְלַל קַרְתָּא דְסִיחוֹן:
@764 אֲרֵי קִידוּם תַּקִיף כְּאֶשָׁא נְפַק מֵחֶשְׁבּוֹן עָבְדֵי קְרָבָא כְּשַׁלְהוֹבִיתָא מִקַרְתָּא דְסִיחוֹן קַטִילוּ עַמָא דִשְׁרוֹ בִּלְחָיַת מוֹאָב כּוּמְרַיָא דְפַלְחִין בֵּית דַחֲלָא רָמָתָא דְאַרְנוֹן:
@765 וַי לְכוֹן מוֹאֲבָאֵי אֲבַדְתּוּן עַמָא דְפָלְחִין לִכְמוֹשׁ מְסַר בְּנוֹהִי צִירִין וּבְנָתֵיהּ בְּשִׁבְיָא לְמַלְכָּא דֶאֱמוֹרָאָה סִיחוֹן:
@766 וּמַלְכוּ פְסָקַת מֵחֶשְׁבּוֹן עֲדָא שׁוּלְטַן מִדִיבוֹן וְצֲדִיאוּ עַד נֹפַח דִסְמִיךְ עַד מֵידְבָא:
@767 וִיתֵב יִשְׂרָאֵל בַּאֲרַע אֱמוֹרָאָה:
@768 וּשְׁלַח משֶׁה לְאַלָלָא יָת יַעְזֵר וּכְבָשׁוּ כַּפְרָנָהָא וְתָרִיךְ יָת אֱמוֹרָאָהּ דִי תַמָן:
@769 וְאִתְפְּנִיאוּ וּסְלִיקוּ לְאֹרַח מַתְנָן וּנְפַק עוֹג מַלְכָּא דְמַתְנָן לְקֳדָמוּתְהוֹן הוּא וְכָל עַמֵּיהּ לְאַגָחָא קְרָבָא לְאֶדְרֶעִי:
@770 וַאֲמַר יְיָ לְמשֶׁה לָא תִדְחַל מִנֵיהּ אֲרֵי בִידָךְ מְסָרִית יָתֵיהּ וְיָת כָּל עַמֵיהּ וְיָת אַרְעֵיהּ וְתַעֲבֵד לֵיהּ כְּמָא דִי עֲבַדְתְּ לְסִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן:
@771 וּמְחוֹ יָתֵיהּ וְיָת בְּנוֹהִי וְיָת כָל עַמֵּיהּ עַד דְלָא אִשְׁתָּאַר לֵיהּ מְשֵׁיזִיב וִירִיתוּ יָת אַרְעֵיהּ:
@772 וּנְטָלוּ בְּנֵי יִשְׂרָאֵל וּשְׁרוֹ בְּמֵישְׁרַיָא דְמוֹאָב מֵעִבְרָא לְיַרְדְנָא דִירֵחוֹ: פפפ:
@773 וַחֲזָא בָּלָק בַּר צִפּוֹר יָת כָּל דִי עֲבַד יִשְׂרָאֵל לֶאֱמוֹרָאֵי:
@774 וּדְחִיל מוֹאֲבָאָה מִן קֳדָם עַמָא לַחֲדָא אֲרֵי סַגִי הוּא וַעֲקַת לְמוֹאֲבָאָה מִן קֳדָם בְּנֵי יִשְׂרָאֵל:
@775 וַאֲמַר מוֹאָב לְסָבֵי מִדְיָן כְּעַן יְשֵׁיצוּן קְהָלָא יָת כָּל סַחֲרָנָנָא כְּמָא דִמְלַחֵיךְ תּוֹרָא יָת יְרוֹקָא דְחַקְלָא וּבָלָק בַּר צִפּוֹר מַלְכָּא לְמוֹאָב בְּעִידָנָה הַהִיא:
@776 וּשְׁלַח אִזְגַדִין לְוָת בִּלְעָם בַּר בְּעוֹר לִפְּתוֹר אֲרָם דְעַל פְּרָת אֲרַע בְּנֵי עַמֵיהּ לְמִקְרֵי לֵיהּ לְמֵימָר הָא עַמָא נְפַק מִמִצְרַיִם הָא חֲפָא יַת עֵין שִׁמְשָׁא דְאַרְעָא וְהוּא שָׁרֵי מִלְקִבְלִי:
@777 וּכְעַן אִיתָא כְּעַן לוֹט לִי יָת עַמָא הָדֵין אֲרֵי תַקִיף הוּא מִנִי מָאִים אֵכוּל לְאַגָחָא בֵּיהּ קְרָב וַאֲתָרֵכִינֵיהּ מִן אַרְעָא אֲרֵי יְדַעֲנָא יָת דִי תְבָרַךְ מְבָרָךְ וְדִי תְלוֹט לִיט:
@778 וַאֲזָלוּ סָבֵי מוֹאָב וְסָבֵי מִדְיָן וְקִסְמַיָא בִּידֵיהוֹן וַאֲתוֹ לְוַת בִּלְעָם וּמַלִילוּ עִמֵיהּ פִּתְגָמֵי בָּלָק:
@779 וַאֲמַר לְהוֹן בִּיתוּ הָכָא בְּלֵילְיָא וְאָתֵב יַתְכוֹן פִּתְגָמָא כְּמָא דִי יְמַלֵיל יְיָ עִמִי וְאוֹרִיכוּ רַבְרְבֵי מוֹאָב עִם בִּלְעָם:
@780 וַאֲתָא מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר מָן גוּבְרַיָא הָאִלֵין דְעִמָךְ:
@781 וַאֲמַר בִּלְעָם קֳדָם יְיָ בָּלָק בַּר צִפּוֹר מַלְכָּא דְמוֹאָב שְׁלַח לְוָתִי:
@782 הָא עַמָא דִי נְפַק מִמִצְרַיִם וַחֲפָא יָת עֵין שִׁמְשָׁא דְאַרְעָא כְּעַן אִיתָא לוֹט לִי יָתֵיהּ מָאִים אֵיכוּל לְאַגָחָא בֵּיהּ קְרָב וְאֲתָרֵיכִינֵיהּ:
@783 וַאֲמַר יְיָ לְבִלְעָם לָא תֵיזִיל עִמְהוֹן לָא תְלוֹט יָת עַמָא אֲרֵי בְרִיךְ הוּא:
@784 וְקָם בִּלְעָם בְּצַפְרָא וַאֲמַר לְרַבְרְבֵי בָלָק אִיזִילוּ לְאַרְעֲכוֹן אֲרֵי לֵית רַעֲוָא קֳדָם יְיָ לְמִשְׁבְּקִי לְמֵיזַל עִמְכוֹן:
@785 וְקָמוּ רַבְרְבֵי מוֹאָב וַאֲתוֹ לְוָת בָּלָק וַאֲמָרוּ סָרֵיב בִּלְעָם לְמֵיתֵי עִמָנָא:
@786 וְאוֹסִיף עוֹד בָּלָק לְמִשְׁלַח רַבְרְבִין סַגִיאִין:ויַקִירִין מֵאִלֵין:
@787 וַאֲתוֹ לְוָת בִּלְעָם וַאֲמָרוּ לֵיהּ כִּדְנַן אֲמַר בָּלָק בַּר צִפּוֹר לָא כְעַן תִּתְמְנַע מִלְמֵיתֵי לְוָתִי:
@788 אֲרֵי יְקָרָא אֲיַקְרִינָךְ לַחֲדָא וְכֹל דִי תֵימַר לִי אַעְבֵּד וְאִיתָא כְעַן לוֹט לִי יַת עַמָא הָדֵין:
@789 וַאֲתֵיב בִּלְעָם וַאֲמַר לְעַבְדֵי בָלָק אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ אֱלָהָי לְמֶעְבַּד זְעֵרְתָּא אוֹ רַבְּתָא:
@790 וּכְעַן אוֹרִיכוּ כְעַן הָכָא אַף אַתּוּן בְּלֵילְיָא וְאִדַע מָה יוֹסֵף יְיָ לְמַלָלָא עִמִי:
@791 וַאֲתָּא מֵימַר מִן קֳדָם יְיָ לְבִלְעָם בְּלֵילְיָא וַאֲמַר לֵיהּ אִם לְמִקְרֵי לָךְ אֲתוֹ גֻבְרַיָא קוּם אִיזֵיל עִמְהוֹן וּבְרַם יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תַּעְבֵיד:
@792 וְקָם בִּלְעָם בְּצַפְרָא וְזָרֵיז יַת אֲתָנֵיהּ וַאֲזַל עִם רַבְרְבֵי מוֹאָב:
@793 וּתְקֵיף רָגְזָא דַיְיָ אֲרֵי אָזֵיל הוּא וְאִתְעַתַּד מַלְאָכָא דַיְיָ בְּאוֹרְחָא לְשָׂטָן לֵהּ וְהוּא רָכִיב עַל אַתָּנֵיהּ וּתְרֵין עוּלֵימוֹהִי עִמֵהּ:
@794 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִּידֵיהּ וּסְטַת אֲתָּנָא מִן אוֹרְחָא וַאֲזָלַת בְּחַקְלָא וּמְחָא בִּלְעָם יַת אֲתָּנָא לְאַסְטָיוּתַהּ לְאָרְחָא:
@795 וְקָם מַלְאָכָא דַיְיָ בִּשְׁבִיל כַּרְמַיָא אַתְרָא דְגָדֵירָא מִכָּא וְגָדֵירָא מִכָּא:
@796 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וְאִדְחֵיקַת לְכָתְלָא וּדְחֵיקַת יַת רִגְלָא דְבִלְעָם לְכָתְלָא וְאוֹסִיף לְמִמְחַהּ:
@797 וְאוֹסֵף מַלְאָכָא דַיְיָ לְמֶעְבָּר וְקָם בַּאֲתַר עָק דִי לֵית אֹרַח לְמִסְטֵי לְיַמִינָא וְלִשְׂמָאלָא:
@798 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וּרְבָעַת תְּחוֹת בִּלְעָם וּתְקֵיף רוּגְזָא דְבִלְעָם וּמְחָא יַת אֲתָּנָא בְּחֻטְרָא:
@799 וּפְתַח יְיָ יַת פּוּמָא דַאֲתָּנָא וַאֲמָרַת לְבִּלְעָם מָה עֲבָדִית לָךְ אֲרֵי מְחִיתַנִי דְנַן תְּלַת זִמְנִין:
@800 וַאֲמַר בִּלְעָם לַאֲתָּנָא אֲרֵי חַיִיכְתְּ בִּי אִלוּפוֹן אִית חַרְבָּא בִּידִי אֲרֵי כְעָן קְטַלְתִּיךְ:
@801 וַאֲמָרַת אֲתָּנָא לְבִלְעָם הֲלָא אֲנָא אֲתָּנָךְ דְרָכַבְתְּ עֲלַי מִדְאִיתָךְ עַד יוֹמָא הָדֵין הֲמֵילַף אַלִפְנָא לְמֶעֱבַּד לָךְ כְּדֵין וַאֲמַר לָא:
@802 וּגְלָא יְיָ יַת עֵינֵי בִלְעָם וַחֲזָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִידֵיהּ וּכְרַע וּסְגִיד לְאַפּוֹהִי:
@803 וַאֲמַר לֵיהּ מַלְאָכָא דַיְיָ עַל מָה מָחִיתָא יַת אֲתָּנָךְ דְנַן תְּלַת זִמְנִין הָא אֲנָא נְפָקִית לְמִשְׂטַן אֲרֵי גְלֵי קֳדָמַי דְאַתְּ רָעֵי לְמֵיזַל בְּאוֹרְחָא לְקִבְּלִי:
@804 וַחֲזַתְנִי אֲתָּנָא וּסְטַת מִן קֳדָמַי דְנַן תְּלַת זִמְנִין אִילוּפוֹן לָא סְטַּת מִן קֳדָמַי אֲרֵי כְעַן אַף יָתָךְ קְטָלִית וְיָתַהּ קַיֵימִית:
@805 וַאֲמַר בִּלְעָם לְמַלְאָכָה דַיְיָ חָבִית אֲרֵי לָא יְדָעִית אֲרֵי אַתְּ מְעַתֵּד לָקֳדָמוּתִי בְּאָרְחָא וּכְעַן אִם בִּישׁ בְּעֵינָךְ אֵיתוּב לִי:
@806 וַאֲמַר מַלְאָכָא דַיְיָ לְבִלְעָם אִיזֵיל עִם גוּבְרַיָא וּלְחוֹד יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תְּמַלֵיל וַאֲזַל בִּלְעָם עִם רַבְרְבֵי בָּלָק:
@807 וּשְׁמַע בָּלָק אֲרֵי אָתָא בִלְעָם וּנְפַק לָקֳדָמוּתֵה לְקַרְתָּא דְמוֹאָב דִי עַל תְּחוּם אַרְנוֹן דִי בִּסְטַר תְּחוּמָא:
@808 וַאֲמַר בָּלָק לְבִלְעָם הֲלָא מִשְׁלַח שַׁלְחִית לְוָתָךְ לְמִקְרֵי לָךְ לְמָא לָא אֲתֵיתָא לְוָתִי הַבְקוּשְׁטָא הֲוֵיתָא אָמַר לֵית אֲנָא יָכִיל לְיַקְרוּתָךְ:
@809 וַאֲמַר בִּלְעָם לְבָלָק הָא אֲתֵיתִי לְוָתָךְ כְּעַן הֲמֵיכַל יְכִלְנָא לְמַלָלָא מִדַעַם פִּתְגָמָא דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֲמַלֵיל:
@810 וַאֲזַל בִּלְעָם עִם בָּלָק וַאֲתוֹ לְקִרְיַת מְחוֹזוֹהִי:
@811 וּנְכֵיס בָּלָק תּוֹרִין וְעָאן וּשְׁלַח לְבִלְעָם וּלְרַבְרְבַיָא דִי עִמֵיהּ:
@812 וַהֲוָה בְּצַפְרָא וּדְבַר בָּלָק יַת בִּלְעָם וְאַסְקֵיהּ לְרָמַת דַחַלְתֵּיהּ וַחֲזָא מִתַּמָן קְצַת מִן עַמָא:
@813 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@814 וַעֲבַד בָּלָק כְּמָא דִי מַלֵיל בִּלְעָם וְאַסֵיק בָּלָק וּבִלְעָם תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@815 וַאֲמַר בִּלְעָם לְבָלָק אִתְעַתֵּד עַל עֲלָתָךְ וְאֵיהַךְ מָאִים יְעָרַע מֵימַר מִן קֳדָם יְיָ לָקֳדָמוּתִי וּפִתְגָמָא דְיַחֲזִנַנִי וְאֵחַוֵי לָךְ וַאֲזַל יְחִידִי:
@816 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר לֵיהּ יַת שַׁבְעָא מַדְבְּחִין סְדָרִית וְאַסֵקִית תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@817 וְשַׁוִי יְיָ פִּתְגָמָא בְּפוּמָא דְבִלְעָם וַאֲמַר תּוּב לְוַת בָּלָק וּכְדֵין תְּמַלֵיל:
@818 וְתַב לְוָתֵיהּ וְהָא מְעַתֵּד עַל עֲלָתֵיהּ הוּא וְכָל רַבְרְבֵי מוֹאָב:
@819 וּנְטַל מַתְלֵיהּ וַאֲמַר מִן אֲרָם דַבְּרַנִי בָלָק מַלְכָּא דְמוֹאָב מִטוּרֵי מַדִנְחָא אִיתָא לוֹטּ לִי יַעֲקֹב וְאִיתָא תָּרֵיךְ לִי יִשְׂרָאֵל:
@820 מָה אֲלוֹטֵיהּ דְלָא לַטְיֵהּ אֵל וּמָה אֲתָרְכֵיהּ דְלָא תָרְכֵיהּ יְיָ:
@821 אֲרֵי מֵרֵישׁ טוּרַיָא חֲזִיתֵיהּ וּמֵרָמָתָא סְכִיתֵיהּ הָא עַמָא בִּלְחוֹדֵיהוֹן עֲתִידִין דְיַחְסְנוּן עַלְמָא וּבְעַמְמַיָא לָא יִתְדְנוּן גְמִירָא:
@822 מָן יֵיכוֹל לְמִמְנֵי דַעַדְקַיָא דְבֵית יַעֲקֹב דְאָמִיר עֲלֵיהוֹן יִסְגוּן כְּעַפְרָא דְאַרְעָא אוֹ חֲדָא מֵאַרְבַּע מַשִׁרְיָתָא דְיִשְׂרָאֵל תְּמוּת נַפְשִׁי מוֹתָא דְקַשִׁיטוֹהִי וּתְהֵי סוֹפִי כְּוַתְהוֹן:
@823 וַאֲמַר בָּלָק לְבִלְעָם מֶה עֲבַדְתָּא לִי לְמֵילַט סַנְאַי דְבַרְתִּיךְ וְהָא בְּרָכָא מְבָרְכַת לְהוֹן:
@824 וַאֲתֵיב וַאֲמַר הֲלָא יָת דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֶטַר לְמַלָלָא:
@825 וַאֲמַר לֵיהּ בָּלָק אִיתָא כְעַן עִמִי לַאֲתַר אוֹחֲרָן דְתֶחֱזִנֵיהּ מִתַּמָן לְחוֹד קְצָתֵיהּ תֶּחֱזֵי וְכוּלֵיהּ לָא תֶחֱזֵי וּתְלוּטֵיהּ לִי מִתַּמָן:
@826 וְדַבְּרֵיהּ לַחֲקַל סְכוּתָא לְרֵישׁ רָמָתָא וּבְנָא שַׁבְעָא מַדְבְּחִין וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@827 וַאֲמַר לְבָלָק אִתְעַתֵּד הָכָא עַל עֲלָתָךְ וַאֲנָא אִתְמְטֵי עַד כָּא:
@828 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְבִלְעָם וְשַׁוִי פִתְגָמָא בְּפוּמֵיהּ וַאֲמַר תּוּב לְוָת בָּלָק וּכְדֵין תְּמַלֵיל:
@829 וַאֲתָא לְוָתֵיהּ וְהוּא מְעַתַּד עַל עֲלָתֵיהּ וְרַבְרְבֵי מוֹאָב עִמֵיהּ וַאֲמַר לֵיהּ בָּלָק מָה מַלִיל יְיָ:
@830 וּנְטַל מַתְלֵיהּ וַאֲמַר קוּם בָּלָק וּשְׁמַע אָצִית לְמֵימְרִי בַּר צִפֹּר:
@831 לָא כְמִלֵי בְּנֵי אֱנָשָׁא מֵימַר אֱלָהָא בְּנֵי אֱנָשָׁא אָמְרִין וּמְכַדְבִין וְאַף לָא כְעוֹבָדֵי בְּנֵי בִּשְׂרָא דְאִינוּן גָזְרִין לְמֶעְבַּד וְתַיְבִין וּמִתְמַלְכִין דְהוּא אָמַר וְעָבֵיד וְכָל מֵימְרֵהּ מִתְקַיָם:
@832 הָא בִּרְכָן קַבֵּילִית וַאֲבָרֵכִינֵיהּ לְיִשְׂרָאֵל וְלָא אָתֵב בִּרְכְּתִי מִינֵיה:
@833 אִסְתַּכָּלִית לֵית פָּלְחֵי גִלוּלִין בִּדְבֵית יַעֲקֹב וְאַף לָא עָבְדֵי לֵיאוּת שְׁקַר בְּיִשְׂרָאֵל מֵימְרָא דַיְיָ אֱלָהָהוֹן בְּסַעְדְהוֹן וּשְׁכִינַת מַלְכְּהוֹן בֵּינֵיהוֹן:
@834 אֱלָהָא דְאַפֵּקִנוּן מִמִצְרָיִם תּוּקְפָא וְרוּמָא דִילֵיהּ:
@835 אֲרֵי לָא נַחֲשַׁיָא צָבָן דְיִיטַב לִדְבֵית יַעֲקֹב וְאַף לָא קְסָמַיָא רְעַן בִּרְבוּת בֵּית יִשְׂרָאֵל כְּעִדַן יִתְאַמַר לְיַעֲקֹב וּלְיִשְׂרָאֵל מָה עֲבַד אֱלָהָא:
@836 הָא עַמָא כְּלֵיתָא שָׁרֵי וּכְאַרְיָא יִתְנַטֵל לָא יִשְׁרֵי בְאַרְעֵיהּ עַד דְיִקְטוֹל קְטוֹל וְנִכְסֵי עֲמְמַיָא יֵירָת:
@837 וַאֲמַר בָּלָק לְבִלְעָם אַף מֵילַט לָא תְלוּטִּינוּן אַף בְּרָכָא לָא תְבָ רֵ כִ י נוּ ן:
@838 וַאֲתֵיב בִּלְעָם וַאֲמַר לְבָלָק הֲלָא מַלֵילִית עִמָךְ לְמֵימַר כֹּל דִי יְמַלֵל יְיָ יָתֵיהּ אַעֲבֵיד:
@839 וַאֲמַר בָּלָק לְבִלְעָם אִיתָא כְּעַן אֲדַבְּרִינָךְ לַאֲתַר אָחֳרָן מָאִים יְהֵי רַעֲוָא מִן קֳדָם יְיָ וּתְלוּטֵיהּ לִי מִתַּמָן:
@840 וּדְבַר בָּלָק יַת בִּלְעָם רֵישׁ רָמָתָא דְמִסְתַּכְּיָא עַל אַפֵּי בֵּית יְשִׁימוֹן:
@841 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@842 וַעֲבַד בָּלָק כְּמָא דִי אֲמַר בִּלְעָם וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@843 וַחֲזָא בִלְעָם אֲרֵי תַקִין קֳדָם יְיָ לְבָרָכָא יַת יִשְׂרָאֵל וְלָא הַלַךְ כִּזְמַן בִּזְמַן אֱלָהֵין לָקֳדָמוּת נְחָשַׁיָא וְשַׁוִי לָקָבֵיל עֶגְלָא דַעֲבָדוּ יִשְׂרָאֵל בְּמַדְבְּרָא אַפּוֹהִי:
@844 וּזְקֵף בִּלְעָם יָת עֵינוֹהִי וַחֲזָא יָת יִשְׂרָאֵל שָׁרָן לְשִׁבְטוֹהִי וּשְׁרַת עֲלוֹהִי רוּחַ נְבוּאָה מִן קֳדָם יְיָ:
@845 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@846 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וְחֵזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@847 מָה טָבָא מַשְׁכְּנָךְ יַעֲקֹב בֵּית מֵישְׁרָךְ יִשְׂרָאֵל:
@848 כְּנַחֲלִין דִמְדַבְּרִין כְּגִינַת שַׁקְיָא דְעַל פְּרָת כְּבוּסְמַיָא דִנְצִיב יְיָ כְּאַרְזִין דִנְצִבִין עַל מַיָא:
@849 יִסְגֵי מַלְכָּא דְיִתְרַבָּא מִבְּנוֹהִי וְיִשְׁלוֹט בְּעַמְמִין סַגִיאִין וְיִתְקוֹף מֵאֲגַג מַלְכֵּיהּ וְתִתְנַטֵל מַלְכוּתֵיהּ:
@850 אֱלָהָא דְאַפֵּקִינוּן מִמִצְרַיִם תּוּקְפָא וְרוּמָא דִילֵיהּ יֵיכְלוּן בְּנֵי יִשְׂרָאֵל נִכְסֵי עַמְמַיָא סַנְאֵיהוֹן וּבְבִזַת מַלְכֵּיהוֹן יִתְפַּנְקוּן וְאַרְעֲתְהוֹן יַחְסְנוּן:
@851 יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵתָא לֵית מַלְכוּ דְתִזַעֲזְעִינֵיהּ בְּרִיכָךְ יְהוֹן בְּרִיכִין וְלִיטָךְ יְהוֹן לִיטִין:
@852 וּתְקֵיף רוּגְזָא דְבָלָק בְּבִלְעָם וּשְׁקָפִינוּן לִידוֹהִי וַאֲמַר בָּלָק לְבִלְעָם לְמֵילַט סַנְאַי קְרִיתָךְ וְהָא בָּרָכָא מְבָרְכַת לְהוֹן דְנַן תְּלַת זִמְנִין:
@853 וּכְעַן אִזֵיל לָךְ לְאַתְרָךְ אֲמָרִית יְקָרָא אֲיַקְרִינָךְ וְהָא מְנָעָךְ יְיָ מִן יְקָר:
@854 וַאֲמַר בִּלְעָם לְבָלָּק הֲלָא אַף לְאִזְגַדָךְ דִי שַׁלְחַת לְוָתִי מַלֵילִית לְמֵימָר:
@855 אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ לְמֶעֱבַּד טַבְתָּא אוֹ בִּישְׁתָּא מֵרְעוּתִי דִי יְמַלֵל יְיָ יָתֵיהּ אֲמַלֵיל:
@856 וּכְעַן הָא אֲנָא אָזֵיל לְעַמִי אִיתָא אֲמַלְכִינָךְ מָה דְתַּעְבֵיד וַאֲחַוֵי לָךְ מָא דְיַעֲבֵד עַמָא הָדֵין לְעַמָךְ בְּסוֹף יוֹמַיָא:
@857 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@858 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וִידַע מַדַע מִן קֳדָם עִילָאָה חֵיזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@859 חֲזִיתֵיהּ וְלָא כְעַן סְכִיתֵיהּ וְלָא אִיתוֹהִי קָרִיב כַּד יְקוּם מַלְכָּא מִיַעֲקֹב וְיִתְרַבָּא מְשִׁיחָא מִיִשְׂרָאֵל וְיִקְטּוֹל רַבְרְבֵי מוֹאָב וְיִשְׁלוֹט בְּכָל בְּנֵי אֱנָשָׁא:
@860 וִיהֵי אֱדוֹם יְרוּתָּא וִיהֵי יְרוּתָּא שֵׂעִיר לְבַעֲלֵי דְבָבוֹהִי וְיִשְׂרָאֵל יַצְלַח בְּנִכְסִין:
@861 וְיֵיחוּת חָד מִדְבֵית יַעֲקֹב וְיוֹבִיד מְשֵׁיזִיב מִקִרְיַת עַמְמַיָא:
@862 וַחֲזָא יַת עֲמַלְקָאָה וּנְטַל מַתְלֵיהּ וַאַמַר רֵישׁ קְרָבַיָא דְיִשְׂרָאֵל הֲוָה עֲמַלְקָאָה וְסוֹפֵיהּ לְעָלְמָא יֵיבָד:
@863 וַחֲזָא יַת שַׁלְמָאָה וּנְטַל מַתְלֵיהּ וַאֲמַר תַּקִיף בֵּית מוֹתְבָךְ וְשַׁוֵי בִכְרַךְ תַּקִּיף מְדוֹרָךְ:
@864 אֲרֵי אִם יְהֵי לְשֵׁיצָאָה שַׁלְמָאָה עַד מָה אֲתוּרָאָה יִשְׁבִּינָךְ:
@865 וּנְטַל מַתְלֵיהּ וַאֲמַר וַי לְחַיָיבַיָא דְיֵחוֹן כַּד יַעֲבֵּד אֱלָהָא יָת אִלֵין:
@866 וְסִיעַן יִצְטַרְחַן מֵרוֹמָאֵי וִיעֲנוּן לְאָתוּר וְיִשְׁתַּעְבְּדוּן לְעֵבַר פְּרָת וְאַף אִינוּן לְעָלְמָא יֵיבְדוּן:
@867 וְקָם בִּלְעָם וַאֲזַל וְתָב לְאַתְרֵיהּ וְאַף בָּלָק אֲזַל לְאוֹרְחֵיהּ:
@868 וִיתֵיב יִשְׂרָאֵל בְּשִׁיטִין וּשְׁרֵי עַמָא לְמִטְּעֵי בָּתַר בְּנַת מוֹאָב:
@869 וּקְרָאָן לְעַמָא לְדִבְחֵי טַעֲוַתְהוֹן וַאֲכַל עַמָא וּסְגִידוּ לְטַעֲוַתְהוֹן:
@870 וְאִתְחַבַּר יִשְׂרָאֵל לְבַעֲלָא פְעוֹר וּתְקֵף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל:
@871 וַאֲמַר יְיָ לְמשֶׁה דְבַר יַת כָּל רֵישֵׁי עַמָא וְדוּן וּקְטוֹל דְחַיָב קְטוֹל קֳדָם יְיָ לָקֳבֵל שִׁמְשָׁא וִיתוּב תְּקוֹף רוּגְזָא דַיְיָ מִיִשְׂרָאֵל:
@872 וַאֲמַר משֶׁה לְדַיָנֵי יִשְׂרָאֵל קְטִילוּ גְבַר גַבְרוֹהִי דְאִתְחַבָּרוּ לְבַעֲלָא פְעוֹר:
@873 וְהָא גַבְרָא מִבְּנֵי יִשְׂרָאֵל אֲתָא וְקָרֵב לְוָת אֲחוֹהִי יָת מִדְיָנֵיתָא לְעֵינֵי משֶׁה וּלְעֵינֵי כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְאִינוּן בָּכָן בִּתְרַע מַשְׁכַּן זִמְנָא:
@874 וַחֲזָא פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְקָם מִגוֹ כְנִשְׁתָּא וּנְסֵיב רוֹמְחָא בִידֵיהּ:
@875 וְעַל בָּתַר גַבְרָא בַּר יִשְׂרָאֵל לְקוּבָּתָא וּבְזַע יַת תַּרְוֵיהוֹן יַת גַבְרָא בַּר יִשְׂרָאֵל וְיַת אִתְּתָא לִמְעָהָא וְאִתְכְּלִי מוֹתָנָא מֵעַל בְּנֵי יִשְׂרָאֵל:
@876 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא עַשְׂרִין וְאַרְבְּעָה אַלְפִין: פפפ:
@877 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@878 פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא אֲתֵיב יַת חֵמְתִי מֵעַל בְּנֵי יִשְׂרָאֵל בִּדְקַנֵי יַת קִנְאָתִי בֵּינֵיהוֹן וְלָא שֵׁיצֵיתִי יַת בְּנֵי יִשְׂרָאֵל בְּקִנְאָתִי:
@879 בְּכֵן אֵימַר הָא אֲנָא גְזַר לֵיהּ יַת קְיָמִי שְׁלָם:
@880 וּתְהֵי לֵיהּ וְלִבְנוֹהִי בַּתְרוֹהִי קְיַם כְּהֻנַת עֲלָם חֲלַף דִי קַנֵי קֳדָם אֱלָהֵהּ וְכַפֵּר עַל בְּנֵי יִשְׂרָאֵל:
@881 וְשׁוּם גַבְרָא בַּר יִשְרָאֵל קְטִילָא דִי אִתְקְטֵל עִם מִדְיָנֵיתָא זִמְרִי בַּר סָלוּא רַב בֵּית אַבָּא לְבֵית שִׁ מְעוֹן:
@882 וְשׁוּם אִתְּתָא דְאִתְקְטִילַת מִדְיָנֵיתָא כָּזְבִּי בַּת צוּר רֵישׁ אוּמֵי בֵּית אַבָּא בְּמִדְיָן הוּא:
@883 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@884 אָעֵק יַת מִדְיָנָאֵי וְתִקְטְלוּן יָתְהוֹן:
@885 אֲרֵי מְעִיקִין אִינוּן לְכוֹן בְּנִכְלֵיהוֹן דִי נְכִילוּ לְכוֹן עַל עֵיסַק פְּעוֹר וְעַל עֵיסַק כָּזְבִּי בַּת רַבָּא דְמִדְיָן אֲחַתְהוֹן דְאִתְקְטִילַת בְּיוֹמָא דְמוֹתָנָא עַל עֵיסַק פְּעוֹר:
@887 וַהֲוָה בָּתַר מוֹתָנָא וַאֲמַר יְיָ לְמשֶׁה וּלְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא לְמֵימָר:
@888 קַבִּילוּ יַת חוּשְׁבַּן כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא לְבֵית אֲבָהַתְהוֹן כָּל נָפֵיק חֵילָא בְּיִשְׂרָאֵל:
@889 וּמַלִיל משֶׁה וְאֶלְעָזָר כַּהֲנָא וַאֲמָרוּ לְמִמְנֵי יָתְהוֹן בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירִיחוֹ לְמֵימָר:
@890 מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּבְנֵי יִשְׂרָאֵל דִנְפָקוּ מֵאַרְעָא דְמִצְרָיִם:
@891 רְאוּבֵן בּוּכְרָא דְיִשְׂרָאֵל בְּנֵי רְאוּבֵן חֲנוֹךְ זַרְעִית חֲנוֹךְ לְפַלוּא זַרְעִית פַּלוּא:
@892 לְחֶצְרוֹן זַרְעִית חֶצְרוֹן לְכַרְמִי זַרְעִית כַּרְמִי:
@893 אִלֵין זַרְעֲיַת רְאוּבֵן וַהֲווֹ מִנְיָנֵיהוֹן אַרְבְּעִין וּתְלָתָא אַלְפִין וּשְׁבַע מְאָה וּתְּלָתִין:
@894 וּבְנֵי פַלוּא אֱלִיאָב:
@895 וּבְנֵי אֱלִיאָב נְמוּאֵל וְדָתָן וַאֲבִירָם הוּא דָתָן וַאֲבִירָם מְעַרְעֵי כְּנִשְׁתָּא דְאִתְכְּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן בִּכְנִשְׁתָּא דְקֹרַח בְּאִתְכַּנוֹשֵׁיהוֹן עַל יְיָ:
@896 וּפְתָחַת אַרְעָא יַת פּוּמָהּ וּבְלָעַת יָתְהוֹן וְיָת קֹרַח בְּמוֹתָא דִכְנִשְׁתָּא כַּד אֲכָלַת אֵשָׁתָא יַת מָאתָן וְחַמְשִׁין גַבְרָא וַהֲווֹ לְאָת:
@897 וּבְנֵי קֹרַח לָא מִיתוּ:
@898 בְּנֵי שִׁמְעוֹן לְזַרְעֲיַתְהוֹן לִנְמוּאֵל זַרְעִית נְמוּאֵל לְיָמִין זַרְעִית יָמִין לְיָכִין זַרְעִית יָכִין:
@899 לְזֶרַח זַרְעִית זֶרַח לְשָׁאוּל זַרְעִית שָׁאוּל:
@900 אִלֵין זַרְעֲיַת שִׁמְעוֹן עַשְׂרִין וּתְרֵין אַלְפִין וּמָאתָן:
@901 בְּנֵי גָד לְזַרְעֲיַתְהוֹן לִצְפוֹן זַרְעִית צְפוֹן לְחַגִי זַרְעִית חַגִי לְשׁוּנִי זַרְעִית שׁוּנִי:
@902 לְאָזְנִי זַרְעִית אָזְנִי לְעֵרִי זַרְעִית עֵרִי:
@903 לַאֲרוֹד זַרְעִית אֲרוֹדִי לְאַרְאֵלִי זַרְעִית אַרְאֵלִי:
@904 אִלֵין זַרְעֲיַת בְּנֵי גָד לְמִנְיָנֵהוֹן אַרְבְּעִין אַלְפִין וַחֲמֵשׁ מְאָה:
@905 בְּנֵי יְהוּדָה עֵר וְאוֹנָן וּמִית עֵר וְאוֹנָן בְּאַרְעָא דִכְנָעַן:
@906 וַהֲווֹ בְנֵי יְהוּדָה לְזַרְעֲיַתְהוֹן לְשֵׁלָה זַרְעִית שֵׁלָה לְפֶרֶץ זַרְעִית פֶּרֶץ לְזֶרַח זַרְעִית זָרַח:
@907 וַהֲווֹ בְנֵי פֶרֶץ לְחֶצְרוֹן זַרְעִית חֶצְרוֹן לְחָמוּל זַרְעִית חָמוּל:
@908 אִלֵין זַרְעֲיַת יְהוּדָה לְמִנְיָנֵיהוֹן שִׁבְעִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@909 בְּנֵי יִשָשׂכָר לְזַרְעֲיַתְהוֹן תּוֹלָע זַרְעִית תּוֹלָע לְפֻוָה זַרְעִית פּוּנִי:
@910 לְיָשׁוּב זַרְעִית יָשׁוּב לְשִׁמְרוֹן זַרְעִית שִׁמְרוֹן:
@911 אִלֵין זַרְעֲיַת יִשָׂשׂכָר לְמִנְיָנֵיהוֹן שִׁתִּין וְאַרְבְּעָה אַ:לפִין וּתְלַת מְאָה:
@912 בְּנֵי זְבוּלוּן לְזַרְעֲיַתְהוֹן לְסֶרֶד זַרְעִית סֶרֶד לְאֵלוֹן זַרְעִית אֵלוֹן לְיַחְלְאֵל זַרְעִית יַחְלְאֵל:
@913 אִלֵין זַרְעֲיַת זְבוּלוּן לְמִנְיָנֵיהוֹן שִׁתִּין אַלְפִין:וְחֲמֵשׁ מְאָה:
@914 בְּנֵי יוֹסֵף לְזַרְעֲיַתְהוֹן מְנַשֶׁה וְאֶפְרָיִם:
@915 בְּנֵי מְנַשֶׁה לְמָכִיר זַרְעִית מָכִיר וּמָכִיר אוֹלִיד יַת גִלְעָד לְגִלְעָד זַרְעִית גִלְעָד:
@916 אִלֵין בְּנֵי גִלְעָד אִיעֶזֶר זַרְעִית אִיעֶזֶר לְחֵלֶק זַרְעִית חֵלֶק:
@917 וְאַשְׂרִיאֵל זַרְעִית אַשְׂרִיאֵלִי וְשֶׁכֶם זַרְעִית שֶׁכֶם:
@918 וּשְׁמִידָע זַרְעִית שְׁמִידָע וְחֵפֶר זַרְעִית חֵפֶר:
@919 וּצְלָפְחָד בַּר חֵפֶר לָא הֲווֹ לֵיהּ בְּנִין אֱלָהֵין בְּנָן וְשׁוּם בְּנַת צְלָפְחָד מַחְלָה וְנוֹעָה חָגְלָה מִלְכָּה וְתִרְצָה:
@920 אִלֵין זַרְעֲיַת מְנַשֶׁה וּמִנְיָנֵיהוֹן חַמְשִׁין וּתְרֵין אַלְפִין וּשְׁבַע מְאָה:
@921 אִלֵין בְּנֵי אֶפְרַיִם לְזַרְעֲיַתְהוֹן לְשׁוּתֶלַח זַרְעִית שׁוּתֶלַח לְבֶכֶר זַרְעִית בֶּכֶר לְתַחַן זַ:רעִית תַּחַן:
@922 וְאִלֵין בְּנֵי שׁוּתָלַח לְעֵרָן זַרְעִית עֵרָן:
@923 אִלֵין זַרְעֲיַת בְּנֵי אֶפְרַיִם לְמִנְיָנֵיהּוֹן תְּלָתִין וּתְרֵין אַלְפִין וַחֲמֵשׁ מְאָה אִלֵין בְּנֵי יוֹסֵף לְזַרְעֲיַתְהּוֹן:
@924 בְּנֵי בִנְיָמִין לְזַרְעֲיַתְהוֹן לְבֶלַע זַרְעִית בֶּלַע לְאַשְׁבֵּל זַרְעִית אַשְׁבֵּל לַאֲחִירָם זַרְעִית אֲחִירָם:
@925 לִשְׁפוּפָם זַרְעִית שְׁפוּפָם לְחוּפָם זַרְעִית חוּפָם:
@926 וַהֲווֹ בְנֵי בֶלַע אַרְדְ וְנַעֲמָן זַרְעִית הָאַרְדִי לְנַעֲמָן זַרְעִית נַעֲמִי:
@927 אִלֵין בְּנֵי בִנְיָמִן לְזַרְעֲיַתְהוֹן וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְשִׁית מְאָה:
@928 אִלֵין בְּנֵי דָן לְזַרְעֲיַתְהוֹן לְשׁוּחָם זַרְעִית שׁוּחָם אִלֵין זַרְעֲיַת דָן לְזַרְעֲיַתְהוֹן:
@929 כָל זַרְעֲיַת שׁוּחָם לְמִנְיָנֵיהוֹן שִׁתִּין וְאַרְבַּע אַלְפִין וְאַרְבַּע מְאָה:
@930 בְּנֵי אָשֵׁר לְזַרְעֲיַתְהוֹן לְיִמְנָה זַרְעִית יִמְנָה לְיִשְׁוִי זַרְעִית יִשְׁוִי לִבְרִיעָה זַרְעִית בְּרִיעָה:
@931 לִבְנֵי בְרִיעָה לְחֵבֶר זַרְעִית חֵבֶר לְמַלְכִּיאֵל זַרעִית מַלְכִּיאֵל:
@932 וְשׁוּם:בַּת אָשֵׁר סָרַח:
@933 אִלֵין זַרְעֲיַת בְּנֵי אָשֵׁר לְמִנְיָנֵיהוֹן חַמְשִׁין וּתְלָתָא אַלְפִין:ואַ:רבַּע מְאָה:
@934 בְּנֵי נַפְתָּלִי לְזַרְעֲיַתְהוֹן לְיַחְצְאֵל זַרְעִית יַחְצְאֵל לְגוּנִי זַרְעִית גוּנִי:
@935 לְיֵצֶר זַרְעִית יֵצֶר לְשִׁלֵם זַרְעִית שִׁלֵם:
@936 אִלֵין זַרְעֲיַת נַפְתָּלִי לְזַרְעֲיַתְהוֹן וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְאַרְבַּע מֵאָה:
@937 אִלֵין מִנְיָנֵי בְּנֵי יִשְׂרָאֵל שִׁית מְאָה וְחַד אַלְפִין שְׁבַע מְאָה וּתְלָתִין:
@938 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@939 לְאִלֵין תִּתְפְּלֵיג אַרְעָא בְּאַחֲסָנָא בְּמִנְיַן שְׁמָהָן:
@940 לְסַגִיאֵי תִּסְגוּן אַחֲסַנְתְּהוֹן וְלִזְעֵירֵי תַּזְעֲרוּן אַחֲסַנְתְּהוֹן גְבַר לְפוּם מִנְיָנוֹהִי תִּתְיְהֵב אַחֲסַנְתֵּיהּ:
@941 בְּרַם בְּעַדְבָא תִּתְפְּלֵיג יַת אַרְעָא לִשְׁמָהָן שִׁבְטֵי אֲבָהָתְהוֹן יַחְסְנוּן:
@942 עַל פּוּם עַדְבָא תִּתְפְּלֵיג אַחֲסַנְתְּהוֹן בֵּין סַגִיאֵי לִזְעֵירֵי:
@943 וְאִלֵין מִנְיָנֵי לֵוָאֵי לְזַרְעֲיַתְהוֹן לְגֵרְשׁוֹן זַרְעִית גֵרְשׁוֹן לִּקְהָת זַרְעִית קְהָת לִמְרָרִי זַרְעִית מְרָרִי:
@944 אִלֵין זַרְעֲיַת לֵוִי זַרְעִית לִבְנִי זַרְעִית חֶבְרוֹן זַרְעִית מַחְלִי זַרְעִית מוּשִׁי זַרְעִית קֹרַח וּקְהָת אוֹלִיד יָת עַמְרָם:
@945 וְשׁוּם אִתַּת עַמְרָם יוֹכֶבֶד בַּת לֵוֵי דִילֵדַת יָתַהּ לְלֵוִי בְּמִצְרָיִם וִילֵידַת לְעַמְרָם יָת אַהֲרֹן וְיָת משֶׁה וְיָת מִרְיָם אֲחַתְהוֹן:
@946 וְאִתְיְלִיד לְאַהֲרֹן יַת נָדָב וְיַת אֲבִיהוּא יַת אֶלְעָזָר וְיַת אִיתָמָר:
@947 וּמִית נָדָב וַאֲבִיהוּא בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ:
@948 וַהֲווֹ מִנְיָנֵיהוֹן עַשְׂרִין וּתְלָתָא אַלְפִין כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵילָא אֲרֵי לָא אִתְמְנִיאוּ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲרֵי לָא אִתְיְהִיבַת לְהוֹן אַחֲסָנָא בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@949 אִלֵין מִנְיָנֵי משֶׁה וְאֶלְעָזָר כַּהֲנָא דִי מְנוֹ יַת בְּנֵי יִשְׂרָאֵל בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ:
@950 וּבְאִלֵין לָא הֲוָה גְבַר מִמִנְיָנֵי משֶׁה וְאַהֲרֹן כַּהֲנָא דִי מְנוֹ יָת בְּנֵי יִשְׂרָאֵל בְּמַדְבְּרָא דְסִינָי:
@951 אֲרֵי אֲמַר יְיָ לְהוֹן מֵימַת יְמוּתוּן בְּמַדְבְּרָא וְלָא אִשְׁתְּאַר מִנְהוֹן אֱנַשׁ אֶלָהֵן כָּלֵב בַּר יְפֻנֶה וִיהוֹשֻׁעַ בַּר נוּן:
@952 וְקָרֵיבָא בְּנַת צְלָפְחָד בַּר חֵפֶר בַּר גִלְעָד בַּר מָכִיר בַּר מְנַשֶׁה לְזַרְעֲיַת מְנַשֶׁה בַּר יוֹסֵף וְאִלֵין שְׁמָהַת בְּנָתֵיהּ מַחְלָה נוֹעָה וְחָגְלָה וּמִלְכָּה וְתִרְצָה:
@953 וְקָמָן קֳדָם משֶׁה וְקֳדָם אֶלְעָזָר כַּהֲנָא וְקֳדָם רַבְרְבַיָא וְכָל כְּנִשְׁתָּא בִּתְרַע מַשְׁכַּן זִמְנָא לְמֵימָר:
@954 אָבוּנָא מִית בְּמַדְבְּרָא וְהוּא לָא הֲוָה בְּגוֹ כְנִשְׁתָּא דְאִזְדַמָנוּ עַל יְיָ בְּכְנִשְׁתָּא דְקֹרַח אֲרֵי בְחוֹבֵיהּ מִית וּבְנִין לָא הֲווֹ לֵיהּ:
@955 לְמָא יִתְמְנַע שְׁמָא דַאֲבוּנָא מִגוֹ זַרְעִיתֵיהּ אֲרֵי לֵית לֵיהּ בָּר הַב לָנָא אַחֲסָנָא בְּגוֹ אֲחֵי אָבוּנָא:
@956 וְקָרֵב משֶׁה יָת דִינְהוֹן קֳדָם יְיָ:
@957 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@958 יָאוּת בְּנַת צְלָפְחָד מְמַלְלָן מִתַּן תִּתֵּן לְהוֹן אֲחוּדַת אַחֲסָנָא בְּגוֹ אֲחֵי אֲבוּהֶן וְתַעֲבַר יַת אַחֲסָנַת אֲבוּהֶן לָהֶן:
@959 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵיל לְמֵימָר גְבַר אֲרֵי יְמוּת וּבַר לֵית לֵיהּ וְתַעַבְרוּן יָת אַחֲסַנְתֵּיהּ לִּבְרַתֵּיהּ:
@960 וְאִם לֵית לֵיהּ בְּרַתָּא וְתִתְּנוּן יָת אַחֲסַנְתֵּיה לַאֲחוֹהִי:
@961 וְאִם לֵית לֵיהּ אַחִין וְתִתְּנוּן יָת אַחֲסַנְתֵּיהּ לְאֲחֵי אֲבוּהִי:
@962 וְאִם לֵית אַחִין לַאֲבוּהִי וְתִתְּנוּן יָת אַחֲסַנְתֵּיהּ לְקָרִיבֵיהּ דְקָרֵיבּ לֵיהּ מִזַרְעִיתֵיהּ וְיֵרַת יָתַהּ וּתְהֵי לִבְנֵי יִשְׂרָאֵל לִגְזֵירַת דִין כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@963 וַאֲמַר יְיָ לְמשֶׁה סַק לְטוּרָא דַעֲבָרָאֵי הָדֵין וַחֲזֵי יָת אַרְעָא דִי יְהָבִית לִבְנֵי יִשִׂרָאֵל:
@964 וְתֶחֱזֵי יָתָהּ וְתִתְכְנֵּשׁ לְעַמָיךְ אַף אָתְּ כְּמָא דִי אִתְכְּנִישׁ אַהֲרֹן אָחוּךְ:
@965 כְּמָא דִסָרֵיבְתּוּן עַל מֵימְרִי בְּמַדְבְּרָא דְצִן בְּמַצוּת כְּנִשְׁתָּא לְקַדָשׁוּתִי בְמַיָא לְעֵינֵיהוֹן אִנוּן מֵי מַצוּת רְקָם מַדְבְּרָא דְצִן:
@966 וּמַלִיל משֶׁה קֳדָם יְיָ לְמֵימָר:
@967 יְמַנֵי יְיָ אֱלָהָא רוּחַיָא לְכָל בִּשְׂרָא גְבַר עַל כְּנִשְׁתָּא:
@968 דִי יִפּוֹק קֳדָמֵיהוֹן וְדִי יֵעוֹל קֳדָמֵיהוֹן וְדִי יַפֵּקִנוּן וְדִי יָעֵלִינוּן וְלָא תְהֵי כְּנִשְׁתָּא דַיְיָ כְּעָנָא דִי לֵית לְהֵן רָעֵי:
@969 וַאֲמַר יְיָ לְמשֶׁה דְבַר לָךְ יָת יְהוֹשֻׁעַ בַּר נוּן גְבַר דִי רוּחַ נְבוּאָה בֵּיהּ וְתִסְמוֹךְ יָת יְדָךְ עֲלוֹהִי:
@970 וּתְקֵים יָתֵיהּ לָקֳדָם אֶלְעָזָר כַּהֲנָא וְלָקֳדָם כָּל כְּנִשְׁתָּא וּתְפַקֵד יָתֵיהּ לְעֵינֵיהוֹן:
@971 וְתִתֵּן מִזִיוָךְ עֲלוֹהִי בְּדִיל דִי יְקַבְּלוּן מִנֵיהּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@972 וְלִקֳדָם אֶלְעָזָר כַּהֲנָא יְקוּם וְיִשְׁאַל לֵיהּ בְּדִין אוּרַיָא קֳדָם יְיָ עַל מֵימְרֵיהּ יְהוֹן נַפְקִין וְעַל מֵימְרֵא יְהוֹן עָאלִין הוּא וְכָל בְּנֵי יִשְׂרָאֵל עִמֵיהּ וְכָל כְּנִשְׁתָּא:
@973 וַעֲבַד משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵיהּ וּדְבַר יָת יְהוֹשֻׁע וַאֲקִימֵיהּ קֳדָם אֶלְעָזָר כַּהֲנָא וּקְדָם כָּל כְּנִשְׁתָּא:
@974 וּסְמַךְ יָת יְדוֹהִי עֲלוֹהִי וּפַקְדֵיהּ כְּמָא דִי מַלִיל יְיָ בִּידָא דְמשֶׁה:
@975 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@976 פַקֵיד יָת בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן יָת קוּרְבָּנִי לְחֵם סִדוּר לְקוּרְבָּנַי לְאִתְקַבָּלָא בְּרַעֲוָא תִּטְרוּן לְקָרָבָא קֳדָמַי בְּזִמְנֵיהּ:
@977 וְתֵימַר לְהוֹן דֵין קוּרְבָּנָא דִי תְקַרְבוּן קֳדָם יְיָ אִימְּרִין בְּנֵי שְׁנָא שַׁלְמִין תְּרֵין לְּיוֹמָא עֲלָתָא תְּדִירָא:
@978 יָת אִמְרָא חָד תַּעֲבֵד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעֲבֵד בֵּין שִׁמְשַׁיָא:
@979 וְחָד מִן עַשְׂרָא בִּתְלַת סָאִין סוּלְתָּא לְמִנְחָתָא דְפִילָא בִּמְשַׁח כְּתִישָׁא רַבְעוּת הִינָא:
@980 עֲלָתָא תְּדִירָא דְאִתְעֲבִידָא בְּטוּרָא דְסִינַי לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@981 וְנִסְכֵּיהּ רַבְעוּת הִינָא לְאִמְרָא חָד בְּקוּדְשָׁא יִתְנַסַךְ נִסוּךְ דַחֲמַר עַתִּיק קֳדָם יְיָ:
@982 וְיָת אִמְרָא תִנְיָנָא תַּעֲבֵיד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכֵּיהּ תַּעְבֵיד קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@983 וּבְיוֹמָא דְשַׁבַּתָּא תְּרֵין אִימְרִין בְּנֵי שְׁנָא שַׁלְמִין וּתְרֵין עִשְׂרוֹנִין סוּלְתָּא דְמִנְחָתָא דְפִילָא בִּמְשַׁח וְנִסְכֵּיהּ:
@984 עֲלַת שַׁבְּתָא דְתִּתְעֲבֵיד בְּשַׁבַּתָּא עַל עֲלָתָא תְּדִירָא וְנִסְכַּהּ:
@985 וּבְרֵישֵׁי יַרְחֵיכוֹן תְּקַרְבוּן עֲלָתָא קֳדָם יְיָ תּוֹרִין בְּנֵי תּוֹרֵי תְּרֵין וּדְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@986 וּתְלָתָא עִשְׂרוֹנִין סוּלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְתוֹרָא חָד וּתְרֵין עִשְׂרוֹנִין סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְדִכְרָא חָד:
@987 וְעִשְׂרוֹנָא עִשְׂרוֹנָא סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְאִמְרָא חָד עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@988 וְנִסְכֵּיהוֹן פַּלְגוּת הִינָא יְהֵי לְתוֹרָא וְתַלְתּוּת הִינָא לְדִכְרָא וְרַבְעוּת הִינָא לְאִמְרָא חַמְרָא דָא עֲלַת רֵישׁ יַרְחָא בְּאִתְחַדָתוּתֵיהּ כֵּן לְכָל רֵישֵׁי יַרְחֵי שַׁתָּא:
@989 וּצְפִיר בַּר עִזִין חָד לְחַטָאתָא קֳדָם יְיָ עַל עֲלָתָא תְּדִירָא יִתְעֲבֵד וְנִסְכֵּיהּ:
@990 וּבְיַרְחָא קַדְמָאָה בְּאַרְבַּעַת עַשְׂרָא יוֹמָא לְיַרְחָא פִּסְחָא קֳדָם יְיָ:
@991 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא שַׁבְעָא יוֹמִין פַּטִיר יִתְאָכֵל:
@992 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עֲבִידַת פּוּלְחַן לָא תַעְבְדוּן:
@993 וּתְקַרְבוּן קוּרְבָּנָא עֲלָתָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּרֵין וּדְכַר חָד וְשַׁבְעָא אִימְרִין בְּנֵי שְׁנָא שַׁלְמִין יְהוֹן לְכוֹן:
@994 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִּמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא וּתְרֵין עִשְׂרוֹנִין לְדִכְרָא תַּעְבְּדוּן:
@995 עִשְׂרוֹנָא עִשְׂרוֹנָא תַּעֲבֵיד לְאִמְרָא חָד כֵּן לְשַׁבְעָא אִימְרִין:
@996 וּצְפִירָא דְחַטָאתָא חָד לְכַפָּרָא עֲלֵיכוֹן:
@997 בַּר מֵעֲלַת צַפְרָא דְהִּיא עֲלַת תְּדִירָא תַּעְבְּדוּן יָת אִלֵין:
@998 כְּאִלֵין תַּעַבְדוּן לְיוֹמָא שַׁבְעָא יוֹמִין לְחֵם קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ עַל עֲלָתָא תְדִירָא יִתְעֲבֵיד וִנִסִכֵּיהּ:
@999 וּבְיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִיבִידַת פּוּלְחַן לָא תַעַבְדוּן:
@1000 וּבְיוֹמָא דְבִכּוּרַיָא בְּקָרוֹבֵיכוֹן מִנְחֲתָא חֲדַתָּא קֳדָם יְיָ בְּעַצְרָתֵיכוֹן מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן:
@1001 וּתְקַרְבוּן עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּרֵין וּדְכַר חָד שַׁבְעָא אִימְרִין בְּנֵי שְׁנָא:
@1002 וּמִנְחַתְהוֹן סֻלְתָּא דְפִילָא בִמְשָׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא חָד תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד:
@1003 עִשְׂרוֹנָא עִשְׂרוֹנָא לְאִמְרָא חָד לְשַׁבְעָא אִימְרִין:
@1004 צְפִיר בַּר עִזִין חָד לְכַפָּרָא עֲלֵיכוֹן:
@1005 בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתֵהּ תַּעְבְּדוּן שַׁלְמִין יְהוֹן לְכוֹן וְנִסְכֵּיהוֹן:
@1006 וּבְיַרְחָא שְׁבִיעָאָה בְּחָד לְיַרְחָא מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן יוֹם יַבָּבָא יְהֵי לְכוֹן:
@1007 וְתַעַבְדוּן עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ תּוֹר בַּר תּוֹרֵי חָד דְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@1008 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא תְּרֵין עִשְׂרוֹנִין לְדִכְרָא:
@1009 וְעִשְׂרוֹנָא חָד לְאִימְרָא חָד לְשַׁבְעָא אִימְרִין:
@1010 וּצְפִיר בַּר עִזִין חָד לְחַטָאתָא לְכַפָּרָא עֲלֵיכוֹן:
@1011 בַּר מֵעֲלַת יַרְחָא וּמִנְחָתַהּ וַעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן כִּדְחָזֵי לְהוֹן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@1012 וּבְעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן כָּל עִבִידְתָּא לָא תַעַבְדוּן:
@1013 וּתְקָרְבוּן עֲלָתָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא תּוֹר בַּר תּוֹרֵי חָד דְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין יְהוֹן לְכוֹן:
@1014 וּמִנְחַתְהוֹן סֻלְתָּא דְפִילָא בִמְשָׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד:
@1015 עִשְׂרוֹנָא עִשְׂרוֹנָא לְאִימְרָא חָד לְשַׁבְעָא אִימְרִין:
@1016 צְפִיר בַּר עִזִין חָד חַטָּאתָא בַּר מֵחַטָאתָא דְכִפוּרַיָא וַעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן:
@1017 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן וּתְחַגוּן חַגָא קֳדָם יְיָ שַׁבְעָא יוֹמִין:
@1018 וּתְקַרְבוּן עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּלַת עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין יְהוֹן:
@1019 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא חָד לִתְלַת עֲשַׂר תּוֹרִין תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד לִתְרֵין דִכְרִין:
@1020 וְעִשְׂרוֹנָא עִשְׂרוֹנָא לְאִימְרָא חָד לְאַרְבְּעָא עֲשַׂר אִימְרִין:
@1021 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכַּהּ:
@1022 וּבְיוֹמָא תִנְיָנָא תּוֹרִין בְּנֵי תוֹרֵי תְּרֵי עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1023 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1024 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן:
@1025 וּבְיוֹמָא תְּלִיתָאָה תּוֹרִין חָד עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1026 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִמְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1027 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@1028 וּבְיוֹמָא רְבִיעָאָה תּוֹרִין עַשְׂרָא דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1029 מִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1030 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכַּהּ:
@1031 וּבְיוֹמָא חֲמִישָׁאָה תּוֹרִין תְּשַׁע דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1032 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1033 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@1034 וּבְיוֹמָא שְׁתִיתָאָה תּוֹרִין תְּמַנְיָא דִכְרִין תְּרֵין אִמְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1035 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1036 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכָּהָא:
@1037 וּבְיוֹמָא שְׁבִיעָאָה תּוֹרִין שַׁבְעָא דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@1038 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי לְהוֹן:
@1039 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא מִנְחָתָהּ וְנִסְכָּהּ:
@1040 בְּיוֹמָא תְּמִינָאָה כְּנִישִׁין תְּהֵא לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעְבְדוּן:
@1041 וּתְקַרְבוּן עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ תּוֹר חָד דְכַר חָד אִמְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@1042 מִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרָא לְדִכְרָא וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@1043 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@1044 אִלֵין תַּעְבְדוּן קֳדָם יְיָ בְּמוֹעֲדֵיכוֹן בַּר מִנִדְרֵיכוֹן וְנִדְבוֹתֵיכוֹן לְעֲלְוַתְכוֹן וּלְמִנְחַתְכוֹן וּלְנִסְכֵּיכוֹן וּלְנִכְסַת קוּדְשֵׁיכוֹן:
@1045 וַאֲמַר משֶׁה לִבְנֵי יִשְׂרָאֵל כְּכֹל דִי פַקֵיד יְיָ יָת משֶׁה: פפפ:
@1046 וּמַלִיל משֶׁה עִם רֵישֵׁי שִׁבְטַּיָא לִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָמָא דִי פַקֵיד יְיָ:
@1047 גְבַר אֲרֵי יִדַר נְדַר קֳדָם יְיָ אוֹ יְקַיֵים קְיַם לְמֵיסַר אִסַר עַל נַפְשֵׁיהּ לָא יְבַטֵל פִּתְגָמֵיהּ כְּכָל דִי יִפּוֹק מִפּוּמֵיה יַעֲבֵּד:
@1048 וְאִתְּתָא אֲרֵי תִדַר נְדַר קֳדָם יְיָ וְתֵיסַר אִסָר בְּבֵית אֲבוּהָא בְּרַבְיוּתָהָא:
@1049 וְיִשְׁמַע אֲבוּהָא יָת נִדְרָהּ וְאֵסָרָהּ דִי אֲסָרַת עַל נַפְשָׁהּ וְיִשְׁתּוֹק לָהּ אֲבוּהָא וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱסָרֵי דִי אֲסָרַת עַל נַפְשָׁהּ יְקוּמוּן:
@1050 וְאִם אַעְדֵי אָבוּהָא יָתַהּ בְּיוֹמָא דִשְׁמַע כָּל נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשָׁהּ לָא יְקוּמוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לָהּ אֲרֵי אַעְדִי אֲבוּהָא יָתַהּ:
@1051 וְאִם מֶהֱוָה תֶהֱוֵי לִגְבַר וְנִדְרָהָא עֲלָהּ אוֹ פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשָׁהּ:
@1052 וְיִשְׁמַע בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע וְיִשְׁתּוֹק לַהּ וִיקוּמוּן נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@1053 וְאִם בְּיוֹמָא דִשְׁמַע בַּעֲלַהּ אַעְדִי יָתַהּ וִיבַטֵּל יָת נִדְרָהָא דִי עֲלַהּ וְיָת פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשַׁהּ וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@1054 וּנְדַר אַרְמְלָא וּמְתַרְכָא כֹּל דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּם עֲלַהּ:
@1055 וְאִם בֵּית בַּעֲלַהּ נְדָרַת אוֹ אֲסָרַת אִסַר עַל נַפְשַׁהּ בְּקִיוּם:
@1056 וְיִשְׁמַע בַּעֲלַהּ וְיִשְׁתּוֹק לַהּ לָא אַעֲדֵי יָתַהּ וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱםָרֵי דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@1057 וְאִם בַּטָלָא יְבַטֵל יָתְהוֹן בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע כָּל אַפָּקוּת סִפְוָתָהָא לְנִדְרָהָא וּלְאִסַר נַפְשַׁהּ לָא יְקוּמוּן בַּעֲלַהּ בְּטֵלִינוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@1058 כָּל נְדַר וְכָל קִיוּמַת אִסַר לְסַגָפָא נְפָשׁ בַּעֲלַהּ יְקַיְמִינוּן וּבַעֲלַהּ יְבַטְלִינוּן:
@1059 וְאִם מִשְׁתַּק יִשְׁתּוֹק לַהּ בַּעֲלַהּ מִיוֹם לְיוֹם וִיקַיֵים יָת כָּל נִדְרָהָא אוֹ יָת כָּל אֱסָרָהָא דִי עֲלָהּ קַיֵים יָתְהוֹן אֲרֵי שָׁתֵק לַהּ בְּיוֹמָא דִשְׁמָע:
@1060 וְעִם בַּטָלָא יְבַטֵּל יָתְהוֹן בָּתַר דִשְׁמָע וִיקַבַּל יָת חוֹבַהּ:
@1061 אִלֵין קְיָמַיָא דִי פַקֵיד יְיָ יָת משֶׁה בֵּין גְבַר לְאִתְּתֵיהּ בֵּין אַבָּא לִבְרַתֵּיהּ בְּרַבְיוּתָהָא בֵּית אָבוּהָא:
@1062 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@1063 אִתְפְּרַע פֻּרְעֲנוּת בְּנֵי יִשְׂרָאֵל מִן מִדְיָנָאֵי בָּתַר כֵּן תִּתְכְּנֵישׁ לְעַמָּךְ:
@1064 וּמַלֵיל משֶׁה עִם עַמָא לְמֵימָר זְרִיזוּ מִנְכוֹן גֻבְרִין לְחֵילָא וִיהוֹן עַל מִדְיָן לְמִתַּן פּוּרְעֲנוּת דִין עַמָא דַיְיָ בְּמִדְיָן:
@1065 אַלְפָא לְשִׁבְטָא אַלְפָא לְשִׁבְטָּא לְכֹל שִׁבְטַיָא דְיִשְֹׁרָאֵל תְּשַׁלְחוּן לְחֵילָא:
@1066 וְאִתְבְּחָרוּ מֵאַלְפַיָא דְיִֹשְׂרָאֵל אַלְפָא לְשִׁבְטָא תְּרֵי עֲֹשַׂר אַלְפִין מְזָרְזֵי חֵילָא:
@1067 וּשְׁלַח יָתְהוֹן משֶׁה אַלְפָא לְשִׁבְטָא לְחֵילָא יָתְהוֹן וְיָת פִּינְחָס בַּר אֶלְעָזָר כַּהֲנָא לְחֵילָא וּמָנֵי דְקוּדְשָׁא וַחֲצוֹצְרוֹת יַבֶּבְתָּא בִּידֵיהּ:
@1068 וְאִתְחַיָילוּ עַל מִדְיָן כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּקְטָלוּ כָּל דְכוּרָא:
@1069 וְיָת מַלְכֵי מִדְיָן קְטָלוּ עַל קְטִילֵיהוֹן יָת אֱוִי וְיָת רֶקֶם וְיָת צוּר וְיָת חוּר וְיָת רֶבַע חַמְשָׁא מַלְכֵי מִדְיָן וְיָת בִּלְעָם בַּר בְּעוֹר קְטָלוּ בְּחַרְבָּא:
@1070 וּשְׁבוֹ בְנֵי יִשְׂרָאֵל יָת נְשֵׁי מִדְיָן וְיָת טַּפְלְהוֹן וְיָת כָּל בְּעִירְהוֹן וְיָת כָּל גֵיתֵיהוֹן וְיָת כָּל נִכְסֵיהוֹן בְּזוֹ:
@1071 וְיָת כָּל קִרְוֵיהוֹן בְּמוֹתְבָנֵיהוֹן וְיָת כָּל בֵּית סִגְדַתְהוֹן אוֹקִידוּ בְּנוּרָא:
@1072 וּנְסִיבוּ יָת כָּל עֲדָאָה וְיָת כָּל דְבַרְתָּא בֶּאֱנָשָׁא וּבִבְעִירָא:
@1073 וְאַיתִיוּ לְוָת משֶׁה וּלְוָת אֶלְעָזָר כַּהֲנָא וּלְוָת כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יָת שִׁבְיָא וְיָת דְבַרְתָּא וְיָת עֲדָאָה לְמַשְׁרִיתָא לְמֵישְׁרַיָא דְמוֹאָב דִי עַל יַרְדְנָא דִירֵחוֹ:
@1074 וּנְפָקוּ משֶׁה וְאֶלְעָזָר כַּהֲנָא וְכָל רַבְרְבֵי כְנִשְׁתָּא לְקֳדָמוּתְהוֹן לְמִבָּרָא לְמַשְׁרִיתָא:
@1075 וּרְגֵיז משֶׁה עַל דִמְמַנָן עַל חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָותָא דְאָתוּ מֵחֵיל קְרָבָא:
@1076 וַאֲמַר לְהוֹן משֶׁה הֲקַיֵמְתּוּן כָּל נוּקְבָא:
@1077 הָא אִינוּן הֲוָאָה לִבְנֵי יִשְׂרָאֵל בַּעֲצַת בִּלְעָם לְשַׁקָרָא שְׁקָר קֳדָם יְיָ עַל עֵסַק פְּעוֹר וַהֲוַת מוֹתָנָא בִּכְנִשְׁתָּא דַיְיָ:
@1078 וּכְעַן קְטוּלוּ כָּל דְכוּרָא בְּטַפְלָא וְכָל אִתְּתָא דִידַעַת גְבַר לְמִשְׁכַּב דְכוּרָא קְטּוּלוּ:
@1079 וְכָל טַפְלָא בִנְשַׁיָא דִי לָא יְדָעוּ מִשְׁכַּב דְכוּרָא קַיְימוּ לְכוֹן:
@1080 וְאַתּוּן שְׁרוֹ מִבָּרָא לְמַשְׁרִיתָא שַׁבְעָא יוֹמִין כָּל דִי קְטַל נַפְשָׁא וְכֹל דִי קְרַב בְּקָטִילָא תַּדוּן עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה אַתּוּן וּשְׁבִיכוֹן:
@1081 וְכָל לְבוּשׁ וְכָל מַאן דִמְשַׁךְ וְכָל עוֹבַד מֵעַזֵי וְכָל מַאן דְעָא תַּדוּן עֲלוֹהִי:
@1082 וַאֲמַר אֶלְעָזָר כַּהֲנָא לְגַבְרֵי חֵילָא דַאֲתוֹ לִקְרָבָא דָא גְזֵירַת אוֹרַיְיתָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1083 בְּרַם יָת דַהֲבָא וְיָת כַסְפָּא יָת נְחָשָׁא יָת פַּרְזְלָא יָת אֲבָצָא וְיָת אֲבָרָא:
@1084 כָּל מִדַעַם דְמִתָּעַל בְּנוּרָא תַּעֲבְרוּנֵיהּ בְּנוּרָא וְיִדְכֵּי בְּרַם בְּמֵי אַדָיוּתָא יִתָּדֵי וְכָל דִי לָא מִתָּעַל בְּנוּרָא תַּעַבְרוּנֵיהּ בְּמַיָא:
@1085 וּתְחַוְרוּן לְבוּשֵׁיכוֹן בְּיוֹמָא שְׁבִיעָאָה וְתִדְכּוּן וּבָתַר כֵּן תַּעֲלוּן לְמַשְׁרִיתָא:
@1086 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@1087 קַבֵּל יָת חוּשְׁבַּן דַבְרַת שִׁבְיָא בֶּאֱנָשָׁא וּבִבְעִירָא אַתְּ וְאֶלְעָזָר כַּהֲנָא וְרֵישֵׁי אֲבָהַת כְּנִשְׁתָּא:
@1088 וּתְפַלֵג יָת דְבַרְתָּא בֵּין גַבְרֵי מַגִיחֵי קְרָבָא דְנְפָקוּ לְחֵילָא וּבֵין כָּל כְּנִשְׁתָּא:
@1089 וְתַפְרֵשׁ נְסִיבָא קֳדָם יְיָ מִן גַבְרֵי מְגִיחֵי קְרָבָא דִנְפָקוּ לְחֵילָא חָד נַפְשָׁא מֵחֲמֵשׁ מְאָה מִן אֱנָשָׁא וּמִן תּוֹרֵי וּמִן חֲמָרֵי וּמִן עָנָא:
@1090 מִפַּלְגוּתְהוֹן תִּסְבוּן וְתִתֵּן לְאֶלְעָזָר כַּהֲנָא אַפְרָשׁוּתָא קֳדָם יְיָ:
@1091 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל תִּסַב חָד דְאִתַּחָד מִן חַמְשִׁין מִן אֱנָשָׁא מִן תּוֹרֵי מִן חֲמָרֵי וּמִן עָנָא מִכָּל בְּעִירָא וְתִתֵּן יָתְהוֹן לְלֵוָאֵי נַטְרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ:
@1092 וַעֲבַד משֶׁה וְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1093 וַהֲוָה דְבַרְתָּא שְׁאָר בִּיזָא דִי בְזוֹ עַמָא דִי נְפָקוּ לְחֵילָא עָנָא שִׁית מְאָה וְשַׁבְעִין וְחַמְשָׁא אַלְפִין:
@1094 וְתוֹרֵי שַׁבְעִין וּתְרֵין אַלְפִין:
@1095 וַחֲמָרֵי שִׁיתִּין וְחָד אַלְפִין:
@1096 וְנַפְשָׁא דֶאֱנָשָׁא מִן נְשַׁיָא דִי לָא יְדָעָא מִשְׁכְּבֵי דְכוּרָא כָּל נַפְשָׁתָא תְּלָתִין וּתְרֵין אַלְפִין:
@1097 וַהֲוַת פַלְגוּתָא חוּלַק גוּבְרַיָא דִנְפָקוּ לְחֵילָא מִנְיַן עָנָא תְּלַת מְאָה וּתְלָתִין וּשְׁבַע אַלְפִין וַחֲמֵשׁ מְאָה:
@1098 וַהֲוָה נְסִיבָא קֳדָם יְיָ מִן עָנָא שִׁית מְאָה שַׁבְעִין וַחֲמֵשׁ:
@1099 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וּנְסֵיבְהוֹן קֳדָם יְיָ שַׁבְעִין וּתְרֵין:
@1100 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה וּנְסֵיבְהוֹן קֳדָם יְיָ שִׁתִּין וְחָד:
@1101 וְנַפְשָׁא אֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין וּנְסֵבְהוֹן קֳדָם יְיָ תְּלָתִין וּתְרֵין נַפְשִׁין:
@1102 וִיהַב משֶׁה יָת נְסִיב אַפְרָשׁוּתָא קֳדָם יְיָ לְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1103 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל דִי פְּלַג משֶׁה מִן גוּבְרַיָא דִנְפָקוּ לְחֵילָא:
@1104 וַהֲוַת פַּלְגוּת כְּנִשְׁתָּא מִן עָנָא תְּלַת מְאָה וּתְלָתִין וְשַׁבְעָא אַלְפִין וַחֲמֵשׁ מְאָה:
@1105 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@1106 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה:
@1107 וְנַפְשָׁא דְאֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין:
@1108 וּנְסֵב משֶׁה מִפַּלְגוּת בְּנֵי יִשְׂרָאֵל יָת דְאִתַּחָד חָד מִן חַמְשִׁין מִן אֱנָשָׁא וּמִן בְּעִירָא וִיהַב יָתְהוֹן לְלֵוָאֵי נַטְּרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@1109 וּקְרִיבוּ לְוָת משֶׁה דִמְמַנָן עַל אַלְפֵי חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָתָא:
@1110 וַאֲמָרוּ לְמשֶׁה עַבְדָיךְ קַבִּילוּ יָת חוּשְׁבַּן גַבְרֵי מְגִיחֵי קְרָבָא דִי עִמָנָא וְלָא שְׁגָא מִנָנָא אֱנָשׁ:
@1111 וְקָרֶבְנָא יָת קוּרְבָּנָא דַיְיָ גְבַר דְאַשְׁכַּח מַאן דִדְהַב שִׁירִין וְשִׁבְּכִין עִזְקָן קַדָשִׁין וּמָחוֹךְ לְכַפָּרָא עַל נַפְשָׁתָנָא קֳדָם יְיָ:
@1112 וּנְסֵיב משֶׁה וְאֶלְעָזר כַּהֲנָא יָת דַהֲבָא מִנְהוֹן כָּל מַאן דְעוֹבָדָא:
@1113 וַהֲוָה כָּל דְהַב אַפְרָשׁוּתָא דְאַפְרָשׁוּ קֳדָם יְיָ שִׁתָּא עַשֲׂר אַלְפִין שְׁבַע מְאָה וְחַמְשִׁין סִלְעִין מִן רַבָּנֵי אַלְפִין וּמִן רַבָּנֵי מַאֲוָתָא:
@1114 גַבְרֵי דְחֵילָא בָּזוּ גְבַר לְנַפְשֵׁיהּ:
@1115 וּנְסֵיב משֶׁה וְאֶלְעָזָר כַּהֲנָא יָת דַהֲבָא מִן רַבָּנֵי אַלְפִין וּמַאֲוָתָא וְאַיְתִיאוּ יָתֵיהּ לְמַשְׁכַּן זִמְנָא דָכְרָנָא לִבְנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@1116 וּבְעִיר סַגִי הֲוָה לִבְנֵי רְאוּבֵן וְלִבְנֵי גָד תַּקֵּיף לַחֲדָא וַחֲזוֹ יָת אֲרַע יַעְזֵר וְיָת אֲרַע גִּלְעָד וְהָא אַתְרָא אֲתַר כְּשַׁר לְבֵית בְּעִיר:
@1117 וַאֲתוֹ בְנֵי גָד וּבְנֵי רְאוּבֵן וַאֲמָרוּ לְמשֶׁה וּלְאֶלְעָזָר כַּהֲנָא וּלְרַבְרְבֵי כְּנִשְׁתָּא לְמֵימָר:
@1118 מַכְלֶלְתָּא וּמַלְבֶּשְׁתָּא וְכוּמְרִין וּבֵית נִמְרִין וּבֵית חוּשְׁבָּנָא וּבַעֲלֵי דְבָבָא וְסִימָא וּבֵית קְבוּרְתָּא דְמשֶׁה וּבְעוֹן:
@1119 אַרְעָא דִי מְחָא יְיָ יַת יָתְבָהָא קֳדָם כְּנִשְׁתָּא דְיִשְׂרָאֵל אֲרַע כָּשְׁרָא לְבֵית בְּעִיר הִיא וּלְעַבְדָיךְ אִית בְּעִיר:
@1120 וַאֲמָרוּ אִם אַשְׁכַּחְנָא רַחֲמִין בְּעֵינָיךְ תִּתְיְהִיב יָת אַרְעָא הָדָא לְעַבְדָךְ לְאַחֲסָנָא לָא תְעַבְרִינָנָא יָת יַרְדְנָא:
@1121 וַאֲמַר משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן הַאֲחֵיכוֹן יֵיתוּן לִקְרָבָא וְאַתּוּן תֵּתְבוּן הָכָא:
@1122 וּלְמָא תוֹנוּן יָת לִבָּא דִבְנֵי יִשְׂרָאֵל מִלְמֶעֱבַר לְאַרְעָא דִיהַב לְהוֹן יְיָ:
@1123 כְּדֵין עֲבָדוּ אֲבָהַתְכוֹן כַּד שְׁלָחִית יָתְהוֹן מֵרְקַם גֵיאָה לְמֶחֱזֵי יָת אַרְעָא:
@1124 וּסְלִיקוּ עַד נַחֲלָא דְאַתְכָּלָא וַחֲזוֹ יָת אַרְעָא וְאוֹנִיאוּ יָת לִבָּא דִבְנֵי יִשְׂרָאֵל בְּדִיל דְלָא לְמֵיעַל לְאַרְעָא דִיהַּב לְהוֹן יְיָ:
@1125 וּתְקֵיף רוּגְזָא דַיְיָ בְּיוֹמָא הַהוּא וְקַיֵים לְמֵימָר:
@1126 אִם יֶחֱזוּן גֻבְרַיָא דִסְלִיקוּ מִמִצְרַיִם מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא יָת אַרְעָא דִי קַיֵימִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב אֲרֵי לָא אַשְׁלִימוּ בָּתַר דַחַלְתִּי:
@1127 אֱלָהֵן כָּלֵב בַּר יְפֻנֶה קְנִזָאָה וִיהוֹשֻׁעַ בַּר נוּן אֲרֵי אַשְׁלִימוּ בָּתַר דַחַלְתָּא דַיְיָ:
@1128 וּתְקֵיף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל וּטְרָדִנוּן בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין עַד דְסַף כָּל דָרָא דְעָבִיד דְבִישׁ קֳדָם יְיָ:
@1129 וְהָא קַמְתּוּן חֲלַף אֲבָהַתְכוֹן תַּלְמִידֵי גֻבְרַיָא חַיָבַיָא לְאוֹסָפָא עוֹד עַל תְּקוֹף רוּגְזָא דַיְיָ לְיִשְׂרָאֵל:
@1130 אֲרֵי תְתוּבוּן מִבָּתַר דַחַלְתֵּיהּ וְיוֹסִיף עוֹד לְאַחֲרוּתְהוֹן בְּמַדְבְּרָא וּתְחַבְּלוּן לְכָל עַמָא הָדֵין:
@1131 וּקְרִיבוּ לְוָתֵיהּ וַאֲמָרוּ חַטְרִין דְעָאן נִבְנֵי לִבְעִירָנָא הָכָא וְקִרְוִין לְטַפְלָנָא:
@1132 וַאֲנַחְנָא נִזְדָרֵיז מַבְעִין קֳדָם בְּנֵי יִשְׂרָאֵל עַד דִי נְעֵלִינוּן לְאַתְרֵהוֹן וְיֵתְבוּן טַפְלָנָא בְּקִרְוִין כְּרִיכִין מִן קֳדָם יַתְבֵי אַרְעָא:
@1133 לָא נְתוּב לְבֵיתָנָא עַד דְיַחְסְנוּן בְּנֵי יִשְׂרָאֵל גְבַר אַחֲסַנְתֵּיהּ:
@1134 אֲרֵי לָא נַחֲסִין עִמְהוֹן מֵעִבְרָא לְיַרְדְנָא וּלְהָלָא אֲרֵי קַבֵּילְנָא אַחֲסַנְתָּנָא לָנָא מֵעִבְרָא לְיַרְדְנָא מַדִינְחָא:
@1135 וַאֲמַר לְהוֹן משֶׁה אִם תַּעְבְדוּן יָת פִּתְגָמָא הָדֵין אִם תִּזְדָרְזוּן קֳדָם עַמָא דַיְיָ לִקְרָבָא:
@1136 וְיַעְבֵר לְכוֹן כָּל דִמְזָרֵז יָת יַרְדְנָא קֳדָם עַמָא דַיְיָ עַד דִיתָרַךְ יָת בַּעֲלֵי דְבָבוֹהִי מִן קֳדָמוֹהִי:
@1137 וְתִתְכְּבֵשׁ אַרְעָא קֳדָם עַמָא דַיְיָ וּבָתַר כֵּן תְּתוּבוּן וּתְהוֹן זַכָּאִין מִן קֳדָם יְיָ וּמִיִשְׂרָאֵל וּתְהֵי אַרְעָא הָדָא לְכוֹן לְאַחֲסָנָא קֳדָם יְיָ:
@1138 וְאִם לָא תַעְבְדוּן כֵּן הָא חַבְתּוּן קֳדָם יְיָ וְתֵדְעוּן חוֹבַתְכוֹן דְתַשְׁכַּח יָתְכוֹן:
@1139 בְּנוּ לְכוֹן קִרְוִין לְטַפְלְכוֹן וְחַטְרִין לְעַנְכוֹן וּדְיִפּוֹק מִפּוּמְכוֹן תַּעְבְּדוּן:
@1140 וַאֲמָרוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמשֶׁה לְמֵימָר עַבְדָיךְ יַעְבְדוּן כְּמָא דִי רִבּוֹנִי מְפַקֵד:
@1141 טַפְלָנָא נְשָׁנָא גֵיתָנָא וְכָל בְּעִירָנָא יְהוֹן תַּמָן בְּקִרְוֵי גִלְעָד:
@1142 וְעַבְדָיךְ יַעְבְּרוּן כָּל מְזָרַז חֵילָא קֳדָם עַמָא דַיְיָ לִקְרָבָא כְּמָא דִי רִבּוֹנִי מְמַלֵל:
@1143 וּפַקֵד לְהוֹן משֶׁה יָת אֶלְעָזָר כַּהֲנָא וְיָת יְהוֹשֻׁעַ בַּר נוּן וְיָת רֵישֵׁי אֲבָהַת שִׁבְטַיָא לִבְנֵי יִשְׂרָאֵל:
@1144 וַאֲמַר משֶׁה לְהוֹן אִם יַעְבְּרוּן בְּנֵי גָד וּבְנֵי רְאוּבֵן עִמְכוֹן יָת יַרְדְנָא כָּל דִמְזָרַז לִקְרָבָא קֳדָם עַמָא דַיְיָ וְתִתְכְּבֵשׁ אַרְעָא קֳדָמֵיכוֹן וְתִתְּנוּן לְהוֹן יָת אַרְעָא דְגִלְעָד לְאַחֲסָנָא:
@1145 וְאִם לָא יַעְבְרוּן מְזָרְזִין עִמְכוֹן וְיַחְסְנוּן בֵּינֵיכוֹן בְּאַרְעָא דִכְנָעַן:
@1146 וְאָתִיבוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמֵימָר יָת דִי מַלִיל יְיָ לְעַבְדָךְ כֵּן נַעְבֵּד:
@1147 נַחְנָא נַעֲבֵר מְזָרְזִין קֳדָם עַמָא דַיְיָ לְאַרְעָא דִכְנָעַן וְעִמָנָא אֲחוּדַת אַחֲסַנְתָּנָא מֵעִבְרָא לְיַרְדְנָא:
@1148 וִיהַב לְהוֹן משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה בַּר יוֹסֵף יָת מַלְכְּוַת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה וְיָת מַלְכְּוַת עוֹג מַלְכָּא דְמַתְנָן אַרְעָא לְקִרְוָהָא בִּתְחוּמִין קִרְוֵי אַרְעָא סְחוֹר סְחוֹר:
@1149 וּבְנוֹ בְנֵי גָד יָת דִיבוֹן וְיָת עֲטָּרוֹת וְיָת עֲרֹעֵר:
@1150 וְיָת עַטְרוֹת שׁוֹפָן וְיָת יַעְזֵר וְרָמָתָא:
@1151 וְיָת בֵּית נִמְרָה וְיָת בֵּית הָרָן קִרְוִין כְּרִיכָן וְחַטְרִין דְעָאן:
@1152 וּבְנֵי רְאוּבֵן בְּנוֹ יָת חֶשְׁבּוֹן וְיָת אֶלְעָלֵא וְיָת קִרְיָתָיִם:
@1153 וְיָת נְבוֹ וְיָת בַּעַל מְעוֹן מַקְפָן שְׁמָהָן וְיָת שִׂבְמָה וּקְרוֹ בִשְׁמָהָן יָת שְׁמָהַת קִרְוַיָא דִי בְנוֹ:
@1154 וַאֲזָלוּ בְּנֵי מָכִיר בַּר מְנַשֶׁה לְגִלְעָד וְכִבְשׁוּהָ וְתָרִיךְ יָת אֱמוֹרָאָה דִי בָּהּ:
@1155 וִיהַב משֶׁה יָת גִלְעָד לְמָכִיר בַּר מְנַשֶׁה וִיתֵב בַּהּ:
@1156 וְיָאִיר בַּר מְנַשֶׁה אֲזַל וּכְבַשׁ יָת כַּפְרָנֵיהוֹן וּקְרָא יַתְהֶן כַּפְרָנֵי יָאִיר:
@1157 וְנֹבַח אֲזַל וּכְבַשׁ יָת קְנַת וְיָת כַּפְרָנָהָא וּקְרָא לָה נֹבַח בִּשְׁמֵהּ: פפפ:
@1158 אִלֵין מַטְלָנֵי בְנֵי יִשְׂרָאֵל דִי נְפָקוּ מֵאַרְעָא דְמִצְרַיִם לְחֵילֵיהוֹן בִּידָא דְמשֶׁה וְאַהֲרֹן:
@1159 וּכְתַב משֶׁה יָת מַפְּקָנֵיהוֹן לְמַטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וְאִלֵין מַטְלָנֵיהוֹן לְמַפְּקָנֵיהוֹן:
@1160 וּנְטָלוּ מֵרַעְמְסֵס בְּיַרְחָא קַדְמָאָה בְּחַמְשָׁא עַשְׂרָא יוֹמָא לְיַרְחָא קַדְמָאָה מִבָּתַר יוֹמָא דְפִסְחָא נְפָקוּ בְנֵי יִשְרָאֵל בְּרֵישׁ גְלֵי לְעֵינֵי כָּל מִצְרָאֵי:
@1161 וּמִצְרָאֵי מְקַבְּרִין יָת דִי קְטַל יְיָ בְּהוֹן כָּל בּוּכְרָא וּבְטַעֲוַתְהוֹן עָבַד יְיָ דִינִין:
@1162 וּנְטָלוּ בְנֵי יִשְׂרָאֵל מֵרַעְמְסֵס וּשְׁרוֹ בְּסֻכֹּת:
@1163 וּנְטָּלוּ מִסֻכֹּת וּשְרוֹ בְאֵתָם דִי בִּסְטַר מַדְבְּרָא:
@1164 וּנְטָלוּ מֵאֵתָם וְתָב עַל פּוּם חִירָתָא דִי קֳדָם בְּעֵיל צְפוֹן וּשְׁרוֹ קֳדָם מִגְדֹל:
@1165 וּנְטָלוּ מִן פּוּם חִירָתָא וַעֲבָרוּ בְּגוֹ יַמָא לְמַדְבְּרָא וַאֲזָלוּ מַהֲלַךְ תְּלָתָא יוֹמִין בְּמַדְבְּרָא דְאֵתָם וּשְׁרוֹ בְּמָרָה:
@1166 וּנְטָלוּ מִמָרָה וַאֲתוֹ לְאֵילִם וּבְאֵילִם תְּרֵי עֲשַׂר מַבּוּעִין דְמַיִן וְשַׁבְעִין דִקְלִין וּשְׁרוֹ תַמָן:
@1167 וּנְטָלוּ מֵאֵילִם וּשְׁרוֹ עַל יַמָא דְסוּף:
@1168 וּנְטָּלוּ מִיַמָא דְסוּף וּשְׁרוֹ בְּמַדְבְּרָא דְסִין:
@1169 וּנְטָלוּ מִמַדְבְּרָא דְסִין וּשְׁרוֹ בְּדָפְקָה:
@1170 וּנְטָלוּ מִדָפְקָה וּשְׁרוֹ בְּאָלוּשׁ:
@1171 וּנְטָלוּ מֵאָלוּשׁ וּשְׁרוֹ בִּרְפִידִם וְלָא הֲוָה תַמָן מַיָא לְעַמָא לְמִשְׁתֵּי:
@1172 וּנְטָלוּ מֵרְפִידִם וּשְׁרוֹ בְּמַדְבְּרָא דְסִינָי:
@1173 וּנְטָלוּ מִמַדְבְּרָא דְסִינָי וּשְׁרוֹ בְּקִבְרֵי דִמְשַׁאֲלֵי:
@1174 וּנְטָּלוּ מִקִבְרֵי דִמְשַׁאֲלֵי וּשְׁרוֹ בַּחֲצֵרוֹת:
@1175 וּנְטָלוּ מֵחֲצֵרֹת וּשְׁרוֹ בְּרִתְמָה:
@1176 וּנְטָלוּ מֵרִתְמָה וּשְׁרוֹ בְּרִמוֹן פָּרֶץ:
@1177 וּנְטָלוּ מֵרִמוֹן פָּרֶץ וּשְׁרוֹ בְּלִבְנָה:
@1178 וּנְטָלוּ מִלִבְנָה וּשְׁרוֹ בְּרִסָה:
@1179 וּנְטָלוּ מֵרִסָה וּ:שׁרוֹ בִּקְהֵלָתָה:
@1180 וּנְטָלוּ מִקְהֵלָתָה וּשְׁרוֹ בְּטוּרָא דְשָׁפֶר:
@1181 וּנְטָלוּ מִטוּרָא דְשָׁפֶר וּשְׁרוֹ בַּחֲרָדָה:
@1182 וּנְטָּלוּ מֵחֲרָדָה וּשְׁרוֹ בְּמַקְהֵלוֹת:
@1183 וּנְטָלוּ מִמַקְהֵלוֹת וּשְׁרוֹ בְּתָחַת:
@1184 וּנְטָלוּ מִתָּחַת וּשְׁרוֹ בְּתָרַח:
@1185 וּנְטָלוּ מִתָּרַח וּ:שׁרוֹ בְּמִתְקָה:
@1186 וּנְטָלוּ מִמִתְקָה וּשְׁרוֹ בְּחַשְׁמוֹנָה:
@1187 וּנְטָלוּ מֵחַשְׁמוֹנָה וּשְׁרוֹ בְּמוֹסֵרוֹת:
@1188 וּנְטָלוּ מִמוֹסֵרוֹת וּשְׁרוֹ בִּבְנֵי יַעֲקָן:
@1189 וּנְטָּלוּ מִבְּנֵי יַעֲקָן וּשְׁרוֹ בְּחוֹר הַגִדְגָד:
@1190 וּנְטָלוּ מֵחוֹר הַגִדְגָד וּשְׁרוֹ בְּיָטְבָתָה:
@1191 וּנְטָלוּ מִיָטְבָתָה וּשְׁרוֹ בְּעַבְרֹנָה:
@1192 וּנְטָלוּ מֵעַבְרוֹנָה וּשְׁרוֹ בְּעֶצְיוֹן גָבֶר:
@1193 וּנְטָלוּ מֵעֶצְיוֹן גָבֶר וּשְׁרוֹ בְּמַדְבְּרָא דְצִן הִיא רְקָם:
@1194 וּנְטָלוּ מֵרְקָם וּשְׁרוֹ בְּהוֹר טוּרָא בִּסְיָפֵי אַרְעָא דֶאֱדוֹם:
@1195 וּסְלֵק אַהֲרֹן כַּהֲנָא לְהוֹר טּוּרָא עַל מֵימְרָא דַיְיָ וּמִית תַּמָן בִּשְׁנַת אַרְבְּעִין לְמֵפַּק בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם בְּיַרְחָא חֲמִשָׁאָה בּחַד לְיַרְחָא:
@1196 וְאַהֲרֹן בַּר:מְאָה וְעַשְׂרִין וּתְלַת שְׁנִין כַּד מִית בְּהוֹר טוּרָא:
@1197 וּשְׁמַע כְּנַעֲנָאָה מַלְכָּא דַעֲרָד וְהוּא יָתֵב בִּדְרוֹמָא בְּאַרְעָא דִכְנָעַן בְּמֵיתֵי בְּנֵי יִשְׂרָאֵל:
@1198 וּנְטָלוּ מֵהוֹר טוּרָא וּשְׁרוֹ בְּצַלְמוֹנָה:
@1199 וּנְטָלוּ מִצַלְמוֹנָה וּשְׁרוֹ בְּפוּנוֹן:
@1200 וּנְטָלוּ מִפּוּנוֹן וּשְׁרוֹ בְּאֹבוֹת:
@1201 וּנְטָלוּ מֵאֹבוֹת וּשְׁרוֹ בִּמְגִזַת עֲבָרָאֵי בִּתְחוּם מוֹאָב:
@1202 וּנְטָלוּ מִמְגִזָתָא וּשְׁרוֹ:בּדִיבוֹן גָד:
@1203 וּנְטָלוּ מִדִיבוֹן גָד וּשְׁרוֹ בְּעַלְמוֹן דִבְלָתָיְמָה:
@1204 וּנְטָלוּ מֵעַלְמוֹן דִבְלָתָיְמָה וּשְׁרוֹ בְּטוּרֵי דַעֲבָרָאֵי דִקֳדָם נְבוֹ:
@1205 וּנְטָלוּ מִטוּרֵי דַעֲבָרָאֵי וּשְׁרוֹ בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵחוֹ:
@1206 וּשְׁרוֹ עַל יַרְדְנָא מִבֵּית יְשִׁימוֹת עַד מֵישַׁר שִׁטִין בְּמֵישְׁרַיָא דְמוֹאָב:
@1207 וּמַלִיל יְיָ עִם משֶׁה בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵחוֹ לְמֵימָר:
@1208 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְאַרְעָא דִכְנָעַן:
@1209 וּתְתָרְכוּן יָת כָּל יָתְבֵי אַרְעָא מִן קֳדָמֵיכוֹן וְתֵבְדוּן יָת כָּל בֵּית סִגְדַתְהוֹן וְיָת כָּל צַלְמֵי מַתְּכַתְהוֹן תֵּבְדוּן וְיָת כָּל בָּמַתְהוֹן תְּשֵׁצוּן:
@1210 וּתְתָרְכוּן יָת יָתְבֵי אַרְעָא וְתֵיתְבוּן בָּהּ אֲרֵי לְכוֹן יְהָבִית יָת אַרְעָא לְמֵירַת יָתָהּ:
@1211 וְתַחְסְנוּן יָת אַרְעָא בְעַדְבָא לְזַרְעֲיַתְכוֹן לְסַגִיאֵי תַּסְגוּן יָת אַחֲסַנְתְּהוֹן וְלִזְעִירֵי תַּזְעִירוּן יָת אַחֲסַנְתְּהוֹן לִדְיִפּוֹק לֵהּ תַּמָן עַדְבָא דִי לֵהּ יְהֵי לְשִׁבְטֵי אֲבָהַתְכוֹן תַּחְסְנוּן:
@1212 וְאִם לָא תְתָרְכוּן יָת יָתְבֵי אַרְעָא מִן קֳדָמֵיכוֹן וִיהֵי דִי תַשְׁאֲרוּן מִנְהוֹן לְסִיעַן נַטְלַן זְיַן לְקִבְלֵיכוֹן וּלְמַשִׁרְיַן מַקְפַּנְכוֹן וִיעִיקוּן לְכוֹן עַל אַרְעָא דִי אַתּוּן יָתְבִין בָּהּ:
@1213 וִיהֵי כְּמָא דִי חֲשָׁבִית לְמֶעְבַּד לְהוֹן אַעֲבֵד לְכוֹן:
@1214 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1215 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי אַתּוּן עָאלִין לְאַרְעָא דִכְנָעַן דָא אַרְעָא דִי תִתְפְּלֵג לְכוֹן בְּאַחֲסָנָא אַרְעָא דִכְנַעַן לִתִחוּמָאָה:
@1216 וִיהֵי לְכוֹן רוּחַ דָרוֹמָא מִמַדְבְּרָא דְצִן עַל תְּחוּמֵי אֱדוֹם וִיהֵי לְכוֹן תְּחוּם דָרוֹמָא מִסְיָפֵי יַמָא דְמִלְחָא קִדוּמָא:
@1217 וְיַסְחַר לְכוֹן תְּחוּמָא מִדְרוֹמָא לְמַסְקָנָא דְעַקְרַבִּים וִיעִבַר לְצִן וִיהוֹן מַפְקָנוֹהִי מִדְרוֹמָא לִרְקָם גֵיאָה וְיִפּוֹק לַחֲצַר אַדָר וִיעִבַר לְעַצְמוֹן:
@1218 וְיַסְחַר תְּחוּמָא מֵעַצְמוֹן לְנַחֲלָא דְמִצְרָיִם וִיהוֹן מַפְקָנוֹהִי לְיַמָא:
@1219 וּתְחוּם מַעַרְבָא וִיהֵי לְכוֹן יַמָא רַבָּא וּתְחוּמֵהּ דֵין יְהֵא לְכוֹן תְּחוּם מַעֲרְבָא:
@1220 וְדֵין יְהֵי לְכוֹן תְּחוּם צִפּוּנָא מִן יַמָא רַבָּא תְּכַוְנוּן לְכוֹן לְהוֹר טוּרָא:
@1221 מֵהוֹר טוּרָא תְּכַוְנוּן לִמְטֵי חֲמָת וִיהוֹן מַפְּקָנוֹהִי דִתְחוּמָא לִצְדָד:
@1222 וְיִפּוֹק תְּחוּמָא לְזִפְרוֹן וִיהוֹן מַפְּקָנוֹהִי לַחֲצַר עֵינָן דֵין יְהֵי לְכוֹן תְּחוּם צִפּוּנָא:
@1223 וּתְכַוְנוּן לְכוֹן לִתְחוּם קִדוּמָא מֵחֲצַר עֵינָן לִשְׁפָם:
@1224 וְיֵחוֹת תְּחוּמָא מִשְׁפָם לְרִבְלָה מִמַדְנַח לָעָיִן וְיֵחוֹת תְּחוּמָא וְיִמְטֵי עַל כֵּיף יַם גִנוֹסַר קִדוּמָא:
@1225 וְיֵחוֹת תְּחוּמָא לְיַרְדְנָא וִיהוֹן מַפְקָנוֹהִי לְיַמָא דְמִלְחָא דָא תְהֵי לְכוֹן אַרְעָא לִתְחוּמָאָה סְחוֹר סְחוֹר:
@1226 וּפַקִיד משֶׁה יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר דָא אַרְעָא דְתִתְחַסְנוּן יָתַהּ בְּעַדְבָא דִי פַקֵיד יְיָ לְמִתַּן לְתִשְׁעַת שִׁבְטִין וּפַלְגוּת שִׁבְטָא:
@1227 אֲרֵי קַבִּילוּ שִׁבְטָא דִבְנֵי רְאוּבֵן לְבֵית אֲבָהַתְהוֹן וְשִׁבְטָא דִבְנֵי גָד לְבֵית אֲבָהַתְהוֹן וּפַלְגוּת שִׁבְטָא דִמְנַשֶׁה קַבִּילוּ אַחֲסַנְתְּהוֹן:
@1228 תְּרֵין שִׁבְטִין וּפַלְגוּת שִׁבְטָא קַבִּילוּ אַחֲסַנְתְּהוֹן מֵ עִבְרָא לְיַרְדְנָא דִירֵחוֹ קִדוּמָא מַדִינְחָא:
@1229 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1230 אִלֵין שְׁמָהַת גֻבְרַיָא דִי יַחְסְנוּן לְכוֹן יָת אַרְעָא אֶלְעָזָר כַּהֲנָא וִיהוֹשֻׁע בַּר נוּן:
@1231 וְרַבָּא חָד רַבָּא חָד מִשִׁבְטָא תִּסְבוּן לְאַחֲסָנָא יָת אַרְעָא:
@1232 וְאִלֵין שְׁמָהַת גֻבְרַיָא לְשִׁבְטָא דִיהוּדָה כָּלֵב בַּר יְפֻנֶה:
@1233 וּלְשִׁבְטָא דִבְנֵי שִׁמְעוֹן שְׁמוּאֵל בַּר עַמִיהוּד:
@1234 לְשִׁבְטָא דְבִנְיָמִן אֱלִידָד בַּר כִּסְלוֹן:
@1235 וּלְשִׁבְטָא דִבְנֵי דָן רַבָּא בֻּקִי בַּר יָגְלִי:
@1236 לִבְנֵי יוֹסֵף לְשִׁבְטָא דִבְנֵי מְנַשֶׁה רַבָּא חַנִיאֵל בַּר אֵפוֹד:
@1237 וּלְשִׁבְטָא דִבְנֵי אֶפְרָיִם רַבָּא קְמוּאֵל בַּר שִׁפְטָן:
@1238 וּלְשִׁבְטָא דִבְנֵי זְבוּלֻן רַבָּא אֱלִיצָפָן בַּר פַּרְנָךְ:
@1239 וּלְשִׁבְטָא דִבְנֵי יִשָׂשכָר רַבָּא פַלְטִיאֵל בַּר עַזָן:
@1240 וּלְשִׁבְטָּא דִבְנֵי אָשֵׁר רַבָּא אֲחִיהּוּד בַּר שְׁלֹמִי:
@1241 וּלְשִׁבְטָא דִבְנֵי נַפְתָּלִי רַבָּא פְּדַהְאֵל בַּר עַמִיהוּד:
@1242 אִלֵין דִי פַּקִיד יְיָ לְאַחֲסָנָא יָת בְּנֵי יִשְׂרָאֵל בְּאַרְעָא דִכְנָעַן:
@1243 וּמַלִיל יְיָ עִם משֶׁה בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ לְמֵימָר:
@1244 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִתְּנוּן לְלֵוָאֵי מֵאַחֲסָנַת אֲחוּדַתְהּוֹן קִרְוִין לְמִתָּב וְרֶוַח לְּקִרְוַיָא סַחֲרָנֵיהוֹן תִּתְּנוּן לְלֵוָאֵי:
@1245 וִיהוֹן קִרְוַיָא לְהוֹן לְמִתָּב וְרַוְחֵיהוֹן יְהוֹן לִבְעִירְהוֹן וּלְקִנְיָנֵיהוֹן וּלְכָל חֵוַתְהוֹן:
@1246 וּרְוָחֵי קִרְוַיָא דִי תִתְּנוּן לְלֵוָאֵי מִכּוֹתֵל קַרְתָּא וּלְבָרָא אֲלַף אַמִין סְחוֹר סְחוֹר:
@1247 וְתִמְשְׁחוּן מִבָּרָא לְקַרְתָּא יָת רוּחַ קִדוּמָא תְּרֵין אַלְפִין בְּאַמִין וְיָת רוּחַ דְרוֹמָא תְּרֵין אַלְפִין בְּאַמִין וְיָת רוּחַ מַעֲרְבָא תְּרֵין אַלְפִין בְּאַמִין וְיָת רוּחַ צִפּוּנָא תְּרֵין אַלְפִין בְּאַמִין וְקַרְתָּא בִמְצִיעָא דֵין יְהֵי לְהוֹן רְוָחֵי קִרְוַיָא:
@1248 וְיָת קִרְוַיָא דִי תִתְּנוּן לְלֵוָאֵי יָת שִׁית קִרְוֵי שֵׁזָבוּתָא דִי תִתְּנוּן לְמֵעֲרַק תַּמָן קָטוֹלָא וַעֲלֵיהוֹן תִּתְּנוּן אַרְבְּעִין וְתַרְתֵּין קִרְוִין:
@1249 כָּל קִרְוַיָא דִי תִתְּנוּן לְלֵוָאֵי אַרְבְּעִין וְתַמְנֵי קִרְוִין יָתְהֶן וְיָת רְוָחֵיהֶן:
@1250 וְקִרְוַיָא דִי תִתְּנוּן מֵאֲחוּדַת בְּנֵי יִשְׂרָאֵל מִן סַגִיאֵי תַּסְגוּן וּמִן זְעִירֵי תַּזְעִירוּן גְבַר כְּפוּם אַחֲסַנְתֵּהּ דִי יַחְסְנוּן יִתֵּן מִקִרְווֹהִי לְלֵוָאֵי:
@1251 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@1252 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְאַרְעָא דִכְנָעַן:
@1253 וּתְזַמְנוּן לְכוֹן קִרְוִין קִרְוֵי שֵׁזָבוּתָא יֶהֶוְיָן לְכוֹן וְיַעֲרוֹק לְתַמָן קָטוֹלָא דְיִקְטוֹל נַפְשָׁא בְּשָׁלוּ:
@1254 וִיהוֹן לְכוֹן קִרְוַיָא לְשֵׁזָבָא מִגָאֵל דְמָא וְלָא יְמוּת קָטוֹלָא עַד דְיֵקוּם קֳדָם כְּנִשְׁתָּא לְדִינָא:
@1255 וְקִרְוַיָא דִי תִתְּנוּן שִׁית קִרְוֵי שֵׁזָבוּתָא יֶהֶוְיַן לְכוֹן:
@1256 יָת תְּלַת קִרְוַיָא תִתְּנוּן מֵעִבְרָא לְיַרְדְנָא וְיָת תְּלַת קִרְוַיָא תִתְּנוּן בְּאַרְעָא דִכְנָעַן קִרְוֵי שֵׁזָבוּתָא יֶהֶוְיָן:
@1257 לִבְנֵי יִשְׂרָאֵל וּלְגִיוֹרַיָא וּלְתוֹתָבַיָא דְבֵינֵיכוֹן יֶהֶוְיַן שִׁית קִרְוַיָא הָאִלֵין לְשֵׁזָבָא לְמֵעֲרַק לְתַמָן כָּל דְיִקְטוֹל נַפְשָׁא בְּשָׁלוּ:
@1258 וְאִם בְּמָאן דְפַרְזְלָא מְחָהִי וְקַטְלֵהּ קָטוֹלָא הוּא אִתְקְטָלָא יִתְקְטֵל קָטוֹלָא:
@1259 וְאִם בְּאַבְנָא דְמִתְנָסְבָא בִידָא דְהִיא כְמִסַת דִי יְמוּת בַּהּ מְחָהִי וְקָטְלֵהּ קָטוֹלָא הוּא אִתְקְטָלָא יִתְקְטֵל קָטוֹלָא:
@1260 אוֹ בְּמָאן דְעָא דְמִתְנָסֵב בִּידָא דְהִיא כְמִסַת דִי יְמוּת בֵּה מְחָהִי וְקַטְּלֵהּ קָטוֹלָא הוּא אִתְקְטָלָא יִתְקְטַל קָטוֹלָא:
@1261 גָאֵל דְמָא הוּא יִקְטוֹל יָת קָטוֹלָא כַּד אִתְחַיַב לֵהּ מִן דִינָא הוּא יְקַטְלִנֵהּ:
@1262 וְאִם בְּסַנְאָה דְחָהִי אוֹ רְמָא עֲלוֹהִי בְּכַמְנָא וְקַטְלֵהּ:
@1263 אוֹ בִדְבָבוּ מְחָהִי בִידֵהּ וְקָטְלֵהּ אִתְקְטָלָא יִתְקְטֵל מַחְיָא קָטוֹלָא הוּא גָאֵל דְמָא יִקְטוֹל יָת קָטוֹלָא כַּד אִתְחַיֵב לֵיהּ מִן דִינָא:
@1264 וְאִם בִּתְכֵיף בְּלָא דְבָבוּ דְחָהִי אוֹ רְמָא עֲלוֹהִי כָּל מָאן בְּלָא כְמָן לֵיהּ:
@1265 אוֹ בְּכָל אַבְנָא דְהִיא כְמִסַת דִי יְמוּת בָּהּ בְּלָא חָזֵי וּרְמָא עֲלוֹהִי וְקָטְלֵהּ וְהוּא לָא סָנֵי לֵיהּ וְלָא תָבַע בִּישְׁתֵיהּ:
@1266 וִידוּנוּן כְּנִשְׁתָּא בֵּין מַחְיָא וּבֵין גָאֵל דְמָא עַל דִינַיָא הָאִלֵין:
@1267 וִישֵׁזְבוּן כְּנִשְׁתָּא יָת קָטוֹלָא מִיַד גָאֵל דְמָא וִיתִיבוּן יָתֵיהּ כְּנִשְׁתָּא לְקִרְיַת שֵׁזָבוּתֵהּ דִי עֲרַק לְתַמָן וִיתֵב בָּהּ עַד דִימוּת כַּהֲנָא רַבָּא דִי רַבֵּי יָתֵהּ בִּמְשַׁח קוּדְשָׁא:
@1268 וְאִם מִפַּק יִפּוֹק קָטוֹלָא יָת תְּחוּם קִרְיַת שֵׁזָבוּתֵהּ דִי עֲרַק לְתַמָן:
@1269 וְיַשְׁכַּח יָתֵהּ גָאֵל דְמָא מִבָּרָא לִתְחוּם קִרְיַת שֵׁזָבוּתֵהּ וְיִקְטוֹל גָאֵל דְמָא יָת קָטוֹלָא לֵית לֵהּ דְמָא:
@1270 אֲרֵי בְקִרְיַת שֵׁזָבוּתֵהּ יִתֵּב עַד דִימוּת כַּהֲנָא רַבָּא וּבָתַר דִימוּת כַּהֲנָא רַבָּא יְתוּב קָטּוֹלָא לְאֲרַע אַחֲסַנְתֵּה:
@1271 וִיהוֹן אִלֵין לְכוֹן לִגְזֵרַת דִין לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@1272 כָּל דְיִקְטוֹל נַפְשָׁא לְפוּם סַהֲדִין יִקְטוֹל יָת קָטוֹלָא וְסָהִיד חַד לָא יַסְהִד בֶּאֱנַשׁ לְמִקְטָל:
@1273 וְלָא תְקַבְּלוּן מָמוֹן עַל אֱנַשׁ קָטוֹל דִי הוּא חַיָב לְמִקְטָל אֲרֵי אִתְקְטָלָא יִתְקְטֵל:
@1274 וְלָא תְקַבְּלוּן מָמוֹן לְמֵעֲרוֹק לְקִרְיַת שֵׁזָבוּתֵהּ לְמֵתוּב לְמִתַּב בְּאַרְעָא עַד דִימוּת כַּהֲנָא:
@1275 וְלָא תְּחַיְבוּן יָת אַרְעָא דִי אַתּוּן בָּהּ אֲרֵי דְמָא הוּא מְחַיַב יָת אַרְעָא וּלְאַרְעָא לָא מִתְכַפֵּר עַל דַם זַכַּאי דִי אִתְאַשֵׁד בַּהּ אֶלָהֵן בְּדַם אַשְׁדֵהּ:
@1276 וְלָא תְסַאֲבוּן יָת אַרְעָא דִי אַתּוּן יָתְבִין בָּהּ דִי שְׁכִנְתִּי שַׁרְיָא בְּגַוָהּ אֲרֵי אֲנָא יְיָ דִשְׁכִנְתִּי שַׁרְיָא בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@1277 וְקָרִיבוּ רֵישֵׁי אֲבָהָתָא לְּזַרְעִית בְּנֵי גִלְעָד בַּר מָכִיר בַּר מְנַשֶׁה מִזַרְעֲיַת בְּנֵי יוֹסֵף וּמַלִילוּ קֳדָם משֶׁה וְקָדָם רַבְרְבַיָא רֵישֵׁי אֲבָהָתָא לִבְנֵי יִשְׂרָאֵל:
@1278 וַאֲמָרוּ יָת רִבּוֹנִי פַּקִיד יְיָ לְמִתַּן יָת אַרְעָא בְאַחֲסָנָא בְּעַדְבָא לִבְנֵי יִשְׂרָאֵל וְרִבּוֹנִי אִתְפַּקֵד בְּמֵימְרָא דַיְיָ לְמִתַּן יָת אַחֲסָנַת צְלָפְחָד אָחוּנָא לִבְנָתֵהּ:
@1279 וִיהֶוְיַן לְחַד מִבְּנֵי שִׁבְטַיָא דִבְנֵי יִשְׂרָאֵל לִנְשִׁין וְתִתְמְנַע אַחֲסַנְתְּהוֹן מֵאַחֲסָנַת אֲבְהָתָנָא וְתִתּוֹסַף עַל אַחֲסָנַת שִׁבְטַיָא דִיֶהֶוְיָן לְהוֹן וּמֵעֲדַב אַחֲסַנְתָּנָא יִתְמְנָע:
@1280 וְאִם יְהֵי יוֹבֵלָא לִבְנֵי יִשְׂרָאֵל וְתִתּוֹסַף אַחֲסַנְתְּהוֹן עַל אַחֲסָנַת שִׁבְטָא דִי תְהֶוְיָן לְהוֹן וּמֵאַחֲסָנַת שִׁבְטָא דְאֲבְהָתָנָא יִתְמְנַע אַחֲסַנְתְּהֶן:
@1281 וּפַקִיד משֶׁה יָת בְּנֵי יִשְׂרָאֵל עַל מֵימְרָא דַיְיָ לְמֵימָר יָאוּת שִׁבְטָא דִבְנֵי יוֹסֵף מְמַלְלִין:
@1282 דֵין פִּתְגָמָא דִי פַקִיד יְיָ לִבְנַת צְלָפְחָד לְמֵימַר לִדְתַקִין בְּעֵינֵיהוֹן תְּהֶוְיַן לִנְשִׁין בְּרַם לְזַרְעִית שִׁבְטָא דַאֲבוּהֶן תְּהֶוְיַן לִנְשִׁין:
@1283 וְלָא תַסְחַר אַחֲסָנָא לִבְנֵי יִשְׂרָאֵל מִשִׁבְטָא לְשִׁבְטָא אֲרֵי גְבַר בְּאַחֲסָנַת שִׁבְטָא דַאֲבָהָתוֹהִי יִדְבְּקוּן בְּנֵי יִשְׂרָאֵל:
@1284 וְכָל בְּרַתָּא יַרְתַת אַחֲסָנָא מִשִׁבְטַּיָא דִבְנֵי יִשְׂרָאֵל לְחַד מִזַרְעִית שִׁבְטָא דַאֲבוּהָא תְּהֵי לְאִנְתּוּ בְּדִיל דְיֵרְתוּן בְּנֵי יִשְׂרָאֵל גְבַר אַחֲסָנַת אֲבָהָתוֹהִי:
@1285 וְלָא תַסְחַר אַחֲסָנָא מִשִׁבְטָא לְשִׁבְטָא אוֹחֲרָנָא אֲרֵי גְבַר בְּאַחֲסַנְתֵּהּ יִדְבְּקוּן שִׁבְטַיָא דִבְנֵי יִשְׂרָאֵל:
@1286 כְּמָא דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנַת צְלָפְחָד:
@1287 וַהֲוָאָה מַחְלָה תִרְצָה וְחָגְלָה וּמִלְכָּה וְנֹעָה בְּנַת צְלָפְחָד לִבְנֵי אֲחֵי אֲבוּהֶן לִנְשִׁין:
@1288 מִזַרְעֲיַת בְּנֵי מְנַשֶׁה בַר יוֹסֵף הֲוָאָה לִנְשִׁין וַהֲוַת אַחֲסַנְתְּהֶן עַל שִׁבְטָא זַרְעִית אֲבוּהֶן:
@1289 אִלֵין פִּקוּדַיָא וְדִינַיָא דִי פַקִיד יְיָ בִּידָא דְמשֶׁה לְוַת בְּנֵי יִשְׂרָאֵל בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ: חזק:

@1 **וידבר. במדבר סיני באחד לחדש.** וגו' . מתוך חבתן לפניו מונה אותם כל שעה, כשיצאו ממצרים מנאן, וכשנפלו בעגל מנאן לידע מנין הנותרים. כשבא להשרות שכינתו עליהן מנאן' באחד בניסן הוקם המשכן, ובאחד באיר מנאם:
@2 **למשפחתם.** דע מנין כל שבט ושבט: **לבית אבתם.** מי שאביו משבט אחד ואמו משבט אחר יקום על שבט אביו: **לגלגלתם.** על ידי שקלים בקע לגלגלת:
@3 **כל יצא צבא.** מגיד שאין יוצא בצבא פחות מבן עשרים:
@4 **ואתכם יהיו.** כשתפקדו אותם יהיו עמכם נשיא כל שבט ושבט:
@16 **אלה קרואי העדה.** הנקראים לכל דבר חשיבות שבעדה:
@17 **את האנשים האלה.** את שנים עשר נשיאים הללו: **אשר נקבו.** לו כאן בשמות:
@18 **ויתילדו על משפחתם.** הביאו ספרי יחוסיהם ועדי חזקת (לידתם) [לידת] כל אחד ואחד, להתיחס על השבט:
@49 **אך את מטה לוי לא תפקד.** כדאי הוא לגיון של מלך להיות נמנה לבדו. דבר אחר, צפה הקדוש ברוך הוא שעתידה לעמוד גזרה על כל הנמנין מבן עשרים שנה ומעלה שימותו במדבר, אמר אל יהיו אלו בכלל, לפי שהם שלי, שלא טעו בעגל:
@50 **ואתה הפקד את הלוים.** כתרגומו מני, לשון מנוי שררה על דבר שהוא ממנה עליו, כמו (אסתר ב' ג) ויפקד המלך פקידים:
@51 **יורידו אתו.** כתרגומו יפרקון, כשבאין לסע במדבר ממסע למסע היו מפרקין אותו מהקמתו, ונושאין אותו עד מקום אשר ישכון שם הענן ויחנו שם ומקימין אותו: **והזר הקרב.** לעבודתם זו: **יומת.** בידי שמים:
@52 **ואיש על דגלו.** כמו שהדגלים סדורים בספר זה, שלשה שבטים לכל דגל:
@53 **ולא יהיה קצף.** אם תעשה כמצותי לא יהיה קצף, ואם לאו שיכנסו זרים בעבודתם זו יהיה קצף, כמו שמצינו במעשה קרח (במדבר יז, יא) כי יצא הקצף וגו' :
@56 **באתת.** כל דגל יהיה לו אות. מפה צבועה תלויה בו. צבעו של זה לא כצבעו של זה, צבע כל אחד כגון אבנו הקבועה בחשן, ומתוך כך יכיר כל אחד את דגלו. דבר אחר באותות לבית אבתם באות שמסר להם יעקב אביהם כשנשאוהו ממצרים, שנאמר (בראשית נ, יב) ויעשו בניו לו כן כאשר צום, יהודה ויששכר וזבולן ישאוהו מן המזרח, וראובן ושמעון וגד מן הדרום וכו' , כדאיתא בתנחומא (במדבר יב) בפרשה זו: **מנגד.** מרחוק מיל, כמו שנאמר ביהושע (יהושע ג, ד) אך רחוק יהיה ביניכם וביניו כאלפים אמה, שיוכלו לבא בשבת, משה ואהרן ובניו והלוים חונים בסמוך לו:
@57 **קדמה.** לפנים הקרויה קדם, ואיזו, זו רוח מזרחית. והמערב קרוי אחור:
@63 **ראשנה יסעו.** כשרואין הענן מסתלק, תוקעין הכהנים בחצוצרות ונוסע מחנה יהודה תחלה, וכשהולכין, הולכין כדרך חניתן, הלוים והעגלות באמצע, דגל יהודה במזרח, ושל ראובן בדרום, ושל אפרים במערב, ושל דן בצפון:
@71 **ונסע אהל מועד.** לאחר שני דגלים הללו: **כאשר יחנו כן יסעו.** כמו שפרשתי, הליכתן כחניתן, כל דגל מהלך לרוח הקבועה לו: **על ידו.** על מקומו. ואין לשון יד זז ממשמעו, רוח שלצדו, קרוי על ידו, הסמוכה לו לכל הושטת ידו. אי''ן שו''ן איש''א בלע''ז [על ידו] :
@74 **ועליו.** כתרגומו ודסמיכין עלוהי:
@89 **ואלה תולדת אהרן ומשה.** ואינו מזכיר אלא בני אהרן. ונקראו תולדות משה, לפי שלמדן תורה. מלמד שכל המלמד את בן חברו תורה, מעלה עליו הכתוב כאלו ילדו: **ביום דבר ה' את משה.** נעשו אלו התולדות שלו, שלמדן מה שלמד מפי הגבורה:
@92 **על פני אהרן.** בחייו:
@94 **ושרתו אתו.** ומהו השרות, ושמרו את משמרתו, לפי ששמירת המקדש עליו שלא יקרב זר, כמו שנאמר (במדבר יח, א) אתה ובניך ובית אביך אתך תשאו את עון המקדש, והלוים הללו מסיעין אותם, זה הוא השרות:
@95 **ושמרו את משמרתו.** כל מנוי שהאדם ממנה עליו ומטל עליו לעשותו, קרוי משמרת בכל המקרא ובלשון משנה, כמו שאמרו בבגתן ותרש (מגילה יג, ב) והלא אין משמרתי ומשמרתך שוה, וכן משמרות כהנה ולויה:
@96 **ואת משמרת בני ישראל.** שכלן היו זקוקין לצרכי המקדש, אלא שהלוים באים תחתיהם בשליחותם, לפיכך לוקחים מהם המעשרות בשכרן, שנאמר (במדבר יח, לא) כי שכר הוא לכם חלף עבודתכם:
@97 **נתונים המה לו.** לעזרה: **מאת בני ישראל.** כמו מתוך בני ישראל, כלומר משאר כל העדה נבדלו לכך בגזרת המקום, והוא נתנם לו, שנאמר (במדבר ח, יט) ואתנה את הלוים נתונים וגו':
@98 **ואת אהרן ואת בניו תפקד.** לשון פקידות ואינו לשון מנין: **ושמרו את כהנתם.** קבלת דמים וזריקה והקטרה ועבודות המסורות לכהנים:
@100 **ואני הנה לקחתי.** ואני מהיכן זכיתי בהן: **מתוך בני ישראל.** שיהיו ישראל שוכרין אותן לשרות שלי. על ידי הבכורות זכיתי בהם ולקחתים תמורתם, לפי שהיתה העבודה בבכורות, וכשחטאו בעגל נפסלו, והלוים שלא עבדו עבודה זרה נבחרו תחתיהם:
@103 **מבן חדש ומעלה.** משיצא מכלל נפלים הוא נמנה לקרא שומר משמרת הקדש. אמר ר' יהודה ברבי שלום למוד הוא אותו השבט להיות נמנה מן הבטן, שנאמר (במד' כו, כט) אשר ילדה אתה ללוי במצרים, עם כניסתה בפתח מצרים ילדה אתה. ונמנית בשבעים נפש, שכשאתה מונה חשבונם לא תמצאם אלא שבעים חסר אחת, והיא השלימה את המנין:
@104 **על פי ה'.** אמר משה לפני הקדוש ברוך הוא היאך אני נכנס לבתי כלם ולתוך אהליהם לדעת מנין יונקיהם. אמר לו הקדוש ברוך הוא עשה אתה את שלך ואני אעשה את שלי. הלך משה ועמד על פתח האהל והשכינה מקדמת לפניו, ובת קול יוצאת מן האהל ואומרת כך וכך תינוקות יש באהל זה, לכך נאמר על פי ה':
@109 **לגרשון משפחת הלבני.** כלומר לגרשון היו הפקודים משפחת הלבני ומשפחת השמעי פקודיהם כך וכך:
@113 **המשכן.** יריעות התחתונות: **והאהל.** יריעות עזים העשויות לגג: **מכסהו.** עורות אילים ותחשים: **ומסך פתח.** הוא הוילון:
@114 **ואת מיתריו.** של משכן והאהל ולא של חצר:
@117 **משפחת בני קהת יחנו** וגו' **תימנה.** וסמוכין להם דגל ראובן החונים תימנה, אוי לרשע ואוי לשכנו, לכך לקו מהם דתן ואבירם ומאתים וחמשים איש עם קרח ועדתו, שנמשכו עמהם במחלקתם:
@119 **והמסך.** היא הפרכת, שאף היא קרויה פרכת המסך:
@120 **ונשיא נשיאי הלוי.** ממנה על כלם. ועל מה היא נשיאותו, פקדת שומרי משמרת הקדש, על ידו היה פקדת כלם:
@126 **משה ואהרן ובניו.** וסמוכין להם דגל מחנה יהודה, והחונים עליו יששכר וזבולן, טוב לצדיק טוב לשכנו, לפי שהיו שכניו של משה שהיה עוסק בתורה, נעשו גדולים בתורה, שנאמר (תהלים ס, ט) יהודה מחקקי, ומבני יששכר יודעי בינה וגו' (דה''י א' יב לג) מאתים ראשי סנהדראות, ומזבולן משכים בשבט סופר (שופטים ה יד) :
@127 **אשר פקד משה ואהרן.** נקוד על ואהרן, לומר שלא היה במנין הלוים: **שנים ועשרים אלף.** ובפרטן אתה מוצא שלש מאות יתרים, בני גרשון שבעת אלפים וחמש מאות, בני קהת שמונת אלפים ושש מאות, בני מררי ששת אלפים ומאתים, [הרי שנים ועשרים אלף ושלש מאות] . ולמה לא כללן עם השאר ויפדו את הבכורות, ולא יהיו זקוקים השלשה ושבעים ומאתים בכורות העודפים על המנין לפדיון, אמרו רבותינו במסכת בכורות (בכורות ה א) אותן שלש מאות לוים בכורות היו ודים שיפקיעו עצמם מן הפדיון:
@128 **פקד כל בכור זכר** וגו' **מבן חדש ומעלה.** משיצא מכלל ספק נפלים:
@133 **ואת בהמת הלוים** וגו' **.** לא פדו בהמות הלוים את בכורי בהמה טהורה שלישראל, אלא את פטרי חמוריהם, ושה אחד של בן לוי פטר כמה פטרי חמורים שלישראל, תדע שהרי מנה העודפים באדם ולא מנה העודפים בבהמה:
@134 **ואת פדויי השלשה** וגו' **.** ואת הבכורות הצריכין להפדות בהם, אלו השלשה ושבעים ומאתים העודפים בהם, יתרים על הלוים, מהם תקח חמשת שקלים לגלגלת, כך היתה מכירתו של יוסף עשרים כסף, שהיה בכורה של רחל:
@137 **העדפים על פדויי הלוים.** על אותן שפדו הלוים בגופן:
@138 **חמשה וששים ושלש מאות ואלף.** כך סכום החשבון חמשת שקלים לגלגלת. למאתים בכורות אלף שקל, לשבעים בכורות שלש מאות וחמשים שקל, לשלש בכורות חמשה עשר שקל. אמר כיצד אעשה, בכור שאומר לו תן חמשת שקלים, יאמר לי אני מפדויי הלוים. מה עשה, הביא שנים ועשרים אלף פתקין וכתב עליהן בן לוי, ומאתים ושבעים ושלשה פתקין כתב עליהן חמשה שקלים, בללן ונתנן בקלפי, אמר להם בואו וטלו פתקיכם לפי הגורל:
@141 **נשא את ראש** וגו' **.** מנה מהם את הראויין לעבודת משא, והם מבן שלשים ועד בן חמשים שנה, והפחות משלשים לא נתמלא כחו. מכאן אמרו בן שלשים לכח, והיותר על בן חמשים כחו מכחיש מעתה:
@143 **קדש הקדשים.** המקדש שבכלן הארון והשלחן והמנורה והמזבחות והפרוכת וכלי שרת:
@144 **ובא אהרן ובניו** וגו' **.** יכניסו כל כלי וכלי לנרתקו המפורש לו בפרשה זו, ולא יצטרכו הלוים בני קהת אלא לשאת: **בנסוע המחנה.** כשהענן מסתלק הם יודעין שיסעו:
@146 **קערת וכפות קשות ומנקיות.** כבר פרשתי במלאכת המשכן: **הנסך.** הכסוי לשון מסך, כדכתיב (שמות כה, כט) אשר יסך בהן:
@148 **מלקחיה.** כמין צבת שמושך בה את הפתילה לכל צד שירצה: **מחתתיה.** כמין כף קטנה ושוליה פשוטין ולא סגלגלים, ואין לה מחצה לפניה אלא מצדיה, וחותה בה את דשן הנרות כשמטיבן: **נרתיה.** לוצי''ש בלע''ז [מנורות] שנותנים בהן השמן והפתילות:
@149 **אל מכסה עור תחש.** כמין מרצוף:
@151 **את כל כלי השרת אשר ישרתו בם בקדש.** בתוך המשכן שהוא קדש, והן כלי הקטרת שמשרתין בהם במזבח הפנימי:
@152 **ודשנו את המזבח.** מזבח הנחשת: **ודשנו.** יטלו את הדשן מעליו: **ופרשו עליו בגד ארגמן.** ואש שירדה מן השמים רבוצה תחת הבגד כארי בשעת המסעות, ואינה שורפתו, שהיו כופין עליה פסכתר של נחשת:
@153 **מחתת.** שבהן חותים גחלים לתרומת הדשן, שעשויה כמין מחבת שאין לה אלא שלש מחצות, ומלפניה שואבת את הגחלים: **מזלגות.** צנוריות של נחשת שבהן מכין באברים שעל המזבח להפכן כדי שיתעכלו יפה ומהר: **יעים.** הם מגרפות ובלע''ז ודי''ל [מגרפה] והן של נחשת ובהן מכבדין את הדשן מעל המזבח:
@154 **לכסת את הקדש.** הארון והמזבח: **ואת כל כלי הקדש.** המנורה וכלי שרת: **ומתו.** שאם יגעו חייבין מיתה בידי שמים:
@155 **ופקדת אלעזר.** שהוא ממנה עליהם לשאת אותם, שמן וקטרת ושמן המשחה ומנחת התמיד, עליו מטל לצוות ולזרז ולהקריב בעת חנייתן: **פקדת כל המשכן.** ועוד היה ממנה על משא בני קהת לצוות איש איש על עבודתו ועל משאו, והוא המשכן וכל אשר בו, כל הסדורים למעלה בפרשה זו, אבל משא בני גרשון ומררי שאינן מקדש הקדשים, על פי איתמר היה, כמו שכתוב בפרשת נשא (פסוק כח) :
@157 **אל תכריתו.** אל תגרמו להם שימותו:
@159 **ולא יבאו לראות כבלע את הקדש.** לתוך נרתק שלו, כמו שפרשתי למעלה (פסוק ה) בפרשה זו, ופרשו עליו בגד פלוני וכסו אותו במכסה פלוני, ובלוע שלו הוא כסויו:
@161 **נשא את ראש בני גרשון גם הם.** כמו שצויתיך על בני קהת לראות כמה יש שהגיעו לכלל עבודה:
@164 **את יריעת המשכן.** עשר תחתונות: **ואת אהל מועד.** יריעות עזים העשויות לאהל עליו: **מכסהו.** עורות אילים מאדמים: **מסך פתח.** וילון המזרחי:
@165 **אשר על המשכן.** כלומר הקלעים והמסך של חצר הסוככים ומגינים על המשכן ועל מזבח הנחשת סביב: **ואת כל אשר יעשה להם.** כתרגומו ית כל דיתמסר להון, לבני גרשון:
@166 **על פי אהרן ובניו.** ואיזה מהבנים ממנה עליהם, ביד איתמר בן אהרן הכהן:
@171 **ויתדתם ומיתריהם.** של עמודים, שהרי יתדות ומיתרי הקלעים במשא בני גרשון היו, ויתדות ומיתרים היו ליריעות ולקלעים מלמטה, שלא תגביהם הרוח, ויתדות ומיתרים היו לעמודים סביב לתלות בהם הקלעים בשפתם העליונה, בכלנסות וקנדסין [וקנטסין] , כמו ששנויה במלאכת המשכן:
@186 **עבדת עבדה.** הוא השיר במצלתים וכנורות, שהיא עבודה לעבודה אחרת: **ועבודת משא.** כמשמעו:
@188 **ופקדיו אשר צוה ה' את משה.** ואותן הפקודים היו במצוה מבן שלשים שנה ועד בן חמשים שנה:
@190 **צו את בני ישראל** וגו' **.** פרשה זו נאמרה ביום שהוקם המשכן, ושמנה פרשיות נאמרו בו ביום, כדאיתא במסכת גיטין בפרק הנזקין (ס, א) : **וישלחו מן המחנה.** שלש מחנות היו שם בשעת חניתן, תוך הקלעים היא מחנה שכינה, חנית הלוים סביב כמו שמפורש בפרשת במדבר סיני היא מחנה לויה, ומשם ועד סוף מחנה הדגלים לכל ארבע הרוחות היא מחנה ישראל. הצרוע נשתלח חוץ לכלן, הזב מתר במחנה ישראל ומשלח מן השתים, וטמא לנפש מתר אף בשל לויה ואינו משלח אלא משל שכינה, וכל זה דרשו רבותינו מן המקראות במסכת פסחים (סז) : **טמא לנפש.** דמסאב לטמי נפשא דאנשא. אומר אני שהוא לשון עצמות אדם בלשון ארמי, והרבה יש בבראשית רבה אדרינוס שחיק טמיא, שחיק עצמות:
@194 **למעל מעל בה'.** הרי חזר וכתב כאן פרשת גוזל ונשבע על שקר, היא האמורה בפרשת ויקרא (ה, כא) ומעלה מעל בה' וכחש בעמיתו וגו' , ונשנית כאן בשביל שני דברים שנתחדשו בה האחד, שכתב והתודו, למד שאינו חיב חומש ואשם על פי עדים עד שיודה בדבר. והשני על גזל הגר שהוא נתון לכהנים:
@195 **את אשמו בראשו.** הוא הקרן שנשבע עליו: **לאשר אשם לו.** למי שנתחיב לו:
@196 **ואם אין לאיש גואל.** שמת התובע שהשביעו, ואין לו יורשים: **להשיב האשם אליו.** כשנמלך זה להתודות על עונו. ואמרו רבותינו וכי יש לך אדם בישראל שאין לו גואלים או בן או אח או שאר בשר הקרוב ממשפחת אביו למעלה עד יעקב, אלא זה הגר שמת ואין לו יורשים: **האשם המושב.** זה הקרן והחומש: **לה' לכהן.** קנאו השם ונתנו לכהן שבאותו משמר: **מלבד איל הכפורים.** האמור בויקרא (ויקרא ה, כה) שהוא צריך להביא:
@197 **וכל תרומה** וגו' **.** אמר רבי ישמעאל וכי תרומה מקריבין לכהן, והלא הוא המחזר אחריה לבית הגרנות. ומה תלמוד לומר אשר יקריבו לכהן, אלו הבכורים, שנאמר בהם תביא בית ה' אלהיך, (שמות כג, יט) . ואיני יודע מה יעשה בהם, תלמוד לומר לכהן לו יהיה, בא הכתוב ולמד על הבכורים שיהיו נתנין לכהן:
@198 **ואיש את קדשיו לו יהיו.** לפי שנאמרו מתנות כהנה ולויה יכול יבואו ויטלום בזרוע, תלמוד לומר ואיש את קדשיו לו יהיו, מגיד שטובת הנאתן לבעלים, ועוד מדרשים הרבה דרשו בו בספרי. ומדרש אגדה ואיש את קדשיו לו יהיו, מי שמעכב מעשרותיו ואינו נותנן, לו יהיו המעשרות, סוף שאין שדהו עושה אלא אחד מעשרה שהיתה למודה לעשות: **איש אשר יתן לכהן.** מתנות הראויות לו: **לו יהיה.** ממון הרבה:
@200 **איש איש כי תשטה אשתו.** מה כתיב למעלה מן הענין ואיש את קדשיו לו יהיו, אם אתה מעכב מתנות הכהן, חייך שתצטרך לבא אצלו להביא לו את הסוטה: **איש איש.** ללמדך שמועלת בשתים, באיש מלחמה של מעלה ואישה מלמטה: **כי תשטה אשתו.** שנו רבותינו אין המנאפין נואפין עד שתכנס בהן רוח שטות, דכתיב כי תשטה, וכתוב בו נואף אשה חסר לב (משלי ו, לב) . ופשוטו של מקרא כי תשטה. תט מדרכי צניעות ותחשד בעיניו, כמו שטה מעליו ועבר (שם ד, טו) , אל ישט אל דרכיה לבך (שם ז, כה) : **ומעלה בו מעל.** ומהו המעל, ושכב איש אותה:
@201 **ושכב איש.** פרט לקטן ומי שאינו איש: **אתה שכבת זרע.** שכיבתה פוסלת אותה, ואין שכיבת אחותה פוסלת אותה כמעשה בשתי אחיות שהיו דומות זו לזו: **ונעלם מעיני אישה.** פרט לסומא הא אם היה רואה ומעמעם [ומעלים] אין המים בודקין אותה: **ונסתרה.** שיעור שתראה לטמאת ביאה: **ועד אין בה.** הא אם יש בה אפלו עד אחד שאמר נטמאת לא היתה שותה: **ועד אין בה.** לטמאה אבל יש עדים לסתירה: **נתפשה.** נאנסה, כמו ותפשה ושכב עמה (דברים כב, כח) :
@202 **ועבר עליו.** קודם לסתירה: **רוח קנאה וקנא.** פרשו רבותינו לשון התראה, שמתרה בה אל תסתרי עם איש פלוני: **והיא נטמאה או עבר עליו** וגו' **.** כלומר הוא התרה בה ועברה על התראתו, ואין ידוע אם נטמאה אם לאו:
@203 **קמח.** שלא יהא מסלת: **שערים.** ולא חטים, היא עשתה מעשה בהמה וקרבנה מאכל בהמה: **לא יצק עליו שמן.** שלא יהא קרבנה מהדר, שהשמן קרוי אור והיא עשתה בחשך: **ולא יתן עליו לבנה.** שהאמהות נקראות לבונה, שנאמר ואל גבעת הלבונה (שה''ש ד, ו) , והיא פרשה מדרכיהן: **כי מנחת קנאת הוא.** הקמח הזה, קמח לשון זכר: **מנחת קנאת.** מעוררת עליה שתי קנאות, קנאת המקום וקנאת הבעל:
@205 **מים קדשים.** שקדשו בכיור, לפי שנעשה מנחשת מראות הצובאות, וזו פרשה מדרכיהן שהיו נבעלות לבעליהן במצרים תחת התפוח, וזו קלקלה לאחר, תבדק בו: **בכלי חרש.** היא השקתה את הנואף יין משבח בכוסות משבחים, לפיכך תשתה מים המרים במקדה בזויה של חרש:
@206 **והעמיד הכהן** וגו' **.** והלא כבר נאמר והעמידה לפני ה', אלא מסיעין היו אותה ממקום למקום כדי ליגעה ותטרף דעתה ותודה: **ופרע.** סתר את קליעת שערה כדי לבזותה, מכאן לבנות ישראל שגלוי הראש גנאי להן: **לפני ה'.** בשער נקנור, הוא שער העזרה המזרחי, דרך כל הנכנסים: **ונתן על כפיה.** ליגעה אולי תטרף דעתה ותודה, ולא ימחה שם המיוחד על המים: **המרים.** על שם סופן שהם מרים לה: **המאררים.** המחסרים אותה מן העולם, לשון סלון ממאיר (יחזקאל כח, כד) . ולא יתכן לפרש מים ארורים, שהרי קדושים הן, ולא ארורים כתב הכתוב, אלא מאררים את אחרים. ואף אנקלוס לא תרגם ליטיא, אלא מלטטיא, שמראות קללה בגופה של זו:
@207 **והשביע אתה** וגו' **.** ומה היא השבועה אם לא שכב, הנקי, הא אם שכב חנקי [לא תנקי] , שמכלל לאו אתה שומע הן, אלא שמצוה לפתוח בדיני נפשות תחלה לזכות:
@208 **ואת כי שטית.** כי משמש בלשון אם:
@209 **בשבעת האלה.** שבועה של קללה: **יתן ה' אותך לאלה.** שיהיו הכל מקללין ביך יבואך כדרך שבא לפלונית: **ולשבועה.** שיהיו הכל נשבעין ביך לא יארע לי כדרך שארע לפלונית וכן הוא אומר והנחתם שמכם לשבועה לבחירי (ישעיה סה, טו) , שהצדיקים נשבעים בפרענותן של רשעים, וכן לענין הברכה ונברכו וגו' (בראש' יב, ג) בך יברך ישראל לאמר (בראש' מח, כ) : **את ירכך.** בקללה הקדים ירך לבטן לפי שבה התחילה בעברה תחלה: **צבה.** כתרגומו נפוחה:
@210 **לצבות בטן.** כמו להצבות בטן, זהו שמוש פתח שהלמ''ד נקודה בו, וכן לנחותם הדרך (שמות יג, כא) , לראותכם בדרך אשר תלכו בה (דברים א, לג) , וכן לנפיל ירך להנפיל ירך, שהמים מצבים את הבטן ומפילים את הירך: **לצבות בטן ולנפיל ירך.** בטנו וירכו של בועל, או אינו אלא של נבעלת, כשהוא אומר את ירכך נופלת ואת בטנך צבה, הרי של נבעלת אמור: **אמן אמן.** קבלת שבועה, אמן על האלה אמן על השבועה, אמן אם מאיש זה, אמן אם מאיש אחר, אמן שלא סטיתי ארוסה ונשואה שומרת יבם וכנוסה:
@212 **והשקה את האשה.** אין זה סדר המעשה, שהרי בתחלה מקריב מנחתה, אלא הכתוב מבשרך שכשישקנה יבואו בה למרים. לפי שנאמר בטן וירך, מנין לשאר כל הגוף, תלמוד לומר ובאו בה בכלה, אם כן מה תלמוד לומר בטן וירך, לפי שהן התחילו בעברה תחלה, לפיכך התחילה מהן הפרענות: **למרים.** להיות לה רעים ומרים:
@213 **והניף.** מוליך ומביא מעלה ומוריד, ואף היא מניפה עמו שידה למעלה מידו של כהן: **והקריב אתה.** זו היא הגשתה בקרן דרומית מערבית של מזבח קודם קמיצה כשאר מנחות:
@214 **אזכרתה.** הוא הקומץ, שעל ידי הקטרתו המנחה באה לזכרון לגבוה:
@215 **והשקה את המים.** לרבות שאם אמרה איני שותה לאחר שנמחקה מגלה, מערערין אתה ומשקין אתה בעל כרחה, אלא אם כן אמרה טמאה אני: **וצבתה בטנה** וגו' **.** אף על פי שבקללה הזכיר ירך תחלה, המים אין בודקין אלא דרך כניסתן בה: **והיתה האשה לאלה.** כמו שפרשתי שהיו הכל אלין בה: **בקרב עמה.** הפרש יש בין אדם המתנול במקום שנכר, לאדם המתנול במקום שאינו נכר:
@216 **ואם לא נטמאה האשה.** בסתירה זו: **וטהרה היא.** ממקום אחר: **ונקתה.** ממים המאררים, ולא עוד אלא ונזרעה זרע, אם היתה יולדת בצער תלד ברוח, אם היתה יולדת שחורים יולדת לבנים:
@218 **או איש.** כמו או נודע (שמות כא, לו) , כלומר אם איש קנאי הוא, לכך והעמיד את האשה:
@219 **ונקה האיש מעון.** אם בדקוה המים אל ידאג לומר חבתי במיתתה, נקי הוא מן הענש. דבר אחר משישקנה תהיה אצלו בהתר ונקה מעון, שהסוטה אסורה לבעלה:
@221 **כי יפלא.** יפריש. למה נסמכה פרשת נזיר לפרשת סוטה, לומר לך שכל הרואה סוטה בקלקולה יזיר עצמו מן היין, שהוא מביא לידי ניאוף: **נדר נזיר.** אין נזירה בכל מקום אלא פרישה, אף כאן שפרש מן היין: **להזיר לה'.** להבדיל עצמו מן היין לשם שמים:
@222 **מיין ושכר.** כתרגומו מחמר חדת ועתיק, שהיין משכר כשהוא ישן: **וכל משרת.** לשון צביעה במים וכל משקה, ובלשון משנה יש הרבה אין שורין דיו וסמנים (שבת יז, ב) , נזיר ששרה פתו ביין (נזיר לד, ב) :
@223 **חרצנים.** הם הגרענין: **זג.** הם קלפות שמבחוץ, שהחרצנים בתוכן כענבל בזוג:
@224 **קדש יהיה.** השער שלו, לגדל הפרע של שער ראשו: **פרע.** נקוד פתח קטן לפי שהוא דבוק לשער ראשו, פרע של שער. ופרושו של פרע, גדול של שער, וכן את ראשו לא יפרע (ויקרא כא, י) , ואין קרוי פרע פחות משלושים יום:
@227 **כל ימי נזרו קדש הוא.** זו קדשת הגוף מלטמא למתים:
@228 **בפתע.** זה אונס: **פתאם.** זה שוגג. ויש אומרים פתע פתאום דבר אחד הוא, מקרה של פתאום: **וכי ימות מת עליו.** באהל שהוא בו: **ביום טהרתו.** ביום הזאתו, או אינו אלא בשמיני שהוא טהור לגמרי, תלמוד לומר ביום השביעי, אי שביעי יכול אפלו לא הזה, תלמוד לומר ביום טהרתו:
@229 **וביום השמיני יבא שתי תרים.** להוציא את השביעי. או אינו אלא להוציא את התשיעי, קבע זמן לקרבין וקבע זמן למקריבין, מה קרבין הכשיר שמיני ומשמיני והלאה, אף מקריבין שמיני ומשמיני והלאה:
@230 **מאשר חטא על הנפש.** שלא נזהר מטמאת המת, רבי אלעזר הקפר אומר שציער עצמו מן היין: **וקדש את ראשו.** לחזור ולהתחיל מנין נזירותו:
@231 **והזיר לה' את ימי נזרו.** יחזור וימנה נזירותו כבתחלה: **והימים הראשונים יפלו.** לא יעלו מן המנין:
@232 **יביא אתו.** יביא את עצמו, זה אחד משלשה אתים שהיה ר' ישמעאל דורש כן. כיוצא בו והשיאו אותם עון אשמה (ויקרא כב, טז) , את עצמם, כיוצא בו ויקבור אותו בגיא (דברים לד, ו) , הוא קבר את עצמו:
@234 **ומנחתם ונסכיהם.** של עולה ושלמים, לפי שהיו בכלל ויצאו לדון בדבר חדש שיטעינו לחם, החזירן לכללן שיטעינו נסכים כדין עולה ושלמים: **חלת בלולת ורקיקי מצות.** עשר מכל מין:
@236 **זבח שלמים לה' על סל המצות.** ישחט את השלמים על מנת לקדש את הלחם: **את מנחתו ואת נסכו.** של איל:
@237 **וגלח הנזיר פתח אהל מועד.** יכול יגלח בעזרה, הרי זה דרך בזיון. אלא וגלח הנזיר לאחר שחיטת השלמים שכתוב בהן ושחטו פתח אהל מועד (ויקרא ג, ב) , ספרי: **אשר תחת זבח השלמים.** תחת הדוד שהוא מבשלן בו, לפי ששלמי נזיר היו מתבשלין בעזרה, שצריך לטול הכהן הזרוע אחר שנתבשלה ולהניף לפני ה':
@238 **הזרוע בשלה.** לאחר שנתבשלה:
@239 **קדש הוא לכהן.** החלה והרקיק והזרוע תרומה הן לכהן: **על חזה התנופה.** מלבד חזה ושוק הראויים לו מכל שלמים מוסף על שלמי נזיר הזרוע הזה, לפי שהיו שלמי נזיר בכלל ויצאו לדון בדבר החדש להפרשת זרוע הצרך להחזירן לכללן לדון אף בחזה ושוק:
@240 **מלבד אשר תשיג ידו.** שאם אמר הריני נזיר על מנת לגלח על מאה עולות ועל מאה שלמים, **כפי נדרו אשר ידור כן יעשה מוסף על תורת נזרו.** על תורת הנזיר יוסיף ולא יחסר, שאם אמר הריני נזיר חמש נזירות על מנת לגלח על שלש בהמות הללו, אין אני קורא בו כאשר ידור כן יעשה:
@242 **אמור להם.** כמו זכור שמור, בלע''ז דישנ''ט (באמרכם) : **אמור להם.** שיהיו כלם שומעים: **אמור.** מלא, לא תברכם בחפזון ובהלות, אלא בכונה ובלב שלם:
@243 **יברכך.** שיתברכו נכסיך: **וישמרך.** שלא יבואו עליך שודדים לטול ממונך, שהנותן מתנה לעבדו אינו יכול לשמרו מכל אדם, וכיון שבאים לסטים עליו ונוטלין אותה ממנו, מה הנאה יש לו במתנה זו, אבל הקדוש ברוך הוא הוא הנותן הוא השומר. והרבה מדרשים דרשו בו בספרי:
@244 **יאר ה' פניו אליך.** יראה לך פנים שוחקות, פנים צהובות: **ויחנך.** יתן לך חן:
@245 **ישא ה' פניו אליך.** יכבוש כעסו:
@246 **ושמו את שמי.** יברכום בשם המפורש: **ואני אברכם.** לישראל ואסכים עם הכהנים. דבר אחר ואני אברכם לכהנים:
@247 **ויהי ביום כלות משה.** כלת כתיב, יום הקמת המשכן היו ישראל ככלה הנכנסת לחפה: **כלות משה.** בצלאל ואהליאב וכל חכם לב עשו את המשכן, ותלאו הכתוב במשה, לפי שמסר נפשו עליו לראות תבנית כל דבר ודבר כמו שהראהו בהר להורות לעושי המלאכה, ולא טעה בתבנית אחת וכן מצינו בדוד לפי שמסר נפשו על בנין בית המקדש, שנאמר זכור ה' לדוד את כל ענותו אשר נשבע לה' וגו' (תהלים קלב, א. ב) , לפיכך נקרא על שמו, שנאמר ראה ביתך דוד (מלכים א' יב, טז) : **ביום כלות משה להקים.** ולא נאמר ביום הקים מלמד שכל שבעת ימי המלואים היה משה מעמידו ומפרקו ובאותו היום העמידו ולא פרקו, לכך נאמר ביום כלות משה להקים, אותו היום כלו הקמותיו וראש חדש ניסן היה, בשני נשרפה הפרה, בשלישי הזו הזיה ראשונה, ובשביעי גלחו:
@248 **הם נשיאי המטת.** שהיו שוטרים עליהם במצרים והיו מכים עליהם, שנאמר (שמות ה) ויכו שוטרי בני ישראל וגו' : **הם העומדים על הפקדים.** שעמדו עם משה ואהרן כשמנו את ישראל, שנאמר (במדבר א) ואתכם יהיו וגו' :
@249 **שש עגלת צב.** אין צב אלא מחפים וכן (ישעיה סו, כ) בצבים ובפרדים, עגלות מכסות קרויות צבים: **ויקריבו אותם לפני המשכן.** שלא קבל משה מידם עד שנאמר לו מפי המקום. אמר רבי נתן מה ראו הנשיאים להתנדב כאן בתחלה, ובמלאכת המשכן לא התנדבו תחלה, אלא כך אמרו הנשיאים יתנדבו צבור מה שיתנדבו, ומה שמחסרין אנו משלימין, כיון שראו שהשלימו צבור את הכל, שנאמר (שמות לו, ז) והמלאכה היתה דים, אמרו מעתה מה לנו לעשות, הביאו את אבני השוהם והמלואים לאפוד ולחשן, לכך התנדבו כאן תחלה:
@253 **כפי עבדתם.** שהיה משא בני גרשון קל משל מררי, שהיו נושאים הקרשים והעמודים והאדנים:
@255 **כי עבדת הקדש עליהם.** משא דבר הקדשה הארון והשלחן וגו' , לפיכך בכתף ישאו:
@256 **ויקריבו הנשאים את חנכת המזבח.** לאחר שהתנדבו העגלות והבקר לשאת המשכן, נשאם לבם להתנדב קרבנות המזבח לחנכו: **ויקריבו הנשיאים את קרבנם לפני המזבח.** כי לא קבל משה מידם עד שנאמר לו מפי הגבורה:
@257 **יקריבו את קרבנם לחנכת המזבח.** ועדין לא היה יודע משה היאך יקריבו, אם כסדר תולדותם, אם כסדר המסעות, עד שנאמר לו מפי הקדוש ברוך הוא יקריבו למסעות, איש יומו:
@258 **ביום הראשון.** אותו היום נטל עשר עטרות, ראשון למעשה בראשית, ראשון לנשיאים וכו' , כדאיתא בסדר עולם: **למטה יהודה.** יחסו הכתוב על שבטו, ולא שגבה משבטו והקריב. או אינו אומר למטה יהודה אלא שגבה משבטו והביא, תלמוד לומר זה קרבן נחשון, משלו הביא:
@259 **שניהם מלאים סלת.** למנחת נדבה:
@260 **עשרה זהב.** כתרגומו, משקל עשר שקלי הקדש היה בה: **מלאה קטרת.** לא מצינו קטרת ליחיד ולא על מזבח החיצון אלא זו בלבד, והוראת שעה היתה:
@261 **פר אחד.** מיוחד שבעדרו:
@262 **שעיר עזים אחד לחטאת.** לכפר על קבר התהום וטמאת ספק:
@265 **הקריב נתנאל בן צוער. הקרב את קרבנו.** מה תלמוד לומר הקריב בשבטו של יששכר, מה שלא נאמר בכל השבטים, לפי שבא ראובן וערער ואמר די שקדמני יהודה אחי, אקריב אני אחריו. אמר לו משה מפי הגבורה נאמר לי שיקריבו כסדר מסען לדגליהם. לכך אמר הקרב את קרבנו, והוא חסר יו''ד, שהוא משמע הקרב, לשון צווי, שמפי הגבורה נצטוה הקרב. ומהו הקריב הקרב שני פעמים, שבשביל שני דברים זכה להקריב שני לשבטים אחת שהיו יודעים בתורה, שנאמר (ד''ה א' יב, לג) ומבני יששכר יודעי בינה לעתים, ואחת שהם נתנו עצה לנשיאים להתנדב קרבנות הללו. וביסודו שלר' משה הדרשן מצאתי אמר רבי פנחס בן יאיר, נתנאל בן צוער השיאן עצה זו: **קערת כסף.** מנין אותיותיו בגימטריה תתק''ל כנגד שנותיו של אדם הראשון: **שלשים ומאה משקלה.** על שם שכשהעמיד תולדות לקיום העולם בן מאה ושלשים שנה היה, שנאמר (בראשית ה, ג) ויחי אדם שלשים ומאת שנה ויולד בדמותו וגו' : **מזרק אחד כסף.** בגימטריה תק''כ, על שם נח שהעמיד תולדות בן ת''ק שנה, ועל שם עשרים שנה שנגזרה גזרת המבול קודם תולדותיו, כמו שפרשתי אצל (בראשית ו, ג) והיו ימיו מאה ועשרים שנה, לפיכך נאמר מזרק אחד כסף ולא נאמר מזרק כסף אחד, כמו שנאמר בקערה, לומר שאף אותיות של אחד מצטרפות למנין: **שבעים שקל.** כנגד שבעים אמות שיצאו מבניו:
@266 **כף אחת.** כנגד התורה שנתנה מידו של הקדוש ברוך הוא: **עשרה זהב.** כנגד עשרת הדברות: **מלאה קטרת.** גימטריה של קטרת תרי''ג מצות, ובלבד שתחליף קו''ף בד,, ל על ידי א''ת ב''ש ג''ר ד''ק:
@267 **פר אחד.** כנגד אברהם, שנאמר בו (בראשית יח, ז) ויקח בן בקר: **איל אחד.** כנגד יצחק (שם כב, יג) ויקח את האיל וגו' : **כבש אחד.** כנגד יעקב (שם ל, מ) והכשבים הפריד יעקב:
@268 **שעיר עזים.** לכפר על מכירת יוסף, שנאמר בו (שם לז, לא) וישחטו שעיר עזים:
@269 **ולזבח השלמים בקר שנים.** כנגד משה ואהרן, שנתנו שלום בין ישראל לאביהם שבשמים: **אילם עתדים כבשים.** שלשה מינים כנגד כהנים ולוים וישראלים, וכנגד תורה נביאים וכתובים. שלש חמשיות כנגד חמשה חמשין, וחמשת הדברות הכתובין על לוח אחד, וחמשה הכתובין על השני. עד כאן מיסודו של ר' משה הדרשן:
@270 **ביום השלישי נשיא** וגו' **.** ביום השלישי היה נשיא המקריב לבני זבולן, וכן כלם, אבל בנתנאל שנאמר בו הקריב נתנאל, נופל אחריו הלשון לומר נשיא יששכר, לפי שכבר הזכיר שמו והקרבתו, ובשאר שלא נאמר בהן הקריב, נופל עליהן לשון זה נשיא לבני פלוני, אותו היום היה הנשיא המקריב לשבט פלוני:
@330 **ביום המשח אתו.** בו ביום שנמשח הקריב, ומה אני מקים אחרי המשח, שנמשח תחלה ואחר כך הקריב. או אחרי המשח לאחר זמן, ולא בא ללמד ביום המשח אלא לומר שנמשח ביום, כשהוא אומר (ויקרא ז, לו) ביום משחו אתם, למדנו שנמשח ביום, ומה תלמוד לומר ביום המשח אתו, ביום שנמשח הקריב: **קערת כסף שתים עשרה.** הם הם שהתנדבו ולא ארע בהם פסול:
@331 **שלשים ומאה הקערה האחת** וגו' **.** מה תלמוד לומר, לפי שנאמר שלשים ומאה משקלה, ולא פרש באיזו שקל, לכך חזר ושנאה כאן, וכלל בכלן כל כסף הכלים בשקל הקדש: **כל כסף הכלים** וגו' **.** למדך שהיו כלי המקדש מכונים במשקלן, שוקלן אחד אחד ושוקלן כלן כאחד, לא רבה ולא מעט:
@332 **כפות זהב שתים עשרה.** למה נאמר, לפי שנאמר כף אחת עשרה זהב, היא של זהב, ומשקלה עשרה שקלים של כסף, או אינו אלא כף אחת של כסף ומשקלה עשרה שקלי זהב, ושקלי זהב אין משקלם שוה לשל כסף, תלמוד לומר כפות זהב, של זהב היו:
@335 **ובבא משה.** שני כתובים המכחישים זה את זה, בא שלישי והכריע ביניהם. כתוב אחד אומר (ויקרא א, א) וידבר ה' אליו מאהל מועד, והוא חוץ לפרכת, וכתוב אחד אומר (שמות כה, כב) ודברתי אתך מעל הכפרת, בא זה והכריע ביניהם, משה בא אל אהל מועד ושם שומע את הקול הבא מעל הכפרת: **מבין שני הכרובים.** הקול יוצא מן השמים לבין שני הכרובים ומשם יצא לאהל מועד: **וישמע את הקול.** יכול קול נמוך, תלמוד לומר את הקול, הוא הקול שנדבר עמו בסיני, וכשמגיע לפתח היה נפסק, ולא היה יוצא חוץ לאהל: **מדבר.** כמו מתדבר, כבודו של מעלה לומר כן מדבר בינו לבין עצמו, ומשה שומע מאליו: **וידבר אליו.** למעט את אהרן מן הדברות:
@337 **בהעלתך.** למה נסמכה פרשת המנורה לפרשת הנשיאים, לפי שכשראה אהרן חנכת הנשיאים חלשה דעתו, שלא היה עמהם בחנכה, לא הוא ולא שבטו, אמר לו הקדוש ברוך הוא חייך, שלך גדולה משלהם, שאתה מדליק ומטיב את הנרות: **בהעלתך.** על שם שהלהב עולה, כתוב בהדלקתן לשון עליה, שצריך להדליק עד שתהא שלהבת עולה מאליה. ועוד דרשו רבותינו, מכאן שמעלה היתה לפני המנורה שעליה הכהן עומד ומטיב: **אל מול פני המנורה.** אל מול נר אמצעי שאינו בקנים, אלא בגוף של מנורה: **יאירו שבעת הנרות.** ששה שעל ששת הקנים, שלשה המזרחיים פונים למול האמצעי, הפתילות שבהן, וכן שלשה המערביים ראשי הפתילות למול האמצעי. ולמה, כדי שלא יאמרו לאורה הוא צריך:
@338 **ויעש כן אהרן.** להגיד שבחו של אהרן שלא שנה:
@339 **וזה מעשה המנורה.** שהראהו הקדוש ברוך הוא באצבע לפי שנתקשה בה, לכך נאמר וזה: **מקשה.** בטדי''ץ בלע''ז [עשוי בהכאה] לשון דא לדא נקשן (דניאל ה, ו) . עשת של ככר זהב היתה, ומקיש בקרנס וחותך בכשיל לפשט אבריה כתקונן, ולא נעשית אברים אברים על ידי חבור: **עד ירכה עד פרחה.** ירכה היא השדה שעל הרגלים, חלול כדרך מנורות כסף שלפני השרים: **עד ירכה עד פרחה.** כלומר גופה של מנורה כלה וכל התלוי בה: **עד ירכה.** שהוא אבר גדול: **עד פרחה.** שהוא מעשה דק שבה הכל מקשה. ודרך עד לשמש בלשון זה, כמו (שופטים טו, ה) מגדיש ועד קמה ועד כרם זית: **כמראה אשר הראה** וגו' **.** כתבנית אשר הראהו בהר, כמו שנאמר (שמות כה, מ) וראה ועשה בתבניתם וגו' : **כן עשה את המנורה.** מי שעשאה. ומדרש אגדה על ידי הקדוש ברוך הוא נעשית מאליה:
@341 **קח את הלוים.** קחם בדברים, אשריכם שתזכו להיות שמשים למקום:
@342 **הזה עליהם מי חטאת.** של אפר הפרה מפני טמאי מתים שבהם: **והעבירו תער.** מצאתי בדברי רבי משה הדרשן, לפי שנתנו כפרה על הבכורות שעבדו עבודה זרה והיא קרויה זבחי מתים, והמצורע קרוי מת, הזקיקם תגלחת כמצורעים:
@343 **ולקחו פר בן בקר.** והוא עולה, כמו שנאמר (פסוק יב) ועשה את האחד עולה, והוא קרבן צבור בעבודה זרה: **ופר שני.** מה תלמוד לומר שני, לומר לך, מה עולה לא נאכלת, אף חטאת לא נאכלת. ובזו יש סמך לדבריו בתורת כהנים. ואומר אני שהוראת שעה היתה, ששעיר היה להם להביא לחטאת עבודה זרה עם פר העולה:
@344 **והקהלת את כל עדת.** לפי שהלוים נתנים קרבן כפרה תחתיהם, יבואו ויעמדו על קרבנם ויסמכו את ידיהם עליהם:
@346 **והניף אהרן את הלוים תנופה.** כדרך שאשם מצורע טעון תנופה חי. שלש תנופות נאמרו בפרשה זו, הראשונה לבני קהת, לכך נאמר בם והיו לעבוד את עבודת ה', לפי שעבודת קדש הקדשים עליהם הארון והשלחן וגו' . השניה לבני גרשון, לכך נאמר בם תנופה לה', שאף עליהם היתה עבודת הקדש יריעות וקרסים הנראים בבית קדש הקדשים, והשלישית לבני מררי:
@351 **נתנים נתנים.** נתונים למשא נתונים לשיר: **פטרת.** פתיחת:
@352 **כי לי כל בכור.** שלי היו הבכורות בקו הדין, שהגנתי עליהם בין בכורי מצרים ולקחתי אותם לי עד שטעו בעגל, ועכשיו ואקח את הלוים:
@354 **ואתנה** וגו' **.** חמשה פעמים נאמר בני ישראל במקרא זה, להודיע חבתן שנכפלו אזכרותיהן במקרא אחד כמנין חמשה חמשי תורה, וכך ראיתי בבראשית רבה: **ולא יהיה בבני ישראל נגף.** שלא יצטרכו לגשת אל הקדש, שאם יגשו יהיה נגף:
@355 **ויעש משה ואהרן וכל עדת** וגו' **.** משה העמידן ואהרן הניפן וישראל סמכו את ידיהם:
@357 **כאשר צוה ה'** וגו' **כן עשו.** להגיד שבח העושין והנעשה בהן, שאחד מהן לא עכב:
@359 **זאת אשר ללוים.** שנים פוסלים בהם, ואין המומים פוסלים בהם: **מבן חמש ועשרים.** ובמקום אחר אומר (במדבר ד, ג) מבן שלשים שנה, הא כיצד, מבן עשרים וחמש בא ללמוד הלכות עבודה ולומד חמש שנים, ובן שלשים עובד, מכאן לתלמיד שלא ראה סימן יפה במשנתו בחמש שנים, ששוב אינו רואה:
@360 **ולא יעבד עוד.** עבודת משא בכתף, אבל חוזר הוא לנעילת שערים ולשיר ולטעון עגלות, וזהו ושרת את אחיו עם אחוהי, כתרגומו:
@361 **לשמר משמרת.** לחנות סביב לאהל, ולהקים ולהוריד בשעת המסעות:
@362 **בחדש הראשון.** פרשה שבראש הספר לא נאמרה עד איר, למדת שאין סדר מקדם ומאחר בתורה. ולמה לא פתח בזו, מפני שהוא גנותן של ישראל, שכל ארבעים שנה שהיו ישראל במדבר לא הקריבו אלא פסח זה בלבד:
@363 **במועדו.** אף בשבת. במועדו אף בטמאה:
@364 **ככל חקתיו.** אלו מצות שבגופו, שה תמים זכר בן שנה: **וככל משפטיו.** אלו מצות שעל גופו ממקום אחר, כגון שבעת ימים למצה ולבעור חמץ. [מצות שבגופו, שה תמים זכר בן שנה. שעל גופו, צלי אש ראשו על כרעיו ועל קרבו. שחוץ לגופו, מצה ובעור חמץ] :
@365 **וידבר משה** וגו' **.** מה תלמוד לומר, והלא נאמר (ויקרא כג, מד) וידבר משה את מועדי ה', אלא כששמע פרשת מועדים מסיני, אמרה להם, וחזר והזהירם בשעת מעשה:
@367 **לפני משה ולפני אהרן.** כששניהם יושבין בבית המדרש באו ושאלום. ולא יתכן לומר זה אחר זה, שאם משה לא היה יודע, אהרן מנין לו:
@368 **למה נגרע.** אמר להם אין קדשים קרבים בטמאה. אמרו לו יזרק הדם עלינו בכהנים טהורים ויאכל הבשר לטהורים. אמר להם עמדו ואשמעה, כתלמיד המבטח לשמוע מפי רבו. אשרי ילוד אשה שכך מבטח, שכל זמן שהיה רוצה היה מדבר עם השכינה. וראויה היתה פרשה זו להאמר על ידי משה כשאר כל התורה כלה, אלא שזכו אלו שתאמר על ידיהן, שמגלגלין זכות על ידי זכאי:
@371 **או בדרך רחקה.** נקוד עליו, לומר לא שרחוקה ודאי, אלא שהיה חוץ לאסקפת העזרה כל זמן שחיטה. פסח שני מצה וחמץ עמו בבית ואין שם יום טוב, ואין אסור חמץ אלא עמו באכילתו:
@375 **וכי יגור אתכם גר ועשה פסח.** יכול כל המתגייר יעשה פסח מיד, תלמוד לומר חקה אחת וגו', אלא כך משמעו, וכי יגור אתכם גר ובא עת לעשות פסח עם חבריו כחקה וכמשפט יעשה:
@376 **המשכן לאהל העדת.** המשכן העשוי להיות אהל ללוחות העדות: **יהיה על המשכן.** כמו הוה על המשכן, וכן כל לשון הפרשה:
@378 **העלות הענן.** כתרגומו אסתלקות, וכן ונעלה הענן. ולא יתכן לכתוב ולפי עלות הענן ועלה הענן, שאין זה לשון סלוק אלא צמוח ועליה, כמו (מלכים א' יח, מד) והנה עב קטנה ככף איש עלה מים:
@379 **על פי ה' יסעו.** שנינו במלאכת המשכן, כיון שהיו ישראל נוסעים היה עמוד הענן מתקפל ונמשך על גבי בני יהודה כמין קורה, תקעו והריעו ותקעו ולא היה מהלך עד שמשה אומר קומה ה', ונסע דגל מחנה יהודה, זו בספרי: **ועל פי ה' יחנו.** כיון שהיו ישראל חונים, עמוד הענן מתמר ועולה ונמשך על גבי בני יהודה כמין סכה, ולא היה נפרש עד שמשה אומר שובה ה' רבבות אלפי ישראל, הוי אומר על פי ה' וביד משה:
@381 **ויש.** כלומר ופעמים: **ימים מספר.** ימים מועטים:
@383 **או ימים.** שנה, כמו (ויקרא כה, כט) ימים תהיה גאלתו:
@386 **עשה לך.** שיהיו תוקעין לפניך כמלך, כמו שנאמר (דברים לג, ה) ויהי בישרון מלך: **עשה לך.** משלך: [ **עשה לך.** אתה עושה ומשתמש בהם ולא אחר] : **למקרא העדה.** כשתרצה לדבר עם הסנהדרין ושאר העם ותקראם לאסף אליך, תקראם על ידי חצוצרות: **ולמסע את המחנות.** בשעת סלוק מסעות תתקעו בהם לסימן, נמצאת אתה אומר על פי שלשה היו נוסעים, על פי הקדוש ברוך הוא ועל פי משה ועל פי חצוצרות: **מקשה.** מהעשת תעשה בהקשת הקרנס:
@387 **ותקעו בהן.** בשתיהן והוא סימן למקרא העדה, שנאמר ונועדו אליך כל העדה אל פתח אהל מועד:
@388 **ואם באחת יתקעו.** הוא סימן למקרא הנשיאים, שנאמר ונועדו אליך הנשיאים. ואף הן יעידתן אל פתח אהל מועד. ומגזרה שוה הוא בא בספרי:
@389 **ותקעתם תרועה.** סימן מסע המחנות תקיעה תרועה ותקיעה, כך הוא נדרש בספרי מן המקראות היתרים:
@391 **ובהקהיל את הקהל** וגו' **.** לפי שהוא אומר והיו לך למקרא העדה ולמסע את המחנות מה מקרא העדה, תוקע בשני כהנים ובשתיהן, שנאמר ותקעו בהן וגו' , אף מסע המחנות בשתיהן, יכול מה מסע המחנות תוקע ומריע ותוקע אף מקרא העדה תוקע ומריע ותוקע, ומעתה אין חלוק בין מקרא העדה למסע את המחנות תלמוד לומר ובהקהיל את הקהל וגו' , למד שאין תרועה למקרא העדה והוא הדין לנשיאים. הרי סימן לשלשתם, מקרא העדה בשתים, ושל נשיאים באחת, וזו וזו אין בהם תרועה, ומסע המחנות בשתים על ידי תרועה ותקיעה:
@392 **ובני אהרן יתקעו.** במקראות ובמסעות הללו:
@394 **על עלתיכם.** בקרבן צבור הכתוב מדבר: **אני ה' אלהיכם.** מכאן למדנו מלכיות עם זכרונות ושופרות, שנאמר ותקעתם הרי שופרות, לזכרון הרי זכרונות, אני ה' אלהיכם זה מלכיות וכו' :
@395 **בחדש השני.** נמצאת אומר שנים עשר חדש חסר עשרה ימים עשו בחורב, שהרי בראש חדש סיון חנו שם ולא נסעו עד עשרים באיר לשנה הבאה:
@396 **למסעיהם.** כמשפט המפורש למסע דגליהם מי ראשון ומי אחרון: **במדבר פארן.** קברות התאוה במדבר פארן היה ושם חנו ממסע זה:
@401 **והורד המשכן.** כיון שנוסע דגל יהודה נכנסו אהרן ובניו ופרקו את הפרכת וכסו בה את הארון, שנאמר (במדבר ד, ה) ובא אהרן ובניו בנסוע המחנה, ובני גרשון ובני מררי פורקין המשכן וטוענין אותו בעגלות ונוסעים, והארון וכלי הקדש של משא בני קהת עומדים מכסין ונתונין על המוטות עד שנסע דגל מחנה ראובן, ואחר כך ונסעו הקהתים:
@405 **נשאי המקדש.** נושאי הדברים המקדשים: **והקימו את המשכן.** בני גרשון ובני מררי, שהיו קודמים להם מסע שני דגלים, היו מקימין את המשכן, כשהיה הענן שוכן, וסימן החניה נראה בדגל מחנה יהודה והם חונים, ועדין בני קהת באים מאחריהם עם שני דגלים האחרונים, היו בני גרשון ובני מררי מקימין את המשכן, וכשבאים בני קהת מוצאים אותו על מכונו, ומכניסין בו הארון והשלחן והמנורה והמזבחות, וזהו משמעות המקרא והקימו מקימי המשכן אותו עד טרם בואם של בני קהת:
@409 **מאסף לכל המחנות.** תלמוד ירושלמי לפי שהיה שבטו של דן מרבה באכלוסין היה נוסע באחרונה וכל מי שהיה מאבד דבר היה מחזירו לו. אית מאן [אתיא כמאן] דאמר כתיבה היו מהלכין, ומפיק לה מן (במדבר ב, יז) כאשר יחנו כן יסעו. ואית דאמרי כקורה היו מהלכין ומפיק לה מן מאסף לכל המחנות:
@412 **אלה מסעי.** זה סדר מסעיהם: **ויסעו.** ביום ההוא נסעו:
@413 **חבב.** הוא יתרו, שנאמר (שופטים ד, יא) מבני חבב חותן משה, ומה תלמוד לומר (שמות ב, יח) ותבאנה אל רעואל אביהן, מלמד שהתינוקות קורין לאבי אביהן אבא. ושמות הרבה [ושני שמות] היו לו יתר על שם שיתר פרשה אחת בתורה. חובב על שחבב את התורה וכו' : **נסעים אנחנו אל המקום.** מיד עד שלשה ימים אנו נכנסין לארץ, שבמסע זה הראשון נסעו על מנת להכנס לארץ ישראל, אלא שחטאו במתאוננים. ומפני מה שתף משה עצמו עמהם, שעדין לא נגזרה גזרה עליו וכסבור שהוא נכנס:
@414 **אל ארצי ואל מולדתי.** אם בשביל נכסי, אם בשביל משפחתי:
@415 **אל נא תעזב.** אין נא אלא לשון בקשה, שלא יאמרו לא נתגיר יתרו מחבה, סבור היה שיש לגרים חלק בארץ, עכשו שראה שאין להם חלק הניחם והלך לו: **כי על כן ידעת חנתנו במדבר.** כי נאה לך לעשות זאת על אשר ידעת חנותנו במדבר וראית נסים וגבורות שנעשו לנו: **כי על כן ידעת.** כמו על אשר ידעת, כמו (בראשית לח, כו) כי על כן לא נתתיה לשלה בני, כי על כן עברתם (שם יח, ה) , כי על כן באו (שם יט, ח) , כי על כן ראיתי פניך (שם לג, י) : **והיית לנו לעינים.** לשון עבר כתרגומו. דבר אחר לשון עתיד, כל דבר ודבר שיתעלם מעינינו תהיה מאיר עינינו. דבר אחר שתהא חביב עלינו כגלגל עינינו, שנאמר (דברים י, יט) ואהבתם את הגר:
@416 **והיה הטוב ההוא** וגו' **.** מה טובה הטיבו לו, אמרו כשהיו ישראל מחלקין את הארץ היה דשנה של יריחו חמש מאות אמה על חמש מאות אמה והניחוהו מלחלוק, אמרו מי שיבנה בית המקדש בחלקו הוא יטלנו, בין כך ובין כך נתנוהו לבני יתרו ליונדב בן רכב, שנאמר ובני קני חותן משה עלו מעיר התמרים וגו' (שופטים א, טז) :
@417 **דרך שלשת ימים.** מהלך שלשת ימים הלכו ביום אחד, שהיה הקדוש ברוך הוא חפץ להכניסם לארץ מיד: **וארון ברית ה' נסע לפניהם דרך שלשת ימים.** זה הארון היוצא עמהם למלחמה ובו שברי לוחות מנחים ומקדים לפניהם דרך שלשת ימים לתקן להם מקום חניה:
@418 **וענן ה' עליהם יומם.** שבעה עננים כתובים במסעיהם. ארבע מארבע רוחות, ואחד למעלה, ואחד למטה, ואחד לפניהם מנמיך את הגבוה ומגביה את הנמוך והורג נחשים ועקרבים: **מן המחנה.** ממקום חניתן:
@419 **ויהי בנסע הארן.** עשה לו סימניות מלפניו ומלאחריו, לומר שאין זה מקומו. ולמה נכתב כאן, כדי להפסיק בין פרענות לפרענות וכו' כדאיתא בכל כתבי הקדש (שבת קטז, א) : **קומה ה'.** לפי שהיה מקדים לפניהם מהלך שלשת ימים, היה משה אומר עמוד והמתן לנו ואל תתרחק יותר במדרש תנחומא בויקהל: **ויפוצו אויביך.** המכנסין: **וינסו משנאיך.** אלו הרודפים: **משנאיך.** אלו שונאי ישראל, שכל השונא את ישראל שונא את מי שאמר והיה העולם, שנאמר (תהלים פג, ג) ומשנאיך נשאו ראש, ומי הם, על עמך יערימו סוד:
@420 **שובה ה'.** מנחם תרגמו לשון מרגוע וכן (ישעיה ל, טו) בשובה ונחת תושעון: **רבבות אלפי ישראל.** מגיד שאין השכינה שורה בישראל פחותים משני אלפים ושתי רבבות:
@421 **ויהי העם כמתאננים.** אין העם אלא רשעים. וכן הוא אומר (שמות יז, ד) מה אעשה לעם הזה, ואומר (ירמיה יג, י) העם הרע הזה. וכשהם כשרים קרואים עמי, שנאמר (שמות ה) שלח את עמי, (מיכה ו ג) עמי מה עשיתי לך: **כמתאננים.** אין מתאוננים אלא לשון עלילה מבקשים עלילה היאך לפרוש מאחרי המקום וכן הוא אומר בשמשון (שופטים יד ד) כי תאנה הוא מבקש: **רע באזני ה'.** תואנה שהיא רעה באזני ה' שמתכונים שתבא באזניו ויקניט. אמרו אוי לנו כמה לבטנו בדרך הזה שלשה ימים, שלא נחנו מענוי הדרך: **ויחר אפו.** אני הייתי מתכון לטובתכם שתכנסו לארץ מיד: **בקצה המחנה.** במקצין שבהם לשפלות, אלו ערב רב. רבי שמעון בן מנסיא אומר בקצינים שבהם ובגדולים:
@422 **ויצעק העם אל משה.** משל למלך בשר ודם שכעס על בנו והלך הבן אצל אוהבו של אביו ואמר לו צא ובקש עלי מאבא: **ותשקע האש.** שקעה במקומה בארץ שאלו חזרה לאחת הרוחות היתה מקפלת והולכת כל אותו הרוח:
@424 **והאספסף.** אלו ערב רב שנאספו אליהם בצאתם ממצרים: **וישבו.** גם בני ישראל ויבכו עמהם: **מי יאכלנו בשר.** וכי לא היה להם בשר, והלא כבר נאמר (שמות יב, לח) וגם ערב רב עלה אתם וצאן ובקר וגו' . ואם תאמר אכלום, והלא בכניסתם לארץ נאמר (במדבר לב, א) ומקנה רב היה לבני ראובן וגו' , אלא שמבקשים עלילה:
@425 **אשר נאכל במצרים חנם.** אם תאמר שמצריים נותנים להם דגים חנם, והלא כבר נאמר (שמות ה, יח) ותבן לא ינתן לכם, אם תבן לא היו נותנין להם חנם, דגים היו נותנין להם חנם, ומהו אומר חנם, חנם מן המצות: **את הקשאים.** אמר ר' שמעון מפני מה המן משתנה לכל דבר חוץ מאלו, מפני שהן קשים למניקות, אומרים לאשה אל תאכלי שום ובצל מפני התינוק. משל למלך וכו' , כדאיתא בספרי: **הקשאים.** הם קוקומברי''ש בלע''ז [מלפפנים] : **אבטחים.** בורק''ש **החציר.** כרישין פוריל''ש ותרגומו ית בוציניא וכו' :
@426 **אל המן עינינו.** מן בשחר מן בערב:
@427 **והמן כזרע גד.** מי שאמר זה לא אמר זה, ישראל אומרים בלתי אל המן עינינו, והקדוש ברוך הוא הכתיב בתורה והמן כזרע גד וגו' , כלומר ראו באי עולם על מה מתלוננים בני, והמן כך וכך הוא חשוב: **כזרע גד.** עגול כגדא זרע אליינדר''א [כוסבר] : **הבדלח.** שם אבן טובה קריסט''ל :
@428 **שטו.** אין שיט אלא לשון טיול אישבני''ר בלא עמל: **וטחנו ברחים** וגו' **.** לא ירד בריחים ולא בקדירה ולא במדוכה אלא משתנה היה טעמו לנטחנין ולנדוכין ולמבשלין: **בפרור.** קדרה: **לשד השמן.** לחלוח של שמן, כך פרשו דונש. ודומה לו (תהלים לב, ד) נהפך לשדי בחרבוני קיץ. והלמ''ד יסוד, נהפך לחלוחי בחרבוני קיץ. ורבותינו פרשוהו לשון שדים, אך אין ענין שדים אצל שמן. ואי אפשר לומר לשד השמן לשון (דברים לב, טו) וישמן ישורון, שאם כן היה המי''ם נקוד קמ''ץ קטן וטעמו למטה תחת המי''ם, עכשיו שהמי''ם נקוד פת''ח קטן והטעם תחת השי''ן, לשון שמן הוא, והשי''ן הנקודה בקמץ גדול ואינה נקודה בפתח קטן מפני שהוא סוף פסוק. דבר אחר לשד לשון נוטריקון ליש שמן דבש, כעיסה הנלושה בשמן וקטופה בדבש. ותרגום של אונקלוס דמתרגם דליש במשחא, נוטה לפתרונו של דונש, שהעיסה הנלושה בשמן, לחלוחית שמן יש בה:
@430 **בכה למשפחתיו.** משפחות משפחות נאספים ובוכים לפרסם תרעמתן בגלוי. ורבותינו אמרו למשפחתיו על עסקי משפחות, על עריות הנאסרות להם:
@432 **כי תאמר אלי.** שאתה אומר אלי שאהו בחיקך. והיכן אמר לו כן, לך נחה את העם (שמות לב) , ואומר (שם ו) ויצום אל בני ישראל, על מנת שיהיו סוקלים אתכם ומחרפים אתכם: **על האדמה אשר נשבעת לאבתיו.** אתה אומר לי לשאתם בחיקי:
@435 **ואם ככה את עשה לי.** תשש כחו של משה כנקבה כשהראהו הקדוש ברוך הוא הפרענות שהוא עתיד להביא עליהם על זאת. אמר לפניו, אם כן הרגני תחלה: **ואל אראה ברעתי.** ברעתם היה לו לכתוב, אלא שכנה הכתוב. וזה אחד מתקוני סופרים בתורה לכנוי ולתקון הלשון:
@436 **אספה לי.** הרי תשובה לתלנתך שאמרת לא אוכל אנכי לבדי. והזקנים הראשונים היכן היו, והלא אף במצרים ישבו עמהם, שנאמר (שמות ג, טז) לך ואספת את זקני ישראל, אלא באש תבערה מתו. וראויים היו לכך מסיני, דכתיב (שמות כד) ויחזו את האלהים, שנהגו קלות ראש, כנושך פתו ומדבר בפני המלך. וזהו (שם) ויאכלו וישתו, ולא רצה הקדוש ברוך הוא לתן אבלות במתן תורה ופרע להם כאן: **אשר ידעת כי הם** וגו' **.** אותם שאתה מכיר שנתמנו עליהם שוטרים במצרים בעבודת פרך והיו מרחמים עליהם ומכים על ידם, שנאמר (שמות ה, יד) ויכו שוטרי בני ישראל, עתה יתמנו בגדלתן כדרך שנצטערו בצרתן: **ולקחת אתם.** קחם בדברים, אשריכם שנתמניתם פרנסים על בניו של מקום: **והתיצבו שם עמך.** כדי שיראו ישראל וינהגו בהם גדלה וכבוד ויאמרו חביבין אלה שנכנסו עם משה לשמוע דבור מפי הקב,, ה:
@437 **וירדתי.** זו אחת מעשר ירידות הכתובות בתורה: **ודברתי עמך.** ולא עמהם: **ואצלתי.** כתרגומו וארבי, כמו (שמות כד, יא) ואל אצילי בני ישראל: **ושמתי עליהם.** למה משה דומה באותה שעה, לנר שמנח על גבי מנורה והכל מדליקין המנו, ואין אורו חסר כלום: **ונשאו אתך.** התנה עמהם על מנת שיקבלו עליהם טורח בני, שהם טרחנים וסרבנים: **ולא תשא אתה לבדך.** הרי תשובה למה שאמרת לא אוכל אנכי לבדי:
@438 **התקדשו.** הזמינו עצמכם לפרענות, וכן הוא אומר (ירמיה יב, ג) והקדשם ליום הרגה:
@440 **עד חדש ימים.** זו בכשרים שמתמצין על מטותיהן ואחר כך נשמתן יוצאה, וברשעים הוא אומר הבשר עודנו בין שניהם, כך היא שנויה בספרי, אבל במכילתא שנויה חלוף הרשעים אוכלין ומצטערין שלשים יום והכשרים הבשר עודנו בין שניהם: **עד אשר יצא מאפכם.** כתרגומו דתקוצון ביה, יהא דומה לכם כאלו אכלתם ממנו יותר מדאי עד שיוצא ונגעל לחוץ דרך האף: **והיה לכם לזרא.** שתהיו מרחקין אותו יותר ממה שקרבתם. ובדברי רבי משה הדרשן ראיתי שיש לשון שקורין לחרב זרא: **את ה' אשר בקרבכם.** אם לא שנטעתי שכינתי ביניכם, לא גבה לבבכם לכנס לכל הדברים הללו:
@441 **שש מאות אלף רגלי.** לא חש למנות את הפרט שלשת אלפים היתרים. ור' משה הדרשן פרש שלא בכו אלא אותן שיצאו ממצרים:
@442 **הצאן ובקר ישחט.** זה אחד מארבעה דברים שהיה רבי עקיבא דורש ואין רבי שמעון דורש כמותו. רבי עקיבא אומר שש מאות אלף רגלי, ואתה אמרת בשר אתן להם ואכלו חדש ימים, הצאן ובקר וגו' , הכל כמשמעו, מי יספיק להם, כענין שנאמר (ויק' כה) ומצא כדי גאלתו. ואיזו קשה, זו או (במ' כ) שמעו נא המרים, אלא לפי שלא אמר ברבים חסך לו הכתוב ולא נפרע ממנו, וזו של מריבה היתה בגלוי, לפיכך לא חסך לו הכתוב. רבי שמעון אומר חס ושלום לא עלתה על דעתו של אותו צדיק כך, מי שכתוב בו (במ' יב) בכל ביתי נאמן הוא, יאמר אין המקום מספיק לנו, אלא כך אמר שש מאות אלף רגלי וגו' ואתה אמרת בשר אתן לחדש ימים, ואחר כך תהרוג אמה גדולה כזו, הצאן ובקר ישחט להם כדי שיהרגו, ותהא אכילה זו מספקתן עד עולם, וכי שבחך הוא זה, אומרים לו לחמור טול כור שעורים ונחתוך ראשך. השיבו הקדוש ברוך הוא ואם לא אתן יאמרו שקצרה ידי, הטוב בעיניך שיד ה' תקצר בעיניהם, יאבדו הם ומאה כיוצא בהם ואל תהי ידי קצרה לפניהם אפלו שעה אחת:
@443 **עתה תראה היקרך דברי.** רבן גמליאל בנו של רבי יהודה הנשיא אומר אי אפשר לעמוד על התפל, מאחר שאינן מבקשים אלא עלילה לא תספיק להם, סופן לדון אחריך, אם אתה נותן להם בשר בהמה גסה, יאמרו דקה בקשנו, ואם אתה נותן להם דקה, יאמרו גסה בקשנו, חיה ועוף בקשנו, דגים וחגבים בקשנו, אמר לו אם כן יאמרו שקצרה ידי. אמר לפניו הריני הולך ומפיסן. אמר לו עתה תראה היקרך דברי, שלא ישמעו לך. הלך משה לפיסן אמר להם היד ה' תקצר, (תהלים עח, כ) הן הכה צור ויזובו מים וגו' הגם לחם יוכל תת, אמרו פשרה היא זו, אין בו כח למלאת שאלתנו. וזהו שנאמר ויצא משה וידבר אל העם, כיון שלא שמעו לו ויאסף שבעים איש וגו' :
@445 **ולא יספו.** לא נתנבאו אלא אותו היום לבדו, כך מפורש בספרי, ואונקלוס תרגם ולא פסקין, שלא פסקה נבואה מהם:
@446 **וישארו שני אנשים.** מאותן שנבחרו. אמרו אין אנו כדאין לגדלה זו: **והמה בכתבים.** במבוררים שבהם לסנהדרין, ונכתבו כלם נקובים בשמות, ועל ידי גורל, לפי שהחשבון עולה לשנים עשר שבטים, ששה ששה לכל שבט ושבט חוץ משני שבטים שאין מגיע אליהם אלא חמשה חמשה. אמר משה, אין שבט שומע לי לפחות משבטו זקן אחד. מה עשה, נטל שבעים ושנים פתקין וכתב על שבעים זקן, ועל שנים חלק וברר מכל שבט ושבט ששה, והיו שבעים ושנים. אמר להם טלו פתקיכם מתוך קלפי, מי שעלה בידו זקן, נתקדש, ומי שעלה בידו חלק אמר לו המקום לאחפץ בך:
@447 **וירץ הנער.** יש אומרים גרשום בן משה היה:
@448 **כלאם.** הטל עליהם צרכי צבור והם כלים מאליהם. דבר אחר תנם אל בית הכלא, לפי שהיו מתנבאים משה מת ויהושע מכניס את ישראל לארץ:
@449 **המקנא אתה לי.** הקנאי אתה לי הקנאתי אתה מקנא: **לי.** כמו בשבילי. כל לשון קנאה אדם הנותן לב על הדבר או לנקום או לעזור אינפרינמינ''ט בלע''ז אוחז בעבי המשא:
@450 **ויאסף משה.** מפתח אהל מועד: **אל המחנה.** נכנסו איש לאהלו: **ויאסף.** לשון כניסה אל הבית, כמו (דברים כב, ב) ואספתו אל תוך ביתך, ואב לכלם (תהלים לט) יצבר ולא ידע מי אספם, מלמד שלא הביא עליהם פרענות עד שנכנסו הצדיקים איש לאהלו:
@451 **ויגז.** ויפריח, וכן (תהלים צ, י) כי גז חיש, וכן (נחום א, יב) נגזו ועבר: **ויטש.** ויפשוט, כמו (שמואל א' ל, טז) והנה נטשים על פני כל הארץ, (יחזקאל כט, ה) ונטשתיך המדברה: **וכאמתים.** פורחות בגובה עד שהן כנגד לבו של אדם, כדי שלא יהא טורח באסיפתן לא להגביה ולא לשחות:
@452 **הממעיט.** מי שאוסף פחות מכלם, העצלים והחגרים, אסף עשרה חמרים: **וישטחו.** עשו אותן משטיחין משטיחין:
@453 **טרם יכרת.** כתרגומו עד לא פסק. דבר אחר אינו מספיק לפסקו בשניו עד שנשמתו יוצאה:
@456 **ותדבר.** אין דבור בכל מקום אלא לשון קשה, וכן הוא אומר (בראשית מב, ל) דבר האיש אדני הארץ אתנו קשות, ואין אמירה בכל מקום אלא לשון תחנונים, וכן הוא אומר (בראשית יט, ז) ויאמר אל נא אחי תרעו, (במדבר יב, ו) ויאמר שמעו נא דברי, כל נא לשון בקשה: **ותדבר מרים ואהרן.** היא פתחה בדבור תחלה, לפיכך הקדימה הכתוב תחלה, ומנין היתה יודעת מרים שפרש משה מן האשה, רבי נתן אומר, מרים היתה בצד צפורה בשעה שנאמר למשה אלדד ומידד מתנבאים במחנה, כיון ששמעה צפורה, אמרה אוי לנשותיהן של אלו אם הם נזקקים לנבואה שיהיו פורשין מנשותיהן כדרך שפרש בעלי ממני, ומשם ידעה מרים והגידה לאהרן. ומה מרים שלא נתכונה לגנותו, כך נענשה, קל וחמר למספר בגנותו של חברו: **האשה הכשית.** מגיד שהכל מודים ביפיה, כשם שהכל מודים בשחרותו של כושי: **כושית.** בגימטריא יפת מראה: **על אדות האשה.** על אודות גרושיה: **כי אשה כשית לקח.** מה תלמוד לומר, אלא יש לך אשה נאה ביפיה ואינה נאה במעשיה, במעשיה ולא ביפיה, אבל זאת נאה בכל: **האשה הכשית.** על שם נויה נקראת כושית כאדם הקורא את בנו נאה כושי, כדי שלא תשלט בו עין רעה: **כי אשה כשית לקח.** ועתה גרשה:
@457 **הרק אך.** עמו לבדו דבר ה': **הלא גם בנו דבר.** ולא פרשנו מדרך ארץ:
@458 **ענו.** שפל וסבלן:
@459 **פתאם.** נגלה עליהם פתאם, והם טמאים בדרך ארץ, והיו צועקים מים מים, להודיעם שיפה עשה משה שפרש מן האשה, מאחר שנגלית עליו שכינה תדיר ואין עת קבועה לדבור: **צאו שלשתכם.** מגיד ששלשתן נקראו בדבור אחד, מה שאי אפשר לפה לומר ולאזן לשמוע:
@460 **בעמוד ענן.** יצא יחידי, שלא כמדת בשר ודם. מלך בשר ודם כשיוצא למלחמה יוצא באכלוסין, וכשיוצא לשלום יוצא במועטים, ומדת הקדוש ברוך הוא יוצא למלחמה יחידי, שנאמר (שמות טו, ג) ה' איש מלחמה, ויוצא לשלום באכלוסין, שנאמר (תהלים סח, יח) רכב אלהים רבתים אלפי שנאן: **ויקרא אהרן ומרים.** שהיו נמשכין ויוצאין מן החצר לקראת הדבור: **ויצאו שניהם.** ומפני מה משכן והפרידן ממשה, לפי שאומרים מקצת שבחו של אדם בפניו וכלו שלא בפניו, וכן מצינו בנח, שלא בפניו נאמר (בראשית ו, ט) איש צדיק תמים, ובפניו נאמר (בראשית ז, א) כי אתך ראיתי צדיק לפני. דבר אחר שלא ישמע בנזיפתו של אהרן:
@461 **שמעו נא דברי.** אין נא אלא לשון בקשה: **אם יהיה נביאכם.** אם יהיו לכם נביאים: **ה' במראה אליו אתודע.** שכינת שמי אין נגלית עליו באספקלריא המאירה אלא בחלום וחזיון:
@463 **פה אל פה.** אמרתי לו לפרוש מן האשה. והיכן אמרתי לו, בסיני (דברים ה, כז) לך אמר להם שובו לכם לאהליכם, ואתה פה עמד עמדי: **ומראה ולא בחידת.** מראה זה מראה דבור, שאני מפרש לו דבורי במראית פנים שבו ואיני סותמו לו בחידות, כענין שנאמר ליחזקאל (יחזקאל יז, ב) חוד חידה וגו' , יכול מראה שכינה, תלמוד לומר (שמות לג, כ) לא תוכל לראות את פני: **ותמנת ה' יביט.** זה מראה אחורים, כענין שנאמר (שמות לג, כג) וראית את אחרי: **בעבדי במשה.** אינו אומר בעבדי משה, אלא בעבדי במשה, בעבדי אף על פי שאינו משה, במשה אפלו אינו עבדי, כדאי הייתם לירא מפניו, וכל שכן שהוא עבדי ועבד מלך מלך, היה לכם לומר אין המלך אוהבו חנם. ואם תאמרו איני מכיר במעשיו, זו קשה מן הראשונה:
@464 **ויחר אף ה' בם וילך.** מאחר שהודיעם סרחונם גזר עליהם נדוי, קל וחמר לבשר ודם שלא יכעס על חברו עד שיודיענו סרחונו:
@465 **והענן סר.** ואחר כך והנה מרים מצרעת כשלג, משל למלך שאמר לפדגוג, רדה את בני, אבל לא תרדנו עד שאלך מאצלך, שרחמי עליו:
@466 **נואלנו.** כתרגומו לשון אויל:
@467 **אל נא תהי.** אחותנו זו: **כמת.** שהמצורע חשוב כמת, מה מת מטמא בביאה, אף מצורע מטמא בביאה: **אשר בצאתו מרחם אמו.** אמנו היה לו לומר, אלא שכנה הכתוב. וכן חצי בשרו, חצי בשרנו היה לו לומר, אלא שכנה הכתוב. מאחר שיצאה מרחם אמנו היא לנו כאלו נאכל חצי בשרנו, כענין שנאמר (בראשית לז, כז) כי אחינו בשרנו הוא. ולפי משמעו אף הוא נראה כן, אין ראוי לאח להניח את אחותו להיות כמת: **אשר בצאתו.** מאחר שיצא זה מרחם אמו של זה שיש כח בידו לעזור ואינו עוזרו, הרי נאכל חצי בשרו, שאחיו בשרו הוא. דבר אחר אל נא תהי כמת, אם אינך רופאה בתפלה, מי מסגירה ומי מטהרה, אני אי אפשר לראותה, שאני קרוב ואין קרוב רואה את הנגעים, וכהן אחר אין בעולם, וזהו אשר בצאתו מרחם אמו:
@468 **אל נא רפא נא לה.** בא הכתוב ללמדך דרך ארץ, שהשואל דבר מחברו צריך לומר שנים או שלשה דברי תחנונים ואחר כן יבקש שאלותיו: **לאמר.** מה תלמוד לומר, אמר לו השיבני אם אתה מרפא אותה אם לאו, עד שהשיבו ואביה ירק ירק וגו' . רבי אלעזר בן עזריה אומר בארבעה מקומות בקש משה מלפני הקדוש ברוך הוא להשיבו אם יעשה שאלותיו אם לאו, כיוצא בו (שמות ו, יב) וידבר משה לפני ה' לאמר וגו' , מה תלמוד לומר לאמר, השיבני אם גואלם אתה אם לאו, עד שהשיבו עתה תראה וגו' . כיוצא בו (במדבר כז, טו. טז) וידבר משה אל ה' לאמר יפקד ה' אלהי הרוחות לכל בשר, השיבו קח לך (במד' כז, יח) . כיוצא בו (דברים ג) ואתחנן אל ה' בעת ההיא לאמר, השיבו רב לך: **רפא נא לה.** מפני מה לא האריך משה בתפלה, שלא יהיו ישראל אומרים אחותו נתונה בצרה והוא עומד ומרבה בתפלה [דבר אחר שלא יאמרו ישראל בשביל אחותו הוא מאריך בתפלה, אבל בשבילנו אינו מאריך בתפלה] :
@469 **ואביה ירק ירק בפניה.** ואם אביה הראה לה פנים זועפות הלא תכלם שבעת ימים, קל וחמר לשכינה ארבעה עשר יום, אלא דיו לבא מן הדין להיות כנדון, לפיכך אף בנזיפתי תסגר שבעת ימים: **ואחר תאסף.** אומר אני כל האסיפות האמורות במצורעים על שם שהוא משלח מחוץ למחנה, וכשהוא נרפא נאסף אל המחנה לכך כתוב בו אסיפה לשון הכנסה:
@470 **והעם לא נסע.** זה הכבוד חלק לה המקום בשביל שעה אחת שנתעכבה למשה כשהשלך ליאור, שנאמר (שמות ב, ד) ותתצב אחותו מרחק וגו' :
@473 **שלח לך אנשים.** למה נסמכה פרשת מרגלים לפרשת מרים, לפי שלקתה על עסקי דבה שדברה באחיה, ורשעים הללו ראו ולא לקחו מוסר: **שלח לך.** לדעתך, אני איני מצוה לך, אם תרצה שלח, לפי שבאו ישראל ואמרו (דברים א, כב) נשלחה אנשים לפנינו, כמה שנאמר (שם) ותקרבון אלי כלכם וגו' , ומשה נמלך בשכינה. אמר אני אמרתי להם שהיא טובה, שנאמר (שמות ג, יז) אעלה אתכם מעני מצרים וגו' , חייהם שאני נותן להם מקום לטעות בדברי המרגלים למען לא יירשוה:
@474 **על פי ה'.** ברשותו, שלא עכב על ידו: **כלם אנשים.** כל אנשים שבמקרא לשון חשיבות, ואותה שעה כשרים היו:
@487 **ויקרא משה להושע** וגו' **.** התפלל עליו יה יושיעך מעצת מרגלים:
@488 **עלו זה בנגב.** הוא היה הפסולת של ארץ ישראל, שכן דרך התגרים מראין את הפסולת תחלה ואחר כך מראין את השבח:
@489 **את הארץ מה היא.** יש ארץ מגדלת גבורים ויש ארץ מגדלת חלשים יש מגדלת אכלוסין ויש ממעטת אכלוסין: **החזק הוא הרפה.** סימן מסר להם, אם בפרזים יושבין, חזקים הם שסומכין על גבורתם, ואם בערים בצורות הם יושבין, חלשים הם:
@490 **הבמחנים.** תרגומו הבפצחין, כרכין פצוחין ופתוחין מאין חומה: **הטובה היא.** במעינות ותהומות טובים ובריאים:
@491 **היש בה עץ.** אם יש בהם אדם כשר שיגין עליהם בזכותו: **בכורי ענבים.** ימים שהענבים מתבשלין בבכור:
@492 **ממדבר צן עד רחב לבא חמת.** הלכו בגבוליה באורך וברוחב כמין גאם, הלכו רוח גבול דרומית ממקצוע מזרח עד מקצוע מערב, כמו שצוה משה עלו זה בנגב, דרך גבול דרומית מזרחית עד הים, שהים הוא גבול מערבי. ומשם חזרו והלכו כל גבול מערבי על שפת הים עד לבא חמת, שהוא אצל הר ההר במקצוע מערבית צפונית, כמו שמפורש בגבולות הארץ בפרשת אלה מסעי:
@493 **ויבא עד חברון.** כלב לבדו הלך שם ונשתטח על קברי אבות, שלא יהא נסת לחבריו להיות בעצתם, וכן הוא אומר (דברים א, לו) ולו אתן את הארץ אשר דרך בה, וכתיב (שופטים א, כ) ויתנו לכלב את חברון: **שבע שנים נבנתה.** אפשר שבנה חם את חברון לכנען בנו הקטן קודם שיבנה את צוען למצרים בנו הגדול, אלא שהיתה מבנה בכל טוב על אחד משבעה בצוען. ובא להודיעך שבחה של ארץ ישראל, שאין לך טרשין בארץ ישראל יותר מחברון, לפיכך הקצוה לקברות מתים, ואין לך מעלה בכל ארצות כמצרים, שנאמר (בראשית יג, י) כגן ה' כארץ מצרים, וצוען היא המעלה שבארץ מצרים ששם מושב המלכים, שנאמר (ישעיה ל, ד) כי היו בצוען שריו, והיתה חברון טובה ממנה שבעה חלקים:
@494 **זמורה.** שוכת גפן ואשכול של ענבים תלוי בה: **וישאהו במוט בשנים.** ממשמע שנאמר וישאהו במוט איני יודע שהוא בשנים, מה תלמוד לומר בשנים, בשני מוטות. הא כיצד, שמונה נטלו אשכול, אחד נטל תאנה ואחד רמון, יהושע וכלב לא נטלו כלום, לפי שכל עצמם להוציא דבה נתכונו, כשם שפריה משנה כך עמה משנה. ואם חפץ אתה לידע כמה משאוי אחד מהם צא ולמד מאבנים שהקימו בגלגל, (יהושע ד ה) והרימו לכם איש אבן אחת על שכמו, והקימוה בגלגל. ושקלום רבותינו משקל כל אחת ארבעים סאה. וגמירי, טונא דמדלי אנש על כתפיה, אינו אלא שליש משאוי ממשאוי שמסיעין אותו להרים:
@496 **וישבו מתור הארץ מקץ ארבעים יום.** והלא ארבע מאות פרסה על ארבע מאות פרסה היא, ומהלך אדם בינוני עשרה פרסאות ליום, הרי מהלך ארבעים יום מן המזרח למערב והם הלכו ארכה ורחבה, אלא שגלוי לפני הקדוש ברוך הוא שיגזור עליהם יום לשנה, קצר לפניהם את הדרך:
@497 **וילכו ויבאו.** מהו וילכו, להקיש הליכתן לביאתן, מה ביאתן בעצה רעה, אף הליכתן בעצה רעה: **וישיבו אתם דבר.** את משה ואת אהרן:
@498 **זבת חלב ודבש הוא.** כל דבר שקר שאין אומרים בו קצת אמת בתחלתו, אין מתקים בסופו:
@499 **בצרות.** לשון חזק, ותרגומו כריכן, לשון בירניות עגלות, ובלשון ארמי כריך. עגול:
@500 **עמלק יושב** וגו' **.** לפי שנכוו בעמלק כבר, הזכירוהו מרגלים כדי ליראם: **על יד הירדן.** יד כמשמעו, אצל הירדן, ולא תוכלו לעבור:
@501 **ויהס כלב.** השתיק את כלם: **אל משה.** לשמוע מה שידבר במשה. צוח ואמר וכי זו בלבד עשה לנו בן עמרם. השומע היה סבור שבא לספר בגנותו, מתוך שהיה בלבם על משה בשביל דברי המרגלים. שתקו כלם לשמוע גנותו, אמר והלא קרע לנו את הים והוריד לנו את המן והגיז לנו את השלו: **עלה נעלה.** אפלו בשמים והוא אומר עשו סלמות ועלו שם נצליח בכל דבריו: **ויהס.** לשון שתיקה, וכן (זכריה ב, יז) הס כל בשר, (עמוס ו, י) הס כי לא להזכיר. כן דרך בני אדם הרוצה לשתק אגדת אנשים אומר הס:
@502 **חזק הוא ממנו.** כביכול כלפי מעלה אמרו:
@503 **אוכלת יושביה.** בכל מקום שעברנו מצאנום קוברי מתים, והקדוש ברוך הוא עשה לטובה כדי לטרדם באבלם ולא יתנו לב לאלו: **אנשי מדות.** גדולים וגבוהים וצריך לתת להם מדה, כגון גלית (שמואל א' יז, ד) גבהו שש אמות וזרת, וכן (שמואל ב' כא, כ) איש מדון, (ד''ה א' יא, כג) איש מדה:
@504 **הנפילים.** ענקים מבני שמחזאי ועזאל שנפלו מן השמים בימי דור אנוש: **וכן היינו בעיניהם.** שמענו אומרים זה לזה נמלים יש בכרמים כאנשים: **ענק.** שמעניקים חמה בקומתן:
@505 **כל העדה.** סנהדראות:
@506 **לו מתנו.** הלואי ומתנו:
@508 **נתנה ראש.** כתרגומו נמני רישא, נשים עלינו מלך, ורבותינו פרשו לשון עבודה זרה:
@513 **אל תמרדו.** ושוב ואתם אל תיראו: **כי לחמנו הם.** נאכלם כלחם: **סר צלם.** מגנם וחזקם. כשרים שבהם מתו, איוב שהיה מגין עליהם. דבר אחר צלו של מקום סר מעליהם:
@514 **לרגום אתם.** את יהושע וכלב: **וכבוד ה'.** הענן ירד שם:
@515 **עד אנה.** עד היכן: **ינאצני.** ירגיזוני: **בכל האתות.** בשביל כל הנסים שעשיתי להם היה להם להאמין שהיכולת בידי לקים הבטחתי:
@516 **ואורשנו.** לשון תרוכין. ואם תאמר מה אעשה לשבועת אבות: **ואעשה אתך לגוי גדול.** שאתה מזרעם:
@517 **ושמעו מצרים.** ושמעו את אשר תהרגם: **כי העלית.** כי משמש בלשון אשר, והם ראו אשר העלית בכחך הגדול אותם מקרבם וכשישמעו שאתה הורגם לא יאמרו שחטאו לך, אלא יאמרו שכנגדם יכלת להלחם אבל כנגד יושבי הארץ לא יכלת להלחם. וזה הוא:
@518 **ואמרו אל יושב הארץ הזאת.** כמו על יושב הארץ הזאת. ומה יאמרו עליהם, מה שאמור בסוף הענין, מבלתי יכלת ה', בשביל ששמעו כי אתה ה' שוכן בקרבם, ועין בעין אתה ה' נראה להם, והכל בדרך חבה, ולא הכירו בך שנתקה אהבתך מהם עד הנה:
@519 **והמתה את העם הזה כאיש אחד.** פתאום, ומתוך כך יאמרו הגוים אשר שמעו את שמעך וגו' :
@520 **מבלתי יכלת** וגו' **.** לפי שיושבי הארץ חזקים וגבורים, ואינו דומה פרעה לשלשים ואחד מלכים, זאת יאמרו על יושב הארץ הזאת: **מבלתי יכלת.** מתוך שלא היה יכלת בידו להביאם שחטם: **יכלת.** שם דבר הוא:
@521 **יגדל נא כח ה'.** לעשות דבורך: **כאשר דברת לאמר.** ומהו הדבור:
@522 **ה' ארך אפים.** לצדיקים ולרשעים. כשעלה משה למרום מצאו משה להקדוש ברוך הוא שהיה יושב וכותב ה' ארך אפים. אמר לו לצדיקים. אמר לו הקדוש ברוך הוא אף לרשעים. אמר לו רשעים יאבדו. אמר לו הקדוש ברוך הוא חייך שתצטרך לדבר. כשחטאו ישראל בעגל ובמרגלים התפלל משה לפניו בארך אפים, אמר לו הקב''ה והלא אמרת לי לצדיקים. אמר לו והלא אמרת לי אף לרשעים: **ונקה.** לשבים: **לא ינקה.** לשאינן שבים:
@524 **כדברך.** בשביל מה שאמרת פן יאמרו מבלתי יכלת ה':
@525 **ואולם.** כמו אבל זאת אעשה להם: **חי אני.** לשון שבועה. כשם שאני חי וכבודי ימלא את כל הארץ, כך אקים להם, כי כל האנשים הרואים וגו' אם יראו את הארץ. הרי זה מקרא מסורס, חי אני כי כל האנשים אם יראו את הארץ וכבודי ימלא את כל הארץ, שלא יתחלל שמי במגפה הזאת לומר מבלתי יכלת ה' להביאם, שלא אמיתם פתאום כאיש אחד אלא באחור ארבעים שנה מעט מעט:
@526 **וינסו.** כמשמעו: **זה עשר פעמים.** שנים בים שנים במן ושנים בשלו וכו' , כדאיתא במסכת ערכין (טו, א) :
@527 **אם יראו.** לא יראו: **לא יראוה.** לא יראו את הארץ:
@528 **רוח אחרת.** שתי רוחות אחת בפה ואחת בלב, למרגלים אמר, אני עמכם בעצה, ובלבו היה לומר האמת ועל ידי כן היה בו כח להשתיקם, כמו שנאמר (לעיל יג, ל) ויהס כלב, שהיו סבורים שיאמר כמותם, זהו שנאמר בספר (יהושע יד, ז) ואשב אתו דבר כאשר עם לבבי, ולא כאשר עם פי: **וימלא אחרי.** וימלא את לבו אחרי וזה מקרא קצר: **אשר בא שמה.** חברון תנתן לו: **יורשנה.** כתרגומו יתרכינה, יורישו את הענקים ואת העם אשר בה, ואין לתרגמו יירתינה, אלא במקום יירשנה:
@529 **והעמלקי** וגו' **.** אם תלכו שם יהרגו אתכם, מאחר שאיני עמכם: **מחר פנו.** לאחוריכם וסעו לכם וגו' :
@531 **לעדה הרעה** וגו' **.** אלו המרגלים, מכאן לעדה שהיא עשרה: **אשר המה מלינים.** את ישראל עלי: **את תלנות בני ישראל אשר המה מלינים.** המרגלים מלינים אותם עלי שמעתי:
@532 **חי אני.** לשון שבועה: **אם לא** וגו' **כן אעשה.** כביכול איני חי: **כאשר דברתם.** שבקשתם ממני או במדבר הזה לו מתנו (פסוק ב) :
@533 **וכל פקדיכם לכל מספרכם.** כל הנמנה לכל מספר, שאתם נמנין בו, כגון לצאת ולבא לצבא ולתת שקלים, כל המנויים לכל אותן מספרות ימותו, ואלו הן מבן כ' שנה וגו', להוציא שבטו של לוי שאין פקודיהם מבן עשרים:
@536 **ופגריכם אתם.** כתרגומו לפי שדבר על הבנים להכניסם לארץ ובקש לומר ואתם תמותו, נופל לשון זה כאן לומר אתם:
@537 **ארבעים שנה.** לא מת אחד מהם פחות מבן ששים, לכך נגזר ארבעים, כדי שיהיו אותם של בני עשרים מגיעין לכלל ששים. ושנה ראשונה היתה בכלל, ואף על פי שקדמה לשלוח המרגלים, לפי שמשעשו את העגל עלתה גזרה זו במחשבה אלא שהמתין להם עד שתתמלא סאתם, וזהו שנאמר (שמות לב, לד) וביום פקדי, במרגלים, ופקדתי עליהם חטאתם, ואף כאן נאמר תשאו את עונתיכם, שתי עונות של עגל ושל תלונה. וחשב להם במנין חייהם מקצת שנה ככלה, וכשנכנסו לשנת ששים מתו אותם של בני עשרים: **ונשאו את זנותיכם.** כתרגומו ויקבלון ית חוביכון:
@538 **את תנואתי.** שהניאותם את לבבכם מאחרי. תנואה לשון הסרה, כמו (במדבר ל, ו) כי הניא אביה אתה:
@540 **וישבו וילינו עליו.** וכששבו מתור הארץ הרעימו עליו את כל העדה בהוצאת דבה אותם אנשים וימותו. כל הוצאת דבה לשון חנוך דברים, שמלקיחים לשונם לאדם לדבר בו, כמו (שה''ש ז, י) דובב שפתי ישנים. וישנה לטובה וישנה לרעה, לכך נאמר כאן מוצאי דבת הארץ רעה, שיש דבה שהיא טובה: **דבה.** פרלדי''ץ בלע''ז [לשון הרע] :
@541 **במגפה לפני ה'.** באותה מיתה ההגונה להם מדה כנגד מדה. הם חטאו בלשון, ונשתרבב לשונם עד טבורם ותולעים יוצאים מלשונם ובאין לתוך טבורם, לכך נאמר במגפה ולא במגפה, וזהו לפני ה', באותה הראויה להם על פי מדותיו של הקדוש ברוך הוא, שהוא מודד מדה כנגד מדה:
@542 **ויהושע וכלב חיו** וגו' **.** מה תלמוד לומר חיו מן האנשים ההם, אלא מלמד שנטלו חלקם של מרגלים בארץ וקמו תחתיהם לחיים:
@544 **אל ראש ההר.** והוא הדרך העולה לארץ ישראל: **הננו ועלינו אל המקום.** לארץ ישראל: **אשר אמר ה'.** לתתה לנו שם נעלה: **כי חטאנו.** על אשר אמרנו הלא טוב לנו שוב מצרימה:
@545 **והוא לא תצלח.** זו שאתם עושין לא תצלח:
@547 **כי על כן שבתם.** כלומר כי זאת תבא לכם על אשר שבתם וגו' :
@548 **ויעפלו.** לשון חוזק וכן (חבקוק ב, ד) הנה עפלה. אינגרי''ש בלע''ז [עזי רוח] לשון עזות, וכן (מיכה ד, ח) עפל בת ציון, (ישעיה לב, יד) עפל ובחן. ומדרש תנחומא מפרשו לשון אופל, הלכו חשכים שלא ברשות:
@549 **ויכתום.** כמו (דברים ט, כא) ואכת אתו טחון, מכה אחר מכה: **עד החרמה.** שם המקום נקרא על שם המאורע:
@551 **כי תבאו.** בשר להם שיכנסו לארץ:
@552 **ועשיתם אשה.** אין זה צווי אלא כשתבאו שם ותעלה על לבבכם לעשות אשה לה': **ריח ניחח.** שיהיה נחת רוח לפני: **לפלא נדר או בנדבה** וגו' **.** או שתעשו האשה בשביל חובת מועדיכם שחייבתי אתכם לעשות במועד:
@553 **והקריב המקריב.** תקריבו נסכים ומנחה לכל בהמה המנחה כליל, והשמן נבלל בתוכה, והיין לספלים, כמו ששנינו במסכת סכה (סוכה מח, א) :
@554 **לכבש האחד.** על כל האמור למעלה הוא מוסב על המנחה ועל השמן ועל היין:
@555 **או לאיל.** ואם איל הוא. ורבותינו דרשו או לרבות את הפלגס לנסכי איל:
@559 **אשה ריח.** אינו מוסב אלא על המנחה והשמן, אבל היין אינו אשה, שאינו נתן על האש:
@560 **או לשה.** בין שהוא בכבשים בין שהוא בעזים כבש ושה קרוים בתוך שנתם: **איל.** בן שלשה עשר חדש ויום אחד:
@561 **כמספר אשר תעשו.** כמספר הבהמות אשר תקריבו לקרבן, ככה תעשו נסכים לכל אחד מהם: **כמספרם.** של בהמות מספרם של נסכים:
@564 **ככם כגר.** כמותכם כן גר וכן דרך לשון עברית, (בראשית יג, י) כגן ה' כארץ מצרים, כן ארץ מצרים, (מ''א כב, ד) כמוני כמוך כעמי כעמך:
@567 **בבאכם אל הארץ.** משנה ביאה זו מכל ביאות שבתורה, שבכלן נאמר כי תבא, כי תבאו, לפיכך כלן למדות זו מזו וכיון שפרט לך הכתוב באחת מהן שאינה אלא לאחר ירשה וישיבה, אף כלן כן, אבל זו נאמר בה בבאכם, משנכנסו בה ואכלו מלחמה נתחיבו בחלה:
@569 **ראשית ערסתכם.** כשתלושו כדי עיסתכם שאתם רגילין ללוש במדבר. וכמה היא, (שמות טז, טז) וימדו בעמר עמר לגלגלת, תרימו מראשיתה, כלומר קודם שתאכלו ממנה, ראשית תלקח חלה אחת תרומה לשם ה': **חלה.** טורטי''ל בלע''ז [עוגה] : **כתרומת גרן.** שלא נאמר בה שעור ולא כתרומת מעשר שנאמר בה שעור, אבל חכמים נתנו שעור, לבעל הבית אחד מעשרים וארבעה, ולנחתום אחד מארבעים ושמונה:
@570 **מראשית ערסתיכם.** למה נאמר, לפי שנאמר ראשית עריסותיכם, שומע אני ראשונה שבעיסות, תלמוד לומר מראשית, מקצתה ולא כלה: **תתנו לה' תרומה.** לפי שלא שמענו שעור לחלה, נאמר תתנו, שיהא בה כדי נתינה:
@571 **וכי תשגו ולא תעשו.** עבודה זרה היתה בכלל כל המצות שהצבור מביאין עליהן פר, והרי הכתוב מוציאה כאן מכללן לדון בפר לעולה ושעיר לחטאת: **וכי תשגו** וגו' **.** בעבודה זרה הכתוב מדבר, או אינו אלא באחת מכל המצות, תלמוד לומר את כל המצות האלה, מצוה אחת שהיא ככל המצות, מה העובר על כל המצות פורק עול ומפר ברית ומגלה פנים, אף מצוה זו פורק בה עול ומפר ברית ומגלה פנים ואיזו, זו עבודה זרה: **אשר דבר ה' אל משה.** אנכי ולא יהיה לך מפי הגבורה שמענום, (תהלים סב, יב) אחת דבר אלהים שתים זו שמעתי:
@572 **את כל אשר צוה** וגו' **.** מגיד שכל המודה בעבודה זרה ככופר בכל התורה כלה ובכל מה שנתנבאו הנביאים, שנאמר למן היום אשר צוה ה' והלאה:
@573 **אם מעיני העדה נעשתה לשגגה.** אם מעיני העדה נעשתה עברה זו על ידי שוגג, כגון ששגגו והורו על אחת מן העבודות שהיא מתרת לעבוד עבודה זרה בכך: **לחטת.** חסר א' שאינו כשאר חטאות, שכל חטאות שבתורה הבאות עם עולה החטאת קודמת לעולה, שנאמר (ויקרא ה, י) ואת השני יעשה עולה, וזו עולה קודמת לחטאת:
@574 **הביאו את קרבנם אשה לה'.** זה האמור בפרשה הוא פר העולה שנאמר אשה לה': **וחטאתם.** זה השעיר:
@576 **תחטא בשגגה.** בעבודה זרה: **עז בת שנתה.** שאר עברות יחיד מביא כשבה או שעירה ובזו קבע לה שעירה:
@579 **ביד רמה.** במזיד: **מגדף.** מחרף, כמו (יחזקאל ה, טו) והיתה חרפה וגדופה, (ישעיה לז, ו) אשר גדפו נערי מלך אשור. עוד דרשו רבותינו מכאן למברך את השם שהוא בכרת:
@580 **דבר ה'.** אזהרת עבודה זרה מפי הגבורה, והשאר מפי משה: **עונה בה.** בזמן שעונה בה שלא עשה תשובה:
@581 **ויהיו בני ישראל במדבר וימצאו.** בגנותן של ישראל דבר הכתוב, שלא שמרו אלא שבת ראשונה, ובשניה בא זה וחללה:
@582 **המצאים אתו מקושש.** שהתרו בו ולא הניח מלקושש אף משמצאוהו והתרו בו:
@583 **כי לא פרש מה יעשה לו.** לא היו יודעים באיזו מיתה ימות, אבל יודעים היו שהמחלל שבת במיתה:
@584 **רגום.** כמו עשה פיישנ''ט בלע''ז וכן הלוך אלנ''ט וכן זכור ושמור:
@585 **ויציאו אתו.** מכאן שבית הסקילה חוץ ורחוק מבית דין:
@587 **ועשו להם ציצת.** על שם הפתילים התלויים בה, כמו (יחזקאל ח, ג) ויקחני בציצית ראשי. דבר אחר ציצית על שם וראיתם אתו, כמו (שה''ש ב, ט) מציץ מן החרכים: **על כנפי בגדיהם.** כנגד (שמות יט, ד) ואשא אתכם על כנפי נשרים. על ארבע כנפות ולא בעלת שלש ולא בעלת חמש, כנגד ארבע לשונות של גאלה שנאמר במצרים (שמות ו) והוצאתי והצלתי וגאלתי ולקחתי: **פתיל תכלת.** על שם שכול בכורות. תרגומו של שכול תכלא. ומכתם היתה בלילה וכן צבע התכלת דומה לצבע רקיע המשחיר לעת ערב. ושמונה חוטים שבה, כנגד שמונה ימים ששהו ישראל משיצאו ממצרים עד שאמרו שירה על הים: **תכלת.** צבע ירוק של חלזון:
@588 **וזכרתם את כל מצות ה'.** שמנין גימטריא של ציצית שש מאות, ושמונה חוטים וחמשה קשרים הרי תרי''ג: **ולא תתורו אחרי לבבכם.** כמו (לעיל יג, כה) מתור הארץ. הלב והעינים הם מרגלים לגוף ומסרסרים לו את העברות, העין רואה והלב חומד והגוף עושה את העברות:
@590 **אני ה'.** נאמן לשלם שכר: **אלהיכם.** נאמן לפרע: **אשר הוצאתי אתכם.** על מנת כן פדיתי אתכם שתקבלו עליכם גזרתי: **אני ה' אלהיכם.** עוד למה נאמר, כדי שלא יאמרו ישראל מפני מה אמר המקום, לא שנעשה ונטל שכר, אנו לא עושים ולא נוטלים שכר, על כרחכם אני מלככם. וכן הוא אומר (יחזקאל כ, לג) אם לא ביד חזקה וגו' אמלך עליכם. דבר אחר למה נאמר יציאת מצרים, אני הוא שהבחנתי במצרים בין טפה של בכור לשאינה של בכור, אני הוא עתיד להבחין ולהפרע מן התולה קלא אילן בבגדו ואומר תכלת היא. ומיסודו של רבי משה הדרשן העתקתי, למה נסמכה פרשת מקושש לפרשת עבודה זרה, לומר שהמחלל את השבת כעובד עבודה זרה, שאף היא שקולה ככל המצות, וכן הוא אומר בעזרא (נחמי' ט, יג. טו) ועל הר סיני ירדת ותתן לעמך תורה ומצות ואת שבת קדשך הודעת להם, ואף פרשת ציצית לכך נסמכה לאלו לפי שאף היא שקולה כנגד כל המצות, שנאמר ועשיתם את כל מצותי:
@591 **ויקח קרח.** פרשה זו יפה נדרשת במדרש רבי תנחומא: **ויקח קרח.** לקח את עצמו לצד אחד להיות נחלק מתוך העדה לעורר על הכהנה, וזהו שתרגם אנקלוס ואתפלג נחלק משאר העדה להחזיק במחלוקת, וכן (איוב טו, יב) מה יקחך לבך, לוקח אתך להפליגך משאר בני אדם. דבר אחר ויקח קרח משך ראשי סנהדראות שבהם בדברים, כמו שנאמר (במדבר כ, כה) קח את אהרן, (הושע יד, ג) קחו עמכם דברים: **בן יצהר בן קהת בן לוי.** ולא הזכיר בן יעקב, שבקש רחמים על עצמו שלא יזכר שמו על מחלקתם, שנאמר (בראשית מט, ו) בקהלם אל תחד כבדי. והיכן נזכר שמו על קרח, בהתיחסם על הדוכן בדברי הימים, שנאמר (ד''ה א' ו, כב. כג) בן אביאסף בן קרח בן יצהר בן קהת בן לוי בן ישראל: **ודתן ואבירם.** בשביל שהיה שבט ראובן שרוי בחניתם תימנה, שכן לקהת ובניו החונים תימנה, נשתתפו עם קרח במחלקתו, אוי לרשע אוי לשכנו. ומה ראה קרח לחלוק עם משה, נתקנא על נשיאותו של אליצפן בן עזיאל שמנהו משה נשיא על בני קהת על פי הדבור. אמר קרח, אחי אבא ארבעה היו, שנאמר (שמות ו, יח) ובני קהת וגו' . עמרם הבכור נטלו שני בניו גדלה, אחד מלך ואחד כהן גדול, מי ראוי לטול את השניה, לא אני שאני בן יצהר שהוא שני לעמרם, והוא מנה נשיא את בן אחיו הקטן מכלם, הריני חולק עליו ומבטל את דבריו. מה עשה, עמד וכנס מאתים חמשים ראשי סנהדראות, רבן משבט ראובן שכניו, והם אליצור בן שדיאור וחבריו וכיוצא בו, שנאמר נשיאי עדה קראי מועד, ולהלן הוא אומר (במדבר א, טז) אלה קרואי העדה, והלבישן טליתות שכלן תכלת. באו ועמדו לפני משה. אמרו לו טלית שכלה של תכלת חיבת בציצית או פטורה. אמר להם חיבת. התחילו לשחק עליו, אפשר טלית של מין אחר חוט אחד של תכלת פוטרה, זו שכלה תכלת לא תפטור את עצמה: **בני ראובן.** דתן ואבירם ואון בן פלת:
@593 **רב לכם.** הרבה יותר מדאי לקחתם לעצמכם גדלה: **כלם קדשים.** כלם שמעו דברים בסיני מפי הגבורה: **ומדוע תתנשאו.** אם לקחת אתה מלכות לא היה לך לברר לאחיך כהנה, לא אתם לבדכם שמעתם בסיני אנכי ה' אלהיך (שמות כ, ב) , כל העדה שמעו:
@594 **ויפל על פניו.** מפני המחלקת, שכבר זה בידם סרחון רביעי, חטאו בעגל (שמות לב, יא) ויחל משה, במתאוננים (במדבר יא, יב) ויתפלל משה, במרגלים (שם יד, יג) ויאמר משה אל ה' ושמעו מצרים, במחלקתו של קרח נתרשלו ידיו. משל לבן מלך שסרח על אביו ופייס עליו אוהבו פעם ושתים ושלש, כשסרח רביעית נתרשלו ידי האוהב ההוא. אמר עד מתי אטריח על המלך, שמא לא יקבל עוד ממני:
@595 **בקר וידע** וגו' **.** עתה עת שכרות הוא לנו ולא נכון להראות לפניו והוא היה מתכון לדחותם שמא יחזרו בהם: **בקר וידע ה' את אשר לו.** לעבודת לויה: **ואת הקדוש.** לכהנה: **והקריב.** אותם אליו. והתרגום מוכיח כן ויקריב לקדמוהי יקריב לשמושיה. ומדרשו בקר, אמר לו משה, גבולות חלק הקדוש ברוך הוא בעולמו, יכולים אתם להפוך בקר לערב, כן תוכלו לבטל את זו, שנאמר (בראשית א, ה. ז) ויהי ערב ויהי בקר ויבדל, כך (דה''א כג, יג) ויבדל אהרן להקדישו וגו' :
@596 **זאת עשו קחו לכם מחתות.** מה ראה לומר להם כך, אמר להם בדרכי הגוים יש נמוסים הרבה וכומרים הרבה ואין כלם מתקבצים בבית אחד, אנו אין לנו אלא ה' אחד, ארון אחד ותורה אחת ומזבח אחד וכהן גדול אחד ואתם מאתים וחמשים איש מבקשים כהנה גדולה, אף אני רוצה בכך, הא לכם תשמיש חביב מכל, היא הקטרת החביבה מכל הקרבנות וסם המות נתון בתוכו שבו נשרפו נדב ואביהוא, לפיכך התרה בהם והיה האיש אשר יבחר ה' הוא הקדוש, כבר הוא בקדשתו. וכי אין אנו יודעים שמי שיבחר הוא הקדוש, אלא אמר להם משה הריני אומר לכם שלא תתחיבו, מי שיבחר בו יצא חי, וכלכם אובדים: **מחתות.** כלים שחותין בהם גחלים ויש להם בית יד:
@597 **רב לכם בני לוי.** דבר גדול אמרתי לכם. ולא טפשים היו שכך התרה בהם וקבלו עליהם לקרב, אלא הם חטאו על נפשותם, שנאמר את מחתות החטאים האלה בנפשתם. וקרח שפקח היה מה ראה לשטות זה, עינו הטעתו, ראה שלשלת גדולה יוצאה ממנו, שמואל ששקול כנגד משה ואהרן. אמר בשבילו אני נמלט, ועשרים וארבע משמרות עומדות לבני בניו כלם מתנבאים ברוח הקדש, שנאמר (ד''ה א' כה, ה) כל אלה בנים להימן, אמר אפשר כל הגדלה הזאת עתידה לעמוד ממני ואני אדום, לכך נשתתף לבוא לאותה חזקה, ששמע מפי משה שכלם אובדים ואחד נמלט. אשר יבחר ה' הוא הקדוש, טעה ותלה בעצמו, ולא ראה יפה, לפי שבניו עשו תשובה, ומשה היה רואה. תנחומא: **רב לכם.** דבר גדול נטלתם בעצמכם לחלוק על הקדוש ברוך הוא:
@598 **ויאמר משה אל קרח שמעו נא בני לוי.** התחיל לדבר עמו דברים רכים, כיון שראהו קשה ערף, אמר עד שלא ישתתפו שאר השבטים ויאבדו עמו, אדבר גם אל כלם, התחיל לזרז בהם שמעו נא בני לוי:
@599 **ולעמד לפני העדה.** לשיר על הדוכן:
@600 **ויקרב אתך.** לאותו שרות שהרחיק ממנו שאר עדת ישראל:
@601 **לכן.** בשביל כך אתה וכל עדתך הנעדים אתך על ה' כי בשליחותו עשיתי לתת כהנה לאהרן ולא לנו היא המחלוקת הזו:
@602 **וישלח משה** וגו' **.** מכאן שאין מחזיקין במחלוקת, שהיה משה מחזר אחריהם להשלימם בדברי שלום: **לא נעלה.** פיהם הכשילם, שאין להם אלא ירידה:
@604 **ותתן לנו.** הדבר מוסב על לא האמור למעלה, כלומר לא הביאותנו ולא נתת לנו נחלת שדה וכרם, אמרת לנו (שמות ג, יז) אעלה אתכם מעני מצרים אל ארץ וגו' , משם הוצאתנו ולא אל ארץ זבת חלב ודבש הביאתנו, אלא גזרת עלינו להמיתנו במדבר, שאמרת לנו (במדבר יד, כט) במדבר הזה יפלו פגריכם: **העיני האנשים ההם תנקר** וגו' **.** אפלו אתה שולח לנקר את עינינו אם לא נעלה אליך, לא נעלה: **האנשים ההם.** כאדם התולה קללתו בחברו:
@605 **ויחר למשה מאד.** נצטער עד למאד: **אל תפן אל מנחתם.** לפי פשוטו הקטרת שהם מקריבים לפניך מחר אל תפן אליהם. והמדרש אומר יודע אני שיש להם חלק בתמידי צבור, אף חלקם לא יקבל לפניך לרצון, תניחנו האש ולא תאכלנו: **לא חמור אחד מהם נשאתי.** לא חמורו של אחד מהם נטלתי. אפלו כשהלכתי ממדין למצרים והרכבתי את אשתי ואת בני על החמור, והיה לי לטול אותו החמור משלהם, לא נטלתי אלא משלי. ותרגום אנקלוס, שחרית, לשון ארמי, כך נקראת אנגריא של מלך שחוור:
@606 **והם.** עדתך:
@607 **והקרבתם** וגו' **איש מחתתו.** החמשים ומאתים איש שבכם:
@609 **ויקהל עליהם קרח.** בדברי ליצנות. כל הלילה ההוא הלך אצל השבטים ופתה אותם כסבורין אתם שעלי לבדי אני מקפיד, איני מקפיד אלא בשביל כלכם. אלו באין ונוטלין כל הגדלות, לו המלכות ולאחיו הכהנה, עד שנתפתו כלם: **וירא כבוד ה'.** בא בעמוד ענן:
@612 **אל אלהי הרוחת.** יודע מחשבות. אין מדתך כמדת בשר ודם, מלך בשר ודם שסרחה עליו מקצת מדינה אינו יודע מי החוטא, לפיכך כשהוא כועס נפרע מכלם, אבל אתה לפניך גלויות כל המחשבות ויודע אתה מי החוטא: **האיש אחד.** הוא החוטא ואתה על כל העדה תקצוף. אמר הקדוש ברוך הוא יפה אמרת, אני יודע ומודיע מי חטא ומי לא חטא:
@614 **העלו** וגו' **.** כתרגומו הסתלקו מסביבות משכן קרח:
@615 **ויקם משה.** כסבור שישאו לו פנים ולא עשו:
@617 **יצאו נצבים.** בקומה זקופה לחרף ולגדף, כמו (שמואל א' יז, טז) ויתיצב ארבעים יום דגלית: **ונשיהם ובניהם וטפם.** בא וראה כמה קשה המחלוקת, שהרי בית דין של מטה אין עונשין אלא עד שיביא שתי שערות, ובית דין של מעלה עד עשרים שנה, וכאן אבדו אף יונקי שדים:
@618 **לעשות את כל המעשים האלה.** שעשיתי על פי הדבור לתת לאהרן כהנה גדולה ובניו סגני כהנה ואליצפן נשיא הקהתי:
@619 **לא ה' שלחני.** אלא אני עשיתי הכל מדעתי ובדין הוא חולק עלי:
@620 **ואם בריאה.** חדשה: **יברא ה'.** להמית אותם במיתה שלא מת בה אדם עד הנה, ומה היא הבריאה, ופצתה האדמה את פיה ותבלעם, אז וידעתם כי נאצו הם את ה', ואני מפי הגבורה אמרתי. ורבותינו פרשו אם בריאה. פה לארץ מששת ימי בראשית מוטב, ואם לאו יברא ה':
@624 **נסו לקולם.** בשביל הקול היוצא על בליעתן:
@627 **ואת האש.** שבתוך המחתות: **זרה הלאה.** לארץ מעל המחתות: **כי קדשו.** המחתות ואסורין בהנאה, שהרי עשאום כלי שרת:
@628 **החטאים האלה בנפשתם.** שנעשו פושעים בנפשתם, שנחלקו על הקדוש ברוך הוא: **רקעי.** רדידין: **פחים.** טסין מרדדין טינבי''ש בלע''ז : **צפוי למזבח.** למזבח הנחשת: **ויהיו לאות.** לזכרון, שיאמרו אלו היו מאותן שנחלקו על הכהנה ונשרפו:
@629 **וירקעום.** אטינבירנ ''ט בלע ''ז:
@630 **ולא יהיה כקרח.** כדי שלא יהיה כקרח: **כאשר דבר ה' ביד משה לו.** כמו עליו, על אהרן דבר אל משה, שיהיה הוא ובניו כהנים, לפיכך לא יקרב איש זר אשר לא מזרע אהרן וגו' , וכן כל לי ולו ולהם הסמוכים אצל דבור פתרונם כמו על. ומדרשו על קרח. ומהו ביד משה ולא כתב אל משה, רמז לחולקים על הכהנה שלוקין בצרעת, כמו שלקה משה בידו שנאמר (שמות ד, ו) ויוציאה והנה ידו מצרעת כשלג, ועל כן לקה עזיה בצרעת:
@636 **וכפר עליהם.** רז זה מסר לו מלאך המות כשעלה לרקיע, שהקטרת עוצר המגפה כדאיתא במסכת שבת (שבת פט א) :
@638 **ויעמד בין המתים** וגו' **.** אחז את המלאך והעמידו על כרחו. אמר לו המלאך הנח לי לעשות שליחותי. אמר לו משה צוני לעכב על ידך. אמר לו אני שלוחו של מקום ואתה שלוחו של משה. אמר לו אין משה אומר כלום מלבו אלא מפי הגבורה, אם אין אתה מאמין הרי הקדוש ברוך הוא ומשה אל פתח אהל מועד בא עמי ושאל. וזהו שנאמר וישב אהרן אל משה. דבר אחר למה בקטרת, לפי שהיו ישראל מליזין ומרננים אחר הקטרת לומר סם המות הוא, על ידו מתו נדב ואביהוא, על ידו נשרפו חמשים ומאתים איש, אמר הקדוש ברוך הוא תראו שעוצר מגפה הוא, והחטא הוא הממית:
@643 **כי מטה אחד.** אף על פי שחלקתים לשתי משפחות משפחת כהנה לבד ולויה לבד מכל מקום שבט אחד הוא:
@645 **והשכתי.** כמו וישכו המים (בראשית ח, א) , וחמת המלך שככה: (אסתר ז, י) כא **בתוך מטותם.** הניחו באמצע, שלא יאמרו מפני שהניחו בצד שכינה פרח:
@648 **ויצא פרח.** כמשמעו: **ציץ.** הוא חנטת הפרי כשהפרח נופל: **ויגמל שקדים.** כשהכר הפרי הכר שהן שקדים, לשון (בראשית כא, ח) ויגדל הילד ויגמל, ולשון זה מצוי בפרי האילן, כמו (ישעיה יח, ה) ובסר גמל יהיה נצה. ולמה שקדים, הוא הפרי הממהר להפריח מכל הפרות, אף המעורר על הכהנה פרענותו ממהרת לבא, כמו שמצינו בעזיה (ד''ה ב' כו, יט) והצרעת זרחה במצחו. ותרגומו וכפית שגדין, כמין אשכול שקדים יחד כפותים זה על זה:
@650 **למשמרת לאות.** לזכרון שבחרתי באהרן הכהן ולא ילונו עוד על הכהנה: **ותכל תלונתם.** כמו ותכלה תלונתם, לשון שם מפעל יחיד לנקבה כמו תלנתם מורמורי''ץ בלע''ז [תלנות] ויש חלוק בין תלנותם לתלנתם, תלנתם תלנה אחת, תלנותם שם דבר בלשון יחיד, ואפלו הם תלנות הרבה:
@653 **כל הקרב הקרב** וגו' **.** אין אנו יכולין להיות זהירין בכך, כלנו רשאין להכנס לחצר אהל מועד ואחד שיקריב עצמו יותר מחברו ויכנס לתוך אהל מועד ימות: **האם תמנו לגוע.** שמא הפקרנו למיתה:
@654 **ויאמר ה' אל אהרן.** למשה אמר שיאמר לאהרן להזהירו על תקנת ישראל שלא יכנסו למקדש: **אתה ובניך ובית אביך.** הם בני קהת אבי עמרם: **תשאו את עון המקדש.** עליכם אני מטיל ענש הזרים שיחטאו בעסקי הדברים המקדשים המסורים לכם הוא האהל והארון והשלחן וכלי הקדש אתם תשבו ותזהירו על כל זר הבא לגע: **ואתה ובניך.** הכהנים: **תשאו את עון כהנתכם.** שאינה מסורה ללוים ותזהירו הלוים השוגגים שלא יגעו אליכם בעבודתכם:
@655 **וגם את אחיך.** בני גרשון ובני מררי: **וילוו.** ויתחברו אליכם להזהיר גם את הזרים מלקרב אליהם: **וישרתוך.** בשמירת השערים ולמנות מהם גזברין ואמרכלין:
@657 **וזר לא יקרב אליכם.** אתכם אני מזהיר על כך:
@658 **ולא יהיה עוד קצף.** כמו שהיה כבר, שנאמר (במדבר יז, יא) כי יצא הקצף:
@659 **לכם מתנה נתנים.** יכול לעבודתכם של הדיוט, תלמוד לומר לה', כמו שמפורש למעלה, לשמור משמרת גזברין ואמרכלין:
@660 **עבדת מתנה.** במתנה נתתיה לכם:
@661 **ואני הנה נתתי לך.** בשמחה. לשון שמחה הוא זה, כמו (שמות ד, יד) הנה הוא יוצא לקראתך וראך ושמח בלבו, משל למלך שנתן שדה לאוהבו ולא כתב ולא חתם ולא העלה בערכאין. בא אחד וערער על השדה. אמר לו המלך כל מי שירצה יבא ויערער לנגדך, הריני כותב וחותם לך ומעלה בערכאין, אף כאן לפי שבא קרח וערער כנגד אהרן על הכהנה, בא הכתוב ונתן לו עשרים וארבע מתנות כהנה בברית מלח עולם, ולכך נסמכה פרשה זו לכאן: **משמרת תרומתי.** שאתה צריך לשמרן בטהרה: **למשחה.** לגדלה:
@662 **מן האש.** לאחר הקטרת האשים: **כל קרבנם.** כגון זבחי שלמי צבור: **מנחתם חטאתם ואשמם.** כמשמעו: **אשר ישיבו לי.** זה גזל הגר:
@663 **בקדש הקדשים תאכלנו** וגו' **.** למד על קדשי קדשים שאין נאכלין אלא בעזרה ולזכרי כהנה:
@664 **תרומת מתנם.** המורם מן התודה ומהשלמים ואיל נזיר: **לכל תנופת.** שהרי אלו טעונין תנופה: **כל טהור.** ולא טמאים. דבר אחר כל טהור לרבות אשתו:
@665 **ראשיתם.** היא תרומה גדולה:
@671 **כחזה התנופה וכשוק הימין.** של שלמים שנאכלים לכהנים לנשיהם ולבניהם ולעבדיהם לשני ימים ולילה אחד, אף הבכור נאכל לשני ימים ולילה אחד: **לך יהיה.** בא רבי עקיבא ולמד הוסיף לך הכתוב הויה אחרת, שלא תאמר כחזה ושוק של תודה, שאינו נאכל אלא ליום ולילה:
@672 **כל תרומת הקדשים.** מחבתה של פרשה זו כללה בתחלה וכללה בסוף ופרט באמצע: **ברית מלח עולם.** כרת ברית עם אהרן בדבר הבריא ומתקיים ומבריא את אחרים: **ברית מלח.** כברית הכרותה למלח שאינו מסריח לעולם:
@673 **וחלק לא יהיה לך בתוכם.** אף בבזה:
@676 **והם.** הלוים ישאו עונם של ישראל, שעליהם להזהיר הזרים מגשת אליהם:
@677 **אשר ירימו לה' תרומה.** הכתוב קראו תרומה עד שיפריש ממנו תרומת מעשר:
@680 **ונחשב לכם תרומתכם כדגן מן הגרן.** תרומת מעשר שלכם אסורה לזרים ולטמאים וחייבין עליה מיתה וחמש כתרומה גדולה שנקראת ראשית דגן מן הגרן: **וכמלאה מן היקב.** כתרומת תירוש ויצהר הנטלת מן היקבים: **מלאה.** לשון בשול תבואה שנתמלאת: **יקב.** הוא הבור שלפני הגת שהיין יורד לתוכו. וכל לשון יקב חפירת קרקע הוא, וכן (זכריה יד, י) יקבי המלך, הוא ים אוקיינוס חפירה שחפר מלכו של עולם:
@681 **כן תרימו גם אתם.** כמו שישראל מרימים מגרנם ומיקביהם תרימו גם אתם ממעשר שלכם, כי הוא נחלתכם:
@682 **מכל מתנתיכם תרימו את כל תרומת ה'.** בתרומה גדולה הכתוב מדבר, שאם הקדים לוי את הכהן בכרי וקבל מעשרותיו קודם שיטול כהן תרומה גדולה מן הכרי, צריך להפריש הלוי מן המעשר תחלה אחד מחמשים לתרומה גדולה, ויחזור ויפריש תרומת מעשר:
@683 **בהרימכם את חלבו ממנו.** לאחר שתרימו תרומת מעשר ממנו: **ונחשב.** המותר ללוים חלין גמורין: **כתבואת גרן.** לישראל, שלא תאמר הואיל וקראו הכתוב תרומה שנאמר כי את מעשר בני ישראל אשר ירימו לה' תרומה, יכול יהא כלו אסור, תלמוד לומר ונחשב ללוים כתבואת גרן, מה של ישראל חלין, אף של לוי חלין:
@684 **בכל מקום.** אפלו בבית הקברות:
@685 **ולא תשאו עליו חטא** וגו' **.** הא אם לא תרימו תשאו חטא: **ולא תמותו.** הא אם תחללו תמותו:
@687 **זאת חקת התורה.** לפי שהשטן ואמות העולם מונין את ישראל לומר מה המצוה הזאת ומה טעם יש בה, לפיכך כתב בה חקה, גזרה היא מלפני ואין לך רשות להרהר אחריה: **ויקחו אליך.** לעולם היא נקראת על שמך, פרה שעשה משה במדבר: **אדמה תמימה.** שתהא תמימה באדמימות, שאם היו בה שתי שערות שחורות פסולה: **ויקחו אליך.** משלהם כשם שהם פרקו נזמי הזהב לעגל משלהם כך יביאו זו לכפרה משלהם: **פרה אדמה.** משל לבן שפחה שטנף פלטין של מלך. אמרו תבא אמו ותקנח הצואה, כך תבא פרה ותכפר על העגל: **אדמה.** על שם (ישעיה א, יח) אם יאדימו כתולע, שהחטא קרוי אדום: **תמימה.** על שם ישראל שהיו תמימים ונעשו בו בעלי מומין, תבא זו ותכפר עליהם ויחזרו לתמותם: **לא עלה עליה על.** כשם שפרקו מעליהם עול שמים:
@688 **אלעזר.** מצותה בסגן: **אל מחוץ למחנה.** חוץ לשלש מחנות: **ושחט אתה לפניו.** זר שוחט ואלעזר רואה: **אל אלעזר הכהן.** כשם שנקהלו על אהרן, שהוא כהן, לעשות העגל. ולפי שאהרן עשה את העגל לא נעשית עבודה זו על ידו, שאין קטיגור נעשהסניגור:
@689 **אל נכח פני אהל מועד.** עומד במזרחו של ירושלים ומתכון ורואה פתחו של היכל בשעת הזאה הדם: **ושרף את הפרה.** כשם שנשרף העגל:
@691 **עץ ארז ואזוב ושני תולעת.** שלשה מינין הללו כנגד שלשת אלפי איש שנפלו בעגל. וארז הוא הגבוה מכל האילנות ואזוב נמוך מכלם, סימן שהגבוה שנתגאה וחטא, ישפיל את עצמו כאזוב ותולעת ויתכפר לו:
@692 **אל המחנה.** למחנה שכינה, שאין טמא משלח חוץ לשתי מחנות אלא זב ובעל קרי ומצורע: **וטמא הכהן עד הערב.** סרסהו ודרשהו וטמא עד הערב ואחר יבוא אל המחנה:
@694 **והניח מחוץ למחנה.** לשלשה חלקים מחלקה, אחד נתן בהר המשחה, ואחד מתחלק לכל המשמרות, ואחד נתן בחיל. זה של משמרות היה חוץ לעזרה לטול ממנו בני העירות וכל הצריכין להטהר, וזה שבהר המשחה כהנים גדולים לפרות אחרות מקדשין המנו, וזה שבחיל נתון למשמרת מגזרת הכתוב, שנאמר והיתה לעדת בני ישראל למשמרת: **למי נדה.** למי הזיה, כמו (איכה ג, נג) וידו אבן בי, (זכריה ב, ד) לידות את קרנות הגוים, לשון זריקה: **חטאת הוא.** לשון חטוי כפשוטו, ולפי הלכותיו קראה הכתוב חטאת, לומר, שהיא כקדשים להאסר בהנאה: **למשמרת.** כמו שפשע העגל שמור לדורות לפרענות, שאין לך פקודה שאין בה מפקודת העגל, שנאמר (שמות לב, לד) וביום פקדי ופקדתי וגו' . וכשם שהעגל טמא כל העוסקין בו, כך פרה מטמאה כל העוסקין בה, וכשם שנטהרו באפרו, שנאמר (שמות לב, כ) ויזר על פני המים וגו' , כך ולקחו לטמא מעפר שרפת החטאת וגו' :
@697 **הוא יתחטא בו.** באפר הזה:
@698 **במת בנפש.** ואי זה מת, של נפש האדם, להוציא נפש בהמה, שאין טמאתה צריכה הזאה. דבר אחר בנפש זו רביעית דם: **את משכן ה' טמא.** אם נכנס לעזרה אפלו בטבילה בלא הזאת שלישי ושביעי: **עוד טמאתו בו.** אף על פי שטבל:
@699 **כל הבא אל האהל.** בעוד שהמת בתוכו:
@700 **וכל כלי פתוח.** בכלי חרס הכתוב מדבר, שאין מקבל טמאה מגבו אלא מתוכו, לפיכך אם אין מגופת צמידתו פתולה עליו יפה בחבור, טמא הוא, הא אם יש צמיד פתיל עליו טהור: **פתיל.** לשון מחבר בלשון עברי, וכן (בראשית ל, ח) נפתולי אלהים נפתלתי, נתחברתי עם אחותי:
@701 **על פני השדה.** רבותינו דרשו לרבות גולל ודופק. ופשוטו על פני השדה, שאין שם אהל, מטמא המת שם בנגיעה:
@704 **וחטאו ביום השביעי.** הוא גמר טהרתו:
@705 **ואיש אשר יטמא** וגו' **.** אם נאמר מקדש למה נאמר משכן וכו' כדאיתא בשבועות (דף טז ב) :
@706 **ומזה מי הנדה.** רבותינו אמרו שהמזה טהור, וזה בא ללמד שהנושא מי חטאת טמא טמאה חמורה לטמא בגדים שעליו, מה שאין כן בנוגע. וזה שהוציאו בלשון מזה, לומר לך, שאינן מטמאין עד שיהא בהן שעור הזאה: **והנגע** וגו' **יטמא.** ואין טעון כבוס בגדים:
@707 **וכל אשר יגע בו.** הטמא הזה שנטמא במת יטמא: **והנפש הנגעת.** בו בטמא מת: **תטמא עד הערב.** מכאן למדנו שהמת אבי אבות הטמאה והנוגע בו אב הטמאה ומטמא אדם, זהו פרושה לפי משמעה והלכותיה: ומדרש אגדה העתקתי מיסודו שלר' משה הדרשן וזהו:
@708 **כל העדה.** עדה השלמה, שכבר מתו מתי מדבר ואלו פרשו לחיים: **ותמת שם מרים.** למה נסמכה פרשת מיתת מרים לפרשת פרה אדמה, לומר לך מה קרבנות מכפרין אף מיתת צדיקים מכפרת: **ותמת שם מרים.** אף היא בנשיקה מתה ומפני מה לא נאמר בה על פי ה', שאינו דרך כבוד של מעלה. ובאהרן נאמר על פי ה', באלה מסעי (במדבר לג, לח) :
@709 **ולא היה מים לעדה.** מכאן שכל ארבעים שנה היה להם הבאר בזכות מרים:
@710 **ולו גוענו.** הלואי שגוענו: **בגוע אחינו.** במיתת אחינו בדבר, למד שמיתת צמא מגנה ממנה: **בגוע.** שם דבר הוא, כמו במיתת אחינו, ולא יתכן לפרשו כשמתו אחינו, שאם כן היה לו להנקד בגוע:
@715 **ואת בעירם.** מכאן שחס הקדוש ברוך הוא על ממונם של ישראל:
@717 **ויקהלו** וגו' **.** זה אחד מן המקומות שהחזיק מועט את המרבה: **המן הסלע הזה נוציא.** לפי שלא היו מכירין אותו, לפי שהלך הסלע וישב לו בין הסלעים, כשנסתלק הבאר, והיו ישראל אומרים להם מה לכם מאיזה סלע תוציאו לנו מים, לכך אמר להם המרים סרבנים, לשון יוני שוטים, מורים את מוריהם, המן הסלע הזה שלא נצטוינו עליו נוציא לכם מים:
@718 **פעמים.** לפי שבראשונה לא הוציא אלא טפין, לפי שלא צוה המקום להכותו אלא ודברתם אל הסלע, והמה דברו אל סלע אחר ולא הוציא, אמרו שמא צריך להכות כבראשונה, שנאמר (שמות יז, ו) והכית בצור, ונזדמן להם אותו סלע והכהו:
@719 **יען לא האמנתם בי.** גלה הכתוב שאלולי חטא זה בלבד היו נכנסין לארץ, כדי שלא יאמרו עליהם כעון שאר דור המדבר, שנגזר עליהם שלא יכנסו לארץ, כך היה עון משה ואהרן. והלא (במדבר יא, כב) הצאן ובקר ישחט קשה מזו, אלא לפי שבסתר חסך עליו הכתוב, וכאן שבמעמד כל ישראל, לא חסך עליו הכתוב מפני קדוש השם: **להקדישני.** שאלו דברתם אל הסלע והוציא הייתי מקדש לעיני העדה ואומרים מה סלע זה שאינו מדבר ואינו שומע ואינו צריך לפרנסה מקים דבורו של מקום, קל וחמר אנו: **לכן לא תביאו.** בשבועה, כמו (שמואל א' ג, יד) לכן נשבעתי לבית עלי, נשבע בקפיצה כדי שלא ירבו בתפלה על כך:
@720 **המה מי מריבה.** הם הנזכרים במקום אחר, את אלו ראו אצטגניני פרעה שמושיען של ישראל לוקה במים, לכך גזרו (שמות א) כל הבן הילוד היאורה תשליכוהו: **ויקדש בם.** שמתו משה ואהרן על ידם. שכשהקדוש ברוך הוא עושה דין במקדשיו הוא יראוי ומתקדש על הבריות, וכן הוא אומר (תהלים סח, לו) נורא אלהים ממקדשיך, וכן הוא אומר (ויקרא י, ג) בקרובי אקדש:
@721 **אחיך ישראל.** מה ראה להזכיר כאן אחוה, אלא אמר לו אחים אנחנו בני אברהם, שנאמר לו (בראשית טו, יג) כי גר יהיה זרעך, ועל שנינו היה אותו החוב לפרעו: **אתה ידעת את כל התלאה.** לפיכך פרש אביכם מעל אבינו (שם לו, ו) וילך אל ארץ מפני יעקב אחיו, מפני השטר חוב המטל עליהם והטילו על יעקב:
@722 **וירעו לנו.** סבלנו צרות רבות: **ולאבותינו.** מכאן שהאבות מצטערים בקבר, כשפרענות באה על ישראל:
@723 **וישמע קלנו.** בברכה שברכנו אבינו (בראשית כז, כב) הקול קול יעקב, שאנו צועקים ונענים: **מלאך.** זה משה מכאן שהנביאים קרואים מלאכים, ואומר (ד''ה ב' לו, טז) ויהיו מלעיבים במלאכי האלהים:
@724 **נעברה נא בארצך.** אין לך לעורר על הירשה של ארץ ישראל, כשם שלא פרעת החוב. עשה לנו עזר מעט לעבור דרך ארצך: **ולא נשתה מי באר.** מי בורות היה צריך לומר אלא כך אמר משה אף על פי שיש בידינו מן לאכול ובאר לשתות, לא נשתה ממנו אלא נקנה מכם אוכל ומים להנאתכם, מכאן לאכסנאי שאף על פי שיש בידו לאכול, יקנה מן החנוני כדי להנות את אשפיזו: **דרך המלך נלך** וגו' **.** אנו חוסמים את בהמתנו ולא יטו לכאן ולכאן לאכול:
@725 **פן בחרב אצא לקראתך.** אתם מתגאים בקול שהורישכם אביכם, אמרתם (דברים כו, ז) ונצעק אל ה' וישמע קולנו, ואני אצא עליכם במה שהורישני אבי (בראשית כז, מ) ועל חרבך תחיה:
@726 **רק אין דבר.** אין שום דבר מזיקך:
@727 **וביד חזקה.** בהבטחת זקננו והידים ידי עשו:
@729 **כל העדה.** כלם שלמים ועומדים להכנס לארץ שלא היה בהן אחד מאותם שנגזרה גזרה עליהם שכבר כלו מתי מדבר, ואלו מאותן שכתוב בהן (דברים ד, ד) חיים כלכם היום: **הר ההר.** הר על גבי הר כתפוח קטן על גבי תפוח גדול, ואף על פי שהענן הולך לפניהם ומשוה את ההרים, שלשה נשארו בהן הר סיני לתורה והר נבו לקבורת משה והר ההר לקבורת אהרן:
@730 **על גבול ארץ אדום.** מגיד שמפני שנתחברו כאן להתקרב לעשו הרשע, נפרצו מעשיהם וחסרו הצדיק הזה, וכן הנביא אומר ליהושפט (דברי הימים ב' כ, לז) כהתחברך עם אחזיהו פרץ ה' את מעשיך:
@732 **קח את אהרן.** בדברי נחומים. אמור לו אשריך שתראה כתרך נתון לבנך מה שאין אני זכאי לכך:
@733 **את בגדיו.** את בגדי כהנה גדולה הלבישהו והפשיטם מעליו לתתם על בנו בפניו. אמר לו הכנס למערה, ונכנס. ראה מטה מצעת ונר דלוק. אמר לו עלה למטה, ועלה. פשוט ידיך, ופשט. קמוץ פיך, וקמץ. עצום עיניך, ועצם. מיד חמד משה לאותה מיתה, וזהו שנאמר לו (דברים לב, נ) כאשר מת אהרן אחיך, מיתה שנתאוית לה:
@734 **ויעש משה.** אף על פי שהדבר קשה לו לא עכב:
@736 **ויראו כל העדה** וגו' **.** כשראו משה ואלעזר יורדים ואהרן לא ירד, אמרו היכן הוא אהרן. אמר להם מת. אמרו לו אפשר מי שעמד כנגד המלאך ועצר את המגפה ישלוט בו מלאך המות. מיד בקש משה רחמים והראוהו מלאכי השרת להם מטל במטה, ראו והאמינו: **כל בית ישראל.** האנשים והנשים, לפי שהיה אהרן רודף שלום ומטיל אהבה בין בעלי מריבה ובין איש לאשתו: **כי גוע.** אומר אני שהמתרגם דהא מית טועה הוא, אלא אם כן מתרגם ויראו ואתחזיאו, שלא אמרו רבותינו זכרונם לברכה כי זה משמש בלשון דהא אלא על מדרש שנסתלקו ענני כבוד, וכדאמר ר' אבהו (ראש השנה ג, א) , דאמר רבי אבהו אל תקרי ויראו אלא ויראו ועל לשון זה נופל לשון דהא, לפי שהוא נתינת טעם למה של מעלה המנו. למה ויראו, לפי שהרי מת אהרן. אבל על תרגום וחזו כל כנישתא, אין לשון דהא נופל אלא לשון אשר, שהוא מגזרת שמוש אי, שמצינו אם משמש בלשון אשר, כמו (איוב כא, ד) ואם מדוע לא תקצר רוחי, והרבה מפורשים כזה הלשון (שם יד, ה) אם חרוצים ימיו:
@737 **וישמע הכנעני.** שמע שמת אהרן ונסתלקו ענני כבוד וכו' , כדאיתא בראש השנה (דף ג א) . ועמלק מעולם רצועת מרדות לישראל, מזמן בכל עת לפרענות: **ישב הנגב.** זה עמלק, שנאמר (במדבר יג, כט) עמלק יושב בארץ הנגב. ושנה את לשונו לדבר בלשון כנען, כדי שיהיו ישראל מתפללים להקדוש ברוך הוא לתת כנענים בידם והם אינם כנענים, ראו ישראל לבושיהם כלבושי עמלקים ולשונם לשון כנען, אמרו נתפלל סתם, שנאמר אם נתן תתן את העם הזה בידי: **דרך האתרים.** דרך הנגב שהלכו בה המרגלים שנאמר (במדבר יג, כב) ויעלו בנגב. דבר אחר דרך האתרים דרך התיר הגדול הנוסע לפניהם, שנאמר (במדבר י, לג) דרך שלשת ימים לתור להם מנוחה: **וישב ממנו שבי.** אינה אלא שפחה אחת:
@738 **והחרמתי.** אקדיש שללם לגבוה:
@739 **ויחרם אתהם.** בהריגה: **ואת עריהם.** חרמי גבוה:
@740 **דרך ים סוף.** כיון שמת אהרן ובאה עליהם מלחמה זו חזרו לאחוריהם דרך ים סוף, הוא הדרך שחזרו להם כשנגזר עליהם גזרת מרגלים, שנאמר (דברים א, מ) ויסעו המדברה דרך ים סוף. וכאן חזרו לאחוריהם שבע מסעות, שנאמר (שם י, ו) ובני ישראל נסעו מבארות בני יעקן מוסרה שם מת אהרן. וכי במוסרה מת, והלא בהר ההר מת, אלא שם חזרו והתאבלו עליו והספידוהו כאלו הוא בפניהם. וצא ובדוק במסעות ותמצא שבע מסעות מן מוסרה עד הר ההר: **לסבב את ארץ אדום.** שלא נתנם לעבור בארצו: **ותקצר נפש העם בדרך.** בטורח הדרך שהקשה להם. אמרו עכשו היינו קרובים להכנס לארץ ואנו חוזרים לאחורינו כך חזרו אבותינו ונשתהו שלשים ושמונה שנה עד היום, לפיכך קצרה נפשם בענוי הדרך. ובלשון לע''ז אינקרו''ט לו''ר . ולא יתכן לומר ותקצר נפש העם בדרך בהיותו בדרך. ולא פרש בו במה קצרה, שכל מקום שתמצא קצור נפש במקרא מפורש שם במה קצרה, כגון (זכריה יא, ח) ותקצר נפשי בהם, וכגון (שופטים י, טז) ותקצר נפשו בעמל ישראל, וכל דבר הקשה על אדם נופל בו לשון קצור נפש, כאדם שהטורח בא עליו ואין דעתו רחבה לקבל אותו הדבר, ואין לו מקום בתוך לבו לגור שם אותו הצער, ובדבר המטריח נופל לשון גדל, שגדול הוא וכבד על האדם, כגון (זכריה יא, ח) וגם נפשם בחלה בי, גדלה עלי, (איוב י, טז) ויגאה כשחל תצודני, כללו של פרוש כל לשון קצור נפש בדבר, לשון שאין יכול לסבלו הוא, שאין הדעת סובלתו:
@741 **באלהים ובמשה.** השוו עבד לקונו: **למה העליתנו.** שניהם שוים: **ונפשנו קצה.** אף זה לשון קצור נפש ומאוס: **בלחם הקלקל.** לפי שהמן נבלע באיברים קראוהו קלקל. אמרו עתיד המן הזה שיתפח במעינו, כלום יש ילוד אשה שמכניס ואינו מוציא:
@742 **את הנחשים השרפים.** ששורפים את האדם בארס שניהם: **וינשכו את העם.** יבא נחש שלקה על הוצאת דבה ויפרע ממוציאי דבה. יבא נחש שכל המינין נטעמים לו טעם אחד ויפרע מכפויי טובה, שדבר אחד משתנה להם לכמה טעמים:
@743 **ויתפלל משה.** מכאן למי שמבקשים ממנו מחילה שלא יהא אכזרי מלמחול:
@744 **על נס.** על כלונס שקורים פירק''א בלע''ז [מוט] וכן (ישעיה ל, יז) וכנס על הגבעה, (שם מט, כב) ארים נסי, (שם יג, ב) שאו נס, ולפי שהוא גבוה לאות ולראיה קראו נס: **כל הנשוך.** אפלו כלב או חמור נושכו היה נזוק ומתנונה והולך, אלא שנשיכת הנחש ממהרת להמית, לכך נאמר כאן וראה אתו ראיה בעלמא, ובנשיכת הנחש נאמר והביט, והיה אם נשך הנחש את איש והביט וגו' , שלא היה ממהר נשוך הנחש להתרפאות אלא אם כן מביט בו בכונה. ואמרו רבותינו וכי נחש ממית או מחיה, אלא בזמן שהיו ישראל מסתכלין כלפי מעלה ומשעבדין את לבם לאביהם שבשמים היו מתרפאים, ואם לאו היו נמוקים:
@745 **נחש נחשת.** לא נאמר לו לעשותו של נחשת, אלא אמר משה הקדוש ברוך הוא קוראו נחש, ואני אעשנו של נחשת, לשון נופל על לשון:
@747 **בעיי העברים.** לא ידעתי למה נקרא שמם עיים. ועי לשון חרבה הוא דבר הטאוט במטאטא, והעי''ן בו יסוד לבדה והוא מלשון יעים, (ישעיה כח, יז) ויעה ברד: **העברים.** דרך מעבר העוברים שם את הר נבו אל ארץ כנען, שהוא מפסיק בין ארץ מואב לארץ אמורי: **על פני מואב ממזרח השמש.** במזרחה של ארץ מואב:
@749 **מגבל האמרי.** תחום סוף מצר שלהם, וכן (דברים ב, יח) גבול מואב, לשון קצה וסוף: **מעבר ארנון.** הקיפו ארץ מואב כל דרומה ומזרחה עד שבאו מעבר השני לארנון בתוך ארץ האמורי בצפונה של ארץ מואב: **היוצא מגבל האמרי.** רצועה יוצאה מגבול האמורי והיא של אמוריים ונכנסת לגבול מואב עד ארנון, שהוא גבול מואב ושם חנו ישראל, ולא באו לגבול מואב, כי ארנון גבול מואב, והם לא נתנו להם רשות לעבור בארצם. ואף על פי שלא פרשה משה, פרשה יפתח, כמו שאמר יפתח (שופטים יא, יז) וגם אל מלך מואב שלח ולא אבה. ומשה רמזה (דברים ב, כט) כאשר עשו לי בני עשו היושבים בשעיר והמואבים היושבים בער, מה אלו לא נתנום לעבור בתוך ארצם אלא הקיפום סביב, אף מואב כן:
@750 **על כן יאמר.** על חניה זו ונסים שנעשו בה יאמר בספר מלחמות ה', כשמספרים נסים שנעשו לאבותינו יספרו את והב וגו' : **את והב.** כמו את יהב, כמו שיאמר מן יעד ועד, כן יאמר מן יהב והב. והוי''ו יסוד הוא, כלומר את אשר יהב להם הרבה נסים בים סוף: **ואת הנחלים ארנון.** כשם שמספרים בנסי ים סוף, כך יש לספר בנסי נחלי ארנון, שאף כאן נעשו נסים גדולים. ומה הם הנסים:
@751 **ואשד הנחלים.** תרגום של שפך אשד. שפך הנחלים שנשפך שם דם אמוריים שהיו נחבאים שם, לפי שהיו ההרים גבוהים והנחל עמוק וקצר וההרים סמוכים זה לזה, אדם עומד על ההר מזה ומדבר עם חברו בהר מזה, והדרך עובר תוך הנחל. אמרו אמוריים כשיכנסו ישראל לתוך הנחל לעבור, נצא מן המערות בהרים שלמעלה מהם ונהרגם בחצים ואבני בליסטראות. והיו אותן הנקעים בהר של צד מואב ובהר של צד אמוריים היו כנגד אותן נקעים כמין קרנות ושדים בולטין לחוץ, כיון שבאו ישראל לעבור נזדעזע ההר של ארץ ישראל, כשפחה היוצאת להקביל פני גברתה, ונתקרב לצד הר של מואב ונכנסו אותן השדים לתוך אותן נקעים והרגום. וזהו אשר נטה לשבת ער, שההר נטה ממקומו ונתקרב לצד גבול מואב ונדבק בו, וזהו ונשען לגבול מואב:
@752 **ומשם בארה.** משם בא האשד אל הבאר. כיצד, אמר הקדוש ברוך הוא מי מודיע לבני הנסים הללו. המשל אומר נתת פת לתינוק הודיע לאמו. לאחר שעברו חזרו ההרים למקומם והבאר ירדה לתוך הנחל והעלתה משם דם ההרוגים וזרועות ואיברים ומוליכתן סביב המחנה וישראל, ראו ואמרו שירה:
@753 **עלי באר.** מתוך הנחל והעלי מה שאת מעלה. ומנין שהבאר הודיעה להם, שנאמר ומשם בארה. וכי משם היתה, והלא מתחלת ארבעים שנה היתה עמהם, אלא שירדה לפרסם את הנסים, וכן אז ישיר ישראל. השירה הזאת נאמרה בסוף ארבעים, והבאר נתנה להם מתחלת ארבעים, ומה ראה לכתב כאן, אלא הענין הזה נדרש למעלה המנו:
@754 **באר חפרוה.** זאת היא הבאר אשר חפרוה שרים משה ואהרן: **במשענותם.** במטה: **וממדבר.** נתנה להם:
@755 **וממתנה נחליאל.** כתרגומו:
@756 **ומבמות הגיא אשר בשדה מואב.** כי שם מת משה ושם בטלה הבאר. דבר אחר כרוה נדיבי העם כל נשיא ונשיא כשהיו חונים נוטל מקלו ומושך אצל דגלו ומחנהו ומי הבאר נמשכין דרך אותו סימן ובאין לפני חנית כל שבט ושבט: **במחקק.** על פי משה שנקרא מחוקק, שנאמר (דברים לג, כא) כי שם חלקת מחקק ספון. ולמה לא נזכרמשה בשירה זו, לפי שלקה על ידי הבאר. וכיון שלא נזכר שמו של משה לא נזכר שמו של הקדוש ברוך הוא. משל למלך שהיו מזמנין אותו לסעודה, אמר אם אוהבי שם אני שם, ואם לאו איני הולך: **ראש הפסגה.** כתרגומו ריש רמתא: **פסגה.** לשון גובה, וכן (תהלים מח, יד) פסגו ארמנותיה, הגביהו ארמנותיה: **ונשקפה.** אותה הפסגה על פני המקום ששמו ישימון, והוא לשון מדבר שהוא שמם. דבר אחר ונשקפה הבאר על פני הישימון שנגנזה בימה של טבריה והעומד על הישימון מביט ורואה כמין כברה בים והיא הבאר, כך דרש רבי תנחומא:
@757 **וישלח ישראל מלאכים.** ובמקום אחר תולה השליחות במשה, שנאמר (דברים ב, כו) ואשלח מלאכים ממדבר קדמות, וכן (במדבר כ, יד) וישלח משה מלאכים מקדש אל מלך אדום, וביפתח הוא אומר (שופטים יא, יז) וישלח ישראל מלאכים אל מלך אדום וגו' , הכתובים הללו צריכים זה לזה, זה נועל וזה פותח, שמשה הוא ישראל וישראל הם משה, לומר לך שנשיא הדור הוא ככל הדור, כי הנשיא הוא הכל:
@758 **אעברה בארצך.** אף על פי שלא נצטוו לפתח להם בשלום בקשו מהם שלום:
@759 **ולא נתן סיחן** וגו' **.** לפי שכל מלכי כנען היו מעלין לו מס שהיה שומרם שלא יעברו עליהם גיסות, כיון שאמרו לו ישראל אעברה בארצך אמר להם כל עצמי איני יושב כאן אלא לשמרם מפניכם ואתם אומרים כך: **ויצא לקראת ישראל.** אלו היתה חשבון מלאה יתושין, אין כל בריה יכולה לכבשה, ואם היה סיחון בכפר חלש אין כל אדם יכול לכבשו, וכל שכן אלו שהיה בחשבון. אמר הקדוש ברוך הוא מה אני מטריח על בני כל זאת לצור על כל עיר ועיר, נתן בלב כל אנשי המלחמה לצאת מן העירות ונתקבצו כלם למקום אחד, ושם נפלו. ומשם הלכו ישראל אל הערים ואין עומד לנגדם כי אין שם איש, אלא נשים וטף:
@760 **כי עז.** ומהו חזקו, התראתו של הקדוש ברוך הוא, שאמר להם (דברים ב, יט) אל תצרם וגו' :
@761 **בנתיה.** כפרים הסמוכים לה:
@762 **והוא נלחם.** למה הצרך להכתב, לפי שנאמר (דברים ב, ט) אל תצר את מואב, וחשבון משל מואב היתה, כתב לנו שסיחון לקחה מהם ועל ידו טהרה לישראל: **מידו.** מרשותו:
@763 **על כן.** על אותה מלחמה שנלחם סיחון במואב: **יאמרו המשלים.** בלעם, שנאמר בו (במדבר כג, ז) וישא משלו: **המשלים.** בלעם ובעור. והם אמרו: **באו חשבון.** שלא היה סיחון יכול לכבשה והלך ושכר את בלעם לקללו, וזהו שאמר לו בלק (שם כב, ו) כי ידעתי את אשר תברך מברך וגו' : **תבנה ותכונן.** חשבון בשם סיחון להיות עירו:
@764 **כי אש יצאה מחשבון.** משכבשה סיחון: **אכלה ער מואב.** שם אותה המדינה קרוי ער בלשון עברי, ולחית בלשון ארמי: **ער מואב.** ער של מואב:
@765 **אוי לך מואב.** שקללו את מואב שימסרו בידו: **כמוש.** שם אלהי מואב: **נתן.** הנותן את בניו של מואב: **פליטם.** נסים ופליטים מחרב ואת בנותיו בשבית וגו' :
@766 **ונירם.** מלכות שלהם: **אבד חשבון עד דיבן.** מלכות ועול שהיה למואב בחשבון אבד משם, וכן עד דיבן. תרגום שלסר, עד. כלומר סר ניר מדיבון. ניר לשון מלכות ועול וממשלת איש, כמו (מלכים א' יא, לו) למען היות ניר לדוד עבדי: **ונשים.** שי''ן דגושה לשון שממה, כך יאמרו המושלים ונשים אותם: **עד נפח.** השמונום עד נפח:
@768 **וישלח משה לרגל את יעזר.** המרגלים לכדוה. אמרו לא נעשה כראשונים, בטוחים אנו בכח תפלתו של משה להלחם:
@770 **אל תירא אתו.** שהיה משה ירא להלחם, שמא תעמד לו זכותו של אברהם, שנאמר (בראשית יד, יג) ויבא הפליט, הוא עוג, שפלט מן הרפאים שהכו כדרלעומר וחבריו בעשתרות קרנים, שנאמר (דברים ג, יא) כי רק עוג מלך הבשן נשאר מיתר הרפאים:
@771 **ויכו אתו.** משה הרגו, כדאיתא בברכות בהרואה (דף נד, ב) עקר טורא בת תלתא פרסי וכו' :
@773 **וירא בלק בן צפור את כל אשר עשה ישראל לאמרי.** אמר אלו שני מלכים שהיינו בטוחים עליהם לא עמדו בפניהם, אנו על אחת כמה וכמה. לפיכך ויגר מואב:
@774 **ויגר.** לשון מורא, כמו (איוב יט, כט) גורו לכם: **ויקץ מואב.** קצו בחייהם:
@775 **אל זקני מדין.** והלא מעולם היו שונאים זה את זה, שנאמר (בראשית לו, לה) המכה את מדין בשדה מואב, שבאו מדין על מואב למלחמה. אלא מיראתן של ישראל עשו שלום ביניהם. ומה ראה מואב לטול עצה ממדין, כיון שראו את ישראל נוצחים שלא כמנהג העולם, אמרו מנהיגם של אלו במדין נתגדל, נשאל מהם מה מדתו. אמרו לו אין כחו אלא בפיו. אמרו אף אנו נבא עליהם באדם שכחו בפיו: **כלחוך השור.** כל מה שהשור מלחך אין בו ברכה: **בעת ההוא.** לא היה ראוי למלכות. מנסיכי מדין היה, וכיון שמת סיחון מנוהו עליהם לצורך שעה:
@776 **פתורה.** כשלחני הזה שהכל מריצין לו מעות, כך כל המלכים מריצין לו אגרותיהם. ולפי פשוטו של מקרא כך שם המקום: **ארץ בני עמו.** של בלק. משם היה, וזה היה מתנבא ואומר לו עתיד אתה למלוך. ואם תאמר מפני מה השרה הקדוש ברוך הוא שכינתו על גוי רשע, כדי שלא יהא פתחון פה לאמות לומר אלו היו לנו נביאים חזרנו למוטב, העמיד להם נביאים והם פרצו גדר העולם, שבתחלה היו גדורים בעריות וזה נתן להם עצה להפקיר עצמן לזנות: **לקרא לו.** הקריאה שלו היתה ולהנאתו, שהיה פוסק לו ממון הרבה: **עם יצא ממצרים.** ואם תאמר מה מזיקך: **הנה כסה את עין הארץ.** סיחון ועוג שהיו שומרים אותנו עמדו עליהם והרגום: **והוא ישב ממלי.** חסר כתיב, קרובים הם להכריתני, כמו (תהלים קיח, י) כי אמילם:
@777 **נכה בו.** אני ועמי נכה לו בהם. דבר אחר לשון משנה היא (ב''מ קה ב) מנכה לו מן הדמים, לחסר מהם מעט: **כי ידעתי** וגו' **.** על ידי מלחמת סיחון שעזרתו להכות את מואב:
@778 **וקסמים בידם.** כל מיני קסמים, שלא יאמר אין כלי תשמישי עמי. דבר אחר קסם זה נטלו בידם זקני מדין, אמרו אם יבא עמנו בפעם הזאת יש בו ממש, ואם ידחנו אין בו תועלת, לפיכך כשאמר להם לינו פה הלילה, אמרו אין בו תקוה, הניחוהו והלכו להם, שנאמר וישבו שרי מואב עם בלעם, אבל זקני מדין הלכו להם:
@779 **לינו פה הלילה.** אין רוח הקדש שורה עליו אלא בלילה, וכן לכל נביאי אמות העולם, וכן לבן בחלום הלילה, שנאמר (בראשית לא, כד) ויבא אלהים אל לבן הארמי בחלם הלילה. כאדם ההולך אצל פלגשו בהחבא: **כאשר ידבר ה' אלי.** אם ימליכני ללכת עם בני אדם כמותכם אלך עמכם, שמא אין כבודו לתתי להלך אלא עם שרים גדולים מכם: **וישבו.** לשון עכבה:
@780 **מי האנשים האלה עמך.** להטעותו בא. אמר פעמים שאין הכל גלוי לפניו, אין דעתו שוה עליו, אף אני אראה עת שאוכל לקלל ולא יבין:
@781 **בלק בן צפור** וגו' **.** אף על פי שאיני חשוב בעיניך, חשוב אני בעיני המלכים:
@782 **קבה לי.** זו קשה מארה לי, שהוא נוקב ומפרש: **וגרשתיו.** מן העולם. ובלק לא אמר אלא ואגרשנו מן הארץ, איני מבקש אלא להסיעם מעלי, ובלעם היה שונאם יותר מבלק:
@783 **לא תלך עמהם.** אמר לו אם כן אקללם במקומי. אמר לו לא תאר את העם. אמר לו אם כן אברכם. אמר לו אינם צריכין לברכתך, כי ברוך הוא. משל אומרים לצרעה לא מדבשיך ולא מעקציך:
@784 **להלך עמכם.** אלא עם שרים גדולים מכם. למדנו שרוחו גבוהה ולא רצה לגלות שהוא ברשותו של מקום אלא בלשון גסות, לפיכך ויוסף עוד בלק:
@788 **כי כבד אכבדך מאד.** יותר ממה שהיית נוטל לשעבר אני נותן לך:
@789 **מלא ביתו כסף וזהב.** למדנו שנפשו רחבה ומחמד ממון אחרים. אמר, ראוי לו לתן לי כל כסף וזהב שלו, שהרי צריך לשכור חילות רבות, ספק נוצח ספק אינו נוצח, ואני ודאי נוצח: **לא אוכל לעבר.** על כרחו גלה שהוא ברשות אחרים, ונתנבא כאן שאינו יכול לבטל הברכות שנתברכו האבות מפי השכינה:
@790 **גם אתם.** פיו הכשילו, גם אתם סופכם לילך בפחי נפש כראשונים: **מה יסף.** לא ישנה דבריו מברכה לקללה הלואי שלא יוסיף לברך, כאן נתנבא שעתיד להוסיף להם ברכות על ידו:
@791 **אם לקרא לך.** אם הקריאה שלך וסבור אתה לטול עליה שכר, קום לך אתם: **ואך.** על כרחך את הדבר אשר אדבר אליך אתו תעשה, ואף על פי כן וילך בלעם, אמר שמא אפתנו ויתרצה:
@792 **ויחבש את אתנו.** מכאן שהשנאה מקלקלת את השורה, שחבש הוא בעצמו. אמר הקדוש ברוך הוא רשע כבר קדמך אברהם אביהם, שנאמר (בראשית כב, ג) וישכם אברהם בבקר ויחבש את חמורו: **עם שרי מואב.** לבו כלבם שוה:
@793 **כי הולך הוא.** ראה שהדבר רע בעיני המקום ונתאוה לילך: **לשטן לו.** מלאך של רחמים היה והיה רוצה למנעו מלחטוא, שלא יחטא ויאבד: **ושני נעריו עמו.** מכאן לאדם חשוב היוצא לדרך יוליך עמו שני אנשים לשמשו וחוזרים ומשמשים זה את זה:
@794 **ותרא האתון.** והוא לא ראה, שנתן הקדוש ברוך הוא רשות לבהמה לראות יותר מן האדם, שמתוך שיש בו דעת תטרף דעתו כשיראה מזיקין: **וחרבו שלופה בידו.** אמר רשע זה הניח כלי אמנותו, שכלי זינן של אמות העולם בחרב, והוא בא עליהם בפיו, שהוא אמנות שלהם, אף אני אתפוש את שלו ואבוא עליו באמנותו. וכן היה סופו (במדבר לא, ח) ואת בלעם בן בעור הרגו בחרב:
@795 **במשעול.** כתרגומו בשביל. וכן (מ''א כ, י) אם ישפק עפר שומרון לשעלים. עפר הנדבק בכפות הרגלים בהלוכן, וכן (ישעיה מ, יב) מי מדד בשעלו מים, ברגליו ובהלוכו: **גדר מזה וגדר מזה.** סתם גדר של אבנים הוא:
@796 **ותלחץ.** היא עצמה: **ותלחץ.** את אחרים, את רגל בלעם:
@797 **ויוסף מלאך ה' עבור.** לעבור עוד לפניו להלוך להיות לפניו במקום אחר, כמו (בראשית לג, ג) והוא עבר לפניהם. ומדרש אגדה יש בתנחומא מה ראה לעמוד בשלשה מקומות, סימני אבות הראהו:
@799 **זה שלש רגלים.** רמז לו אתה מבקש לעקור אמה החוגגת שלש רגלים בשנה:
@800 **התעללת.** כתרגומו לשון גנאי ובזיון: **לו יש חרב בידי.** גנות גדולה היה לו דבר זה בעיני השרים, זה הולך להרוג אמה שלמה בפיו, ולאתון זו צריך לכלי זין:
@801 **ההסכן הסכנתי.** כתרגומו, וכן (איוב כב, ב) הלאל יסכן גבר. ורבותינו דרשו מקרא זה בגמרא אמרו ליה, מאי טעמא לא רכבת אסוסיא. אמר להון ברטיבא שדאי ליה וכו' , כדאיתא במסכת עבודה זרה (ד, ב) :
@803 **כי ירט הדרך לנגדי.** רבותינו חכמי המשנה דרשוהו (שבת קה, א) נוטריקון יראה ראתה, נטתה, בשביל שהדרך לנגדי, כלומר לקנאתי ולהקניטני. ולפי משמעו כי חרד הדרך לנגדי לשון רטט, כי ראיתי בעל הדרך שחרד ומהר הדרך שהוא לכעסי ולהמרותי [ולהמראתי] . ומקרא קצר הוא, כמו (ש''ב יג, לט) ותכל דוד. לישנא אחרינא ירט לשון רצון, וכן (איוב טז) ועל ידי רשעים ירטני, מפייס ומנחם אותי על ידי רשעים, שאינן אלא מקניטים:
@804 **אולי נטתה.** כמו לולא, פעמים שאולי משמש בלשון לולא: **גם אתכה הרגתי.** הרי זה מקרא מסורס, והוא כמו גם הרגתי אותך, כלומר לא העכבה בלבד קראתך על ידי, כי גם ההריגה: **ואותה החייתי.** ועתה מפני שדברה והוכיחתך ולא יכלת לעמוד בתוכחתה, כמו שכתוב (פסוק ל) ויאמר לא. על כן הרגתיה, שלא יאמרו זו היא שסלקה את בלעם בתוכחתה ולא יכול להשיב, שחס המקום על כבוד הבריות, וכן (ויקרא כ, טו. טז) ואת הבהמה תהרגו, וכן (שם) והרגת את האשה ואת הבהמה:
@805 **כי לא ידעתי.** גם זה גנותו, ועל כרחו הודה, שהוא היה משתבח שיודע דעת עליון, ופיו העיד לא ידעתי: **אם רע בעיניך אשובה לי.** להתריס נגד המקום היא תשובה זו. אמר לו הוא בעצמו צוני ללכת, ואתה מלאך מבטל את דבריו, למוד הוא בכך, שאמר דבר ומלאך מחזירו, אמר לאברהם (בראשית כב, ב) קח נא את בנך וגו' , ועל ידי מלאך בטל את דברו, אף אני אם רע בעיניך צריך אני לשוב:
@806 **לך עם האנשים.** בדרך שאדם רוצה לילך בה, מוליכין אותו. **לך עם האנשים.** כי חלקך עמהם וסופך להאבד מן העולם: **ואפס.** על כרחך את הדבר אשר אדבר וגו' : **עם שרי בלק.** שמח לקללם כמותם:
@807 **וישמע בלק.** שלח שלוחים לבשרו: **אל עיר מואב.** אל מטרופולין שלו, עיר החשובה שלו, לומר ראה מה אלו מבקשים לעקור:
@808 **האמנם לא אוכל כבדך.** נתנבא שסופו לצאת מעמו בקלון:
@810 **קרית חצות.** עיר מלאה שוקים אנשים ונשים וטף בחוצותיה, לומר ראה ורחם שלא יעקרו אלו:
@811 **בקר וצאן.** דבר מועט, בקר אחד וצאן אחד בלבד:
@812 **במות בעל.** כתרגומו לרמת דחלתיה, שם עבודה זרה:
@815 **אולי יקרה ה' לקראתי.** אינו רגיל לדבר עמי ביום: **וילך שפי.** כתרגומו יחידי, לשון שופי ושקט, שאין עמו אלא שתיקה:
@816 **ויקר.** לשון עראי, לשון גנאי, לשון טמאת קרי, כלומר בקושי ובבזיון, ולא היה נגלה עליו ביום אלא בשביל להראות חבתן של ישראל: **את שבעת המזבחת.** שבעה מזבחות ערכתי אין כתיב כאן, אלא את שבעת המזבחות, אמר לפניו אבותיהם של אלו בנו לפניך שבעה מזבחות, ואני ערכתי כנגד כלן. אברהם בנה ארבעה (בראשית יב, ז) ויבן שם מזבח לה' הנראה אליו, (שם יב, ח) ויעתק משם ההרה וגו' , (שם יג, יח) ויאהל אברם וגו' ואחד בהר המוריה. ויצחק בנה אחד (שם כו, כה) ויבן שם מזבח וגו' . ויעקב בנה שתים, אחד בשכם ואחד בבית אל: **ואעל פר ואיל במזבח.** ואברהם לא העלה אלא איל אחד:
@819 **ארה לי יעקב ולכה זעמה ישראל.** בשני שמותיהם אמר לו לקללם, שמא אחד מהם אינו מבהק:
@820 **מה אקב לא קבה אל.** כשהיו ראוים להתקלל לא נתקללו, כשהזכיר אביהם את עונם, כי באפם הרגו איש. לא קלל אלא אפם, שנאמר (בראשית מט) ארור אפם. כשנכנס אביהם במרמה אצל אביו היה ראוי להתקלל, מה נאמר שם (שם כז, לג) גם ברוך יהיה. במברכים נאמר (דברים כז, יב) אלה יעמדו לברך את העם. במקללים לא נאמר ואלה יעמדו לקלל את העם, אלא על הקללה, לא רצה להזכיר עליהם שם קללה: **לא זעם ה'.** אני אין כחי אלא שאני יודע לכון השעה שהקדוש ברוך הוא כועס בה, והוא לא כעס כל הימים הללו שבאתי אליך, וזהו שנאמר (מיכה ו, ה) עמי זכר נא מה יעץ וגו' ומה ענה אתו בלעם וגו' למען דעת צדקות ה':
@821 **כי מראש צרים אראנו.** אני מסתכל בראשיתם ובתחלת שרשיהם, ואני רואה אותם מיסדים וחזקים כצורים וגבעות הללו על ידי אבות ואמהות: **הן עם לבדד ישכן.** הוא אשר זכו לו אבותיו לשכון בדד, כתרגומו: **ובגוים לא יתחשב.** כתרגומו, לא יהיו נעשין כלה עם שאר האמות, שנאמר (ירמיה ל, יא) כי אעשה כלה בכל הגוים וגו' אינן נמנין עם השאר. דבר אחר כשהן שמחין אין אמה שמחה עמהם, שנאמר (דברים לב, יב) ה' בדד ינחנו. וכשהאמות בטובה, הם אוכלין עם כל אחד ואחד ואין עולה להם מן החשבון, וזהו, ובגוים לא יתחשב:
@822 **מי מנה עפר יעקב** וגו' **.** כתרגומו, דעדקיא דבית יעקב וכו' מארבע משריתא, מארבע דגלים. דבר אחר עפר יעקב אין חשבון במצות שהם מקימין בעפר (דברים כב, י) לא תחרוש בשור ובחמור, (ויקרא יט, יט) לא תזרע כלאים, אפר פרה, ועפר סוטה וכיוצא בהם: **ומספר את רבע ישראל.** רביעותיהן, זרע היוצא מן התשמיש שלהם: **תמת נפשי מות ישרים.** שבהם:
@825 **וקבנו לי.** לשון צווי, קללהו לי:
@826 **שדה צופים.** מקום גבוה היה ששם הצופה עומד לשמור אם יבא חיל על העיר: **ראש הפסגה.** בלעם לא היה קוסם כבלק, ראה בלק שעתידה פרצה להפרץ בישראל משם ששם מת משה. כסבור ששם תחול עליהם הקללה, וזו היא הפרצה שאני רואה:
@827 **אקרה כה.** מאת הקדוש ברוך הוא: **אקרה.** לשון אתפעל:
@828 **וישם דבר בפיו.** ומה היא השימה הזאת, ומה חסר המקרא באמרו שוב אל בלק וכה תדבר, אלא כשהיה שומע שאינו נרשה לקלל, אמר מה אני חוזר אצל בלק לצערו. ונתן לו הקדוש ברוך הוא רסן וחכה בפיו כאדם הפוקס בהמה בחכה להוליכה אל אשר ירצה. אמר לו על כרחך תשוב אל בלק:
@829 **ושרי מואב אתו.** ולמעלה הוא אומר וכל שרי מואב, כיון שראו שאין בו תקוה הלכו להם מקצתם, ולא נשארו אלא מקצתם: **מה דבר ה'.** לשון צחוק הוא זה, כלומר אינך ברשותך:
@830 **קום בלק.** כיון שראהו מצחק בו, נתכון לצערו עמוד על רגליך, אינך רשאי לישב ואני שלוח אליך בשליחותו של מקום: **בנו צפר.** לשון מקרא הוא זה, כמו (תהלים קד, כ) חיתו יער, (בראשית א, כד) וחיתו ארץ, (תהלים קיד, ח) למעינו מים:
@831 **לא איש אל** וגו' **.** כבר נשבע להם להביאם ולהורישם ארץ שבעה אמות, ואתה סבור להמיתם במדבר: **ההוא אמר** וגו' **.** בלשון תמה, ותרגומו תיבין ומתמלכין, חוזרים ונמלכין לחזור בהם:
@832 **הנה ברך לקחתי.** אתה שואלני מה דבר ה', קבלתי ממנו לברך אותם: **וברך ולא אשיבנה.** הוא ברך אותם ואני לא אשיב את ברכתו: **וברך.** כמו וברך וכן הוא גזרת רי''ש, כמו (תהלים עד, יח) אויב חרף, כמו חרף, וכן (שם י, ג) ובוצע ברך, המהלל ומברך את הגוזל ואומר, אל תירא כי לא תענש, שלום יהיה לך, מרגיז הוא להקדוש ברוך הוא. ואין לומר ברך שם דבר, שאם כן היה נקוד בפתח קטן וטעמו למעלה, אבל לפי שהוא לשון פעל הוא נקוד קמץ, וטעמו למטה:
@833 **לא הביט און ביעקב** וגו' **.** כתרגומו. דבר אחר אחרי פשוטו הוא נדרש מדרש נאה. **לא הביט.** הקדוש ברוך הוא און שביעקב, כשהן עוברין על דבריו אינו מדקדק אחריהם להתבונן באוניות [באון] שלהם ובעמלן שהן עוברין על דתו: **עמל.** לשון עברה, כמו והרה עמל (תהלים ז, טו) , כי אתה עמל וכעס תביט (שם י, יד) לפי שהעברה היא עמל לפני המקום: **ה' אלהיו עמו.** אפלו מכעיסין וממרים לפניו אינו זז מתוכן: **ותרועת מלך בו.** לשון חבה ורעות כמו רעה דוד (שמואל ב' טו, לז) אוהב דוד, ויתנה למרעהו (שופטים טו, ו) וכן תרגם אנקלוס ושכינת מלכהון ביניהון:
@834 **אל מוציאם ממצרים.** אתה אמרת הנה עם יצא ממצרים, לא יצא מעצמו אלא האלהים הוציאם: **כתועפות ראם לו.** כתוקף רום וגובה שלו, וכן וכסף תועפות (איוב כב כה) , לשון מעוז המה, ואומר אני שהוא לשון ועוף יעופף (בראשית א כ) , המעופף ברום וגובה ותקף רב הוא זה ותועפות ראם עפיפת גובה. דבר אחר, **תועפות ראם.** תקף ראמים, ואמרו רבותינו אלו השדים:
@835 **כי לא נחש ביעקב.** כי ראוים הם לברכה שאין בהם מנחשים וקוסמים: **כעת יאמר ליעקב** וגו' **.** עוד עתיד להיות עת כעת הזאת אשר תגלה חבתן לעין כל שהן יושבין לפניו ולומדים תורה מפיו ומחצתן לפנים ממלאכי השרת, והם ישאלו להם מה פעל אל, וזהו שנאמר והיו עיניך רואות את מוריך (ישעיה ל, כ) . דבר אחר יאמר ליעקב אינו לשון עתיד, אלא לשון הוה, אינן צריכין למנחש וקוסם כי בכל עת שצריך להאמר ליעקב ולישראל מה פעל הקדוש ברוך הוא ומה גזרותיו במרום, אינן מנחשים וקוסמים אלא נאמר להם על פי נביאיהם מה היא גזרת המקום, או אורים ותמים מגידים להם, ואונקלוס לא תרגם כן:
@836 **הן עם כלביא יקום** וגו' **.** כשהן עומדים משנתם שחרית, הן מתגברין כלביא וכארי לחטוף את המצות, ללבוש טלית לקרא את שמע ולהניח תפלין: **לא ישכב.** בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו. כיצד, קורא את שמע על מטתו ומפקיד רוחו ביד המקום, בא מחנה וגיס להזיקם, הקדוש ברוך הוא שומרם ונלחם מלחמותם ומפילם חללים. דבר אחר הן עם כלביא יקום וגו' . כתרגומו: **ודם חללים ישתה.** נתנבא שאין משה מת עד שיפיל מלכי מדין חללים ויהרג הוא עמהם, שנאמר (יהושע יג, כב) ואת בלעם בן בעור הקוסם הרגו בני ישראל בחרב אל חלליהם:
@837 **גם קב לא תקבנו.** גם ראשון מוסיף על גם השני, וגם השני על גם ראשון, וכן גם לי גם לך לא יהיה (מלכים א' ג, כו) , וכן גם בחור גם בתולה (דברים לב, כה) :
@839 **וקבותו לי.** אין זה לשון צווי, כמו וקבנו, אלא לשון עתיד, אולי יישר בעיניו ותקבנו לי משם, מלדי''רש מי''י בלע''ז [תקלל אותו] :
@840 **ראש הפעור.** קוסם היה בלק וראה שהן עתידין ללקות על ידי פעור ולא היה יודע במה, אמר שמא הקללה תחול עליהם משם, וכן כל החוזים בכוכבים רואים ואינם יודעים מה רואים:
@843 **וירא בלעם כי טוב** וגו' **.** אמר איני צריך לבדוק בהקדוש ברוך הוא כי לא יחפוץ לקללם: **ולא הלך כפעם בפעם.** כאשר עשה שתי פעמים: **לקראת נחשים.** לנחש אולי יקרה ה' לקראתו כרצונו, אמר רוצה ואינו רוצה לקללם, אזכיר עונותיהם, והקללה על הזכרת העברה תחול: **וישת אל המדבר פניו.** כתרגומו:
@844 **וישא בלעם את עיניו.** בקש להכניס בהם עין רעה, והרי יש לך שלש מדותיו עין רעה ורוח גבוהה ונפש רחבה האמורים למעלה: **שוכן לשבטיו.** ראה כל שבט ושבט שוכן לעצמו ואינן מעורבין, ראה שאין פתחיהם מכונין זה כנגד זה, שלא יציץ לתוך אהל חברו: **ותהי עליו רוח אלהים.** עלה בלבו שלא יקללם:
@845 **בנו בער.** כמו למעינו מים (תהלים קיד, ח) . ומדרש אגדה שניהם היו גדולים מאבותיהם, בלק בנו צפור, אביו בנו הוא במלכות, ובלעם גדול מאביו בנביאות, מנה בן פרס היה: **שתם העין.** עינו נקורה ומוצאת לחוץ וחור שלה נראה פתוח, ולשון משנה הוא כדי שישתום ויסתום ויגוב (ע''ז סט.) ורבותינו אמרו לפי שאמר ומספר את רבע ישראל, שהקדוש ברוך הוא יושב ומונה רביעיותיהן של ישראל מתי תבא טפה שנלד הצדיק ממנה, אמר בלבו מי שהוא קדוש ומשרתיו קדושים יסתכל בדברים הללו, ועל דבר זה נסמת עינו של בלעם. ויש מפרשים שתום העין פתוח העין, כמו שתרגם אנקלוס, ועל שאמר שתום העין, ולא אמר שתום העינים, למדנו שסומא באחת מעיניו היה:
@846 **נפל וגלוי עינים.** פשוטו כתרגומו, שאין נראה עליו אלא בלילה כשהוא שוכב. ומדרשו כשהיה נגלה עליו לא היה בו כח לעמוד על רגליו ונופל על פניו, לפי שהיה ערל ומאוס להיות נגלה עליו בקומה זקופה לפניו:
@847 **מה טבו אהליך.** על שראה פתחיהם שאינן מכונין זה מול זה: **משכנתיך.** חניותיך, כתרגומו. דבר אחר מה טבו אהליך. מה טבו אהל שילה ובית עולמים בישובן שמקריבין בהן קרבנות לכפר עליהם: **משכנתיך.** אף כשהן חרבין, לפי שהן משכון עליכם, וחרבנן כפרה על הנפשות, שנאמר כלה ה' את חמתו (איכה ד) , ובמה כלה, ויצת אש בציון:
@848 **כנחלים נטיו.** שנארכו ונמשכו לנטות למרחוק, אמרו רבותינו מברכותיו של אותו רשע אנו למדים מה היה בלבו לקללם כשאמר (פסוק א) וישת אל המדבר פניו, וכשהפך המקום את פיו ברכם מעין אותן קללות שבקש לומר כו', כדאיתא בחלק (סנהדרין קה, א) : **כאהלים.** כתרגומו, לשון מור ואהלות (תהלים מה, ט) : **נטע ה'.** בגן עדן. לשון אחר כאהלים נטע ה', כשמים המתוחין כאהל: **נטע ה'.** לשון נטיעה מצינו באהלים, שנאמר ויטע אהלי אפדנו (דניאל יא, מה) :
@849 **מדליו.** מבארותיו. ופירושו כתרגומו: **וזרעו במים רבים.** לשון הצלחה הוא זה, כזרע הזרוע על פני המים: **וירם מאגג מלכו.** מלך ראשון שלהם יכבוש את אגג מלך עמלק: **ותנשא מלכותו.** של יעקב יותר ויותר, שיבא אחריו דוד ושלמה:
@850 **אל מוציאו ממצרים.** מי גורם להם הגדלה הזאת, אל המוציאם ממצרים, בתוקף ורום שלו יאכל את הגוים שהם צריו: **ועצמותיהם.** של צרים: **יגרם.** מנחם פתר בו לשון שבירה, וכן (צפניה ג, ג) לא גרמו לבקר, וכן (יחזקאל כג, לד) את חרשיה תגרמי, ואני אומר לשון עצם הוא שמגרר הבשר בשניו מסביב והמוח שבפנים, ומעמיד העצם על ערמימותה: **וחציו ימחץ.** אנקלוס תרגם חציו של צרים, חלוקה שלהם כמו (בראשית מט, כג) בעלי חצים, מרי פלוגתא, וכן ימחץ, לשון (שופטים ה, כו) ומחצה וחלפה רקתו, שיחצו את ארצם. ויש לפתור לשון חצים ממש, חציו של הקדוש ברוך הוא ימחץ בדמם של צרים, יטבול ויצטבע בדמם, כמו (תהלים סח, כד) למען תמחץ רגלך בדם. ואינו זז מלשון מכה, כמו מחצתי, שהצבוע בדם נראה כאלו מחוץ ונגוע:
@851 **כרע שכב כארי.** כתרגומו, יתישבו בארצם בכח וגבורה:
@852 **ויספק.** הכה זו על זו:
@855 **לעבר את פי ה'.** כאן לא נאמר אלהי, כמו שנאמר בראשונה, לפי שידע שנבאש בהקדוש ברוך הוא ונטרד:
@856 **הולך לעמי.** מעתה הריני כשאר עמי, שנסתלק הקדוש ברוך הוא מעליו: **לכה איעצך.** מה לך לעשות. ומה היא העצה, אלהיהם של אלו שונא זמה הוא כו' , כדאיתא בחלק (סנהדרין קו.) תדע שבלעם השיא עצה זו להכשילם בזמה, שהרי נאמר הן הנה היו לבני ישראל בדבר בלעם (לקמן לא, טז) : **אשר יעשה העם הזה לעמך.** מקרא קצר הוא זה, איעצך להכשילם, ואומר לך מה שהן עתידין להרע למואב באחרית הימים:
@858 **וידע דעת עליון.** לכון השעה שכועס בה:
@859 **אראנו.** רואה אני שבחו של יעקב וגדלתן, אך לא עתה היא, אלא לאחר זמן: **דרך כוכב.** כתרגומו, לשון דרך קשתו (איכה ב, ד) , שהכוכב עובר כחץ, ובלע''ז דישטנ''ט [מזנק] כלומר יקום מזל: **וקם שבט.** מלך רודה ומושל: **ומחץ פאתי מואב.** זה דוד, שנאמר בו השכב אותם ארצה וימדד שני חבלים להמית וגו' (שמואל ב' ח, ב) : **וקרקר.** לשון קורה כמו אני קרתי (מלכים ב' יט, כד) מקבת בור נקרתם (ישעיה נא, א) יקרוה עורבי נחל (משלי ל, יז) פורי''יר בלע''ז [לנקב] : **כל בני שת.** כל האמות, שכלם יצאו מן שת בנו של אדם הראשון:
@860 **והיה ירשה שעיר איביו.** ישראל:
@861 **וירד מיעקב.** ועוד יהיה מושל אחר מיעקב: **והאביד שריד מעיר.** מעיר החשובה של אדום והיא רומי, ועל מלך המשיח אומר כן, שנאמר בו וירד מים עד ים (תה' עב) ולא יהיה שריד לבית עשו (עוב' א) :
@862 **וירא את עמלק.** נסתכל בפרענותו של עמלק: **ראשית גוים עמלק.** הוא קדם את כלם להלחם בישראל, וכך תרגם אנקלוס ואחריתו לאבד בידם, שנאמר תמחה את זכר עמלק (דברים כה, יט) :
@863 **וירא את הקיני.** לפי שהיה קיני תקוע אצל עמלק, כענין שנאמר ויאמר שאול אל הקיני וגו' (שמואל א' טו, ו) הזכירו אחר עמלק, נסתכל בגדלתן של בני יתרו שנאמר בהם תרעתים שמעתים שוכתים (דברי הימים א' ב, נה) : **איתן מושבך.** תמה אני מהיכן זכית לכך הלא אתה עמי היית בעצת הבה נתחכמה לו (שמות א, י) , ועתה נתישבת באיתן ומעוז של ישראל:
@864 **כי אם יהיה לבער קין** וגו' **.** אשרך שנתקעת לתוקף זה שאינך נטרד עוד מן העולם, כי אף אם אתה עתיד לגלות עם עשרת השבטים ותהיה לבער ממקום שנתישבת שם, מה בכך: **עד מה אשור תשבך.** עד היכן הוא מגלה אותך, שמא ללחלח וחבור, אין זה טרוד מן העולם, אלא טלטול ממקום למקום ותשוב עם שאר הגליות:
@865 **וישא משלו** וגו' **.** כיון שהזכיר את שבית אשור אמר, **אוי מי יחיה משמו אל.** מי יכול להחיות את עצמו משמו את אלה שלא ישים עליו הגוזר את אלה, שיעמוד סנחריב ויבלבל את כל האמות, ועוד יבואו:
@866 **וצים מיד כתים.** ויעברו כתיים שהן רומיים בבירניות גדולות על אשור: **וענו עבר.** וענו אותם שבעבר הנהר: **וגם הוא עדי אבד.** וכן פרש דניאל עד די קטילת חיותא והובד גשמה (דניאל ז, יא) : **וצים.** ספינות גדולות, כדכתיב וצי אדיר (ישעיה לג, כא) תרגומו ובורני רבתא:
@868 **בשטים.** כך שמה: **לזנות אל בנות מואב.** על ידי עצת בלעם כדאיתא בחלק:
@869 **וישתחוו לאלהיהן.** כשתקף יצרו עליו ואמר לה השמעי לי, והיא מוציאה לו דמות פעור מחיקה ואומרת לו השתחוה לזה:
@870 **פעור.** על שם שפוערין לפניו פי הטבעת ומוציאין רעי, וזו היא עבודתו: **ויחר אף ה' בישראל.** שלח בהם מגפה:
@871 **קח את כל ראשי העם.** לשפוט את העובדים לפעור: **והוקע אותם.** את העובדים: **והוקע.** היא תליה, כמו שמצינו בבני שאול והוקענום לה' (שמואל ב' כא, ו) ושם תליה מפורשת בעבודה זרה בסקילה, וכל הנסקלין נתלין: **נגד השמש.** לעין כל. ומדרש אגדה השמש מודיע את החוטאים, הענן נקפל מכנגדו והחמה זורחת עליו:
@872 **הרגו איש אנשיו.** כל אחד ואחד מדיני ישראל היה הורג שנים, ודיני ישראל שמונת רבוא ושמונת אלפים, כדאיתא בסנהדרין (יח.) :
@873 **והנה איש מבני ישראל בא.** נתקבצו שבטו של שמעון אצל זמרי שהיה נשיא שלהם, אמרו לו אנו נדונין במיתה ואתה יושב וכו' , כדאיתא באלו הן הנשרפין (סנהדרין דף פב, א) : **את המדינית.** כזבי בת צור: **לעיני משה.** אמרו לו משה, זו אסורה או מתרת, אם תאמר אסורה, בת יתרו מי התירה לך וכו' , כדאיתא התם: **והמה בוכים.** נתעלמה ממנו הלכה כל הבועל ארמית קנאים פוגעים בו געו כלם בבכיה. בעגל עמד משה כנגד ששים רבוא, שנאמר (שמות לב, כ) ויטחן עד אשר דק וגו' וכאן רפו ידיו, אלא כדי שיבא פנחס ויטול את הראוי לו:
@874 **וירא פנחס.** ראה מעשה ונזכר הלכה, אמר לו למשה מקבלני ממך הבועל ארמית קנאין פוגעין בו, אמר לו קריינא דאגרתא איהו ליהוי פרוונקא, מיד ויקח רמח בידו וגו' :
@875 **אל הקבה.** אל האהל: **אל קבתה.** [אל הקבה] כמו הלחיים והקיבה כון בתוך זכרות של זמרי ונקבות שלה, וראו כלם שלא לחנם הרגם, והרבה נסים נעשו לו כו', כדאיתא התם (סנהד' פב:) :
@878 **פנחס בן אלעזר בן אהרן הכהן.** לפי שהיו השבטים מבזים אותו, הראיתם בן פוטי זה שפטם אבי אמו עגלים לעבודה זרה והרג נשיא שבט מישראל, לפיכך בא הכתוב ויחסו אחר אהרן: **בקנאו את קנאתי.** בנקמו את נקמתי, בקצפו את הקצף שהיה לי לקצוף. כל לשון קנאה הוא המתחרה לנקום נקמת דבר, אנפרימנ''ט בלע''ז :
@879 **את בריתי שלום.** שתהא לו לברית שלום, כאדם המחזיק טובה וחנות למי שעשה עמו טובה, אף כאן פרש לו הקדוש ברוך הוא שלומותיו:
@880 **והיתה לו.** בריתי זאת: **ברית כהנת עולם.** שאף על פי שכבר נתנה כהנה לזרעו של אהרן, לא נתנה אלא לאהרן ולבניו, שנמשחו עמו ולתולדותיהם שיולידו אחר המשחתן, אבל פנחס שנלד קודם לכן ולא נמשח, לא בא לכלל כהנה עד כאן. וכן שנינו בזבחים (קא, ב) לא נתכהן פנחס עד שהרגו לזמרי: **לאלהיו.** בשביל אלהיו, כמו (במד' יא) המקנא אתה לי, (זכר' ח) קנאתי לציון, בשביל ציון:
@881 **ושם איש ישראל** וגו' **.** במקום שייחס את הצדיק לשבח יחס את הרשע לגנאי: **נשיא בית אב לשמעני.** לאחד מחמשת בתי אבות שהיו לשבט שמעון. דבר אחר להודיע שבחו של פנחס, שאף על פי שזה היה נשיא, לא מנע את עצמו מלקנא לחלול השם, לכך הודיעך הכתוב מי הואהמכה:
@882 **ושם האשה המכה** וגו' **.** להודיעך שנאתם של מדינים שהפקירו בת מלך לזנות, כדי להחטיא את ישראל: **ראש אמות.** אחד מחמשת (במד' לא) מלכי מדין את אוי ואת רקם ואת צור וגו' , והוא היה חשוב מכלם, שנאמר ראש אמות, ולפי שנהג בזיון בעצמו להפקיר בתו מנאו שלישי: **בית אב.** חמשה בתי אבות היו למדין עיפה ועפר וחנוך ואבידע ואלדעה, וזה היה מלך לאחד מהם:
@884 **צרור.** כמו זכור, שמור, לשון הוה. עליכם לאייב אותם:
@885 **כי צוררים הם לכם** וגו' **על דבר פעור.** שהפקירו בנותיהם לזנות, כדי להטעותכם אחר פעור. ואת מואב לא צוה להשמיד, מפני רות שהיתה עתידה לצאת מהם, כדאמרינן בבבא קמא (לח, ב) :
@887 **ויהי אחרי המגפה** וגו' **.** משל לרועה שנכנסו זאבים לתוך עדרו והרגו בהן והוא מונה אותן לידע מנין הנותרות. דבר אחר כשיצאו ממצרים ונמסרו למשה, נמסר לו במנין, עכשו שקרב למות ולהחזיר צאנו, מחזירם במנין:
@888 **לבית אבתם.** על שבט האב יתיחסו, ולא אחר האם:
@889 **וידבר משה ואלעזר הכהן אתם.** דברו עמם על זאת שצוה המקום למנותם: **לאמר.** אמרו להם צריכים אתם להמנות:
@890 **מבן עשרים שנה ומעלה כאשר צוה** וגו' **.** שיהא מנינם מבן עשרים שנה ומעלה, שנאמר (שמות ל, יג) כל העבר על הפקדים וגו' :
@891 **משפחת החנכי.** לפי שהיו האמות מבזין אותם ואומרים מה אלו מתיחסין על שבטיהם, סבורין הם שלא שלטו המצריים באמותיהם, אם בגופם היו מושלים קל וחומר בנשותיהם, לפיכך הטיל הקדוש ברוך הוא שמו עליהם, ה''א מצד זה ויו''ד מצד זה, לומר, מעיד אני עליהם שהם בני אבותיהם. וזהו הוא שמפורש על ידי דוד (תהלים קכב, ד) שבטי יה עדות לישראל. השם הזה מעיד עליהם לשבטיהם, לפיכך בכלם כתיב החנכי הפלאי, אבל בימנה לא הצרך לומר משפחת הימני, לפי שהשם קבוע בו יו''ד בראש וה''א בסוף:
@895 **אשר הצו.** את ישראל על משה: **בהצתם.** את העם על ה': **הצו.** השיאו את ישראל לריב על משה, לשון הפעילו:
@896 **ויהיו לנס.** לאות ולזכרון (במדבר יז, ה) למען אשר לא יקרב איש זר, לחלוק עוד על הכהנה:
@897 **ובני קרח לא מתו.** הם היו בעצה תחלה, ובשעת המחלוקת הרהרו תשובה בלבם, לפיכך נתבצר להם מקום גבוה בגיהנם וישבו שם:
@899 **לזרח.** הוא צוחר, לשון צוהר. אבל משפחת אהד בטלה, וכן חמשה משבט בנימין, שהרי בעשרה בנים ירד למצרים וכאן לא מנה אלא חמשה, וכן אצבון לגד, הרי שבע משפחות. ומצאתי בגמרא ירושלמית, שכשמת אהרן נסתלקו ענני כבוד ובאו הכנענים להלחם בישראל ונתנו לב לחזור למצרים וחזרו לאחוריהם שמנה מסעות מהר ההר למוסרה, שנאמר (דברים י, ו) ובני ישראל נסעו מבארות בני יעקן מוסרה שם מת אהרן, והלא בהר ההר מת, וממוסרה עד הר ההר שמונה מסעות יש למפרע, אלא שחזרו לאחוריהם ורדפו בני לוי אחריהם להחזירם, והרגו מהם שבע משפחות, ומבני לוי נפלו ארבע משפחות משפחת שמעי ועזיאלי, ומבני יצהר לא נמנו כאן אלא משפחת הקרחי, והרביעית לא ידעתי מה היא. ורבי תנחומא דרש שמתו במגפה בדבר בלעם, אבל לפי החסרון שחסר משבט שמעון במנין זה ממנין הראשון שבמדבר סיני, נראה שכל עשרים וארבעה אלף נפלו משבטו של שמעון:
@902 **לאזני.** אומר אני שזו משפחת אצבון, ואיני יודע למה לא נקראת משפחתו על שמו:
@910 **לישוב.** הוא יוב האמור ביורדי מצרים, כי כל המשפחות נקראו על שם יורדי מצרים. והנלדין משם והלאה לא נקראו המשפחות על שמם, חוץ ממשפחות אפרים ומנשה שנלדו כלם במצרים, וארד ונעמן בני בלע בן בנימין. ומצאתי ביסודו של רבי משה הדרשן שירדה אמן למצרים כשהיתה מעברת מהם, לכך נחלקו למשפחות, כחצרון וחמול, שהיו בני בנים ליהודה, וחבר ומלכיאל שהיו בני בנים של אשר. ואם אגדה היא הרי טוב, ואם לאו, אומר אני, שהיו לבלע בני בנים הרבה, ומשנים הללו ארד ונעמן יצאה מכל אחד משפחה רבה ונקראו תולדות שאר הבנים על שם בלע, ותולדות השנים הללו נקראו על שמם. וכן אני אומר בבני מכיר, שנחלקו לשתי משפחות, אחת נקראת על שמו ואחת נקראת על שם גלעד בנו. חמש משפחות חסרו מבניו של בנימין, כאן נתקימה מקצת נבואת אמו שקראתו בן אוני, בן אנינותי ובפלגש בגבעה נתקימה כלה. זו מצאתי ביסודו של ר' משה הדרשן:
@922 **ואלה בני שותלח** וגו' **.** שאר בני שותלח נקראו תולדותיהם על שם שותלח. ומערן יצאה משפחה רבה ונקראת על שמו. ונחשבו בני שותלח לשתי משפחות. צא וחשוב ותמצא בפרשה זו חמשים ושבע משפחות, ומבני לוי שמונה, הרי ששים וחמש, וזהו שנאמר (דברים ז, ז) כי אתם המעט וגו' , ה''א מעט, חמשה אתם חסרים ממשפחות כל העמים, שהן שבעים, אף זה הבנתי מיסודו של ר' משה הדרשן. אך הצרכתי לפחות ולהוסיף בדבריו:
@924 **לאחירם.** הוא אחי שירד למצרים, ולפי שנקרא על שם יוסף שהיה אחיו ורם ממנו נקרא אחירם:
@925 **לשפופם.** הוא מפים, על שהיה יוסף שפוף בין האמות:
@928 **לשוחם.** הוא חשים:
@932 **ושם בת אשר שרח.** לפי שהיתה קימת בחיים מנאה כאן:
@939 **לאלה תחלק הארץ.** ולא לפחותים מבן עשרים, אף על פי שבאו לכלל עשרים בטרם חלוק הארץ, שהרי שבע שנים כבשו ושבע חלקו, לא נטלו חלק בארץ אלא אלו שש מאות אלף ואלף, ואם היה לאחד מהם ששה בנים, לא נטלו אלא חלק אביהם לבדו:
@940 **לרב תרבה נחלתו.** לשבט שהיה מרבה באכלוסין נתנו חלק רב, ואף על פי שלא היו החלקים שוים, שהרי הכל לפי רבוי השבט חלקו החלקים, לא עשו אלא על ידי גורל, והגורל היה על פי רוח הקדש, כמו שמפורש בבבא בתרא (קכב, א) אלעזר הכהן היה מלבש באורים ותמים, ואומר ברוח הקדש אם שבט פלוני עולה, תחום פלוני עולה עמו. והשבטים היו כתובים בשנים עשר פתקין, ושנים עשר גבולים בשנים עשר פתקין, ובללום בקלפי והנשיא מכניס ידו לתוכה ונוטל שני פתקין, עולה בידו פתק של שם שבטו, ופתק של גבול המפורש לו, והגורל עצמו היה צווח ואומר אני הגורל עליתי לגבול פלוני, לשבט פלוני, שנאמר על פי הגורל, ולא נתחלקה הארץ במדה, לפי שיש גבול משבח מחברו, אלא בשומא, בית כור רע כנגד בית סאה טוב, הכל לפי הדמים:
@941 **לשמות מטות אבתם.** אלו יוצאי מצרים. שנה הכתוב נחלה זו מכל הנחלות שבתורה, שכל הנחלות החיים יורשים את המתים וכאן מתים יורשים את החיים. כיצד, שני אחים מיוצאי מצרים, שהיו להם בנים בבאי הארץ, לזה אחד ולזה שלשה, האחד נטל חלק אחד, והשלשה נטלו שלשה, שנאמר לאלה תחלק הארץ, חזרה נחלתן אצל אבי אביהן וחלקו הכל בשוה. וזהו שנאמר לשמות מטות אבתם ינחלו. שאחר שנטלו הבנים חלקוה לפי האבות שיצאו ממצרים, ואלו מתחלה חלקוה למנין יוצאי מצרים לא היו נוטלין אלו הארבעה, אלא שני חלקים, עכשו נטלו ארבעה חלקים: **אך בגורל.** יצאו יהושע וכלב, וכן הוא אומר (שופ' א) ויתנו לכלב את חברון כאשר דבר משה, ואומר (יהושע יט) על פי ה' נתנו לו את העיר אשר שאל: **מטות אבתם.** יצאו גרים ועבדים:
@942 **על פי הגורל.** הגורל היה מדבר, כמו שפרשתי, מגיד שנתחלקה ברוח הקדש, לכך נאמר על פי ה':
@944 **אלה משפחת לוי.** חסר כאן משפחות השמעי והעזיאלי וקצת מן היצהרי:
@945 **אשר ילדה אתה ללוי במצרים.** לידתה במצרים ואין הורתה במצרים. כשנכנסו לתוך החומה ילדתה, והיא השלימה מנין שבעים, שהרי בפרטן אי אתה מוצא אלא ששים ותשע:
@948 **כי לא התפקדו בתוך בני ישראל.** להיות נמנין בני עשרים שנה, ומה טעם: **כי לא נתן להם נחלה.** והנמנין מבן עשרים שנה היו בני נחלה, שנאמר איש לפי פקדיו יתן נחלתו:
@950 **ובאלה לא היה איש** וגו' **.** אבל על הנשים לא נגזרה גזרת המרגלים, לפי שהן היו מחבבות את הארץ. האנשים אומרים (במדבר יד, ד) נתנה ראש ונשובה מצרימה, והנשים אומרות (במד' כז) תנה לנו אחזה. לכך נסמכה פרשת בנות צלפחד לכאן:
@952 **למשפחת מנשה בן יוסף.** למה נאמר, והלא כבר נאמר בן מנשה, אלא לומר לך יוסף חבב את הארץ, שנאמר (בראשית נ, כה) והעליתם את עצמתי וגו' , ובנותיו חבבו את הארץ, שנאמר (במדבר כז, ד) תנה לנו אחזה. וללמדך שהיו כלם צדיקים, שכל מי שמעשיו ומעשה אבותיו סתומים ופרט לך הכתוב באחד מהם ליחסו לשבח, הרי זה צדיק בן צדיק. ואם יחסו לגנאי כגון (מלכים ב' כה, כה) בא ישמעאל בן נתניה בן אלישמע, בידוע שכל הנזכרים עמו רשעים היו: **מחלה נעה** וגו' **.** ולהלן הוא אומר (במדבר לו, יא) ותהיינה מחלה תרצה, מגיד שכלן שקולות זו כזו, לפיכך שנה את סדרן:
@953 **לפני משה ולפני אלעזר.** מגיד שלא עמדו לפניהם אלא בשנת הארבעים, אחר שמת אהרן: **לפני משה.** ואחר כך לפני אלעזר, אפשר אם משה לא ידע אלעזר יודע, אלא סרס המקרא ודרשהו, דברי רבי יאשיה. אבא חנן משום רבי אלעזר אומר בבית המדרש היו יושבים, ועמדו לפני כלם:
@954 **והוא לא היה** וגו' **.** לפי שהיו באות לומר בחטאו מת, נזקקו לומר לא בחטא מתלוננים ולא בעדת קרח שהצו על הקדוש ברוך הוא, אלא בחטאו לבדו מת, ולא החטיא את אחרים עמו. ר' עקיבא אומר מקושש עצים היה. ור' שמעון אומר מן המעפילים היה:
@955 **למה יגרע שם אבינו.** אנו במקום בן עומדות, ואם אין הנקבות חשובות זרע, תתיבם אמנו ליבם: **כי אין לו בן.** הא אם היה לו בן לא היו תובעות כלום. מגיד שחכמניות היו:
@956 **ויקרב משה את משפטן.** נתעלמה הלכה ממנו וכאן נפרע על שנטל עטרה לומר (דברים א, יז) והדבר אשר יקשה מכם תקרבון אלי. דבר אחר ראויה היתה פרשה זו להכתב על ידי משה, אלא שזכו בנות צלפחד ונכתבה על ידן:
@958 **כן בנות צלפחד דברת.** כתרגומו יאות, כך כתובה פרשה זו לפני במרום, מגיד שראתה עינן מה שלא ראתה עינו של משה: **כן בנות צלפחד דברת.** יפה תבעו. אשרי אדם שהקדוש ברוך הוא מודה לדבריו: **נתן תתן.** שני חלקים, חלק אביהן, שהיה מיוצאי מצרים, וחלקו עם אחיו בנכסי חפר: **והעברת.** לשון עברה הוא במי שאינו מניח בן לירשו. דבר אחר על שם שהבת מעברת נחלה משבט לשבט שבנה ובעלה יורשין אותה. שלא תסוב נחלה לא נצטוה אלא לאותו הדור בלבד וכן והעברתם את נחלתו לבתו, בכלן הוא אומר ונתתם, ובבת הוא אומר והעברתם:
@962 **לשארו הקרב אליו ממשפחתו.** ואין משפחה קרויה אלא משפחת האב:
@963 **עלה אל הר העברים.** למה נסמכה לכאן, כיון שאמר הקדוש ברוך הוא נתן תתן להם, אמר אותי צוה המקום להנחיל, שמא התרה הגזרה ואכנס לארץ. אמר לו הקדוש ברוך הוא גזרתי במקומה עומדת. דבר אחר כיון שנכנס משה לנחלת בני גד ובני ראובן שמח ואמר כמדמה שהתר לי נדרי, משל למלך שגזר על בנו שלא יכנס לפתח פלטין שלו, נכנס לשער והוא אחריו, לחצר והוא אחריו, לטרקלין והוא אחריו, כיון שבא לכנס לקיטון, אמר לו בני מכאן ואלך אתה אסור לכנס:
@964 **כאשר נאסף אהרן אחיך.** מכאן שנתאוה משה למיתתו של אהרן. דבר אחר אין אתה טוב ממנו, (דברים לב, נא) על אשר לא קדשתם, הא אם קדשתם אותי עדין לא הגיע זמנכם להפטר. בכל מקום שכתב מיתתם כתב סרחונם, לפי שנגזרה גזרה על דור המדבר למות במדבר בעון שלא האמינו, לכך בקש משה שיכתב סרחונו, שלא יאמרו אף הוא מן הממרים היה. משל לשתי נשים שלוקות בבית דין אחת קלקלה ואחת אכלה פגי שביעית וכו' , אף כאן בכל מקום שהזכיר מיתתן הזכיר סרחונם, להודיע שלא היתה בהם אלא זו בלבד:
@965 **הם מי מריבת קדש.** הם לבדם אין בהם עון אחר. דבר אחר הם שהמרו במרה, הם היו שהמרו בים סוף, הם עצמם שהמרו במדבר צין:
@966 **וידבר משה אל ה'** וגו' **.** להודיע שבחן של צדיקים שכשנפטרין מן העולם מניחין צרכן ועוסקין בצרכי צבור: **לאמר.** אמר לו השיבני אם אתה ממנה להם פרנס אם לאו:
@967 **יפקד ה'.** כיון ששמע משה שאמר לו המקום תן נחלת צלפחד לבנותיו אמר הגיע שעה שאתבע צרכי שיירשו בני את גדלתי. אמר לו הקדוש ברוך הוא לא כך עלתה במחשבה לפני, כדאי הוא יהושע לטול שכר שמושו שלא מש מתוך האהל. וזהו שאמר שלמה (משלי כז, יח) נצר תאנה יאכל פריה: **אלהי הרוחת.** למה נאמר, אמר לפניו: רבונו של עולם, גלוי וידוע לפניך דעתו של כל אחד ואחד ואינן דומין זה לזה, מנה עליהם מנהיג שיהא סובל כל אחד ואחד לפי דעתו:
@968 **אשר יצא לפניהם.** לא כדרך מלכי האמות שיושבים בבתיהם ומשלחין את חילותיהם למלחמה, אלא כמו שעשיתי אני שנלחמתי בסיחון ועוג, שנאמר אל תירא אתו. (במדבר כא, לד) וכדרך שעשה יהושע, שנאמר (יהושע ה, יג) וילך יהושע אליו ויאמר לו הלנו אתה וגו' . וכן בדוד הוא אומר (ש''א יח, טז) כי הוא יוצא ובא לפניהם, יוצא בראש ונכנס בראש: **ואשר יוציאם.** בזכיותיו: **ואשר יביאם.** בזכיותיו. דבר אחר ואשר יביאם שלא תעשה לו כדרך שאתה עושה לי, שאיני מכניסן לארץ:
@969 **קח לך.** קחנו בדברים אשריך שזכית להנהיג בניו של מקום: **לך.** את שבדוק לך את זה אתה מכיר: **אשר רוח בו.** כאשר שאלת שיוכל להלוך כנגד רוחו של כל אחד ואחד: **וסמכת את ידך עליו.** תן לו מתרגמן שידרוש בחייך, שלא יאמרו עליו, לא היה לו להרים ראש בימי משה:
@970 **וצויתה אתו.** על ישראל, דע שטרחנין הם סרבנים הם, על מנת שתקבל עליך:
@971 **ונתתה מהודך עליו.** זה קרון עור פנים: **מהודך.** ולא כל הודך נמצינו למדין פני משה כחמה פני יהושע כלבנה: **למען ישמעו כל עדת בני ישראל.** שיהיו נוהגין בו כבוד ויראה כדרך שנוהגין בך:
@972 **ולפני אלעזר הכהן יעמד.** הרי שאלתך ששאלת שאין הכבוד הזה זז מבית אביך, שאף יהושע יהא צריך לאלעזר: **ושאל לו.** כשיצטרך לצאת למלחמה: **על פיו.** של אלעזר: **וכל העדה.** סנהדרין:
@973 **ויקח את יהושע.** לקחו בדברים והודיעו מתן שכר פרנסי ישראל לעולם הבא:
@974 **ויסמך את ידיו עליו.** בעין יפה יותר ויותר ממה שנצטוה. שהקדוש ברוך הוא אמר לו וסמכת את ידך, והוא עשה בשתי ידיו, ועשאו ככלי מלא וגדוש ומלאו חכמתו בעין יפה: **כאשר דבר ה'.** אף לענין ההוד נתן מהודו עליו:
@976 **צו את בני ישראל.** מה אמור למעלה (כז, טז) יפקד ה'. אמר לו הקדוש ברוך הוא עד שאתה מצוני על בני, צוה את בני עלי. משל לבת מלך שהיתה נפטרת מן העולם והיתה מפקדת לבעלה על בניה וכו' , כדאיתא בספרי: **קרבני.** זה הדם: **לחמי.** אלו אמורין, וכן הוא אומר (ויקרא ג, טז) והקטירם הכהן המזבחה לחם אשה: **לאשי.** הנתנין לאשי מזבחי: **תשמרו.** שיהיו כהנים ולוים וישראלים עומדין על גביו מכאן למדו ותקנו מעמדות: **במועדו.** בכל יום הוא מועד התמידים:
@977 **ואמרת להם.** אזהרה לבית דין: **שנים ליום.** כפשוטו ועיקרו בא ללמד שיהיו נשחטין כנגד היום, תמיד של שחר במערב ושלבין הערבים במזרחן של טבעות:
@978 **את הכבש אחד.** אף על פי שכבר נאמר בפרשת ואתה תצוה, וזה אשר תעשה וגו' (שמות כט, לח) , היא היתה אזהרה לימי המלואים, וכאן צוה לדורות:
@979 **סלת למנחה.** מנחת נסכים:
@980 **העשיה בהר סיני.** כאותן שנעשו בימי המלואים. דבר אחר העשיה בהר סיני, הקיש עולת תמיד לעולת הר סיני אותה שנתקרבה לפני מתן תורה שכתוב בה (שמות כד, ו) וישם באגנות מלמד שטעונה כלי:
@981 **ונסכו.** יין: **בקדש הסך.** על המזבח יתנסכו: **נסך שכר.** יין המשכר פרט ליין מגתו:
@982 **ריח ניחח.** נחת רוח לפני שאמרתי ונעשה רצוני:
@984 **עלת שבת בשבתו.** ולא עולת שבת זו בשבת אחרת, הרי שלא הקריב בשבת זו שומע אני יקריב שתים לשבת הבאה, תלמוד לומר בשבתו, מגיד שאם עבר יומו בטל קרבנו: **על עלת התמיד.** אלו מוספין, לבד אותן שני כבשים של עולת התמיד. ומגיד שאין קרבין אלא בין שני התמידין, וכן בכל המוספין נאמר על עולת התמיד לתלמוד זה:
@986 **ושלשה עשרונים.** כמשפט נסכי פר, שכן הן קצובין בפרשת נסכים:
@988 **זאת עלת חדש בחדשו.** שאם עבר יומו בטל קרבנו ושוב אין לו תשלומין:
@989 **ושעיר עזים** וגו' **.** כל שעירי המוספין באין לכפר על טמאת מקדש וקדשיו, הכל כמו שמפורש במס' שבועות (דף ט, א) . ונשתנה שעיר ראש חדש שנאמר בו לה', ללמדך שמכפר על שאין בו ידיעה לא בתחלה ולא בסוף, שאין מכיר בחטא אלא הקדוש ברוך הוא בלבד, ושאר השעירין למדין ממנו. ומדרשו באגדה אמר הקדוש ברוך הוא, הביאו כפרה עלי על שמעטתי את הירח: **על עלת התמיד יעשה.** כל הקרבן הזה: **ונסכו.** אין ונסכו מוסב על השעיר, שאין נסכים לחטאת:
@992 **כל מלאכת עבדה.** אפלו מלאכה הצריכה לכם, כגון דבר האבד המתרת בחלו של מועד אסורה ביום טוב:
@993 **פרים.** כנגד אברהם, שנאמר (בראשית יח, ז) ואל הבקר רץ אברהם: **ואיל.** כנגד אילו של יצחק: **כבשים.** כנגד יעקב שנאמר (בראשית ל, מ) והכשבים הפריד יעקב. ביסודו של רבי משה הדרשן ראיתי זאת:
@998 **כאלה תעשו ליום.** שלא יהיו פוחתין והולכין כפרי החג:
@1000 **וביום הבכורים.** חג השבועות קרוי בכורי קציר חטים על שם שתי הלחם, שהם ראשונים למנחת חטים הבאים מן החדש:
@1005 **תמימים יהיו לכם ונסכיהם.** אף הנסכים יהיו תמימים. למדו רבותינו מכאן שהיין שהעלה קמחין פסול לנסכים:
@1011 **מלבד עלת החדש.** מוספי ראש חדש שהוא ביום ראש השנה:
@1016 **מלבד חטאת הכפרים.** שעיר הנעשה בפנים האמור באחרי מות, שגם הוא חטאת: **ועלת התמיד.** ומלבד עולת התמיד תעשו עולות הללו: **ונסכיהם.** מוסב על המוספין הכתובים ועל תעשו והוא לשון צווי מלבד עולת התמיד ומנחתה תעשו את אלה ונסכיהם. וכן כל ונסכיהם האמורים בכל המועדות חוץ משל קרבנות החג שכל ונסכה ונסכיהם ונסכיה שבהם מוסבים על התמיד ואינן לשון צווי, שהרי נסכיהם של מוספין כתובין לעצמן בכל יום ויום:
@1023 **ומנחתם ונסכיהם לפרים.** פרי החג שבעים הם. כנגד שבעים אמות שמתמעטים והולכים, סימן כליה להם, ובימי המקדש היו מגינין עליהם מן היסורין: **ולכבשים.** כנגד ישראל שנקראו (ירמיה נ, יז) שה פזורה, והם קבועים ומנינם תשעים ושמונה לכלות מהם תשעים ושמונה קללות שבמשנה תורה. בשני נאמר ונסכיהם על שני תמידי היום ולא שנה הלשון אלא לדרוש, כמו שאמרו רבותינו זכרונם לברכה בשני ונסכיהם, בששי ונסכיה, בשביעי כמשפטם, מ''ם יו''ד מ''ם, הרי כאן מים, רמז לנסוך המים מן התורה בחג:
@1040 **עצרת תהיה לכם.** עצורים בעשית מלאכה. דבר אחר עצרת עצרו מלצאת, מלמד שטעון לינה. ומדרשו באגדה לפי שכל ימות הרגל הקריבו כנגד שבעים אמות וכשבאין ללכת, אמר להם המקום בבקשה מכם עשו לי סעודה קטנה כדי שאהנה מכם:
@1041 **פר אחד איל אחד.** אלו כנגד ישראל, התעכבו לי מעט עוד. ולשון חבה הוא זה, כבנים הנפטרים מאביהם והוא אומר להם קשה עלי פרידתכם עכבו עוד יום אחד. משל למלך שעשה סעודה וכו', כדאיתא במסכת סכה (דף נה, ב) ובמדרש רבי תנחומא למדה תורה דרך ארץ, שמי שיש לו אכסנאי יום ראשון יאכילו פטומות, למחר מאכילו דגים, למחר מאכילו בשר בהמה, למחר מאכילו קטניות, למחר מאכילו ירק, פוחת והולך כפרי החג:
@1044 **אלה תעשו לה' במועדיכם.** דבר הקצוב לחובה: **לבד מנדריכם.** אם באתם לדור קרבנות ברגל, מצוה היא בידכם או נדרים או נדבות שנדרתם כל השנה תקריבום ברגל, שמא יקשה לו לחזור ולעלות לירושלים ולהקריב נדריו, ונמצא עובר בבל תאחר:
@1045 **ויאמר משה אל בני ישראל.** להפסיק הענין, דברי רבי ישמעאל, לפי שעד כאן דבריו של מקום ופרשת נדרים מתחלת בדבורו של משה, הצרך להפסיק תחלה ולומר שחזר משה ואמר פרשה זו לישראל, שאם לא כן יש במשמע שלא אמר להם זו אלא בפרשת נדרים התחיל דבריו:
@1046 **ראשי המטות.** חלק כבוד לנשיאים ללמדם תחלה ואחר כך לכל בני ישראל. ומנין שאף שאר הדברות כן, תלמוד לומר (שמות לד, לא. לב) וישבו אליו אהרן וכל הנשאים בעדה וידבר משה אליהם ואחרי כן נגשו כל בני ישראל. ומה ראה לאמרה כאן, למד שהפרת נדרים ביחיד ממחה ואם אין יחיד ממחה מפר בשלשה הדיוטות. או יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד, נאמר כאן זה הדבר, ונאמר בשחוטי חוץ (ויקרא יז, ב) זה הדבר, מה להלן נאמרה לאהרן ולבניו ולכל בני ישראל, שנאמר דבר אל אהרן וגו' , אף זו נאמרה לכלן: **זה הדבר.** משה נתנבא (שמות יא, ד) בכה אמר ה' כחצות הלילה, והנביאים נתנבאו בכה אמר ה', מוסף עליהם משה שנתנבא בלשון זה הדבר. דבר אחר זה הדבר מעוט הוא, לומר שהחכם בלשון התרה ובעל בלשון הפרה, כלשון הכתוב כאן, ואם חלפו אין מתר ואין מופר:
@1047 **נדר.** האומר הרי עלי קנם שלא אוכל או שלא אעשה דבר פלוני, יכול אפלו נשבע שיאכל נבלות אני קורא עליו ככל היוצא מפיו יעשה, תלמוד לומר לאסר אסר את המתר ולא להתיר את האסור: **לא יחל דברו.** כמו לא יחלל דברו, לא יעשה דבריו חלין:
@1048 **בבית אביה.** ברשות אביה ואפלו אינה בביתו: **בנעריה.** ולא קטנה ולא בוגרת, שהקטנה אין נדרה נדר והבוגרת אינה ברשותו של אביה להפר נדריה. ואי זו היא קטנה, אמרו רבותינו בת אחת עשרה שנה ויום אחד נדריה נבדקין. אם ידעה לשם מי נדרה ולשם מי הקדישה נדרה נדר. בת שתים עשרה שנה ויום אחד אינה צריכה להבדק:
@1050 **ואם הניא אביה אתה.** אם מנע אותה מן הנדר, כלומר שהפר לה. הנאה זו איני יודע מה היא, כשהוא אומר ואם ביום שמע אישה יניא אותה והפר, הוי אומר הנאה זו הפרה. ופשוטו לשון מניעה והסרה וכן (במדבר לב, ז) ולמה תניאון, וכן (תהלים קמא, ה) שמן ראש אל יני ראשי, וכן (במדבר יד, לד) וידעתם את תנואתי, את אשר סרתם מעלי: **וה' יסלח לה.** במה הכתוב מדבר באשה שנדרה בנזיר ושמע בעלה והפר לה והיא לא ידעה ועוברת על נדרה ושותה יין ומטמאה למתים, זו היא שצריכה סליחה, ואף על פי שהוא מופר. ואם המופרים צריכים סליחה, קל וחמר לשאינן מופרים:
@1051 **ואם היו תהיה לאיש.** זו ארוסה או אינו אלא נשואה, כשהוא אומר ואם בית אישה נדרה, הרי נשואה אמור וכאן בארוסה, ובא לחלק בה, שאביה ובעלה מפירין נדרה. הפר האב ולא הפר הבעל או הפר הבעל ולא הפר האב, הרי זה אינו מופר, ואין צריך לומר אם קים אחד מהם: **ונדריה עליה.** שנדרה בבית אביה ולא שמע בהן אביה ולא הופרו ולא הוקמו:
@1052 **ושמע אישה** וגו' **.** הרי לך שאם קים הבעל שהוא קים:
@1053 **והפר את נדרה אשר עליה.** יכול אפלו לא הפר האב, תלמוד למר בנעריה בית אביה, כל שבנעוריה ברשות אביה היא:
@1054 **כל אשר אסרה על נפשה יקום עליה.** לפי שאינה לא ברשות אב ולא ברשות בעל, ובאלמנה מן הנשואין הכתוב מדבר, אבל אלמנה מן האירוסין, מת הבעל נתרוקנה וחזרה לרשות האב:
@1055 **ואם בית אישה נדרה.** בנשואה הכתוב מדבר:
@1058 **כל נדר וכל שבעת אסר** וגו' **.** לפי שאמר שהבעל מפר, יכול כל נדרים במשמע, תלמוד לומר לענות נפש, אינו מפר אלא נדרי ענוי נפש בלבד. והם מפורשים במסכת נדרים (דף עט, א) :
@1059 **מיום אל יום.** שלא תאמר מעת לעת, לכך נאמר מיום אל יום, ללמדך שאין מפר אלא עד שתחשך:
@1060 **אחרי שמעו.** אחרי ששמע וקים, שאמר אפשי בו, וחזר והפר לה אפלו בו ביום: **ונשא את עונה.** הוא נכנס תחתיה. למדנו מכאן שהגורם תקלה לחברו הוא נכנס תחתיו לכל ענשין:
@1063 **מאת המדינים.** ולא מאת המואבים, שהמואבים נכנסו לדבר מחמת יראה שהיו יראים מהם, שיהיו שוללים אותם, שלא נאמר אלא (דברים ב, ט) אל תתגר בם מלחמה. אבל מדינים נתעברו על ריב לא להם. דבר אחר מפני שתי פרידות טובות שיש לי להוציא מהם, רות המואביה ונעמה העמונית:
@1064 **וידבר משה** וגו' **.** אף על פי ששמע שמיתתו תלויה בדבר עשה בשמחה ולא אחר: **החלצו.** כתרגומו לשון חלוצי צבא מזינים: **אנשים.** צדיקים, וכן (שמות יז, ט) בחר לנו אנשים, וכן (דברים א, טו) אנשים חכמים וידעים: **נקמת ה'.** שהעומד כנגד ישראל, כאלו עומד כנגד הקדוש ברוך הוא:
@1065 **לכל מטות ישראל.** לרבות שבט לוי:
@1066 **וימסרו.** להודיעך שבחן של רועי ישראל כמה הם חביבים על ישראל, עד שלא שמעו במיתתו מה הוא אומר (שמות יז, ד) עוד מעט וסקלני, ומששמעו שמיתת משה תלויה בנקמת מדין, לא רצו ללכת עד שנמסרו על כרחן:
@1067 **אתם ואת פנחס.** מגיד שהיה פנחס שקול כנגד כלם. ומפני מה הלך פנחס ולא הלך אלעזר. אמר הקדוש ברוך הוא מי שהתחיל במצוה, שהרג כזבי בת צור, יגמור. דבר אחר שהלך לנקום נקמת יוסף אבי אמו, שנאמר (בראשית לז, לו) והמדנים מכרו אתו. ומנין שהיתה אמו של פנחס משל יוסף, שנאמר (שמות ו, כה) מבנות פוטיאל, מזרע יתרו שפטם עגלים לעבודה זרה ומזרע יוסף שפטפט ביצרו. דבר אחר שהיה משוח מלחמה: **וכלי הקדש.** זה הארון והציץ. שהיה בלעם עמהם ומפריח מלכי מדין בכשפים, והוא עצמו פורח עמהם. הראה להם את הציץ, שהשם חקוק בו, והם נופלים, לכך נאמר על חלליהם במלכי מדין, שנופלים על החללים מן האויר, וכן בבלעם כתיב (יהושע יג, כב) אל חלליהם: **בידו.** ברשותו וכן (במדבר כא, כז) ויקח את כל ארצו מידו:
@1069 **חמשת מלכי מדין.** וכי איני רואה שחמשה מנה הכתוב, למה הזקק לומר חמשת, אלא ללמדך ששוו כלם בעצה והשוו כלם בפרענות. בלעם הלך שם לטול שכר עשרים וארבעה אלף שהפיל מישראל בעצתו, ויצא ממדין לקראת ישראל ומשיאן עצה רעה. אמר להם אם כשהייתם ששים רבוא לא יכלתם להם, ועכשיו בשנים עשר אלף אתם באים להלחם. נתנו לו שכרו משלם ולא קפחוהו: **בחרב.** הוא בא על ישראל, והחליף אמנותו באמנותם, שאין נושעים אלא בפיהם על ידי תפלה ובקשה. ובא הוא ותפש אמנותם לקללם בפיו, אף הם באו עליו והחליפו אמנותם באמנות האמות, שבאין בחרב, שנאמר (בראשית כז, מ) ועל חרבך תחיה:
@1071 **טירתם.** מקום פלטרין שלהם, שהוא לשון מושב כומרים יודעי חקיהם. דבר אחר לשון מושב שריהם, כמו שמתרגם סרני פלשתים טורני פלשתאי:
@1072 **ויקחו את כל השלל** וגו' **.** מגיד שהיו כשרים וצדיקים ולא נחשדו על הגזל לשלוח יד בבזה שלא ברשות, שנאמר את כל השלל וגו' , ועליהם מפורש בקבלה שניך כעדר הרחלים וגו' , אף אנשי המלחמה שביך כלם צדיקים: **שלל.** הן מטלטלין של מלבוש ותכשיטין: **בז.** הוא בזת מטלטלין שאינם תכשיטין: **מלקוח.** אדם ובהמה. ובמקום שכתוב שבי אצל מלקוח, שבי באדם ומלקוח בבהמה:
@1074 **ויצאו משה ואלעזר הכהן.** לפי שראו את נערי ישראל יוצאים לחטף מן הבזה:
@1075 **ויקצף משה על פקודי החיל.** ממנים על החיל, ללמדך שכל סרחון הדור תלוי בגדולים שיש כח בידם למחות:
@1077 **הן הנה.** מגיד שהיו מכירין אותן. זו היא שנכשל פלוני בה: **בדבר בלעם.** אמר להם אפלו אתם מכניסים כל המונות [האמות] שבעולם אין אתם יכולים להם, שמא מרבים אתם מן המצרים שהיו שש מאות רכב בחור. בואו ואשיאכם עצה. אלהיהם של אלו שונא זמה הוא וכו' , כדאיתא בחלק (סנהדרין קו.) ובספרי:
@1078 **וכל אשה ידעת איש.** ראויה להבעל אף על פי שלא נבעלה. ולפני הציץ העבירום והראויה להבעל פניה מוריקות: **הרגו.** למה חזר ואמר, להפסיק הענין, דברי ר' ישמעאל, שאם אני קורא הרגו כל זכר בטף וכל אשה ידעת איש וכל הטף בנשים וגו' איני יודע אם להרוג עם הזכרים או להחיות עם הטף, לכך נאמר הרגו:
@1080 **מחוץ למחנה.** שלא יכנסו לעזרה: **כל הרג נפש.** ר' מאיר אומר בהורג בדבר המקבל טמאה הכתוב מדבר, ולמדך הכתוב שהכלי מטמא אדם בחבורי המת, כאלו נוגע במת עצמו, או יכול אפלו זרק בו חץ והרגו, תלמוד לומר וכל נגע בחלל, מקיש הורג לנוגע, מה נוגע על ידי חבורו, אף הורג על ידי חבורו: **תתחטאו.** במי נדה, כדין שאר טמאי מתים, שאף לדברי האומרים קברי גוים אינן מטמאין באהל, שנאמר (יחזקאל לד, לא) ואתן צאני צאן מרעיתי אדם אתם, אתם קרויין אדם ואין הגוים קרויין אדם, מודה הוא שהגוים מטמאין במגע ובמשא, שלא נאמר אדם אלא אצל טמאת אהלים, שנאמר אדם כי ימות באהל: (במדבר יט, יד) **אתם ושביכם.** לא שהנכרים מקבלין טמאה וצריכין הזאה, אלא מה אתם בני ברית, אף שביכם כשיבואו לברית ויטמאו, צריכין הזאה:
@1081 **וכל מעשה עזים.** להביא כלי הקרנים והטלפים והעצמות:
@1082 **ויאמר אלעזר הכהן** וגו' **.** לפי שבא משה לכלל כעס בא לכלל טעות, שנתעלמו ממנו הלכות גיעולי נכרים. וכן אתה מוצא בשמיני למלואים, שנאמר (ויקרא י, טז) ויקצף על אלעזר ועל איתמר, בא לכלל כעס, בא לכלל טעות, וכן (במדבר כ, י. יא) בשמעו נא המרים ויך את הסלע, על ידי הכעס טעה: **אשר צוה ה'** וגו' **.** תלה ההוראה ברבו:
@1083 **אך את הזהב** וגו' **.** אף על פי שלא הזהיר לכם משה אלא על הלכות טמאה, עוד יש להזהיר לכם על הלכות געול. ואך לשון מעוט, כלומר ממועטין אתם מלהשתמש בכלים אפלו לאחר טהרתן מטמאת המת, עד שיטהרו מבליעת אסור נבלות. ורבותינו אמרו אך את הזהב לומר שצריך להעביר חלודה שלו קודם שיגעילנו, וזהו לשון אך, שלא יהא שם חלודה, אך המתכת יהיה כמות שהוא:
@1084 **כל דבר אשר יבא באש.** לבשל בו כלום: **תעבירו באש.** כדרך תשמישו הגעלתו, מה שתשמישו על ידי חמין, יגעילנו בחמין, ומה שתשמישו על ידי צלי, כגון השפוד והאסכלה, ילבננו באור: **אך במי נדה יתחטא.** לפי פשוטו חטוי זה לטהרו מטמאת מת. אמר להם צריכין הכלים געול לטהרם מן האסור, וחטוי לטהרן מן הטמאה. ורבותינו דרשו מכאן, שאף להכשירן מן האסור הטעין טבילה לכלי מתכות. ומי נדה הכתובין כאן דרשו מים הראוים לטבול בהם נדה. וכמה הם, ארבעים סאה: **וכל אשר לא יבא באש.** כל דבר שאין תשמישו על ידי האור, כגון כוסות וצלוחיות שתשמישן בצונן ולא בלעו אסור: **תעבירו במים.** מטבילן ודיו ודוקא כלי מתכות:
@1085 **אל המחנה.** למחנה שכינה, שאין טמא מת טעון שלוח ממחנה לויה וממחנה ישראל:
@1087 **שא את ראש.** קח את החשבון:
@1088 **וחצית את המלקוח בין תפשי המלחמה** וגו' **.** חציו לאלו וחציו לאלו:
@1093 **ויהי המלקוח יתר הבז.** לפי שלא נצטוו להרים מכס מן המטלטלין אלא מן המלקוח, כתב את הלשון הזה, ויהי המלקוח שבא לכלל חלקה ולכלל מכס, שהיה עודף על בז המטלטלין אשר בזזו עם הצבא איש לו, ולא בא לכלל חלקה מספר הצאן וגו' :
@1103 **וממחצית בני ישראל אשר חצה משה.** לעדה והוציאה להם מן האנשים הצובאים:
@1104 **ותהי מחצת העדה.** כך וכך:
@1109 **ויקח משה** וגו' **הפקדים.** הממנים:
@1110 **ולא נפקד.** ולא נחסר ותרגומו ולא שגא, אף הוא בלשון ארמי חסרון, כמו אנכי אחטנה, (בראשית לא, לט) תרגומו דהות שגיא ממנינא, וכן כי יפקד מושבך (שמואל א' כ, יח) , יחסר מקום מושבך, איש הרגיל לישב שם. וכן (שם כ, כז) ויפקד מקום דוד, נחסר מקומו ואין איש יושב שם:
@1111 **אצעדה.** אלו צמידים של רגל: **וצמיד.** של יד: **עגיל.** נזמי אזן: **וכומז.** דפוס של בית הרחם לכפר על הרהור הלב של בנות מדין:
@1118 **עטרות ודיבון** וגו' **.** מארץ סיחון ועוג היו:
@1121 **האחיכם.** לשון תמיהה הוא:
@1122 **ולמה תניאון.** תסירו ותמניעו לבם מעבור שיהיו סבורים שאתם יראים לעבור מפני המלחמה וחוזק הערים והעם:
@1123 **מקדש ברנע.** כך שמה, ושני קדש היו:
@1127 **הקנזי.** חורגו של קנז היה, וילדה לו אמו של כלב את עתניאל:
@1128 **וינעם.** ויטלטלם. מן נע ונד:
@1129 **לספות.** כמו (ישעיה כט, א) ספו שנה על שנה, (ירמיה ז, כא) עולותיכם ספו וגו' , לשון תוספת:
@1131 **נבנה למקננו פה.** חסים היו על ממונם יותר מבניהם ובנותיהם, שהקדימו מקניהם לטפם. אמר להם משה לא כן עשו, העיקר עיקר והטפל טפל, בנו לכם תחלה ערים לטפכם ואחר כך גדרות לצאנכם:
@1132 **ואנחנו נחלץ חשים.** נזדרז מהירים, כמו (ישעיה ח, א) מהר שלל חש בז, (ישעיה ה, יט) ימהר יחישה: **לפני בני ישראל.** בראשי גיסות, מתוך שגבורים היו, שכן נאמר בגד (דברים לג, כ) וטרף זרוע אף קדקד, ואף משה חזר ופרש להם באלה הדברים (דברים ג, יח) ואצו אתכם בעת ההיא וגו' חלוצים תעברו לפני אחיכם בני ישראל כל בני חיל. וביריחו כתיב (יהושע ו, יג) והחלוץ הולך לפניהם, זה ראובן וגד שקימו תנאם: **וישב טפנו.** בעודנו אצל אחינו: **בערי המבצר.** שנבנה עכשיו:
@1134 **מעבר לירדן** וגו' **.** בעבר המערבי: **כי באה נחלתנו.** כבר קבלנוה בעבר המזרחי:
@1139 **לצנאכם.** תיבה זו מגזרת (תהלים ח, ח) צנה ואלפים כלם, שאין בו אל''ף מפסיק בין נו''ן לצד''י, ואל''ף שבא כאן אחר הנו''ן במקום ה''א של צנה הוא. מיסודו של ר' משה הדרשן למדתי כן: **והיצא מפיכם תעשו.** לגבוה שקבלתם עליכם לעבור למלחמה עד כבוש וחלוק. שמשה לא בקש מהם אלא ונכבשה ואחר תשבו, והם קבלו עליהם עד התנחל, הרי הוסיפו להתעכב שבע שחלקו, וכן עשו:
@1140 **ויאמר בני גד.** כלם כאיש אחד:
@1143 **ויצו להם.** כמו עליהם, ועל תנאם מנה אלעזר ויהושע, כמו (שמות יד, יד) ה' ילחם לכם:
@1147 **ואתנו אחזת נחלתנו.** כלומר בידינו וברשותנו תהי אחזת נחלתנו מעבר הזה:
@1151 **ערי מבצר וגדרות צאן.** זה סוף הפסוק מוסב על תחלת הענין, ויבנו בני גד את הערים הללו להיות ערי מבצר וגדרות צאן:
@1153 **ואת נבו ואת בעל מעון מוסבת שם.** נבו ובעל מעון שמות עבודה זרה הם, והיו האמוריים קורים עריהם על שם עבודה זרה שלהם, ובני ראובן הסבו את שמם לשמות אחרים, וזהו מסבות שם, נבו ובעל מעון מוסבות לשם אחר: **ואת שבמה.** בנו שבמה והיא שבם האמורה למעלה:
@1154 **ויורש.** כתרגומו ותריך. שתבת רי''ש משמשת שתי חלקות לשון ירשה ולשון הורשה, שהוא טירוד ותירוך:
@1156 **חותיהם.** כפרניהון: **ויקרא אתהן חות יאיר.** לפי שלא היו לו בנים קראם בשמו לזכרון:
@1157 **ויקרא לה נבח.** לה אינו מפיק ה''א. וראיתי ביסודו של רבי משה הדרשן לפי שלא נתקים לה שם זה, לפיכך הוא רפה, שמשמע מדרשו כמו לא. ותמהני מה ידרוש בשתי תיבות הדומות לה (רות ב, יד) ויאמר לה בעז, (זכריה ה, יא) לבנות לה בית:
@1158 **אלה מסעי.** למה נכתבו המסעות הללו, להודיע חסדיו של מקום, שאף על פי שגזר עליהם לטלטלם ולהניעם במדבר, לא תאמר שהיו נעים ומטלטלים ממסע למסע כל ארבעים שנה ולא היתה להם מנוחה, שהרי אין כאן אלא ארבעים ושתים מסעות. צא מהם ארבעה עשר, שכלם היו בשנה ראשונה, קודם גזרה, משנסעו מרעמסס עד שבאו לרתמה. שמשם נשתלחו המרגלים, שנאמר (במדבר יב, טז) ואחר נסעו העם מחצרות וגו' (שם יג, ב) שלח לך אנשים וגו' . וכאן הוא אומר ויסעו מחצרות ויחנו ברתמה, למדת שהיא במדבר פארן. ועוד הוצא משם שמונה מסעות שהיו לאחר מיתת אהרן מהר ההר עד ערבות מואב בשנת הארבעים, נמצא שכל שמנה ושלשים שנה לא נסעו אלא עשרים מסעות. זה מיסודו של רבי משה הדרשן. ורבי תנחומא דרש בו דרשה אחרת משל למלך שהיה בנו חולה והוליכו למקום רחוק לרפאותו, כיון שהיו חוזרין התחיל אביו מונה כל המסעות. אמר לו כאן ישנו, כאן הוקרנו, כאן חששת את ראשך וכו' :
@1161 **ומצרים מקברים.** טרודים באבלם:
@1175 **ויחנו ברתמה.** על שם לשון הרע של מרגלים, שנאמר (תהלים קכ, ג) מה יתן לך ומה יוסיף לך לשון רמיה חצי גבור שנונים עם גחלי רתמים:
@1195 **על פי ה'.** מלמד שמת בנשיקה:
@1197 **וישמע הכנעני.** כאן למדך שמיתת אהרן היא השמועה, שנסתלקו ענני הכבוד וכסבור שנתנה רשות להלחם בישראל, לפיכך חזר וכתבה:
@1201 **בעיי העברים.** לשון חרבות וגלים, כמו לעי השדה, (מיכה א, ו) שמו את ירושלים לעיים (תהלים עט, א) :
@1206 **מבית הישמת עד אבל השטים.** כאן למדך שעור מחנה ישראל שנים עשר מיל. דאמר רבה בר בר חנה לדידי חזי לי ההוא אתרא וכו' (ערובין נה, ב) : **אבל השטים.** מישור של שטים אבל שמו:
@1208 **כי אתם עברים את הירדן** וגו' **והורשתם** וגו' **.** והלא כמה פעמים הזהרו על כך, אלא כך אמר להם משה כשאתם עוברים בירדן ביבשה, על מנת כן תעברו, ואם לאו מים באין ושוטפין אתכם, וכן מצינו שאמר להם יהושע בעודם בירדן:
@1209 **והורשתם.** וגרשתם: **משכיתם.** כתרגומו בית סגדתהון, על שם שהיו מסככין את הקרקע ברצפת אבנים של שיש להשתחוות עליהם בפשוט ידים ורגלים, כדכתיב (ויקרא כו, א) ואבן משכית לא תתנו בארצכם להשתחוות עליה: **מסכתם.** כתרגומו מתכתהון:
@1210 **והורשתם את הארץ.** והורשתם אותה מיושביה ואז וישבתם בה, תוכלו להתקים בה, ואם לאו לא תוכלו להתקים בה:
@1211 **אל אשר יצא לו שמה.** מקרא קצר הוא זה, אל מקום אשר יצא לו שמה הגורל לו יהיה: **למטות אבותיכם.** לפי חשבון יוצאי מצרים. דבר אחר בשנים עשר גבולין כמנין השבטים:
@1212 **והיה אשר תותירו מהם.** יהיו לכם לרעה: **לשכים בעיניכם.** ליתדות המנקרות עיניכם. תרגום של יתדות שיכיא: **ולצנינם.** פותרים בו הפותרים לשון מסוכת קוצים הסוככת אתכם לסגור ולכלוא אתכם מאין יוצא ובא: **וצררו אתכם.** כתרגומו:
@1215 **זאת הארץ אשר תפל לכם** וגו' **.** לפי שהרבה מצות נוהגות בארץ ואין נוהגות בחוצה לארץ, הצרך לכתוב מצרני גבולי רוחותיה סביב, לומר לך מן הגבולים הללו ולפנים המצות נוהגות: **תפל לכם.** על שם שנתחלקה בגורל נקראת חלקה לשון נפילה. ומדרש אגדה אומר על ידי שהפיל הקדוש ברוך הוא שריהם של שבע אמות מן השמים וכפתן לפני משה, אמר לו ראה אין בהם עוד כח:
@1216 **והיה לכם פאת נגב.** רוח דרומית אשר מן המזרח למערב: **ממדבר צן.** אשר אצל אדום מתחלת מקצוע דרומית מזרחית של ארץ תשעת המטות. כיצד, שלש ארצות יושבות בדרומה של ארץ ישראל זו אצל זו קצת ארץ מצרים, וארץ אדום כלה וארץ מואב כלה. ארץ מצרים במקצוע דרומית מערבית, שנאמר בפרשה זו מעצמון נחלה מצרים והיו תוצאותיו הימה. ונחל מצרים היה מהלך על פני כל ארץ מצרים, שנאמר (יהושע יג, ג) מן השיחור אשר על פני מצרים. ומפסיק בין ארץ מצרים לארץ ישראל וארץ אדום אצלה לצד המזרח וארץ מואב אצל ארץ אדום בסוף הדרום למזרח, וכשיצאו ישראל ממצרים, אם רצה המקום לקרב את כניסתם לארץ היה מעבירם את הנילוס לצד צפון ובאין לארץ ישראל, ולא עשה כן, וזהו שנאמר (שמות יג, יז) ולא נחם אלהים דרך ארץ פלשתים, שהם יושבים על הים במערבה של ארץ כנען, כענין שנאמר בפלשתים (צפניה ב, ה) יושבי חבל הים גוי כרתים. ולא נחם אותו הדרך אלא הסבן והוציאם דרך דרומה אל המדבר, והוא שקראו יחזקאל (יחזקאל כ, לה) מדבר העמים, לפי שהיו כמה אמות יושבות בצדו והולכין אצל דרומה מן המערב כלפי מזרח תמיד, עד שבאו לדרומה של ארץ אדום ובקשו ממלך אדום שיניחם להכנס בארצו ולעבור דרך רחבה ולהכנס לארץ, ולא רצה. והצרכו לסבוב את כל דרומה של אדום עד בואם לדרומה של ארץ מואב, שנאמר (שופטים יא, יז) וגם אל מלך מואב שלח ולא אבה. והלכו כל דרומה של מואב עד סופה ומשם הפכו פניהם לצפון עד שסבבו כל מצר מזרחי שלה לרחבה וכשכלו את מזרחה מצאו את ארץ סיחון ועוג שהיו יושבין במזרחה של ארץ כנען והירדן מפסיק ביניהם. וזהו שנאמר ביפתח (שופטים יא, יח) וילך במדבר ויסב את ארץ אדום ואת ארץ מואב ויבא ממזרח שמש לארץ מואב. וכבשו את ארץ סיחון ועוג שהיתה בצפונה של ארץ מואב. וקרבו עד הירדן והוא כנגד מקצוע צפונית מערבית של ארץ מואב, נמצא שארץ כנען שבעבר הירדן למערב היה מקצוע דרומית מזרחית שלה אצל אדום:
@1217 **ונסב לכם הגבול מנגב למעלה עקרבים.** כל מקום שנאמר ונסב או ויצא, מלמד שלא היה המצר שווה אלא הולך ויוצא לחוץ, יוצא המצר ועוקם לצד צפונו של עולם באלכסון למערב ועובר המצר בדרומה של מעלה עקרבים, נמצא מעלה עקרבים לפנים מן המצר: **ועבר צנה.** אל צין כמו מצרימה: **והיו תוצאותיו.** קצותיו. בדרומה של קדש ברנע: **ויצא חצר אדר.** מתפשט המצר ומרחיב לצד צפון של עולם ונמשך עוד באלכסון למערב ובא לו לחצר אדר ומשם לעצמון ומשם לנחל מצרים. ולשון ונסב האמור כאן לפי שכתב ויצא חצר אדר שהתחיל להרחיב משעבר את קדש ברנע ורוחב אותה רצועה שבלטה לצד צפון היתה מקדש ברנע עד עצמון ומשם והלאה נתקצר המצר ונסב לצד הדרום ובא לו לנחל מצרים ומשם לצד המערב אל הים הגדול שהוא מצר מערבה של כל ארץ ישראל. נמצא שנחל מצרים במקצוע מערבית דרומית:
@1218 **והיו תוצאותיו הימה.** אל מצר המערב שאין עוד גבול נגב מאריך לצד המערב משם והלאה:
@1219 **וגבול ים.** ומצר מערבי מהו: **והיה לכם הים הגדול.** למצר: **וגבול.** הנסין שבתוך הים אף הם מן הגבול והם איים, שקורין אישלי''ש [איים] :
@1220 **גבול צפון.** מצר צפון: **מן הים הגדול תתאו לכם הר ההר.** שהוא במקצוע צפונית מערבית. וראשו משפיע ונכנס לתוך הים ויש מרוחב הים לפנים המנו וחוצה המנו: **תתאו.** תשפעו לכם לנטות ממערב לצפון אל הר ההר: **תתאו.** לשון סבה, כמו (ד''ה ב' יב, יא) אל תא הרצים, (יחזקאל מ, י) ותאי השער היציע, שקורין אפינדי''ץ , שהוא מוסב ומשפע:
@1221 **מהר ההר.** תסבו ותלכו אל מצר הצפון לצד המזרח ותפגעו בלבא חמת, זו אנטוכיא: **תוצאות הגבול.** סופי הגבול. כל מקום שנאמר תוצאות הגבול, או המצר כלה שם לגמרי ואינו עובר להלן כלל, או משם מתפשט ומרחיב ויוצא לאחוריו להמשיך להלן באלכסון יותר מן הרוחב הראשון, ולענין רוחב המדה הראשון קראו תוצאות, ששם כלתה אותה מדה:
@1222 **והיו תוצאתיו חצר עינן.** הוא היה סוף המצר הצפוני. ונמצאת חצר עינן במקצוע צפונית מזרחית. ומשם והתאויתם לכם אל מצר המזרחי:
@1223 **והתאויתם.** לשון הסבה ונטיה כמו תתאו: **שפמה.** במצר המזרחי ומשם הרבלה:
@1224 **מקדם לעין.** שם מקום. והמצר הולך במזרחו נמצא העין לפנים מן המצר ומארץ ישראל הוא: **וירד הגבל.** כל שהגבול הולך מצפון לדרום הוא יורד והולך: **ומחה על כתף.** אל עבר: **ים כנרת קדמה.** שיהא ים כנרת תוך לגבול במערב, והגבול במזרח ים כנרת, ומשם יורד אל הירדן והירדן מושך ובא מן הצפון לדרום באלכסון נוטה לצד מזרח ומתקרב לצד ארץ כנען כנגד ים כנרת ומושך לצד מזרחה של ארץ ישראל כנגד ים כנרת עד שנופל בים המלח ומשם כולה הגבול בתוצאותיו אל ים המלח, שממנו התחלת מצר מקצוע דרומית מזרחית. הרי סובבת אותה לארבע רוחותיה:
@1228 **קדמה מזרחה.** אל פני העולם שהם במזרח, שרוח מזרחית קרויה פנים, ומערבית קרויה אחור, לפיכך דרום לימין וצפון לשמאל:
@1230 **אשר ינחלו לכם.** בשבילכם כל נשיא ונשיא אפטורפוס לשבטו ומחלק נחלת השבט למשפחות ולגברים ובורר לכל אחד ואחד חלק הגון. ומה שהם עושין יהיה עשוי כאלו עשאום שלוחים. ולא יתכן לפרש לכם זה ככל לכם שבמקרא, שאם כן היה לו לכתוב ינחילו לכם. ינחלו משמע שהם נוחלים לכם בשבילכם ובמקומכם, כמו (שמות יד, יד) ה' ילחם לכם:
@1231 **לנחל את הארץ.** שיהא נוחל וחולק אותה במקומכם:
@1242 **לנחל את בני ישראל.** שהם ינחילו אותה לכם למחלקותיה:
@1244 **ומגרש.** רוח מקום חלק חוץ לעיר סביב להיות לנוי לעיר, ואין רשאין לבנות שם בית ולא לנטוע כרם ולא לזרוע זריעה:
@1245 **ולכל חיתם.** ולכל צרכיהם:
@1246 **אלף אמה סביב.** ואחריו הוא אומר אלפים באמה, הא כיצד אלפים, הוא נותן להם סביב, ומהם אלף הפנימיים למגרש והחיצונים לשדות וכרמים:
@1253 **והקריתם.** אין הקריה אלא לשון הזמנה וכן הוא אומר (בראשית כז, כ) כי הקרה ה' אלהיך לפני:
@1254 **מגאל.** מפני גואל הדם שהוא קרוב לנרצח:
@1255 **שש ערי מקלט.** מגיד שאף על פי שהבדיל משה בחייו שלש ערים בעבר הירדן, לא היו קולטות עד שנבחרו שלש שנתן יהושע בארץ כנען:
@1256 **את שלש הערים** וגו' **.** אף על פי שבארץ כנען תשעה שבטים וכאן אינן אלא שנים וחצי, השוה מנין ערי מקלט שלהם משום דבגלעד נפישי רוצחים, דכתיב (הושע ו, ח) גלעד קרית פועלי און עקבה מדם:
@1258 **ואם בכלי ברזל הכהו.** אין זה מדבר בהורג בשוגג הסמוך לו, אלא בהורג במזיד. ובא ללמד, שההורג בכל דבר צריך שיהא בו שעור כדי להמית, שנאמר בכלם אשר ימות בו, דמתרגמינן דהיא כמסת דימות ביה, חוץ מן הברזל, שגלוי וידוע לפני הקדוש ברוך הוא שהברזל ממית בכל שהוא אפלו מחט, לפיכך לא נתנה בו תורה שעור לכתוב בו אשר ימות בו. ואם תאמר בהורג בשוגג הכתוב מדבר, הרי הוא אומר למטה או בכל אבן אשר ימות בה בלא ראות וגו' , למד על האמורים למעלה שבהורג במזיד הכתוב מדבר:
@1259 **באבן יד.** שיש בה מלא יד: **אשר ימות בה.** שיש בה שעור להמית, כתרגומו. לפי שנאמר (שמות כא, יח) והכה איש את רעהו באבן, ולא נתן בה שעור, יכול כל שהוא, לכך נאמר אשר ימות בה:
@1260 **או בכלי עץ יד.** לפי שנאמר וכי יכה איש את עבדו או את אמתו בשבט (שמות כא) , יכול כל שהוא, לכך נאמר בעץ אשר ימות בו, שיהא בו כדי להמית:
@1261 **בפגעו בו.** אפלו בתוך ערי מקלט:
@1262 **בצדיה.** כתרגומו, בכמנא. במארב:
@1264 **בפתע.** באונס. ותרגומו בתכיף, שהיה סמוך לו, ולא היה לו שהות להזהר עליו:
@1265 **או בכל אבן אשר ימות בה.** הכהו: **בלא ראות.** שלא ראהו: **ויפל עליו.** מכאן אמרו ההורג דרך ירידה גולה, דרך עליה אינו גולה:
@1267 **עד מות הכהן הגדול.** שהוא בא להשרות שכינה בישראל ולהאריך ימיהם, והרוצח בא לסלק את השכינה מישראל ומקצר את ימי החיים. אינו כדאי שיהא לפני כהן גדול. דבר אחר לפי שהיה לו לכהן גדול להתפלל שלא תארע תקלה זו לישראל בחייו: **אשר משח אתו בשמן הקדש.** לפי פשוטו מן המקראות הקצרים הוא, שלא פרש מי משחו, אלא כמו אשר משחו המושח אותו בשמן הקדש. ורבותינו דרשוהו במסכת מכות (יא, ב) לראיית דבר, ללמד שאם עד שלא נגמר דינו מת כהן גדול ומנו אחר תחתיו ולאחר מכאן נגמר דינו, חוזר במיתתו של שני, שנאמר אשר משח אתו, וכי הוא משחו לכהן או הכהן משח אותו, אלא להביא את הנמשח בימיו שמחזירו במיתתו:
@1269 **אין לו דם.** הרי הוא כהורג את המת שאין לו דם:
@1271 **בכל מושבתיכם.** למד שתהא סנהדרין קטנה נוהגת בחוצה לארץ כל זמן שנוהגת בארץ ישראל:
@1272 **כל מכה נפש** וגו' **.** הבא להרגו על שהכה את הנפש: **לפי עדים ירצח.** שיעידו שבמזיד ובהתראה הרגו:
@1273 **ולא תקחו כפר.** לא יפטר בממון:
@1274 **ולא תקחו כפר לנוס אל עיר מקלטו.** למי שנס אל עיר מקלטו שהרג בשוגג אינו נפטר מגלות בממון לתן כפר לשוב לשבת בארץ בטרם ימות הכהן: **לנוס.** כמו לנס, כמו (מיכה ב, ח) שובי מלחמה, ששבו מן המלחמה, וכן (צפניה ג, יח) נוגי ממועד, וכן (יהושע ה, ה) כי מלים היו, כאשר תאמר שוב על מי ששב כבר, ומול על מי שמל כבר, כן תאמר לנוס על מי שנס כבר, וקורהו נוס כלומר מברח. ואם תאמר לנוס לברוח, ותפרשהו לא תקחו כפר למי שיש לו לברוח לפטרו מן הגלות, לא ידעתי היאך יאמר לשוב לשבת בארץ, הרי עדין לא נס ומהיכן ישוב:
@1275 **ולא תחניפו.** ולא תרשיעו, כתרגומו ולא תחיבון:
@1276 **אשר אני שכן בתוכה.** שלא תשכינו אותי בטמאתה: **כי אני ה' שכן בתוך בני ישראל.** אף בזמן שהם טמאים שכינה ביניהם:
@1279 **ונוסף על נחלת המטה.** שהרי בנה יורשה והבן מתיחס על שבט אביו:
@1280 **ואם יהיה היובל.** מכאן היה רבי יהודה אומר עתיד היובל שיפסוק: **ואם יהיה היובל.** כלומר אין זו מכירה שחוזרת ביובל, שהירשה אינה חוזרת, ואפלו אם יהיה היובל לא תחזור הנחלה לשבטו, ונמצא שנוספה על נחלת המטה אשר תהיינה להם:
@1284 **וכל בת ירשת נחלה.** שלא היה בן לאביה:
@1287 **מחלה תרצה** וגו' **.** כאן מנאן לפי גדלתן זו מזו בשנים ונשאו כסדר תולדותן, ובכל המקרא מנאן לפי חכמתן ומגיד ששקולות זו כזו:

@1 **במדבר סיני וגו'**. רז''ל דרשו (במד''ר פ''א) הבנות יקרות בפסוק זה, ונשאר להעיר למה לא השוה ה' מדותיו יתברך בשיעור הדברים, כי כשהזכיר הודעת המקום הקדים מחברת הכללות שהוא מדבר סיני ואחר כך הזכיר פרט המקום ואמר **באהל מועד**, וכשהזכיר הודעת הזמן הקדים זכרון פרט הזמן ואמר **באחד לחודש השני** ואחר כך הזכיר מחברת כללות הזמן ואמר **בשנה השנית**:
@1 **ונראה** כי הכתוב אדרבא השכיל לדבר בשיעור שוה, והוא על דרך אומרם (ב''ר פס''ח) הנה מקום אתי שמקומו של הקדוש ברוך הוא הוא טפל לו, ולערך זה יהיה טפל כל המקום לגבי המקום אשר חונה שם האלהים, ומעתה מחברת הכללות הוא אהל מועד והמדבר הוא פרט טפל לו, ולהעירך הכתוב בכוונה זו סדר סמוך לזה מאמר **באחד לחודש** וגו' **בשנה השנית**, אם כן מאמר באהל מועד הוא מחברת הכללות ולזה נסדר באחרונה כסדר שנה השנית שנסדר אחר מאמר באחד לחדש, ותדע כמה הוא מופלג מקום אשר ה' שם ממה שמצינו שבב' אמות שבין בדי הארון עמדו רווחים ס' ריבוא של ישראל (ב''ר פ''ה), הרי שהגם שהוא לעין מועט הוא מרובה לצד השוכן בו ברוך הוא:
@2 **שאו את ראש וגו'**. צריך לדעת מספר זה למה. ורש''י ז''ל הביא דברי המדרש שאמרו כי כשבא להשרות שכינתו בתוכם חזר למנותם ע''כ, וזה לא יספיק ליישוב הפשט, כי היה לו למנותם קודם חודש ניסן לא אחר כך, גם בהפלגת זמן חודש ימים, ונראה לי בהקדים לחקור זאת, כי במספר שאחר העגל שהוא מספר שבפרשת פקודי באו לכלל חשבון ו' מאות אלף וג' אלפים וה' מאות ונ' שיש במספר זה נוסף על מספר יוצאי מצרים שלשת אלפים וה' מאות וחמישים בהמשך זמן ששה חדשים הגם שכילה בהם העגל בג' מיני מיתות, מגפה, חרב בני לוי, השקאת אפר העגל, ובמספר שלפנינו שהוא אחר ו' חדשים אחרים ממספר הב' רואני שלא הוסיפו על מספר הקודם לו אפילו אחד. והדבר כמעט זר למאוד שלא הוסיפו, שאיך יתכן שבהמשך זמן זה לא יבואו מהם לכלל עשרים, ומה גם שלא אירע להם חסרון ונוסף שהיו עסוקים במלאכת המשכן:
@2 **ויגדל** הקושיא לפי מה שאמרו בפסיקתא (זוטרתא) וזה לשונם ויהיו כל הפקודים וגו' ולהלן הוא אומר בקע וגו' לשש מאות אלף וגו' למדנו שכל זמן שהיו ישראל עסוקין במלאכת המשכן לא חסרה מהם נפש אחת ע''כ. דבריהם ז''ל לפי הנראה רחוקים, שהלא אדרבא בהשכיל על דבר אנו רואים שחסרו יותר ממה שחסרו במעשה העגל הגם שלא היו עסוקים במלאכת המשכן:
@2 **אכן** לפי מה שעלה בידינו שכל שבט לוי שוקלים שקלים (שקלים פ''א מ''ג) אין קושיא, כי במספר שבפרשת פקודי היו הלוים בכלל המספר אבל במספר שלפנינו לא נכנסו הלוים, ומעתה הרי שהוסיפו כל מספר הלוים, ולזה אמר בסמוך למספר **והלוים לא התפקדו בתוך בני ישראל**, ולא היה צריך לומר שהנני רואה שלא התפקדו במספר הקודם, והן אמת אם אמר הכתוב כאשר צוה ה' כמו שאמר הכתוב אחר פרשת הדגלים הייתי אומר כי בא להשמיענו שקיימו מאמר ה' שצוה שלא יפקדו אותם, וממה שלא אמר אלא והלוים לא התפקדו בתוכם הרי זה מראה באצבע כי נתכוון לומר אל תתמה על המספר שהוא בשוה למספר הקודם בלא תוספת והלוים לא התפקדו והרי לפניך היתרון:
@2 **ופירוש** דברי הפסיקתא יציץ וזרח, כי מה שמצינו חשבון עצום כזה ששוה במספר ב' לשלפנים זה יגיד כי הן הנה שהיו במספר הראשון ובששה חדשים שבין ב' המספרות לא נעדר מהם אחד והנוספין במספר מלאו חסרון מספר הלוים שהיו בכלל הראשון ולא בכלל מספר השני, ולזה נתחכם ה' לומר למשה לשאת את ראש בני ישראל ביום אחד לחודש הב' וגו' בכיוון שהיה זמן שהגיע המספר למספר הראשון לבד הלוים להעירך במה שאמר בפסיקתא שהמספר עצמו הא' היה כמספר הב' ולא מת א' ונכנם אחר במקומו, והטעם לצד שהיו עסוקים במלאכת המשכן על דרך (דברים ד') ואתם הדבקים בה' חיים כלכם, ונוכל לומר גם לדברי המדרש שהביא רש''י שכשבא להשרות שכינתו בתוכם וכו' שבחר בזמן זה לטעם הנזכר:
@3 **תפקדו אותם**. חזר לומר כן ולא הספיק במה שקדם לומר **שאו את ראש** וגו'. להעירך בכוונת אומרו **שאו** שיכוין על פי דבריהם ז''ל (ילקוט כאן) שאמרו שנתקנאו או''ה בישראל מה ראו להתקרב וכו' אמר להם הקדוש ברוך הוא הביאו לי ספר איקונין שלכם ונמצא כל אחד אינו יודע מאיזו משפחה הוא עד כאן. הרי כי יקפיד ה' על היחוס ויושפל כל החסר ספר איקונין, לזה כשבא ה' לצוות לפקוד בני ישראל קדם לומר **שאו** לשון נשיאות ורוממות למצוא לכל א' ספר איקונין מה שאין כן באו''ה, ואחר כך ביאר מה היא המעלה **מבן עשרים שנה** וגו' **תפקדו אותם**, ומעתה צריכה לגופה:
@18 **ואת כל העדה וגו' באחד לחודש**. יודיע הכתוב כי ביום עצמו נקהלו היהודים על הדבר, והדבר יגיד שכל אחד היה לו יחוסו אצלו בלא טורח הראיה והעדיות, גם שבו ביום הוכרו היחוסין של כולן, והוא אומרו **ויתילדו** סמוך למאמר באחד לחודש וגו':
@18 **ויתילדו וגו'**. כתב רש''י ז''ל הביאו ספר יחוסיהן ועידי חזקת לידתן כל אחד ואחד להתיחם על השבט. והשיג רמב''ן כי לא היו צריכין לכל זה עד כאן. ואולי כי הוצרכו לחזקת לידה למיחוש ממזר שמכיר אביו, והכרת ממזרתו תהיה מהלידה, וצריך להביא חזקת לידה פירוש שנולד בכשרות, וזולת זה יוכל הממזר לומר ספר יוחסין עד יעקב אשר הודיעתו אמו:
@20 **כל יוצא צבא**. אמר הכתוב כן בכל פרטי המספר, לומר שלא היה אחד מכל הבאים לכלל המספר שלא היה ראוי לצאת בצבא אלא כולן גבורי כח, והוא אומרו **כל** פירוש כל אחד מהם יוצא צבא. וזה נס שאינו באומות שאי אפשר שלא ימצא בכל המספרים שלהם אחד שאינו ראוי לצאת בצבא:
@47 **והלוים לא התפקדו וגו'**. פירשתי למעלה (ב') כוונתו במאמר זה:
@49 **לא תפקוד וגו' לא תשא**. פירוש בין על ידי כופר נפש בין שלא על ידי כופר נפש. ועיין מה שפירשתי בפרשת כי תשא:
@49 **עוד** יכוין לומר שהגם שיבא לידך מספר של נשיאות ומעלה שהוא מספר הדגלים אף על פי כן **לא תשא**:
@57 **והחונים וגו'**. אמד **והחונים** בתוספת וא''ו, לצד שקדם מצות חנייה סביב למשכן הוסיף להתנות סדרן:
@87 **והלוים לא התפקדו וגו' כאשר וגו'**. פירוש הגם שמספר זה מספר הכבוד והמעלה שעשו כסדר המלאכים שירדו עם השכינה בהר סיני כמאמרם ז''ל (במד''ר פנ:) אף על פי כן **לא** וגו' לצד כי מצות ה' היא לא תפקוד ולא תשא:
@89 **תולדות אהרן ומשה וגו'**. ולא מנה אלא תולדות אהרן, לומר כי בני אהרן יחשבו על משה לצד שהוא התפלל בעדם וחיו דכתיב (דברים ט) ובאהרן התאנף ה' להשמידו וגו', ואמרו ז''ל (ויק''ר פ''ז) שהועילה תפלתו להציל אלעזר ואיתמר, ואומרו **ביום דבר** וגו' לומר זמן שהתפלל עליהם, וכלל עוד בזה סיבת קבלת תפלתו שהוא לצד שדבר ה' אליו בהר סיני ונעשה ציר נאמן לה' בקבלת התורה:
@91 **אלה שמות וגו' המשוחים וגו'**. חזר לומר **אלה שמות** פעם ב' ולא הספיק במה שאמר בפעם א' אלה שמות וגו' ולגמור אומר **המשוחים** וגו', נתכוין למעט שלא נמשחו אלא אלו, ולזה דקדק לומר **אלה** למעט זולתם, ומפסוק ראשון לא נשמע זה לצד שאמר ואלה שלא תשמע שפסל עם בני ישראל שקדמו להם והבן:
@103 **כל זכר מבן חודש וגו'**. טעם מבן חודש, כפי זמן אשר באו המה תחתיהם שהם הבכורות, ולמה יתן הבכור פדיונו כיון שיש לו בן לוי במקומו, ואם תאמר למה אין הלוים פודים כמו כן מאז והלאה את הבכורות, ולא יצטרכו ישראל פדיון לבכוריהם, יש לומר כי אותם הלוים כבר נכנסו תחת הבכורות שהיו אז ואת בניהם הקים ה' תחת אבותיהם שהרי נתקדשו הם ובניהם עד עולם. ואולי כי לזה כפל ה' במאמרו במה שכתב בפסוק **ואני הנה לקחתי את הלוים** וגו' **והיו לי הלוים** פירוש הוחלטו הם ובני בניהם, מעתה אין לוי שיפדה בכור ישראל הבא אחר כן פטר רחם:
@127 **כל פקודי הלוים וגו'**. רמב''ן ז''ל תמה בדבר שיש לתמוה בו, כי הלוים הן הנה ידידי ה' וקרוביו ואשר לא חטאו בעגל ולא נגפו ולא הורגו ולא הושקו ואיך נתמעטו כל כך מכל השבטים שאינם מגיעים במספרם מבן חודש לחצי שבט הקטן שבישראל, ולכשתעמוד על מספרם מבן כ' לא יגיע לשליש ולרביע, וראיתי שיישב בשני דרכים, האחד הוא לצד שהריבוי בא מצד העינוי דכתיב (שמות א) וכאשר יענו אותו כן ירבה וגו', ודרך ב' מטעם כעסו של יעקב אביגו עליו השלום. ובעיני טעם הב' רחוק, כי לא נמצא רושם המעטת הזרע בכעס אביהם עליו השלום, ועוד תמצא במספר הבא בדברי הימים (א' כ''ג) היו הלוים שמנה ושלשים אלף מבן שלשים שנה עד בן חמשים שנה, ובמספרם בפרשת נשא באו לכלל חשבון שמונת אלפים וה' מאות ושמנים נמצאו שהוסיפו ד' חלקים בקירוב על מספר זה, ובמספר בני ישראל הבא שם לא באו לכפל מספר האמור כאן, ובאומד מספר זה לכשיהיו נמנים מבן כ' עד בן מאה ומעלה כדרך שנמנים ישראל יכול להיות מספרם כגדול שבטי ישראל ומעלה ואיה כעם אביהם:
@127 **וטעם** הא' של העינוי הוא טעם נכון אבל לא יוצדק לפי מאמר חז''ל (ב''ר פ ע''ט) שאמרו לא מת יעקב עד שהגיעו ישראל לכלל מספר ס' ריבוא, ובהכרח ליישב הכתובים לפי דבריהם ז''ל כי אומרו כן ירבה פירוש כמו כן בשיעור הראשון ירבה ולא היה מתמעט הגם שהיו הורגים מהם ומענים אותם היה כח בישראל לפרות ולרבות כמשפט הראשון למלאות החסר, ומה שאמר הכתוב (שמות שם) ובני ישראל פרו וגו' ויקוצו מפני וגו', לצד כי בימי יעקב היו קטני קטנים ולא היו עושים רושם בעיר וכשגדלו עשו פירסום, ומעתה הריבוי היה קודם העינוי ולמה לא יהיה כן לשבט לוי, ואין לומר שהיו כמו כן רבים כשאר השבטים בעת פטירת אביהם ונתמעטו אחר כך ולצד שלא היה בהם העינוי לא חזרו להתרבות, כי גם על זה דן אנכי למה יתמעטו מברכה ראשונה, ורז''ל אמרו (במד''ר פ''ה) שהיה הארון מכלה בהם, זה היה אחר מינוי עבודת הלוים:
@127 **והנכון** בעיני הוא כי שבט לוי מעשה אחד להם כמעשה עמרם אשר שלח את אשתו בשביל גזירת הבן הילוד, והטעם לצד שהיו מעונגים ולא נשתעבדו לא נמס לבבם כל כך לראות נטעיהם מושלכים ביאור כמעשה איש ישראל אשר מצד השעבוד ועול העבודה הוזל והוקל בעיניהם ובלבם לראות ילדיהם מושלכים ביאור, גם שהיו מזלזלים בעצמן לילד ולעזוב בשדות ובמחילות הארץ אשר אין אדם נכבד שנפשו מכובדת עליו כשבט לוי עושה כן, וזה לך האות כי עמרם שלח את אשתו, ולא הוצרך הכתוב להודיע את הדבר שגם בעמרם לא הגיד הכתוב הענין אלא מהשכלת הענין נודע, וללמד על כל שבטו יצא, וזו היא סיבת מיעוטם כי אם אין גדיים אין תיישים, והגם שמצינו שעמרם החזיר גרושתו, אין ללמוד ממנו שכולם החזירו כי הוא זה אשר בא אליו הדבר בנבואה כמאמר חז''ל באגדה (שמו''ר פ''א סוטה יב) ובדברי הזוהר הקדוש (ח''ב יא:) בפסוק וילך איש וגו', וכמו שאמרו ג''כ (שמו''ר פ''א) בפסוק ותתצב אחותו וגו' שהלכה לראות מה יהיה בנבואתה. ואם תאמר למה שבט בן תורה יעשה מיעוט פריה ורביה, אולי שדנו בה למען לא ניגע לריק ולא נלד לבהלה, וכיוצא בזה מצינו שאמרו (תענית יא.) שאסור לשמש מטתו בשנת רעבון הגם שיש מניעת פריה ורביה, ודנו כמו כן לצד כלוי הבנים הזכרים נמנעו כל עיקר, ומעתה אדרבא עשה ה' עמהם נם שנשארו מהם מספר זה, ולזה אחר זמן שהיו עסוקים גם הם בפריה ורביה פרו וישרצו וגו' יותר משאר השבטים:
@129 **ואת בהמת הלוים וגו'**. פירוש הבהמות שהם חייבים בפדיון שהם פטרי חמורים שאמר הכתוב (שמות יג) ופטר חמור תפדה בשה, ודוקא פטר חמור אבל בכורות הטהורות לא, כי התמימין אינם בני פדיון, ובעלי מומין משנעשו בני מומין רגע אחד ברשות [הבעלים], (הבכור) זכה בו והרי הוא אצלו כחולין ומה מקום לפדיון:
@133 **והיו לי הלוים אני ה'**. הכונה במאמר **אני ה'**, לומר שהגם שאמרו רבותינו ז''ל (ילקוט שס''ד) עתידה עבודה שתחזור לבכורות, לא ירדו הלוים מהיות לה', והוא אומרו **והיו לי אני ה'** כשם ששמי לעולם ועד כמו כן יהיו לי הלוים:
@135 **ולקחת חמשת וגו'**. צריך לדעת למה אמר ולקחת בוא''ו כיון שמאמר זה הוא גזרת מאמר ואת **פדויי השלשה** וגו', ואולי כי בזה העיר כוונת כתוב הקודם לזה ואת פדויי השלשה וגו' שגזרתו הוא מבכור בני ישראל פירוש שיקח פדיון בכורות העודפים על הלוים מאת הבכורות ולא מהלוים, שתעלה על דעתך לומר שכדרך שפדו בבהמת הלוים בהמתם כמו כן יפדו הנותרים מהם וקל וחומר הוא, תלמוד לומר מבכור בני ישראל פירוש יהיה הפדיון, וכן אמר במעשה **ויקח משה** וגו' **מאת בכור בני ישראל לקח את הכסף**, והוסיף לומר מצוה שניה שיהיה הפדיון ה' שקלים, והוא אומרו ולקחת בתוספת וא''ו, וחזר לומר **תקח**, שיקח השקל בשקל הקודש שהוא כפול, ושדבר זה מעכב בפדיון:
@139 **ויתן משה וגו' כאשר צוה ה' וגו'**. קשה אחר שאמר הכתוב **על פי ה'** מה מקום לומר **כאשר צוה ה'** וגו'. ונראה כי לצד שיש במעשה זה הטבה לאהרן אחיו ובניו, ויש מקום לומר כי היה למשה נחת רוח להטיב לאחיו, לזה בא הכתוב ושלל בחינת מחשבה זו ממשה שלא חשב במעשה זה רצון הנתינה לאחיו אלא לקיים מאמר ה' היה לו החפץ במעשהו:
@141 **נשא את ראש בני קהת**. לפי מה שהעלינו בפרשת כי תשא כי על ידי נתינת הכופר הוא נשיאת ראש להם ולזה אמר הכתוב במספרם כי תשא מה שאין כן הלוים שלא נתנו כופר במספרם אמר פקוד את בני לוי, אם כן למה שינה הכתוב את לשונו בלוים עצמן וחזר לומר **נשא** ולא פקוד. ונראה כי לצד שנתן ה' להם עבודה פנימית לשאת ארון ושלחן לזה יחס להם לשון נשיאות ראש בערך גרשון ומררי שיהיו הם מעולים מהם, והגם שגרשון הוא בכור לוי, קהת בחר לו יה כי ממנו יצא אור לעולם משה ואהרן, ושורת הדין שענף זה ישא ארון התורה אשר שם משה שיצא מקהת, ודקדק לומר **מתו** ך **בני לוי**, מטעם שאמרנו לצד שהוא אמצעי בין גרשון ובין מררי ויתיחם אליו תוך:
@142 **לעשות מלאכה**. שינה מהאמור בעבודת בני גרשון ובני מררי לעבוד עבודה ואמר **לעשות מלאכה**, העיר בזה שאין בכללות מעשה בני קהת עבודה, לצד שהארון הוא אדרבה נושא את נושאיו (במד''ר פ''ד) ואין עושין בו אלא מלאכה. עוד נראה כי לצד שיש להם לעשות סדר נכון במשאם כשנושאים בכתף וכיוון ההליכה לצד כבוד ארון אלהים כנושא אדונו על כתפו, לזה קרא עבודתם מלאכה, מה שאין כן עבודת בני גרשון ובני מררי:
@158 **וזאת עשו וגו'**. פירוש המעשה הוא שלא יהיו בני קהת ברשות עצמן לשאת כחפצם, שאז לצד חיבת עבודת הקודש הכל רצים לעבוד ונמצאו שוגגים בדבר, אלא ישימו אותם אהרן ובניו איש איש וגו' ובזה כל אחד מכיר מקומו, והוא אומרו **ושמו אותם איש** וגו', והוא אומרו **ולא יבואו לראות** פירוש כדי שלא יבואו לידי ראיה כבלע את הקודש, ופירוש **ושמו** הוא שלא יועיל בהכרת כל אחד מקומו לבד אלא לא יכנס לשים ידו לשאת עד שיאמר לו אהרן ובניו פלוני שים ידך במקום פלוני לישא וכן על זה הדרך, והוא אומרו **ושמו אותם**, ולזה תמצא במצות בני גרשון הגם שאמר הכתוב על פי אהרן ובניו תהיה כל עבודת וגו' לא אמר ושמו וגו':
@158 **וחיו ולא ימותו**. פירוש כי בהתעסקם בארון שבו התורה שהוא מקור החיים יאריכו ימים, ולחשש ההיזק שיכול להיות מהנגיעה והראות בו אמר **ולא ימותו**:
@158 **חסלת פרשת במדבר**
@160 (כא~כב) **וידבר ה' וגו' נשא**. הוצרך לומר **וידבר** פעם ב' ולא הספיק במה שאמר וידבר ה' במספר בני קהת הקודם שבפרשת במדבר, לצד שבא לומר ענין אחר לבד המספר, והוא שינשא וירומם בני גרשון לערך בני מררי, וענין זה הוא דבר בפני עצמו שאין נשיאות זה בגדר נשיאות בני קהת שהם נושאי הארון, לזה קבע לו דיבור בפני עצמו, ולזה כשצוה על מספר בני מררי אמר בני מררי וגו' תפקוד לא קבע להם דיבור בפני עצמו שאין להם מעלה אלא מנין ממה שאמר תפקוד ולא תשא:
@160 **אל משה וגו'**. ולהלן במספר אמר **ואל אהרן**, לצד כי שם בא הציווי לאהרן כדי שיעשה סדר האמור בענין משאם של בני קהת דכתיב ושמו אותם וגו' ולא ימותו, לזה אמר **ואל אהרן**, מה שאין צורך לזה במשא בני גרשון:
@162 **תפקוד אותם**. כפל לומר **תפקוד**, פרשתי בפרשת במדבר בענין בני קהת:
@162 **לצבא צבא וגו'**. ובבני קהת אמר לצבא לבד, כי הם היו נושאים כלי הקודש הפנימיים לזה אמר לצבא, מה שאין כן מה שלפנינו הם צובאים צבא הצובא קודש שהם היריעות וגו' והקרשים וגו' שהם צבא הקודש לזה אמר **לצבוא צבא**, מעתה הם צובאים הצבא:
@169 **לעבוד את עבודת אהל מועד**. ולהלן בבני גרשון אומר עבודה באהל מועד, לצד כי עבודת בני גרשון היא באהל מועד עצמו שנושאים יריעות המשכן ואהל מועד מכסהו וגו', מה שאין כן בני מררי שעבודתם היא הקרשים והאדנים וגו' שהם עבודת אהל מועד שנושאים אהל מועד, ולזה אמר **לעבוד את** וגו' **הקרשים** וגו' שהם עבודת אהל מועד, ולזה לא חש לומר לצבא לבד, שהרי פירש הכתוב דבריו, מה שאין כן בעבודת בני גרשון להעירך בהפרש שבין עבודתם לעבודת בני קהת לצד שבשניהם אמר עבודה באהל ואין היכר בדבריו להפרש שבין שניהם לזה כתב שינוי לצבוא צבא משונה ממה שכתב בבני קהת לצבא, ולצד הפרש שבין בני גרשון לבני מררי העירך בשינוי אחר כמו שכתבנו:
@173 **ויפקוד משה ואהרז ונשיאי העדה**. טעם שלשתם, משה שליח ה', אהרן הנמסרים לו דכתיב (ג' ט') נתונים נתונים המה לו, נשיאי ישראל המוסרים אותם במקומם לעבוד דכתיב בפרשת במדבר (שם ז') ושמרו את משמרתו ואת משמרת כל העדה וגו', ומה שלא אמר כן במספר הלוים מבן חדש, לצד כי מספר ההוא היה על פי ה' לצד שהיה המספר גם למה שבעריסה, ואמרו ז''ל (במד''ר פ''ג) שבת קול היתה אומרת באהל זה יש כך וכך, לזה לא הזכיר אלא משה נביא ה':
@175 **אלפים שבע מאות**. ולא אמר ושבע מאות כדרך שאמר בבני גרשון ושש מאות ושלשים, ובבני מררי ומאתים, וחמש מאות ושמונים, אולי רמז בחסרון ו' לקרח ואותם שמתו עמו שהיו מבני קהת, או אולי כי מספר השבע מאות משונה בהדרגה ממספר האלפים מטעם מעשה קרח, לזה לא אמר ושבע מאות להוסיף על ענין ראשון להשוותם יחד, והגם שלא נתפרסם בתורה במעשה ההוא אלא קרח, אפשר שענף של קרח נטו קצת אחריו, או לצד שלא מיחו בו אחיו וקרוביו:
@188 **על פי ה' פקד וגו'**. פירוש המינוי שמינה אותם בני קהת על דבר זה ובני גרשון על דבר זה וגו' היו כל הפקידות על פי ה' ואומרו **ביד משה** פירוש כל המינויים משה מינה אותם לא שצוה לאהרן למנות, ואחר שפקד אותם משה על פי מעשיו היה מתנהג אהרן לשום איש איש על עבודתו, ואומרו ופקודיו פירוש פקודיו שמינה אהרן ובניו על שבט לוי כאמור למעלה גם הוא אשר צוה ה' את משה:
@190 **צו את בני ישראל וישלחו וגו'**. טעם סמיכות פרשה זו לשלפניה, לצד שצוה ה' על הרחקת הלוים מדברים המקודשים ומינה עליהם הכהנים כאמור בסמוך, הטיל גם על ישראל הרחקת את שאינם ראוים ליכנס למחניהם הקדוש:
@191 **אשר אני שוכן**. פירוש דוקא כל עוד שהוא שוכן, אבל הוגללו הפרוכות מותרים מצורעים ליכנס למחנות (מנחות צה.):
@194 **איש וגו' כי יעשו מכל וגו'**. אמר **למעול** ולא אמר ומעלו מעל, יתבאר על פי דבריהם ז''ל (ספרי פסיקתא ב' ב''ק קי.) שאמרו שהכתוב מדבר במשקר בממון חברו ונשבע לו לשקר, והגם שכבר נאמר הדבר בפרשת ויקרא, חזר ונשנה לפרטי הדינים שנתחדשו בו, כפי זה יעיר הכתוב כי משעת מעשה החטא שהוא הגזל וכפירת ממון יחשוב הוא למעול מעל בה' לישבע בשמו כשיתבעוהו לדין, שאם לא כן הרי הוא בהשבון, והוא אומרו **כי יעשו מכל חטאת האדם** שהוא גזילת ממון חברו משעת מעשה הנה הוא מסכים למעול מעל בה':
@194 **ואשמה הנפש ההוא**. לצד שהוא חטא בשבועה בה' יפעיל הגרעון בנפש, ושינה ה' לומר לשון יחיד וכל מה שלפניו ומה שלאחריו לשון רבים, מלפניו אמר **כי יעשו** וגו', מלאחריו **והתודו**, ותמצא שאמרו בגמרא כי כשירגישך הכתוב בכגון זה הוא הרגש גדול, ועיין מה שכתבנו מזה בפרשת ויקרא (ז' כ''א). גם דקדק לומר תיבת **ההוא** ללא צורך, יעורר הכתוב שהפגם הלז יעשה רושם למקור נפשות עם בני ישראל שתקרא נפש, וכדי שלא תבין שעל המועל הוא מדבר לזה אמר **ההוא** ולא אמר ואשמה נפשו, ועיין מה שכתוב בזוהר (אחרי ס''ז.) בפירוש פסוק נפשי אויתיך בלילה בדיוק נכון:
@195 **והשיב את אשמו**. שינה לדבר לשון יחיד הגם שהתחיל לדבר לשון רבים והתודו, לצד שהוידוי שוים הם בו, מה שאין כן האשם אינו בהשואה, לצד שהוא בעולה ויורד כאמור בפרשת ויקרא, וגמר הכתוב לדבר בשיעור זה לשון יחיד, כי אין צורך לשנות לכתוב בענין אחר:
@197 **וכל תרומה וגו' לו יהיה וגו'**. צריך לדעת למה כפל הכתוב ענין אחד ג' פעמים **וכל תרומה** וגו' לו יהיה, **ואיש את קדשיו** וגו', **איש אשר יתן** וגו'. עוד למה כפל לומר ג' פעמים **לו יהיה**, ורז''ל בספרי פירשו לו יהיה בא לתת הבכורים שנקראו ראשית כתרומה המובאים בית ה' שיהיו לו לכהן נתונים. לו יהיו שאמר בפסוק ב' לומר שאם הכהן הקריב קדשיו אפילו במשמרה שאינה שלו הרי הם שלו, ואומרו ואשר יתן לכהן לו יהיה אם נתן לו פדיון בכור בנו ומת אחר ל' יום לכהן לו יהיה ולא יחזירם, והרבה דרשות כיוצא בזה, אבל צריכין אנו ליישב המקרא על פי פשוטו. ונראה לפדש ג' כתובים הבאים כאחד שהם מלמדים כללות כ''ד מתנות אשר חלק ה' לכהנים, וכתבם רמב''ם בפרק א' מהלכות בכורים וזה לשונו כ''ד מתנות שנתן לכהנים נחלקים לה' חלקים, שהם ג'. הא' הם קדשים שזוכים מן המקדש ואלו הם. בשר חטאת. בשר אשם. שלמי ציבור. מותר העומר. שירי מנחות. שתי הלחם. לחם הפנים. שמן מצורע. עורות קדשים. חזה ושוק של שלמים. המורם מן התודה. המורם מאיל נזיר. בכור בהמה טהורה. והבכורים. הרי אלו י''ד מתנות שכולן צריכין הבעלים להביאם וליתנם לכהן וכולן קדש. חלוקה ב' הם התרומה. ותרומת מעשר. והחלה. והג' הם המתנות. וראשית הגז. שדה אחוזה. פדיון הבן. פדיון פטר חמור. גזל הגר. והחרמים. שהם חולין ועל הכהן לחזר אחריהם עד כאן:
@197 **ואלה** הם דברי הכתובים, כנגד חלוקה ראשונה שהם י''ד מתנות שיש בהם ב' הדרגות שהם קודש וצריכין ישראל להביאם וליתנם לכהן אמר **וכל תרומה לכל קדשי** בני ישראל הרי הזכיר עליהם שם קודש, אשר יקריבו לה' הרי הזכיר הבאתם שהם יקריבו אותם למקום המקודש. וכנגד חלוקה ב' שהם תרומה ותרומת מעשר וחלה אמר **ואיש את קדשיו** לו יהיו, הזכיר לשון הקדש לומר כי מדבר במתנות המקודשים, ולא הזכיר בהם הקרבה כי הכהן יחזר אחריהם. וכנגד ז' מתנות אמר **איש אשר יתן לכהן** לא הזכיר שם קדושה לצד שהם חולין גמורים, ודקדק לומר **אשר יתן** שאין לכהן זכות בהם אלא משעת נתינה כדין המתנות עד שיגיע ליד המקבל, ועיין מה שכתבתי בהלכות. מתנות כהונה (פרי תואר סי' ס''א), ואמר **לו יהיה** שאין הכהן יכול למאן שלא ליקחם כאמור בדבריהם (יו''ד ש''ו ד'). ומעתה יש טעם נכון במה שחלקם הכתוב לג' הדרגות לומר על כל אחת ואחת מג' חלוקות לו יהיה, שצריך לקחת כל הבא לו מהם, ולא היה נשמע אם היה אומר על חלוקה אחת מהם לבד:
@200 **דבר וגו' ואמרת וגו' איש איש וגו'**. כפל לומר **דבר ואמרת**, גם שינה את לשונו, גם כפל לומר **איש איש**, לצד שיש ב' הדרגות בסוטות א' נקיה ואחת טמאה, הטמאה תצבה בטנה ותפול ירכה וגו', והטהורה משבחת ונזרעה זרע, לזה אמר דיבור ואמירה, דיבור לטמאה, ואמירה רכה לטהורה אשר יקנא לה בעלה, כי ה' יתמוך לבה ביעודים הנאמרים אם לא נטמאה האשה, ולטעם זה עצמו כפל לומר איש איש, והוא על דרך אומרם ז''ל (מגילה יב:) באומרו ומעלה בו מעל אם מעלה בו מעל איהו בקרי וכו', ומעתה יאמר אדם אם קינא לאשתו ויודע הוא בעצמו שאין בו מעל תהיה בדיקתה אצלו ממעשיו במקום השקאה ויאמר להחזיקה בטהרה אפילו אחר קינוי וסתירה, לזה אמר **איש איש** בין היודע בעצמו כי הוא איש טהור בין אשר לא טהור צריך להביאה אל הכהן:
@200 **ואולי** כי לזה כיון הכתוב בכפל **דבר ואמרת**, בין למי שחושב שלא להביא מטעם שיודע בעצמו שהוא טהור, גם כדי שלא יריע חזקתו, ואומרו **ואמרת** אמירה רכה להחפץ בדבר, או לכל אחד ואחד ישנו בדיבור קשה ואמירה רכה, מי שיש בו מעל הגם שיש לו דיבור קשה כי תגלה רעתו בקהל אף על פי כן יש לו טובה להרחיקו ממכשול לבל ישכב עם טמאה בתמידות, ולמי שהוא נקי יש לו דיבור קשה להכריחו לבזות באשתו, ויש לו אמירה הסועדת הלב שתנקה האשה ונזרעה זרע וגו':
@203 **והביא האיש את אשתו וגו'**. עד סוף כל הענין. יש להעיר בענין. א' מה היא כוונתו במאמר **מנחת זכרון מזכרת עון**, למה הוצרך לזכרון, ומה גם שהמעשה אינו רחוק להצריך זכרון, גם למה יתיחס למנחת שעורים שהיא מזכרת עון והלא רואה אני שהוא קרבן מנחה חדשה לישראל ממחרת הפסח. עוד צריך לדעת הכוונה במעשה זה של מים קדושים, מה מעשיהם של מים, ולמה נקראו קדושים, ורז''ל אמרו (סוטה ט''ו:
@203 ספרי) שנתכוין לומר שקדשו בכלי שהוא הכיור, גם לזה יש להשכיל למה יצו ה' על דבר זה, גם מה הוא פעולת הספר להשקותה בו, בשלמא מה שעשה משה בעגל שהשקה את ישראל הוא על דרך תיסרך רעתך (ירמיה ב) גם למה מן המקדש, גם דקדק שיהיה מהמזומן במקדש (סוטה שם) ולא יחפור נפלאים ממני הדברים, גם אומרו **ונתן אל המים** ואמרו ז''ל (שם) שצריך שיהיה העפר צף על פני המים, ורבנן סוברים שאם הקדים העפר למים פסול, מה מעכב דבר זה, ורואני שלא הזכיר הכתוב במצוה זו חוקה לסתום פי שואל לאמר לא תשאל, גם אומרו **מי המרים** לא ידעתי למה יקרא להם מרים, ורז''ל בספרי אמרו מרים נהפכים המים להיות מרים, דבר אחר על שם סופן ממרין את הגוף, ובגמרא (שם כ.) אמר אבוה דשמואל צריך שיתן דבר מר לתוך המים מאי טעמא דכתיב המרים שמרים כבר עד כאן. והדברים תמוהים למה סתם ה' הדברים במצוה זו, נוסף על תמיהת הדבר בכללותו:
@203 **ואפשר** לפרש הענין על פי מה שקדם לנו מידיעה בפנימיות התורה, הלא השמעתיך בפרשת בראשית (ב) בפסוק ויכלו השמים וגו' ויכל אלהים וגו' כי כל נברא והווה תכסוף ותכל תאותו להדבק אל האלהים חיים ברוך הוא, והרגש תיאבון זה ישנו גם בבלתי נועע כל אחד כפי שיעור הרוחניות אשר הטביע בו הבורא כפי מה שצריך לקיומו ולתת שבח לבוראו כאומרו (משלי טז) כל פעל ה' למענהו. עוד מצינו לרז''ל שאמרו (ב''ד פ''ה) טעם שנקראו מים בוכים לצד שה' פלג המים חציים למעלה וחציים נשארו למטה מתחת ליבשה, המים שנשארו למטה הם בוכים ומתאנחים על שלא זכו להתקרב לאלהים חיים בחצי העליון, כי הוא זה כוסף הנבראים יחד ותקותם:
@203 **עוד** הן הראנו ה' את אשר יחפוץ לקבוע דירה בתחתונים מימי אדם, ובחטאו נתקללה האדמה וגבה כסא המלוכה מקור הברכה מן העולם, (ב''ר פי''ט) עד עת בוא דברו ביום מתן תורה ויחשוק למעשה ידיו לדור בתחתונים, וזה לך האות מאמרו במדבר לבני ישראל לעשות לו מקדש, ולא המתין עד בואם אל ארץ נושבת שהיה נשאר זמן מועט אם לא היה מעשה המרגלים, וכשהתעיבו עול אפילו אחר שירדה שכינה וישכון כבודו שנים רבות סלק ה' שכינתו ושב למקומו הראשון שמים לרום, ומעתה זולת החטאים אשד יסובבו תהיה דירת אלהים חיים בתחתונים, ובזה ומחה ה' דמעת המים הבוכים ויוסר חרפת הארץ וישמחו המים ותגל הארץ אשר אררה ה' ורחק ממנה דוד עולם והנה עתה עת דודים, ואם יסובבו החטאים ישוב הדבר לכמות שהיה וירום הכסא, ועל זה ידוו הדווים לקול תתו מים, וצריך להעיר אוזן בלימודים אלו כי הטבת ישראל כשעמדו על הר סיני והכשרתם היה גם כן ראוי להשרות שכינתו יתברך בארץ ומלאה הארץ דעה ודירת ה' בתחתונים כבעליונים ויתעלה מקומנו זה, כי המעלה והירידה תלויה בקרבתם לפני ה':
@203 **ותמצא** שאמרו ז''ל (שמו''ר פמ''א) חירות ממלאך המות וכו' חירות מיצר הרע, ועל ידי עון העגל חזר הכיעור לכמות שהיה והוציא ראשו השטן ולא הועיל הטבתם של ישראל אלא למקום מוגבל תוך מחניהם, אבל כללות העולם נשמ''ו ביום זעם וחזר קב המות לעולם, מה שאין כן בזמן המקווה אשר יאבד כל בחינת הרע כאומרו (זכרי' יג) ואת רוח הטומאה אעביר מן הארץ שאז ארצינו תקרא ארץ החיים כי בלע המות לנצח:
@203 **ושמור** לך הדברים ועל פיהם נעלה במסילת כוונת הענין על נכון, כי יצו ה' בקנאות איש אשתו כי יבדקנה במעשה זה שיביאנה אל מקום אשר שם חונה האלהים, וכבר העירותיך כי למקום ההוא יקרא ארץ העליונה לצד ששכנה שם שכינה, ואינה בכלל ארור אשר אררה ה', גם מים אשר שם לא תרד עיניהם דמעה, כי למה יבכו ולמה ירע לבבם, וצוה ה' שיקח מהמים ההם קדושים, יקראו קדושים בקרבתם לפני ה' קדוש ונורא שמו, ובזה העירך מעשה המים, ואין דברי סותרים חס ושלום דברי רבותינו שאמרו שהיו מקודשים בכיור, אלא ממה שדבר ה' בדרך זה נתכוין לדברי גם כן אלהים חיים, גם צוה לקחת מן העפר המקדש דוקא לצד שהוא קרוב לקדוש ועליון ברוך הוא, וצוה שלא יחפור בדקר אלא מן העפר המוכן לפני ה' בלא הפסק בנין כמאמרם ז''ל (סוטה טו:) לצד היותם יותר קרובים ומרגישים בהשראת שכינה בהם, מה שהרגש זה אינו בעפר שהוא חוץ למקדש כי לא טָעַם טַעַם זה עד הנה לעשות את אשר חפץ ה' עשות:
@203 **וצוה** ה' שיתן המים תחילה והעפר למעלה, הטעם כסדר אשר המה בעולם, ותמצא שחכמים שאמרו שאם הקדים העפר לא עשה כלום אמרו אם היו מעורבים כשרים, והוא הענין עצמו שהם סדורים מים ועפר, כי יש חלק שהמים למטה והעפר למעלה ויש חלק שהמים אצל העפר אבל עפר למטה אין דוגמא זו בסדר מים החיים, ולר''ש שאמר שם (טז:) אפילו עפר למטה סובר שאין להקפיד כי יש מים למעלה מהעפר ודי שיתקדשו המים בכלי וזהו חיותם להרגיש בהרגש הצריך לענין:
@203 **וצוה** ה' לכתוב פרשת סוטה באזכרות שבה ומוחקים כל הכתב במים ובעפר ההוא, והטעם לתת כח בהם לעשות מעשה אשר יחפצו עשות, וצוה עוד שיקריב מנחה מהשעורים, הטעם דוגמא למנחה פחותה שהביא קין בתחלת העולם, וזה נסבב מחטא אדם וחוה, והוא הזכרת עון אשר גרם בכי למים וקללה לאדמה, והוא מאמר **מנחת זכרון מזכרת עון**, ואז ישקה האשה המים, והנה בבוא המים ההם במעי האשה במיחוי השם בתוכו אם האשה טמאה הנה השם ההוא על ידי המנחה שמזכרת עון יזכור עון הקודם וירגישו המים ובזה יהיו מרים כי יזכרו יגונם ובכיתם וה' מחה את דמעתם, והנה האשה הטמאה תסובב מרתם ובאו בה המים המרים למרים יחתכו מעיה ויעשו בה נקמה כי זאת האשה הגורמת בכיתם, ובכח השם הנתון בהם ינקמו נקמתם ממנה, והיודע חטא חוה בזוהמת נחש ידע כי זה הוא עון הראשון אשר העלה שכינת אור עליון מעולם זה התחתון, וכפי זה האם ימצא איש את אויבו וישלחנו, ויקיימו בה הבא להרגך השכם להורגו, ויעשו נקמה בה בין המים בין העפר שלשניהם יש גרם רעה, והגם שלא הזכיר הכתוב אלא מים יש בו גם העפר:
@216 **ואם לא נטמאה וגו' וטהורה וגו'**. כפל לומר וטהורה, לצד שבא לומר כי מלבד שתנקה האשה מהמים ולא ישחיתוה עוד לה ונקתה ונזרעה זרע, לזה התנה **וטהורה** פירוש לא נטמאת בנתינת שכיבתו של איש מבלעדי אישה, **וטהורה** מדבר מגונה שהוא מעשה הנואפים הקודמים לביאה חשק הזולת וחיבוק ונישוק ודומה לו, אז הוא שיטיבו לה המים ככל הכתוב, אבל אם לא נטמאה אבל לא נטהרה מענפי החטא הגם שתנקי מהעונש לא יגיעוה טובות האמורות, ותמצא שבשבועת הכהן אמר **כי שטית תחת** וגו' **וכי נטמאת** וגו', וקשה מה הוא כוונתו במאמר כי שטית, אם הוא כי נטמאת לא היה לו לומר וכי נטמאת בתוספת וא''ו, אלא ודאי שנתכוון לענין דברים הקודמים לטומאה שהוא חשק הזולת וכו', והתנה **וכי נטמאת** אז הוא שיהיה לה עונש, ואמר בהפכיות אם לא היו ב' החלוקות תנקה מהרע ותצליח בדבר טוב, וחלוקה האמצעית מובנת מאמצעות הדברים, ורז''ל אמרו (שם יח:) וטהורה היא מאיש אחר, ולדרכינו איש אחר נכלל במאמר לא נטמאה כי דרך כלל אמר בין מאיש זה בין מאחר:
@221 **דבר וגו' ואמרת וגו'**. כפל הכתוב לומר **דבר ואמרת**, גם שינה לשונו, אולי שיכוין לב' מיני נזיר שאחד משובח מחבירו, והוא נזירות כההוא שאמרו בנדרים (ט:) שאמר שמעון הצדיק מימי לא אכלתי וכו' אלא פעם וכו' העבודה שאגלח לשמים וכו' עליך אמר קרא נזיר להזיר לה' יעויין שם. לזה אמר **דבר** כנגד שאר נזירות, **ואמרת** כנגד נזירות המעולה, ולזה כפל לומר **נזיר להזיר לה'** ולא אמר להזיר לה', נתכוון לומר כנגד ב' מיני נזירות, **נזיר** כנגד כל הנזירות שיזיר עצמו, ומאמר **להזיר לה'** כנגד נזירות שהיא מתחלתה לה' כמעשה אותו אדם שהזיר כשראה בבואה שלו:
@228 **וטמא ראש נזרו**. אמר תוס' וא''ו, גם אמר תיבת **ראש**, נתכוון לומר שהגם שאינו אלא טומאת שוגג אף על פי כן לא מלבד שנטמא גופו אלא אפילו קדושה שיש בראשו דכתיב נזר אלהיו על ראשו. עוד ירצה לומר כי לא סתר הנזירות מאז והלאה לבד אלא וטמא גם כן ראש נזרו פירוש תחילת הנזירות, והוא מה שגמר אומר **והזיר לה'** וגו' **והימים הראשונים יפלו**, ומה שחזר לומר אחר כך **כי טמא נזרו** ולא הספיק מה שקדם במאמר וטמא ראש נזרו, שלא יהיה מקום לבעל דין לומר שלא טמא אלא יום א' שהוא התחלת הנזירות, ומאמר **והימים הראשונים** גילה כי לא יום אחד לבד מתחילת הנזירות יטמא אלא ב' הראשונים ולא כל הימים, וגזירת הכתוב הוא, תלמוד לומר כי טמא נזרו בדרך כלל:
@242 **דבר אל אהרן וגו' לאמר**. אמר פעם ב' **לאמור**, אולי כי חש הכתוב לומר שאינו אלא רשות תלמוד לומר לאמר כי מצות עשה היא לאמר. עוד ירצה שלא לאהרן ובניו שהיו אז בנמצא לבד הוא מצוה אלא גם לדורות. עוד נתכוון לשון רוממות, לומר כי מצוה זו יש בה דבר מלך לקיים הדבר, גם יש בה מעלה לכהנים כי הברכות מסרם ה' בידם, והוא אומרו דבר וגו' לאמר:
@243 **יברכך ה' וישמרך**. הקדים הברכה ואחר כך השמירה, לומר שיצוה ה' שמירתו להם לפי ערך הברכה וגדולתה. עוד ירצה שכל כך תהיה גדולת הברכה עד שיצטרך ה' לשומרך. עוד ירצה **יברכך** ולא יסובב רעה מהברכה כדרך פן תאכל ושבעת וגו' (דבדים ח'):
@244 **יאר ה'**. פירוש שלא יהיה מסך המבדיל בין ישראל לאביהם שבשמים שבזה יאיר אור שכינתו על ישראל:
@244 **ויחנך וגו'**. פירוש יתן לך חן וחנינה, ועיין מה שפירשתי בפסוק (בראשית לט, כא) ויהי ה' את יוסף ויט אליו חסד ויתן חנו וגו':
@245 **ישא ה' פניו אליך וגו'**. פירוש אם סיבבו מעשים עד שהבדילו עונותיכם ביניכם ובין אלהיכם ישא ה' המבדיל, **וישם לך שלום** פירוש הוא הפך הפירוד, והמשכיל בתיבת שלום ידע כי הוא זה יסוד עולם המחזיק בעליונים ובתחתונים והוא כלי המחזיק ברכה כשאין מפריד, וזה הוא סוד ושמו את שמי על בני ישראל שגמר אומר ואני אברכם:
@247 **ביום כלות משה**. רז''ל אמרו (במד''ר פי''ב) כלת כתיב, ורואני כי בספר תורה כתובה בוא''ו, ואני אומר כי דברי תורה כאלו וכיוצא באלו אינם נמסרים לכל מרים יד בתופשי התורה, כי יסובב הדבר הכפירה והזלזול בכבוד מורים, ויש לך לדעת כי סדר תורתינו הקדושה ותיבותיה ואותיותיה ספורות מזוקקות חצובות ממחצב קדוש ונורא נפלאים המה למכיר בהם ויותר פליאות נעלמים מעין כל, ואעירך גרגיר אחד והוא הלא תמצא כי יש אותיות נרגשות במבטא התיבות ואינם בכתב כגון יהושע כי במבטא ישנו להרגש של אות הוי''ו בין שי''ן לעי''ן ואינה במכתב, וישנה במקום שאינה נרגשת שהיא בין ה''א לשי''ן, והערה זאת תכונן דעת משכיל להכיר כי אותיותיה ספורות מזוקקות ואי אפשר להוסיף אפילו אות אחת הגם כי תצטרך למכטא הקריאה ותהיה נקראת הגם שאינה כתובה, ותהיה קרי ולא כתיב, וקבעה התורה הוא''ו שלא במקומה להעיר בנסתרות, ואולי כי מזה השכילך שנתכוון לצרף שלשה אותיות משמו יתברך בשמו של צדיק, ולסמוך שי''ן ועי''ן להעיר אל ש''ע נהורין, ואם היה מסדר וא''ו במקומה היתה נפסדת הידיעה בדבר כי לא פורש, והנה מביני מערכות האותיות המה ישכילו משבצותם והם האומרים כי כלת כתיב והוא''ו היא מושאלת שם בהשאלה, והמשכיל יבין כי הוא סודו של משה אשר מתיחדת לו וקיימה בו נקבה תסובב גבר (ירמי' לא), וזה שיעור הדברים כלת כתיב פירוש תיבה זו של כלות זה פירושה קח מהכתוב כלת כדי שתבין אשר תכוין אליו התיבה ואות הוא''ו היא בחינת החתן, והוא סוד נעלם וא''ו תוך כלת והבן. ודרשה זו אין אדם דורשה מדעתו אם לא תקדים ההכרה בדברים על בוריין ואמיתותם מפי מקבלי תורה וסודותיה ורמזיה:
@251 **קח מאתם וגו'**. אומרו **מאתם**, ללמד שעדיין היו ברשות המביאים ולא באו לרשותו של משה, וטעמו של משה לצד שלא נצטוה שישאו המשכן על העגלות לא רצה לקבל כי למה הם ראוים, והנשיאים שיערו בדעתם כי הקרשים והאדנים משא גדול שצריך לעגלות, והסכימה דעתו של הקדוש ברוך הוא:
@256 **ויק ריבו הנשיאים וגו'**. נראה כי כולם כאחד רצו להקריב ביום ראשון לחנוכת המזבח, שרצו שיתחנך מכולם יחד, וה' אמר נשיא אחד ליום וגו', ואמר כי בכל הי''ב ימים יחשב חנוכת המזבח, ולזה אחר אומרו **נשיא אחד** וגו' אמר פעם אחרת **לחנוכת המזבח** לומר כמו שכתבנו, וכאן לא אמר ה' למשה קח מאתם כדרך שאמר למעלה, משמע שלא היה צריך רשות לזה כי ודאי שיקח קרבנות וכל המובא בית ה' זהב וכסף, אלא לצד שבאו יחד אמר ה' אליו כי יסדרם נשיא א' ליום, אלא שראיתי לרז''ל בספרי שאמרו וזה לשונם מגיד שכשם שנתנדבו הנשיאים למלאכת המשכן כך נתנדבו לחנוכת המזבח ולא קבל משה מהן עד שנאמר לו מפי הקדוש ברוך הוא שנאמר יקריבו את קרבנם לחנוכת וגו' עד כאן. רז''ל דייקו יתור אומרו **יקריבו את קרבנם** שלא היה צריך לומר ודרשו שבא לרשיון הא למדת שלא קבל מהם, ויש לנו לחקור זאת למה ימאן משה מקחת מידם נדבת ה', ואפשר שלא רצה לקבל מהם עד שידע אם ה' חפץ שהם יחנכו המזבח או משה או אהרן, ומה גם שלא ראה עמהם שבט לוי, ועיין בתחילת פרשת בהעלותך מה שכתבנו שם, והוא הדין שהיה מסתפק בכל אחד שיבא לחנך המזבח בקרבנו, אבל זולת זה בוודאי שהיה מקבל:
@256 **ויקריבו הנשיאים וגו'**. אמר פעם ב' **ויקריבו הנשיאים**, לומר שהם עצמם טרחו בהבאת הנדבה עד המשכן, הגם שהם נשיאים לא חשו לכבודם. עוד ירצה שלא הביאו הקרבן ונתנוהו ביד המקריב אלא הקריבו אותם לפני המזבח בסמוך לו לומר כי אלו יקריבו ראשונה באין קודם להם, וכמו כן יכוין הכתוב במאמר **ויקריבו אותם לפני המשכן** האמור בעגלות לומר כי הקדשם הוא לצרכי משכן לשאת עליהם קרשיו וגו':
@258 **המקריב ביום הראשון את קרבנו**. צריך לדעת למה הוצרך לומר **את קרבנו** ואולי שבא לומר שהביא משלו ולא משל השבט, ולדבריהם ז''ל (ספרי פיסקא מ''ח) שדייקו דבר זה ממה שכפל לומר בכל אחד זה קרבן נחשון וגו' זה קרבן נתנאל מלמד שהביאו משלהם טעם אומרו **קרבנו**, לפי שיש בו ב' בחינות הקרבה, א' הפלגת זכיותיו וקורבתו לפני ה' כאמור בענין בדבריהם ז''ל (במד''ר פי''ג) נפלאים מעשיו של נחשון, והב' הקרבן עצמו, לזה אמר **הקריב את קרבנו** פירוש הקריב קרבן האמור בענין עם קרבנו הנעלם שהוא סגל מעשה הטוב אשר הפליא עשות, ותדע כי עם קרבן האדם יתייחדו ויתועדו כוחות הקדושה אשר סובבו ממנו ואשר אליו, עוד לצד כי בחינת הקרבן יפעיל הקרבת ענפי הקדושה, והעיד הכתוב כי השיגה יד נחשון להקריב את קרבנו פירוש הצריך להקריב מניצוצי הקדושה וענפיה הקריב וייחד יחד כל הצריך להתקרב ולהתיחד מבחינתו, והוא מאמר **המקריב את קרבנו**, וזה יעשה בכח ובכוונה בהבאת הקרבן:
@258 **למטה יהודה**. ולא אמר נשיא ככל האמור בכל המטות, לומר כי ראוי הוא נחשון להקריב ראשון הגם שלא היה נשיא ומעלתו מצד עצמו, מה שאין כן בכל שאר הנשיאים כי מעלתם היא לצד היותם נשיאי השבט לבד. עוד ירצה להפליג מהותו שלא היה מחשיב עצמו כנשיא אלא כאחד מבני השבט, ולצד שמצינו רז''ל (תנחומא לקמן פסוק מ''ח) שביקשו לדרוש בשמות הנשיאים כל אחד כפי מעשיו, נראה כי צדיק זה שמו גם כן יגיד כי הוא זה אשר היה יחיד שנתנדב לקדש שמו בירידה לים, והוא אומרו **נחשון** אות נו''ן מתחלפת בלמ''ד באותיות דטלנ''ת שהגם שהיה נחשול של ים גובר בין ישראל שנקראו עמי נדב וירד לים כמאמרם ז''ל (סוטה לז.):
@259 **וקרבנו**. אמר תוספת וא''ו מתחילת המעשה, לפי מה שפירשנו במאמר המקריב את קרבנו כי יכוין לנעלם יוצדק לומר בזכרון הנגלה **וקרבנו**, גם לשאר הדרכים הוסיף בו וא''ו לרמוז ליתרון אשר כצדיק זה ירום וגבה מאד:
@264 **ביום השני וגו'**. הקדים שבט יששכר, לצד היותו בן תורה הורם שבטו וקדם לראובן הבכור, ולא זו בלבד אלא גם זבולון המחזיק בידו ללמוד דכתיב (דברים לג) שמח זבולן בצאתך ויששכר וגו' ישב בצלו וקדם לראובן:
@264 **הקריב נתנאל וגו' נשיא יששכר**. הקדים הזכרת שמו לזכרון הנשיאות, לעשות לו גדר המעלה גם בלא חשיבות הנשיאות, מה שאין כן כל שאר הנשיאים שהקדים זכרון הנשיאות לשמם ובשמו הזכיר זכרון התורה ואמצעות קנינה, זכרון התורה **נתנאל** נתן אל על דרך אומרו (משלי ד) לקח טוב נתתי לכם, אמצעות קניינה **בן צוער** שאין התורה נקנית אלא על ידי יסורין, כך היא דרכה של תורה (גיטין נז.) אדם כי ימות באהל, ואולי כי לצד זה גם כן הקדים זכרון שמו לומר כי לצד המפעל הרשום בשמו שהיה בו זכה להיות נשיא לבני יששכר יודעי בינה לעתים:
@265 **הקרב את קרבנו**. כל זה מיותר אחר שכבר אמר הקריב נתנאל, אלא נתכוון להגדיל בחינות הנוספות בזכרון הקרבת נחשון בן עמינדב, ותמצא שהזכיר בנחשון זכרון הקרבן שלשה פעמים, **המקריב** וגו' **קרבנו** וגו' **וקרבנו**, אחד זכרון התקרבותו להקדים ראשונה ואחד לבחינת הקרבן הנעלם, ואחד לקרבן עצמו, כמו כן בנשיא של תורה הזכיר שלשה קרבנות, **הקריב נתנאל** וגו' **הקריב את קרבנו**, ובשאר הנשיאים לא הזכיר אלא הזכרת הקרבן המובא בית ה', כי לא יוכלו עשות כמלכי ישראל שהם שבט יהודה ושבט יששכר, וטעם אומרו הקרב בלא יו''ד, לדרוש המסורת שהוא לשון ציווי והורמנותא, והכוונה בזה על פי מאמרם ז''ל (ספרי פ' נ''ב) שערער ראובן עליו, לזה בא מאמר אדון הרשות ואמר **הקרב**, לזה כתב בלא יו''ד לרמוז זה:
@270 **אליאב בן חלון**. נקרא כן לצד שהוא דבר המעמיד ליששכר ללמוד תורה יקרא אב, וכמו שמצינו שהקדימו משה ליששכר דכתיב (דברים לג) שמח זבולן וגו' ויששכר וגו', והוא מאמר **אליאב** פירוש לי יתיחם לקרות אב, הגם שהוא **חלון** פירוש חולין שאינו בן תורה ועוסק בפרקמטיא חולין עולם הזה אף על פי כן דין אבא למלכא:
@276 **אליצור בן שדיאור**. אולי שירמוז לראובן אשר מחל לו ה' עון הרשום בתורה (בראשית לה) וישכב וגו' והעלה לו צרי למחלתו, והוא אומרו **אלי** פירוש אלהי, **צור** על דרך (ירמי' ח) הצרי אין בגלעד, **בן שדי אור** כאן רמז לענין הרשום בתורה וישכב וגו' והצרי הוא שתכף למאמר וישכב וגו', אמר ויהיו בני יעקב שנים עשר בזה ריפא הנגע, ולדברי חז''ל שאמרו (שבת נה:) כל האומר ראובן חטא וכו' הן הם הדברים שהראה ה' בסמיכות ויהיו בני יעקב וגו':
@282 **שלומיאל בן צורישדי**. ירמוז לשמעון ששלם לו אל על חטא יוסף ויאסור אותו במשמר, גם מה ששלם ה' במעשה זמרי, **צורי שדי** שה' אמר לכליונו די דכתיב (לקמן כה, ח,) ותעצר המגפה:
@288 **אליסף בן דעואל**. ירמוז להיות שנאספו לעריהם תחילה על פי ה' כאמור זולת גבורי חיל שעברו כל חלוץ וגו', והוא אומרו **אל יסף**. עוד על פי דבריהם ז''ל שארץ סיחון ועוג לא היתה בכלל מתנת ארץ ישראל שנתן ה' לאברהם, כמו שאמרו בספרי (ח''ב פיסקא רצט) וזה לשונם פרט לעבר הירדן שנטלת מעצמך עד כאן. ומצינו שמשפט ארץ ישראל יש לה (שביעית פ''ט מ''ב) כידוע, ועיין מה שכתבתי בפרשת מטות בפסוק עטרות וגו', לזה קראו **אליסף** לצד שהוסיף ליטול יותר ממתנת ה' והסכים ה' עמהם, **בן דעואל** פירוש שעשו היכר לעדות לדעת כי הם ידועי עובדי אל כאחד שבטי ישראל כאמור ביהושע סימן כ''ב:
@294 **אלישמע בן עמיהוד**. רז''ל אמרו (תנחומא) ר''מ ור' יהושע בן קרחה היו דורשים את השמות אלישמע בן עמיהוד אלי שמע ולאדונתו לא שמע, עמי היה הודו ולא עם הרשעים עד כאן. נראה כי יכוין הכתוב במאמר **אלי שמע** שטעם שפירש יוסף לא לצד שום מיחוש אשר יסובב מהמעשה אלא לצד יראת ה' כאומרו. (בראשית לט) וחטאתי לאלהים, והוא מאמר **אלי שמע**. עוד ירצה על פי דבריהם שאמרו (סוטה לו:) שנדמה לו דיוקנו של אביו וכו', והן ידוע כי הוא מראה השכינה כי אביו במקומו לא ידע דבר ואפי' אם עודנו חי, אלא אביר יעקב אלהי ישראל, והוא מאמר **אלי שמע**, וכפל לומר עוד **עמיהוד** לרמוז מה שאמר הכתוב (שם) ולא שמע אליה לשכב אצלה להיות עמה פירוש לשכב וגו' כפשוטו, להיות עמה שתבעה ממנו לקירוב בשרו לבשרה ולא רצה, והוא מאמר עמי הודו וכו', ורז''ל שאמרו עם רשעים לשון רבים, אולי שכוונתם לומר שלא מאשת פוטיפר לבד נשמר אלא מכמה כיוצא בה:
@300 **גמליאל בן פדהצור**. אמרו רז''ל הנזכרים וזה לשונם גמליאל עמי גמולים טובים, בן פדהצור פדאני מבית הסוהר עד כאן. וירמוז עוד על זה הדרך **גמליאל** שיוסף אמר כי גמלו ה' חסדים טובים בעד המעשה הגם שהוא פראו במה שהראהו דיוקנו, והוא אומרו **פדה צור**:
@306 **אבידן בן גדעוני**. רמז לשאול שהוא אבי שכן קרא לו דוד (שמואל א כד) ואבי ראה גם ראה, דן שנידון לגדוע המלכות ממנו כאומרו (שם טו) קרע ה' את ממלכות ישראל מעליך. עוד ירמוז למרדכי אשר אבד זרע עמלק.
@306 **בן גדעוני** בן אותו שנגדעה מלכותו של שאול בשבילו:
@312 **אחיעזר בן עמישדי**. אולי שרמז לשמשון, ואומר **אחי** ירמוז לרוח ה' שהיתה עמו דכתיב (שופטים יד) ותצלח עליו רוח ה', ויכונה בשם אחי על דרך אומרו (תהלים קכב) למען אחי ורעי, **עזר** שהיה ה' בעזרו נגד אויביו, ואמר **בן עמישדי** ירמוז לאחר שנקרו פלשתים את עיניו וקרא לה' והיה עמו ונקם מאויביו:
@318 **פגעיאל בן עכרן**. ירמוז על פי דבריהם (ספרי ח''ב פיסקא שנ''ה) שאשר הגיד לאחיו מעשה ראובן ונזפוהו וכשהודה ראובן הודו לדברי אשר וקרבוהו, והוא מאמר **פגעי אל** פירוש פגעו אליו אחיו אחר שעברוהו:
@318 **עוד** ירצה. על דרך אומרו ברוך מבנים אשר. ואמרו רז''ל (שם) וזה לשונם אין לך בכל השבטים שנתברך בבנים כאשר עד כאן. ומצינו שברכת הבנים תסובב משכונת הקדושה, וזה לך האות ארון התורה אשר חנה בבית עובד אדום הגיתי וכו' (ברכות סג:), והוא מאמר **פגעי אל** שפגע בו אל אשר מזה נתברך בבנים, ואומרו **בן עכרן** ירמוז לעכירות הבתולים מבנותיהם כמאמרם ז''ל (תדא''ר פ''ט) שלא היה להם דם בתולים:
@324 **אחירע בן עינן**. ירמוז על דרך מאמרם ז''ל (ספרי שם) בפסוק שבע רצון מלמד שהיה נפתלי שמח בחלקו בימים בדגים בפרגיות ומלא ברכת ה' ים גינוסר עד כאן. והוא מאמר **אחי רע** פירוש שחלק אחיו היה בעיניו רע בערך חלקו, והיתה עינו מלאה מחלק שנפל בגורל ו:
@330 **ביום המשח אותו וגו'**. כאן הצדיק דברינו שכתבנו למעלה כי כולן הקריבו יחד ביום אחד אלא שנסדרה נדבתם אחד ליום:
@330 **מאת נשיאי ישראל**. צריך לדעת למה הוצרך לומר כן, ואולי שישבח הכתוב אותם שמעצמן עשו חנוכת המזבח, והוא מאמר **מאת נשיאי** פירוש מאתם היה המעשה ולא הוצרכו להגיע מהזולת, ורז''ל אמרו (ספרי ח''א נ''ג) שבא לומר ששוו כולן במצוה אחת וזכות אחד עד כאן. פירוש אומרו זכות אחד הוא בענין הקרבן האמור בענין, אבל ימצא בהם הדרגות זה למעלה מזה כי נחשון גדול מכולן:
@333 **כל הבקר לעולה**. אמר לשון יחיד, לומר כי גדר אחד לכולן. וכן אמר **בקר זבח השלמים** לשון יחיד לטעם זה עצמו:
@335 **הקול מדבר אליו**. לפי מה שכתבנו במקומות אחרים (שמות כ' א'), כי דבור היוצא מה' היה נוצר ממנו מלאך והוא המדבר לנביא, ועל פי זה ישבתי כל תיבת לאמר האמור בדיבורי ה' והוא אומרו **הקול מדבר אליו** פירוש קולו של הקדוש ברוך הוא מדבר לו, והגם שהתיבה דגושה כמו מתדבר, לצד שהקול הוא עצמו הדיבור יוצדק ליאמר כסדר זה, והמשכיל יבין:
@335 **חסלת פרשת נשא**
@337 **דבר וגו' ואמרת**. צריך לדעת למה כפל לומר **דבר ואמרת**, גם במלות שונות. ויתבאר על פי דבריהם ז''ל (תנחומא במד''ד פט''ו) וזה לשונם למה נסמכה פרשת מנורה לפרשת נשיאים, לפי שראה אהרן חנוכת נשיאים חלשה דעתו שלא היה עמהם בחנוכה לא הוא ולא שבטו אמר לו הקדוש ברוך הוא חייך שלך גדולה משלהם שאתה מדליק ומטיב את הנרות ערב ובוקר וכו' עד כאן. הנה דבריהם ז''ל צריכין ביאור, מה נחמה זו עושה לחלישות דעתו של אהרן על חנוכת הנשיאים שלא היה בכלל הלא אין מעשה המנורה מקביל לחנוכה, גם למה לא הניח דעתו בכל הקרבנות שהוא מקריב, תמידין, ומוספין, והקטורת, גם בהקרבת החנוכה עצמה של כל הנשיאים הרי הוא המקריב, ולמה לא ריצהו אלא במנורה, ויתיישב הענין בתת לב למה שאמרו במנחות בפרק ב' מדות דף פ''ח וזה לשונם כיצד עושה מסלקן ומניחן באוהל ומקנחן בספוג ונותן בהם שמן וכו' עד כאן. ולסברת החולק על סברא זו וסובר דקביעי נרות סובר גם כן שהיו קנים שבהם נרות קבועים דקים והיה כופפם למטה עד שהיה מטיבם ומקנחם וחוזר וזוקפם כבראשונה כדמוכח שם מדברי רש''י ד''ה של פרקים וכו':
@337 **ואני** אומר אילו הייתי שם הייתי מוכיח ודן לפניהם מהכתובים דלא קביעי נרות, הראשון ממה שמצינו כשהזכיר כל פרטי מעשה המנורה לא הזכיר פרט זה שעשה למול פני המנורה יאירו, שאם הנרות קבועים כשהזכיר המעשה חל זכרון הדבר, ועוד ראיה אחרת ממה שאמר הכתוב בפרשת במדבר (ד' ט') ולקחו בגד תכלת וכיסו את מנורת המאור ואת נרותיה ואת מלקחיה ואת מחתותיה ואת כל כלי שמנה, הרי זה מראה באצבע שאין הנרות קבועים, שאם לא כן הרי הנרות בכלל המנורה הם ולא היה צריך לפרטם, אלא ודאי שאינם קבועים ולזה הוצרך לפרטם כמלקחיה וכמחתותיה שהם בפני עצמם:
@337 **שוב** ראיתי כזה בדברי הימים (ב' ד') ואת המנורות ונרותיהם, הרי זה מגיד כי בזכרון מנורות לא יכללו נרותיהם, וגם ראיתי לרש''י ז''ל שם שכתב וזה לשונו להוציא מלב המפרשים נרות היו עשויים מגופה של מנורה ואדוקים בה שהרי כתיב מנורות ונרותיהם וכו' עד כאן יעוין שם דבריו באורך, הא למדת שפשטיות הכתובים יגידו כי לא קביעי נרות:
@337 **וכפ''ז** נשכיל כוונת תשובת ה' לאהרן, כי אהרן היה מתאנח על חנוכת המזבח והשיבו הקב''ה חייך שלך וכו' פירוש מעשה המנורה שמוריד הנרות ומניחן באוהל ומקנחם וחוזר ובונה אותם מחדש ומדליקה הרי כל יום כעושה מעשה חדש שמחנך הוא המנורה בכל הדלקה והדלקה, ואומרו מדליק ומטיב ערב ובוקר ולא מצינו הדלקה אלא בערב, הרי אמרו במסכת תמיד (פ''ג מ''ט) כי נר מערבי צריך להיות דולק יומם ולילה, ובתורת כהנים אמרו וזה לשונם להעלות נר נר מערבי דולק תדיר מצאו שכבה מדשנו ומדליקו ממזבח העולה עד כאן. הרי שישנה להדלקה והטבה לילה ויום, ונמצא שמחנך בכל יום המנורה והם לא חנכו אלא פעם אחת המזבח, והוא מה שכפל הכתוב במאמרו **דבר ואמרת**, דבר דיבור הצריך למצוה, ואמרת מענה רך המיישב הדעת מחולשתה שאמרנו שחלשה דעתו של אהרן והשיבו כי שלו גדול וכו', גם תתפרש תיבת **ואמרת** לשון מעלה על דרך אומרו (דברים כו) את ה' האמרת שהשיבו שלו מעולה מכולן:
@337 **וגם** לסברת האומר קביעי נרות הנה הוא אומר שהיו הקנים שבו הנרות דקים שהיה יכול לכפוף ולהוריד הנרות למטה עד שיקנחם ולחזור להעלותם ובאמצעות הקינוח וכו' יחשב כמחדש והרי הוא מחנך בכל יום, ויתיישב ערך הכתוב עצמו כמו שכתבתי:
@337 **בהעלותך את הנרות**. צריך לדעת למה לא אמר בהדליקך, ורז''ל דרשו (במד''ר פט''ו ספרי) בו דרשות רבות. גם צריך לדעת למה לא צוה ה' מצוה זו ביום ראשון כי היא מצוה הנוהגת מיום ראשון בעבודה, ועוד הלא היא כתובה המצוה עצמה שמצוה כאן בפרשת תרומה (שמות כה) והעלה את נרותיה והאיר על עבר פניה ולמה חזר לשנותה, עוד למה אמר **יאירו** ולא צוה לנוכח למצטווה תאיר כשיעור בהעלותך, וכמו שאמר גם כן בפרשת תרומה והאיר על עבר וגו'. אכן במה שהקדמתי במאמר חז''ל יתיישב הכל על נכון, כי אומרו **בהעלותך** לצד שהנרות לא היו קבועים יצו ה' שבכל עת אשר יורידם לקנחם ויעלה אותם לסדרם במקומם יסדרם כדרך שיאירו אל מול פני המנורה וגו', ולזה לא אמר גם כן תאיר כי אין המצוה בשעת הדלקה שיוצדק לומר תאיר אלא המצוה היא על סדר הנחתם שיניחם בסדר שיאירו אל מול וגו' והבן:
@337 **ובזה** נתיישב למה הוצרך לחזור לצוות לזה, כי לצד שעד עתה היה משה עושה כסדר זה בז' ימי המילואים, וחש ה' שידין אהרן בדעתו שאין מעכב סדר הנחתן ואדרבא יותר הוא סדר נכון שיהיו הנרות ישרים פיפיותיהם ולא באלכסון, לזה צוה ה' שיאמר לאהרן שדבר זה מעכב, ובחר לסדר מצוה זו כאן ולא סדרה עם סדורי הקרבנות אשר צוה ה' ועבודה המעכבת, להודיענו הקפדת אהרן וריצויו מה שנזכר במאמרם ז''ל:
@337 **אל מול פני המנורה וגו'**. טעם הדבר יתבאר על פי דבריהם ז''ל שאמרו במסכת שבת דף כ''ב וזה לשונם מחוץ לפרוכת העדות וגו' וכי לאורה הוא צריך והלא כל מ' שנה שהיו ישראל במדבר לא הלכו אלא לאורו אלא עדות לבאי עולם שהשכינה שורה בישראל מאי עדות אמר רב זו נר מערבי שנותן בה שמן כמדת חברותיה וממנה היה מדליק ובה היה מסיים עד כאן. על פי הדברים האלה יצו ה' להאיר אל מול פני המנורה שהוא נר המערבי להראות כל נר ונר שלא בא אלא בשביל עדות אשר יגיד נר הפונים אליו כלם להראות נסו הנזכר, ומה שראיתי שדקדקו התוספות התם בתמיהת וכי לאורה הוא צריך וכו' מטעם כל מ' שנה וכו' ולא אמרו והלא כל העולם כולו לאורו של מקום, לעניות דעתי אינו דקדוק כי תצדיק התמיהה מהמורגש להם יותר מדברי' הבאים באמונה כי ה' ברא שמש וירח המאירים לעולם, ולדרך זה יתיישב עם ההיא שהביאו משלהי כל הקרבנות וכו' יעיין שם דבריהם:
@337 **ויש** לנו לחקור זאת מעתה שלא בא המנורה אלא להגיד נסה שבנר מערבי היה מספיק בנר מצדה האחד ונר מצדה השני, ויש לומר כפי הפשט שהוא לנוי שאחר שהוצרכה ביאתה לרמז הנזכר אין נכון להביא בית ה' אלא דבר מתוקן ונכון שבמנורות. ובדרך רמז ירמוז בז' נרות לאומות העולם שהם ע' אומות כל אחד ירמוז לכלל העשירי, ירמוז כי כולן מאירים לנוכח המערבי שהם ישראל שהם בחינת המערב כידוע ליודעי חן, ורמז גם כן שכולן כלים ונר ישראל לא יכבה, ותמצא שהארת הנרות אינו אלא בלילה והוא סוד הגלות שנקרא לילה, מה שאין כן בבא זמן הישועה המתיחס לה בקר כתיב (ישעי' כא) אתא בקר וגו' יכבה נר האומות וישאר מכללותם נר ישראל שהוא הולך ואור עד נכון היום, גם רמז במצות הדלקת הנרות שיכוין המדליק בהדלקתם שתהיה הארתם למול פני המנורה שהכל יהיו לצורכי ישראל המתייחם להם שם פנים כידוע למבינים:
@338 **ויעש כן וגו' כאשר וגו'**. צריך לדעת למה הוצרך לומר **אל מול פני** וגו' ולא הספיק במאמר ויעש כן וגו'. עוד חזר לומר **כאשר צוה** וגו' והוא המאמר עצמו שאמר ויעש כן וגו', יכוין לומר על זה הדרך, אומרו **ויעש כן** כנגד פירוק הנרות וקינוחם כדי שתהיה כחדשה שבזה יוצדק החינוך כמו שאמרנו, ואומרו **אל מול** פני וגו' כנגד סדר הנחתן שיהיו פיפיותיהם אל מול פני וגו' ואומרו **כאשר צוה** לצד שהדיבור היה ביום ותבא לומר שאז בזמן שנצטוה עשה מעשה האמור, לזה אמר **כאשר** וגו' לו' שעשה בזמן שצוה ה' שהיא בערב, והגם שאמרנו כי ישנה להדלקה ביום בנר מערבי, דבר זה לא היה אלא בזמני ירידת עם ה' שהיה כבה נר מערבי (יומא לט:) לא בימי אהרן, ומה גם בתחלת הקמת המשכן. גם רמז באומרו **כאשר צוה** וגו' להודיע שבחו של אהרן, כי מה שעשה אהרן לא עשאו לצד המעלה והכבוד אשר האמיר אותו ה' אלא לצד עשות מצות ה', על דרך אומרו (תהלים מ) לעשות רצונך אלהי חפצתי:
@339 **וזה מעשה המנורה וגו'**. טעם שהוצרך לומר פסוק זה פעם אחרת כאן ולא הספיק מה שאמר כבר בפרשת תרומה ובפרשת ויקהל, יתישב בין למאן דאמר לא קביעי נרות שבא להסיר מכשול הטעות הנמשך ממאמר בהעלותך שאמרנו שהיה מפרק וחוזר ומעלה אותם, ומזה תבא הסברא לומר כי גם שאר המנורה אין חיוב בקיומה מקשה, שהרי גם הנרות בכלל חלק מהמנורה הם ומצינו שהם מפורקים ונדון מהם כדין דבר שהיה בכלל ויצא וכו' ללמד על הכלל, שהגם שאמר הכתוב מקשה זה היה בתחלה אבל אחר כך יכול לעשות כאשר יחפוץ, לזה אמר **וזה מעשה המנורה מקשה** וגו' שכן היא עומדת, וממוצא דבר אתה למד כי הנרות יצאו מהכלל מקשה של המנורה ולא תלמוד מהם. ולמאן דאמר קביעי נרות גם כן בא להודיע שעמדה המנורה במעשה מקשה גם אחר שהשתמשו בה:
@341 **קח את הלוים וגו'**. פרש''י קחם בדברים, ונראה שנתכוין לומר שיבדילם מישראל ולעשות להם מחנה לויה לצד הצורך בטהרתם יותר מבני ישראל, והעד מה שגמר אומר **וטהרת אותם**, הרי שבצורכי טהרה הכתוב מדבר:
@354 **ואתנה את הלוים נתונים לאהרן וגו'**. כפל לומר תיבת נתונים, יכוין לחייב המקבל לקבל המתנה, שלא לומר אי אפשי לקבל מתנה זו, והגם שבמשפטי איש לחבירו יכול למאן כל עוד שלא הגיעה לידו ולא זכה בה, כאן מחייבם לקבל מתנה זו הגם שיש להם צד למאן במתנה זו, כי באמצעות זה יאסר על הכהנים עבודת הלוים ויתחייבו מיתה עליה כאומרם ז''ל בספרי (לקמן יח ג') וז''ל גם הם גם אתם אתם בשלהם והם בשלכם במיתה. והגם שהרמב''ם בפרק ג' מהלכות כלי המקדש כתב וזה לשונו לוים שעבדו עבודת הכהנים וכו' חייבים מיתה בידי שמים אבל הכהן שעבד עבודת הלוי אינו במיתה אלא בלא תעשה עד כאן. על כל פנים ישנו לעונש ונגרע מעבודתם בעבודת הקודש. ולטעם זה יש מקום למאן, לזה כפל לומר נתונים בעל כרחך:
@354 **מתוך בני ישראל**. אמר הכתוב ה' פעמים בני ישראל בפסוק זה ללא צורך, רז''ל דרשו (ויק''ר פ''ב) שהוא מראה החיבה כפל זכרון שמותם ה' פעמים בפסוק א' כנגד ה' חומשי תורה, והוא דרך דרש. ולפי פשט הכתוב נראה כי בדיוק נאמרו הזכרות בני ישראל. אומרו **מתוך בני ישראל** יכוין אל הכללות וכמאמר הקודם קח את הלוים מתוך בני ישראל, ואומרו לעבוד **עבודת בני ישראל** יכוין אל הבכורות שעבודה זו שלהם היתה והלוים עובדים עבודתם, ולזה הוצרך לומר בני ישראל ולא אמר עבודתם שאז היתה נאבדת הכוונה אשר כיוון לה הכתוב. ואומרו **ולכפר על בני ישראל** חוזר אל הכללות, וחש לומר לכפר עליהם שאז תהיה הכוונה שחוזר אל הקודם שהם הבכורות לבד, לזה נאמר בני ישראל לומר שעל הכללות הוא אומר, ואומרו **ולא יהיה בבני ישראל** וגו' ולא אמר ולא יהיה בכם נגף, נתחכם להודיע כי אומרו ולכפר וגו' ולא יהיה בכם נגף אין אחת גזרת חברתה על זה הדרך לכפר וגו' כדי שלא יהיה בהם נגף, אלא הם ב' הדרגות הטובה על זה הדרך לכפר על נפשותיכם מתחלואי הנפש המסובבים מהחטאים, ועוד לא יהיה בבני ישראל נגף בגשתם, וכוונה זו מובנת ממה שאמר בבני ישראל שזה יגיד הבדל המאמר שאינו קשור למעלה. ואומרו **בגשת בני ישראל** נתכוון לומר שהגם שלא יגשו אלא היחידים על כל בני ישראל יקצוף על הדבר, ומצינו כיוצא בזה שיקצוף ה' על הכללות בשביל הפרט, וצא ולמד מעדת קורח מאמר ה' שם (ט''ז כ''א) הבדלו מתוך העדה וגו' והוצרך משה להתפלל לה' על הדבר, וע''ש הטעם:
@355 **ויעש וגו' וכל עדת וגו' כן עשו להם בני ישראל**. יש להעיר למה כפל לומר כן עשו, עוד שינה שהתחיל לומר **כל עדת** וגמר אומרו **בני ישראל**. ונראה שנתכוין בכפל כן עשו בני ישראל על הבכורות, ובא להחזיק טובה לבכורות יותר שהגם שנטלו מקומן בעבודת בית אלהינו עשו ככל אשר צוה ה', הגם כי כפי הטבע אנושי יכאיב לבם ולא ידקדקו עשות ככל פרטי המצוה, ולזה שינה במאמרו מלשון שהתחיל לדבר בו כל עדת בני ישראל ואמר **בני ישראל**, כי לא על כלן מדבר הכתוב כאן אלא על פרט א' כאמור:
@362 **בשנה השנית וגו'**. צריך לדעת למה שינה הכתוב סדר הרגיל להקדים זכרון החודש ואחר כך זכרון השנה, שכן תמצא בתחלת הספר שאמר באחד לחדש השני בשנה השנית. גם כי בסדר זה שכתב נתחייב הכתוב להפסיק באמצע זכרון הזמן במאמר **לצאתם מארץ מצרים** מה שלא היה עושה כן אם היה מקדים זכרון החודש ואחר כך זכרון השנה שאז יאמר לצאתם מארץ מצרים אחרי כן, עוד יש להעיר למה נשתנית פרשה זו שלא נאמר בה דבר אל בני ישראל ככל התורה כולה. אכן יתבאר בהעיר עוד אומרו **ויעשו** בתוספת ו' בתחלת ענין, עוד קשה למה הוצרך ה' לצוות בני ישראל על הפסח והלא כבר צוה כאמור בפרשת בא אל פרעה, והיה נראה לומר לזה כי חש הכתוב לומר שאין מצות פסח אלא בארץ מצרים ובבואם אל ארץ נושבת ולא במדבר, לזה בא לומר **במדבר ויעשו בני ישראל את הפסח**, וזה דבר רחוק:
@362 **ונראה** כי כוונת הכתוב היא לצד שאמרה תורה (שמות יב) כל בן נכר לא יאכל בו, ותניא במכילתא וזה לשונם כל בן נכר אחד ישראל מומר ואחד גוי במשמע עד כאן לשונם. ולצד שמצינו שישראל עשו העגל וכו' ואמרו ז''ל (חולין ה.) כל המודה בעבודה זרה ככופר בכל התורה כולה ויאמר עליו בן נכר, מעתה יש מקום לדון בישראל שאינם יכולין לעשות הפסח, והגם שנתרצה ה' למשה בתפלותיו ובמשפטיו אשר עשה בישראל, עם כל זה עודם לא נתבשרו שנתכפר עון העגל ויש ספק בדבר, לזה בא הקדוש ברוך הוא ונתן רשות ואמר להם **ויעשו בני ישראל את הפסח**, ודקדק לומר **ויעשו** לומר מלבד מה שהובטחו שניחם ה' על הרעה אשר דבר לעשות עוד להם שהוכשרו להיות ראוים לעשות הפסח, ומעתה באנו להשכיל להטיב שינוי הקדמת זכרון השנה, כי כיון שכל עצמו לא בא המאמר כאן אלא להכשירם לעשות הפסח לזה פתח דבריו הזכיר **שנה השנית** להשכיל סובב המאמר שהוא לצד שהיה זה אחר מעשה העגל מה שאין הדבר מושכל בהזכרת זמן החודש שאינו מסתיים בזה הערת הדבר, ולזה לא אמר דבר אל בני ישראל שלא בא לצוות לזה אלא לרשיון ודי בהודעת המשפט למשה שכן הוא הדין, ואולי לפי מה שאמרו בפסחים (ו:) שמאמר זה היה בראש חודש נוכל לומר כי זה המאמר היה קודם ירידת שכינה למשכן ביום ר''ח ניסן והקדים ה' מאמר זה לבשרם שכשרים הם לעשות פסח ואחר ירדה שכינה, ולזה תמצא שאמר בסמוך אחרי זה **וביום הקים את המשכן כסה הענן**:
@367 **ויהי אנשים וגו'**. צריך לדעת למה אמר לשון יחיד על הרבים, ועוד למה הוצרך לומר **ולא יכלו** לעשות הפסח אחר שהודיע שהיו טמאים, ואולי כי לצד שצוה ה' מראש חדש על הפסח כמו שפירשו בפסחים דף ו' שמאמר ויעשו בני ישראל את הפסח הי' בראש חודש ניסן, ומן הראוי היה להם להשתמר מטומאה, ותבא הסברא להטיל בהם דופי אשר לא שמרו את מצות ה' ונטמאו ולא חששו למצות פסח, תלמוד לומר **ויהי** לשון יחיד לומר כי לא היה אלא ענין טומאה אחת אשר נטמאו האנשים בה, וענין טומאה זה עצמו לא היה בידם להשתמר ממנו ובעל כורחם היו נטמאים כמאמרם ז''ל (סוכה כה:) בין לר' יוסי הגלילי שאמר נושאי ארונו של יוסף היו, בין לרבי עקיבא, בין לר' יצחק שאמר טמאי מת מצוה היו צריכין ליטמא הגם שידעו שטומאתם נמשכת עד ארבעה עשר, והוא מה שרמז מאמר **ולא יכלו** לעשות הפסח לומר שלא יכלו לשמור עצמן מהטומאה לעשות הפסח, ואומרו **ביום ההוא**, כבר דקדקו רז''ל (פסחים צ:) למר כדעתו ולמר כדעתו, עוד ירצה באומרו לשון יחיד לומר כי לצד שהיו יחידים הוא שלא יכלו לעשות הפסח, אבל אם היו צבור היו יכולין לעשות הפסח כי בא בטומאה, שוב ראיתי בספרי מרז''ל שדייקו כן:
@367 **לנפש אדם**. אומרו לנפש אדם לומר אבל לטמא שרץ יכולין הם, על פי דבריהם ז''ל (שם) שאמרו שוחטין וזורקין על טמא שרץ וטובל ואוכל פסחו לערב, אבל טמא מת הגם שחל שביעי שלו ביום י''ד אין שוחטין עליו, והוא אומרו ביום ההוא ואמר ר' יצחק וזה לשונו שחל שביעי שלהם בערב הפסח כתיב ביום ההוא הוא שאינם יכולין אבל ביום שלאחריו היו יכולין, וגם לסברת האומר ביום ההוא נטמאו ישנו לפירושינו במאמר לנפש אדם לומר שאם היה שרץ שוחטין עליו:
@367 **ויקרבו לפני משה וגו'**. טעם קרבתם לפני משה ואהרן, לפי פשט הכתוב כדי שתבא ההוראה ממשה תיכף ומיד לכהן להקריב את קרבניהם אם כן יורה, ורז''ל במסכת בבא בתרא פרק יש נוחלין דף קי''ט אמרו וזה לשונם אפשר עמדו לפני משה ולא אמר וכו', אלא סרם המקרא ודרשהו דברי ר' יאשיה אבא חנן משום רבי אליעזר אומר בבית המדרש היו יושבים ובאו וכו' ע''כ, ואמרו בגמרא וזה לשונם במאי קא מפלגי מר סבר חולקין כבוד לתלמיד במקום הרב ומר סבר אין חולקין, והלכתא חולקין, והלכתא אין חולקין ולא קשיא הא דפליג ליה רביה יקרא, הא דלא פליג ליה רביה יקרא עד כאן לשונם. הנה ממה שאמרו הלכתא חולקין והלכתא אין חולקין והעמידו אומרם הלכתא חולקין בדפליג ליה רביה יקרא והלכתא אין חולקין בדלא פליג ליה רביה יקרא הדברים מוכיחים שחולקין רבי יאשיה ואבא חנן בקצוות מר סבר חולקין אפילו אין רבו חולק לו כבוד ומר סבר אין חולקין אפילו חולק לו רבו כבוד שבזה יוצדק לומר הלכתא וכו' והלכתא וכו' מכלל דפליגי:
@367 **ויש** לנו לחקור זאת מנין לו לש''ס להעמיד מחלוקת זו שחולקין בקצוות, ומה גם היות הפך הכלל שאנו אומרים שאין להעמיד מחלוקת רז''ל בקצוות, ואם לצד שלא נודע מחלוקתם אם בשחולק וכו' אם בשאין חולק וכו' אין הכרע לומר שאין חולקין אלא בשאין חולק לו רבו וכו' אבל כשחולק לו רבו וכו' מודים שחולקין או נלך לצד זה שאין חולקין התנאים אלא כשחולק לו רבו וכו' אבל כשאין רבו חולק מודים שאין חולקים לו כבוד ואשר על כן העמיד הש''ס מחלוקת בקצוות, זה דוחק, שהיה לו להש''ם לעמוד על משמעות דברי התנאים קודם כמנהג הש''ם ויגלה מחלוקתם ואחר כך יאמר הלכתא וכו':
@367 **והיה נראה לומר** כי הש''ס דייק שחולקין בקצוות מתוך מחלקותם ממה שחולקין, כי בשלמא אי אמרינן שחולקין בקצוות שפיר אלא אם אינם חולקין אלא בחלוקה אחת ושוים בחברתה למה פליג תנא על דברי חבירו כיון שיכול להעמיד דבריו בחלוקה שיודה בה הוא, גם זה אינו מספיק, כי זה הטעם צודק בדברי אבא חנן שחולק בקצוות אפילו דלא פליג לו רביה יקרא, אבל רבי יאשיה מי יאמר שסובר אין חולקין אפילו פליג ליה רביה יקרא, ועוד גם על החולק אני דן מי גילה לו שת''ק בכל הקצוות הוא אומר:
@367 **אכן** הטעם הוא כי ממה שהוצרך רבי יאשיה לסרס המקרא ולדורשו והוא היפך פשט הכתוב הרי זה מגיד כי לא מצא לו דרך להעמידו בלא סירום, ואם היה סובר רבי יאשיה שחולקין כבוד לתלמיד במקום הרב היה לו להניח הכתוב כפשוטו ולהעמידו כשחולק לו רבו כבוד, ויוצדקו הדברים בהאיש משה רבינו עליו השלום שהיה עניו מאד שהיה חולק כבוד לאהרן אחיו ומה גם שהיה גדול ממנו, עוד מצאנוהו שהיה חולק לו כבוד כאמרם ז''ל (מכילתא פרשת בא יב) שאמרו כשהיו עומדים לפני פרעה משה חולק כבוד לאהרן שיקדים בדיבור ואהרן למשה והיה הדיבור יוצא מבין שניהם, הנה הוא חולק לו כבוד:
@367 **וממה** שסרס המקרא גילה דעתו שסובר שאין חולקין וכו' אפילו חולק לו רבו כבוד, וממה שמצינו שנחלקו גם כן בענין בנות צלפחד דכתיב ותעמודנה לפני משה ולפני אלעזר וגו', וזה לשונם אפשר עמדו לפני משה וכו' ולפני אלעזר ולא אמר וכו' ויעמדו לפני הנשיאים בעדה והעדה וכו' אלא סרס המקרא ודרשהו דברי רבי יאשיה אבא חנן אומר משום רבי אליעזר בבית המדרש היו יושבים וכו', ומביא הש''ס הענין עצמו שהבאנו למעלה, והנה ממה שראינו שחלק אבא חנן בעמידת בנות צלפחד לפני הנשיאים והעדה מן הסתם לא היו הנשיאים חולקין כבוד לכל העדה ואין צריך לומר משה מלך ישראל ואף על פי כן אמר אבא חנן שחלקו להם כבוד הא למדת שסובר שחולקין כבוד אפילו אין רבו חולק לו כבוד, ומעתה הרווחנו טעם נכון למה נחלקו ב' פעמים ר' יאשיה ואבא חנן:
@368 **למה נגרע וגו'**. צריך לדעת טענת האנשים במאמר למה נגרע, הלא טעמם בפיהם יענו אנחנו טמאים, ומה מבקשים ליתן להם תורה חדשה. ואולי כי לצד שנטמאו ברשותו יתברך בין למאן דאמר טמאי מת מצוה בין למאן דאמר נושאי ארונו של יוסף חשבו כי ידין ה' אותם כטהורים, וכשם שמצינו (פסחים עז.) שיתרצה ה' עשות הפסח בטומאה בציבור, לזה טענו **למה נגרע**, וכי בשביל שעשו מצוה יהיו נגרעים מקרבן פסח, או ירצה לומר שיעשו לפסח תשלומין כחגיגה שיש לה תשלומין כל ז' שאמרו (חגיגה ט.) חוגג והולך כל הרגל, כמו כן יצו ה' להם שיעשו פסח למחר, והוא מאמר **במועדו** שהוא מועד הפסח:
@368 **ואולי** כי לזה דקדק הכתוב לומר **ביום ההוא** פירוש לדברי האומר יום ז' של טומאתם היה לזה באו ביום ההוא כדי שיאמר להם לעשותו תשלומין למחר:
@368 **ולדרך** זה אנו מרויחים טעם שה' אמר מצוה זו של פסח שני אחר ששאלו האנשים ההמה, לומר שהגם שיהיו טהורים בתוך ימי הפסח כנדון שלפנינו אף על פי כן אין לו תשלומין לעשותו בז' ימי הפסח כחגיגה אלא בחודש הב'. עוד ירצה אומרו **למה נגרע** פירוש כיון שהיה יום ז' לטומאתם טוענים שיכולין לשחוט עליהם פסחיהם כדרך ששוחטין וזורקין על טמא שרץ כיון שהם נטהרים לערב ואין להם טומאה אלא ביום ההוא, והוא מאמר **ביום ההוא**, ורז''ל אמרו עניינים אחרים, ואלו ואלו דברי אלהים חיים:
@374 **והאיש אשר הוא טהור וגו'**. צריך לדעת למה לא כתב עונש המבטל פסח בזמנו עד עתה ולא כשכתב מצות הפסח, ולפי מה שנחלקו בענין זה (פסחים צג.) וזה לשונם תנו רבנן חייב על הראשון וחייב על הב' דברי רבי, רבי נתן אומר חייב על הראשון ופטור על הב', רבי חנינא בן עקיבא אומר אף על הראשון אינו חייב אלא אם כן לא עשה הב', ואמרו שם בפסחים ושלשתם מקרא א' דרשו יעיין שם, מעתה לכל אחת מהסברות הניח הכתוב לומר עד כאן לכל א' מהסברות כדרכו, מה שלא היינו שומעין כן אם היה מצוה במקומו:
@375 **וכי יגור**. אמר בתוספת ו', נתכוון בזה להטיל על ישראל משפט הגרים לבל יזלזלו במצות, ולזה אמר **וכי יגור** מוסיף על ענין ראשון, ומה ענין ראשון לבני ישראל גם זה לישראל:
@375 **ועשה וגו'**. צריך לדעת למה כתב ועשה בתוספת ו' בתחלת ענין. עוד למה הוצרך לחזור לומר **כן יעשה**, והיה נראה לומר שבא לשלול גר תושב ולזה אמר **וכי יגור אתכם גר** ויהיה מאותם שעושים פסח דהיינו גר שמקיים התורה על זה אני מצוך כחקת הפסח וגו' כן יעשה, ואין פירוש זה מספיק כי מובן הוא הדבר שאינו מדבר אלא בגר גמור, ויתבאר על פי דבריהם ז''ל בספרי (כאן) וזה לשונם רשב''א אומר הרי שנתגייר בין ב' פסחים שומע אני יעשה ב' תלמוד לומר ולאזרח, מה אזרח שלא עשה וכו' ע''כ, והוא מאמר הכתוב ועשה בתוספת ו' לומר אם היה בן מעשה הראשון אז יתחייב לעשות ב' כשלא הוכשר, וכפי זה אומרו **ועשה** תנאי הוא **אז הוא כחקת הפסח** וגו' יעשה, פירוש חקת הפסח הוא שישנו גם כן בתשלומין, אבל אם אינו בפסח אחד אינו בפסח ב':
@375 **עוד** נראה לפרש בהעיר עוד למה פרט הכתוב הגר במצוה זו מכל המצות, והגם שאמרו ז''ל (ספרי) וזה לשונם אין לי אלא פסח שהשוה הגר לאזרח כל המצות שבתורה מנין תלמוד לומר חקה אחת וגו' עד כאן. עם כל זה למה לא בחר לפרט אלא במצות פסח. אכן לצד שיש מקום לומר שאין הגר חייב בפסח לפי שלא היה לא הוא ולא אבותיו במצרים ואין מקום למעשה פסח אצלם כי לא פסח ה' על בתיהם במצרים, וזה דומה למאמרם ז''ל שאמרו (ביכורים פ''א) גר מביא ואינו קורא שאינו יכול לומר וכו' כמו כן הדבר הזה, לזה חידש הכתוב דין זה כאן ואמר **וכי יגור אתכם גר** ועשה פסח הוסיף בו תוספת פירוש שהגם שאינו מהיוצאים ממצרים אף על פי כן מלבד שצריך לעשות כל המצות ואף גם זאת ועשה פסח וגו':
@375 **ודקדק** לומר **אתכם** לומר שהגם שאתם רואים זה חדש מקרוב בא עם כל זה אתכם הוא כאחד ממנו, ויציאתנו ממצרים היתה גאולת עולם גם לנפש הגר, הגם שלא היה בנגלה היה בנסתר, כי שורש הקדושה אחד הוא וכשהיו אבותינו במצרים היתה כללות הקדושה טבועה בטומאת מצרים ואם חס ושלום הי' כללות הקדושה נטבע אין תרופה לענפים כי הכל הולך אחר העיקר והצלת העיקר נוגעת גם לענפים, ואמר **כחקת הפסח**, חש הכתוב שיאמר האומר הן האמת כי עשה יעשה כל משפטי פסח אבל דברים שהם ממש דברי שקר כמו שתאמר להגיד עבדים היינו לפרעה במצרים ויוציאנו וגו' וכדומה עדיין דן אנכי כי לא ישעו בדברי שקר, תלמוד לומר כחקת הפסח כי יכול יוכל דבר כדברים האלה כי היה היה גם הוא במצרים בבחינת השרשים, ועיין מה שפירשתי בפסוק (שמות כג) ואתם ידעתם את נפש הגר, ואומרו **כן יעשה** בא לחובה שלא תאמר שלא בא הכתוב אלא לרשות שיכול לומר כן תלמוד לומר כן יעשה חובה, ומאמר **חקה אחת** בא להשוות כל התורה כולה:
@378 **ולפי העלות**. אמר ו' בתחלת ענין, לומר כי ענין הענן אשר על המשכן היה משמש ב' דברים, אחד הוא למכסה על האהל לכבוד ולתפארת, והוא מאמר **כסה הענז את המשכז לאהל על העדות**, והוסיף עוד ואמר **ולפי** וגו' פירוש ועוד היה הענן לצורך זה שלפי העלותו יסעו בני ישראל כדי שידעו זמן הנסיעה וזמן החניה:
@378 **ואחרי כן יסעו וגו'**. צריך לדעת מה הוא אומרו **ואחרי כן** וגו' שהיה צריך לעשות גזירה במאמר על זה הדרך ולפי העלות וגו' יסעו כשיעור מאמר הסמוך ובמקום אשר ישכון וגו' שם יחנו. ונראה שאם היה אומר אחרי כן יסעו היה נשמע שזה הוא גזרת הכתוב, ולא כן הוא הכוונה, אלא שהגזירה הוא במאמר הבא אחר כך **על פי ה'** וגו', וזה הוא שיעור הכתוב **ולפי העלות** וגו' ואחרי כן הוא שיהיו נוסעים וגו' וכיון שכן **על פי ה'** וגו' הרי הם נוסעים על פי ה'. עוד נתכוון לומר בדרך זה שזולת כן אם היה אומר אחרי כן יסעו היתה הגזירה בתיבת אחרי כן והיה המשמעות שלא היו נוסעים קודם אלא אחרי כן ואין בנשמע שהיו על כל פנים נוסעים כשהיה נוסע הענן, לזה אמר **ואחרי כן** כדי שתהיה נרדפת למעלה ותבא הגזירה במאמר יסעו בני ישראל, כאלו אמר ולפי העלות וגו' יסעו, ואם היה אומר בסדר זה ולפי העלות וגו' יסעו, אז הי' נשמע שבעלותו הוא שמתחייבים ליסע, ואין במובן שאם ירצו ליסע שתמנעם מניעת עליית הענן, לזה אמר ולפי העלות וגו' ואחרי כן לומר ולא קודם:
@379 **על פי ה' יסעו בני ישראל וגו'**. והענן יגיד אשר פי ה' יקבנו:
@379 **כל ימי וגו' ובהאריך וגו'**. בא הכתוב לסדר כל בחינות הנהגות הענן, וללמד שבחן של ישראל שהיו חפצים באשר יחפוץ ה', והתחיל בענין אריכות זמן החניה ואמר **כל ימי אשר ישכון הענן יחנו** פירוש יחנו יחפצו לחנות, ולזה לא אמר חנו בני ישראל שיהיה נשמע שעשו לצד ההכרח מהמנהיג, והוסיף לומר **ובהאריך** וגו' לומר שאפילו יאריך כל כך ימים רבים אף על פי כן יחנו, ואומרו **ושמרו** וגו' לומר כי מלבד שהיו חונים כל זמן וכו' עוד מודיע כי לא היו עושים הדבר לצד שהיו חפצים בשבת ולא בהילוך אלא לצד שמירת דבר ה', והוא אומרו **ושמרו** וגו' הגם שהם ימים רבים, ואומרו **ולא יסעו** ולא אמר ולא נסעו, לשלול בחינת החושב כאלו אמר ולא יחפצו ליסע:
@381 **ויש אשר וגו' ימים מספר**. גם זה מספר בשבח ישראל שהגם שלא יחנו לפוש אלא ימים מועטים יסעו בהעלות הענן, ואמר **על פי ה' יחנו**, ואין שייכות לזכרון שניהם אלא למסע, נתכוון להשוות הנסיעה לחניה לומר כשם שעל פי ה' יחנו ברצון והשלמת דעת לנוח מהדרך כמו כן ברצון השלם היו נוסעים הגם שהיו נוחים זמן מועט. וראיתי שתרגם יונתן בן עוזיאל ימים מספר שבעת יומין, ולפי דבריו ז''ל אין מקום לדברינו לומר שבא לשבח ישראל כי יש במשך ז' ימים לנוח מן הדרך, ולדבריו ז''ל יתבאר הכתוב על זה הדרך שבא לומר שבין בפרק החניה ובין בפרק הנסיעה הגם שהיה להם הרצון לא היו עושים הדבר אלא לצד היות הדבר מאמרו יתברך, והוא אומרו **על פי ה' יחנו ועל פי ה' יסעו**:
@382 **ויש אשר וגו' מערב עד בקר וגו'**. מכאן ואילך בא הכתוב להודיע ההדרגות שהיו בשינוי חנייתם, והתחיל מזמן חניית לילה, והוא אומרו **מערב עד בקר**, ואמר סמוך לה זמן חניית יום ולילה כאומרו **יומם ולילה**, ואמר סמוך לה זמן ב' ימים כאומרו **יומים**, וסמוך לה **חודש**, וסמוך לה **ימים** שהוא שנה, והודעה בזה אינו כהודעה בפסוקים הקודמין פסוק ובהאריך ופסוק ויש אשר וגו' ימים מספר, שאם כן לא היה לו להקדים זכרון ימים מספר לזכרון ערב עד בוקר, ואין לומר כי שני פסוקים ובהאריך ויש וגו' ימים מספר הם זכרון דרך כלל מה שפרט אחר כך, שהרי אין בכלל מה שבפרט שהוא מערב עד בוקר ויומם ולילה. אלא ודאי כי ב' כתובים הראשונים יגידו ענין אחד כמו שכתבנו, וג' כתובים האחרונים יגידו הדרגות שינויי העכבה שהיו משתנים מגדר לילה אחת לגדר שנה אחת, והטעם בזה לפי מאמר אנשי אמת שטעם העברתם במדבר הוא לברר ניצוצי הקדושה השבויות ביד שוכן מדבר ציה, אשר על כן היודע נסתרות היה משער שיעור אשר יספיק לבירור במקום ההוא אם מעט ואם הרבה והיו מתעכבים כפי הצורך, גם לא היו חונים אלא במקום שיש לברר ולא במקום שיספיק בו הבירור במשך זמן הילוכם בו:
@383 **בהאריך הענן וגו'**. פירוש יספר כאן בשבח ישראל שאפילו כל כך נתעכב הענן שנה אחת יחנו ברצונם, **ובהעלותו** אפילו לא יתעכב אלא מערב עד בקר ונעלה הענן נוסעים, והשוה הכתוב שניהם רצון הנסיעה שהיתה להם בשלא היה מתעכב אלא לילה אחת לרצון שהיה להם לנסוע אחר שנה אחת כי ודאי יחפצו ליסע, והשוה הכתוב רצון שהיה להם בנסיעה אחר שנה אחת לנסיעה אחר לילה אחת לחניתם שלא היו קצים בעכבת החנייה לצד הזמן שלא היה כל כך ארוך כמו כן בחנייתם שנה אחת, וגמר אומר הטעם, **על פי ה'** שלא היו חפצים אלא לעשות מאמר ה', ואומרו שמרו **את משמרת ה'** פירוש היו ממתינים כשיעור אשר ימתין ה' ליסע אם מעט ואם הרבה:
@383 **ואם** תאמר אם כן למה הוצרך להקדים ב' פסוקים ראשונים פסוק **ובהאריך** ופסוק **ויש אשר יהיה** וגו', אם להגיד שבחן של ישראל הנה הוא ביתר שבח בגמרן של דברים כמו שפירשנו. הנה אם לא קדם מאמר **ובהאריך** הענן על המשכן וגו' **ויש** וגו' לא היינו מפרשים במאמר ובהאריך על המשכן וגו' על פי ה' וגו' כדרך שפירשתי, אלא היינו אומרים שהיו ממתינים בזמן הארוך והיו נוסעים בזמן המועט ולא אחרו ולא קדמו, אבל ידיעת הרצון השלם כדרך שפירשתי לא היינו יודעים, אלא אחר שהקדים שלא קדמו ולא אחרו בפסוקים הראשונים כדרך שפירשנו שאפילו כחושב לא חשבו להקדים ולאחר, בא הכתוב והעירנו בגומרן של דברים להבין מה שפירשנו בהם, ומה שאמר עוד **על פי ה' ביד משה**, רז''ל כבר דרשו (ספרי ח''א פ''ד) שהיה הענן מתעגל ולא היה מזדקף עד שהיה משה אומר קומה ה' וגו':
@386 **עשה לך וגו'**. צריך לדעת למה הוצרך לחצוצרות למסע המחנות הלא עיני כל ישראל על הענן וכשיראוהו נוסע נוסעים, ואולי כי לצד שלא היו נוסעים יחד אלא יקדים דגל יהודה ואחריו בני גרשון נושאי המשכן ואחריו דגל ראובן וכו', לזה היה צריך לחצוצרות כדי שכל אחד ידע הזמן בדיוק שיסע בו בזה אחר זה. עוד נראה בדקדוק עוד אומרו תיבת **לך** שלא היה צריך לומר, ויתבאר ע''פ דבריהם ז''ל שכתבנו בסמוך שלא היה מזדקף הענן עד שהיה משה אומר לו קומה וגו' והיה הדבר תלוי ביד משה. ומעתה נוכל לומר גם כן שיצו ה' שכמו כן תהיה נסיעת ישראל על פי משה לכבודו של משה, כדרך שחלק לו כבוד למסע הענן שלא יסע עד שיאמר לו קומה, והוא מה שרמז במאמר **לך** פירוש לרשותך ולמאמרך, ורז''ל דרשו (ספרי כאן) עשה לך משלך, גם דרשו (במד''ר פט''ו) לך אתה משמש ולא אחר יכול להשתמש בהם, וע' פנים לתורה:
@390 **ותקעתם תרועה שנית**. ולא היה מספיק בתקיעה אחת לכלן כדרך שתוקע למערב וצפון תקיעה אחת לשניהם כאומרם בספרי, (ח''ב ע''ג) הטעם לצד שהיו מורידים המשכן ונוסעים בני גרשון קודם שיסעו דגל בני ראובן תימנה, לזה צריך תקיעה בפני עצמה אחר נסיעת המשכן:
@395 **בשנה השנית בחודש וגו'**. הקדים זכרון השנה לזכרון החודש, כדי להסמיך מאמר נעלה הענן למאמר בעשרים לחודש, כי כן הוא יופי שיעור הדיבור:
@413 **נוסעים אנחנו וגו'**. צריך לדעת למה הוצרך לומר זה הלא ידוע היה הדבר להם, ורז''ל הרגישו מזה ואמרו (ספרי כאן) שנתכוין במאמר זה לומר שלא נשאר להם אלא נסיעה אחת ויגיעו למחוז חפצם, ויתבאר עוד הכתוב בהעיר במאמר **אותו אתן לכם** שלא היה לו לומר תיבת אותו. אכן לצד שלא הבטיח ה' בהבטחותיו לאבותינו לתת לנו אלא ארץ כנען ולא ארץ סיחון ועוג, וכמאמרם ז''ל (ספרי ח''ב רצ''ט) וכתבנוהו למעלה (ז' מ''ב), ולצד שהיו אז נוסעים לארץ סיחון ועוג אמר לחובב נוסעים אנחנו אל המקום אשר אמר ה' אותו אתן גם כן לכם הגם שלא נתנו לאבותינו יתן אותו לנו, כי ידע בנבואה מה שעתיד להיות, והגם שאמרו בספרי (שם) וזה לשונם פרט לארץ סיחון ועוג שנטלתם מעצמיכם ע''כ, אף על פי כן הסכים ה' ונתנה להם. עוד נתכוון במאמר **אותו אתן לכם** רמז כי ארץ סיחון ועוג יתנם ה' להם בכינוי לרמוז גם אל משה כי הוא לכדה והורישה לב' המטות וחצי המטה, ודקדק לומר אותו למעט ארץ כנען כי לא למשה יתננה אלא ליהושע:
@413 **לכה אתנו והטבנו לך וגו'**. כוונת הדברים הוא לצד שאמרו ז''ל (ספרי ח''א קל''ב) ארץ ישראל נתחלקה לשבטים ולא לגרים, ומעתה אין מקום לתת חלק ונחלה לבני חובב תוך ישראל זולת בדרך מתנה מחלקם, ולזה כשבא משה להבטיחו דקדק לומר לו **והטבנו לך** פירוש מחלק ישראל יתנו לו בתורת הטבה, ולצד שחש משה שלא יחפצו במאמר משה מה' סיבות אשר יסובבו מהדבר, ג' יסובבו מבחינת המתנה, וב' מבחינת ההבטחה ג' מבחינת המתנה, א' לצד שיתבייש הנשפע מהמשפיע על דרך אומרם (ירושלמי ערלה פ''א ה''ג) מאן דאכיל דלאו דיליה וכו', ב' לצד שיתמעט כבוד המקבל מתנה בעיני הנותן ולא יהיה עומד בעיניו בכבוד הראשון, ג' לצד המעטת המתנה בערך אדם גדול תהיה לו לחרפה וימאס מציאותה מהעדרה. ב' מבחינת ההבטחה, א' מצד שיש לחוש שינחם מדברו הטוב אשר דיבר לעשות, או מצד צרות עין כי תרע עינו מתת מטובו, או כי יתמעט אהבת המובטח ממנו בלבו, והב' לצד שלא תשיג ידו עשות, וכמאמר רז''ל (ויק''ר פכ''ו) בפסוק אמרות ה' אמרות טהורות, ולזה נתחכם משה בנועם דבריו והסיר כל הה' חששות הנזכרים:
@413 **ופתח** דבריו האירו במאמר **לכה אתנו והטבנו** וגו' פירוש בעד הליכתך עמנו הטבנו לך, ומעתה ההטבה אינה בחנם ויכול לתבוע ולהוציא בדיינים, ובדרך זה הוסר מיחוש הבושה דמאן דאכיל דלאו דיליה, גם מיחוש המעטת בכבודו לצד שנהנה ממנו, גם מיחוש ביטול ההבטחה כי יתנחם שהרי אינו הולך עמם ועוזב ארצו ונחלתו אלא בתנאי זה, ואומרו **והטבנו לך** כאן פירוש שיעור ההטבה שיהיה חלק בני חובב מובחר וטוב מכל חלק עם בני ישראל שיתנו לו חלק המובחר, וכן אמרו רז''ל (ספרי כאן) שנתנו לו דושנה של יריחו. ואומרו **כי ה' דבר טוב** בזה סתר ב' המיחושים שנשארו מהמיחושים שרשמנו והם המעטת ההטבה ומניעת השג יד לקיים הבטחון, כי ה' דבר טוב וטובת ה' מופלאת היא, ולשיעור זה תהיה ההטבה גדולת הערך וראויה להתכבד, גם חזקה ובריאה ואין בה חזרה כי ה' לא איש הוא וגו' ויתנחם ובפרט מדברו הטוב, כי דוקא על הרעה הוא שניחם דכתיב (שמות לב) וינחם ה' על הרעה, ודקדק לומר על ישראל לתוספת חיזוק הטוב לצד שהוא לישראל ולא לאומות העולם ולא ינחם על הטובה להם:
@414 **כי אם אל ארצי וגו' אלך**. צריך לדעת למה הוצרך לומר תיבת **אלך** והלא מובן הוא מאומרו לא אלך כי אם וגו'. יתבאר על דרך אומרם ז''ל (מכילתא יתרו) וזה לשונם וישלח משה את חותנו ר' יהושע אומר שלחו מכבודו של עולם, ר''א המודעי אומר אמר לו כלום הנר מהנה אלא במקום החושך מה אני מהנה בין חמה ולבנה אלא אני הולך לארצי ומגייר כל בני מדינה ואביאם ללמוד וכו' יכול הלך ולא עשה כן הרי אומר (שופטים א) ובני קני וגו', מתוך דבריהם משמע שרבי יהושע סובר שיתרו לא נתגייר ושלחו משה מכבודו של עולם, ולר''א נתגייר, ולדברי שניהם יתיישב יתור **אלך** על נכון, לר' יהושע נתכוון לומר על זה הדרך **לא אלך כי אם אל ארצי** ולא לטעם חביבות ארצי לבד אבל זולת זה הייתי יושב, לא כן הוא אלא אלך על כל פנים, ולסברת ר''א על זה הדרך **לא אלך** פירוש לחלוטין בהליכה זו **כי אם אל ארצי ואל מולדתי** פירוש אל אשר יאות לבני ארצי ומולדתי אלך לגיירם ולשוב, וכפל לומר ארצי ומולדתי לומר אם אמצא מקום אגייר כל בני מדינתי ולפחות בני מולדתי:
@415 **אל נא תעזוב אותנו וגו'**. לדברי ר''א יתבאר על זה הדרך שמבקש ממנו שלא ילך אפילו לפי שעה הגם שדעתו לחזור, והוא מה שרמז בתיבת נא, וכנגד טענת שרגא בטיהרא שלא קבלה ממנו אמר הטעם **כי על כן ידעת חנותנו במדבר** ועל ידך האירו דרכינו בעצתך דכתיב (שמות יח) ואתה תחזה מכל העם וגו' והסכים ה' על עצתך וכתיב ויבחר משה וגו' אם כן יכול אתה להאיר אפילו לפני חמה ולבנה, ולדברי ר' יהושע יתבאר על זה הדרך **אל נא** פירוש אין נכון עתה לעזוב אותנו, והטעם **כי על כן ידעת** וגו', פירוש בשלמא אם לא באת אצלינו כל עיקר אין אני חושש לך אבל עתה שבאת וידעת חנותנו במדבר פירוש לצד שישראל מכוסים בעננים ואין אדם יודע מקומם כמאמרם ז''ל (במד''ד פי''ט ר''ה ג.) בפסוק כי גוע אהרן וגו' וישמע הכנעני כי בא ישראל וגו', ואמרו רז''ל כי לצד שנסתלקו ענני כבוד הוכר מקומן של ישראל, אמור מעתה קודם לכן לא נודע תחנותם וחובב הודיעו ה' חנותם של ישראל, ועוד לו שהסכים ה' למה שהאיר עיניהם בעצתו, והוא אומרו **והיית לנו** וגו', ואין נכון לעזוב אותם אחר כל זה, כי יש בזה חילול ה', כי יאמרו שעמד על אמונתם והחשיבוהו כל כך ועזב אותם אין זה אלא שלא הוצדקו אצלו מופתי האמונה ואין נכון עשות כן, וכשלא קבל גרשו משה מכבודו של עולם:
@416 **והיה כי תלך וגו' והיה וגו'**. צריך לדעת למה כפל לומר **והיה** פעם ב' עוד כל הכתוב מיותר שהן הן הדבדים הנאמרים במאמר ראשון, ויתבאר לב' הסברות, לסברת ר''א תיבת והיה וגו' נמשכת עם מה שלמעלה על זה הדרך והיית לנו לעינים והיה כמו כן כי תלך עמנו תחשב במדרגה זו ולא תהיה בגדר נר לפני חמה ולבנה כמאמרך לדברי ר''א, ולדברי ר' יהושע ירצה שתעמוד במצב זה גדול בעינינו, ואומרו **והיה הטוב ההוא** וגו' פירוש לדברי ר''א שרצה ללכת ולחזור אמר אליו אין נכון ללכת ולחזור כי אני רוצה שתהא מצוי בעת אשר ה' יתן הטוב לעמו כדי שנטיב לך בחלק היפה ממנו, אשר לא כן אם לא תהיה מצוי בעת חילוק הארץ, ונתרצה על הדבר אלא שאחר זמן כשראה שנגזרה גזירה על ישראל להתעכב במדבר מ' שנה הלך לעשות דברו הטוב לגייר בני עירו וחזר ונמצא בעת הטבת ה' לישראל כמאמר משה. ולדברי ר' יהושע גם כן נתכוון לומר לו שלא יראה בעיני עצמו היותו גר שיהיה במדרגה שפלה מהעם כמאמר כי אם אל ארצי ואל מולדתי שיורה שחפץ ללכת במקום שיש לו מכירין, לזה אמר לא כן הוא אלא **והיה הטוב ההוא אשר ייטיב ה' יהיה עמנו** פירוש עם כולנו יחד שלא יחשבוהו במדריגה שפלה מהם. ועוד שיהיה לך חלק הטוב והמובחר שבחלקים, והוא מאמר והטבנו לך:
@419 **ויהי בנסוע הארון וגו' קומה ה' וגו'**. צריך לדעת כוונת המאמר, ויתבאר הכתוב על פי דבריהם (ע''ח של''ב פ''א) שרשמנו בכמה מקומות שטעם הליכת ישראל במדבר היתה לברר ניצוצי הקדושה השבויות ברשות שוכן מדבר ציה, וצריך אתה לדעת כי החיצונים ישנם בב' הדרגות א' הוא בחינת המסית והמפתה לנדבק בו להרע ולהשחית, ב' בחינת המזיק והמחבל ואין בטבעו לפתות, ובא המאמר כאן **ויהי בנסוע הארון** כי כשנוסע ומתדבקים בו כל ניצוצי הקדושה וכשמתבררים ניצוצי הקדושה מתפוצצים ומשתברים הקליפות, והוא מאמר **קומה ה** ', **ויפוצו אויביך** שהם הקליפות הנאחזות בניצוצי הקדושה יתפוצצו, ואליהם רמז בתיבת **ויהי** לשון צער, וכנגד בחינת הרע המפתה את האדם אמר **וינוסו משנאיך מפניך** פירוש אותם בחינות המשניאים דרך ה' בלבות בני אדם ינוסו, ואומר לשון רבים לצד היותם רבים המפתים כמאמרם ז''ל ביומא (סט:) שיש יצר הרע של עבודה זרה ושל זנות וכו', וכל זה בנסוע פירוש בדרך נסיעה, וכשהיה חונה היה אומר באופן אחר, כי ה' כשחונה במקום אחד יגיד בזה כי המקומות שלא חנה שם לא היה שם בירור ניצוצי הקדושה שיצטרך לחנות שמה ויספיק מעבר דרך שם, ובמקום אשר יחנה שם יגיד כי שם יש ניצוצי הקדושה שצריך להתעכב בשבילם שם, ועל זה היה מכוין משה ואומר בנחה **שובה ה' רבבות אלפי ישראל**, פירוש שישיב ניצוצי הקדושה לקבץ כל הרבבות ואלפים הנקראים ישראל כי כל ניצוצי הקדושה יקראו ישראל ואולי שרמז בתיבת **אלפי** לשון מעלה ורבנות, ותמצא כי ניצוצי הקדושה אשר שבה ס''מ הרשע היו רבים ונכבדים, וצא ולמד רות מנין יצתה, ויכוין משה בזה להתפלל להתעצם כח קדושת ישראל בעזר ה' לנצח ולברר כל אשר ימצא במקום ההוא:
@430 **ויחר אף ה' מאד**. טעם **מאד**, לצד שכל עושה רשעה לצד תגבורת הפיתוי ועריבות האיסור יש לדון בו צד האונס, אבל אלו שמבקשים לשוב הרי הם כמגרים בהם יצר הרע ואין גדר רע גדול בזה:
@430 **ובעיני משה רע**. כי יקפיד האיש על מעשה ידיו, וצא ולמד ממה שנאמר בשמואל (תענית ה:) שחסרו מימיו שלא יראה ברעה אשר תמצא את שאול, וכמו כן רע על משה מעשה בלתי הגון של ישראל. עוד ירצה על זה הדרך שרע בעיני משה מה שחרה ה' אפו מאד כל כך, וכמאמרם ז''ל (ספרי ח''א צ''ה) שהראה ה' למשה פורענות שעתיד להביא ואמר לפניו רבונו של עולם וכי הגון הוא שתתן להם בשר ותהרגם וכו' עד כאן:
@431 **למה הרעות וגו' ולמה וגו'**. קשה למה התחיל בתרעומת הנזק ואחר כך בתרעומת מניעת התועלת שהיה צריך לומר למה לא מצאתי חן וגו'. ולמה הרעות וגו'. אכן הכוונה היא על פי דבריהם ז''ל (שם צ''א) בפסוק לך נחה את העם שאמר הקדוש ברוך הוא למשה בני סרבנים הם טרחנים הם וכו' מקללים אתכם סוקלים אתכם באבנים וכו' עד כאן לשונם, ועל זה בא מאמר משה כאן **למה הרעות** פירוש הטלת עלי הרעה הזאת לסבול רעות בניך, ואחר שקבלתי היה מן הראוי למצוא חן בעיניך לתת לי עוזר לישא עמי בעול הגדול ולא כן עשית שנתת עלי כל המשא, ואמר **לא מצתי** חסר א', לומר אפילו מיצוי פירוש דבר מועט מהחן לא השגתי:
@431 **או** ירצה על זה הדרך **למה הרעות** כמו שפירשתי ואומרו **ולמה לא מצאתי** פירוש כיון שנתת עלי עול הדבר הזה יש לי לטעון למה לא מצאתי חן לצד ששמת עלי משא כל העם, ופירוש למ''ד של **לשום** היא למ''ד הסיבה, ואמר זה משה, לצד שראה כי ביקש שלא יתן להם בשר ולא יהרגם כדברי המדרש שכתבנו בסמוך ולא מצא חן בעיני ה' לקבל תפלתו, גם ראה המסובב מהם שהם גרמו לו מיתה במדבר וכמה ענפי היגון אשר סובב לו מהם אשר לא כן היה מן הראוי להשתלם על יגיעו וסבלותו:
@432 **האנכי הריתי וגו'**. דבר בסדר זה, יתבאר על פי דבריהם ז''ל (סנהדרין יט:) שכל המלמד בן חבירו תורה כאלו ילדו, גם אמרו ז''ל (תיקונים ע') שכל נשמות עם בני ישראל דור המדבר היו ענפי נשמתו של משה רבינו והוא היה להם לאב, לזה לא אמר האב אני לעם הזה או אם בני הם, כי כן הוא כפי האמת שהוא היה אב לנשמותם ונקראים בניו גם כן לצד שלמדם תורה, אלא **האנכי הריתי** פירוש כנגד צד היותם ענפיו אמר מה בכך כיון שלא הורה גבר מהם לא יתחייב בטיפולם, וכנגד שנקראים בניו לצד שלמדם תורה אמר **אם אנכי ילדתיהו** כי דוקא בן הבא דרך לידה לא הבא מאמצעות לימוד תורה:
@432 **עוד** נתכוון בכפל **הריתי וילדתיהו** לומר שהמשא שעליו של העם הוא כמשא של אכ ושל אם יחד שדומה לבן שילדתו אמו ומתה שהאב יעשה מעשה האב והאם, ואולי גם כן שרמז לב' זמנים שחייב האב לישא עול הבן, הא' הוא דבר תורה שהוא עד בן שש עד בן שבע (כתובות סה:), והב' מדברי סופרים עד בן י''ג שנה (שם מט:) והגם שעדיין לא תקנו חז''ל תוספת זמן זה, הוא ענין מושכל לדעת אנוש ומכל שכן משה שהיה נביא, ותמצא שאמרו רז''ל (יומא כח:) קיים אברהם אבינו אפילו עירובי תבשילין הגם שעדיין לא תקנום כמו כן ידע נביא ה' מתקנת חז''ל, ואמר על ב' הזמנים **האנכי הריתי** כנגד חיוב התורה, אם **אנכי ילדתיהו** כנגד חיוב דבריהם, ופירוש תיבת ה''א של האנכי היא ה''א ההנחה פירוש שמתרצה משה להתחייב במה שחייב האב לבן ואפילו חיוב של דבריהם ואף על פי כן הנה אלה אנשים גדולים המה למעלה מזמן הקצוב ולמה אתה אומר אלי שאהו בחיקך לאדם גדול בשנים לו יהיה שהם בני הריני פטור מהם, ועוד חוזר וטוען לו יהיה שידון בהם דין קטן לצד שהם מושללים בהשגת המזון ודינם כקטן אף על פי כן לא מתחייב לעשות מה ששואלים ממני לתת להם בשר, והוא אומרו **מאין לי** בשר פידוש בשלמא אם היו שואלין מזון הצריך יתחייב מדין אב אבל הם שואלין מותרות, ועוד הגם שהם מותרות אם היה לו על האב לשעשע בנו כפי יכלתו אבל מאין לי וגו':
@434 **לא אוכל אנכי לבדי וגו'**. כאן החליט הרצון, כי לא תרעומת לבד הוא מתרעם אבל יסכים לשאת, אלא גילה דעתו ורצונו שאינו רוצה לישא לבדו, ונתן הטעם לא ח''ו שממאן עשות מאמר ה' אלא ששיער שהוא משא כבד ממנו ולא יוכל שאתו:
@435 **ואם ככה את עושה לי וגו'**. פירוש חש כי יאמר ה' אליו לשאת בעל כרחו הגם שלא יוכל על מנת כן יעבוד ה' עד יציאת נשמה דכתיב (דברים ו) בכל נפשך, לזה אמר **ואם** וגו' **הרגני נא** פירוש עתה מסר נפשו ולא ישא עוד המשא לבדו, ונתן הטעם **ואל אראה ברעתי** פירוש דבר הגורם רע לנפש שעליו יקפידו הצדיקים, והרעה אשר עליה צעק לבו היא שאם יהרגוהו ישראל יתחייבו כליה ונמצא שגרמו לו להענישם, גם לזה יחשב תחלואי הנפש על דרך מאמר (משלי יז) גם ענוש לצדיק וגו', וכפל לומר **הרגני נא הרוג** לומר שהרוג הוא אם לא יהרגהו ה' כי ודאי שיהרגוהו ישראל, ואם כן כשה' הורג אותו אינו הורג אלא אדם הרוג גברא קטילא קטיל, ותיבת הרוג נדרשת בניקוד שור''ק ורז''ל אמרו (ילקוט כאן תשל''ה מדרש תהלים כג) וז''ל אם לא אתן הם הורגים אותי ואם אדבר כנגדך אתה הורגני, והכתוב יכוין לכל הדרכים:
@436 **אספה לי וגו' מזקני ישראל**. ולא אמר אספה לי וגו' ע' זקני ישראל, ירמוז למה שאמרו ז''ל (במד''ר פט''ו) שהע' זקנים שאסף במצרים נהרגו כולן עם חור, לזה אמר אליו שיאסוף ע' אחרים מזקני ישראל, ואמר תיבת **לי** שיתכוין בדבר לשמו יתברך כדי שלא יטעהו השטן בזקן שאינו נכון, וכשיהיה לשמו ית' שומר מצוה לא ידע דבר רע:
@436 **עוד** נתכוון שאסיפתם תהיה לה' שיקבלו המינוי והשררה מה' על ישראל ולא ממשה. עוד ירצה שיאמר להם הגם שזקנים הראשונים נהרגו לא ימנעו עצמם הם מגשת אל המינוי הגם שיהיו נאספים פירוש נהרגים לי לשמי, כדרך אומרו (תהלים מד) כי עליך הורגנו:
@436 **זקני העם ושוטריו**. פירוש שהם בעיני העם נחשבים ויכולין לרדות בהם ויחרדו למאמרם, והוא מאמר **ושוטריו**:
@437 **ואצלתי מן הרוח וגו'**. טעם סדר זה, להראותו כי ה' נתן בו כח שיכול שאת משא כל העם וכשמאן חזר ונטל ממנו מה שצריך לבאים לשאת עמו במשא העם:
@437 **ולא תשא אתה לבדך**. כאן החליט ממנו החזרה פירוש שהגם שיחזור משה לומר אשא לבדי אמר ה' אליו לא תשא אתה לבדך. עוד רמז לו שבאמצעות הדבר לא תשאר הנשיאות והמעלה למשה לבדו, והוא מאמר **ולא תשא** לשון נשיאות ראש לא תהיה לבדך כבתחלה. שוב בא לידי מאמר חז''ל (במד''ר פט''ו) וזה לשונם אמר הקדוש ברוך הוא למשה אני נתתי לך בינה ודעת לפרנס את בני ותתיחד אתה באותה גדולה עכשיו משלך הם נוטלים עד כאן. עוד יתבאר לסברת האומרים (סנהדרין יז.) ולא יספו לא פסקו, ובזה **ולא תשא** לשון נבואה כאומר (מלאכי א) משא דבר ה' פירוש לא תהיה אתה נביא לבדך אלא יהיו כל הזקנים נביאים ג''כ:
@438 **התקדשו למחר וגו'**. טעם שלא נתן עד מחר לפי דבריהם ז''ל (ספרי כאן) שדרשו בתיבת התקדשו וזה לשונם הזמינו עצמכם לפורענות עד כאן. לזה לא רצה ה' לתת להם תכף ומיד עד שהודיעם כי פורענות הוא נותן להם בנתינת הבשר והתרה בהם והאריך להם זמן ואמר עד **למחר** ובזה יהיה להם הלילה לחשבון הנפש אולי ישובו בתשובה וינחם ה' על הרעה כי לא יחפוץ ה' להשחית עמו:
@438 **ואכלתם בשר**. אמר **ואכלתם** בתוספת וא''ו לדבריהם ז''ל (ספרי) שאמר להם הכינו עצמיכם וכו', כפי זה יוצדק לומר ואכלתם כי הוא הודעת ענין נוסף על הראשון התקדשו לפורענות ועוד ואכלתם בשר:
@438 **כי בכיתם וגו'**. משמע כי יקפיד ה' על הבכי וצריך לדעת מה כיעור יש בבכי מצד עצמו, ונראה כי טעם ההקפדה הוא לצד שהבכי יורה על חסרון המוחלט בשלילת ההשגה שאם לא כן היה להם לשאול מה' כבן השואל מאביו את אשר תאוה נפשו, וממה שבכו יורה כי הדבר מוחלט אצלם כי ה' אין לו כח ח''ו לתת שאלתם, והוא מה שדקדק לומר **מי יאכילנו** לומר אין מי שיוכל עשות דבר זה, וכן תמצא בו שאמרו רז''ל (ספרי) שאמרו ישראל אין כח וכו', וזו כפירה ביכולת היכול על כל ברוך הוא ועיין בפסוק שאחרי זה:
@438 **באזני ה'**. פירוש שלא חשו לדבר כדברים האלה הגם שה' שוכן בתוכם והמדברים מרגישים ויודעים כי שומע שוכן בתוכם, ויש בזה חציפות גדולה עד מאד לומר דברי כפירה באזני ה' ועיין בפסוק שאחר זה:
@438 **כי טוב לנו וגו'**. צריך לדעת כוונת אומרו תיבת **כי כי**, גם אין לה שיעור נכון בקוטב לשון הנשמע, ואולי שיודיע הכתוב כי כל כך עצמה תאות הבשר עד שבחרו במצרים לאכול בה בשר. עוד יתבאר הכתוב על זה הדרך **כי בכיתם באזני ה' לאמר** פירוש טעם הבכי שהשמעתם לאזני ה' הוא מי יאכילנו בשר זה היה בגדר המאמר, אבל רוח הקודש בוחן לבותם יודע כי חפצם בתכלית הדברים הוא כי יותר טוב להם מצרים, כי בוחרים ארץ מצרים משבת בשכונת השכינה, ולזה חרה אף ה' בהם ואמר הזמינו עצמיכם לפורענות, ובזה תמצא נחת רוח במאמר ה' שאמר לבסוף **יען מאסתם את ה' אשר בקרבכם** וגו' ולא מצינו שהוזכר זה בדבריהם, ולפי מה שפירשנו יתיישב על נכון, גם ידוייק אומרו מאסתם **את** ה' ביתרון תיבת את, כי נתכוון לומר שמאסו להיות עם ה' השוכן אתם וחושקים בארץ מצרים:
@438 **ונתן ה' לכם בשר ואכלתם**. צריך לדעת למה חזר לומר הדברים שאמר בסמוך, עוד שלא הספיק במאמר ונתן וגו' ואמר **ואכלתם** והלא מובן הוא הדבר שיאכלו הניתן להם, ונראה שיכוין הכתוב לומר להם שהגם שאמר התקדשו למחר וגו' ופירשנוהו שבא לומר שיחזרו בתשובה ולא יהיה פורענות ולזה נתן להם זמן עד מחר, כל זה יהיה קודם נתינת הבשר להם אבל אחר שיתן להם הבשר לא תועיל החרטה והתשובה להם שלא יאכלוהו, והוא מאמר **ונתן ה' לכם בשר** אז **ואכלתם** צריכין אתם לאכול בחיוב, ובדרך רמז כפל לומר כן לרמוז להם שאם יחזרו בתשובה גם כן על כל פנים יאכלו בשר כי יצא דבר מלך שלטון, והם לא הבינו הדברים, או הבינו ולא הצדיקו:
@439 **לא יום אחד וגו'**. טעם אורכן של דברים, והכוונה בהם, לפי מה שפירשנו במאמר ואכלתם בשר כי מצות מלך הוא לחייבם לאכול, ולצד שיש לך אדם שתשלים תאותו באכילת בשר ביום אחד, ויש בב', ויש בה', ויש בי', ויש בעשרים, ויאמר האדם הנה השלמתי תאותי ולא יאכל עוד, לזה בא דבר מלך להמשלים תאותו ביום אחד כתב אזהרה לא יום אחד, ולהמשלים תאותו בב' באה עליו האזהרה ולא יומים, וכן כולם, והגביל להם ל' יום בחיוב האכילה כדי שימאסוהו והיה לזרא בטבע אנושי תמורת התאוה בו, ומעתה כל המבטל מאכילתו יום א' הרי זה עבר על לאו ובטל מצות עשה:
@441 (כא~כב) **ויאמר משה וגו' הצאן ובקר וגו'**. נפלאו ממני הדברים ממי שאמרם שאין נכון ליאמר כזה אפילו מאדם שלא הכיר גדולת אלהי ישראל ומכל שכן לאיש האלהים, ורז''ל (ספרי) מהם חשבו לו לחטא, ומהם אמרו כי על מפלתן של ישראל יתפלא למה יומתו שש מאות אלף וגו' בשביל הבשר, והדרשה תדרש, אבל על כל פנים צריך ליישב פשטן של דברים, עוד צריך לדעת למה חזר לומר הדברים הנאמרים **ואתה אמרת בשר אתן**. עוד צריך לדעת מה תמיהא היא זאת **הצאן ובקר** וגו' גם בלא נס יש להם מקנה ליזון ממנו חודש ימים, ומקרא מלא דבר הכתוב (שמות יב) וגם ערב רב וגו' וצאן ובקר וגו'. עוד צריך לדעת למה הגזים כל כך בכל דגי הים שצריך כל דגי הים להסתפק מהם חודש ימים והלא כל העולם אוכלים דגים שהם כפלים כל כך פעמים על שש מאות אלף שהיו ישראל:
@441 **אכן** יתיישבו הכתובים בב' דרכים. האחד כשאמר ה' אליו שיתן להם בשר סתם הבין משה משמעות הדברים כי מין אחד של בשר יתן להם, לזה אמר לפניו **שש מאות אלף** וגו' פירוש ומנין רב כזה ימצא בהם דעות שונות, זה יחפוץ בשר צאן, וזה יחפוץ בקר, וזה איל וצבי, וזה עופות, וזה דגים, **ואתה אמרת בשר אתן להם** משמע מין בשר א', מה היא הבשר שתתן, **הצאז ובקר** וגו' ומצא להם פירוש מבוקשם, **אם את כל דגי** פירוש מיני דגים וגו' **ומצא** להם פירוש מבוקשם, הלא כשתתן להם בשר צאן ובקר יאמרו חפצים באיל וצבי, וכשתתן להם איל וצבי יאמרו חפצים בבשר עופות, וכשתתן להם עופות יאמרו דגים, ורשם ב' קצוות הבשר צאן ובקר וקצה האחרון בשר דגים והדרגות אמצעיים שבין בשר צאן ובקר לבשר דגים מובנים, ואמר **כל דגי הים** פירוש שלא יועיל במינים מהדגים אלא אם יביא כל מיני דגים שבים שזולת זה המין החסר יבכו עליו, ומעתה אין סתימת פיהם זולת כל מיני בשר בהמה וחיה וכל מיני עופות וכל מיני דגים המספיקים להם חודש ימים, נמצאת אומר שעיקר הפלאתו היתה לצד שהבין מדברי ה' כי מין אחד של בשר, ואין הכי נמי אם היה אומר שיתן להם כל מינים שבעולם של בשר לא היה מתמיה, ובזה נתיישבו כל הדקדוקים ודברי משה חן, ועיקר כוונת משה בזה אולי ימנע מתת הבשר ולא ימותו בני ישראל כי ה' תלה זה בזה:
@441 **ודרך** ב' על פי דבריהם ז''ל (ברכות נח.) שאמרו אין הקדוש ברוך הוא עושה נס לשקר, ולצד שאמר ה' אליו שהבשר הוא חרבם כמאמרם ז''ל (בפ' כ') בפירוש רש''י והיה לכם לזרא שכן קורין וכו' לחרב זרא אם כן לא על הנם מדבר הכתוב אלא שיאכלו מבשר הנמצא ועל זה תמה שאין נמצא להם לאכול שלשים יום, ומאמר **בשר אתן להם** שנראה שיתנו מחדש פירוש הוא שיתן להם רשות לאוכלו, לצד שעד עתה לא היה להם רשות לאכול ממקניהם והיו לעבודת ה' ואמר ה' כי יתן להם רשות לאכול בשר, ומאמר **אם את כל דגי הים** פירוש לצד שהיו להם דגים מהבאר שהיתה הולכת עמהם אבל לא היה להם הסתפקות אפילו ליום אחד בחודש, כששיער משה דבר הצריך לס' ריבוא ל' יום שיער שכל דגים שיכולין להיות שם בנמצא לא יספיקו, ובדרך נס כבר אמרנו שסבר שלא יעשה ה' נס לתכלית דבר רע כמו שכתבתי, ולדרך זה תמיהת משה תמיהא ואין עליו אשמת דבר כי אינו עושה חסרון ביכולת ה' חם ושלום:
@443 **היד ה' תקצר וגו' היקרך דברי וגו'**. יתבאר על פי ב' הדרכים שכתבנו, לדרך הא' שפירשנו שתמיהת משה היתה כי לא יסתפקו כלם במין בשר הניתן להם ותרעומתם עומדת לעד, הודיעו ה' כי יש יכולת בידו לתת מין בשר שימלא כל תאותם בו, והוא מאמר **היד ה' תקצר** פירוש לתת במין בשר אחד די סיפוקם כל אשר יתאוו כל המתאוים, ואומרו **עתה תראה היקרך דברי** פירוש דבר אחד שאני עושה או דיבור אחד שאמרתי לעשות יהיה יקר כל כך שיש בו הסתפקות לכל חלקי התאוות שיכולין להיות, שיתן להם מין בשר שיש בו כל מיני בשר שיכולין להיות בעולם, ושיעור תיבת **יקרך** הוא יהיה יקר אצלך כשתראה יקר הפעולה, או יתפרש **יקרך** יהיה לך ממנו יקר כשיתן ה' על ידי משה מין הבשר שאין כמוהו יהיה למשה יקר וגדולה בעיני ישראל להאמין בו ובנבואתו ויתיקר בעיניהם:
@443 **ולדרך** ב' שכתבנו שתמיהת משה היתה לחושבו שהבשר שממנו ישבעו בני ישראל הוא מהנמצא אבל מהנם לא יעשה נס לדבר כזה, אמר ה' אליו **היד ה' תקצר** פירוש האם נכון שיד ה' ח''ו תקצר, ואם כן אם לא נעשה הנס יאמרו כי לא תגיע יד עליונה עשות מבוקשם, ולזה יחפוץ ה' עשות נם שלא כסדרו בשביל חילול ה', ולזה גמר אומר **עתה תראה** במה שאני עושה תראה **היקרך דברי** וגו' פירוש יהיה יקר בעיניך מכאן והלאה דברי פירוש דבר הנוגע לי לכבודי כשתראה שאני מקלקל השורה ועושה נס לשקר בשבילי שלא יחללו שמי מזה תדע שיעור הקפדתי על הדבר אם גדול או קטן הוא, ותמצא רז''ל (קידושין מ.) שהפליאו לומר בענין חילול ה' שהקפדתו גדולה:
@444 **ויצא משה וידבר וגו'**. הקדים הדברים אל העם ואחר כך אסף הזקנים אשר לא כן מצינו בסדר דברי ה' אליו שהקדים אסיפת זקנים ואחר כך ואל העם תאמר, לצד שדן בדעתו כי דעת עליון היא להקדים מאמרו לישראל, שאם היתה כונתו להקדים האסיפה לא היה לו לצוות לו מאמר העם, אלא הרי זה מגיד שיקדים מאמר לעם ואחר כך יאסוף הזקנים לאהל ויעשה כל האמור בענין:
@444 **וטעם** אשר הקדים ה' מאמר האסיפה, לצד שבזה היתה תשובה לדברי משה שאמר לא אוכל לבדי לשאת את כל העם, לזה הקדים להשיבו על דבריו תחילה ואחר כך ציוהו לדבר אל בני ישראל, וידע ה' כי משה חכם לידע הצריך להקדים כמו שכן השכיל עשות. עוד אפשר לומר כי מאמר **וידבר אל העם את דברי ה'** הם דברי אסיפת הזקנים לבד, וחשב עד אשר יגמור מה שצוה ה' באסיפת הזקנים ויצא לדבר אל העם מאמר ב' ואל העם תאמר, וגם מדברי מדרש תנחומא משמע כן:
@445 **וירד ה' וגו' וידבר אליו**. צריך לדעת מה דבר ה' אליו, עוד צריך לדעת למה הוצרך לכל זה ולא ניבא אותם מבלי כל סדר המוכן ויתבאר הענין על פי מאמרם ז''ל בספר הזוהר (פנחס רכ.) בפסוק לכן אמור הנני נותן לו את בריתי שלום, כי יצו ה' על משה שיאמר הנני נותן וגו', והטעם מפני שזכה כבר משה בברית השלום ושלו יחשב וכשרצה ליתנו לפנחם נמצא שכבר נתנו למשה וזכה בו ואין הקדוש ברוך הוא חוזר ונוטל מתנותיו, כמו כן הנבואה נתן למשה למנה וכל הבא להתנבאות משה הוא הנותן מהטעם הנזכר, ולזה יקרא אדון הנביאים, והוא מאמר ה' כאן שצוה לאסוף הזקנים והוא עמהם וירד ה' בענן, ואומרו **וידבר אליו** פירוש לשון שררה וממשלה כדרך אומרו (תהלים מז) ידבר עמים תחתינו שעשה ה' השררה בדבר זה אליו פירוש למשה וברשותו וברצונו האציל וגו':
@445 **ויאצל מן הרוח**. אומרו **ויאצל**, אולי שרומז למקור רוח הנבואה שבבחינה זו, ובדרך זה יוצדק לאמר ויאצל, ואומרו **מן הרוח אשר עליו**, פירוש מאותה הבחינה שעליו, אבל הנאצל בא מהמאציל ברוך הוא ולא שיוציא ממשה וליתן על אחרים. או יאמר **מן הרוח** אשר על משה ואמר **ויאצל** לצד שאין הבדל לרוח שעודנו עליו לרוח הניתן ממנו לזקנים, ולדרך זה יכוין במאמר **אשר עליו** על החלק הנאצל בעצמו שעודנו עליו אחר ויאצל, ולדברי המדרש (במד''ר פט''ו) כשמנה המעלות שהיו לב' יותר מהע' מנה גם כן שהשבעים נבואתם משל משה והב' משל הקדוש ברוך הוא:
@445 **ויהי כנוח**. אמר **ויהי** לשון צער, לדבריהם ז''ל (שם) שהזקנים התנבאו מאמר התקדשו למחר, אין לך צער גדול מזה שאמרו לישראל בתחילת נבואתם יכינו עצמן לפורענות, ואומרו **ויתנבאו** בתוספת וא''ו, לומר שמלבד שהיו כלי מוכשר לנוח עליהם הרוח עוד להם שהתנבאו, והודיע הכתוב שנבואתם היתה תכף ומיד כאומרו כנוח עליהם וגו' ויתנבאו. עוד יתבאר על פי סברת האומרים ולא יספו שלא נתנבאו אלא אותו יום על זה הדרך ויהי כנוח וגו' לשון צער כנזכר ועוד צער אחר להם שהתנבאו ולא יספו:
@446 **וישארו שני אנשים וגו'**. צריך לדעת א' כוונת מאמר וישארו מנין נשארו. ב' למה הוצרך להזכיר שמם. ג' אומרו **ותנח עליהם** וגו' ממה נפשך אם הם מהע' הרי כבר הזכירם הכתוב בכלל הע' דכתיב ויאצל וגו' ויתן על ע', כי מאומרו ותנח משמע דבר חדש שלא הוזכר עד עתה, ואם אינם מהע' הלא לא אמר ה' אל משה אלא ע'. ד' אומרו **והמה בכתובים** אין ידוע הכוונה בזה. ה' אומרו **ולא יצאו** הלא מאומרו וישארו במחנה מובן הדבר שלא יצאו. ו' אומרו **ויתנבאו** לבסוף שהיה לו להסמיך הנמשך להם בפני עצמו והנעשה מהם בפני עצמו על זה הדרך וישארו ב' אנשים וגו' והמה בכתובים ולא יצאו האהלה ותנח עליהם הרוח ויתנבאו, ולמה כתב הדברים שלא כסדר הנכון:
@446 **ורז''ל** נחלקו (ספרי) מנין נשארו, יש אומרים נשארו מהע''ב שברר משה מישראל ו' מכל שבט בשוה והגריל להוציא הב' היתרים על הע' שאמר לו ה' והם הב' שנשארו, ורבי שמעון אמר כי מהע' נשארו שלא רצו ליכנם לאהל מועד לצד ענוה ושפלות ונשארו במחנה ע''כ. לסברת האומר מהע' נשארו יתבאר הכתוב עז''ה וישארו ב' אנשים במחנה לצד חושבם עצמן כשיריים, **שם הא'** וגו' פירוש ידועים היו במדות ישרות ומוחזקים בעיני ישראל שלסיבה זו נשארו במחנה, שזולת זה יש לעם לרנן אחריהם שמאסו ח''ו בנחת הרוח עליהם ונמצאו מחללים ה' וימאסם עליון לסיבה זו, אלא לצד ששם האחד המיוחד אלדד ושם השני לו מידד לזה לא דנו בהם המעשה להרע, ובזה לא נמאסו ותנח עליהם הרוח עצמה שנחה על הע' לא מנעתם ההרחקה שהיתה בין אהל מועד ובין המחנה ונחה גם עליהם, ודקדק לומר **ותנח**, לומר ששם קנתה מקומה הרוח כאומרם ששאר הע' פסקו ואלו לא פסקו נבואה מהם, וקודם שהזכיר הנבואה הזכיר דברים שבהם יצדיקו העם כי דברי נבואה בפיהם אמת, ואמר **והמה בכתובים** פירוש מאותם הע' שנכתבו, וכדי שלא תחשוב שהכתובים הם שנכתבו בפתקי הגורלות, לזה אמר ולא יצאו האוהלה הא למדת שהיו יכולין לצאת, ובזה נאמנו דבריהם שהיו נבואה והוא אומרו **ויתנבאו**, וזולת התנאי הנזכר מי יחזיק דבריהם לדברי נביאות, ובזה נתישבו כל הדקדוקים:
@446 **ולדברי** האומר מהע''ב נשארו יתבאר הכתוב על זה הדרך **וישארו** פירוש הגם שנשארו ב' האנשים שהיו יתרים על הע' במחנה, **שם האחד** וגו' אף על פי כן ותנח עליהם הרוח גם כן מלבד שנחה על הע' כמו שאמר למעלה ויאצל מן הרוח וגו' ויתן על ע' איש וידוייק על נכון למה הוצרך לומר ותנח עליהם הרוח לצד שלא הזכיר בפסוק ראשון שנתן הרוח אלא על הע' הודיעך ה' שגם נחה על הב', ואמר **והמה בכתובים** וגו' בא לתת טעם להצדקת נבואתם כמו שפירשתי למעלה ואמר והמה בכתובים פירוש בפתקים שכתב משה ע''ב זקן, ומעתה הרי ראוים הם לנבואה כיוצא בע' ויכול להיות שיתנבאו, וכדי שלא תבין שהמה בכתובים שבאו האהלה לזה בירר הכתוב ואמר ולא יצאו בפתקין לבא האהלה:
@446 **ודרך** דרש אולי שיודיע הכתוב שהב' שלא יצאו בפתקין נכלמו ונכנסו במחנה מה שלא עשו כן כל ישראל שיצאו כולם לאהל מועד והב' נחבאו במחנה, וירא ה' בושתם וכלימתם ויתנבאו, והוא אומרו **והמה בכתובים** שהן הפתקין ומטעם זה ולא יצאו מהמחנה, וחננם ה' ומילא תאותם ויתנבאו:
@447 **וירץ הנער וגו'**. צריך לדעת למה נתרעש המגיד להגיד שנתנבאו, ועוד לו שרעש עליהם לתתם בבית כלא וכי כל המתנבא נענש על שניכא וזה מן התימה, ויש לתת טעם לסברת האומר שהיו ב' שנשארו בפתקין, כי לצד שאמר משה לישראל על פי ה' שיתן רוח נבואה על ע' ועכשיו נבאו גם הב' יש לחוש לא' מב' דברים, או לא יאמן משה ח''ו במאמרו שאמר לו ה' ע', או המתנבאים נבאו שקר, ולסברת האומר כי היו מהע' הגידו למשה המעשה הבלתי הגון שהוא אמר שילכו לאהל מועד והם עמדו במחנה ונבאו שם, ויש בזה שתים רעות, א' שלא קיימו דבר משה, והב' שבזה גילו דעתם שלא רצו שתאצל עליהם הרוח מרוחו של משה אלא ממקור הרוח ומתנבאים במ ח נה:
@448 **ויעז יהושע וגו' כלאם**. צריך לדעת על מי סמך יהושע להורות לפני רבו, ומה גם להורותו כה וכה תעשה, וזה מהזרות, ורז''ל אמרו (עירובין סג.) כל דמותיב מלה קדם רביה אזיל בלא ולד שנאמר ויען יהושע וגו', ואפשר לתת טעם למעשה יהושע על פי דבריהם ז''ל (ספרי) שאמרו וזה לשונם מה נבואה אמרו משה מת יהושע מכניס עד כאן. לזה כששמע יהושע הדברים בחר לדבר לפני רבו כדי שיגלה דעתו כי מאוסים הדברים אצלו ואומריהם וכי שקר בפיהם, ובזה שלל החשד כי יחפוץ הוא בדברים הנאמרים למעלתו וגילה ההפכיות ברצונו:
@448 **ואמר** אדוני משה **כלאם** פירוש תן אותם במשמר עד אשר יבא דבר מלך משפט עשות, או כלם מן העולם, וטעם הדבר בין לסברת האומר חוץ מהע' בין לסברת האומר מהע' מהטעמים שכתבנו, ואולי שרמז באומרו **אדוני משה**, שאינו חפץ היות הוא אדון אלא היות לו אדונו משה לשלול הרצון בנאמר כי ימות משה והוא יכניס, וידויק גם כן מאמר **ויען** שעשה תשובה לדברים הנאמרים עליו בנבואה ההיא כי לא דברו נכונה וצריכין לינתן בבית כלא, ואף על פי כן ענשו הכתוב, כי סוף סוף השיב דבר בפני רבו:
@449 **המקנא אתה לי וגו'**. לסברת האומר שהיו מהע' ירצה על זה הדרך המקנא אתה בשביל כבודי שלא רצו האנשים לבא לקבל הנבואה ממני, מי יתן כל עם ה' נביאים ולא יהיו מקבלים הנבואה ממני אלא מה', כאלו, והוא מאמר **כי יתן ה' את רוחו עליהם** בלא אמצעות משה, כי שם מקור הענוה והחלט העדר ההקפדה, ולסברת האומר מהפתקין ירצה על זה הדרך המקנא אתה לי פירוש למאמרי שאמרתי ע' ונבאו ע''ב, מי יתן את וגו', והטעם כי יתן ה' את וגו' פירוש שהע' שאמר ה' שיושפעו מרוחו של משה הוא בתחילה קודם שהתחיל ה' לנבאות את אחרים זולת משה. אבל אחר שהאציל ה' רוחו של משה ונתן לע' הותרה נבואה לכל כי יתן ה' את רוחו עליהם, ואין כאן הכחשה בנבואת משה:
@456 **ותדבר וגו' במשה**. אולי שדברו בפניו של משה, והדעת מסכמת בזה גם כן, כי מה יועילו דבר לא טוב ביניהם לבין עצמן, אלא אמרו דבריהם דרך תוכחה והוא שומע מלתם, שוב ראיתי בדברי רז''ל (ספרי) שאמרו כן ורמזוהו במאמר וישמע ה' והאיש משה וגו' פירוש גם הוא שמע:
@457 **הרק אך במשה**. רז''ל אמרו (ב''ר פ''א) אכין ורקין מיעוטין, וכאן נתכוונו לומר בזה שמעשה משה ירשום הפגם בהם גם באבות העולם אשר דבר עמהם ה', וכן הוא במדרש (ספרי) וזה לשונם והלא גם עם האבות דבר עד כאן. ועוד אפשר שנתכוונו לרמוז ב' מיעוטים שהיו בנבואת משה, א' שלא נתנבא עד שהיה בן פ' שנה דכתיב (שמות ז) ומשה בן שמונים שנה בדברם אל פרעה ובאותו זמן הוא שדבר אליו ה' ואהרן ומרים נתנבאו בני ג' וה' קודם שנולד משה, ומיעוט ב' שביום שנתנבא נצטרע דכתיב (שם ד') והנה ידו מצורעת וגו' מה שלא היה כן להם, וכנגד זה אמר הרק אך:
@457 **וישמע ה'**. הוצרך לומר **וישמע ה'**, לומר שלא שמע אלא ה' הכוונה בזה שלא דברו בפני בריה, עוד נתכוין לומר שמהם שמע ולא ממשה, שלא קבל לפני ה' כדרך הנעלבין מזולתם:
@458 **והאיש משה ענו**. הודיע הכתוב זו כאן, לפי מה שכתבנו שדברו בפניו נתן הכתוב טעם שהוצרך ה' לעשות כל האמור בענין, מטעם כי האיש משה עניו מאוד ולצד ענוותו נמנע מהשיב להם התשובה המתחייבת לבא בענין כדי שידעו ההפרש שבין נבואת משה לשאר נביאים, ודקדק לומר **מכל האדם אשר על פני האדמה**, להחליט מניעת התשובה ממנו בענין כי אדם שבדעתו הוא למטה ח''ו מכל אשר על פני האדמה איך ישוער ח''ו שיאמר תשובה שיצא ממנה שהוא גדול מכל הנביאים, ולזה בא מאמר מה' והשיבם **פתאום**. לצד שאינו (לשון אונאה) משה בדברים וכתיב (עמוס ז) הנה ה' נצב על חומת אנך, ורז''ל אמרו (ילקוט) פתאום סמוך לזיקה וכו':
@458 **אל משה וגו'**. טעם קריאת משה, לדבריהם ז''ל (שם) שאמרו שהיו טמאים, קרא למשה כדי להכיר תולדות הפרישה שפירש משה שנמצא מוכן לדבר ה' אליו באין מונע אשר לא כן הם שקראם ה' ולא יכלו לצאת, ולפי הפשט כדי שיהיה מוכן משה להתפלל על מרים. עוד טעם קריאת משה לצד שנתכוין ה' לגלות להם תיכף ומיד בסדר הקריאה כי גדול משה מהם ממה שהקדימו להם בקריאה והשמיעם הדבר ובזה ירגישו סתירה למחשבתם שאמרו הרק במשה הלא גם בנו וגו':
@460 **וירד ה' בעמוד בענן**. צריך לדעת למה לא ירד ה' קודם קריאה ראשונה, שנראה מסדר הכתובים שלא ירד אלא אחר קריאה, גם ממה שאמר בקריאה צאו שלשתכם אל אהל מועד זה יעיד שעדיין לא ירד, שאם לא כן לא היה צריך לרשום להם המקום כי הם רואים מקום אשר ישכון שם הענן, ולדבריהם שכתבנו שהיו טמאים בשעת הקריאה יש טעם נכון בדבר, כי לא רצה ה' לרדת קודם הקריאה ויהיה יושב וממתין להם כביכול לצאתם, ואינו מהכבוד, גם ימשך להם ח''ו עונש לנקראים ואין הקדוש ברוך הוא חפץ להעניש אלא להטיב, והטעם שירד ה' ולא דבר ממקומו כסדר הקריאה, כדי לפרסם הדבר כשיראו שירד הענן ועמד פתח האהל והוא פרסום והערה גדולה ויודע לכל ישראל כי הקפיד ה' על אשר נגעו בנאמן ביתו והענישם על הדבר:
@461 **שמעו נא דברי**. צריך לדעת למה הוצרך לומר כן ודאי כי ישמעו את אשר ידבר, עוד צריך לדעת אומרו תיבת **נא** כי לא יוצדק לומר האדון לעבדו לשון בקשה. אכן יתכוין ה' בנועם אמריו להרגישם במניעת השמיעה שקודם לכן, כי עתה הם ראוים לשמוע ולא קודם לצד טומאתם לדבריהם ז''ל, וממוצא דבר אתה יודע כי אין נכון לעבד שיהיה מושלל ההכנה בעת אשר אדונו יצוה עליו, ואוזן מילין תבחן כי מוכרח משה במעשיו לפרוש מאשתו, ולדרך זה הרווחנו תירוץ לקושיא א', למה לא נתן ה' טעם הפרישות בדבריו להם כי הוא העיקר הצריך להשמיעם, ולפי זה ה' נתן אומר המבשר צבא רב:
@461 **עוד** ירצה על זה הדרך **שמעו נא** פירוש עתה אתם שומעים לצד ההכרח ליסרכם ולהוכיחכם, ואין לדבר לכם דברים אלו ע''י משה מב' טעמים א' כי הוא נוגע בדבר ועליו באו הדברים, ועוד מהטעם עצמו האמור בענין שקרא ה' לאהרן ומרים לדבר עמהם שלא בפני משה, אבל קודם ואחר כך אין אני מדבר עמכם, וזו סתירה למאמרם שגם בהם דבר, ותמצא שאמרו ז''ל (במד''ר ס''פ נשא) שבכל המקומות שאמר הכתוב וידבר ה' אל משה ואל אהרן אין הכונה בדבר גם עם אהרן אלא למשה שיאמר לאהרן, והם הדברים שרמז ה' בתיבת נא:
@461 **ודקדק** לומר **דברי** ולא הספיק לומר שמעו נא ומובן שמה שישמעו הם דבריו, נתכוין כן הגם שהיו מתנבאים קודם לא היה כסדר זה שישמעו הדברים מפי אל עליון וכמו שפירש ה' דבריו בסמוך אם יהיה נביאכם ה' וגו':
@461 **עוד** אפשר שרמז להם שלא ידבר עמהם עוד אלא עתה, לבל יחשבו בדעתם כי הוכשרו לנבואה עליונה כזאת והיה כזה יום מחר, לזה אמר עתה. עוד ירצה במאמר **נא** לצד שהיו טמאי קרי ובדיני טהרת טומאה אמרה תורה (ויקרא כב) שאין הטבילה גומרת הטהרה לאכול בתרומה עד הערב שמש, וענין הנבואה כיון שמצינו כי צריך האצלת הרוח הקדושה כדי שיוכשר לדבר ה' עמו לא יספיק טהרת מים עד בא השמש וטהר, שלא יהיה זה גרוע מטהרה הצריכה לאכילת תרומה וכאן מצינו שביום עצמו שהיו טמאים טומאת קרי סמוך לטבילתם דבר ה' עמהם, לזה אמר ה' **שמעו נא דברי** פירוש עתה דוקא הוראת שעה היא שאשמיעכם דברי הגם שעדיין צריכין הערב שמש, לקיים מה שנאמר (ב''ר נה) אהבה מקלקלת השורה אהבת ה' עם משה ידידו לא יכול להתאפק עד למחר:
@461 **אם יהיה נביאכם וגו'**. ולא דבר לנוכח אליהם אם תהיו נביאים, לצד שהם הזכירו בטענתם נביאים אחרים חוץ מהם וכמאמר המדרש (ספרי) שאמרו הלא דבר גם עם אברהם ולא פירש וכו', לזה בא דברו יתברך לעשות הפרש גם מהנרמז בדבריהם למשה, ואולי כי לזה אמר לשון יחיד אם יהיה:
@461 **ה' במראה אליו וגו'**. בא להודיענו הפרש הדרגת הנביאים מהדרגת משה, ולצד שיש ג' דברים בענין הנבואה, א' השגת המראה, ב' זמן השגתה פירוש אם יתנבא בכל עת שירצה או אין הדבר תלוי ברצונו אלא בזמן שיחפוץ ה', ג' השגת בחינת הדיבור כאשר אבאר, והתחיל ה' לומר בבחינת הדרגת השגת הראיה, ואמר ה' **במראה אליו אתודע** פירוש לפי שיש ג' הדרגות כלליות בהכרת ה', הא' לא השיגה אדם בנבואה והוא מה ששאל משה (תשא לג יח) הראני נא את כבודך פירוש נא עתה מה שאתה עתיד להראותני לאחר מיתה, כי יודע היה משה המושג לצדיקים בעולם העליון, והשיבו ה' לא תוכל וגו' כי לא יראני האדם וחי אלא לאחר מיתה, והדרגה זו היא בעצמות אורו יתברך, והגם שלא יתייחם אליו מאמר עצמות אלא לשכך אוזן וכו', הדרגה ב' היא אור המאיר ממנו ית' שיתייחס אליו תמונה, ואין תמונה זו דומה לשום תמונה מההוים בנמצא, כי אין לו תמונה אלא תמונה לנעלם מעיני כל חי שאין לה מכיר זולת משה אשר הכיר' לו ה' דכתיב ותמונת ה' יביט, מה שלא השיג זולתו בכל הנביאים, הדרגה ג' היא הבהקת אורו ית' ברחוק, הא למה זה דומה לנר דלוק אשר ילך אורו למרחוק ויראה אדם האור ההוא, וזה יקרא מראה, וזה הוא השגת הנביאים זולת משה, והוא מאמר ה' במראה והבן, וכנגדה אמר במשה ותמונת ה' יביט:
@461 **וכנגד** זמן השגת הנבואה אמר **אליו אתודע**, פירוש אפילו מדרגה קטנה כזו אינה אצלו בתמידות בעת אשר יחפוץ ישיגנה, אלא כשאני רוצה אתודע לו בה, וכשיחפוץ הוא להשיגה אינו מובטח שישיגנה בכל עת, כמו שהוא מובטח משה בכל עת אשר יחפוץ דכתיב (ט' ח') עמדו ואשמעה מה יצוה ה' בלא שום ספק בדבר, נמצאת אומר כל הנביאים אין נבואה בטוחה אצלם הגם שהיא מדרגה קטנה ממדרגת משה, ומשה נבואתו הגם שהיא גדולה מהם בטוחה אצלו בכל עת שירצה, והוא מאמר **בכל ביתי נאמן הוא** פירוש כנאמן הזה שהכל בידו וברשותו לעשות כל אשר יחפוץ כמו כן משה, ודקדק לומר **בכל ביתי** לכלול אפילו בהשגת נבואה הגדולה הדבר ברשותו להתנבא, מה שלא היה נשמע אם היה אומר בביתי נאמן הוא שהייתי אומר שאין הדבר מסור לחפצו אלא מדרגה הקטנה של כל הנביאים, וההפרש הוא שהם אין הדבר ברשותם מה שאין כן הוא תלמוד לומר בכל וגו':
@461 **וכנגד** השגת בחינת הדיבור אמר **בחלום אדבר בו**, פירוש דע כי ב' מדות בהודעת החלומות, הא' כשישמע הדברים תהיה דעתו מעורבבת ולא תבחן אזנו מילין להשכיל הנדבר כי דעתו מבולבלת, ב' כל הנדבר בחלום אין הדברים כפשטן אלא משל ודמיון, וצא ולמד מחלומות הכתובים בתורה ופתרוניהם, והוא מה שאמר ה' כי הנביאים בעת בא דברו הטוב להם יתבלבל דעתם ויהיו כאדם השוכב בלב ים ויתהוללו, גם לא יבא להם הדיבור בצורתו אלא מלובש תוך דמיון ומשל כדי שיוכלו שאת הדיבור ואף על פי כן מתהוללים, ופירוש תיבת **בחלום** הוא בגדר חלום באיכות ומהות, ולעולם בהקיץ היה ה' נגלה אל עבדיו הנביאים, אלא כשהיה בא להם הדיבור היו מקבלים אותו כתכונת החלום כנזכר והיו נופלים לארץ ומתטרפת דעתם מעליהם, מה שאין כן משה שהיה מושלל מזה שלא היתה דעתו משתנית בבא דבר ה' והיה שומע בדעת שלימה, גם לא היו באים אליו הדברים בדרך משל ומליצה אלא דברים מבוארים וברורים ואינן צריכין פתרון, והוא מאמר ה' **פה אל פה אדבר בו** פירוש הנה עיני כל ישראל רואות הג''ן פרשיות אשר דבר ה' אל משה שכלן הם דברים שיבין פשטן של דברים כל מבין לשון הקודש, גם אוצרות חכמה אשר אצר ה' בהם כולם נכוחים למבין הבא לעיין ולהעמיק ירגיש במשמעות הכתובים עצמן את אשר חשב ה' לומר בהם, ואין דרך זה בדברים אשר דבר ה' ביד עבדיו הנביאים ירמיה וישעיה שכלן משל ומליצה, כמאמר (יחזקאל יז) הנשר הגדול בעל הכנפים וגו', וביותר מהמה נבואת זכריה המסגר שערי הנבואה אשר סגר גם נבואתו ואין אתנו יודע כוונת נבואתו:
@461 **ויש** לחקור זאת כיון שהמנבא הוא ה' אלהינו אחד למה לזה ידבר נכוחות ולזה דברו מעקשים, ואמרו אנשי אמת במה שקדם לנו הידיעה בדבר המלאך לדניאל ההרגש שהיה פועל בו מזה תשכיל לראות כי הרכבת מין האנושי תפסידנה הרגשת הרוחני ואינה יכולה לסבול זולת המורכב אשר כונן ה' בחכמתו הנפלאה שיוכלו שתוף יחד הנפש והגוף, והלא תראה אפילו במקורות הנרגשות ונתפסות אש ומים זה מכלה את זה זולת השמים אשר כוננו ידי יוצר, ומזה תשער איך יוכל עמוד בדבר אלהים מקור הרוחניות ויחצוב קולו להבת אש איך יוכל עמוד, ולזה אין אדם משיג לעמוד בכוחו לשמוע קול אלהים חיים זולת האיש אשר הפך חומרו ועשאו צורה כמו שרשמנו במקומות אחרים שזה אין לו גוף ויכול שאת דבר מלך, ולכן בהנבא ה' לאדם שאין גופו דומה לצורתו יתחכם ה' עשות על זה האופן, כי יצא דבר מלך מפי עליון והדיבור יתעטף באוירים דקים ואחר כך יגיע לאוזן נביא ובזה יסבלנו הנביא, ואף גם זה יפעיל הרגש בנביאים להשתגע, ודבר זה יסובב בא הדברים דרך משל ומליצה בבחינת החלום:
@461 **ולזה** כל הנביאים לבד ממשה ידברו משלים ומליצות ויותר מהמה זכריה שהיה אחרון בנביאות היה הדיבור בא ונגלד ונגלם ביותר משאר נבואות כדי שיוכל לסבול, ולזה נתרבו בו המליצות ועומק הדמיון עד שאין דורות אחרונים יודעים דבריו, והוא מה שהודיע ה' כאן בבחינת המושג למשה ואמר **פה אל פה** פירוש לא היה הדיבור נפסק מפי אל עליון לפי משה לעבור באויר העולם שישתנה הדיבור בהלבשת האוירים ויסובב לדבר דברי משלים וחידות, גם שלל ההתרגשות אשר תקרה לנביאים כמאמר **ומראה** פירוש לא ירדם ולא יתבהל אלא ומראה פירוש בעת ובשעה עצמה שאני מדבר בו פה אל פה אינו כסדר החלום אלא ומראה שאני מראה לו אור המנבא ומביט, וזה יגיד ההערה והתכוננת השכל:
@461 **ואומרו ולא בחידות**, הוא להעיר בתולדת הדבר כי לצד שהיה מדבר פה אל פה בזה היה גם כן הדיבור יוצא בלא חידות, ודקדק לומר **אל פה** ולא לאוזן, המשכיל על דבר נביא שאמר (מ''א ג') לב שומע ידע סוד הדבר, וזו היא הדרגת נבואה שאין למעלה ממנה שיקשור ה' נפש נביא במקור המנבא וישלשל הנבואה פה אל פה, ובזה גם כן תבין אומרו **אדבר בו** ולא אמר אתו או עמו אלא בו והבן. עוד נתכוון להשכילך שלא היה הדיבור אלא מפי ה' לפי משה ולא היה רואה פני עולם, והוא מאמר בו:
@463 **ומדוע יראתם וגו'**. פירוש חוזר ה' וטוען שהיה להם לשער בדעתם כי הוא עומד ומשמש לפני ה', ואם היה עושה עול לא היה ה' מסכים על ידו, אמור מעתה בה' דברתם שהסכים על ידו, והוא אומרו **מדוע** וגו' **בעבדי**, ואומרו **במשה** פירוש אדם שהוא מובחן לגדול בעיני ה' תחשדוהו בדבר מגונה, ואפשר שרמז עוד להם באומרו **במשה** על שדברו בפניו והכלימוהו בדבריהם כמאמר רז''ל שכתבתי למעלה (בפסוק א'):
@464 **ויחר אף ה'**. פירוש גירה בהם הנחרים בהם שהם כת האף, **וילך** כדי שיעשה האף מה שהורשה, והגם שבסנה אמר הכתוב (שמות ד') ויחר אף ה' במשה, שם רשם שיעור אשר יפעול בו האף והוא שיסור ממנו כח הנשמה שהיא בחינת הכהונה ותנתן לאהרן כמאמר רז''ל (זבחים קב. שמו''ר פ''ג) שהרושם הוא הסרת הכהונה, וכאן עשה האף משפט גדול שהצרעת היא כמיתה כאמור בענין, ובשניהם היה העונש כאומרו **בם**, וכן אמרו רז''ל (ספרי) ויפן וגו' פנה מצרעתו, אלא שמרים לא נתרפאה כאהרן תכף ומיד, ולא ידע אדם מצרעתו:
@465 **והנה מצורעת**. לא היה צריך לומר הדבר אחר שכבר אמר והנה מרים מצורעת וגו' ולפי דבריהם ז''ל (ספרי) שאמרו שגם אהרן נצטרע ירצה לומר הנה היא עדיין מצורעת ולא פרחה ממנה כאהרן ואמרו עוד חז''ל (שם) שדוקא כשהיה פונה היתה מצורעת וכשהיה מחזיר פניו היתה פורחת ממנה, ולדבריהם צריך לומר כי משה לא היה מביט במרים לדעת מה היא, שאם לא כן ממה נפשך קשה והבן:
@466 **בי אדוני אל נא תשת וגו'**. הנה מדברי אהרן משמע כי משה הקפיד על דבריהם אשר על כן מחלה פניו שימחול להם חטאתם, ונראה כי טעמו של אהרן הוא שדן במשה דין חכם, שכפי הדין (קידושין לב:) חכם שמחל על כבודו כבודו מחול, ולזה אמד בדעתו שאם ימחול סר הנגע, ואמר **אל נא תשת** וגו' פירוש הגם שהקפדת על הדברים עד שבא העונש עתה שבא העונש יכופר העון ולא תשת עוד עלינו חטאת, ואחר האמת לא כן הוא כי משה לא הקפיד על הדבר, ולזה נתחכם הכתוב וסמוך לדברם בו אמר והאיש משה עניו מאוד נתכוון לשלול דברי אהרן כאן, וטעם העונש הוא לב' סיבות, הא' שיש לנו לדון במשה משפט מלך, שכן כתיב (דברים לג) ויהי בישורון מלך, ומלך שמחל על כבודו אין כבודו מחול (שם), ואולי כי לזה גם כן נתכוון ה' במאמרו להם **מדוע לא יראתם לדבר בעבדי** כי לה' המלוכה ועבד מלך מלך (שבועות מז:):
@466 **וסיבה** ב' לפי מה שפירשתי שהקפיד ה' על שחשדו שעשה משה עול ח''ו והסכים ה' על ידו ולא הוכיחו, אם כן מילין לצד עילאה הם, ולזה הענישם הגם שאין כאן הקפדת משה, והצדיק משה כי לא הוא הסובב בהקפדתו שהוצרך להתפלל לה', ואף על פי כן לא הועיל לרפאות עד עבור שבעת ימים, ואם היה הדבר בו לא היה צריך לתפלה אלא ימחול וסר הנגע, הא למדת שהעונש בא לא' מב' הטעמים, או לשניהם יחד, ואפשר שאם היה משה מקפיד בדברם היה העונש באופן אחר כפול ומכופל להם ח''ו:
@466 **אשר נואלנו ואשר וגו'**. הכוונה בב' עניינים, הוא על פי מה שפירשתי בתרעומת ה' עליהם שהקפיד על שהשוו נבואתם לנבואת משה, והקפיד על שנגעו בכבוד משה לומר לא טוב עשה, לזה אמר כנגד השואת נבואתם לנבואתו אמר **אשר נואלנו** כי דברו דברי שטות בזה, וכנגד מה שאמרו עליו לא טוב עשה אמר **ואשר חטאנו**:
@468 **ויצעק וגו' לאמר**. טעם אומרו **לאמר**, בא בטענה כדי שלא יאמרו שהקפיד ויחזיקוהו כנוטר איבה, ודברי אהרן יגידו למו, לזה אמר בצעקו לה' בשביל שלא יאמרו דברים הנאמרים בסמוך מפי אהרן:
@468 **עוד** ירצה כי אמר לפני ה' קודם התפללו שהוא מוחל על כבודו ואחר כך התפלל אל נא וגו':
@468 **אל נא** נתכוון לשאול ממדת החסד כאומרו (תהלים נב) חסד אל, נא לשון בקשה ופיוס לעורר הרחמים, **רפא נא** פירוש עתה ולא יתעכב:
@469 **ואביה ירוק ירק וגו'**. הלביש שיעור הדברים בה ולא אמר האב אם ירוק בפני בתו וכו', לומר שהיא במדרגת בת שהיא מדרגת הצדיקים, וכפל לומר **ירוק ירק**, לומר שאם היה צועק לו קודם לא היה רוקק בפניה, וזה הוא שיעור הדברים **ואביה ירוק** פירוש כשגרמה שירק בפניה ולא היה מי שירצהו שלא לרוק עד שירק והוא אומרו **ירק** פעם ב' וגו', הא למדת שאם היה אופן שהיה מתפלל משה קודם לא היתה נענשת:
@469 **תסגר שבעת ימים**. נראה שפרחה ממנה צרעת בתפלת משה, וכמאמרו רפא נא פירוש עתה, אלא שגזר ה' שתשב כמנודה, שאם לא כן לא היה צריך הכתוב לומר תסגר פשיטא שתסגר עד שתתרפא מצרעתה, אלא ודאי שכבר נתרפאה, ולזה גם כן לא הזכיר טהרת צרעתה ביום אסיפתה, ולדברי רז''ל (זבחים קב, ספרי) שאהרן לא ראה צרעת מרים מטעם קורבה, יתבאר על נכון, כי לצד שאין כאן צרעת כי אין כהן שיאמר טמא אם כן כאן אלא סגירה לבד כמנודה, או אפשר שנסגרה על פי ה' אלהינו שהוא כהן, והוא אומרו **תסגר** וגו' הרי הסגירה, ונטהרה על פי ה' דכתיב **ואחר תאסף**:
@470 **והעם לא נסע**. תלה הדבר בעם ולא אמר ולא נסע העם, להודיע כי העם הסכימו לבל יסעו עד האסף מרים, והגם שהדבר היה תלוי בנסיעת הענן, התורה מעידה כי גם בזכותה הם היו חפצים בעכבה לכבדה, ומה גם אם היה ידוע להם כי בזכותה היה המים להם (תענית ט.) בודאי שישב שם העם על המים:
@470 **חסלת פרשת בהעלותך**
@472 **וידבר וגו' לאמר**. צריך לדעת למה אמר **לאמר** כיון שהדיבור אינו אלא אל משה, ואולי שבא להרשותו לומר שהדברים נאמרו לו מפי השכינה, שזולת זה הרי הוא בבל תאמר (יומא ד:), גם שלא יחשדוהו ישראל כי משה חפץ בדבר ויאמרו כי דעתו כדעתם, לזה יצוה שיאמר להם כי כן צוה לו המלך, גם כדי שישמעו לו לשלוח כסדר הנדבר אליו מה', ולא יעכבו על ידו כשידעו כי דבר מלך הוא, גם לפי דברי רז''ל שפירשו תיבת לך לדעתך שאין ה' מצוה על הדבר, חפץ ה' שיאמר לישראל הדברים כמות שהם מפי עליון אולי ירגישו כי לא טוב עשות ויבטחו בה' ויאמינו בו:
@473 **שלח לך אנשים וגו'**. צריך לדעת אומרו **לך**, ורז''ל אמרו (סוטה שם) לדעתך אני איני מצוך וכו', וקשה למה יסכים ה' על הרעה אשר דבר לעשות לעמו ויופיע מאמרו על עצת רשעים. ולהבין הענין אעיר בדבר, מבטן מי יצא הקר''ח הרעה הגדולה הנסבבת מהמרגלים, אם מצד המעשה, אין בו רע, כי הלא מצינו (יהושע ב) שכמו כן שלח יהושע ב' אנשים מרגלים וירגלו הארץ, אם כן אין הדבר מכוער מצד עצמו, ואם מצד האנשים המרגלים שהיו רשעים, הלא מצינו שנבחרו על פי ה' הבוחן לבות וכליות, והעיד הכתוב עליהם כולם אנשים שהם צדיקים:
@473 **אכן** יתבאר הדבר על פי דבריהם ז''ל שאמרו (ילקוט) וזה לשונם בתחילה נתקבצו אצל משה לשלוח המרגלים ולא רצה ואמר להם כבר הבטיחנו ה', ואמרו לו כי העממים יודעים בנו שאנו באים לירש אותם והם מטמינים את ממונם וכשיגיעו ישראל לא ימצאו כלום ונמצא דברי ה' בטל ח''ו, ואז וייטב הדבר בעיני משה מה שאמרו (דברים א) ויחפרו לנו את הארץ פירוש החפירות שמטמינים בהם סמונם וכו' כיון ששמע משה כך נלכד בידם עד כאן. הנה ממה שדקדקו במאמרם ז''ל ואמרו נלכד בידם יורה שבמרמה דברו ולכדוהו בערמה, ואין ידוע מה היא מרמה שדברו בפיהם שבה נלכד:
@473 **אכן** ב' מיני ריגול הם, הא' הוא ריגול לדעת דרך אשר יעלו בה, גם לדעת אם יטריחו כל ישראל לעלות או חלק אחד מהם, וכמאמר מרגלי העי שהשיבו ליהושע (יהושע ז) אל יעל כל העם כאלפים איש או כשלשת אלפים איש יעלו וגו' אל תיגע שמה את כל העם, וריגול זה לא ירגל אלא את העיר אשר יבאו שמה וכשיכבשוה ויסכימו לצור על עיר אחרת ירגלוה אחת לאחת, וריגול ב' הוא ריגול כללי, זה יורה כי רוצים לראות ולשער אם יש כח בהם לכבוש, והוא הריגול שהסכימו ישראל לשלוח לרגל הוא לכללות ארץ כנען כמו שמפורש במעשה, וזה יגיד מיעוט האמונה בה' וביקוש תואנה, ולזה אמרו במדרש שלא רצה משה עד שנתחכמו במרמה וידברו לו שלצד הטמנת הממון הם שולחים, וטעם זה צודק בכל ארץ כנען ונלכד בידם ושלח מרגלים לתכלית זה כי אין רע בדבר, כמו כן יהושע שלח מרגלים לסיבה הצריכה כמו שכתבתי ואין רע אלא דוקא בטעם ריגול שהיה בדעת ישראל בגניבת דעת משה:
@473 **ולזה** בא דבר ה' אל משה ואמר **שלח לך** פירוש למה שאתה סובר השליחות שהיא בשביל הטמנת הממון פירוש אבל לא לטעם שחושבים הם, והעירו כי לא מחשבותם מחשבותיו, ומשה אפשר שלא הבין הכוונה על סדר והבין דרך אחר כאשר אבאר, או נוכל לומר שהבין אלא כיון שראה שה' לא מנעו מלשלוח עשה מעשה ולא נתחכם על דבר מלך, והגם שה' גילה לו, ה' חפץ לגלות לעבדיו הנסתרות, גם לדעת טעם לכל היוצא מהענין, ואם תאמר קושיא לאלהינו למה לא מנע הדבר מהיות כן, לצד שראה שזולת זה היו פוקרים יותר ועושים בהלה יותר ממה שעשו בהליכת המרגלים:
@473 **עוד** ירצה במאמר לך לצד שהזכירם בלשון חשיבות ואמר אנשים שיורה שהם צדיקים לזה אמר לך פירוש כל עוד שהם לפניך אצלך הם צדיקים אבל כשיחזרו פניהם ללכת בשליחות פקע מהם כלילא, וכמאמר הכתוב (כ''ו) וילכו ויבואו ואמרו ז''ל (סוטה לה.) מקיש הליכתם לביאתם וכו', ומזה הרגיש משה והתפלל על יהושע שלא ילך בעצת רשעים, ולדרך זה יתבאר דברי רז''ל שאמרו (במד''ר פט''ז) וזה לשונם אבל מרגלים ששלח משה רשעים היו דכתיב שלח לך אנשים עד כאן. ואין ידוע כוונתם ז''ל מנין מוכיחים הדברים ממאמר שלח לך שרשעים היו, אלא שדייקו תיבת **לך** כמו שדייקנוה לך הם אנשים אבל בשליחות כשיתחילו בהליכה רשעים הם. עוד יש לומר שפירוש **לך** הוא לך הם צדיקים אבל אני יודע שהם רשעים. ואם תאמר ולמה יסכים ה' לשלוח רשעים, ומה גם שאמר הכתוב על פי ה' ואמרו ז''ל (שם) שהיה הקב''ה אומר פלוני לשבט פלוני, ואולי כי בפרט זה של הריגול כל ישראל שוו בדעת אחת לרגל עד אשר רגלו והוא לראות אם יכולין לכובשם כפי יכולת שהיה בישראל וזה יגיד מיעוט האמונה ולזה יקראו רשעים:
@473 **או** אפשר לצד שכוונת המשלחים היתה רעה תפעיל פועל הרע בשליח ויחזור להיות שלוחו של אדם כמותו ויולד בו תכונה רעה מה שלא היתה בו קודם כדרך שתולד בחינת הקדושה בשלוחי מצוה לטובה אות, ולזה הגם שהיו צדיקים, בהתחלתם עשות ההליכה לרגל נולד בהם תכונה רעה מכח המשלחים ויעצו להדיח:
@473 **עוד** ירצה לומר **שלח לך** שיהיה השליחות מתכנה על שם משה ולא על שמו ית' לצד מה שיצא מהדבר:
@473 **עוד** ירצה לומר להם שלא תהיה כוונת הליכתם למה שחושבים ישראל אלא למה שחושב משה בשליחות, והוא מאמר **שלח לך** למה שבדעתך ולא למה שבדעתם:
@473 **עוד** רמז במאמר **לך** על פי מה שאמרו ז''ל (שמו''ר פ''ה) בפסוק עתה תראה אבל במלחמת ל''א מלכים אינך רואה עד כאן. מעתה אם היו ישראל נכנסים לארץ בשנה השנית ליציאת מצרים והיה מתקיים מאמר ה' שאמר עתה תראה היה מוכרח משה לישב חוץ לארץ כהדיוט או יכנס לארץ ישראל הדיוט, ובאמצעות שליחות המרגלים נתעכבו ישראל מ' שנה ולא ירד משה מגדולתו ויהי בישורון מלך מ' שנה עד מלאת ימיו, והוא אומרו **שלח לך** כי לך הנאה בזה בתכלית הדברים:
@473 **ויתורו את וגו'**. קשה אומרו **ויתורו** שהיה לו לומר לתור וגו', עוד קשה אומרו **אשר אני נותן** וגו' אחר אשר הזכיר שם המקום לא היה צריך לומר אשר אני וגו' כי מי לא ידע שהוא נותנה להם. אכן לפי מה שפירשנו שהתנה בשליחות תנאי הראשון לך פירוש למה שהוא חושב שיהיו שלוחי משה ושאר הפירושים שפירשנו בה, והוסיף עוד תנאי אחר אנשים שצריך שיהיו צדיקים, עוד בא והוסיף תנאי אחר בדבר שהריגול הוא **אשר אני נותן** לבני ישראל פירוש לא לשער אם הארץ ההיא יש כח בהם ללוכדה ולרשת אנשיה כי זה ודאי כי אין יכולת בהם לעמוד אפילו כנגד עיר קטנה שבהם, אלא **אשר אני נותן**, וכיון שהדבר ההוא בא להם במתנה על הנותן להוציא עושקיה כדין הנותן מתנה, והוא ילחם להם ויעמידנה בידם באין שטן ואין פגע רע, גם ישכילו בריגולם אשר יפליא ה' להשפיל רמים עם גדול ורם רבים ועצומים כדי שבעל הנם יכיר בניסו, ובזה נתחכם ה' בחסדו והרים מלפניהם מכשול כשיראו עמלק וגו' וילידי ענק וגו' ועוצם חוזק הערים הבצורות לבל יפחדו ויראו כי אין ירושתם בכח ישראל אלא בכח הבורא אשר הכל יוכל כי הוא הנותן:
@473 **וזה** הוא מאמר **אשר אני נותן**, ובמתק לשונו גילה כי כפי הטבע אינם יכולין להם כמו שאמרו המרגלים אחר כך, ובזה נתישבו הדקדוקים. אלא שנשאר לחקור זאת למה לא הספיק לומר ויתורו את הארץ אשר אני נותן ולא היה צריך להזכיר **ארץ כנען**, וראיתי לרז''ל (ילקוט) שהרגישו בהערה זו ואמרו שבא לרמוז אל זכות הגורם המתנה והוא זכות יצחק שנולד לאברהם ושרה אברהם בן מאה שנה ושרה בת צ' שנה שהוא במספר השנים של שניהם ק''צ, וזה דרך דרש, ונראה לומר כי נתכוון לומר המאמר עצמו שאמר משה לישראל במשנה תורה (דברים ט) לא בצדקתך וגו', כי ברשעת הגוים וגו', והוא מה שהזכיר כאן כשאמר אני נותן ארץ **כנען** לומר לצד שהיא ארץ כנען אשר נתמלא סאתו לזה אני נותן:
@473 **תשלחו**. ולא הספיק במאמר שלח שבתחילת הכתוב. אולי שבא לעכב שלא ילכו אלא בסדר זה איש א' וגו' ולא יותר ולא פחות:
@487 **אלה שמות האנשים**. צריך לדעת למה חזר לומר כן והלא כבר אמר ואלה שמותם וגו' ויתבאר על פי דבריהם ז''ל (סוטה לד:) שאמרו וזה לשונם אמר ר' יצחק דבר זה מסורת בידינו מאבותינו מרגלים על שם מעשיהם נקראו וכו' סתור בן מיכאל שסתר דבריו של הקדוש ברוך הוא וכו' עד כאן. והנה לצד שרצה לומר הכתוב ויקרא משה להושע בן נון יהושע שהתפלל עליו וכו' יאמר האומר מה ראה משה להתפלל על יהושע, לזה הקדים לומר **ואלה שמות** האנשים וגו' להעירך כי משמותם השכיל משה מעשיהם הרעים אשר לזה הוצרך להתפלל על יהושע ויקרא וגו', ולזה סמך למאמר אלה שמות וגו' ויקרא משה וגו', והגם שכתבתי למעלה שהרגיש ברשעם ממאמר תיבת לך, אין פירוש זה מוכרח ויש לפרש תיבת לך באופן אחר ומשמותם הטה והכריע כי ירשיעו בשליחותם, עוד אולי שלא הצדיק שכולן רשעים אלא משמותם שכל שמותם גילו מה שעתידין לעשות:
@487 **ויקרא משה וגו'**. רז''ל אמרו (שם) שהתפלל עליו, וצריך לדעת למה שינה שמו ויכול היה להתפלל בלא שינוי השם. ואולי שנתן כח בשמו בתוספת היו''ד שמספרה עשרה כדי שיוכל נגד העשר מרגלים, עוד כדי שיטול זכות וחלק הטוב של כל העשרה כמאמרם ז''ל (חגיגה טו.) זכה נוטל חלקו וחלק חבירו:
@488 **וישלח אותם וגו'**. צריך לדעת למה הוצרך לומר כן אחר שכבר זכר השליחות ב' פעמים וישלח אותם וגו', אשר שלח משה, ואולי שיודיע הכתוב שעשה להם לויה, ונתן הכתוב טעם הלויה ואמר **לתור** וגו' שהוצרכו לשמירה לפי שהלכו לדרך סכנה. עוד ירצה שנתכוין בלויה לדרך אשר יתורו שכן משפט הלויה:
@489 **וראיתם וגו' מה היא**. פירוש לפי שיש ארץ שהבלה ואוירה זך ובריא וממזג הטבעיות ויש שאוירה עכור ומעופש ומתנגד למזג הטבעיות, גם יש ארץ שהיא מלאה מעיינות ומימיה נקיים ומולידים מזג טוב באדם ויכונן הכוחות ויש להפך, ואלו הם דברים שישנם בארץ מצד עצמה בלא סיבה אמצעי, וכנגד דברים אלו אמר וראיתם את הארץ **מה היא** מצד ברייתה אם היא בגדר הרצון או להפכו, ולצד כי חקירה זו יש בה בחינות שישנם בהבחנה להם בדרך עברתם בה, ויש דברים שצריכין נסיון כמו שתאמר אם מחזקת טבע האנושי אם מימיה מפרים ומרבים, דברים אלו אינם ניכרים בדרך העברה ולזה צוה להם **ואת העם** וגו' פירוש מהפעולות יודעו הכוחות מהעם היושב בה יתגלה כח הארץ אם העם חזק או רפה, ולצד שיש מקום לומר שאין מבחן מחוזק העם כי יש במה לתלות והוא כי הם גודרין עצמן מהתשמיש, לזה אמר **המעט הוא אם רב**, גם בזה יגלה כי מימיה מפרים ומרבים:
@489 **עוד** ירצה בהעיר למה שינה סדר שלקח הכתוב בכל ההדרגות שהקדים בהם חלק הטוב ואחר כך הזכיר חלק הרע, **החזק הוא** ואחר כך הרפה, **הטובה היא** אם דעה הקדים הטובה, וגם מבחן החזק הוא חלק הטוב לדעת טובת הארץ שמגדלת חזקים, וכן במאמר האחרון הקדים לומר **השמנה היא** ואחר כך אם רזה, וכמו כן **היש בה עץ** ואחר כך אמר אם אין ולמה כשהזכיר המיעוט והריבוי הקדים לומר המעט הוא אם רב, והיה נראה לומר כי גם במבחן זה הקדים חלק הטוב והוא שאם הם מועטים הוא יותר טוב לישראל, וזה אינו כי לא יסתפק בטובה שיודע החלט שלילתה:
@489 **אכן** הכוונה היא על זה הדרך **המעט הוא** וגו' פירוש חוזר למאמר החזק הוא וגו' אם חוזק העם הוא דבר גדול שמעטים הם כיוצא בהם אם רבים כיוצא בהם בעולם, וכפי זה הקדים חלק המעולה לשבח הארץ שאין כמותה מגדלים חזקים בכל הארצות, או לצד הכרת הנם גם כן כמו שכתבתי, ולדרך זה לא תקשה למה הפסיק בענין במאמר ואת העם וגו' באמצע עניני הארץ שהרי אחר כך הוא אומר ומה הארץ וגומר, ולדברינו בענין הארץ הכתוב מדבר:
@490 **ומה הארץ אשר וגו'**. פירוש כנגד פרט הנעשה באמצעות הזולת שהם בנייני העיר והדירות והכלים אם טובה היא בבנין מפואר אם רעה בבנייניה, ולזה דקדק לומר **אשר הוא יושב בה**, וכנגד פרט זה תמצא שאמר הכתוב בפרשת ואתחנן (דברים ו') והיה כי יביאך וגו' לתת לך ערים גדולות וטובות אשר לא בנית, ומכלל נוי העיר הזכיר גם כן הבמחנים אם במבצרים, ורז''ל דרשו (במד''ר פט''ז) שסימן מסר להם, וזה דרך דרש, אבל פשט הכתוב כל עיקר השאלה אינו אלא על הארץ, אבל העם פשוט הוא שהוא עם גדול ורם בני ענק נפילים ואין ספק בזה לרגל אותם, ולכשנאמר שרמז להם גם על גבורת האנשים תהיה הכוונה לומר להם לראות עוצם גבורתם להכיר בנסי אל אשר ימגן אותם בידם:
@491 **ומה הארץ השמנה וגו'**. פירוש אם נותנת שומן בפירותיה **אם רזה** פירוש אם כשנותנת כחה בפירות אם נעשית רזה מצד זה כדרך הארצות שזורעים אותה שנה ומובירים אותם שנה כדי שלא תהיה כחושה או זורעים אותה שנה אחר שנה ואינה משתנית בכחה ועושה שני כראשון שזה יגיד שאינה נכחשת מצד גידוליה:
@491 **היש בה עץ**. פירוש שם המין אם יש בה כל מין עץ, אם אין פירוש אם יש עץ שאינו נמצא בה, והוא מאמר הכתוב (דברים ח) לא תחסר כל בה:
@495 **למקום ההוא קרא וגו'**. פירוש הקדוש ברוך הוא קודם לכן כתב עד נחל אשכול על שם העתיד כי הוא מגיד מראשית אחרית, ואומרו **אשר כרתו משם** וגו' פירוש ואם תאמר והלא כמה אשכולות נכרתו מהמקום, לזה אמר הפלאת אשכול זה שנקרא המקום על שמו על אודות האשכול וגו' אשר כרתו בני ישראל פירוש כללות ישראל כרתו אשכול זה, והגם שלא היו אלא י''ב אנשים, לצד היותם שלוחי כל ישראל, כאלו כרתו כל ישראל על דרך אומרו (שמות יב) ושחטו אותו כל קהל עדת ישראל:
@497 **וילכו ויבואו וגו'**. קשה למה הוצרך לומר **וילכו** אחר שכבר השמיענו ההליכה, ורז''ל אמרו (סוטה לה.) שנכתבה להקישה לביאה מה ביאה בעצה רעה וכו', וצריך לדעת לאיזה ענין ישמיענו הכתוב דבר זה שהלכו בעצה רעה:
@497 **אכן** יתבאר הענין על פי מה שאמרו במס' קדושין דף ל''ט וזה לשונם תניא רבי יעקב אומר אין לך מצוה וכו' הרי שאמר לו אביו עלה לבירה והבא לי גוזלות ועלה ולקח הגוזלות ושלח את האם ובחזרתו נפל ומת היכן אריכות ימיו של זה אלא לעולם שכולו טוב וכו', והעלה בש''ם שרבי יעקב מעשה חזא, ומקשה ודלמא מהרהר בעבודה זרה הוה, ומשני איהו נמי הכי קאמר אי סלקא דעתך שכר מצוה בהאי עלמא איכא אמאי לא אגין מצוה עליה דלא אתי לידי הרהור עד כאן. משמע דלמאן דאמר שכר מצוה בהאי עלמא איכא תגין מצוה מהיסורין ומהחטא, וקשה דבמסכת סוטה דף כ''א אומר במסקנת הדברים לרבא מצוה אגוני מגנא אבל אצולי לא מצלא ואפילו בזמן עצמו שהוא עסוק בה, וכפי זה במה מוכיח רבי יעקב ממה שלא הגינה עליו המצוה שלא לבא לידי הרהור עבודה זרה, והגם שלסברת רב יוסף שמביא הש''ס בסוטה מצוה בזמן שהוא עסוק בה תגין עליו גם מהעבירות, הלא נדחית סברת רב יוסף מכח קושית דואג ואחיתופל שלא הגינה עליהם תורתם שלא יצאו לתרבות רעה, וכיון שנדחו דברי רב יוסף במה מצדיק הש''ם דחיית רבי יעקב בקידושין:
@497 **ויש** שרצו לחלק בין מעשה מצוה למעשה מצוה, מה שאמרו בסוטה דמצוה לא מצלא מהחטא אפילו בעידנא דעסיק בה מדבר בעושה שלא לשמה, ושם שאמרו אמאי לא אגנת עליהם שלא לבא לידי חטא מדבר במצוה לשמה עד כאן דבריהם, וזה הבל שאם כן היה לו לתלמוד לדחות מעשה הסולם בשלא עשה המצוה לשמה שהיא דחיה יותר קרובה מדחיית דלמא מהרהר בעבודה זרה, גם היה מרויח בדחיה זו שאין להקשות למה לא הגינה עליו מיצר הרע כיון שאין כח באותה מצוה להגין מיצר הרע:
@497 **והנכון** לתרץ הוא דמסקנת התלמוד היא כסברת רב יוסף דמצוה בעידנא דעסיק בה מגנא ומצלא ולזה הוא שמוכיח ר' יעקב ממה שלא הגינה והצילה המצוה על העולה בסולם להביא גוזלות לאביו שהרי גם בחזרה היה שעת מעשה מצוה שהביא גוזלות לאביו, ומה שדחה הש''ס בסוטה סברת רב יוסף ממה שלא הגינה תורה לדואג ואחיתופל אינה דחיה, לפי מה שאמרו בחגיגה (טו:) במתניתא תנא דואג ואחיתופל טינא היתה בלבם פירוש שתורתם היתה שלא לשמה, ומעתה אין הוכחה ממה שלא הצילתם תורתם שהרי לא היתה תורה לשמה, או למה שפירשו שם התוספות שהיו בעלי עבירות קודם שעסקו בתורה וקדמה תורתם ליראת חטאם שבכגון זה אין תורה מצילתם מיצר הרע:
@497 **ועוד** אפילו לסברת הדוחה סברת רב יוסף במסכת סוטה מדואג ואחיתופל לא דחה אלא חלוקת תועלת התורה דאינה מצלת (אפילו) בזמן שאינו עוסק בה אבל מה שאמר מצוה בעידנא דעסיק בה מגנא ומצלא לא דחה הש''ם, והגם דרבא מכח קושית דואג ואחיתופל הוכרח ליישב הברייתא שאמרה תלה הכתוב המצוה בנר והתורה באור וכו' יאמר שאין תועלת במצוה אלא להגין מהצרות, אין הכרח לדבריו ויכולין לומר על זה הדרך מצוה בעידנא דעסיק בה מגנא ומצלא ובעידנא דלא עסיק בה ולא כלום תורה בעידנא דעסיק בה מגנא ומצלא ובעידנא דלא עסיק בה מגנא ולא מצלא, ומה שאמרו אם יש לה זכות תולה זכות תורה שמצלת מהפורענות אפילו שלא בזמן שעוסקת בה, והגם שאין אשה מצווה על התורה, בשכר תורת בעליהן ובניהם וכדברי רבינא שם (סוטה כא.) ולדרך זה מוכיח ר' יעקב מהעולה בסולם להביא גוזלות לאביו שלא הצילתו מצותו בעת שהיה עסוק בה:
@497 **ועוד** כשנעמיק בדבר נעמיד סוגית קדושין אפילו אליבא דרבא, בהעיר מה שאמר הש''ם דלמא מהרהר בעבודה זרה קשה לו יהיה שמהרהר בעבודה זרה היתה המצוה מצילתו מהיסורין כמו שמוכח מסוטה שאמרו אם יש לה זכות תולה, ושם בסוטה זו ודאי קלקלה וקאמר שהזכות ימנע יסוריה ואפילו אליבא דרבא, ושם זכותה מרוחק ומה שלפנינו שהלך להביא גוזלות זכותו לפניו, ולתרץ זה מוכרח לומר לצד שהיה מהרהר בעבודה זרה הרי הוא ככופר בכל התורה והרי הוא כגוי לכל דבריו ואין לו מצוה שתגין עליו, או אפשר כי לצד שבשעת מעשה המצוה הרהר בעבירה אין תועלת במצוה שעושה להגין כל עיקר, ומתרץ דסובר ר' יעקב אי אמרינן דשכר מצוה בהאי עלמא היתה מגינה עליו מבא לידו דבר הסובב פורענות שאם לא תאמר כן אם כן גם מהפורענות אינה מגינה, וגם לסברת רבא שאמר מצוה אגוני מגנא מפורענות מכלל הדבר ההוא שלא יבא לידו עון שיסובב הפורענות, שזולת זה גם מהפורענות אינו מ ובט ח:
@497 **נמצינו** אומרים שלסברת רב יוסף מצוה בשעת מעשה מצלת מיצר הרע, וגם לסברת רבא לתירוץ ב' אם העון יסובב פורעניות בעולם הזה תגין עליו המצוה ממנו, ולזה בא הכתוב כאן לתרץ הקושי' הנרגשת למה לא הגינה עליהם המצוה שהלכו בשליחות מצוה דכתיב וישלח אותם משה על פי ה' להצילם מהפורעניות אשר סובב להם, ואמר **וילכו ויבואו** פירוש להקיש הליכתם לביאתם מה ביאתם בעצה רעה אף כשהלכו בעצה רעה אם כן אין כאן מצוה כל עיקר ואדרבא שלוחי עבירה הם:
@497 **עוד** נראה הטעם שהוצרך הכתוב להשמיענו זה הוא על פי מה שאמרו שם בקידושין אחר שתרץ לסברת ר' יעקב שהיה לו להגין עליו מלבא לידי עבירה חזר התלמוד להקשות והאמר ר' אלעזר שלוחי מצוה אינן ניזוקין ומתרץ סולם רעוע הוה עד כאן. וקשה מה קושיא היא זאת אחר שאמר הש''ס מהרהר בעבודה זרה הוא למה לא יועיל דבר זה גם לתירוץ קושית שלוחי מצוה אינן ניזוקין, אלא ודאי ששלוחי מצוה יש להם תועלת בשליחות המצוה שלא ימשך להם פעולה רעה מהשליחות עצמו, ומשמע מהש''ס שזה דבר מוסכם הוא, ומעתה נתחייב הכתוב לומר **וילכו ויבואו** לעקור מהם שם שליחות מצוה שלא הלכו אלא בעצה רעה ולזה הוזקו בשליחותם:
@497 **ובדרך** רמז יתבאר אומרו **וילכו ויבואו** על דרך אומרם ז''ל (סוטה ג.) בעלי הסוד כי אדם גדול כשיזדמן לפניו עבירה ויגש לעשות פורחת ממנו נפשו הרמה ונכנסת בו רוח שטות ואז יקרב לעשותה, ולצד שהכתובים מעידים שהאנשים ההמה נשיאי ישראל וגדולי הנפש לזה העיד הכתוב כי בשעת מעשה הרע כשבאו למשה לדבר דברי רשע הלכו, פירוש פרחו מהם אורות הקדושות מנשמתם ואז ויבואו:
@497 **עוד** ירמוז במאמר **וילכו** שעשו הליכה מוחלטת בארץ כנען שלא יבואו לה עוד כאשר גילו בדבריהם אשר דברו לעם, גם התורה החליטה עליהם שהליכתם הליכת עולם ולא ישובו לראותה עוד. ואומרו **ויבואו** אל משה וגו' בא לתת טעם למה באו ולא נאבדו בשליחותם, **אל משה** וגו' פירוש חש ה' על דבר כבוד משה אשר על כן השלימו השליחות ובאו. עוד כדי שיראו משה ואהרן והעדה מעשה ה' כי אנשים מעט עלו בין כמה אומות גדולים ועצומים ונמלטו, ומזה יצדיקו כי כמו כן יעשה ה' עמהם להטיל אימתם על כל העמים וישרים דרכי ה' וגו':
@497 **אל מדבר פארן קדשה**. צריך לדעת למה לא הזכיר הכתוב קדשה אלא בחזרה ולא בהליכה. ואולי שרמז במאמר **קדשה** מה שנתעכבו בקדש בסיבת המרגלים דכתיב (דברים א מו) ותשבו בקדש ימים רבים כימים אשר ישבתם, ואמרו ז''ל (רש''י שם) י''ט שנה עשו בקדש וי''ט שנה בחזרה מקדש עד שהגיעו לה פ''ב הרי ל''ח שנה, מעתה בקדשה ובסיבובה נתעכבו כל הזמן שגרמו המרגלים להתעכב במדבר, והוא מאמר ויבואו אל משה וגו' אל כל עדת ישראל קדשה:
@497 **וישיבו אותם דבר**. העלים הכתוב תשובתם הרעה ואמר **דבר** סתם, שאין דרך הכתוב לכתוב מעשיהם של רשעים אלא לצד ההכרח, כמו שתמצא שלא כתב הריגת חור ביום מעשה העגל, וגם מעשה העגל אמרו בגמרא (ע''ז ד:) שלא נכתב אלא ללמד ישראל שאם חטא ציבור אומרים להם כלך אצל ציבור, וכמו כן במה שלפנינו העלים הדברים עד שהוצרך לומר שישראל רצו לשוב למצרים וימרו בה' ח''ו חל עליו לומר סיבת הדבר וגילה דבר שהוציאו דבת הארץ, וטעם שהוצרך הכתוב לומר המראת ישראל, הוא להודיע טעם עכבתם במדבר מ' שנה שהיה לסיבת המראתם ואומר **ואת כל העדה** פירוש שהשיבוהו כשהיה את כל העדה ולא יחדוהו לדבר אליו דברים הרעים בפני עצמו שנתכוונו להבאישו בעיני כל ישראל:
@497 **או** ירצה על זה הדרך **וישיבו אותם דבר** האמור בסמוך, ובא הכתוב להודיע שחלקו כבוד למשה ליחד לו התשובה כחוק המלוכה ואחר כך השיבו גם לכל העדה:
@497 **או** ירצה על פי מה שאמרו ז''ל במאמר שכתבנו בפסוק ראשון שנלכד משה בידם בטענת ויחפרו לנו את הארץ וגו' עד כאן. אמור מעתה שטעם שליחות ישראל היה טעם בפני עצמו וטעם שליחות משה היה טעם בפני עצמו, לזה אמר הכתוב **וישיבו אותם דבר** למשה ואהרן לדברים שאמר להם בשליחותו ואת כל העדה לדברים שאמרו להם בשליח ותם:
@498 **ויספרו לו וגו'**. דקדק לומר **לו**, שהיו מייחדים הדיבור ביחוד אליו, אבל המאמר לא היה למשה לבד אלא לכל העדה השומעים, והוא אומרו **ויאמרו** ולא אמר לו:
@498 **באנו אל הארץ וגו'**. פירוש שהגענו שמה לשלום ולא אירע להם תקלה, וגמרו אומר הטעם **אשר שלחתנו** פירוש לצד שעשינו מצות שליחותך נשמרנו. או ירצו לומר לצד שעשה להם לויה ששלחם היא שעמדה להם לבוא אל הארץ בשלום. ואולי כי לזה דקדק לומר **ויספרו לו** לומר שספרו דבר הנוגע למעלת משה כי זכותו עמדה להם, ואומרו **ויאמרו** הוא תשובת הארץ מה שנוגע לכללות ישראל לזה לא אמר לו:
@498 **וגם זבת חלב ודבש וגו'**. אומרו וגם לצד שקדמה הודעה במדה טובה שנעשה להם נם בהליכה מוסיפין להודות גם בטובת הארץ כי זבת חלב וגו':
@499 **אפס כי עז וגו'**. פירוש לפי שבשליחות משה שאל החזק הוא וגו' הבמחנים וגו' לזה אמרו כי העם חזק ובמבצרים יושב, וגמרו אומר **וגם ילידי הענק** וגו' פירוש שלא לחשוב כי בצרו עריהם לצד חולשתם הרי גם ילידי הענק ראינו שם ואלו אין להם פחד ודאי אם כן אין ללמוד ממבצריהם שחלשים הם:
@499 **עוד** ירצה באומרו **העם היושב בארץ** כי העם היו יושבים נפוצים חוץ לערים והיו סומכין על גבורתם, וכן תמצא שאמרו ז''ל (במד''ר כאן) בפסוק עמלק יושב וגו' והכנעני וגו' שהיו יושבים בדרך חוץ לעיר, גם רמזו במאמר **היושב בארץ** שהארץ צריכה גבורי כח לעמוד בה:
@501 **ויהס וגו' אל משה**. פירוש לפי שאין כח באדם הדיוט להשתיק המון שש מאות אלף לזה בא במאמרו כי הוא משתיקם אל משה ולא לגזירתו, וידוע כי משה מלך דכתיב (ברכה) ויהי בישורון מלך ולאימתו שתקו לשמוע אשר יאמר, ואמר **עלה נעלה וירשנו אותה**, פירוש גם לפי דברי המרגלים נוכל לה:
@502 **האנשים וגו'**. פירוש השיבו לדברי כלב ואמרו לא נוכל וגו', והוסיפו לומר דבה בארץ לומר שהגם שהיו יכולין לירש אותה מאוסה היא לצד שאוכלת יושביה וגו':
@503 **וכל העם וגו'**. פירוש ואף על פי כן אוכלתם הארץ, או ירצה בדקדוק אומרו **בתוכה** לומר כל שנתקיימו בתוכה הם אנשי מדות ובזה יוכלו חיות, אבל כל שאינם אנשי מדות עומדים חוצה לה לבל תאכל אותם הארץ:
@503 **ונהי וגו' וכן היינו בעיניהם**. הודיעו בזה כי אפילו שאר האנשים הרגילים שם אינם דומים להם, והראיה כי התפלאו בהם שהם כחגבים לצד הפלאת מיעוט גופם, הא למדת שאותם הרגילים עמהם אינם בדמיון זה:
@505 **ותשא וגו' ויבכו העם**. אומרו **העם** ולא הספיק במה שזכר הנושאים קולם, לומר כי לא כל העדה בכו בלילה ההוא אלא חלק מהם הגם שבכללות כלם נשאו קולם לדברי המרגלים אשר הפליאו להפחיד. עוד יתבאר על פי דבריהם ז''ל (סוטה לה. תענית כט.) שאמרו וזה לשונם אמר הקדוש ברוך הוא אתם בכיתם בכיה של חנם אני אקבע לכם בכיה לדורות עד כאן. והוא מאמר הכתוב **ותשא כל העדה** וגו' פירוש שהיתה אז וזה גרם לעם בכיה בלילה ההוא לדורות, ואם אמר הכתוב ויבכו בלילה היו חוזרים הדברים לעדה הנזכרת אשר שמעו דברי המרגלים:
@506 **וילונו וגו' כל בני ישראל וגו' כל העדה**. טעם כפל זכרון המלינים, גם שינוי הזכרון, לצד שכללות ישראל היו בכלל המלינים אבל דברים שבאו בטענה היו מפי כללות העדה הראוים לדבר בטענה עם משה ואמרו סדר בחירת הרע, חלוקה ראשונה לו מתנו בארץ מצרים, וזה נמנע מהם שכבר יצאו, ובחרו ברעה יותר ממנה שימותו במדבר, וזה ישנו במציאות כי ימיתם במדבר, למה ה' מביאם למדרגה רעה יותר למות בחרב ולשבות נשיהם וגו', וגמרו אומר **הלא טוב** פירוש אם ה' לא ימיתם במדבר מסכימין לשוב מצרימה שאפשר שלא ימיתום מצרים ותהיה נפשם להם לשלל, ולא פחדו שיגזור ה' עליהם וימיתם במדבר ולא יגיעו למצרים כי זה הוא מבוקשם כאומרו או במדבר הזה וגו':
@510 **ויהושע וגו' מן התרים את הארץ**. הוצרך לומר שהיו מן התרים, לתת טעם לקריעת בגדיהם, כי האומר מי אתם יהושע וכלב לעשות מעשה זה מה שלא עשו כל גדולי ישראל, ואמר הטעם כי לא היה לצד שהחשיבו עצמן יותר מכל גדולי ישראל אלא לצד היותם מן התרים שתרו אותה וראו מעלתה ועשו ההרגשה, גם נתכוון בזה לומר כי נתכוונו בקריעתם זו כדי להרעישם לומר אלו תרו אותה וקרעו בגדיהם על מאיסתה בעיני ישראל ויכחישו דברי הממאנים:
@511 **ויאמרו לאמר**. אומרו תיבת **לאמר** אחר שאמר אל כל בני ישראל. אולי כי לצד שגם המרגלים גם הם אמרו ארץ זבת חלב וגו' שהוא שבח הארץ וכוונתם היתה להרע להצדיק מאמר הדופי, לזה העיד הכתוב כי יהושע וכלב נתכונו לרומם ולפאר הארץ, ותיבת **לאמר** כאן לשון רוממות על דרך אומרו (פ' תבא) האמרת והאמירך:
@511 **טובה הארץ וגו'**. נתכוונו לסתור דברי המרגלים שאמרו ארץ אוכלת וגו', ואמרו טובה מאד מאד בין בענין פירותיה בין ביישובה, וכנגד הפלגת המניעה אמרו אם חפץ וגו' ונתנה בתורת מתנה לא בכח יגבר איש וגמרו אומר לחמנו הם:
@512 **אם חפץ בנו ה'**. נתחכמו לדבר בלשון ספק, כדי שיניחו להם לגמור הדברים כי יאמרו שאין דבריהם אלא לגדר האפשרות ולא בבחינת ההחלט ולזה הניחום לומר כל הדברים ובגמרן אמרו לרגום, וכאן הבן שואל למה לא רגמו על תחלתן של דברים שהרי אין בדבריהם האחרונים תוספת ושינוי מתחילת דבריהם, אלא לצד שבתחילת דבריהם אמרו אם, היו יושבים ומצפים גמרן של דברים וכשעמדו בהן אמרו לרגום:
@512 **ארץ אשר וגומר**. כאן גזירת מאמר אם חפץ:
@512 **היא זבת חלב ודבש**. פירוש **היא** ולא אחרת כיוצא בה, והמרגלים אמרו זבת חלב ודבש היא אין תיבת היא מופלגת מהארץ שוללת מציאות כיוצא בה אלא לזכרון אשר עליו בא מאמר זבת חלב ודבש:
@513 **ואתם אל וגו'**. פירוש כל הפלגות המורא ישנו בערך זולתכם אבל לא אתם, ודקדק לומר וא''ו של ואתם לרמוז אפילו אחר שהצדיקו דברי המרגלים ודברו דברים בלתי הגונים:
@513 **כי לחמנו הם**. טעם שהוציאו הדבר בלשון לחם, יתבאר על פי דברי אנשי אמת שחקרו במעשה ה' אשר עשה בהרכבת הבעלי חיים שכל חי אוכל ושותה, שהיה ה' יכול עשות שיתקיימו בעלי חיים בלא מאכל, והנה לפניך מין בריה ששואפת רוח והיה לה למזון, ואם ככה היה ה' עושה היו ישראל נפנים לעסק התורה ולמצות, גם היו נמנעים מכמה מעשים בלתי הגונים אשר יסובבו מצורכי המחיה והכלכלה, ולזה הייתי מתרץ מעצמי כי רצה ה' לזכות ישראל בתרי''ג מצות אשר רובם תלוים במיני המאכל והמשתה, התרומות, מעשרות, חלה, מצות שמיטה, ושבזריעה, ושבחרישה, ושבקצירה, וכדומה, אבל חכמי האמת (שער הגלגולים פ''ד) הוסיפו בזה טעם לשבח בדרך כלל, כי כל עיקרי הנבראים מעלין בקודש בסוד הבירורין של ניצוצי הקדושה, הן הנה המתבררים באמצעות המאכלים, ומעתה ניצוצי הקדושה יקראו לחם עם ה', גם אמרו ז''ל כי כל נברא יש בו ניצוץ קדוש, ואפילו בנבראים בלתי טהורים, והאנשים הרשעים, וגם בס''מ הרשע, אין מהם שאין בו חלק החיוני שהוא בחינת הטוב שהוא דבר המעמיד שזולתו לא יתקיים כל דבר, ובהפרד ניצוץ החיוני ממקומו יתבטל ויאבד כל הבנין, גם אמרו (שם פי''ח) כי בחינת הקדושה בטבעה להמשיך מינה כאבן השואבת ובזה תשכיל להבין מאמרם ז''ל (שבת לד.) שאמרו יהיב ביה עיניה ונעשה גל של עצמות והבן. ועל פי הדברים יכוין אומרו אל תיראו וגו' כי **לחמנו** הם וחזרו ופירשו מין הלחם שאנו אומרים הוא סר צלם מעליהם והוא ניצוץ המחיה אותם כבר הוסר מעליהם, ועוד **וה' אתנו** שהוא בחינת כללות הקדושה ובזה נעשה כאבן השואבת לכל ניצוצין המחיים אותם ונאבדים כלם יחד, ומעתה אין מקום לירא מהם כאומרו אל תיראום:
@514 **ויאמרו וגו' לרגום וגו'**. צריך לדעת למה לא נרגשו במאמר ראשון שאמר כלב עלה נעלה וירשנו וגו' נוכל לה, ונראה כי לדברי כלב לא חששו לפי שדבריו בטלים מעצמן שאין עדות יחיד עומדת לגבי עדות רבים דכתיב (דברים יט) על פי שני עדים יקום דבר לזה לא חשו לדבריו, מה שאין כן כשבאו יחד דברי יהושע וכלב מעתה הורעה עדות המרגלים כי דין ב' עדים כדין מאה עדים (מכות ה:) ועדות שקולה היא זאת ואין כאן עדות לא של מרגלים ולא של יהושע וכלב וחזר הדין למה שהיה קודם שלוח המרגלים לזה חשו להם ואמרו לרגום אותם:
@514 **וצריך** לדעת למה לא השכילו לדון על פי משפט התורה להכחיש דברי העשרה בדברי הב' כיון שדין העדות הוא תרי כמאה ומאה כתרי. ואפשר שדנו ביהושע שהוא פסול לעדות במה שנוגע למשה כי היה משרתו מבחוריו:
@515 **ויאמר ה' וגו'**. המאמר כאן בא למנוע משה מלהתפלל על ישראל, כדרך שאמר לו במעשה העגל (שמות לב) הניחה לי, כמו כן במעשה זה הקדים לומר אליו ענין האמור בסמוך כדי שימנע מלהתפלל עליהם, ולזה לא אמר לאמר:
@515 **עד אנה ינאצוני וגו' ועד אנה לא יאמינו וגו'**. קשה אם הם מנאצים מה מקום להתרעם על העדר האמונה. ואולי שכנגד המרגלים אמר ינאצוני וכנגד שהאמינו להם אמר לא יאמינו בי שהבטחתים לתת להם את הארץ:
@515 **עוד** לצד שהיו בישראל כת אחת מנאצים שהרשיעו ופקרו. ומה גם לדבריהם ז''ל שאמרו (סוטה לה.) בפסוק לרגום אותם באבנים וכבוד ה' וגו' שהיו זורקים אבנים גם כנגד מעלה, וכנגדם אמר ינאצוני, וכת אחת מתפחדים מהעמים וכנגדם אמר לא יאמינו, וכנגד ב' בחינות אמר אכנו בדבר ואורישנו, כנגד שלא האמינו אמר **אכנו** בדבר, ונתכוון לגמור כנגד המנאצים **ואורישנו** פירוש מעולם הבא וב' גזירות אלו נתקיימו במרגלים שהכה אותם ה' בדבר דכתיב (ל''ז) וימותו האנשים וגו' במגפה ואין להם חלק לעולם הבא כמאמרם ז''ל (סנהדרין קח:) ואומרו **ואעשה אותך** פירוש ישפיע בו ובענפיו כל ניצוצי הקדושה הראוי לבא מה שלא היה בכוחו קודם, ואומרו **ממנו** פירוש שהגוי עצום יהיה מהעם המוזכר בתחלה שיטה ה' כל נשמות התלויות בעם ויטעם בשורש נשמתו של משה:
@515 **עוד** יתבארו הכתובים על זה הדרך והוא לצד שכבר קדם מעשה העגל ומאמר ה' שם ותשובת משה שבה נצח את הדין ובטל את הגזירה בטענות האמורים שם, בעבור זה בא האלהים לדבר נגד טענות הראשונות, והתחיל לומר **עד אנה** פירוש אין קצבה לניאוץ האנשים האלה לומר העבר להם זאת ואפס כח הסבל, ובזה דחה גם כן לטענת משה שיאמרו מצרים ברעה הוציאם כי זה יהיה ניאוץ הגוים פעם אחת וניאוץ של ישראל אין לו קצבה, גם בזה דחה טענת זכות אבות כי אין ראוי למלך גדול ורם ברוך הוא לסבול כל כך ניאוצין מבניהם:
@515 **ותמצא** שאמרו רז''ל (שבת פט:) שהשיבו האבות להקדוש ברוך הוא כשאמר להם בניכם חטאו אמרו לו ימחו על דבר כבוד שמך, שגם הם לא יחפצו בהכעסות ה' ברוך הוא, וכנגד טענות אשר הוצאת מארץ מצרים שאמר משה במעשה העגל שנתכוין לומר שלא ישוה הגוי אשר יצא ממנו להביא ראשו בעול האלהות כעם היוצא ממצרים אשר להם נעשו המסות הגדולות, לזה אמר כי לא הועיל להם מה שראו ביציאת מצרים, והוא אומרו **ועד אנה לא יאמינו בי בכל האותות** וגו', ומעתה אין הפרש להם לצד פרט זה אם כן אכנו וגו', ואם תאמר ומה אעשה לשבועת האבות, **ואעשה אותך** שאתה מבניהם לגוי גדול וגו', ועדיין ישנה לקושיא ובמה תהיה בטוח מהבאים תחתיהם שלא ינאצו גם הם, לזה אמר **ואעשה** וגו' לגוי גדול ועצום פירוש שיהיו הנשמות גדולות ועצומות יותר ממנו פירוש מהעם הנמצאים שיהיו קרובים לקדושה ביותר מהעם ההוא שיוכל עמוד במצות ה', ותמצא כי באמצעות נפש קדושה יסתייע עשות מעשה קודש וימאס עשות רע, ועיין מה שפירשתי בפסוק (בראשית מט) ראובן בכורי אתה וגו', והעם היוצא ממצרים לצד שהיו תוך קליפת מצרים ושמלת שבים לא נטהרו ממנה בהחלט וזה סיבה לנאץ, מה שלא יהיה כן העם היוצא ממשה:
@517 **ושמעו מצרים וגו'**. צדיך לדעת למה אומר **ושמעו** בתוספת וא''ו בתחלה, היה לו לומר ישמעו מצרים, עוד צריך לדעת כוונת אומרו **כי העלית**, אם רצונו לומר ישמעו שהעלה זה אין לו שחר, כי הלא המה ראו מעשי ה' ונפלאות אשר עשה בתוכם. ועוד מה יסובב הריגתם לשמיעת מצרים שהעלה בכחו וגו', ואם הכוונה היא לציין מי הם מצרים אשר ישמעו ואמר אותן אשר העלית בכחך וגו' קשה וכי יש מצרים אחרים לטעות בהם, ולו יהיה שיש מצרים אחרים עם כל זה מן הסתם אינו חוזר אלא על מצרים הידוע:
@517 **ונראה** שהכוונה היא במה שנעיר על משה עליו השלום למה לא הזכיר טענות שטען לפני ה' במעשה העגל, והגם שפירשתי בפסוק עד אנה ינאצוני וגו' שה' סתר טענה זו בטענת נלאתי נשוא גם לצד שאין לניאוץ זה קצבה, עם כל זה היה למשה להזכיר זכות אבות בצירוף הטענות שהזכיר כאן שבהם נצח הדין כאשר אבאר. אכן משה עליו השלום נתחכם בנועם דבריו שאמר ושמעו בתוספת וא''ו לומר מלבד טענות הראשונות שאמר כשהתפלל על מעשה העגל שחוזר הוא וטוען ומוסיף עליהם להשיב על מאמר ה', והוא אומרו **ושמעו מצרים** וגו', ונתן טעם לדבריו שאמר הדבר בהחלט שישמעו ואם תאמר מי אמר לך שישמעו ודאי ואפשר שלא ישמעו, לזה אמר **כי העלית בכחך הגדול** וגו' ודקדק לומר **מקרבו** לומר שהגם שנסי מצרים היו ידועים לכל עם כל זה ישתנה הדבר לאותם שהיו בקרבם ואומה כזו לא תמנע מחקור מהנעשה מישראל וענייניהם, ולזה אני מחליט שידעו אשר יעשה מהם בדקדוק, וכפי זה תיבת כי היא נתינת טעם למאמר ושמעו:
@517 **עוד** ירצה על זה הדרך שבא ליתן טעם למה לא חש אלא לשמיעת מצרים ולהנסבב ממנה ולא לשאר העמים, לזה אמר כי **העלית** בכחך וגו' פירוש הם שידעו אומה זו שאין בה יכולת ולא יכלה עלות ממצרים אלא בכחך הגדול כשישמעו שמתו כאחד הגם שה' יקיים הבטחתו ויכניס לארץ זרעו של משה אף על פי כן יתלו כי המשפחה ההיא היה בת כח היכול עמוד מפני יושב הארץ, וזה הוא מדברים הרגילים כי אומה חזקה תמשול בלמטה ממנה, אבל העם היוצא ממצרים שאין לו אלא כח ה' לא היה כח בה' ח''ו להביאם, והוא מה שדקדק לומר **העלית בכוחך את העם הזה** מראה באצבע העם היוצא שלא היה בו כח זולת כח עליון לשלול עם הבא במקומו שאין ממנו מופת לסתור טענת מבלתי יכולת ה', ומיחוש זה אינו אלא מצד מצרים אבל שאר האומות אם לא היה טעם שמצרים ידעו העם ואיכותו לא היה חילול ה'. נמצאת אומר מתוך דברי משה ב' דברים מוכרחים הא' שישמעו מצרים הנעשה מישראל, והב' כי מצרים ידעו שישראל אין בהם כח לעמוד במלחמות גדולות זולת כחו יתברך:
@518 **ואמרו אל יושב וגו' שמעו וגו'**. צריך לדעת מה יאמרו ליושב הארץ, ואם כוונתו לומר שיאמרו מבלתי יכולת ה' ח''ו להם, היה לו להסמיך הדברים על זה הדרך אל יושב וגו' מבלתי יכולת ה' והיה לו להקדים מאמר שמעו וגו' או לאחרו:
@518 **אכן** כוונת המאמר הוא על זה הדרך **ואמרו** וגו' פירוש כשישמעו מצרים יתלו הדבר לטעם יושב הארץ פירוש לצדם היה הדבר, ולהיות שיש כאן ב' דרכים, האחד הוא שלא היה העם ראוי לכל כך מעלה בעיני ה' להאביד לפניו יושב הארץ גוים גדולים ועצומים, והגם שאבדה מצרים בשבילם אין למידין ממצרים ליושב הארץ ז' גויים גדולים ועצומים ולא היו כל כך אהובים אצלו עם בני ישראל אז לאבד מפניהם עמים רבים, והב' הוא שה' היה חפץ בעם ואוהבם אלא שלא השיגה ידו חס ושלום ליושב הארץ, לזה אמר **שמעו כי אתה ה' בקרב** וגו' פירוש לא יאמרו שהסיבה שנולדה מיושב הארץ הוא לצד שגם הם אהובים וחביבים אצל הבורא ברוך הוא כנז' שהרי שמעו חביבו' ישראל אצלך כי אתה ה' בקרב העם אשר עין בעין וגו', הרי נפלאה אהבתם לה' ופרסם כי שמו הגדול נקרא עליהם, ואילו היה יכול לעשות עמהם טובות לא היה נמנע ממיחוש אומות שלא באו לכלל חלק מריבוא מאהבת ישראל גלוי לכל העולם, ומעתה כשתמית את העם הזה לא יתלו הדבר לצד מיעוט השגת אהבתך בהם ואם תעשה את הדבר הזה והמתה וגו' ואמרו וגו':
@519 **והמתה וגו' כאיש אחד וגו'**. גילה דעתו עליו השלום בזה שאינו מבקש שיסלח ה' על החטא אלא שלא יבא לידי חילול השם, ורמז בדבריו כי ההרגש שממנו יומשך האמור בדבריו הוא דוקא אם ימיתם כאיש אחד אבל מעט מעט לא יורגש הדבר, וכן מצינו שעשה ה':
@519 **ואמרו הגוים וגו'**. פירוש לא מצרים לבד אלא כל הגוים ששמעו שמעך, **לאמר** פירוש לשון מעלה ורוממות רום יכולת ה', עתה יאמרו מבלתי וגו' ויתהפך קידוש ה' לחילול ח''ו בפי כל העמים, ולזה דקדק לומר **ואמרו** בתוספת וא''ו לומר כי מלבד מצרים וכו' גם כל הגוים. עוד טעם אומרו **לאמר** לצד שאין ידוע מבטא הדברים הנאמרים מהגוים וסדרן, לזה אמר ואמרו אמירה שהכוונה בה לומר מבלתי וגו'. עוד אומרו **לאמר** פירוש הגם שלא יצדיקו הם עצמן הדברים בדעתן אף על פי כן יאמרו המתחייב מהמעשה, וזה הוא שיעור הענין ואמרו וגו' ודבר זה אין בו אלא אמירה לבד ולא הצדקת הדברים בדעתם:
@520 **מבלתי יכולת ה' וגו'**. פירוש או שאין בו כח ח''ו כנגד יושבי הארץ, או על דרך אומרו (תהלים יד) אמר נבל בלבו אין אלהים פירוש שאפס היכולת שהיה קודם לזה ח''ו, ויש בזה חילול ה' גדול:
@520 **העם**. בא מאמר זה לסתור טענת הכנסת זרעו של משה, ואמר כי חילול ה' יהיה גם בזה כל שלא מכניס העם הזה, וכמו שכתבתי בפסוק ושמעו מצרים, וכח טענת משה היא שהגם שהם מנאצים אותו אם יהרגם בבת אחת יש חילול ה' גדול בכל העולם, ואולי כי הוא זה שרמז הכתוב בתחילת דברי משה שאמר **ויאמר משה אל ה'** פירוש אמירה זו היתה לסיבת דברים הנוגעים אל ה' כדי שלא יתחלל שמו ח''ו:
@520 **וישחטם במדבר**. טעם שדבר בלשון זה, לרמוז את אשר יגשימו הדברים באלהי עולם, והטעם כי כשתהיה הסיבה כי ח''ו הוגבל בכח הנה הוא בגדר הגשם ח''ו:
@521 **ועתה יגדל נא וגו'**. יש להעיר א' אומרו **ועתה**. ב' אומרו **יגדל** משמע שיעשה איזה דבר שבו יגדל עוד ולא מצינו שעשה דבר בענין זה להתגדל. ג' אומרו **נא** אם הכוונה היא עתה הלא אמר עתה יגדל ואם לשון בקשה למה לא הקדימה. ד' אומרו כאשר **דברת** מה דבר ה' והיכן דבר. ה' תיבת **לאמר** למי יאמרו הדברים:
@521 **אכן** לצד שנתחכם משה בטענה הנשמעת כי יש חילול ה' גדול בהמיתם הוסיף לדבר כי עתה יש יתרון לגדולתו יתברך אם ישוב מחרון אפו ויכנסו ישראל לארץ מה שלא היה מקודם ענין זה, והוא שאחר שספרו המרגלים הפלאת תוקף הארץ וגבורת הגבורים ואף על פי כן הורישם לפני ישראל בזה יגדל כח ה', ואומרו **כאשר דברת** הוא מאמר שלח לך וגו' אשר אני נותן לבני ישראל ופירשנוהו במקומו שנתכוון במאמר זה כי הוא מושלל מבחינת ההשגה כפי בחינת היכולת אלא בתורת מתנה אשר הוא הבורא נותן לבני ישראל כמו שכתבנו שם, ופרט זה אמר ה' אליו לאמר לישראל והוא מאמר דברת לאמר:
@521 **ואומרו נא** פירוש עתה, וכפל לומר ב' פעמים עתה, יתבאר על פי דבריהם (ב''ר פכ''א) שאמרו אין ועתה אלא תשובה, ולפי שאמר משה לפני ה' הדברים שאין כדאי ליאמר על האדון הגם שהיה אומר דברי הגוים ולא דברי עצמו ח''ו אף על פי כן אינו מן המוסר, ותמצא כיוצא בדבר שהשומע ברכת ה' מפי עדים הגם שאינם אלא מעידים מה שאמר הרשע המברך אף על פי כן קורע השומע (סנהדרין ס.), וכמו כן כשאמר משה מאמר הגוים נגד כבודו יתברך התודה ועשה תשובה על שהוציא מפיו דברי זלזול כנגד הבורא ברוך הוא והוא מאמר ועתה. גם רמז הכתוב במאמר **ועתה** שיקח תשובתם של ישראל, ואומרו **יגדל** נא על דרך אומרם ז''ל (ברכות לד:) במקום שבעלי תשובה עומדים אין צדיקים גמורים יכולים לעמוד, והטעם שיותר מתקדש שמו יתברך כשמטיבים הרשעים את דרכיהם, והוא אומרו **יגדל נא** פירוש יהיה יותר גדולת ה' עתה כשיחזרו בתשובה אחר המרד, גם רמז בתיבת נא על דרך אומרם (אבות פ''ד מי''ז) יפה שעה אחת בתשובה וכו':
@521 **עוד** יתבאר הכתוב על זה הדרך **ועתה יגדל** פירוש מה שאני מבקש מה' לא להחליט המחילה לכל המנאצים אלא ועתה יגדל נא כח ה' פירוש להתנקם מהמנאצים הרשעים שהם המרגלים, כי כשה' עושה משפט ברשעים שמו מתגדל ומתרומם, ואומרו כאשר **דברת** הוא מה שאמר (י''ב) אכנו בדבר ופירשנוהו במקומו באחד מהדרכים שחוזר למרגלים, ודקדק לומר נא פירוש עתה בשעת מעשה העבירה ולא יתלה להם זמן, וכמו שכן היה דכתיב (ל''ז) וימותו האנשים מוציאי דבת הארץ רעה במגפה לפני ה', ועיין מה שפירשתי שם, ואומרו **לאמר** אולי שבקש משה מה' שיאמר הדברים להם קודם שימותו כדי שיראו ויחתו. או ירצה **לאמר** לישראל ראו אלו שדברו שקר מה עלתה בידם להחרירם לבל ישובו להכעיס, וכן אמר דוד (תהלים ט) בפועל כפיו נוקש רשע הגיון סלה. ורמז בראשי תיבות **ועתה יגדל נא כח** שם אלהים, ושם אדני שרשם הכתוב גם כן יגיד משפט, ואחר כך חזר לעורר הרחמים על כללות העם דכתיב סלח נא לעון העם הזה:
@521 **עוד** נתכוון משה במאמר **ועתה** וגו' על מה שאמר אליו ה' ואעשה אותך לגוי גדול ועצום, שהגם שינחם ה' מהרעה אשר אמר לא מפני זה ישוב ה' מדברו הטוב, ותמצא שאמרו ז''ל (מכות יא.) קללת חכם אפילו על תנאי וכו' ומכל שכן ברכה ומכל שכן דברי אלהים חיים, והוא אומרו **ועתה** פירוש וגם עתה יגדל נא כח ה' שדיבר לאמר ואעשה אותך לגוי גדול לקיים גוי גדול שישנו עתה ויגדיל עשות להוסיף גוי גדול ממשה, ותמצא שכן היה דכתיב ובני רחביה רבו למעלה ואמרו ז''ל (ברכות ז.) למעלה מם' ריבוא, ודקדק לומר דברת לאמר, לצד שבעת אשר דבר קשות כנגד ישראל האמיר את משה במדה טובה, לזה אמר דברת דבור קשה לישראל, לאמר אמירה רכה למשה:
@521 **עוד** ירצה **כאשר דברת** שיהיה לגוי גדול, ואומרו **לאמר** פירוש כנגד מה שאמר ועצום ממנו שתהיה בחינתם חזקה יותר מהם:
@521 **ויש** לנו לחקור זאת למה לא שאל משה דבר זה כשאמר לו כן כשעשו העגל כי גם שם נאמר לו (שמות לב) ואעשה אותך לגוי גדול, ואפשר כי כאן בא בטענה לפי שיצא הדבר מפי עליון שני פעמים, והוא מה שדקדק במאמרו **כאשר דברת לאמר** פירוש דברת במעשה העגל ואמרת עתה במעשה המרגלים:
@521 **עוד** נראה שבמאמר ראשון לא אמר ה' אלא ואעשה אותך לגוי גדול ולא אמר ועצום ממנו, ולפי אחד מהדרכים שפירשתי במאמר ועצום ממנו הכוונה היא שהגוי גדול שיהיה ממשה הוא מהעם עצמו כמו שכתבתי, ולזה אחר שהתפלל שתעמוד העטרה במקומה בעם היוצא ממצרים חש על טובתו שאמר אליו ה' ואעשה אותך וגו' שתתבטל כי ה' לא אמר לעשותו גוי גדול אלא מהעם, לזה אמר **יגדל נא כח ה'** וגו', מה שאין כן במעשה העגל לא אמר ה' אלא ואעשה אותך לגוי גדול, מן הסתם הגם שחזר בו ה' וניחם על הרעה אשר דבר על עמו לא מפני זה יתבטל הטוב אפילו היה על תנאי ויטע ה' ברוך הוא נטעי נשמות חדשות לפרות ולרבות, ואולי כי זו היתה כוונת דבריהם ז''ל שאמרו (שם לב.) שאמר משה לפני הקדוש ברוך הוא כסא של ג' רגלים לא יכול לעמוד של רגל א' וכו' ישראל שיש להם ג' עמודים וכו' עד כאן. וקשה וכי משה לא מהם הוא שיאמר על בניו שהם של רגל אחד, ולדברינו יוצדקו הדברים לצד שהגוי העומד ממשה הם נטעי נשמות שלא באו מאברהם יצחק ויעקב וכפי זה אין להם אלא רגל אחד:
@521 **עוד** נראה טעם שהתפלל כאן לצד שהובטח בגוי היוצא ממנו שיהיה עצום במדרגת הקדושה וטהרה שלא ינאץ ה' לזה הוא שהתפלל יגדל כח ה' על פרט זה, ודקדק לומר יגדל נא פירוש שמצינו (ברכות לג:) שבחירת מעשה הטוב אינה ביד הקדוש ברוך הוא, **ועתה יגדל נא כח ה'** אפילו בבחינת דבר זה להמציא נפש נוטה למעשה הטוב:
@522 ה' **ארך אפים**. צריך לדעת למה לא אמר לפניו כל הי''ג מדות הנאמרים בפרשת כי תשא, ויתבאר על פי דבריהם ז''ל בראש השנה פרק א' דף י''ז וזה לשונם ה' ה' אני הוא קודם שיחטא האדם ואני הוא לאחר שיחטא האדם ויעשה תשובה עד כאן. ובפרשת תשא (שמות לד ו) כתבתי דברי הרא''ש ז''ל בזה ומה שעלה בידי בפירוש הענין, הא למדת שמדת רחמים הראשונה הוא קודם שיחטא, לזה כאן שהיה צריך משה למדה שאחר החטא לזה לא אמר אלא ה' פעם אחת:
@522 **ולהר''ן** גאון שהביאו דבריו התוספות (ר''ה יז:) והרא''ש שה' ראשון אינו מחשבון המדות אלא מודיע מי הוא הקורא, כפי זה יש טעם נכון למה לא אמר משה כאן אלא פעם אחת ה', אלא דקשה איך יחלוק הר''ן על דברי רבות ינו:
@522 **ואפשר** לפרש הדברים לפי דברי הר''ן כי מה שאמרו קודם שיחטא ואחר שיחטא פירוש שה' רחמן אפילו אחר שיחטא האדם כמו שהיה רחמן קודם שיחטא ואין חידוש לרחמים אלא אחר החטא, וכפי זה אין קושית הרא''ש שהקשה קודם החטא למה צריך לרחמים כי כפי האמת כן הוא, גם דילג ג' מדות אל, רחום, וחנון, לצד שג' מדות אלו צריכין להם מי שחסר הצלה מצרה או מי שחסר טוב או מי שנתון במכאובים ועתה לא הוצרך בתפלה למדות אלו, והתחיל מארך אפים להאריך אפו גם לרשעים, וכדבריהם ז''ל שאמרו (סנהדרין קיא.) כשעלה משה למרום מצאו להקדוש ברוך הוא שהיה כותב ארך אפים וגו' יעויין שם דבריהם, הרי כי לארך אפים קרא, גם אמר רב חסד להטות משפטם כאומרם ז''ל (ר''ה שם) רב חסד מטה כלפי חסד, ולא הזכיר אמת ולא נוצר חסד לאלפים כי אינו צריך למדות אלו על מה שלפנינו, והזכיר נושא עון ופשע כי להם צריך, ולא הזכיר וחטאה שלא היו אז שוגגין אלא מזידין, והזכיר כל שאר המדות לצד שהם מדות שנוגעות למה שלפניו:
@524 **ויאמר ה' סלחתי כדברך**. פירוש לא סלחתי על העון בהחלט אלא כדבריך שלא אהרגם כאחת מהטעמים שרשם במאמרו שלא יאמרו מבלתי יכולת וגו', אבל על כל פנים יעשה בהם משפט באריכות אפים, והוא מאמר הסמוך **כל האנשים** וגו' **אם יראו את הארץ** וגו', ואומרו **חי אני** פירוש נשבע בחיי המלך כביכול, גם נשבע ואמר וימלא כבוד וגו' פירוש כן ימלא כבוד ה' את הארץ עד שנעשה זה, והוא גם כן שבועה על הדבר:
@524 **עוד** נראה לפרש הכתוב על זה הדרך **סלחתי כדברך** פירוש לצד דבריך שחלית פני, ולצד שנאמר בדברי משה מיחוש מאמר הגוים מבלתי יכולת ה' וגו' ופירשנו במקומו ב' דרכים הא' כי אין אלהים ח''ו עוד, והב' שאין בו כח נגד יושבי הארץ, לזה אמר **ואולם חי אני** פירוש כנגד מה שיאמרו שאין בנמצא המציל ח''ו ואמר חי אני, וכנגד מה שיאמרו שאין בו כח ח''ו לעמוד בפני יושבי הארץ אמר **וימלא כבוד ה' את כל הארץ** פירוש במעשה אשר יפליא לבסוף בא' ושלשים מלכים הגם שיעשה זה לזרעו של משה, והכוונה בדברים אלו לומר שלא עשה אלא לכבוד משה שבקש ממנו סליחה ולא למיחוש מאמר הגוים:
@526 **ולא שמעו בקולי**. פירוש לצד ששמע עם קול אלהים חיים פנים בפנים דבר ה' עמהם לזה יקפיד על שלא קבלו ולא חשו על קולו יתברך אשר שמעו:
@527 **אם יראו וגו' וכל מנאצי וגו'**. צריך לדעת למה הוצדך לפרש המנאצים מנין יעלה על הדעת שלא יהיו בכלל הגזירה שהוצרך לפרטם. ואפשר כי לפי שה' אמר וינסו אותי זה עשר פעמים שזה יגיד כי כל שלא ניסה עשר פעמים והם אותם שיצאו ממצרים פחות מכ' אינם בכלל הגזירה, לזה הוציא המנאצים מהכלל שהגם שיהיה בהם שלא ניסו עשר פעמים נחתמו בגזירה זו, ומנאציו הם המרגלים או אותם שהיו זורקין אבנים בענן ה' כדברי רז''ל (סוטה לה.):
@527 **גם** נתכוין הכתוב לרשום פרט חדש במרגלים שלא יהיו ראויים לארץ פירוש שלא יטלו חלק בה, וכמו שאמרו במסכת בבא בתרא דף קי''ז שבניהם של מרגלים לא נטלו חלק המרגלים בארץ אלא חלק אבי אביהם עד כאן. מה שאין כן כל הדור ההוא שנטלו חלקם בניהם, ופירוש יראוה פירוש שלא יהיו ראויים לה, ולזה גמר אומר **ועבדי כלב** וגו' **וזרעו יורישנה**, וידיעת ההפכים מושכלת מהנאמר:
@528 **ועבדי כלב עקב וגו'**. צריך לדעת למה לא הזכיר אלא כלב ולא יהושע, גם כוונת אומרו **היתה** רוח אחרת עמו, גם אומרו **וימלא** אחרי, גם אומרו **והביאותיו** בתוספות וא''ו בגזרת הכתוב:
@528 **אכן** פירוש הכתוב הוא על זה הדרך **ועבדי כלב** וטעם שאני קורא אותו עבדי הוא עקב פירוש שכר אשר היתה רוח אחרת עמו, שהגם שיהושע גם כן לא ניאץ ה' עם המרגלים אף על פי כן זה היה לו סיבה תפלת משה הצילתו מיצר הרע ומכוחותיו שהם המרגלים לבל יטעוהו מה שאין כן כלב שנכנס בגדר סכנת יצר הרע וחברתו הרשעה ותחל רוח רעה לפעמו, והראיה שהלך ונשתטח על קברות האבות, והוא אומרו **רוח אחרת עמו** ואף על פי כן **וימלא אחרי** פירוש השלים אחר רצונו יתברך, ודקדק לומר בדרך זה לצד שיש באדם ב' יועצין יועץ רע ויועץ טוב ללכת אחרי ה' והוא השלים ומילא אחרי חלק ה', וזה הוא על דרך אומרם ז''ל (קידושין לט:) מי שבאה עבירה לידו וניצול ממנה נותנין לו שכר כעושה מצוה, וזה אינו ביהושע כי לא היתה רוח אחרת עמו להטעותו מדרך השכל כי משה מנעו, ויש כח בתפלת הצדיקים גם לבחינה זו בסוד (שמואל ב כג) צדיק מושל יראת אלהים והבן. אשר על כן זכה כלב שיקרא עבד ה' כמשה רבינו עליו השלום:
@528 **והוסיף** עוד לומר מלבד המעלה הנזכר עוד והביאותיו אל הארץ אשר בא שמה פירוש להתפלל על עצמו, וכאן רמז התעצמותו עד שמילא אחרי ה', וכוונת הטבה זו היא שלא בלבד שלא נכנם בגדר הגזירה אלא הבטיחו בחיים, שהגם שהיה בן ארבעים שנה אז וגזר ה' שישבו ארבעים שנה במדבר הבטיחו שיחיה עד בואו שמה, והוא אומרו **והביאותיו** הרי הובטח בחייו ארבעים שנה מה שלא נעשה לשום צדיק בעולם:
@528 **ואולי** כי לזה הקדים לקרותו עבדו לומר שהגם שיודיעהו הבטחת החיים ארבעים שנה לא יזור אחור מעבודת ה' לצד שארך יום קיצו, וכבר פירשתי (בחפץ ה' שבת ל') במעשה חזקיה שהוסיף לו ה' ט''ו שנה שנשאלתי ישוב מאמרם ז''ל שהשיב ה' לדוד כששאל ממנו הודיעני ה' קצי ומדת ימי וגו' ואמר לו גזירה היא מלפני שאין מודיעין לו לאדם קיצו וכו' עד כאן. ולמה הודיע ה' לחזקיה, והשבתי כי דוקא קץ שהאדם מביא עמו החרוץ דכתיב (איוב יד) אם חרוצים ימיו אבל תוספות ימים לא נכלל בכלל גזירה זו, וחפץ ה' להודיע על דרך אומרם בגמרא (שבת י:) בפסוק לדעת כי אני ה' מקדשכם שהנותן מתנה לחבירו צריך להודיעו, לזה מודיע ה' חסדו כשמוסיף ימים על ימי אדם, והוא מאמר והביאותיו וגו', וכן תמצא שאמר הכתוב ביהושע סימן י''ד ויאמר אליו כלב וגו' ועתה הנה החיה ה' אותי כאשר דבר והם דברינו עצמם. ואמר עוד **וזרעו יורישנה** לומר כי עשה ה' חסד זה גם לזרעו:
@528 **עוד** יתבאר הכתוב על זה הדרך עקב אשר עשה ב' דברים טובים, א' היתה רוח אחרת עמו פירוש שלא הלך אחר עצת המרגלים, והב' וימלא אחרי שהשתיק העם וסתר דברי המרגלים, ושתים שלם לו ה', אחד והביאותיו וגו', ב' יורישנה, וטעם שלא הזכיר יהושע, לצד שהוא זכה מצד תפלת משה ולא הוצרך להתעצם מכחו:
@529 **והעמלקי והכנעגי וגו'**. כוונת הודעה זו כאן, גם תוספת וא''ו, לצד שהחליט ה' שכל הדור לא יבואו לארץ וימותו במדבר והוא אמר שלא ימיתם כאיש אחד ולזה צריכין להתעכב במדבר זמן ארוך כמו שכן גילה הדברים בסמוך, ויש צד לומר שישבו שם כל הזמן ההוא, לזה אמר **והעמלקי** וגו' פירוש ואינם יכולין להתעכב במקום זה שאתם עלולים ליפול לפניהם, על דרך אומרם (ב''ר פ' צ''א) השטן מקטרג בשעת הסכנה, לזה **מחר פנו** וגו', והגם שמצינו שישבו אחר כך שם ימים רבים דכתיב (דברים א) ותשבו בקדש ימים רבים ואמרו ז''ל (בסדר עולם) י''ט שנה, זה היה בחזרה, שאז כבר נתצמצם והוקטן העון אשר לא כן קודם, ובזה מצאנו טעם למה לא נתעכבו אז שם מה שנתעכבו אחר כך; וטעם אומרו **והעמלקי** בתוספות וא''ו לקשור הדברים עם תחלת הדיבור של אם יראו וגו' שמוסיף עוד גזירת המסעות כאומרו מחר פנו שהוא''ו נמשכת עם מאמר מחר פנו:
@530 **וידבר ה' וגו'**. שיעור הדיבור יגיד כי עתה מתחיל לדבר אליו ה' בענין זה ולא כן הוא שהלא כבר דיבר ה' דברים רבים בזה כאמור בסמוך. אכן לצד שהדברים שעברו מה' למשה עד עתה היו דברים בינו לבין משה לא בשליחות לישראל, והמשכיל במה שפירשנו יצדיק הדברים שלא היה אלא כמלך שמדבר עם עבדו בדברים שרצונו לעשות, ולזה לא אמר שם לאמר כל עיקר, וכאן מתחיל לדבר אליו דברי שליחות לישראל ולזה אמר **וידבר ה'** וגו' לומר לישראל הדברים ככתבן:
@531 **עד מתי לעדה וגו'**. הם המרגלים, וכן אמרו במשנה דסנהדרין (קח.) ואומרו **את תלונות בני ישראל** הם שאר העדה, ואומרו **עד מתי**, נתכוון לומר שעדיין היו מפחידים ישראל לסור מאחרי ה' ולזה קראם עדה רעה לומר שעודנה ברשעה עומדת, ואומרו **אשר המה מלינים עלי** פירוש מלבד רעת עצמן עוד מלינים ישראל עלי:
@531 **את תלונות בני ישראל וגו' שמעתי**. הוצרך להודיע ששמע, לומר כי לא שמע אלא תלונות בני ישראל ולא דברי רשע המרגלים, ושיעור הכתוב הוא על זה הדרך את תלונות בני ישראל אשר המרגלים מלינים עלי שמעתי פירוש תלונות בני ישראל לא הלנת המרגלים, כי דברי המרגלים עצמן נמאסו ומנעם מבוא לאזניו:
@532 **אמור וגו' כאשר דברתם באזני וגו'**. כאן ביאר דבריו שעל בני ישראל הוא אומר שהם אותם שהגיעו דבריהם ושמעם ה' באזניו לאלה הוא שהגביל זמן מבן עשרים וגו'. אבל המרגלים לא באה להם הודעת הגזירה כי לעיני כל ישראל שם שם ינגפו מיתה משונה כמו שכן היה:
@533 **מבן עשרים וגו' אשר הלינותם**. צריך לדעת כוונת אומרו **אשר הלינותם**, ואם רצה לומר על אשר הלינותם חסר תיבת על, גם לא היה צריך לומר שכבר אמר את תלונות וגו' שמעתי וגו':
@533 **ונראה** שכוונת הדברים היא לצד שאמר ה' מבן עשרים שנה חש שיבינו שכוונת הדברים היא כל מי שהיום בן עשרים, וכפי זה נכללים בכלל הגזירה גם מי שיצא ממצרים פחות מעשרים כיון שבשנה ב' באו לכלל כ', לזה אמר **אשר הלינותם** פירוש מזמן שהתחילו להלין, ושיעור הכתוב הוא אותם שהלינו עלי מבן עשרים, וכפי זה חוזר להלנה ראשונה כשיצאו ממצרים שאם על הלנתם אז לא היה צריך לדייק דבריו ולומר בן עשרים בזמן ההלנה כיון שהוא מדבר באותו זמן שהוא זמן שהלינו, והוא מה שאמר למעלה וינסו אותי זה עשר פעמים הא למדת כל שהיה בכלל עשרים בחטא ראשון הוא שנכלל בכלל הגזירה, ואולי כי דיוק זה לא הרגישו בו הדור ההוא וחשבו הדברים כפשטן שבאה הגזירה על אותן שהיו אז בן כ', ולזה שנת המ' כשיצאו לחפור בליל ט' באב ולא מת מהם א' ובדקו בי' וי''א וי''ב וי''ג וי''ד ועשו יום ט''ו שמחה (פתיחתא איכה רבה), וקשה למה חשבו שימותו עוד אחר שהיו ידועים אותם שהיו בן עשרים כשיצאו ממצרים ומה מיחוש עוד להם לגזירה, אלא שהם חשבו שהגזירה היתה על אותן שהיו אז בן כ':
@533 **ואולי** כי גם ה' אמר דבריו שקולין כמנהגו שאומר דברים סובלים ב' דרכים אם זכו יהיה לטובה לא זכו וכו', וכן תמצא כשאמר לאדם (בראשית ב) ביום אכלך ממנו מות תמות הזכיר יום סתם תוכל לומר יומו של אדם ותוכל לומר יומו של הקב''ה אלף שנה וכשעשה אדם תשובה הטה ה' הכוונה לזכות שהוא יומו של הקב''ה, כמו כן במה שלפנינו נתכוון במאמר **אשר הלינותם** ב' דרכים, א' על אשר הלינותם, וא' הוא הבדל להתחלת ההלנה כדברינו, אם זכו יתפרש הדבר לזמן יציאה כדברינו, ואם לא זכו תתקיים הגזירה גם על אותם שהיו כשיצאו פחות מכ', ומה שאמר וינסו אותי זה עשר פעמים ידבר על רוב המלינים, ולזה כשראו בשנת המ' שלא מת אחד מהם עשאוהו יום טוב על שנתבטלה הגזירה מעל אותם שיצאו פחות מעשרים והיו בשעת הגזירה בן עשרים:
@535 **וטפכם אשר וגו'**. לצד שאמר כאשר דברתם באזני כן אעשה לכם והם דברו גם על טפם רעה, לזה בא ה' והוציאם מהכלל ואמר וטפכם וגו' והבאתי וגו', ואמר **והבאתי** בתוספת וא''ו, לומר מלבד שלא יהיו לבז אלא עוד להם טובה שיביאם ה' אל הארץ וגו':
@536 **ופגריכם אתם וגו'**. צריך לדעת למה הוצרך לומר כן אחר שכבר אמר במדבר הזה יפלו פגריכם, ואפשר שנתכוון לומר שלא יכניסו בניהם עצמותם לארץ כמו שהעלו עצמות יוסף ועצמות השבטים לארץ אלא יפלו במדבר:
@536 **עוד** נראה שיכוין לומר שמלבד שיפלו פגריהם כמו שאמר למעלה פירוש שיפלו פגרים מתים, אמר עוד שהגופות גם כן תהיה להם נפילה במדבר שיהיו ביד ס''מ שר המדבר, שאין לך נפילה גדולה מזו כידוע ליודעי מדע, ולזה דקדק לומר ופגריכם אתם יפלו שאחר שקראם פגרים אמר יפלו, ואם על המיתה הוא אומר היה לו להקדים הנפילה שהיא הסובבת בהם שם הפגר וכמו שאמר למעלה יפלו פגריכם, אלא ודאי על השפלת ונפילת הגופות אחר מיתה הוא אומר, ודקדק לומר **אתם** שלא יבינו מאמר פגריכם שבא לומר על בני בניהם שגם עליהם יאמר בכינוי כי הבן חלק מאביו, לזה אמר אתם:
@536 **וחכמי** קאשטיליה המגורשים שמעתי משמם שפירשו שחוזר על משה ואהרן שגזר ה' עליהם גם כן שימותו במדבר, ולזה אמר תיבת **אתם** למשה ואהרן שעמהם הוא מדבר, ונתן ה' טעם לדבריו במה שגמר אומר אם לא זאת אעשה לכל העדה וגו' יתמו ושם ימותו על דרך אומרם ז''ל (במד''ר פי''ט) בפסוק ויתא ראשי עם שטעם שנקבר משה בעבר הירדן להביא דור המדבר לעולם הבא, ולזה אם לא היו מתים משה ואהרן במדבר לא היו חיים דור המדבר, וזה דרך רמז, כי ודאי שלא יאמר פגר על משה ואהרן שגופן זך כמלאכים, גם לא יאמר לשון נפילה על ב' מאורי עולם:
@539 **אני ה' דברתי אם לא וגו'**. צריך לדעת מה כוונת מאמר **אני ה' דברתי** הלא יודעים אנו כי ה' הוא המדבר, עוד מה כוונת אומרו **אם לא זאת** וגו', ומה הוא אומרו **ושם ימותו**. אכן ירצה על זה הדרך אני ה' שהוא מדת החסד והרחמים גם היא הסכימה על המשפט כתוב, והוא אומרו **דברתי** דברים קשים אלו, ואם תאמר איך תסכים מדה זאת על הצרה לישראל, לזה אמר אם לא זאת אעשה, ואאריך עמהם להטיב יודע אני תכליתם שיאבדו מעולם הזה ומעולם הבא, על ידי ניאוציהם אשר יוסיפו לחטוא, והוא אומרו **במדבר הזה יתמו** פירוש כולם יהיו כלים בשלימות, ושם לעולם הבא ימותו, לזה דבר ה' משפט זה שימותו במדבר ולא יתמו כי בניהם הקים תחתם, וגם לעולם הבא לא ימותו כמאן דאמר (סנהדרין קח.) יש להם חלק לעולם הבא, ומעתה רחום הוא בדין זה:
@540 **והאנשים אשר שלח וגו'**. כל הכתוב מיותר שכבר השמיענו כי משה שלח האנשים וגו' וכל מה שאמר הכתוב, ואולי כי לצד שרצה לומר הכתוב המשפט שנעשה בהם תכף ומיד, ויאמר האומר והלא מדת ארך אפים ישנה גם לרשעים ולמה לא האריך ה' אפו קצת לאלו, לזה סדר הפלגת חטאם שמנעו אריכות אפים, דע כי לצד ה' דברים יחרה אף ה' ויתנקם מהרה. א' האדם גדול וחשוב כי ימרוד בקונו לא יאבה ה' סלוח לו שאינו דומה לאדם בינוני כי יחטא. ב' אדם שחברתו נאה וחסודה והוא מתעוות והולך בדרך לא טוב. ג' כשיהיה לאדם הרגש גדול להעירו לבל יחטא וכמעשה אותו שטפחו לו ציציותיו על פניו וכו' (מנחות מד.) ולא יחוש להערה. ד' אם חטא והחטיא את הרבים. ה' אם יהיה חטא גדול ורחוק מטבע הרגיל, כמעשה אמון שאמרו לו יש לך הנאה וכו' (סנהדרין קג:):
@540 **והודיע** הכתוב כאן טעם שלא האריך ה' אפו להם שבהם נתקבצו ה' דברים המפליגים מדת ארך אפים, והתחיל לומר כנגד הא' **והאנשים**, ואמרו ז''ל (במד''ד כאן) כל אנשים שבמקרא לשון חשיבות כי ראשי אלפי ישראל המה, וכנגד חברת משלחם אמר **אשר שלח** אותם **משה** בשליחות מצוה לחפור את הארץ, הרי כי הם שלוחי חברה ומחברת משה יחשבו, וכנגד ג' אמר **וישובו** פירוש שנעשה להם נס עצום ששבו ולא נאבדו בהליכתם וצא ולמד מאומרם ז''ל (תדא''ר פכ''ט) מהעובר עליהם מהענקים ולא נגעה בהם יד אדם, וזה היה מספיק להעירם לבל עשות רשע ויכירו כי גדול אלהינו אשר הראם נפלאותיו, וכנגד ד' אמר **וילינו כל העדה** פירוש חטאו הם והחטיאו הרבים, וכנגד הה' אמר **להוציא דבה על הארץ** מי זה אמר ותהי שיאמר על הארץ כלילת יופי כי רעה היא אין לך רשע רחוק מעשות כזה כי איך מין האנושי יעיז פניו כל כך לדבר דברים הפכיים בתכלית ההפכיות לומר דבה רעה על השלימות הטוב, אשר על כן חרה אף ה' והרגם מיד ולא האריך אפו להם:
@541 **וימותו האנשים מוציאי דבת וגו'**. פירוש והם מוציאי דבה מתו, על דרך אומרו (תהלים ט) בפועל כפיו נוקש רשע. עוד ירצה לתת טעם למה מתו במגפה, לפי שהם הוציאו דבה על הארץ מדה כנגד מדה הם דברו דבר רע וה' הכם בדבר:
@541 **לפני ה'**. פירוש וכבוד ה' עומד שם קודם עלותו, ומשונה רשות שניתנה למשחית כאן מרשות שניתנה כשחרה אף ה' באהרן ומרים שלא נגעה צרעת בהם עד שהלך, מה שאין כן כאן שלפניו ניתנה רשות לנגוף אויבי ה':
@542 **ויהושע בן נון וגו' חיו וגו'**. לא היה צריך לומר אחר שפרט הכתוב ואמר האנשים מוציאי דבת הארץ רעה הא למדת שלא מתו אלא אותם שהוציאו דבה רעה, עוד למה הוצרך לומר מן האנשים:
@542 **ויתבאר** על פי מה שאמרו במס' בבא בתרא (קכא:) תניא יאיר בן מנשה נולד בימי יעקב, והקשו ממה שמצינו שנכנם לארץ דכתיב ויכו מהם אנשי העי כשלשים וששה איש וגו' זה יאיר בן מנשה ששקול כרובה של סנהדרין, ותירץ רב אחא שלא נגזרה גזירה לא על פחות מכ' ולא על יותר מס' עד כאן. והנה ממה שלא תירץ הגמרא שיאיר היה צדיק גמור הראת לדעת כי צדקת הצדיק לא הצילתו מהגזרה ההיא, והוא מאמר הכתוב **ויהושע** וגו' **חיו** וגו' פירוש טעם שחיו הוא להיותם מן האנשים ההולכים לתור היא שעמדה להם, אבל אם לא היו מהתרים והיו נשארים בכלל ישראל היתה באה הגזירה גם עליהם הגם שהם צדיקים גמורים לצד שהיו למעלה מעשרים כשיצאו ממצרים ולמטה מס':
@542 **עוד** רמז על דרך אומרם ז''ל (חגיגה טו.) זכה נוטל חלקו וחלק חברו בגן עדן, כמו כן יהושע וכלב הוסיפו חלקם בחיים מן האנשים ההולכים לתור, כי להם משפט ליטול חלק המרגלים, גם אמרו ז''ל (ב''ב קיז:) שהם נטלו חלקם בארץ:
@546 **אל תעלו וגו'**. נתן להם ב' טעמים למונעם מהעליה, א' הוא כי אין ה' בקרבם וכיון שכן הרי זה מהמרד בה', ותמצא שאמר הכתוב במשנה תורה (דברים א) ואדבר אליכם ולא שמעתם ותמרו את פי ה', וטעם ב' ולא תנגפו לפני אויביכם פחד האויב:
@547 **כי העמלקי וגו' כי על כן שבתם וגו'**. פירוש כיון שהמרד היה על מה שאמרו המרגלים עמלק יושב בארץ הנגב וגו' והכנעני וגו' ואמרו ולמה ה' מביא אותנו לנפול בחרב, ואם כן איך תבטחו שיעשה ה' לכם נס במקום הרשע עצמו, ולזה אמר **ונפלתם בחרב** בודאי, כי על כן פירוש על היות עמלק יושב וגו', ולחששת נפילה בחרב זה היה סיבה שעליה שבתם מאחרי ה' ובודאי שלא יהיה ה' עמכם:
@548 **ויעפילו וגו'**. טעו בהוראת דעתם כי לצד שהם מרדו בה' כאומרם שאינו יכול לתת בידם העמים הרמים לזה חשבו לתקן לבטוח בה' ולהחליט האמונה כי הצל יציל ועלו ההרה, ולא נתרצה ה' כי מכתם טריה וכבר נגזרה גזרה, ועיין מה שכתבתי בפרשת דברים:
@551 **כי תבואו אל ארץ מושבותיכם וגו'**. לצד שראה ה' מדוה לבם בגזרת טלטולם במדבר ארבעים שנה מופלגים מביאת הארץ, לזה סעד לבם במצות התלויות בארץ לכונן רוחם כי יעלו וירשו את אדמתם, והפלגת הזמן לא תריע לדבר המוחזק לבא, ודקדק לומר אשר אני **נותן לכם** הגם שהדור ההוא פגריהם יפלו במדבר כל העם היוצא ממצרים בן עשרים, בא לומר כי מעשה בנים יתיחם גם להאבות כי את בניהם הקים תחתם:
@551 **עוד** נראה לומר כי אומרו **נותן לכם** על דרך אומרם ז''ל (סנהדרין צ:) מנין לתחית המתים מן התורה דכתיב אשר נשבע ה' לאבותיכם לתת להם לכם לא נאמר אלא להם וגו' עד כאן. כמו כן הבטיחם שיקומו בתחית המתים וירשו את אדמתם:
@553 **והקריב וגו'**. טעם שהגביל ה' בנסכים ובשמן המנחה רביעית שמן לעשרון שהם ג' לוגין, וכמו כן רביעית יין לנסך, ובב' עשרונים יצו ה' שלישית ההין שמן ושלישית ההין יין שהם ד' לוגין ובג' עשרונים חצי ההין שמן וחצי ההין יין שהוא ששה לוגין שעולה כפי החשבון ב' לוגין לעשרון בין במנחת ב' עשרונים בין במנחת ג' עשרונים, ולמה במנחת עשרון הצריך ה' ג' לוגין, על דרך מה שכתוב במשנה במנחות (קז.) וכתבו רמב''ם בפרק י''ז מהלכות מעשה הקרבנות וזה לשונו מתנדב או נודר אדם יין בפני עצמו ואין מתנדבין לוג יין ולא ב' לוגין שאין בנסכים לא לוג ולא שנים עד כאן. והוא טעם הכתוב שלא נתן לעשרון ב' לוגין הגם שהספיק בשני עשרונים שלישית ההין שהם ד' לוגין להעירך שאין קרבן מהיין מב' לוגין:
@553 **ואם** תאמר יוצדקו הדברים לגבי היין אבל השמן שגם הוא מצינו שבא לבדו בנדבה שאמר ר' טרפון (זבחים צא) מתנדב אדם שמן, ונחלקו רבותינו במנחות (שם) מהם אמרו שלא יפחות מג' לוגין ומהם אמרו מתנדב אפילו לוג מטעם דון מינה ואוקי באתרה אם כן בשלמא למאן דאמר לא יפחות מג' לוגין הוא הטעם שהצריך ה' ג' לוגין בעשרון, אלא למאן דאמר אפילו לוג למה לא עשה כפי החשבון, יש לומר שהשוה ה' מדות שמן ומדות יין בקרבניהם כדין ב' וג' עשרונים:
@571 **וכי תשגו ולא תעשו וגו'**. רז''ל אמרו (הוריות ח.) שכתוב זה מדבר בעובד עבודה זרה, ויש בו כפל אומרו **את כל המצות** וגו' **את כל אשר צוה** וגו' שבא לומר שכופר בעשרת הדברות ובכל שאר מצוות שנצטוו על ידי משה, וחוץ מדבריהם נראה שבא לומר שהעובד עבודה זרה הרי הוא כעובר על כל מצות לא תעשה ומבטל כל מצות עשה, כנגד ביטול מצות עשה אמר ולא תעשו את כל המצות הרי ביטול כל מצות עשה, וכנגד עברת על כל מצות לא תעשה אמר את כל אשר צוה ה' אליכם, וחידוש השמיענו הכתוב במצות עשה ובמצות לא תעשה, כי יש במצות עשה ששקולה כנגד כל התורה אף על פי כן העובד עבודה זרה. הרי הוא ככופר גם בה, וכמו כן יש במצות לא תעשה חמורות הרי הוא גם כן ככופר בכולן ועונשו שקול לכל:
@579 **והנפש אשר תעשה ביד רמה וגו'**. פירוש שהעובד עבודה זרה במזיד מעלה עליו הכתוב כאלו גדף את ה' ח''ו ולזה עונשו ונכרתה הנפש ההיא מקרב עמה ואמר עוד **כי דבר ה' בזה** וגו' פירוש ולטעם ששקולה כנגד כל התורה הרי זה בטל כל מצות עשה והוא אומרו דבר ה' בזה ועבר גם כן על כל מצות לא תעשה והוא אומרו **ואת מצותו הפר** ולזה הכרת תכרת הנפש ההיא הכרת כנגד גידי הנשמה תכרת כנגד אבריה לפי שהנשמות יש להם רמ''ח אברים ושס''ה גידים שכנגדם נתן ה' רמ''ח מצות עשה ושס''ה מצות לא תעשה וכשעבר על כולן לא נשאר לה ענף שממנו תחיה ואין לה תקומה עוד ונקבע בה העון לעולם ועד והוא מאמר **עונה בה** ורז''ל דרשו (ספרי, סנהדרין צ:) הכתוב בענין אחר ושבעים פנים לתורה:
@581 **ויהיו בני ישראל במדבר וגו'**. קשה מה בא הכתוב להשמיענו שהיו ישראל במדבר ויתבאר על פי מה שאמרו במסכת שבת (צו:) וזה לשונם אמר רב יהודה אמר שמואל מקושש מעביר ד' אמות ברשות הרבים היה עד כאן. גם אמרו במסכת שבת פרק א' (ו:) וזה לשונם ת''ר סרטיא ופלטיה וכו' זו היא רשות הרבים, והקשו בש''ס ולחשוב נמי מדבר דהא תניא איזהו רשות הרבים סרטיא וכו' והמדבר, ותירץ אביי לא קשיא כאן בזמן שהיו ישראל שרויים במדבר כאן בזמן הזה, ופירש''י וזה לשונו בזמן ההוא חשוב רשות הרבים בזמן הזה אינו מקום הלוך לרבים פירוש וברייתא דקתני והמדבר הא קא משמע לן דאי איכא רבים מצויים עכשיו במדבר תדיר גם כן הוא בכלל רשות הרבים:
@581 **והוא** מה שאמר הכתוב כשרצה להודיע עון המקושש שהוא מעביר ד' אמות לסברת רב יהודה הקדים לומר ויהיו בני ישראל במדבר פירוש ובזה הוא שנחשב לו חילול השבת להתחייב מיתה, אבל אם לא היו ישראל במדבר הגם שהיה מעביר ד' אמות שם אינו חייב שאין לו דין רשות הרבים:
@581 **ולפי** סברת רמב''ם (הל' שבת פי''ד) כפי מה שנשמע מדבריו ממה שמנה המדבר בכלל רשות הרבים ולא חלק אם מצויים ישראל לשאינם מצויים, ופירשתי בו בחיבורי חפץ ה' שחברתי בימי חורפי שהרמב''ם מפרש דברי אביי על זה הדרך כאן בזמן שהיו ישראל פירוש תנא שהזכיר המדבר מדבר על אותו זמן לזה מנאו גם כן ותנא שלא הזכיר אינו מדבר אלא בזמן הזה וזמן הזה אינן מצויים הולכי מדברות ולצד שאינם מצויים לא טרח להשמיענו דינו, ואין הכי נמי שאפילו בזמן הזה המדבר רשות הרבים, אם כן נחזור לקושיתנו לדרך זה למה הוצרך הכתוב לומר ויהיו בני ישראל במדבר:
@581 **ויתבאר** על פי מה שאמרו עוד שם (שבת צו:) וזה לשונם במתניתא תנא מקושש תולש הוה עד כאן, ולצד שתקשה לדברי התנא והלא אמרו רבותינו (חולין פח.) בדיני כיסוי דם חיה ועוף אין מכסין בעפר המדבר מפני שהיא מלחה ואינה מצמחת עד כאן. אם כן מנין יצאו צמחים במדבר שתלשם מקושש, לזה הקדים לומר **ויהיו בני ישראל במדבר**, ואמרו ז''ל (במד''ר פי''ט) שבארה של מרים היה משקה והיה מעלה גנות ופרדסים ואם כן היו גדלים צמחים במדבר לתלוש, גם לסברת רב אחא בר יעקב שאמר (שבת שם) מעמר היה יתישב גם כן הכתוב בדרך זה:
@581 **וימצאו איש וגו'**. אמר לשון מציאה יתבאר על דרך אומרם ז''ל (ילקוט) שאמר להם משה צאו וראו אם יש אדם שחלל את השבת וכו' עד כאן. לזה אמר וימצאו על דרך אומרו (אסתר ב) ויבוקש הדבר וימצא:
@581 **מקושש עצים ביום השבת**. הקדים זכרון המעשה קודם זכרון היום ולא אמר ביום השבת מקושש עצים, לומר שלא נתעלם ממנו שבת כשעשה מעשיו, ואם היה מקדים זכרון שבת היה נשמע שמצאוהו ביום השבת פירוש הידוע אצלם, אבל מאומרו מקושש עצים ביום השבת חוזר זכרון השבת אל המקושש שיודע כי שבת הוא, ורז''ל (ספרי) נתחכמו להוציא דבר זה שיודע היה שהוא שבת ממה שכפל לומר בפסוק שאחר זה מקושש עצים שבא לומר שאחר שהודיעוהו שבת הוא חזר לקושש, ולדרכנו טעם שכפל לומר פעם ב' מקושש להודיענו שלא היתה לו שגגת מלאכה אלא הודיעוהו כי היא מלאכה שחייב עליה, והוא אומרו אותו מקושש פירוש הוא היה יודע כי עושה מלאכה, ובזה היו לו זדון שבת וזדון מלאכה:
@586 **ויאמר ה' אל משה**. טעם שינוי פרשה זו שאמר **ויאמר** מה שאין כן בכל התורה שבכולן הוא אומר וידבר יתבאר על פי מאמרם ז''ל (ילקוט) שאמרו כשראה משה מעשה המקושש אמר לפני ה' בימי החול לובשין ישראל תפילין וזוכרין המצות ביום השבת במה יזכרו והשיב הקדוש ברוך הוא הריני נותן להם מצות ציצית שבה יזכרו וכו' עד כאן, לזה אמר ויאמר פירוש אמירה המסעדת את הלב במבוקשו:
@587 **דבר וגו' ואמרת**. לצד שיש בזה חיוב המצוה, ויש גם כן מעלה וכבוד הנמשך ממנה, לזה אמר דיבור ואמירה:
@587 **ועשו להם וגו'**. טעם אומרו וא''ו בתחילת הענין, לפי מה שאמרו ז''ל שכתבתי בפסוק ויאמר שאמר משה לה' בימי החול לובשין תפילין וזוכרים וכו' עד כאן. לזה כשבא לומר לו שיעשו ציצית יש מקום לטעות כי מצוה זו תהיה במקום תפילין רצה לובש תפילין רצה לובש ציצית בלא תפילין ואפילו בשאר ימים שבאחד מהם יספיק לזכירת המצות, לזה אמר **ועשו** וא''ו מוסיף שמצות תפילין במקומה עומדת ומוסיף מצות ציצית:
@587 **לדורותם ונתנו וגו'**. הוצרך לומר **לדורותם**, לצד שלא באה מצוה זו אלא לזכרון המצות כשיראו אותו, תבא הסברא לומר כשיבא דור קדוש וטהור שאין צריכין לזכרון זה אין צודך בציצית תלמוד לומר **לדורותם**. עוד ירצה בהעיר למה כתב **לדורותם** באמצע פרטי המצוה. אכן לצד שיש במצות ציצית ב' דברים הלבן והתכלת, הלבן ישנו בכל זמן, והתכלת יש זמן שאינו מצוי, ונתחכם ה' ואמר **לדורותם** קודם זכרון התכלת לומר שהלבן לדורותם אבל תכלת כשאינו בנמצא אין חיוב בו, והגם שהתכלת אינו מעכב את הלבן ולא הלבן את התכלת (מנחות לח.), אף על פי כן הלבן הוא בנמצא לדורות בלא הפסק מה שאין כן התכלת:
@588 **והיה לכם לציצית**. אין ידוע מכוון מאמר זה שיהיה לציצית, ולדברי התוספות שכתבו במסכת מנחות דף מ''ג בדברי רבי מאיר שאמר שם וזה לשונו גדול עונשו של לבן מעונשו של תכלת, משל למלך שאמר לב' עבדיו לאחד אמר הביא לי חותם של טיט ולאחד אמר הביא לי חותם של זהב ופשעו שניהם ולא הביאו איזה מהם עונשו מרובה וכו', כתבו התוספות מה שמדמה חותם של טיט לציצית שכך עושים לעבדים והציצית מעיד על ישראל שהם עבדי ה' כדאיתא במסכת שבת (נז:) כבלא דעבדא תנן עד כאן, ירצה במאמר והיה לכם לציצית לצד שהם עבדים לה' והעבד עושה כבלא יהיה לכם סימן זה לכבלא דעבדא, ואמר **וראיתם אותו** וזכרתם את כל מצות ה' פירוש כשיביטו בסימן עבדותם יתנו לב שאינם בני חורין לעשות כחפצם במאכלם במלבושם בדיבורם ובכל מעשיהם כעבד שאימת רבו עליו ולעמוד בשעה שהאדון מצוה לעמוד ולעשות כל מלאכות אשר צוה ה' לעשות, ואמר **ולא תתורו** וגו' פירוש לצד שהנגלה הוא דבר שהעין חפצה וחושקת בו, ומצות המלך היא ציווי עשות הפך הרצון הטבעי ושנוא הערב המורגש, ומן הנמנע שיעמוד בדבר אלא בהערת סימן עבדותו הוא יכופהו להפך אשר עינו ולבו שם יחפוץ:
@588 **ואמר למען תזכרו ועשיתם**, יתבאר על דרך אומרם ז''ל (מנחות מד.) מעשה באדם אחד וכו' כיון שעלה וכו' טפחו לו ציציותיו על פניו וכו', והוא אומרו למען תזכרו פירוש שהציצית הוא יזכיר אתכם וימנע אתכם מחטא מכל מין חטא, ולזה דקדק לומר **ועשיתם** על דרך אומרם ז''ל (קידושין לט:) ישב אדם ולא עבר עבירה נותנין לו שכר כעושה מצוה והעמידוה בבאה לידו עבירה ופירש ממנה, ואמר **והייתם** קדושים על דרך אומרם ז''ל (ויק''ר כד) אין נקרא קדוש אלא הפורש מן העריות ואומרו **אני ה' אלהיכם** וגו' פירוש חיוב העבדות שאני מחייב אתכם לעשות עליו סימן לצד שהוצאתי אתכם וגו', וכפל לומר פעם ב' **אני ה' אלהיכם** הוא חיוב מושכל, ועיין מה שפירשתי בפסוק (סוף פ' בהר) כי לי בני ישראל עבדים עבדי הם וגו':
@588 **ומעתה** באנו להשכיל על דבר אמת אשר צוה ה' במצוה זו שאין לעשות ציצית אלא בכסות בת ד' כנפות ולא בת ג' ובת ה' כי לצד שהציצית הוא סימן העבדות יצו ה' שיהיה הסימן גם כן יגיד מי לנו אדון, כי ימצא גם כן דבר זה במלכי ארץ שכל אחד יעשה מין סימן אחד לעבדיו וניכר הסימן של כל אחד, וכמו כן גזר ה' שלא נעשה סימן עבדותנו לה' אלא בטלית בת ד' כנפות לרמוז כי מלכנו הוא הבורא ארבע קצות העולם ושליט עליה, ולזה בהיות הטלית בת ג' ובת ה' אבדה הכונה ואין לעשות בה ציצית:
@588 **וצוה** שיהיו החוטין לבן לרשום סימניו יתברך כי מדותיו הם מדת הרחמים והטוב הרמוז במין הלבן, גם התכלת לרמוז על שליטתו בשמים כי התכלת דומה לרקיע, גם במספר החוטין ד' שהם ח' ירמוז לשמו יתברך שהוא שם בן ארבע ויחודו בהיכלו הוא בן ח' בסוד השילוב של הוי''ה ואדנות, גם רשם בדת האל (מנחות לט) לעשות קשר התכלת עם הלבן להעיר במושכל נעלם כי הלבן הוא סוד החסד והתכלת הוא סוד הרחמים, והוא סוד בחינת שמים, ומדה זו מתיחסת ליעקב אבינו שהוא סוד התפארת ואמרו מביני נסתרי התורה כי מדת התפארת תתאב למדת החסד שהיא מתיחסת לאברהם, ולזה יקיף התכלת להלבן כאשר יקיף רוח לנשמה כידוע ליודעי חן:
@588 **וראיתי** להעיר למה לא הכשיר ה' צבע התכלת אלא מדג עולה מהים ולא משאר דברים שיש להם צבע זה עצמו, ואולי שהוא מטעם עצמו שזה הוא סודו כאומרם ז''ל (חולין פט.) ים דומה לרקיע והבן גם להעיר שהרחמים ימשכו מהתורה הנרמזת בים, גם לרמוז כי הרחמים נמשכים מבחינה הנרמזת בדג בסוד עינא פקיחא כידוע לרואים באור החיים:
@588 **חסלת פרשת שלח לך**
@591 **ויקח קרח וגו'**. צריך לדעת אומרו **ויקח**, ורז''ל אמרו (במד''ר פי''ח) לקח עצמו לצד א', ולדרך זה חסר עצמו, כי זכרון קרח הוא לומר מי הוא החולק וחסר הנחלק, ואם כוונתו לומר כדברי אונקלוס ואתפליג, אין שיעור תיבת ואתפליג כשיעור תיבת ויקח, אלא שהתרגום מפרש המכוון, והגם שדבריהם אמת עוד יש לאלוה מילין לדייק תיבת ויקח על נכון. ב' יש להעיר על דבר אמת למה יזכיר ה' זכרון הצדיקים יצהר קהת לוי במעשה בלתי הגון כזה ומה צורך יש בדבר, ורז''ל אמרו (שם) שהתפלל יעקב על עצמו שלא יזכר במעשה זה משמע שצריך היה ליזכר אלא שהתפלל, ואני מתפלא גם על אותם שהזכיר. ג' יש לדעת כוונת הכתוב במאמר **ודתן ואבירם** מה כוונת הכתוב בזכרונם מה מעשיהם, אם לומר שגם הם חלקו עצמן היה לו לכוללן בלקיחה ויאמר ויקחו קרח וגו' ודתן ואבירם, ואם כוונתו לומר שקרח לקח אותם היה לו לומר ויקח קרח וגו' דתן ואבירם וגו'. ד' אומרו **ויקומו** לפני משה מה יגיד הכתוב בקימה זו, אם לומר שבאו לחלוק, אחרי כן הוא אומר ויקהלו וגו' ויאמרו וגו', ואם לומר שעמדו בקומה זקופה לפניו, היה לו לומר ויקומו אחר ויקהלו על זה הדרך ויקהלו וגו' ויקומו וגו' ויאמרו וגו', ולמה הפסיק בין ויקומו לויקהלו במאמר ואנשים מבני ישראל וגו':
@591 **אכן** נתכוון הכתוב להודיע יסוד דבר המחלוקת, שיאמר אדם מנין עלה על דעת קרח לחלוק על נביא נאמן אשר צדקו נבואתו וקרח חכם גדול היה ואיך נשתטה לעשות הדבר הזה הלא כל ישראל ירגמו אותו אבן, לזה אמר הטעמים שלקח בדעתו לבא לריב, ראשונה **בן יצהר** פירוש היותו בן יצהר שהוא גדול מב' אחים הבאים אחריו בבני קהת ואינם יכולין להחציף פניהם כנגדו כי גדול מהם, ב' **בן קהת** הוא המעולה שבבני לוי שהיו נושאים קדש הקדשים, ואמרו רז''ל (שם) קרח מנושאי הארון היה ואין גרשון ומררי ידברו כנגדו, **בן לוי** שהוא שבט מעולה מכל ישראל ואין שאר השבטים מקפחין אותו בדברו לפני משה כי מעולה הוא מכל שאר השבטים גם מכל בני לוי גם בענפי קהת הוא מדרגה ראשונה לב' האחים הבאים אחריו שהם חברון ועוזיאל, ואומרו **ודתן ואבירם** וגו' פירוש גם אותם לקח כדי לערער גם מכחם שהם גדולי שבט ראובן הבכור ליעקב, ובאמצעות זה החשיבו עצמן **ויקומו לפני משה** פירוש קימה ומעלה בהשואה עם משה, קרח למה שהוא כנזכר, ודתן ואבירם לצד היותם גדולי ראובן שהוא גדול מכל האחים וגם מלוי, ואומרו **ואנשים** וגו' פירוש גם אלו לקח עמו לצד היותם גדולי ישראל כדי לחזק זרועותיו, אבל אלו לא באו לגדר זה לקום לפני משה אלא שנקהלו להחזיק דברי קרח ועדתו, ולזה הקדים לומר ויקומו קודם זכרון חמשים ומאתים וגו', ובזה נתישבו כל הדקדוקים:
@591 **עוד** יתבאר הכתוב בהקדים דבריהם ז''ל (שם) שאמרו שעיקר מחלוקתו של קרח הוא על אליצפן בן עוזיאל שנתן לו משה הנשיאות, והודיע הכתוב שלקח קרח מערכת הסתירות במעשה משה, ראשונה טענת היותו בן יצהר, ממה נפשך אם אתה בא אחר הגדול שבבנים ולזה נתת הכהונה לאהרן לצד היותו בן עמרם אם כן מהטעם עצמו לי יאות הנשיאות לצד שאני בן יצהר שני לעמרם שהוא בן קהת שהוא הענף עצמו שבא ממנו אהרן וקודם לחברון ועוזיאל, ולמה נתת הנשיאות לאליצפן, הרי מעשיך מוכיחות שאין גדולה לגדול שבבנים, אם כן חוזר הדין למה שנתן הכהונה לאהרן מטעם שעמרם הוא הבכור אין טעם זה טעם, ומעתה כיון שמצאו דברי משה סתורים אם כן נכנס בבחינת דבר שקר ח''ו וגם בכהונת אהרן לא יאמנו דבריו לילך בו אחר הקדמת עמרם אלא כל שבט לוי בהשואה הוא, והוא מה שרמז במאמר בן לוי, ולצד שחש קרח שלא יקובלו טענותיו אלא לבטל נשיאות אליצפן אבל לומר שאין לחוש לקדימת עמרם ליצהר אין שומע לו כי מודעת זאת שהגדול קודם במעלה, לזה הקיף בטענת ראובן הבכור לכל השבטים ולקח גדולי ראובן, והוא מאמר **דתן ואבירם** וגו' **בני ראובן** לומר כי אם תכריחו לומר הלך אחר הגדול נלך אחר הבכור שבכל האחים ולו יותן הכהונה, ואומרו **ויקומו לפני משה** פירוש לערוך מערכת הסתירות להפיל דבריו, ואומרו **ואנשים מבני ישראל** וגו' הביאם להעריך לפניהם הוכחות מריבתו שלא ידחנו בכח השררה:
@591 **ולרז''ל** ראיתי שאמרו (סנהדרין קט:) טעם שהזכיר הכתוב זכרון מולידיו וזה לשונם קרח שעשה קרחה בישראל, בן יצהר שהרתיח את העולם כצהרים, בן קהת שקיהה שיני מולידיו, בן לוי שנעשה לויה לגיהנם, ולחשוב גם בן יעקב שעקב עצמו לגיהנם, יעקב ביקש רחמים וכו' עד כאן. ובעיני יפלא למה יכנה דברים הרעים לשמות הצדיקים ולא די זה אלא שמקשה בעל הדרשה ולחשוב בן יעקב וכו' אשר לא נכון להזכיר שם מבחר האבות בדרך זה, עוד יש להעיר באומרם שעקב עצמו לגיהנם הלא כבר אמר בן לוי שנתלוה לגיהנם ולמה יכפול הדבר ב' פעמים:
@591 **ולהאיר** אור תורה אסדר ב' ג' גרגרים מסתרי תורה, הא' כי ענפי הקדושה אשר הכין וסדר המאציל ברוך הוא הם שבילי ומשפטי התורה אשר חקק ה' ביד משה עבדו, וכל המחליף סדר מסדרו הנה הוא עוקר הענף ההוא בסוד בחינת נשמתו ועושה הענף ההוא ענף רע כי יסתלק ממנו כח המקדש, וזה לך האות סוד הקרבן אשר יתפגל ויחשב טמא במחשבת חוץ לזמנו וחוץ למקומו ובנותר וירד מכבוד קדושתו להיות טמא ומחייב אוכליו כרת:
@591 ב' כי הענף עצמו שבו פעל און הוא קודם לשלוח בו יד בסוד (ירמי' ב) תיסרך רעתך, נמצאת אומר כי ענף הקדושה יהפך לרעה ויהיה הודו לו למשחית רחמנא ליצלן:
@591 ג' דע כי בחינת הנשמות אשר נטע ה' בעמו הם אותיות התורה כידוע ליודעי חן:
@591 ד' דע כי כשברא ה' את האדם ברא נטע אחד שבו כלולים כל ענפי הקדושה, וכשחטא ונפגם נפגמו כל הנשמות שהיו תלוים בו וכל שיצאו ממנו פגומים היו, עד שיצתה נפש אברהם אבינו ונתלבנה באמצעות עשר נסיונות ונתברר הפסולת בישמעאל ויצתה נשמת יצחק ונתלבנה בעקדה, ונתברר הפסולת בתגבורת האש הוא עשו ויצתה נשמת יעקב בלא שום דופי, והוא מה שהעירונו רז''ל במאמרם (ב''מ פד.) שופריה דיעקב אבינו מעין שופריה דאדם קדמאה עד כאן. פירוש שלא היה בו פסולת כאדם קודם שחטא:
@591 **נמצינו** אומרים שהאילן הוא יעקב, ויצאו ממנו י''ב ענפים, ואחד מהם הוא לוי, ענף זה העניף ג' ענפים גרשון קהת ומררי, וקהת העניף ד' ענפים עמרם יצהר חברון ועוזיאל, וענפי יצהר הוא קרח, והנה בבא קרח להחליף ענפי הקדושה ולהפך הכהונה ממקומה נפגמו ענפי הקדושה שבשורש נשמתו שהיו כולן לשבח, והתחיל ממטה למעלה בראשונה הענף עצמו שהוא קרח בתחלה היה נקרא קרח טהור, בן יצהר שהיה מאיר לעולם כצהרים, בן קהת שהיה מקהה שיני כל רואה גדולתו ומעלתו, בן לוי שנתלוה מיום לידתו להקב''ה בכמה מעלות, ועכשיו הענף עצמו שנקרא קרח נפגם ועשה בו קרחה, ולא ענפו לבד אלא גם שורש הענף שבא ממנו שהוא יצהר נהפך לרעה כשורש נשמתו והרתיח כל העולם כולו כצהרים, ולא שורש אחד לבד אלא גם שורש שלמעלה ממנו שהוא בן קהת נהפך לרעה להקהות שיני מולידיו, ולא זו בלבד אלא גם שורש הענף הראשון שיצא מיעקב שורש של נפש קרח אשר שם נעקרה נפגמה ועשתה בו נקמה ללוותו לגיהנם, וממה שלא הזכיר הכתוב בן יעקב עדיין שורש הראשון שהוא בעיקר האילן שהוא יעקב לא נודעו מעשיו אם גם עדיו הגיע הפגם ונמצא נעקר שורשו של קרח מעיקרו או לא:
@591 **ודע** שיש מחלוקת רז''ל (סנהדרין קח.) בקרח ועדתו אם יש להם חלק לעולם הבא, למאן דאמר אין לו חלק לעולם הבא, גם שורשו ביעקב נמק, והוא מה ששאל השואל ולחשוב בן יעקב, ודקדק לומר שעקב עצמו לגיהנם פירוש לא נתלוה לבד שהוא לזמן מועט אלא עד סוף העולם, והוא מה שרמז במאמר שעקב עצמו לשון סוף ותכלית כעקבים שהם סוף תכונת האדם, ורז''ל ישתמשו בלשון זה כאומרם (סוטה מט:) בעקבות משיחא וכו', ותירץ לפי שהתפלל על עצמו וכו' פירוש לעולם שכן הוא אלא שה' עשה נחת רוח ליעקב שהתפלל וכו', או אפשר שסובר שיש לו חלק לעולם הבא וזו היתה תפלתו של יעקב שלא יגיע כח החטא עד עיקר השורש שביעקב ולא ינתק חבל הכסף מעיקרו ויש תקוה לאחריתם, והוא מאמר התנא (סנהדין שם) עליהם אמר הכתוב (ש''א ב) מוריד שאול ויעל, וראיתי לדקדק אומרו ויעל ולא אמר ומעלה כשיעור שאמר בסמוך ה' ממית ומחיה וכמו כן אמר אחר כך ה' מוריש ומעשיר, אכן נתכוון לומר דברי התנא עצמו שעל עדת קרח הוא מדבר, לזה אמר ויעל פירוש כבר העלה אותם קודם שהורידם שהרי קדמה תפלת יעקב לירידתם ומאז נכתבו בספר העליה:
@593 **רב לכם כי כל העדה וגו' ומדוע וגו'**. פירוש רבנות גדולה נטלתם לעצמכם יותר מהראוי, ואם תאמר מה היא הרבנות הגדולה, כי כל העדה כלם קדושים ועוד להם שבתוכם ה' מה שלא השיגה אומה בעולם ואתם רבנים עליהם, עוד רמזו במאמר זה לומר כי השכינה שכנה לכבוד ישראל לא לכבוד אהרן והוא מאמר **בתוכם ה'**, ואומרו **ומדוע** וגו' פירוש למה אתם מוסיפין היכר הרוממות לעצמיכם עליהם, הכוונה בזה שהם אומרים שאיש ישראל הקרב לגדר שעומד בו אהרן חייב מיתה זו יפליג הנשיאות על קהל ה' ואין ראוי לזלזל כל כך בקהל קדוש קרובי אל עליון לפסלם לבלתי הקרב לעבוד לה' אלהיהם:
@594 **וישמע משה ויפול וגו'**. צריך לדעת למה הוצרך לומר **וישמע** אחר שאמר הכתוב ויאמרו אליהם מנין יעלה על הדעת שלא ישמע. עוד צריך לדעת מה זאת נפילה. ונראה כי לצד שהמלגלגים לא גמרו גזרת המכוון של הצעת הדברים הודיע הכתוב שהבין משה תכלית הדברים הגם שלא פירשו דבריהם, ואומרו **ויפול** וגו' נגד מה שאמרו שהם מתנשאים על קהל ה' שכללו בדבריהם משה ואהרן כנגד מה שנוגע למשה נפל על פניו להראות קצה האחרון ההכנעה ושיוה נפשו כעפר הארץ כעבד המשתחוה לפני השררה, וכנגד גדולת אהרן אמר **וידבר אל קרח** וגו' **בקר** וגו' פירוש לא תצדיקו דברי בזה עד שתבחינו אם ממני יצאו הדברים אם מה' יצא הדבר:
@594 **בקר ויודע וגו'**. טעם אומרו בוקר וגו' ולא עשה המבחן באותו זמן עצמו, אולי שכבר נעשה קטורת של בין הערבים שבו המבחן, עוד שלא יחשדוהו שעשה המבחן בזמן בלתי הגון שהוא בין הערבים שאינו זמן הרצון, וכמאמרם ז''ל בזוהר הקדוש (ח''ב לט:) שהוא זמן תגבורת הדינים. עוד נתכוון בזה איש האלהים לתת להם זמן הלילה להתבונן במעשיהם אולי יכירו כי לא טוב עושים ויחזרו בתשובה ורז''ל אמרו (במד''ד פי''ח) טעמים אחרים למה עכב עד בקר, אלו ואלו דברי אלהים חיים:
@594 **את אשר לו ואת הקדוש וגו'**. צריך לדעת למה כפל לומר **את אשר לו ואת הקדוש**, ורז''ל אמרו (זוהר כאן) אשר לו זו לויה הקדוש זו כהונה, וצריך לדעת למה הוצרך להזכיר ענין הלויה כיון שלא ערערו אלא על הכהונה, ולפי מה שפרשתי כי קרח לקח גדולי שבט ראובן עמו בטענתו שתחזיר הגדולה לבכור שבאחים לזה הוכרח להשיב גם על החלוקה זו:
@594 **עוד** יתבאר בהעיר עוד למה כפל לומר **ואת אשר יבחר בו יקריב אליו**, אכן ירצה על זה הדרך לצד שבערעורם יש ב' פנים, האחד כי אהרן אינו ראוי כל כך כי יש בהם גדולים וטובים ממנו, והב' שישנו לכיוצא בו בעם הראויים לעמוד לשרת עמו, לזה כנגד מה שנוגע לכהונת אהרן שיש ראוי ממנו אמר **את אשר לו** פירוש אשר מזומן לו לעבודתו מתחילת הבריאה, על דרך אומרו (ירמי' א') בטרם אצרך בבטן וגו', **ואת הקדוש** פירוש אחר שיצא לעולם קדש עצמו ועשה עצמו כלי ראוי לשרת בקודש, ודקדק לומר **והקריב** לרמוז שכבר הקריבו והשרה שכינתו על ידו, וכנגד המובן מהם שרצונם להוסיף עליו אמר **ואת אשר יבחר בו יקריב אליו** אם יש ראויים כיוצא באהרן לעמוד גם כן לשרת יקריב אליו:
@600 **ויקרב וגו'**. צריך לדעת מה היא ההבדלה שאמר בפסוק שלפני זה ומה היא הקריבה שאמר כאן, ואולי שנתכוון לב' הדרגות הא' הוא הבדלת שבט לוי מעדת ישראל בדרך כלל וכנגד זה אמר **כי הבדיל** וגו' **מעדת ישראל** והב' הקרבת בני קהת שהקריבם יותר משאר הלוים לשאת קדש קדשים, ועיין מה שפירשתי בפסוק (ד' ב') נשא את ראש בני קהת, וכנגד זה אמר **ויקרב אותך ואת כל אחיך** פירוש ענף הקהתים בני לוי, ודקדק לומר **אותך** רמז לו שכולן נסמכין עליו והוא גדול שבכולן:
@601 **לכן אתה וכל וגו'**. אומרו **לכן** הוא שבועה, והשבועה היא שנועדים על ה' וזה הוא שיעור הדבר אתה וכל עדתך הנועדים בשבועה שעל ה' אתם נועדים לסתור דבריו, ואמר כן אולי ירתעו וירעדו מלהחזיק במחלוקת:
@602 **וישלח משה לקרא וגו'**. נתחכם בזה לדבר עמם ביחוד שלא בשעת הוועד אולי ירויח דעתם אחד לאחד, גם באמצעות החשיבות אשר הוא מחשיבם לדבר אליהם מכללות הנועדים יתרכך לבם להטות אוזן, ודקדק הכתוב לומר **וישלח משה לקרא** וגו' שלא היה צריך לזכרון משה ויסמוך על זכרונו בסמוך, אלא להעיר מי הוא השולח משה מלך ישראל ונביא ה' לקרא לב' הדיוטות אולי בזה יתעשתו להטות אזנם אליו:
@602 **לא נעלה וגו' המעט וגו'**. אומרו **לא נעלה**, לפי מה שפירשתי שנתחכם משה לעשות להם מעלה לדבר עמהם ביחוד אמרו אין אנו חפצים במעלה זו שאתה מחשיב אותנו לשלוח אחרינו, גם נתכוונו במאמר זה לומר שהגם ששליחות זה יהיה להנאתם לעשות להם איזה כבוד ומעלה אף על פי כן **לא נעלה**, מואסים הם אותה המעלה אשר תבא להם ממשה, ונתנו טעם לדבריהם ואומרו **המעט כי העליתנו** וגו' פירוש הקטן דבר זה שעשית לנו שהעליתנו פירוש עשית לנו הדבר בגדר העלאה וכבוד ביציאת מצרים והיה תכלית העליה ירידה מארץ זבת חלב ודבש שהיינו שם להמיתנו במדבר אם כן מעלותיך אינם אלא השפלות וירידות, ואמרו **כי תשתרר** וגו' פירוש אין טעמך בכל העניינים אלא להשתרר לא להטיב לנו, גם בשליחות זה שאתה שולח אחרינו לא לטובתינו אתה מתכוון אלא להשתרר, והוא אומרו **גם השתרר**, גם נתכוונו בכפל **תשתרר גם השתרר** לומר כי שררותו של משה היא כפולה ומכופלת מהשררה שהיתה עליהם קודם צאתם ממצרים, וזה שיעור הדברים כי תשתרר עלינו בריבוי השררות, והוא אומרו **גם השתרר**, ואולי שרמזו לו גם כן שהוא חפץ להתעכב במדבר להמשיך השררה של עצמו לפי מה שאמרו ז''ל (שמו''ד פ''ה) כי מלכותו של משה לא היתה עומדת אלא במדבר, ולזה אמרו **גם השתרר**:
@604 **אף לא אל ארץ וגו'**. קשה אחר שאמרו להמיתנו במדבר מה מקום להתרעם על מדרגה קטנה ממנה, ורש''י ז''ל ישב בדוחק, ואולי שנתכוונו לומר ששלילת הליכתם אצלו לא לצד גדר הרעה שקבלו ממנו שהוציאם להמיתם במדבר אלא אפילו לצד העדר הטוב המובטחים ממנו לבד, והוא אומרו **אף לא אל** וגו' פירוש אף לצד לא אל ארץ וגו' לטעם זה לבד העיני האנשים וגו' ומכל שכן שסבבם הקרבת הנזק:
@604 **העיני וגו' לא נעלה**. פירוש בוחרים ניקור עיניהם ממעלה אשר יובטחו בה ממנו, בזה גילו עוצם הפלגת השנאה אשר שנואה טובת הצדיק אצלם יותר מניקור עיניהם, לזה חרה אפו של משה מאוד:
@605 **ויאמר אל ה' אל תפן וגו'**. הכוונה לצד שראה הפלאת שנאת הרשעים עמו מזה הכיר היותם בחינת הרע גמור אשר טבעו לשנא בחינת הטוב שנאת מות בלא סיבה, ולזה אמר אל ה' **אל תפן אל מנחתם**, והכוונה בזה לצד שאין לך אדם שאין בידו מצות ומעשים טובים, וכבר קדם לנו שאין הקדוש ברוך הוא מקפח שכר כל בריה ובריה ואפילו של רשעים דכתיב (דברים לב) אל אמונה ואין עול, וצא ולמד משכר פסיעותיו של אותו רשע (סנהדרין צו.) אשר על כן חש משה שתעמוד להם איזה מצוה שבידם שהזכות תולה, לזה בקש מה' ואמר **אל תפן אל מנחתם** פירוש אפילו זכות שכבר הגיעה מנחה לה' לא יפן לה ולא יביט אליה:
@605 **ואם** תאמר איך יבטל מדתו ית' לאנשים ההם לעוות משפטם:
@605 **דע** כי הצדיקים יש כח בהם להפקיע זכות הנמצאת לרשעים כשיראו שהם מוחלטים ברע, והוא סוד (ש''ב כג) צדיק מושל יראת אלהים פירוש מושל ביראת ה' שיעשה האדם אם יראה בעיניהם להפקיע זכותו ממנו יש כח בידם מה שאין הקדוש ברוך הוא כביכול עושה, ותמצא בדין שלמטה כיוצא בדבר שיכולין בית דין להפקיר נכסי אדם רשע כאומרם (גיטין לו:) הפקר בית דין הפקר, ואם תאמר למה לך משה להפליא עונשם של אלו, ואם לצד שנאתם אותו לא מפני זה יתחייבו כל כך עונש, גם יש לבעל הדין לחוש כאן ולומר אין אדם נחשד על דבר אלא אם כן יש בו (מוע''ק יח:), ואם אין בו כולו יש בו מקצתו, לזה אמר לפני ה' טעם המספיק לחייבם, והתחיל להסיר מיחוש החשד ואמר **לא חמור** וגו' פירוש אין להם מקום לחושדני ממנו בשררה, שהרי דרך המלכים לקחת צורכיהם מהעם ובפרט בעניינים שהם לצורך העם, והוא אפילו חמור אחד שהיה צריך לו לבוא עליו ולגואלם לא נשא, ואם כן מנין להם מקום לחושדו בשררה:
@605 **והוסיף** לומר **ולא הרעותי** וגו' פירוש תאמר שיש להם שנאה עמי לאיזו סיבה שגרמתי להם בדבר הרגיל בעולם שיארעו דבדים בין בני אדם שמהם יומשכו איבות, **לא הרעותי** וגו' פירוש מימי לא עשיתי להם רעה שתמשך להם שנאה עמי מסיבתה, ודקדק לומר **את אחד מהם** פירוש אפילו בהמשכת הרע מאחד מהם לחברו לא סיבבתי, כמו שתאמר לא באו לפני לדין וחייבתי את הזכאי או זכיתי את החייב שהרע הוא את אחד מהם פירוש שכשמחייב ממון לאחד לתת לחברו הרעה נמשכת לו מחברו שנוטל ממנו מה שאינו חייב לו, ואפילו זה לא עשה עליו השלום לצד שהיה דן בנבואה דין אמת לאמיתו, וכמו שאמרו ז''ל (זוח''ב עח.) בפסוק כי יהיה להם דבר בא אלי, מעתה אין סיבה לשנאתם וחשדם בשום אופן ואין זה אלא לצד היותם חלק רע גמור וטבע הרע לשנוא הטוב שנאה עזה טבעית בלא סיבה, מעתה כל כיוצא בזה מצוה לעקרו ולהפקיע זכותו לבל יפן ה' למנחתם כי באבוד רשעים רנה, וסובר אני כי האנשים הרשעים האלה אינם בכלל עדת קרח שנאמר עליהם (סנהדרין קח.) מוריד שאול ויעל שאלו אבדה תקותם שכולן ענף הקליפה כן יאבדו כל אויבי ה':
@606 **אתה וכל עדתך היו וגו'**. קשה היה לו לומר **אתה וכל עדתך ואהרן** וגו' ובזה לא היה צריך לחזור ולומר **אתה והם**, אולי שנתכוון להזמין הנועדים לבא מחר לברר הדבר, ונתכוון בזה לבל יהיו נשמטים מיום אל יום ויתרבו עליהם מאוהבי המחלוקת, לזה רצה להכריחם לבא מחר לפני ה', אשר על כן לא הזמין אלא הבאים במחלוקת, קרח ועדתו, מה שאין כן אהרן, אלא שהזכירו שיקח מחתתו עמהם:
@606 **עוד** ירצה לומר שיכינו עצמן בקדושה ובטהרה כדי שיהיו ראויים להיות לפני ה', והוא מאמר **היו לפני ה'**, ואולי כי לזה נתן להם זמן ואמר **מחר**, ובפרט זה לא שתף עמהם אהרן כי מוכן ועומד הוא, אלא שהזכירו אחר כך ואמר **אתה והם ואהרן** שגם הוא יהיה עמהם, והגם שכבר אמר להם הדברים עצמן למעלה דכתיב קחו לכם מחתות וגו' לפני ה' מחר, לפי שהוכיחם בדברים אחרי כן ואמר להם המעט מכם וגו' רב לכם בני לוי וגו' תוכן הדברים יגיד הפכיות מה שאמר מקודם, לזה כשלא קבלו התוכחה חזר לומר דברים הראשונים לעשות מבחן הקטרת:
@607 **חמשים ומאתים וגו' ואתה ואהרן וגו'**. כל זה מיותר שכבר אמר **אתה וכל עדתך** וגו' **ואהרן**, ואם רצה לומר חשבון כולם, למעלה כשאמר עדתך שם היה לו לומר מאתים וחמשים ולא היה צריך לחזור ולהזכיר **אתה ואהרן**, ואולי שנתחכם לומר שלא יתערב קרח עם הר''ן אלא ביחוד עם אהרן, ועשה כן כדי שלא יהיה מקום לטועים אחר קרח לומר כי דבקתו הרעה לצד היותו עם ריבוי מקטירי הקטרת אבל אם היה בפני עצמו היה כאהרן, לזה אמר לו **ואתה ואהרן** בפני עצמיכם איש מחתתו, והגם שכולן הקריבו יחד, עם כל זה נעשו ב' כתות כת אחת קרח ואהרן וכת ב' ר''ן איש:
@609 **ויקהל עליהם וגו'**. פירוש שלא נקהלו לרצונם אלא קרח הקהילם, וכפי זה יגיד הכתוב שבח העדה. או ירצה לתת טעם למאמר ה' שבא אחר כך **הבדלו מתוך העדה** וגו' **ואכלה אותם**, ויאמר האומר אם קרח ועדתו חטאו אלה הצאן למה יכלו, לזה הקדים ואמר כי נקהלו לרצון קרח ולחיבתו ולזה נראים כחפצים במעשיו ולזה אמר ה' הבדלו וגו' ואכלה אותם:
@609 **וירא כבוד ה' וגו'**. נתגלית שכינתו יתברך לכל העדה כדי שיכירו כי הוא העושה משפט כתוב והוא הבורר הראוי לשרת לפניו:
@611 **הבדלו מתוך וגו'**. לא על משה ואהרן הוא אומר כי לאלה לא תפגע מדת הדין הגם שיהיו בתוך העדה הכלה ח''ו, וזה לך האות אהרן שהיה בתוך עדת קדח ונבקעה האדמה תחתיהם ולא נפגע, אלא כוונת מאמר ה' הוא על הצדיקים שהיו בתוך העדה כיהושע וכלב ושאר הצדיקים ובני בתיהם של משה ואהרן ושל שאר הצדיקים, ולזה אמר קודם למאמר הבדלו **וידבר ה' אל משה** וגו' **לאמר**, ואם על משה ואהרן הוא אומר לא היה צריך לומר תיבת **לאמר**, אלא לאמר לעדת הצדיקים הבחונים אצלם ולבניהם ובני ביתם שהיו בתוך העדה:
@611 **ואכלה אותם כרגע**. צריך לדעת למה אמר **כרגע** ואם להודיע כי הוא שגיא כח להרוג ששים ריבוא כרגע כבר הודיע זה מקודם דכתיב (שמות לג) רגע א' אעלה בקרבך וכליתך. ונראה לפי דברי המדרש (רבה) שהביא רש''י בפסוק ויפול על פניו זה בידם סרחון רביעי, בעגל במתאוננים במרגלים וכו' עד כאן. אם כן עון המרגלים קדם למחלוקת קרח, ושם פירשתי כי גזירת כליה שגזר ה' על הדור ההוא נתקיימה אלא שהועילה תפלת משה שלא ימות העם כאיש אחד אלא בהמשך זמן ארוך, אם כן העדה כבר היא מחוייבת כליה, לזה בא מאמר ה' כאן בחידוש הגזירה שיהיה **כרגע** פירוש שלא יאריך להם הזמן כמו שנתרצה מקודם, ולדרך זה מצאנו נחת רוח לקושיא שבענין למה יגזור ה' מיתה על עדת ישראל שלא היתה ידם במעל וכמו שנתגלה ממאמר משה בסמוך, ולדברינו לצד שכבר היו ישראל מחוייבי מיתה מעוון המרגלים אלא שה' האריך להם זמן ואמרו ז''ל (שבת לב.) שהשטן מקטרג בשעת הסכנה, וציוו למי שיש בידו שיחה בין ישתבח ליוצר לחזור מעורכי המלחמה (ירושלמי) הגם שאין בחטא כדי להמית, וכמו כן במה שלפנינו כיון שהיו מחוייבי מיתה אין נמלטים בצאת המשחית ויכלו באפס תקוה:
@611 **שוב** הצצתי וראיתי כי דברי ה' כאן הם רפואה ותעלה לעדת ישראל, כי אם לא היה ה' אומר **הבדלו מתוך העדה** והיה יוצא המשחית היו נמלטים הצדיקים שלא היו בכלל גזירת המרגלים וכל שהיו בכלל גזירת המרגלים היה המשחית מכלה אותם, ולומר ה' לישראל שיהיו נבדלים מהם לבל יקר להם מקרה רע, לא היה להם זכות לזה שהרי סוף סוף היה בידם שמץ מהחטא שלא מיחו בקרח ואדרבא באו לרצונו, לזה נתחכם ה' וצוה למשה ואהרן להבדיל הצדיקים והעירו לבקש רחמים עליהם ובאמצעות זכותו של משה אמר ה' אליו **דבר אל העדה** וגו' **העלו מסביב** וגו', ולדרך זה נוכל לפרש כי מאמר ה' שאמר למשה ואהרן **הבדלו** לא בא הדיבור אלא להעירם להתפלל לא שהיה צריך משה להבדיל לבל יספו בחטאת קרח, ואולי כי הוא זה מה שרמז במאמר **לאמר** פירוש שתכלית המאמר האמור בענין הוא לאמר מאמר הבא אחריו שהוא ענין הבדלת ישראל מעדת קרח כי לענין משה ואהרן אין צריכין להבדל, וכפי זה אין אנו צריכין למה שפירשנו שבא הדיבור על בני בתיהם ועל הצדיקים שכיוצא בהם:
@612 **ויאמרו אל אלהי הרוחות וגו'**. אמר שם **אל**, לצד שראה התעוררות תגבורת הדינים הזכיר חסד אל למתק הדינים ואומרו **אלהי הרוחות לכל בשר** טען טענה הנשמעת לפני הבורא כי ה' חפץ שכל הרוחות יקבלו אלהותו עליהם בעודם בבשר בעולם הזה והוא אומרו אלהי **הרוחות** פירוש הרוחות הוא לשון מחשבה ורצון על דרך אומרו (יחזקאל כ) העולה על רוחכם, ואם כן הגם שהמשפט אשר יעשה לכלותם כרגע הוא משפט אמת וכמו שכתבתי הטעם למעלה, עם כל זה לפי הנראה במעשה הוא שאיש א' יחטא ועל כל העדה תקצוף שאין כל העדה בחטא זה ואתה ממית כולן ומעתה ח''ו הרוח תמאן באלהות כזה:
@612 **עוד** נתכוון לדבר לפניו דברי ריצוי המתקבל לפניו, על פי מה שקדם לו בידיעת הדרגת החפץ שיש לבורא, האחד הוא שבח והלל אשר יתגו לו צבא מעלה, למעלה ממנו שבח והלל אשר יתנו לו נשמות הצדיקים מב' אוצרות החיים, אוצר א' של נשמות שעדיין לא באו לעולם הזה שעליהם אמרו ז''ל (יבמות סב.) עד שיכלו נשמות שבגוף, ואוצר ב' של נשמות שכבר באו לעולם הזה וחזרו ונתנו באוצר החיים, וכולם נותנים שיר ושבח והודאה לבורא יתעלה שמו בסוד (משלי טז) כל פעל ה' למענהו. למעלה מהם השיר והשבח העולה מהנשמות אשר הם בעולם הזה אשר הם תוך הבשר והוא מונעם מהכיר ה' והם מתעצמים לאהוב ה' ולשבחו ולהודות למאמרו זה עליון וחשוק אצל הבורא למעלה מהכל, וכמו שמבוארים הדברים בהרחבה בספר הזוהר גם בדבריהם ז''ל:
@612 **ולזה** נתחכם משה וריצה ה' בדבר שהוא חפץ בו ואמר **אלהי הרוחות לכל בשר** שאתה חפץ שאלהותך תהיה לרוחות בזמן שהם בבשר, ואם אתה ממיתם אתה חסר רצון זה, ואין נכון להגביר הדינים שיסובבו הפסד קבלת אלהותך לרוחות שבבשר שהוא רום תכלית חשקך, ואמר האיש **אחד** יחטא לומר שכפי הדין אין להם חיוב כי כולן לא חטאו לחייבם אלא אתה בא עליהם בקצף שהוא תגבורת הדין, והוא אומרו תקצוף:
@612 **האיש אחד יחטא**. אמר לשון עתיד, לצד שעדיין לא חטא חטא שחייב עליו מיתה שהיא ההקרבה כי עד עתה לא עשה אלא לגלוג ואם היה חוזר בו אין עליו חיוב:
@614 **דבר אל העדה לאמר**. אמר **דבר** לשון קושי בענין זה שאינו אלא טובה להציל נפשם, להגיד כי יקפיד ה' על הרוצה לחבול בעצמו שלא לעלות, לזה בא דבר מלך שלטון להכריחו לעלות לבל יפסידו עצמן שהם נכסי שמים, ואמר תיבת **לאמר** פעם ב' ולא הספיק במה שקדם לומר **וידבר** וגו' **לאמר**, לצד שאמר דיבור לשון קושי הודיע כי קושי זה עצמו הוא לרוממות עם סגולה שיקפיד ה' על חסרונם. עוד נתכוון בתיבת **לאמר** שאין חיוב לומר בלשון זה עצמו **העלו** וגו' אלא בלשון שיהיה המכוון בו העלו וגו' ואפילו יאמר בלשון אחר, ולזה תמצא שלא אמר העלו אלא סורו נא וגו', ובמקום שיאמר משכן קרח וגו' אמר מעל אהלי האנשים הרשעים האלה:
@615 **ויקם משה וילך וגו'**. צריך לדעת טעם אומרו **ויקם**, ואם להודיע שהיה יושב מה יצא לנו מהודעה זו, אכן ירצה על דרך אומרו (משלי טז) לפני שבר גאון ולפני כבוד ענוה, ואמרו ז''ל (שמו''ר פמ''ה) השפלתי הגבהתי, והוא מאמר הכתוב ויקם משה קימה היתה לו במה שהלך לדתן ולאבירם האנשים הרשעים אשר חרפוהו ולא רצו לבא אצלו והשפיל עצמו הוא והלך אצלם, עליהם נאמר לפני שבר גאון, ועל משה ולפני כבוד ענוה:
@616 **וידבר אל העדה לאמר**. פירוש **לאמר** שיאמר להם שכן נאמר לו מפי הקדוש ברוך הוא לומר להם:
@616 **סורו נא מעל אהלי האנשים הרשעים**. נתחכם עליו השלום לזכותם בנועם דבריו באמצעות שיעריכום בערך רשעים, והוא אומרו **האנשים הרשעים** פירוש שיהיו בעיניהם ערך רשעים ויסורו מעליהם כי יאמינו בכליונם ויראו פן תדבקם הרעה ובשכר זה יחוננם ה', והגם שכבר נתרצה ה' לומר להם העלו, עם כל זה הצדיקים חפצים לצדק בני דורם לאכול מפרי דרכם:
@617 **ויעלו מעל וגו' ודתן ואבירם יצאו וגו'**. יודיע הכתוב עוצם רשע הקליפות שאפילו אחר שראו שישראל יראו לנפשם פן תדבקם הרעה אשר תמצא את דתן ואבירם אף על פי כן יצאו נצבים, ומזה נתרגש משה ואמר **בזאת תדעון** וגו' פירוש כיון שראה שלא הרגישו דתן ואבירם מההרגש שעשו ישראל שעלו מסביב ואדרבא יצאו בקומה זקופה דן משה בדעתו בודאי כי הרשעים חושבים ברעתם כי משה עושה דברים אלו מדעתו בתחבולות וערמות לומר להם להתרחק כדי שיראו ויחתו ולא מדברי ה', לזה אמר **בזאת תדעון כי ה' שלחני לעשות את כל המעשים האלה** פירוש אפילו פרטי דברים אלו, והתנה כי מלבד שימותו עוד להם שימותו מיתה משונה מכל המיתות ובסמוך יתבאר עוד:
@618 **בזאת תדעון וגו' כי לא מלבי**. צריך לדעת איך יחשוב משה לעם ה' שעדיין לא האמינו בו לנביא אמת, עוד למה כפל לומר **לא מלבי**, ואולי כי צד החשד היה על זה הדרך כי לצד שמצא משה חן בעיני ה' כשהיה משה חפץ לתת גדולה לאחד מקרוביו כגון הכהונה לאהרן והנשיאות לאליצפן וכדומה היה עושה ונמלך בה' והיה ה' מסכים על ידו, או היה חפץ וחושק בלבו לתת לאחיו וכדומה וה' נתן לו תאות לבו, אבל לא לצד שיש עיכוב בדבר כי הוא זה הראוי לכהונה, לזה אמר **בזאת תדעון כי ה' שלחני** לעשות את וגו' לא שהייתי עושה והוא מסכים על ידי למה שהייתי חפץ בדעתי, וכנגד חשש הב' שהיה חושק בלבו על הדבר אמר **כי לא מלבי** פירוש לא הייתי אני חפץ בדבר וה' מסכים על מה שבלבי, ושיעור תיבת **כי** הוא על זה הדרך טעם שאיני צריך להוכיח שה' שלחני לשלול שאני עושה מה שלא הסכים ה' עליו, אלא לשלול שלא מלבי היו הדברים כנזכר והבן:
@618 **אם כמות כל האדם**. פירוש על דרך אומרם בפסוק אשר יעשה אותם האדם אפילו גוי, (ב''ק לח.) וכאן נתכוון לומר שאפילו במיתת האומות שהיא מיתה מנוולת זה בערך המיתה עצמה וכנגד הגוף אמר **ופקודת כל האדם** וגו' על דרך אומרו (מ''ב ט) פקדו את הארורה וקברוה קברו כדרך כל הארץ, **לא ה' שלחני** פירוש אלא מלבי וה' לא מיחה בי, **ואם בריאה** וגו' שבזה תהיה להם מיתה רעה ויאבדו גוף כנפש:
@620 **ואם בריאה וגו'**. כפל לומר **בריאה יברא ה'**, יתבאר על דרך אומרם ז''ל (סנהדרין לז:) בפסוק ארור וכו' האדמה אשר פצתה את פיה שמאותו יום נסתם ונחתם פי הארץ, וכשהיא רוצה לומר שירה לפני ה' כדרך כל הנבראים שאומרים שירה לפני הבורא היא אומרת בכנפיה דכתיב (ישעי' כד) מכנף הארץ זמירות שמענו, וכאן כשרצה משה להעניש הרשעים ההם אמר **ואם בריאה** פירוש אותה בריאה שכבר ברא ה' שהיא פי הארץ ועל ידי מעשה נסתם והיה כלא היה עתה יחזור ה' לברוא אותה הבריאה שיהיה לה פה ופצתה הארץ את פיה שהיה לה מקודם ובלעה אותם. ואולי כי זה יהיה לה תיקון למה שפצתה לבלוע איש צדיק עתה תפצה פיה לבלוע אויבי ה':
@621 **ככלותו וגו' את כל הדברים**. פירוש לא איחרה ולא קדמה אלא המתינה עד שאמר כל הדברים הצריכין בענין ותכף לכלותו נבקעה:
@621 **ותבקע האדמה וגו' ותפתח הארץ וגו'**. ולא הספיק לומר **ותפתח** וגו' או **ותבקע** עוד אמר בבקיעה האדמה ובפתיחה **הארץ**, אולי כי לא היה שם פה הארץ במקום דריסת רגליהם לזה נבקעה האדמה אשר היו עומדים עליה ונזדמן שם פה הארץ ונפתחה, ולזה כנגד המקום שהיו עומדים בו אמר **ותבקע האדמה**, וכנגד פי הארץ אמר **ותפתח הארץ** וגו':
@623 **וירדו וגו' שאולה**. פירוש שלא שלטה בהם הארץ להורגם אלא נשארו חיים ונתנתן הארץ בפקדון לגיהנם, והוא אומרו **חיים שאולה** ולא אמר לשאול, והגם שכל תיבה שצריכה למ''ד בתחילה הטיל לה ה''א בסופה, **עם** כל זה לא לחנם יעשה כן, ויכוין שאחר שירדו לשאול נתן ה' בהם כח ולא מתו, ע''ד אומרם ז''ל (סנהדרין ק:) שהקב''ה נותן כח ברשעים לקבל ענשם, כמו כן אלו נשארו חיים אחר שהיו בשאול עצמה כדי שירבה הרגשתם, ואם היה אומר לשאול היה נשמע שלא היו חיים אלא עד הגעתם לשאול ובהגיעם מתו ולא היה להם חיות אחר שהגיעו לשאול:
@627 **אמור אל אלעזר**. טעם **אלעזר** לצד שלא החשיב ה' הדבר שיעשה על ידי אהרן שהוא כהן גדול, או לצד שעל ידי אהרן נעשה המשפט ומתו מקריבי המחתות לא רצה ה' שיעשה על ידו הרמת המחתות:
@627 **וירם את המחתות**. צריך לדעת למה אמר **וירם** בוא''ו כיון שזה הוא התחלת המצוה. ונראה שנתכוון להוסיף על ענין ראשון שהוא בליעת קרח ועדתו שראו עם בני ישראל כי מה' יצא דבר כהונת אהרן ועוד הוסיף תוקף וחוזק הכהונה ביד אהרן לדורות שירם המחתות וגו' ועשו אותם רקועי פחים וגו' ויהיו לאות לבני ישראל וגו' זכרון לבני ישראל וגו':
@628 **החטאים האלה בנפשותם**. אולי שנתכוון להוציא מלבם לבל ידאגו על היות הדבר בסיבתם, גם לבל יחשוב אדם מישראל כי הם היו להם סיבה, לזה אמר **החטאים הא לה בנפ שותם** פירוש שהם חבלו בעצמן וחסרו נפשם ולא היה להם סיבה מזולתם, ואף על פי כן מצינו שלא הרגישו ישראל בכונת ה' בדברים אלו וילונו על משה וגו' אתם המיתם את עם ה':
@628 **כי הקריבום לפני ה' ויקדשו**. פירוש טעם שאני מצוך להרים המחתות לא שנתרציתי בקטורת שהקריבו לפני אלא במה שהקריבום פירוש לגופן של מחתות, וקודם שנתנו עליהם קטורת אשר היא זרה ומאוסה אצלי כבר נתקדשו המחתות, והוא אומרו **ויקדשו**, ומידי דהוה כמקריב כלי כסף וכלי זהב למקדש שהם קודש, והגע עצמך אם המקריבין היו נמלכים וחוזרים בהם ולא היו נותנים הקטורת על האש מי היו יוצאין המחתות לחולין, ומעתה לא מפני שנתנו הקטורת עליהן יצאו המחתות מקדושתן, ומה שטען רמב''ן כנגד רש''י וזה לשונו זה דומה לזר שעשה כלי שרת להקטיר בחוץ, עליו אמר הכתוב הקריבום לפני ה' באוהל מועד פירוש שהקדישום והביאום למקום המקודש:
@630 **למען אשר לא יקרב וגו' ולא יהיה וגו'**. צריך לדעת למה הוצרך לומר **ולא יהיה** וגו', ורז''ל אמרו (סנהדדין קי.) שבאה אזהרה למחזיק במחלוקת שעובר בלאו של ולא יהיה וגו', וחוץ מדרכם ז''ל נראה שנתכוון ה' לתת טעם למה הוצרך **לזכרון** זה ולא הספיק באזהרה בתורה לא יקרב איש זר וכל הקרב וגומר תבלענו הארץ, לזה אמר **ולא יהיה כקרח** פירוש אם אני מצוה בלא זכרון זה אני חושש שלא יועיל לאיזה אדם מהם באזהרה וימות כקרח ועדתו, וזכרון זה יועיל שלא יסובב לו להיות כמו שהיה לקרח ולעדתו:
@630 **כאשר דבר ה' ביד משה לו**. פירוש לצד שאמר **ולא יהיה כקרח** וגו' ממוצא דבר אתה למד שכל העומד מקודם לערער על הכהונה יהיה לו כקרח וכעדתו ודבר זה לא מצינו שהתרה ה' כן, לזה אמר **כאשר דבר ה' ביד משה לו** פירוש לקרח הא למדת שהדברים שאמר משה לקרח ואם בריאה יברא ה' ופצתה האדמה את פיה וגו' היו דברי ה' ביד משה להתרותו ולא אמרן משה מעצמו, והוא אומרו **ביד משה לו** פירוש לקרח המוזכר בסמוך:
@631 **וילונו כל וגו' לאמר אתם וגו'**. צריך לדעת אומרו **לאמר** אחר שהתלונה היא על משה ועל אהרן מה מקום לומר **לאמר**, ואולי כי העם לא אמרו הדברים ככתבן אתם המיתם את עם ה' אלא אמרו דברי תלונות שכונת כללות דבריהם היא אתם המיתם וגו', לזה אמר **וילונו** וגו' וכוונת תלונתם היא **לאמר** להם אתם המיתם וגו':
@631 **עוד** ירצה בהעיר עוד איך טח מראות עיניהם לעשות תלונה על משה בלא סיבה מה פשעו ומה חטאתו, ומה גם אחר שראו כמה השפיל עצמו לפני דתן ואבירם אולי ישובו וכו' זה יגיד שהשתדל לבל ימותו. אכן תרעומת העדה היתה על מה שעשה משה המבחן של הקטרת בכולן יחד שהיה לו לעשות המבחן בקרח לבד וכשהיה ה' עושה בו המשפט לא היו נגשים המאתים וחמשים נשיאי עדה ולא היו מתים, והוא אומרו **לאמר אתם המיתם** וגו' פירוש במאמרכם שאמרתם להם קחו איש מחתתו וגו' חמשים ומאתים בזה המיתם את עם ה', ולא התרעמו העדה על מיתת קרח דתן ואבירם אלא על המאתים וחמשים שכולן היו ראשי סנהדראות, ולדברי רז''ל שאמרו שתרעומת העדה היתה למה שציום להקטיר הקטורת שהיא עבודה יותר קדושה וחמורה ולא עשה המבחן באחד משאר עבודות, יתבאר גם כן על זה הדרך **לאמר אתם המיתם** פירוש במאמרכם שאמרתם להם להקטיר קטורת אתם הייתם סיבה שימותו:
@635 **הרמו מתוך וגו'**. פירוש לא על משה ואהרן הוא מדבר אלא על אותם שלא היו בכלל המלינים, והעד הנאמן אומרו **וידבר** וגו' **לאמר** ופירוש לאחרים, ודקדק הכתוב לומר **הזאת** להראות באצבע במלינים לשלול זולתם שאינן בכלל הכליון, ובזה נתיישב למה הוצרך לומר **הרמו** והרי יכול ה' להמית רשע לפני צדיק כמעשה הריגת בכורי מצרים, ולפי דברינו שעל שאר העם שלא היו בכלל המלינים הוא אומר לפי שהיו בכלל גזירת המרגלים יש צורך בדבר להתרחק לבל תפגע בהם מדת הדין, ומאמר **כרגע** פירשתי למעלה (ט''ז כ''א):
@636 **קח את המחתה**. להיות שאמרו כי סיבת השרופים היתה בשביל הקטרת הקטורת שהוא סבב מיתת עם ה' לזה הראה להם כי הגם שהקטורת היה חוץ לזמנו וחוץ למקומו אדרבא עצר המיתה מעל ישראל, ובזה יצדיקו כי הכל מעשה ה' כי הוא ממית לחייב באין סובב, ורז''ל אמרו (שבת פט.) כי דבר זה למדו מס''מ בעלותו לקבל תורה:
@637 **ויקח אהרן כאשר וגו'**. פירוש סמוך לדיבורו של משה ללמדך שלא שהה אפילו רגע. עוד ירצה לצד שהענין כאן הוא הפך הדין להקטיר קטורת חוץ לזמנו וחוץ למקומו, לזה אמר **ויקח אהרן** וטעם ויקח הוא כאשר דבר משה פירוש על פי נביא, ויאמן נביא כשיאמר לעבור על מצוה אחת ממצות התורה לפי שעה, וכאליהו בהר הכרמל (מ''א י''ח):
@638 **ויעמוד בין המתים וגו'**. יתבאר על פי דבריהם ז''ל (תנחומא תצוה סי' טו) שאמרו שתפסו למלאך המשחית ומנעו מהשחית ומנה המומתים לבל יוסיף עליהם, והוא אומרו **ויעמוד בין המתים ובין החיים** פירוש שהגביל מספר המתים מבין החיים לבל יוסיף הכות עוד, ולזה אמר **ויהיו המתים במגפה** י''ד אלף וז' מאות, לומר אלה הם שעמדו במספר המתים ותעצר המגפה שלא יוסיף עוד הכות על מספר זה:
@640 **וישב א הרן וגו' והמגפ ה נעצר ה**. חזר לומר **והמגפ ה נעצרה** אחר שכבר אמר ותעצר המגפה, לומר שאפילו אחר שכלה ענן הקטורת ושב אהרן אל משה נשארה המגפה עצורה, שלא תאמר שלא נעצרה אלא כל זמן שהיה עולה ענן הקטורת על דרך אומרו (שמות יז) כאשר ירים משה ידו וגו':
@640 **עוד** יתבאר ע''פ דבריהם ז''ל (תנחומא שם) שאמרו שלא קבל המשחית מאהרן שאמר לו אני שלוחו של מקום עד שהביאו אל פתח אהל מועד ושמע מפי השכינה, והוא אומרו **והמגפה** פירוש מלאך המשחית נקרא מגפה גם הוא החליט להעצר, ולזה דקדק לומר **והמגפה נעצרה** ולמעלה אמר **ותעצר המגפה** פירוש היתה לה מניעה מאהרן אבל הוא לא היה רוצה לימנע מה שאין כן אחר כך גם המגפה הסכימה להיות נעצרה:
@642 **דבר אל בני ישראל וקח מאתם**. אומרו **דבר** וגו' **וקח מאתם** שנראה שהם ב' ענינים, לצד שיצו ה' על ישראל להביא המטות ועל משה לקחת מאתם לזה אמר **דבר וקח**, והגם שלא הזכיר הבאת ישראל, רמזה בכח ו' של **וקח**, עוד נראה טעם אומרו **וקח** בתוספות וא''ו להוסיף על ענין ראשון מלבד זכרון המחתות אשר עשאום ריקועי פחים וגו' עוד **קח מאתם** וגו' להראותם כי באהרן בחר לו יה:
@642 **מאתם וגו' מאת כל נשיאיהם**. טעם שהוצרך לומר **מאתם** ולא הספיק לומר מאת כל נשיאיהם, לעכב שלא יקח המטות אלא מאתם ולא יקח משה בעדם, ואם היה אומר קח מאת נשיאיהם מטה מטה לא הייתי מתחייב לומר שהם יביאו והייתי אומר שהוא הדין שיקח משה בשבילם ושלוחו של אדם כמותו, או הייתי אומר שכוונת אומרו **מאת נשיאיהם** וגו' שיהיה משלהם ולעולם משה יקח, לזה בא מאמר **מאתם** לעיכוב, וטעם הדבר כדי שלא יהיה מקום לומר כי משה בחר להם עץ לא יצלח:
@643 **ואת שם אהרן תכתוב על מטה לוי וגו'**. ממה שלא צוה מקודם לקחת מטה למטה לוי יגיד כי הוא בכלל הי''ב מטות שאמר בסמוך שנים עשר מטות ומטה לוי בכלל הי''ב, ואפשר לומר שככה עשו שלקחו עץ אחד וחלקוהו לי''ב חלקים וכל שבט לקח שיבא מכשורא ואין הפרש בין של אהרן לשל כולן שבזה יצדק המבחן, ובזה ידוייק מאמר הכתוב **ויתנו אליו כל נשיאיהם** וגו' **ומטה אהרן בתוך מטותם** פירוש חלק א' מתוך העץ שממנו לקחו מטותם. שוב בא לידי מאמר רז''ל (במד''ר פי''ח) שאמרו כדברינו:
@645 **והיה האיש אשר אבחר בו וגו'**. ולא הספיק כל מה שעשה ה' בקרח, אולי שהיו חושבים כי מה שאירע לקרח הוא על שדבר נגד משה וחלק עליו וה' ינקום נקם על כבוד נביאו נאמן ביתו ולעולם אפשר שיבחר בשאר השבטים לשרתו, לזה צוה ה' לעשות מבחן המטות:
@648 **ויגמול שקדים**. רז''ל אמרו (שם) טעם שקדים להעיר שכל המערער על הכהונה פורענותו ממהרת לבוא ע''כ, ונראה שהוכרחו לומר כן שאין ראוי לבעל הנם לבקש פרי הממהר להפריח שנראה ח''ו הפחתת היכולת שמבקש אחר פרי שממהר, לזה אמרו כי יש טעם בדבר שהוצרך להפריח שקדים ולא פרי אחר לומר שממהר ליפרע וכו' שזולת זה היה מוציא חרוב:
@651 **ויעש משה כאשר וגו' כן עשה**. טעם שכפל הדבר ירצה על זה הדרך **ויעש כאשר צוה ה'** וגו' פירוש תיכף ומיד כשציוהו ולא איחר, **כאשר צוה ה'** פירוש להשיב כן עשה, וכפי זה מאמר **כאשר** נמשך למעלה ולמטה:
@653 **כל הקרב הקרב וגו'**. נתעוררו עתה ולא קודם הגם שכבר נאמר להם דבר זה, על דרך אומרם (שהש''ר בפ' ישקני) מאן דנכים ליה חויא מהבלא וכו':
@654 **אתה ובניך ובית אביך**. פירוש **בית אביך** נראה בעיני שבא על משה שהוא מאביו שגם עליו באה האזהרה, דאלו על הקהתים הלא כהם כשאר ישראל בהכנסת משכן ה', ועוד ממה שאמר בסמוך וגם את אחיך בני לוי וגו' יגיד שעד עתה לא היה מדבר בהם, אלא נראה פירוש **בית אביך** זה משה וכמאן דאמר (זבחים קב.) שלא פסקה כהונה ממשה, ואפילו למאן דאמר שלא נתכהן משה אלא בשבעת ימי המילואים סובר אני שלא נאסר ליכנס למקום דריסת רגלי הכהנים, ורז''ל אמרו (ספרי) וזה לשונם בית אביך אלו הלוים מלמד שהלוים מוזהרים על ידי הכהנים עד כאן לשונם, וזה דרך דרש לדרוש בכתוב ההלכות שהיו להם מסיני:
@654 **אתך וגו'**. צריך לדעת למה אמר **אתך** אחר שהזכיר אהרן בפירוש. ואולי שבא לומר שבכל זמן מוזהרים יחד, לבל תאמר שיש זמן שחייב אהרן ויש זמן שחייבים בניו תלמוד לומר **אתך** לומר שמוזהרים יחד בכל הזמנים:
@656 **גם הם גם אתם**. פשט הכתוב הוא **גם הם** כישראל הקרבין **גם אתם** בעדם כמו שקדם לומר אתה וגו' תשאו עון וגו'. ורז''ל אמרו בערכין (יא:) וזה לשונם תניא גם הם גם אתם אתם בשלהם והם בשלכם במיתה, הם בשלהם אינם במיתה אלא באזהרה, אמר אביי משורר ששער בשל חברו במיתה עד כאן. וכתב רש''י דלית ליה לאביי הא מתניתא דקתני הם בשלהם אינם במיתה ואשכח תנא דקאי כותיה עד כאן:
@656 **ורמב''ם** ז''ל בפרק ג' מהלכות כלי המקדש כתב וזה לשונו או שסייע לוי במלאכה שאינה מלאכתו חייב מיתה שנאמר ולא ימותו אבל כהן שעבד עבודת לוי אינו במיתה אלא בלא תעשה עד כאן, וקשה לכל מה שכתב רמב''ם, בין מה שכתב או שסייע בן לוי וכו' שהרי לכל הסברות שהביא בגמרא לא משמע כן, אם כתנא דברייתא הרי קתני בפירוש הם בשלהם אינם במיתה, אם כתנא של מעשה רבי יהושע בן חנניה, אם כמו שעלה על דעת התלמוד שאמר תנאי היא שרבי יהושע סובר המשורר ששער באזהרה ולא גזרו מסייע ורבי יוחנן סובר במיתה וגזרו מסייע אם כן בין למר ובין למר מסייע אינו אלא גזירה מדרבנן ולמה פסק רמב''ם או שסייע בן לוי וכו' במלאכה וכו' חייב מיתה, ואם לפי מה שדחה הש''ם דכולה עלמא באזהרה וכו' אם כן משורר ששער ממש אינו חייב ומכל שכן מסייע, ואם דעת רמב''ם היא כאביי, ב' תשובות בדבר, א' שאביי לא אמר שסייע אלא משורר ששער ומדברי הש''ס מוכח שיש הפרש בין העושה למסייע, ב' שאביי דורש חיוב לזה מפסוק והזר הקרב יומת ורמב''ם ז''ל כתב דכתיב ולא ימותו שהוא פסוק ולא ימותו גם הם גם אתם, בין מה שכתב רמב''ם בדין כהן שעבד עבודת לוי שאינו במיתה קשה כי מהברייתא שהביא בש''ס (ערכין) שאמרה אתם בשלהם והם בשלכם במיתה ולא הביא התלמוד תנא שחולק בדבר משמע שכן עלה בידם הדבר, ולמה יחלוק הרמב''ם על הגמרא:
@656 **ונראה** כי רמב''ם ז''ל תלא זייניה בברייתא הובאה בספרי (ספרי זוטא) וזה לשונם וכבר בקש רבי יהושע בן חנניא לסייע את רבי יוחנן בן גדגדא בהגפת דלתות אמר לו חזור לאחוריך שכבר אתה מתחייב בנפשך שאני מן השוערים ואתה מן המשוררים עד כאן, הרי שבן לוי חייב על עבודת בן לוי אחר, ואנו שומעין גם כן שאפילו אינו אלא מסייע חייב מיתה והוא פסק רמב''ם עצמו:
@656 **והגם** שמהתלמוד משמע בהפך הכריע הרמב''ם כגירסת ספרי מב' טעמים, א' כי לדברי התלמוד בין לקא סלקא דעתך בין למה שדחה התלמוד דכולה עלמא באזהרה בין לרבי יהושע בין לרבי יוחנן אין המשורר יכול להיות שוער ולא נחלקו אלא במסייע אם כן מה הוא זה שאומר רבי יוחנן חזור בך שאתה מן המשוררים וכו' הלא גם רבי יהושע יודע זה, ולא היה לו לומר אלא חזור שאף המסייע אסור משום גזירת רבנן, ועוד כשנאמר שהמשורר אינו יכול להיות שוער מה לי שוער לבדו או עם אחר הלא מלאכת השוערים כך היתה שהיו מתקבצים בכנופיא להגפת שערים ולפתיחתם וכולן נקראים שוערים, ולכשנאמר שמשורר ששער חייב מיתה בין שער לבדו בין שער עם אחרים, ותלמוד ערכין שהבין שהמסייע משום גזירה לפי גירסת הברייתא שהיתה לו שלא הוזכר בה שכבר אתה מתחייב בנפשך והוקשה לו להתלמוד במה חולקים רבי יהושע ור' יוחנן והוכרח לישב מחלוקתם בדרך זה ולומר שמן התורה אין איסור אלא לבדו ולא מסייע וחכמים הוא שגזרו מסייע ובזה נחלקו רבי יהושע ורבי יוחנן, אבל לפי גירסת ספרי אפילו מסייע אסור מן התורה והסברה מסייעת:
@656 **והגם** שבכל כיוצא בזה אין אנו הולכים אלא אחר גירסת הברייתות המובאים בגמרא ואין אנו חוששין לנוסח הברייתות זולתם ומכל שכן לדבר שבא מבואר בגמרא כמו מה שלפנינו שאומר הש''ס בפירוש מסייע גזרה, כאן יש טעם נכון בדבר כי הרי לפניך אביי שאומר בפירוש נקטינן משורר ששער בשל חבירו במיתה זה יצדיק גירסת ספרי שאמר לו רבי יוחנן שאתה מתחייב בנפשך, כי לפי גירסא שהביא התלמוד דחויה היא דעת אביי כמו שדחה התלמוד, והגם שהש''ס הקשה לאביי ודחה דבריו, לא היה בפני אביי לומר שאיתותב ואילו היה עומד אביי ודאי שהיה מביא מההיא שהובאה בספרי:
@656 **ועוד** הצצתי מבין ריסי עיניו של אביי שעל אותה של ספרי נטע אהל אפדנו, ממה שהוכיח חיוב מיתה למשורר ששער מפסוק והחונים וגו' שהוא ממה שהוכיחו בברייתא של ספרי, שאמר שם אחר שהביא ההיא של רבי יהושע בן חנניה וכו' וזה לשונם רבי אומר אינו צריך שהרי כבר נאמר אל תכריתו וגו', מעבודה לחברתה מנין תלמוד לומר והחונים לפני המשכן וגו', ומה תלמוד לומר גם הם גם אתם לפי שבא קרח וערער על אהרן הזהיר הכתוב את כל הענין עד כאן, הנה דבברייתא של ספרי הובאה הדרשה שאמר אביי אלא שבברייתא לא נתפרש עיקר הלימוד מנין ובא אביי ופירוש שמסוף הכתוב הוא דורש דגמר אומר והזר הקרב יומת במאי מדבר הכתוב וכו' אלא בזר דאותה עבודה ע''כ, ומעתה בכיוצא בזה מצינו לומר שהאמוראים לא היו בקיאים בברייתות, ולזה התלמוד לא ידע גירסת הברייתא כמו שהובאה בספרי שאלו ידעה לא היה דוחה דברי אביי, גם לא היה אומר מסייע משום גזירה, ותמצא שכתבו התוספות שאפילו במשניות נוכל לומר שלא היו בקיאים, וזה כפי הטיית העיון לצד ההכרחות ואחר משקולת צדדי ההטייה והענין זה שאנו דנין עליו, ודע כי ברייתות הסדורות במכילתא ספרא וספרי הם מזוקקות ואינם כשאר התוספתות ולזה פסקה רמב''ם:
@656 **ונשאר** לנו לפרש לפי זה במה חולקים רבי יהושע ורבי יוחנן, ונראה כי רבי יהושע היה סובר שלא נאסר אלא מעבודה קלה לעבודה חמורה כמו שוער לשורר אבל משורר לשוער שהיא עבודה שעושה המשורר עצמו כשיגדל ויתקלקל קולו, וכמו שכתב רמב''ם שם באותו פרק עצמו, סבר רבי יהושע שיכול עשות, לזה סתר רבי יוחנן סברתו ואמר לו חזור בך שאני וכו' ואתה וכו' פירוש אין אדם יכול לעשות עבודת חברו אלא כל אחד למה שנתמנה, ואני נתמניתי להיות שוער ואתה להיות משורר ואין אדם עושה דבר שלא נתמנה עליו, ולזה נתחכם רמב''ם ז''ל ופסק פרט דין זה שם ואמר וזה לשונו שלא יסייע המשורר לשוער ולא השוער למשורר עד כאן, לשלול סברת רבי יהושע שהיה סובר כשבא לסייע רבי יוחנן:
@656 **שוב** שבתי לדקדק דברי רמב''ם כדי שלא יהיה הפך סברת הגמרא בדין המסייע, כי ב' מיני מסייע הם, א' מסייע בעבודה שיש בה שיעור לאותה עבודה לבד ממנו כגון שהיו שוערים הצריכים לאותה הדלת ובא לסייע הזה אינו חייב אלא מדרבנן, והב' מסייע להשלים הצריכין לאותה עבודה וזה חייב מן התורה, ולזה התלמוד מחמת ישוב סברת ר' יהושע לפי הגירסא שהיתה לפניו סבר שהיו שוערים המספיקים לאותה עבודה ולזה סבר רבי יהושע לסייע שאין איסור בדבר, אבל לפי גירסת ספרי שאמר לו אתה מתחייב בנפשך מוכרחים אנו לפרש שלא היה שיעור מספיק לשוערים להגיף הדלתות, ולזה דקדק רמב''ם בדבריו וזה לשונו הלוים וכו' מוזהרים שלא יעשה אחד מלאכת חברו שלא יסייע המשורר וכו' עד כאן, הנה ממה שדקדק לומר מלאכת חברו ולא אמר במלאכת חברו יגיד שמסייע זה נכנם בחלק מהעבודה המיוחדת לחברו, וגמר אומר שלא יסייע פירוש וגדר זה הוא שאני אוסר לך בו הסיוע ולזה לא אמר ושלא יסייע והבן:
@656 **נמצינו** אומרים כי המסייע בעבודה שאין בה צורכי עבודתה חייב מיתה כדעת רמב''ם וכברייתא דספרי ואין סתירה מהש''ם לזה, אלא שנשאר לדעת טעמו של רמב''ם ז''ל למה לא הוכיח חיוב מיתה ללוי משורר ששער מפסוק והחונים וגו' והזר הקרב יומת כמו שאמר בברייתא של ספרי וכדברי אביי כמו שכתבתי למעלה והלך לחזור אחר פסוק אחר שנראה מדבריו שהוא פסוק אל תכריתו משפחות הקהתי שבסוף פרשת במדבר, כי שם נאמרו ב' מאמרים שהביא הרמב''ם בפרט דין זה, הא' איש איש על עבודתו וגו', וב' ולא ימותו, והגם שכתב ועל משאו ובפסוק אל תכריתו נאמר ואל משאו, בודאי שטעות סופר הוא כי למה יניח מה שנאמר בפסוק שבו אמר ולא ימותו וילך לחפש אחר פסוק שבפרשת נשא כי שם נאמר ועל משאו ושם לא נאמר וימותו, אלא ודאי צריך להגיה בהרמב''ם ואל משאו, ויהי מה קשה למה נטה מדברי תנאים ואמוראים:
@656 **ונראה** כי הרמב''ם לקח דרשת תנא שדרש מפסוק גם הם גם אתם על זה הדרך גם הם לוים על עבודת הכהנים גם אתם כהנים על עבודת לוים, ומריבוי תיבת גם שלא היה צריך לומר אלא הם ואתם מזה דורש חיוב ללוי העובד עבודה שאינה שלו, ומה שכתב רמב''ם או שסייע לוי וכו' חייבין מיתה שנאמר ולא ימותו הוא מה שנאמר בפסוק ולא ימותו גם הם גם אתם, ודרשה זו מודה גם כן רבי הגם שאמר אינו צריך הרי גמר אומר מה תלמוד לומר גם הם וגו' לפי שערער וכו' חזר הכתוב והזהיר וכו' הרי שהצדיק דרשת תנא קמא, והגם שאביי דרש מפסוק והזר הקרב שהיא דרשת רבי, כיון שנתגלה לנו שאין רבי מכחיש בדרשת ולא ימותו כנזכר בחר הרמב''ם בראיית ולא ימותו שהיא יותר מפורשת מדרשת והזר וגו' שדרשתה באם אינו ענין שהכתוב במשה ואהרן נאמר דכתיב והחונים קדמה מזרחה משה וגו', והמשכיל יבין שאינה דרשה מפורשת, לזה בחר רמב''ם להביא בספרו מפסוק ולא ימותו גם הם וגו':
@656 **ומה** שהביא ראיה לאזהרת מעבודה לעבודה מפסוק איש איש על עבודתו ועל משאו מפני שזולת זה מנין לנו אזהרת מעבודה לעבודה שיבא עליה העונש ומנין יעלה מיחוש האיסור בדבר זה לפרש מאמר ולא ימותו על אם משורר ששער, לזה הביא פסוק איש איש על עבודתו ועל משאו. ואפשר כי רבינו (הרמב''ם) מפרש דברי רבי שכתבתי למעלה וזה לשונו אינו צריך שכבר נאמר אל תכריתו וגו' שחוזר על ענין הקרבת ר' יהושע לסייעו בהגפת שערים שהרי נאמר אל תכריתו וגו' ושם נאמר איש איש על עבודתו וגו', ומה שאמר לבסוף מעבודה לעבודה מנין אינו חוזר על האזהרה אלא על החיוב מנין שחייב מיתה, וכפי זה דברי הרמב''ם הם דברי רבי והוא ז''ל מביא בספרו הדרשה היותר מבוארת:
@656 **ולדרך** זה גם כן צריך להגיה בדברי הרמב''ם ואל משאו, ומה שפסק רמב''ם שכהן שעבד עבודת לוי אינו חייב מיתה, נראה כי דן לפי מה שקדם לנו שצריך הכתוב לכתוב העונש והאזהרה, וכאן בפסוק זה לא נאמרה אזהרה ומיתה אלא לבני לוי שכן כתוב לא יקרבו ולא ימותו, והגם שגמר אומר גם הם גם אתם והוסיף הכהנים בהאמור, אין הכרח שחוזר הכתוב לב' לאזהרה וחיוב מיתה ואין לנו לומר אלא על האזהרה בא כיון שלא נאמרה אזהרה לכהנים על עבודת הלוים אלא כאן, ואין זה היקש לומר אין היקש לחצאין ויכול להתפרש על זה הדרך גם הם על מה שהוזכר בסמוך גם אתם יש לכם אזהרה על הדבר, ועוד ממה שאמר רבי אינו צריך ולא נאמר גם הם גם אתם אלא בשביל שערער קרח מזה אתה למד שאין כאן מיתה לכהן העובד עבודת לוי, שאם לא כן הרי צריך וצריך כי מקראי שהביא רבי לא הביא בהם חיוב מיתה לכהן בעבודת לוים אלא אזהרה כמובן שם מהברייתא, אלא ודאי שלא בא מאמר גם אתם אלא לאזהרה, ולזה גם כן לא אמר תנא דספרי אלא כהנים על עבודת לוים מנין ולא אמר כהנים ענושים ומוזהרים על עבודת לוים מנין כמו שהתחיל לומר בלוים:
@656 **ומה** שאמרו בברייתא שהובאה בערכין אתם בשלהם והם בשלכם במיתה ולא הביא הש''ס ברייתא המנגדת לה שזה יגיד שברייתא זו היתה מוסכמת לבעלי הגמרא. אומר אני כי כשנעמוד על עומק הסוגיא ממנה נכריח ללכת בדרכו של רמב''ם, והוא כי שם מסיים באותה ברייתא וזה לשונם הם בשלהם אינם במיתה אלא באזהרה ופרש''י הם בשלהם לוי משורר שהגיף דלתות עד כאן, וקשה לי למה שמקשה הש''ס בסמוך לדברי אביי שאמר משורר ששער במיתה וזה לשונם מיתיבי משורר ששער ושוער ששרר אינם במיתה אלא באזהרה וכו' עד כאן. קשה למה מחזר התלמוד לברייתא אחרת להקשות לדברי אביי ולא הקשה מברייתא שלפניו ממש שאמרה הם בשלהם אינם במיתה. ועוד קשה פרט זה של לוי מעבודה לעבודה היכן הוזכר שיאמר עליו אינ' במיתה אלא באזהרה, הלא תנא לא בא אלא לפרש מאמר גם הם גם אתם, וממה נפשך אם סובר התנא לדרוש מפסוק זה גם לוי מעבודה לעבודה שגם זה נכלל במאמר גם הם גם אתם אם כן המשפט שנעשה בכהן שעבד עבודת לוי נעשה בלוי שעבד עבודת לוי אחר כיון ששניהם כללם הבורא במאמר זה:
@656 **ואם** תאמר שאין להכריח מפסוק זה אלא אזהרה כמו כן גם כן אין לחייב הכהן בעבודה של לוי, אלא מוכרח אתה לומר שאין תנא דורש איסור לוי בעבודת חברו מפסוק גם הם גם אתם אם כן תנא אהיכא קאי שאומר הם בשלהם, אלא ודאי שזה יכריח לומר כי תיבת הם טעות הוא וגרסינן במקומה אתם, וזה פירושו הם בשלכם במיתה ואתם בשלהם אינם במיתה אלא באזהרה גם חסר מהברייתא הם בשלכם, כי להיות שהמדפיס ראה ב' תיבות כפולות הם בשלכם והם בשלכם סבר שהוא כפל לזה השמיט אחת מהם, וזה הוא נוסח הברייתא על נכון גם הם גם אתם אתם בשלהם והם בשלכם הם בשלכם במיתה אתם בשלהם אינם במיתה אלא באזהרה, ולזה לא מצא התלמוד להקשות לאביי מברייתא זו שאין בה זכרון ב' עבודות לוים והקשה מברייתא אחרת, גם בזה יהיה סיפא דברייתא בדרשת הכתוב גם הם גם אתם שהביא התנא, ואמר כי הלוים בשל כהנים במיתה אבל כהנים בשל לוים אינם אלא באזהרה והטעם כמו שכתבתי בפירוש דברי רמב''ם, ומעתה עלה פסק רמב''ם וספרי וברייתא (דכריתות) [דערכין] בקנה אחד:
@661 **ואגי הנה נתתי וגו'**. טעם אומרו **ואני**, נתכוין לומר כי בעד מה שהטלתי עליכם לשאת עון המקדש וגו' גם אני כבר הקדמתי לתת לכם בעד זה משמרת תרומתי לכל קדשי בני ישראל:
@673 **בארצם לא תנחל וגו'**. בספרי אמרו שאסר עליו חלק הארץ וחלק הביזה, ולזה כפל לומר **לא תנחל וחלק לא** וגו', וכוונת הכתוב היא שהגם שירצו ישראל לחלק לו חלק עמהם לא יאמר שלא נתכוון ה' אלא לפטור ישראל מחלק אהרן אבל אם ירצו הרי אלו משובחים על דרך אומרם ז''ל (שביעית פ''י מ''ט) המחזיר חוב בשביעית רוח חכמים נוחה הימנו, לזה אמר **לא תנחל**, ושומע אני דוקא נחלת הארץ הוא שישנה בלאו אבל חלק הביזה אינו באיסור תלמוד לומר **וחלק** וגו'. ודקדק לומר **בתוכם** על דרך אומרו (משלי א') גורלך תפיל בתוכנו פירש ליטול חלק כאחד מהם הוא שאסר עליו אבל אם רצו לשלוח לו דורונות הרי זה מקבל מהם:
@673 **אני חלקך וגו' בתוך בני ישראל**. אומרו **אני**, פירוש מה שהוא מיוחד לי אני יהיה חלקך, וחזר ופירש מה הוא הדבר ואמר **בתוך** וגו' שאין לך דבר שעושים ישראל שאין להקב''ה חלק עמהם ונוטלו הכהן, בתבואות הארץ, בפירות האילן, בלחם, בבשר, ביין, בשמן, ושאר הכ''ד מתנות:
@677 **כי את מעשר וגו' על כן וגו'**. ולמעלה הוא אומר **ולבני לוי נתתי כל מעשר בישראל** וגו' **חלף עבודתם**, נראה כי מתנת מעשר זה שנתן ה' ללוים יש בו ב' דברים, הא' חלק הנוגע להם בארץ, והב' שאינם טורחים בארץ לעשות ז' מלאכות הצריכות עד שיהיו חטים ממורחים, לזה אמר הכתוב ב' דברים חלף חלקם בארץ וחלף עבודתם ישראל עומדים ועושים מלאכתם כדי שיהיו מופנים לעבודת אהל מועד, והנה בלוים לא אמר אני חלקך וגו' שאין הלוים זוכים בחלק ה', ולזה גם הם נותנים חלק ה' תרומה מעשר מן המעשר. והם ומעשרם אינו אלא כשכירות הדיוטות לשרת הקדוש שהוא הכהן ואהל מועד:
@684 **כי שכר וגו' חלף וגו'**. חזר לומר הדברים עצמן שאמר למעלה, לפי שאמר **ואכלתם אותו בכל מקום** שהוא חולין גמורים לזה נתן הטעם כי אין במעשר זה שום קדושה כתרומה או כדומה לה אלא ממון חול שאמר ה' לישראל לפרוע לכם שכר עבודתכם, ומעתה מה קדושה יש בו. ורז''ל (ספרי) אמרו שבא הכתוב לומר שאם עבד יטול ואם לא עבד לא יטול מכאן אמרו בן לוי שקבל עליו כל העבודות חוץ מאחד אין לו חלק בלויה, ואלו ואלו דברי אלהים חיים:
@684 **חסלת פרשת קרח**
@687 **זאת חקת התורה**. צריך לדעת למה כינה למצוה זו שם כללות התורה, שהיה לו לומר זאת חקה וגו' או זאת חקת הטומאה או חקת הטהרה כדרך אומרו (שמות יב) זאת חקת הפסח, ואין לומר שנתכוון להצריך טהרת אפר פרה לעסוק בתורה, כי לא כן מצינו לרז''ל שאמרו (ברכות כב.) שאדרבא אין דברי תורה מקבלין טומאה, ולכל סברות רז''ל (שם) אפילו להמחמירים בבעלי קריין מטעם שצריך באימה וביראה וכו' מודים בטמאי מת שמותרים בעסק התורה:
@687 **ויתבאר** הענין על פי מה שאמרו בפרק בתרא דנזיר (סא:) ופסקו רמב''ם בפרק א' מהלכות טומאת מת שאין הכותי נעשה טמא מת, וזה לשונו שאם נגע במת או נשאו או האהיל עליו הרי הוא כמו שלא נגע הא למה זה דומה לבהמה שנגעה וכו' עד כאן. והנה ההבדל שבו הורמו עם בני ישראל משאר הגוים הוא באמצעות קבלת התורה שזולת זה הנה ככל הגוים בית ישראל, ומעתה טעמנו צוף דבש אמרי אל במה שאמר **זאת חקת התורה** פירוש חקה זו של הטומאה ותנאי טהרתה תסובב מהתורה, כי על ידי שקבלו התורה נעשו עם בני ישראל דבר שהרוחנים השפלים תאבים להדבק בהם להיותם חטיבה של קדושה עליונה בחייהם גם במותם, בחייהם שבנוגע במת או יאהילו עליו וכדומה תדבק בהם הטומאה שבמת ולא תחפוץ להפרד אם לא בכח גדול אשר חקק ה' במצוה האמורה בענין של פרה אדומה, ובמותם גם כן תתרבה הטומאה כאומרם ז''ל (ב''מ קיד:) בפסוק אדם כי ימות וגו' ישראל מטמאים באהל ואין אומות מטמאין באהל:
@687 **וכבר** המשלתי במקום אחר ענין זה לב' כלים שהיו אצל בעל הבית אחת מלאה דבש ואחת מלאה זבל ופינה אותם והוציאם לחוץ מהחדר אותה שהיתה מלאה דבש מתקבצים לה כל הזבובים והרמשים ואותה שהיתה מלאה זבל הגם שיכנסו לה קצת מהרמשים לא ישוה לשל דבש, כמו כן אדם מישראל שמת להיותו מלא קדושה המתוקה והעריבה בצאת הנפש ונתרוקן הגוף יתקבצו הקליפות לאין קץ שהם כוחות הטומאה התאבים תמיד להדבק בקדושה ליהנות מהערב, ולזה יטמא באהל ואפילו אלף בתים מקורים ואחת פתוחה לחברתה הטומאה תמלא כל החלל המקורה, מה שאין כן אשר לא מזרע ישראל להיותו מושלל מהקדושה אין כל כך התקבצות הטומאה אלא חלק הממית הנדבק בגוף, ואשר יסובב הכל היא התורה:
@687 **ובזה** מצאתי נחת רוח למה כשצוה ה' פסח במצרים הקפיד ה' על ב' דברים, הא' דין ערל וצוה למול כאומרם ז''ל (שמו''ר פי''ז) בפסוק ואעבור עליך וגו' דם פסח ודם מילה, והב' על דין בן נכר שאמרו ז''ל (שם פט''ז) בפסוק משכו וקחו לכם וגו' משכו ידיכם מעבודה זרה שבזה יצאו מכלל בן נכר, ועל דין ג' שהוא הטומאה לא מצינו שהקפיד ה', והגם שמצינו (פסחים עז.) שהפסח בא בטומאה בנטמא ציבור, עם כל זה היה ה' יכול לצוות קודם שיזהרו מטומאת מת ולעשות משה אפר פרה ואין מעצור לה' לעשות רצונו יתברך, והגם שיש לומר בזה דחיות אף על פי כן לפי מה שכתבנו יש טעם נכון לשבח, כי ישראל לא היו טמאי מת הגם שנגעו והאהילו על המת כי עדיין לא קבלו התורה ודנו בהם אז דין גר שנתגייר ביום י''ד ששוחטין עליו ואין חוששין לטומאה שנטמא קודם שנתגייר, ותמצא שאמרו בפסחים (צב.) וכתבו הרמב''ם בפרק ו' מהלכות פסח וזה לשונו גר שנתגייר ביום י''ד ומל וטבל אין שוחטין עליו את הפסח גזירה דלשנה הבאה יהיה טמא מת ויטבול לערב ויאמר אשתקד מי לא טבלתי וכו' עד כאן לשונו, ממה שנתן הטעם משום גזירה דלשנה הבאה מזה אתה למד כי זולת גזירה זו אין חוששין לטומאת מת, וכמו כן ישראל כשעשו פסח מצרים אין בהם דין טומאת מת, והוא מאמר ה' זאת חקת התורה:
@687 **ובדרך** רמז ירצה באומרו **חקת התורה** שאם יקיימו מצוה זו הגם היותה חוקה בלא טעם מעלה עליהם הכתוב כאלו קיימו התורה אשר צוה ה' לאמר, כי קיום המצוה בלא טעם יגיד הצדקת האמונה והסכמת הנפש לקיים כל מצות הבורא וזה לך האות, ואולי כי לטעם זה רצה ה' שתתמסר להם המצוה בדרך חקה:
@687 **אשר צוה ה' לאמר**. צריך לדעת למה הוצרך לומר מאמר זה והלא רואני כי ה' הוא המצוה לאמר שכן אמר וידבר ה' אל משה לאמר דבר אל בני ישראל, עוד אומרו לשון נסתר **אשר צוה** ופי ה' הוא המדבר והיה לו לומר אשר אנכי מצוך לאמר, עוד למה לא הספיק במה שאמר לאמר בפסוק ראשון וחזר לומר פעם ב' **לאמר**, עוד צריך לדעת למה לא הקדים מאמר דבר אל בני ישראל קודם מאמר זאת חקת התורה על זה הדרך דבר וגו' זאת חקת התורה. אכן לצד שכל מצות התורה הם שכליות ושמעיות, שכליות שהשכל מחייבם כגון כבוד אב ואם גניבה גזילה אונאה רציחה וכדומה, שמעיות שבת כי בו שבת הבורא, יום טוב על הנם שנעשה לנו בהם, עבודה זרה שלא לעבוד זולת אלהינו כי הוא המוציא אותנו וגו' וכדומה לזה, וזה הוא טעם הנגלה, ואין לך מצוה ומצוה שאין בה עוד סודות נעלמים הנגלים למשה ולאדם ראוי המשיג לקנות קנין התורה במ''ח דברים השנויים במשנת חסידים (אבות פ''ו) שאז מגלין לו רזי התורה שגילה ה' למשה בסיני, ומשה גם כן גילה לישראל בני דורו סודות הנסתרים וטעמי המצות ויסוד כל דבר:
@687 **ובמה** שלפנינו צוה ה' אליו שיסתום הדברים ויאמר להם הדבר בחוקה בלא טעם, והוא מה שהעיר אותנו באומרו **וידבר ה' אל משה לאמר** לישראל פירוש ומה הוא המאמר שצוה לו לומר להם, **זאת חקת התורה** פירוש מצוה זו היא חקת התורה כן צוה ה' לאמר לכם, וכאילו אמר הכתוב אשר צוה ה' לאמר לכם הוא זאת חקת התורה, ומתוך הדברים אתה למד שנאמר למשה דברים מוטעמים במצוה זו אלא שמה שצוה עליו לאמר הוא חוקה, ובזה לא יתבעוהו ישראל לומר להם טעם הדבר כיון שה' צוה עליו לומר הדבר בחוקה:
@687 **ובזה** נתישבו הדקדוקים, גם נתישב למה לא הקדים מאמר דבר וגו' למאמר זאת חקת וגו' כי מאמר זאת חקת התורה היא מצות ה' על מצוה שיאמר לישראל שה' צוה לו שיאמר להם מצוה זו בחוקה, ומאמר דבר בא על עיקר המצוה מצות ה' לישראל, ולצד שיאמרו ישראל הרי העושה מצוה בלא ידיעת טעמה וסודה נחשבת המצוה כגוף בלא נשמה, לזה גמר אומר **דבר אל בני ישראל ויקחו אליך פרה** וגו' פירוש יקחו למה שאתה יודע ומכוין בדבר להיותך יודע סוד הענין ופלאיו ובזה תהיה המצוה נעשית שלימה במעשה ובמחשבה הצריכה, וכפי זה ידויק על נכון אומרו **ויקחו** בתוספת וא''ו בתחילת הציווי להם, שנתכוון לומר שמלבד הלקיחה עצמה שיקחו הפרה עוד יוסיפו שיכוונו בלקיחתה למה שאליך כאמור:
@687 **ואם** תאמר תינח אותה פרה של אותו דור פרה שיעשו בכל דור ודור מה תהא עליה, אפשר שלא מכולן העלים ה' סודה אלא מכללות ישראל אבל למיוחדים שהם אהרן וכיוצא בו נמסרו סודותיה והם ימסרו למיוחדים הבאים אחריהם, או אפשר שבכל דור ודור יכוונו למה שידע משה, ומצאתי שאמרו במדרש (רבה כאן) וזה לשונם ויקחו אליך ללמד שכל הפרות שנעשו יהיו נקראים על משה, וצריך לדעת למה עשה ה' שינוי במצוה זו מכל המצות שתקרא על שמו, ולדברינו יש טעם נכון בדבר כמו שפירשתי:
@687 **או** יאמר על פי דבריהם ז''ל (שם) שאמרו שאומות העולם מונים את ישראל מה מצוה היא זו וכו', לזה בא מאמר הכתוב כאן ואמר **זאת חקת התורה** אשר צוה ה' לאמר פירוש שיאמרו ישראל לאומות כשהן מקנטרים אותם ואומרים להם מה מצוה היא זאת וכו' יאמרו להם חקה חקק ה' עלינו לעשות ואין אנו מהרהרין אחריו, ולפי זה אפשר שהורשה משה לומר להם טעם המצוה וסודה אלא שלא יאמרו הטעם לאומות כשידחקו אותם בדברי קנטור מה מצוה היא זאת ומה טעם יש בה:
@687 **פרה אדומה וגו'**. רואה אני כי כל סימניה מוכיחים על הדינים, אדומה כי הוא זה סימן תגבורת הדינים, תמימה באין שער שחור, וכן אמרו ז''ל (פרה פ''ב) ב' שערות שחורות פוסלות אותה, ולא שערותיה לבד אלא אפילו קרניה וטלפיה צריכים להיות אדומים, אבל שחורות ואין צריך לומר לבנות פוסלות, אשר לא עלה עליה עול כי העול ימתק הדינים בסוד מאמרם (ברכות ה.) יסורין ממרקין כל עונותיו של אדם שהם בחינת הדינים, גם שריפתה באש הוא בחינת הדינים, ובהתקבצות הדינים באפר יעשו הברחה לטומאה הדבוקה באדם מהמת שגם היא אינה אלא רצועה רעה מצד יסורי המשפט:
@687 **וראיתי** בספרי זוטא ופסקו רמב''ם בפרק א' מהלכות פרה אדומה אין לוקחין עגלה ומגדלין אותה שנאמר ויקחו וגו' פרה ולא עגלה עד כאן, ולפי מה שאמרנו שכל מעשיה הם בחינת המשפט יש טעם בדבר, כי שם פרה יגיד מספר הידוע למספר בחינת הדינים כידוע ליודעי חן, לזה צוה ה' שיקנו אותה כשיש בבחינת מספרה מספר אשר תכוון אליו, אבל אם יקנו עגלה קונים דבר שאין בו המספר אשר אנו צריכין לו, והגם שמגדלין אותה עד שנקראת פרה, אף על פי כן יקפיד ה' על שעת הקנין כדי שיהיו קונים דבר שהכוונה בו שהם רפ''ה דינים:
@688 **ונתתם אותה**. אמר **אותה** לפי מה שאמרו רז''ל (פרה פ''ד) שמפי השמועה למדו ששאר פרות נעשות בין בכהן גדול בין בכהן הדיוט דייק לומר אותה אל אלעזר אבל מכאן ולהלאה אין חיוב בסגן:
@690 **ושרף את הפרה לעיניו את עורה**. הפסיק במאמר לעיניו בין זכרון הפרה לזכרון פרטיה שהם עורה וגו', יתבאר על דרך מה שאמרו במסכת פרה (פ''ד), וכתבו רמב''ם בפרק ד' מהלכות פרה אדומה שמצות שריפתה שלימה ואם הפשיטה ונתחה ושרף כלה כשרה עד כאן, לזה הבדיל הכתוב במעשה המובחר ואמר **ושרף את הפרה** פירוש כולה יחד, ואפילו עבר והפשיטה וכו' ועשה עורה לבד ובשרה לבד ופרשה לבד גם כן לא הפסיד, והוא מאמר את עורה ואת וגו':
@690 **על פרשה ישרוף**. חזר לומר **ישרוף** פעם ב' ולא הספיק במה שאמר בתחלה ושרף, לפי מה שפירשתי כי הכתוב ידבר בב' סוגים הא' שריפת הפרה שלימה, והב' אחר שהופשטה ונתנתחה לזה אמר **ישרוף** כנגד חלוקה שניה.
@690 עוד יתבאר על פי מה שאמרו בתוספתא דפרה (פ''ב) וכתבו רמב''ם בפרק ד' מהלכות פרה אדומה וזה לשונו פקע מעורה וכו' אפילו משערה כזית יחזיר ואם לא החזיר פסולה עד כאן, והוא מאמר **ישרוף** פעם ב' לומר שהגם שפקע יחזיר וישרוף לעיכובא:
@699 **זאת התורה אדם כי ימות**. אומרו **זאת התורה**, יתבאר גם כן על דרך שפירשתי בפסוק זאת חקת התורה, והוא לצד שדקדק לומר **אדם כי ימות** וגו' ודרשו רז''ל (ב''מ קיד) אתם קרויים אדם ישראל מטמאין באהל ואין אומות העולם וכו', לזה הקדים לתת הטעם שסובב הדבר ואמר **זאת התורה** שמסיבתה הוא שאותו שנקרא אדם מטמא באהל אבל אומות העולם שאין להם תורה וכו', ועיין מה שכתבתי בפסוק זאת חקת התורה:
@699 **כל הבא אל וגו' וכל אשר באהל**. קשה אם הבא טמא מי גרע ממנו אשר באהל, ויתבאר על פי מה שאמרו בפסיקתא זוטרתי וזה לשונם כל הבא אל האהל שבא מקצתו עד כאן, וכפי זה אם לא היה אומר הכתוב אלא כל הבא הייתי אומר הבא כולו הבא מקצתו מנין וממה שאמר כל אשר באהל הרי כולו אמור מה אני מקיים כל הבא וגו' זה הבא מקצתו. עוד שם בפסיקתא וזה לשונם דבר אחר כל הבא וגו' לעשות קרקעו של בית כמוהו עד התהום עד כאן. נראה שהוכרחו לדרשא זו כי לסברא הראשונה היה לו לומר הכתוב כל אשר באהל וכל הבא אל האהל ויהיה הכתוב מתפרש בדרך לא זו אף זו, אבל ממה שהקדים כל הבא זה יגיד שמאמר **כל אשר** וגו' הוא דין חדש:
@699 **אלא** שבספרי ראיתי ב' הדרכים דרך הראשון תנא קמא ודרך ב' רב אחא בר יאשיה, וגמר אומר תנא קמא שטעם שהוצרך הכתוב לומר כל אשר באהל הגם שאמר כל הבא שהוא בא מקצתו, משום שאין עונשין מן הדין, וקשה לי הלא מה שאנו אומרים אין עונשין מן הדין הוא על עונש מיתה של בית דין של מטה וכאן לו יהיה שנטמא ונכנס למשכן טמא מיתתו בידי שמים, ועוד לבד מזה כשנשכיל על דבר נראה כי מה שלפנינו אינו נקרא עונשין מן הדין כי בכלל הבא כולו יש מקצתו והרי מתחייב הוא על מקצתו כי כל חלק וחלק שבו יקרא מקצתו ואין אנו עונשין אותו מן הדין אלא מן הכתוב, ואולי שסובר תנא זה שכל כיוצא בזה נקרא עונשין מן הדין:
@708 **ויבאו בני ישראל וגו'**. צריך לדעת למה הוצרך לומר **כל העדה** ולא הספיק במאמר **בני ישראל** שמן הסתם הם כל העדה, אכן לפי מה שקדם לנו מדבריהם (מד''ר סו''פ בלק) כי כשישראל הם במדרגת ישרים וצדיקים נקראים בני ישראל וכשאינם בגדר הנאות נקראים עם כאומרו (י''ד י''א) עד אנה ינאצוני העם הזה והרבה כיוצא בזה, והרבה פעמים יקראם הכתוב עם בני ישראל הגם שימצאון בהם הרבה אשר אינם ראוים לגדר זה ויכוין הכתוב אל הרוב הכשרים, וכאן הודיע הכתוב כי כל העדה ישנם בגדר זה שיקראו בני ישראל, והוא מאמר **ויבואו בני ישראל כל העדה** פירוש כולן נקראים בשם ישראל בגדר ישרים וצדיקים, וזה מכוון לדברי רז''ל שאמרו וזה לשונם כל העדה עדה השלימה:
@708 **והם** ז''ל נראה שדרשו תיבת כל העדה עצמה שתגיד השלימות והקיום, וע' פנים לתורה. והכוונה בהודעה זו היא לג' סיבות. הא' לפי שהוא אומר בסמוך מעשה מי מריבה ואמרו ז''ל (דב''ר פ' ואתחנן) שנענש משה על ידם שאמר להם שמעו נא המורים לזה הקדים להודיעך כי כל העדה היו צדיקים וזו היתה סבה שנענש משה שקראם מורים. ב' להגדיל מעלת מרים עליה השלום שהגם שכל העדה היו צדיקים לא עמד זכותם להעמיד להם באר המים שהיה בזכות מרים (תענית ט.). ג' על פי דבריהם ז''ל (ילקוט) שאמרו שישראל לא הלכו לגמול חסד עם מרים וכשנקהלו על משה ועל אהרן חשב אהרן שבאו לגמול חסד עם מרים והם לא באו אלא לריב עמם כאמור בדבריהם ז''ל, ומעתה יש מקום לחשוד בישראל שלא היו אז באותו מצב כשרים וזה לך האות שלא גמלו חסד עם הנביאה, לזה קדם והודיעך כי כל העדה צדיקים אשר בשם ישראל יתכנו, וטעם שלא גמלו חסד אמר הכתוב בסמוך ותמת שם מרים ותקבר שם, ואמרו בגמרא (מוע''ק כח.) וזה לשונם ותמת וגו' סמוך למיתה קבורה עד כאן, ולטעם זה לא הרגישו לבא לגמול חסד, ובמשך זמן מועט עד שידעו קפץ עליהם רוגזו של צמא, והוא מה שאמר הכתוב סמוך למאמר ותקבר שם ולא היה מים וגו':
@708 **וישב העם בקדש**. בא להודיענו שנתעכבו שם ימים רבים כאומרו (דברים א) ותשבו בקדש ימים רבים פירוש **וישב** לשון עכבה:
@708 **ותמת שם וגו'**. צריך לדעת טעם אומרו **שם**, ורז''ל דרשו (מוע''ק שם) שלא עכבוה, ודרשה זו נשמעת מאומרו **ותקבר שם**, ונראה כי לצד שהזכיר מיתה חש על כבוד הצדקת שהרי אמרו (ברכות יח) צדיקים במיתתם קרויים חיים, לזה דקדק לומר **שם** פירוש שם הוא שמתה ולא נשארה ביניהם אלא במקום אחר ישנה בין הצדיקים, כי הצדיקים דומים לפני הקב''ה למרגליות המונחים בארגז כשהוא חפץ באחת מהם הוא מוציאה מהארגז וקובעה בתכשיט אחד מתכשיטיו, ורז''ל דרשו (מוע''ק שם) ותמת שם לגזירה שוה לומר שגם היא מתה בנשיקה, וע' פנים לתורה:
@710 **וירב העם וגו' ולו גוענו**. פירוש נתרעמו עליו שהתפלל עליהם שלא ימותו בדבר:
@711 **ולמה הבאתם וגו'**. תרעומת ב' למה הביאום דרך מדבר שהוא מקום סכנת מיתת צמא שהיה להם להעלותם שלא על דרך המדבר, והכונה בזה כיון שאין כח ביד משה לתת להם מים במדבר על מי סמך להביאם דרך שם, ואומרם **ולמה העליתונו** וגו' פירוש ואם תשיבו אותנו כי אין דרך מובטח להעביר אתכם בו אלא דרך מדבר או הכרח היה הדבר שתעברו דרך מדבר, לזה נתרעמו ואמרו אם כן לא היה לכם להעלותינו ממצרים כיון שהוא מוכרח להביא אותנו אל המקום הרע הזה שיש בו סכנה שאינו מקום זרע וגו' כאומרם ז''ל (חולין פח:) מדבר אינו מעלה צמחים. ואמרו **אל המקום** בה''א הידיעה לומר שמדות רעות שבמדבר ידועות הם שאינו מקום וגו', **ומים אין לשתות** פירוש אפילו לשתות שהוא דבר ההכרחי ואתם אינכם יכולין להמציא לנו מים, ולא היה מענה בפי משה ועמד בתפלה לפני ה' הוא ואהרן דכתיב ויפלו על פניהם:
@715 **קח את המטה וגו' ויקדש בם**. פרשה זו רבו עליה כל מפרשי התורה, ותרתי בה לאור באור החיים, וקודם שנעמוד על פשטן של כתובים נקדים להבין מה היתה שגגתו של משה בענין זה אשר היה סיבה לגזירתו, וראיתי שנאמרו י' דרכים בענין בדברי מפרשי התורה והן הנה בקצרה:
@715 א' רש''י ז''ל פי' ששגגת משה היתה כי ה' אמר אליהם דברו והוא הכה:
@715 ב' רבי אברהם אבן עזרא פירש שהשגגה היתה שגרם שלא נתנה הסלע מימיה עד הכאה ב' במה שאבד הכונה בפעם א' לצד מריבת העדה:
@715 ג' הביאו הנזכר כי הקפדת ה' היתה על שהכה ב' פעמים שאם היה מכה פעם אחת לא היתה הקפדה כי הדיבור לסלע היא ההכאה:
@715 ד' הביאו הנזכר שהקפדת ה' היתה על שלא אמרו שירה על המים כמו עלי באר:
@715 ה' הביאו הנזכר שהקפדת ה' היתה על שאמר לבני אל חי המורים ואין ראוי לאיש חסיד לתעב ולזלזל בבני אברהם יצחק ויעקב וגו':
@715 ו' הר''מ (דמב''ם בח' פרקים) פירש כי הקפיד ה' עליו על אשר נתרגז על העדה ומסיבה זו חשבו כי גם ה' בכעס עמהם אשר לא כן היה:
@715 ז' רבינו חננאל והסכים אליו רמב''ן שהקפדת ה' היתה על אשר אמר נוציא לכם מים ולא אמר יוציא לכם שמזה טעו ישראל וחשבו כי הם בחכמתם עושים את המעשה כי לא היה להם רמז כי ה' הוא העושה הנס ולזה הקפיד ה' ואמר לא האמנתם בי להקדישני וגו':
@715 ח' ר''מ הכהן פירש שהקפדת ה' היתה על מאמר משה המן הסלע הזה וגו', וכוונת משה היתה לצד יכולתו אם לא בכח הנאדר וחשבו האנשים שלא יוכל ה' להוציא מים מן הסלע, וזו היא שגגת משה, והביא ראיה לפירושו ממה שאמר הכתוב (תהלים קו) כי המרו את רוחו ויבטא בשפתיו וגו':
@715 ט' הר''י אלבו בספר העיקרים ישב שהקפדת ה' היתה על שלא נתעוררו משה ואהרן מעצמן להוציא להם מים והיו מרעידים שזה יורה מיעוט הבטחון וגו':
@715 י' בעל מעשה ה' שפירש כי היה ויכוח בין משה ובין ישראל שישראל היו רוצים להוציא להם מים ממקום אחר שחפרו אותו הם ולא רצה משה לדבר לאותו סלע שחפרו הם ונתכעס משה וזרק המטה בידו לא להכות אלא בכעס ובדרך מקרה הכה המטה בסלע וכו' עיין שם דבריו:
@715 **הנה** כל העשרה דרכים אינם מוציאים אותנו ידי חובת האמת, וצא ולמד מה שטען רמב''ן על ג' מהם ודחאם, ומה שטען ראב''ע על ג' אחרים ודחאם, ואני טוען על השאר והם, דרך א' של רבינו חננאל שבחר לו רמב''ן שההקפדה היתה על שכינה לעצמו המעשה ואמר נוציא וגו' הלא ידוע היה משה לשלוחו של מקום וכל מעשיו הנם בכח האל, ולו יהיה כי כחו של משה הוא הלא מגדולת העבד גדולת האדון נודעת בפרק מרובה, ועוד הלא תמצא בפרשת בא אל פרעה אמר הכתוב (שמות יב) ויקרא משה לכל ישראל ויאמר אליהם משכו וקחו וגו' ולא אמר בשם ה', כי ודאי הדבר ידוע הוא כי הוא שלוחו של מקום, ועוד במה שלפנינו מוכרח היה לומר נוציא לכם להיות כי הם המוציאים בדיבורם או בהכאתם שה' נתן ההוצאה בידם, ודרכו של הר''י אלבו אין דעתי הולמו כי אחר שראה משה שה' מנע מהם מים ונסתלק הבאר איך יגש להוציא מים עד אשר ידע דעת הבורא ברוך הוא, ומי יאמר כי ה' חפץ ליסרם, לזה הכרח היה הדבר להשתטח לפני ה' וה' יעשה הטוב בעיניו, ודרכו של בעל מעשה ה' עלה כולו קמשונים ואין בו לא מלח ולא תבלין וקלני מזרועי לטרוח לדחות הדברים הדחויים במחילה מכבודו:
@715 **ותרתי** לי מנוחה בדברי הראשונים ז''ל ואמצא במדרש (ילקוט) וזה לשונם יען לא האמנתם וגו' ד' חטאות כתובים כאן, לא האמנתם, לא קדשתם, מעלתם, מריתם, לא האמנתם שלא אמרתי לכם להכות והכיתם, לא קדשתם להביא מים מכל סלע שרוצים, מעלתם שאמרתם המן הסלע הזה, מריתם שאמרתי לכם ודברתם אל הסלע שנה עליו פרק אחד ועברתם על דברי עד כאן לשונם, ועל פי מדרש זה נעמוד על פירוש אמרי קדוש במאמר **קח את המטה ודברתם אל הסלע** וגו' והוצאת להם מים מן הסלע, ויש להעיר א' למה יצו ה' לקחת המטה כיון שהוצאת מים הוא בדיבור לבד, ב' למה חזר לומר **והוצאת להם מים** אחר שאמר ונתן מימיו, ג' הוצרך לומר פעם ב' **מן הסלע** ולא הספיק בזכרונה בסמוך, הנה לפי המדרש נתגלה לנו כוונת הכתוב למפרע על נכון, כי מה שאמר **קח את המטה** הוא להורמנותא דמלכא והוראת היות בידו כח עליון ולא להכאה, ולא חש לטעות שהוא להכאה ממה שאמר בפירוש ודברתם ומשה לא עשה כן והכה והוא חטא הראשון שאמר בעל המדרש, ומאמר **ודברתם אל הסלע** הוא שישנה עליו פרק אחד והוא לא עשה כן והוא חטא הב', ומאמר **והוצאת להם מים מן הסלע** ונתכוון במאמר זה לומר אפילו מסלע אחר כשהם חפצים להוציא להם ממנה הוציא להם מאיזו סלע שירצו, ולזה גם כן הזכיר פעם ב' הסלע ולא סמך לזכרון הראשונה כי לא זאת הוא מה שהזכיר, והוא לא עשה כן והראיה ממה שאמר להם שמעו נא המורים זה יגיד שהיו מורים איזה דבר, וממה שגמר אומר **המן הסלע** וגו' יגיד כי היו מורים בסלע לומר מסלע זו והוא אומר המן הסלע הזה וגו' פירוש שסלע זה אינו ראוי להוציא מים, נמצאו ביד משה ב' שגגות אחרים, א' שה' אמר הוציא להם מסלע שיחפצו והוא לא עשה כן, ב' שעשה להם החלט האפשריות כאומרו המן הסלע וגו', והם הב' חטאות שמנה בעל המדרש שני ושלישי:
@715 **וחל** עלינו חובת גברא לתת טעם לאיש האלהים על ארבעת השגגות אשר אינו ראוי לאחת מהנה:
@715 **ונראה** כי משה עמד על מאמר ה' בחכמה ולצד עוצם יראתו בה' שגג, וזה יצא ראשונה, מה שאמר לו ה' קח את המטה הבין בו ב' דרכים, א' להכאה וא' להורמנא ולכח עליון בידו שבאמצעות המטה שבו חקוק שם המפורש יעשה פלא, והאמת שיותר צודק פשטן של דברים על להכות בו כי לטעם הב' הוא צד רחוק קצת, והגם שמצינו שאמר לו ה' (שמות ד) ואת המטה הזה תקח בידך אשר וגו', שם היה עושה פעולות במטה, וזכרון ההכאה בא במאמר ה' בסמוך והוצאת להם מים מן הסלע, שלא היה צריך לומר אחר שאמר ודברתם וגו' ונתן מימיו וכמו שדייקנו למעלה, והבין משה כי כוונת ה' היא לומר לו שלא דבור לבד יספיק אלא כח המעשה שיעשה שבו יוציא מים, ובזה גילה סופו על תחילתו כי לקיחת המטה היא לעשות בה מעשה להוציא המים מן הסלע, והגם שעלה על דעת משה פירוש שנתכוין לו ה' כמו שאמרנו שבא לומר שיוציא מסלע אשר יחפצו, הטה לפרש פירוש זה לצד שקדם לו מאמר לקיחת המטה לא נראה בעיניו שתהיה לקיחה לבד מבלי עשות בה דבר, והגם שאין הכרח זה הכרח, בסמוך אבאר על נכון טעם הטייתו למה שעשה, ומאמר ודברתם וגו' פשט הענין הוא מלבד מעשה המטה עוד כי צריך שידברו לה בפירוש הוציא מימיך, והוא מה שהבין משה ולא עלה על דעתו כי מאמר ודברתם הוא שישנו עליו פרק אחד:
@715 **והמשכיל** בעין השכל יראה כי השתנות משמעות מאמר **ודברתם** ישתנה כפי כוונת מאמר **קח את המטה**, כי הדעת נותנת שאין הסלע בעלת חי שתבין דבור בני אדם כשידבר אליו משה אלא בא' מב' דרכים, או באמצעות הכאה במטה אשר בו שם המפורש חקוק יעורר כח המחיה שבה, כמו שפירשתי במקום אחר שאין לך בצמחים שאין לו חלק חיוני כפי תכונתו, ואותו יעיר בהכאת מטה שבו חקוק שם עליון כמו שכן הבין משה, או על ידי שישנו עליו פרק אחד של תורה שהוא חיי עולם מפה קדוש יעורר כח שבדומם ומזה יתעורר לתת מים, לזה אם נפרש קיחת המטה שהיא על ההכאה אין צורך לשנות פרק אחד שזה הוא הערתו, ואם נפרש קיחת המטה אינה להכות נצטרך לפרש ודברתם לשנות עליו פרק אחד, ולזה דעת עליון כשאמר קח את המטה שהיתה כוונתו קיחה לבד, היתה כוונתו במאמר **ודברתם** לשנות פרק אחד מה שאין כן משה שהבין קיחת המטה להכות פירש **ודברתם** כפשוטו:
@715 **ועל** כל פנים לא נעלמו מעיני משה ב' הדרכים במאמר ה' קח את המטה, אבל פירוש ודברתם שהוא לשנות עליו פרק אחד אין זה פשטן של דברים שלא עלה על דעת משה פירוש זה, ודן בדעתו נביא ה' ואמר הנה לפני ב' דרכים, ואם אני עושה דיבור לבד ולא הכאה אני חושש שמא הפירוש האמיתי הוא להכות ומה גם שהוא יותר פשטי ועוד שהוא דבר רחוק שהדומם יתעורר בדיבור בן אדם כמו שכתבתי בסמוך, לזה אם אני מדבר בלא הכאה שלא כדרך שאמר ה' אין הסלע נותן מימיו ויתחלל שם שמים חילול גדול לעיני העדה אשר אני עושה הנס לעיניהם ואתחייב ראשי למלך, לזה יותר אבחר להכות ואטה לפירוש היותר צודק במשמעות מאמר קח את המטה ויקוים גם כן מאמר והוצאת להם מים וגו' כמו שפירשתי, ולא הכאה בלבד עשה אלא בשיתוף הדיבור הכה ואמר לסלע תן מימיך, ובזה אין מיחוש שלא תתן הסלע מימיה ולא יתחלל שם שמים גם הטה לפרש כוונת המאמר **והוצאת להם מים** שהוא על ההכאה הגם שנכנס אצלו בגדר ספק שהכוונה הוא מסלע שיהיו חפצים מהטעם עצמו כי חש לפירוש שהבין שהוא להכאה ומה גם שהוא יותר מוטה כנזכר, ואם כן כשיבא להוציא מסלע אחר אפילו על ידי הכאה לא יתן מימיו לכשנאמר שאין כוונת ה' אלא על סלע הידוע ובזה יתחלל שם שמים ח''ו, לזה אבחר להוציא מהסלע הידוע וכמו שדייק אל עליון במאמר **ונתן מימיו** שזה יצדיק שעל סלע הידוע שבו מים הוא אומר והוא בארה של מרים שמנע מימיו, והגם שאמר אחר כך והוצאת להם מים מן הסלע פירוש מן הסלע הידוע האמור בסמוך, ונמצא שכל כוונת משה לא היתה אלא לחוש על דבר כבוד שמו יתברך ויצתה השגגה באונס:
@715 **ובזה** מצאנו טעם לכל שגגותיו של משה, טעם שהכה חש למה שנשמע מדברי ה' שצריך הכאה ואם כן בלא הכאה לא יתן מימיו ונמצא מתחלל שם שמים, ומה שלא שנה פרק אחד אין זה פשט ודברתם ומשה לא הבין כן כיון שהבין שהמטה הוא להכות וכמו שכתבתי למעלה, וטעם שלא הוציא מים מסלע אחר כיון שאינו מוכרח במשמעות מאמר והוצאת להם מים שעל סלע אחר הוא אומר יש מיחוש שלא יתן ויש חילול ה' גדול, גם חשב כי למה יעשה נם חדש להוציא מים מסלע אחר באין צורך אליו, ודבר ידוע כי אין עושין נם אלא לצד הכרח גדול, ומעתה אין להאשימו על מאמר המן הסלע וגו' כיון שאין החלט במאמר ה' שאמר לו כן, לזה כשבאו ואמרו הוציא לנו מסלע זה אמר להם **שמעו נא המורים** לשון המראה ולשון הוראה כי היו מתכוונים לנסות כח עליון אם יוציא מכל סלע או מסלע זו לבד והיו מורים לו להוציא מסלע אחר, והקפיד משה על הדבר ואמר וגו':
@715 **ואל** ירע בעיניך לומר שמשה לא הבין אמיתות כוונת ה', כי אין הנביאות באה להצדיק בעיון ולזה תמצא שאמרו ז''ל (ב''ב י''ב.) חכם עדיף מנביא, ובמה שלפנינו לא נעלם מעיני משה גם כן המשמעות שנתכוון אליו ה' אלא שנפל לו ספק במשמעות אחר ומשום מיחוש כבודו יתברך הטה למה שעשה כנזכר ואחר שמצאנו טעם למעשה נביא אשא עיני להבין מאמרו יתברך בהקפדתו במאמר **יען לא האמנתם בי להקדישני**, פירוש אתם עשיתם ההכרעה לצד חששא שהסלע לא תתן מים אלא אם תהיה הסלע הידוע ודוקא על ידי הכאה ולא הכרעתם לצד קדושת שמי להקדישני בהוצאת מים מסלע אשר ירצו הם ובלא הכאה שבזה היה ה' מתקדש לעיניהם כשיראו שאפילו הדומם כל שהוא מפליא לעשות בדיבור לבד ובהער' בשנות עליה פרק אחד, והיה לכם לבטל המיחוש בעוצם האמונה שהייתם צריכין לעשות:
@715 **ועומק** הדברים הוא שאם היו משה ואהרן עושים קידוש ה' הגדול באמצעות שהיתה העדה גם כן כולה שלימה וצדיקים היו מחליטים אמונת ה' בלבם שלימה והיה נגרש מהם חלק הרע והיה כח בהם להעמיד אמונתם לדורי דורות, ומעתה היו משה ואהרן נכנסים לארץ והיה משה בונה בית המקדש ואין חשש להשלכת חמתו על ישראל כשיהיו חוטאים כאמור בדבריהם (מדרש תהלים ע''ט), בפסוק מזמור לאסף וגו' וכתבנוהו במקומות אחרים, וכיון שבא תיקון הדבר על ידיהם ולא עשאוהו נחלט הדבר ואמר ה' **לכן** פירוש בשביל זה גם לשון שבועה שלא יביאו וגו', כי ראה ה' מה שעתידין לעשות באחרית הימים בארץ ישראל, וכמו שאמר להם משה עצמו (דברים ל''א) ידעתי כי השחת תשחיתון, ולזה אם יכנס משה לארץ ויבנה בית המקדש יצטרך ה' להשליך עליהם חמתו כשירשיעו ולא על בית המקדש ויכלו כל ישראל ח''ו, לזה אמר **לכן לא תביאו** וגו', ודקדק לומר את הקהל **הזה**, אמרו במדרש (ילקוט) הזה אינכם מביאים אבל אתם מכניסים את כל ישראל לעתיד לבוא דכתיב וענתה שמה כימי נעוריה זה משה ואהרן עד כאן, ומתוכיות הדברים נשמע שאם היו מקדשים שם שמים לעיניהם היה הדור ההוא כדור שבן דוד בא שיעביר ה' את רוח הטומאה ומלאה הארץ דעה את ה':
@715 **והשקית את העדה**. דקדק לומר **והשקית** בכינוי, אולי שנתכוין לא' מב' דרכים, או לפי שהיו ישראל צמאים למים יצו ה' להשקותם כשיעור שלא יהיו ניזוקין, כי זולת זה אם ישתו כחפצם לרוב צמאונם למים ישתו הרבה ויסתכנו וימותו. או ירצה כי ישקם ככל הצורך ולא יקפיד על הזיקם כי המים ההם נסיים הם בכל פרטיהם בין בהוייתן בין בפעולתם, והוא אומרו **והשקית** שהגם שירצו לשתות בהסתפקות אתה השקה אותם ככל הצורך, והוצרך להזכיר **עדה ובעירם**, להקדים העדה לבהמות, והגם שאמר הכתוב ונתתי עשב בשדך לבהמתך ואכלת וגו' ואמרו ז''ל (ברכות מ.), שצריך להקדים מאכל לבהמתו ואחר כך הוא, כל זה אם אין סכנה בדבר אבל כשיש גדר סכנה חייו קודמין, ועיין מה שפירשתי בפרשה דרבקה (בראשית כ''ד) בהשקאת אליעזר וגמליו:
@716 **כאשר צוהו**. הוצרך לומר כן, לומר שלא נתעכב אלא סמוך לצוויו יתברך לקח המטה. עוד נתכוון לומר דבר זה עשה **כאשר ציוהו** והא למדת שמה שעשה מאז והלאה לא כאשר ציוהו, וכמו שכתבנו למעלה ששגג בפירושם של דברים:
@718 **במטהו פעמים**. טעם ב' פעמים כעבד שעושה שליחות אדונו בזריזות גדולה, ורבותינו ז''ל (סנהדרין לד.) דרשו דרשות וכפטיש וגו'. (יב) **ויאמר ה'**. קשה למה שקדם לנו כי לשון אמירה יורה על דברים המסעדים את הלב וגדולה וכבוד יבשר וכאן רואני שלא אמר אלא בשורת גזירה רעה, ויתבאר על פי מה שאמרו במדרש (במד''ר פי''ט) שאמר משה לפני ה' הרי גזרת עלי למות במדבר עם הדור הרע הזה וכו' יאמרו הדורות שאני שוה להם יכתב עלי על מה נענשתי לפיכך כתיב **יען לא האמנתם בי** וגו' עד כאן, והוא מה שרמז ה' באומרו **ויאמר** לשון רוממות למשה ולאהרן שנכתב חטאם שעליו מתו שהוא יען לא וגו', ולא יחשבו הדורות שהם שוים לדור הרע ח''ו:
@720 **המה מי מריבה וגו'**. צריך לדעת למה כפל לומר **מריבה אשר רבו** ולא הספיק לומר המה מים אשר רבו בני וגו', עוד מאומרו **רבו את ה'** זה יגיד שמדבר על ישראל ומאומרו **ויקדש בם** משמע שמדבר על משה ואהרן. ונראה שהכתוב בא לתת טעם להקפדתו יתברך על קדושת שמו בענין זה, ואמר **המה מי מריבה** וגו' ומריבה זו מצדיקה הכתוב באומרו **אשר רבו** פירוש שטענו טענה נגד ה' וצדקו בטענת מריבתם, **ויקדש בם** פירוש עשה ה' דברים להתקדש ביניהם פירוש בישראל במה שאמר למשה לדבר אל הסלע אשר ירצו בני ישראל שבזה יראו כח השליט שהגם שהביאם במדבר לא מקום וגו' ומים אין יוציא להם במאמרו מים מכל מין סלע אשר תהיה לפניהם, ומשה ואהרן לא עשו כן לכן הקפיד ה' עליהם ואמר לכן וגו' ורז''ל אמרו (שם) **ויקדש בם** במשה ואהרן שגזר עליהם שלא יביאו וגו', וע' פנים לתורה:
@721 **אחיך ישראל אתה ידעת וגו'**. טעם אומרו **אחיך**, גם אומרו **אתה ידעת**, לומר כי תלאה זו לא נסבבה ממני אלא מאבותינו ואני ואתה אחים שוים בדבר, ששטר זה של התלאה היה כתוב על אבינו ואחד מן האחים פרעו, ותמצא שאמרו ז''ל (ב''ר פפ''ב) בפסוק וילך אל ארץ וזה לשונם מפני החוב שלא רצה לפרוע חוב אביו עד כאן, ואומרו **אתה ידעת** פירוש כבר קודם היות לנו התלאה ידעת אותה שנגזרה בין הבתרים, ודבר זה דוקא הוא שידעו, ולזה דקדק לומר **אתה**, העובדי כוכבים ומזלות היו חושבים כי מקרה הירידה היה להם להיות עבדים ושפלים, ואומרו **וירדו אבותינו** וגו' פירוש מלבד הגלות עוד נוסף שסבלנו צרה כפולה שהיה הגלות במצרים, על דרך מה שכתבו בתוספות במסכת שבת (י:) במה שאמרו שם בגמרא וזה לשונם לעולם אל ישנה אדם את בנו בין הבנים שבשביל ב' סלעים מילת וכו' נתגלגל הדבר וירדו אבותינו למצרים עד כאן, והקשו התוספות והלא הגזירה היתה מבין הבתרים, ותרצו שאם לא היה שינוי שעשה יעקב ליוסף היה הגלות במקום אחר בלא כל כך תוקף השעבוד אשר הפליאו למרר חייהם, מעתה היות הגלות במצרים הוא נוסף על הידוע בגזירה, לזה אמר **וירדו** וגו' פירוש ועוד לנו שהיתה התלאה במקום זה הרע ימים רבים **וירעו לנו** וגו', ונתכוונו גם כן במאמר זה לומר שהם פרעו שטר חוב ומצד זה זכו בארץ, והודיעום גם כן כי פרעו פרעון גדול בכל כך צער זמן ארוך כאומרו **ימים רבים**:
@724 **נעברה נא בארצך**. ולא אמר נא נעברה, אם נפרשה לשון בקשה נתכוון להסמיך הבקשה לארצו שהיא עיקר השאלה שיהיה המעבר בארצו, ואם נפרשה לשון זמן יתבאר על דרך אומרם ז''ל (ב''ר פ' מ''ד) שאחד מג' עכו''ם שנתן ה' לזרעו של אברהם הוא אדום, לזה דקדק משה בשליחות זה ואמר שכל התנאים שהוא מתנה על עצמו לא נטה ימין ושמאל וגו' כל זה אינו אלא בהעברה של עתה, אבל כשיעברו לעתיד לבא כי משה הוא אשר היה מושיע ורב אז לא יקבל עליו כל התנאים אלא להורישם ולהומם ולבוז ביזם דכתיב (עובדי' א') בית יעקב אש וגו' ובית עשו לקש וגו':
@730 **ויאמר ה' וגו' על גבול ארץ אדום וגו'**. טעם שהוצרך לומר **על גבול** וגו', פירוש על סיבת הגעתם לגבול רשעה נסתלק אהרן, שוב בא לידי מדרש אחד (ילקוט כאן) וזה לשונם בהתחברך לרשע וגו' בשביל שנתחברו לאדום חסרו צדיק אחד עד כאן, והם הדברים עצמן שרמזנו במאמר **על גבול** וגו', ולדרך זה יתבאר אומרו **לאמר** שיצו ה' למשה לומר לישראל פרט זה שרמז במאמר על גבול שהתחברם לרשע סבב פטירת הצדיק, והגם שכבר נגזרה גזירה זו עליו, אפשר שהיה חי עוד ימים עוד לומר מגלגלין חובה על ידי חייב, ובדרך רמז כיון שאהרן עומד עם משה לגאולה העתידה כאומדם ז''ל (שם) בפסוק וענתה שמה כימי נעוריה שכתבתי למעלה, וגאולה העתידה היא מיד אדום שהיא מלכות ס''מ לזה אמר **על גבול ארץ אדום** פירוש על סיבת גבולם אשר הגביל ה' קץ לאדום לימסר ביד ישראל לזה שם יאסף אהרן, וגמר אומר **אל עמיו** לרמוז לעמיו העתידים לרשת ארץ אדום:
@731 **על אשר מריתם את פי**. לפי דברי המדרש (שם) שכתבתי למעלה שיחד מאמר **מריתם פי** כנגד אשר אמר להם לשנות פרק אחד על הסלע בחר ה' ליחד פרט זה למיתת אהרן כי הוא שגיון שלם בערך אהרן, שהגם שמשה לא שנה היה לאהרן לשנות הפרק וכשלא שנה הרי המרה את פי ה', אבל על ג' דברים הרשומים בדבריהם לא היה אלא מסכים למעשה משה, שההכאה משה לבדו הכה, והוצאת מים מסלע שלא היו רוצים ישראל גם כן הוא מעשה משה אלא שהסכים אהרן, וכן מאמר **המן הסלע הזה** הוא דברי משה לבדו, ותמצא שפרט זה של חטא המן הסלע יחדו ה' למשה בשעה שאמר לו (דברים ל''ב) עלה וגו' ומות וגו' על אשר מעלתם וגו' שפירש בה מעל, ולדברי המדרש מאמר זה בא על פרט חטא אומרו **המן הסלע** שפרט, ודבר זה בפרט אין חלק לאהרן בו כי למה יענש אהרן אם משה אמר דיבור בלתי הגון, בשלמא בענין הסלע ובהכאתה הם דברים שבא שליחות מה' לאהרן על ידי משה ויענש על שינוי אשר יעשה בו מה שאין כן אם משה ידבר דברים לא הגונים אין אהרן נתפס עליו, אלא שכללו ה' עם משה לצד עיקר הדבר ששגגו בו יחד:
@733 **והפשט את אהרז את בגדיו**. אמר את **אהרן** את **בגדיו** שנראה שהם ב' הפשטות, הגם שאין זה צחות לשון עם כל זה אפשר שנתכוון לומר לו שהבגדים שיפשיט יהיו בגדי כהונה לא בגדי עצמו, לזה אמר **הפשט את אהרן** לגופה וחזר והתנה שההפשטה הוא **את בגדיו** המיוחדים לו לאהרן שהם בגדי כהונה ועליהם הוא אומר **והלבשתם את אלעזר**, וזה לא היה נשמע אם היה אומר והפשט אהרן את בגדיו שאז אין כאן יתור לדרוש ממנו אלא הדברים כפשטן, וכאלו אמר והפשט אהרן מבגדיו, ומאמר **את בגדיו** הוא גזירת והפשט, מה שאין כן אומרו **והפשט את אהרן** מאמר **את אהרן** הוא גזירת והפשט ונשאר מאמר **את בגדיו** מיותר לדרשה:
@733 **עוד** נתכוון לומר על זה הדרך הפשט את אהרן והפשטה זו אינה אלא מבגדיו והוא אומרו **את בגדיו**, אבל יש לו מלבוש אחר תיכף ומיד, והוא מאמרם ז''ל (ילקוט כאן) וזה לשונם היה אהרן מתפשט ומתלבש בענני כבוד, ומעתה לא נשאר אהרן מופשט מהמלבוש אפילו בעת שהיה מפשיטו משה לא היה נפשט אלא מבגדיו והיה מלביש הענן כל חלק וחלק הנפשט ממנו:
@737 **וילחם בישראל**. טעם אומרו **בישראל** ולא אמר עם ישראל וכמו שאמר בפרשת בשלח ויבא עמלק וילחם עם ישראל, נתכוון לומר כי הם היו סיבה למלחמה זו לצד חטאם, גם מה שאמר בסמוך **וישב ממנו שבי** פירוש ממנו היה הסובב לשבות שביו, והחטא הוא שהם היו סיבה להעדר הצדיק מחמת מי מריבה דכתיב (תהלים ק''ו) ויקציפו על מי מריבה וירע למשה בעבורם, ולא למשה בלבד אלא גם לאהרן כמובן מהענין אלא שמזכיר משה שהוא העיקר:
@737 **וישב ממנו שבי וגו'**. יש להעיר למה לא חרדו ישראל בראותם שעם אחד לקח מישראל שבי ויאמרו אם עם אחד עשה בהם פרץ מה יעשו בכניסתם לארץ, וכמו שמצינו שנתרגש יהושע כשהכו אנשי העי גבור אחד מישראל כאמור שם (יהושע ז'), והגם כי אחר כך נתעצמו בתפלה ונתנו ה' בידם, סוף כל סוף לא מצינו שנתרגשו מקודם, ונראה על פי דבריהם (במד''ר כאן) שאמרו שעם זה עמלק היה, והגם שהכתוב קראו כנעני הוא לצד שבא במלבוש כנעני, ולזה כשהתפללו ישראל שיתנהו בידם לא אמרו תתן את הכנעני הזה, מעתה לצד שלא היה מז' אומות שנתן להם ה' לא נתרגשו בראותו נוצח במלחמה שהרי אין להם ממנו כלום, עוד נראה שלא נתרגשו אלא אז כשנכנסו לארץ שהגיע זמן ששלם עון האמורי מה שאין כן קודם שנכנסו לארץ שאפשר שעדיין לא שלם עונו כדי שיתנהו ביד ישראל, ורז''ל דרשו בזה הרבה דרשות:
@738 **אם נתן תתן** כפל לומר **נתן תתן**, לצד שלא היו יודעים איזה עם הוא לזה אמרו **אם נתון** פירוש אם הוא בכלל הז' אומות הנתונים מה טוב ואם לאו **תתן**, ורז''ל אמרו (מדרש לקח טוב כאן) נתון הכנעני תתן השביה:
@741 **וידבר העם באלהים ובמשה**. הגם שיודעים שכל הנהגתם היא על פי ה' ואין משה עושה דבר מדעתו, אף על פי כן התרעמו עליו שהסכים על דעת קונו ולא הפיל תחינתו לפניו להביאם דרך נכון למועדי רגל, ונראה כי דבריהם כאן לא היו לעשות גזירה עליהם כדרך שאמרו במרגלים (יד ג') למה ה' וגו' נתנה ראש ונשובה מצרימה אלא כמי שמתרעם על חבירו אשר לא טוב עשה, וזה יקרא מדברי לשון הרע, ולזה שלח ה' בהם נחשים מדה כנגד מדה כאומרם ז''ל (תענית ח.) שאלו לנחש וכו':
@741 **ונפשנו קצה וגו'**. אולי שהרגישו לצד הסיבוב של ארץ אדום וקצרה נפשם בדרך חשבו כי זה נסבב לצד היות מזונם מהמן ולא מהלחם, והטעם כי מטבע הולכי דרכים לאכול דבר שהוא קצת קשה להתעכל כי באמצעות ההליכה ממהר להתעכל וכל שנתעכל צריכין למזון פעם אחרת ולזה כשהם אוכלים לחם הם מתחזקים והולכים בכח מה שאין כן באכילת המן שהוא דבר רוחני ותכף מתעכל וזה יסובב שיהיה להם טורח הדרך כי הבטן ריקנית, ולזה הקדים הכתוב ואמר **לסבוב את ארץ אדום** וגו' וזה סיבה להרגשת העם שדברו ואמרו **אין לחם** וגו', **ונפשנו קצה בלחם הקלוקל** פירוש שמתקלקל תכף ומיד ואינו שוהה להתעכל, ורז''ל אמרו (במד''ר כאן) כי המדברים היו שיורי העם שנגזרה עליהם גזירה למות במדבר שלא היה להם נחת רוח במדבר והיו קצים בחייהם מה שאין כן הנכנסים שהיה להם נחת רוח במדבר:
@742 **את הנחשים השרפים**. נראה כי לצד שישראל דברו במשה והוסיפו לחטוא לדבר באלהים שלח ה' בהם מה שנולדו מחטאם, כי כבר כתבנו במקומת אחרים כי מהעבירה יוצא מזיק, ובזה תעמוד על אמיתת מאמרם ז''ל (תענית שם) שאמרו שאלו לנחש ארי דורם ואוכל וכו' אתה מה הנאה יש לך והשיב אמרו לבעל הלשון עד כאן, פירוש תשובתו כי יש מין עבירה שממנה יצא מין נזק שבו, וכאן נולדו מחטאתם ב' דברים נחש ושרף נחש שיש בו שנים ממית אדם ושורף הנפש, וישלחם ה' בם כאומרו **וישלח ה' בעם את הנחשים השרפים**, ואמר **וישלח** על דרך אומרו (איוב ח') וישלחם ביד פשעם, **הנחשים** הם כנגד מה שדברו במשה שכל המדבר לשון הרע בחברו ומכל שכן ברבו נחש מכישו, **והשרפים** הם כנגד מה שדברו באלהים. שוב ראיתי במדרש (רבה כאן) וזה לשונם השרפים שהם שורפים הנפש עד כאן, וזה מכוון לדברינו:
@743 **התפלל וגו' ויסר וגו'**. פירוש **התפלל** למחול החטא, והנה ישתנה מחילת החטא קודם שיצא המחבל לאחר שיצא שאז הגם שנמחל החטא צריך זכות להסיר המזיק, וכמאמרם ז''ל (שבת לב.) וזה לשונם לעולם יבקש אדם רחמים קודם שיחלה שאם יחלה אומרים לו הבא זכות והפטר, לזה נתחכמו דור דעה ואמרו כנגד מה שצריך זכות להצלתם מהנחשים ויסר פירוש שיתפלל גם כן לה' בזכותו של משה להסיר וגו':
@743 **את הנחש**. נתכוונו לומר שיסיר אפילו היזק הקטן שהיא עקיצה ההורגת, ואם היו אומרים את השרף או נחש השרף היה נשמע שעל פרט נחש שהוא שורף את הנפש הוא שמקפידים אבל אם ימות כדרך העולם אינם מבקשים ממנו תלמוד לומר **את הנחש** אפילו פרט הנחש שהוא העונש המכוון כנגד מה שדברו במשה, גם דקדקו לומר לשון יחיד שלא ישאר אפילו נחש אחד כי אחד יכול להמית כמה וכמה:
@744 **עשה לך שרף**. אמר תיבת **לך** רז''ל אמרו (ילקוט ע''ז מד.) וזה לשונם הרי הוא אומר לך משלך ואין אדם אוסר דבר שאינו שלו עד כאן. פירוש כיון שעשאו משה אינו נאסר כשיעבדוהו דורות הבאים, וענין זה אנו למדין אותו ממה שאנו רואים אחר האמת, אבל דוחק לומר שה' אמר לו כך לעשותו משלו כדי שלא יאסר בעבודת דורות הבאים וצריך לדעת למה צוה ה' כן, עוד יש להעיר למה ה' אמר לו שרף ובמעשה משה קורא אותו נחש, עוד יש לדעת טעם ענין זה שצוה ה' לעשות נחש ולהסתכל בו מה יועיל הסתכלות בנחש לרפאות הנשיכה, ורז''ל אמרו (ר''ה כט.) כל זמן שישראל מסתכלין כלפי מעלה וכו' עד כאן, ואם היתה הכוונה בזה להסתכל כלפי מעלה לבד יותר היה ראוי להסתכל בשמים ואז תהיה הכוונה ניכרת לעושיה ביותר מהסתכלות בנחש:
@744 **ונראה** לפי מה שפירשתי שהענישם ה' בנחשים השרפים כנגד ב' עונות שעשו שדברו באלהים ובמשה לזה באה התשובה מה' ואמר לו **עשה לך שרף** כאן רמז שיעשה הנחש בסדר שיהיו רמוזים ב' פרטי החטא שהם שדברו בה' ודברו במשה, כנגד מה שדברו במשה אמר **עשה לך** פירוש כנגד דבר הנוגע לך, וכנגד פרט החטא שדברו בה' אמר **שרף** פירוש בדמות שרף, כי צורך היה בדבר שיהיה בו היכר לב' דברים שהם לשון הרע שדברו באלהים וגם מה שדברו במשה מטעם אשר אבאר, ונתחכם משה לעשות היכר למין חטא שדברו בו שהוא בחינת הנחש במה שעשאו מן הנחושת, כי זולת זה אין בדמיון השרף היכר לב' פרטי החטא, והוא מה שאמר **ויעש משה נחש** פירוש פרט זה של נחש שהוא היכר פרט החטא שדברו בו עשאו לשרף מנחושת ולא מדבר אחר, נמצא דוגמת הנחש הוא כנגד היכר השרף שהרי הוא דומה לו בדמותו, והמין שממנו נעשה שהוא הנחושת הוא כנגד היכר פרט הנחש שממנו הוא:
@744 **וטעם** כל המעשה נראה בהעיר עוד למה לא הועילה תפלתו של משה להסיר הנחשים השרפים ולא יהיה נושך להצטרך לרפואתו, אלא ודאי זה יגיד כי בעל המשפט בחן שלא עשו תשובה המספקת להם, והגם שאמרו חטאנו כי דברנו בה' ובך העיקר חסר והוא העזיבה, ולא מצאנו שאמרו לא נשוב עוד לדבר הרע הזה, ולזה לא הוסר הנגע, לזה נתחכם הבורא ונתיעץ לתקנם על זה הדרך כי מי שתקן עצמו כראוי הנה הוא ניצול ולא ישכנו נחש, ומי שלא נתקן כמצטרך ישכנו נחש לעוררו בתשובה, וצוה עליו להביט אל נחש וגו' ובזה יתקן עצמו ושב ורפא לו:
@744 **והבטתם** לנחש תרמוז לז' דברים:
@744 **הא'** תשובת הגדר על זה הדרך הנה מי גורם לנחש לנשוך הוא חטא בני אדם דכתיב (קהלת י') אם ישוך הנחש בלא לחש וכשאין לחש יעשה הנחש דומם כנחש אשר אליו יביטו כשינשכם נחש, וזו היא הערת הבטתם בנחש הדומם לומר אל זה אביט לעשות כמעשהו לידום מלדבר עוד, ובזה עושים עזיבת החטא:
@744 **ב')** להכיר חטאם על דרך אומרו בזוהר (תיקונים י''ג) על ההוא חויא דמקננא במגדלא שהוא ס''מ הנמשל לנחש שפיתה תחילה לאדם, והוא מה שמעיר נחש במקום גבוה, שיכירו שהם סיבה במה שדברו לשון הרע להכנים נחש במקום גבוה, גם שעשו מעשה נחש שהוא לשון הרע במקום עליון שדברו באלהים, גם יש הערה שדברו במשה בראותם מין מחצב שממנו נעשה הנחש:
@744 **ג')** להעירם מה יקרו דברים גבוהים מדברים ארציים כי נחש שלמטה ממית ונחש עליון מחיה, ובזה ירגישו את אשר דברו רעה על המן שבא מן השמים שהוא לחם הקלוקל ובוחרים בלחם אשר תוציא הארץ, שעליהם נאמר (ישעי' ה') הוי אומרים על הטוב רע ועל הרע טוב:
@744 **ד')** להעירם בתשובה מה שהתרעמו למה הביאם ה' דרך המדבר שאין שם סיפוק ולא הביאם דרך מקום אשר רגיל היות שם בר ולחם, כי ה' חפץ שעיניהם יהיו תלויות לאלהים יושב בשמים על מחיתם ועל כל צורכיהם באין מבטח זולתו מהטעם עצמו שלא הסיר הנחשים והניחם לנושכם ויהיו מתרפאים כשיסתכלו כלפי מעלה לאביהם שבשמים, והוא מאמרם ז''ל (ר''ה כ''ט.) אלא שלא פירשו ההערה שבדבר שהיא תשובה לדברי לשון הרע שדברו למה הביאם אל המדבר, שה' חפץ בזה כדי שיהיה לבם תמיד באין הפסק קרוב לה' כבן המצפה לשלחן אביו ערב ובקר ובכל עת וזמן, ואם היה מביאם דרך ישוב לא היתה להם הדביקות בתמידות כשיהיה מזומן לפניהם סיפוקם, ומה מאוד יסובב דבר זה הרחקת הלב מהכרת השגחת הבורא ויראת רוממותו:
@744 **ה')** להשיבם על מה שנכלל בתרעומת שאמרו למה הביאם דרך מדבר שכוונתם היא שאין סומכין על הנם מטעם שאין הנס מתמיד, וצא ולמד ממה שאומרים הכופרים בפלאי ה' שמבקשים חכמות כוזבים להכחיש בנס ולעשות הדבר דרך טבע שיהיה המעשה ההוא באותו זמן וכל השתנות טבעיות לא יתמיד, ואפשר ששורש לענה זה היה בלב המדברים תועה, לזה צוה ה' לעשות נס קבוע כאומרם ז''ל (במד''ר פי''ט) שזרק משה הנחש השמימה ועמד באויר ושם קנה מקומו באין סומך והיה כל הנשוך יביט אליו ויכיר בהכחשת דעת טועה שהיתה לו מקודם ויאמין כי ה' אשר הביאם למדבר עשה יעשה נסים בהתמדה עד גדר שישמשו הנסים כטבע הרגיל והיה המדבר כישוב לכל הצורך:
@744 **ו')** להראותם כח התשובה על דרך אומרם ז''ל (יומא פו:) שבעלי תשובה נעשים להם העבירות זכיות כי לא לבד מחילת החטא אלא אדרבה יעמוד לו זכות, והוא מה שהעיר בהבטה אל נחש הנחושת לומר שהנחש נשך והוא עצמו כשהוא בבחינת השתיקה פירוש שלא ידבר עוד הגם שכבר דיבר כי כל מין הנחש ידבר לשון הרע אף על פי כן הוא עצמו מחיה ונהפך מרעה לטובה:
@744 **ז')** כי חפץ ה' שיכירו בניסי אל בדרך פרט שכל אחד מהנשוכים יביט למעלה ויכיר בניסו ובזה יצדיקו השגחה הפרטית:
@744 **והיה כל הנשוך**. אמר **והיה** לשון שמחה על הנשיכה, לצד התועליות הנמשכות מהבטת אל נחש הנחושת בז' דברים אשר יכיר בהם בעל הנם כמו שכתבנו, ואמר **כל הנשוך** פירוש אפילו שכבר היה נשוך קודם מעשה נחש הנחושת, ואומרו **וחי** בתוספות וא''ו להעיר גם על חיות הנפש כשיכיר בנס ופרטים הרמוזים יצדיק עצמו ויחיה חיות הגוף וחיות הנפש:
@748 **משם נסעו וגו'**. יש להעיר למה שינה במסע זה ושלאחריו לומר בדרך זה **משם** וגו', ולא אמר כדרך שאמר במקרא שלפניו ושלפני פניו ויסעו וגו' ויסעו וגו'. ואולי כי ב' מסעות אלו של נחל זרד ושל נחל ארנון נסעו מעצמן ולא על פי העננים כסדר הרגיל, ולזה שינה הכתוב ואמר **משם נסעו** פירוש מעצמן. וראיתי להוכיח כפירושינו זה ממה שאמר הכתוב בפרשת דברים (דברים ב) עתה קומו ועברו לכם את נחל זרד וכתיב (שם) קומו סעו ועברו את נחל ארנון, הדברים יגידו שלא נסעו על פי הענן שאם היה על פי הענן מה מקום לדברי משה הלא כשהענן נוסע יסעו ולא היה צורך לומר להם קומו ועברו. והגם שאמר הכתוב (לעיל ט כ') על פי ה' יחנו ועל פי ה' יסעו, זה היה בכל המסעות חוץ מאלו. והטעם אפשר שב' המסעות הללו היו אחר שמת אהרן ונסתלקו ענני כבוד, והגם שאמרו ז''ל (תענית ט.) שחזרו בזכותו של משה, אולי שהענן שהיו נוסעים וחונים על פיו נשאר מסולק בזמן שנסעו ב' מסעות הנזכרים:
@750 **על כן יאמר וגו'**. רז''ל דרשו ב' דרשות בכתוב, א' (קידושין ל:) שהכתוב מדבר במלחמתה של תורה שהיא מלחמת ה', שהגם שנעשים שונאים זה לזה בהלכה נעשים אוהבים לבסוף, והוא מאמר **את והב בסופה**. ב' (ברכות נד.) כי ב' אנשים מצורעים היו בישראל אחד שמו את ואחד שמו והב והיו מהלכים בסוף המחנה לצד היותם מצורעים והיו מודיעים הנס שהיו עושים פגיעת ההרים וכו' עד כאן:
@750 **ונראה** לפרש הכתוב בדרך פשט, כי כיון שהזכיר ארנון גבול מואב ואמר עליה **כי ארנון גבול מואב** פירוש ואין להם בו לישראל חלק לזה גמר אומר **על כן יאמר בספר** פירוש בספר אשר לפני ה' בענין המלחמות אשר ינחיל לעמים ומוציא מזה ונותן לזה ושם גם כן יאמר אשר ינחיל ה' את ישראל מהאומות כאשר הבטיח להאבות ואמר **יאמר** כי שם בספר יאמר על גבול זה שיתנו לישראל בסופה, ולא בזמן ההוא אלא בבא משיחנו אז ינחילנו ה' מואב וגבולו שהוא אחד מהג' הנשארים לנו לנחול אותם שהם הקיני והקניזי והקדמוני, ופירוש תיבת **והב** מתפרש בב' דרכים, הא' לשון אהבה על זה הדרך כי ה' אהב לתתה בסוף ולא עתה, או לשון נתינה על דרך (דניאל ב') יהב חכמתא לחכימין ומצינו שהכתוב ידבר לפעמים תיבה בלשון תרגום, כמו (בראשית כא) מי מלל לאברהם, ואתה מרבבות קודש (דברים לג), ואומרו **ואת הנחלים** וגו' פירוש בא לסדר הגבול של מואב שכתוב בספר מלחמות ה' שעתיד ה' לתת לנו ואמר ואת הנחלים של ארנון גם כן בכלל הניתן לישראל, גם אשד הנחלים אשר נטה וגו':
@753 **אז ישיר ישראל וגו'**. צריך לרעת שירה זו מה טיבה, גם למה לא אמרו שירה על המן כמו שאמרו שירה על המים, גם כל הפרשה צריכה ביאור, ואפשר כי שירה זו על התורה אמרוה, ובזה גם כן לא נקרא תגר על הדור ההוא למה לא שוררו שירה חדשה כשנתנה להם תורה מורשה אשר לה נאוה תהלה, כי ודאי היא זאת שירת התורה שנקראת באר מים, נקראת באר על שם המקור שהיא שכינה עליונה שנקראת באר, גם (מים) לפי שהתורה נמשלה למים, ואומרו **עלי באר** לשון עליה כי לא על באר שלמטה הם אומרים אלא על באר עלי פירוש עליון, **ענו לה** על דרך אומרו (שמות טו) ותען להם מרים שהוא דרך השיר:
@754 **ואמרו חפר וה שרים** וגו' יתבאר על פי דבריהם (ב''ר ס''ד) שאמרו כי באמצעות עסק התורה מתקנים מקור עליון שנקרא באר, והתיקון הוא כפי בחינת מעלת העוסקים בתורה, הצדיקים הראשונים שהיו במדרגה גדולה הם שחפרו את הבאר ועשאוה לשתות ממנה והם האבות בסוד (בראשית כט) והאבן גדולה על פי הבאר ויגל את האבן וישק את הצאן, ומאז היתה ראויה התורה לינתן לישראל ועודנה לא היתה בבחינת ההשגה לשתות ממנה עד שכרוה נדיבי העם הם משה אשר הורידה לנו, ועמדו אחריו מקבלים ממנו זקנים ונביאים ואנשי כנסת הגדולה ופירשוה וגילו מצפוניה, והוא אומרו **כרוה נדיבי העם**, כי תורה שבכתב בלא תורה שבעל פה אין אדם יכול לשתות ממימיה, ואומרו **במחוקק במשענותם** הוא מה שהוסיפו לחדש בתורה חכמי הדורות, ואין זה אלא כחוקק בה חקיקה, ואינו כמדת הראשונים שחפרו וכרו, וגם זה אינו אלא במשענותם של ראשונים שכל דקדוק ודקדוק שידקדק בתורה צריך לפרשו על פי דבריהם, וכל דבר שלא יהיה מיוסד על פי דברי הקדמונים אין לסמוך עליו:
@754 **ואומרו וממדבר מתנה** פירוש מה שזכו נוחליה לא זכו אלא לצד שהיו מחשיבין עצמן כמדבר, וכמו שפירשנו בפסוק (שמות יט ב) ויחנו במדבר שהתורה אינה נקנית אלא באמצעות הענוה והשפלות, ואומרו **וממתנה נחליאל** שבאמצעות התורה שניתנה לנו נחל אותנו אל דכתיב (דברים לב) יעקב חבל נחלתו, גם ירצה שנחלנו אל להיות מיוחד לנו לאלוה דכתיב (תהלים קלה) כי יעקב בחר לו יה, גם שכן בתוכנו ועזב מדור עליון. ואומרו **ומנחליאל במות** פירוש ומאמצעות דבר זה שנחלנו אל במות נעשינו במדריגה עליונה על המלאכים שבחר בנו ה' יותר מהם. ואומרו **ומבמות הגיא אשר** וגו' יתבאר על פי מה שקדם לנו שעיקר תכלית שכר האדם במצותיו ואושריו אינם אלא בעולם העליון אבל בעולם הזה אינו מקום השגת אושר הרוחני:
@754 **ומעתה** הכרח הוא להסתלק האדם מן העולם הזה להשתלם גמוליו כיד ה' הטובה, ומה שאנו רואים שהמיתה נסבבה על חטא האדם שזה יגיד שזולת זה היה האדם חי תמיד ותאמר אם כן יהיה האדם חסר גמולו הטוב, לזה אמרו בעלי הסוד כי זולת החטא היה האדם עולה לרקיע ודר בעליה ובחצר, וזה לך האות אליהו הנביא שעלה השמימה להשתלם גמולו ולא טעם טעם מיתה, והגוף הן אמת שאינו יכול לעמוד בעליה העליונה הגם שנזדכך הגוף ועמד בגדר רוחני אף על פי כן בערך רוחניות עליון יחשב לגשם, אלא שאמרו ז''ל (זוח''א רט.) במעשה אליהו ז''ל כי בהגיעו לגלגל חמה שם נפשט מגופו והניח אותו בגלגל חמה וכשהוא יורד למטה לובשו ויורד בו, ואמרו ז''ל עוד שכשנתן ה' תורה לישראל בהר סיני נעשו ישראל בני חורין מהמיתה וחזרו להיות כאדם קודם שחטא דכתיב חרות על הלוחות ואמרו ז''ל (שמו''ר פ' מ''א) אל תקרי חרות אלא חירות חירות ממלאך המות, וכיון שכן בעת הגיע תכלית שלימותם היו עולים גוף ונפש ופושטים גופם בגלגל חמה כאליהו, והוא מאמר הכתוב כאן **ומבמות הגיא** פירוש ממדריגה העליונה שהשגנו באמצעות התורה יש עוד השגה אחרת מצד דבר זה שהוא הגיא שהיא ירידת גשמנו בגיא שהיא הקבר, **אשר בשדה מואב** שהארץ תקרא שדה, ואומרו **מואב** שבראה אב העולם:
@754 **או** ירמוז להאשה שנקראת גם כן שדה כאמור בדבריהם (זוח''א לו:) והכוונה היא על זה הדרך הגיא אשר בא מפאת האשה שהיא חוה שבאה מאב כל הנבראים שלקחה ה' מצלעותיו ואין אשה בעולם שבאה כדרך זה מצלעות האדם כי אם זאת, והיא היתה סיבת המות להפיל העצמות בגיא, מעתה מאמצעות השגת התורה יחזור הדבר לקדמותו קודם שחטאה חוה ויהיה הגוף כמו שהיה בגיא למעלה, ואין אני יודע גדר מקום זה שהוא אומר ראש הפסגה שאמרנו במקום גלגל חמה והוא אומרו **ראש הפסגה** שמא הוא למעלה במקום הנשמות, לזה אמר **ונשקפה** וגו' על פני העולם הזה שהוא נקרא ישימון לשון שממה שעתיד להיות שמם, או נקרא כן לפי ששולט בו יצר הרע השומם את הנבראים, ואי זה מקום שהוא נשקף על פנים של עולם הזה הוא גלגל חמה שם יונח מה שהיה ראוי להיות בגיא, ונמצא כי באמצעות תועליות התורה כמצטרך יושג להנחיל הנפש והגוף בחיים:
@754 **חסלת פרשת חקת**
@773 **וירא בלק בן צפור וגו' ויגר מואב וגו'**. צריך לדעת לאיזה ענין תלה הראיה בבלק ולא בבעלי המגור שהם מואב. ב'. למה לא פחדו אלא מואב ולא מדין, ומה גם שהמדינים להם יאות הפחד כי המה אבדו ולא מואב ומזלייהו יחזה את אשר יקרה להם. ונראה על פי דבריהם (במד''ר פ''כ) שאמרו שבלק מנסיכי מדין היה אלא שמחמת פחד ישראל עשאוהו מואב מלך עליהם, מעתה במאמר וירא בלק גילה הפסוק פחד ומורא מדין כי אז באותו מצב היה גדול נסיכם של מדין, והגם שלא הזכיר בפירוש המורא מובן הוא בזכרון מעשה ישראל לאמורי שהם תוקף כל יושבי הארץ, והזכיר אחר כך מגור מואב גם כן דכתיב ויגר מואב, ומאמצעות ב' מוראים עשו שלום ביניהם ויאמר מואב לזקני וגו', וכן אמרו ז''ל (שם) וזה לשונם והלא המואבים נלחמים עם המדינים דכתיב המכה את מדין בשדה מואב ושנאה היה ביניהם מעולם משל לב' כלבים וכו' עד כאן, הרי ששניהם פחדו, וטעם הכנעתם של מואב שקבלו מנסיכי מדין למלך עליהם ולא להפך מפני שמואב היו צריכין לעצתן לפי שנתגדל משה ביניהם כאומרם ז''ל (שם) ולזה נכנעו להם והמליכו נסיכם:
@773 **עוד** נראה בהעיר עוד למה אמר לשון ראיה ולא לשון שמיעה, והגם שרז''ל אמרו (מכילתא) וזה לשונם יש ראיה שהיא שמיעה כגון וכל העם רואים את הקולות עד כאן, הלא במקום אחר (מכילתא) מצינו שדרשו שהיו רואים הקולות ממש. עוד למה הוצרך להזכיר שם אביו בן צפור, עוד למה דקדק לומר ב' רבויים **את כל**. עוד צריך לדעת למה כפל לומר **ויגר מואב** וגו', **ויקץ** וגו' עוד למה פעם קראם העם ופעם קראם בני ישראל. אכן יתבאר על דרך אומרם ז''ל (זוהר כאן) כי בלק מכשף גדול היה יותר מבלעם והיה עושה כשפיו בצפור אחד ששמו ידוע, והוא אומרו **וירא בלק** ובמה ראה בצפור, והוא אומרו **בן צפור** פירוש להיותו בן צפור ראה בכשפיו של צפור, ואמר תיבת **בן** לצד כי הצפור הוא לו לאב ולקצין וממנו ידע את כל אשר עשה ישראל לאמורי, ולא הוצרך למגידים להודיע דבר קטן וגדול:
@773 **ואפשר** שכוונת הכתוב היא שמקודם היות המעשה ראה בצפור, ודקדק לומר **את כל** רמז בריבוי כל לגופה שראה בצפור כל מה שעשה ישראל לאמורי, וריבוי את רמז לראיה אחרת עמה [אומה] שעתידה להיות כיוצא בדבר האמורי שעתידין ישראל לכלותם, ומה אומה היא שעקרו ישראל אז היא מדין, וזה רמז בתיבת **את**, הא למדת שראה מה שעשו לאמורי ומה שיעשו למדין, ואפשר שראה גם כן כי מואב מובטחים מצרת ישראל כמו שכן היה, כי הכישוף יגיד העתיד אם רע אם טוב, ומעתה תלה הראיה בבלק כי הוא הרואה בצפור לבד וראיה זו לא ראה אותה אלא בלק בכשפיו, וכוונת הסיפור בדבר זה הוא להקדים הסיבות שסבבו מעשה קריאת בלעם והנמשך ממנו בעונות לישראל, שראיית בלק היתה סיבה אחת לנסבב כאשר אבאר, ואמר עוד **ויגר מואב** אינה הודעת הנמשך משמיעת בלק אלא הודעת סיבה אחרת למאורע הנמשך שנכנס בלב מואב מגור:
@773 **ודקדק** לומר **מפני העם** פירוש לצד היותם רבים ותקיפים כאומרו כי רב הוא, והוסיף לומר **ויקץ** וגו' נתכוון לומר שהגם שנכנם בלבם המגור עם כל זה היו מוצאים תרופה לדבר בדרך טבע שישכרו עמים רבים וחזקים כנגדם אלא צרתם צרה לצד היותם בני ישראל שאין נצחונם כפי הטבע אלא בנס ופלא, והוא אומרו ויקוצו **מפני בני ישראל** פירוש היותם בני ישראל ובאמצעות כל זה השלימו מואב עם מדין ומלך בלק עליהם ושלחו אחר בלעם והיו תוצאותיו חצר מות, ובהעדר אחת מכל הסיבות הנזכרות לא היו שולחים אחר בלעם ולא היה דבר, שאם לא היה ראיית בלק בנסתרות לא היה משיג לדעת את אשר תקראנה אותו ואת עמו במדין ולא היה מתרצה להשלים עם מואב להתחבר עמהם לבא כנגד ישראל, והגם שהיה שולח אחר בלעם והוא במקומו במדין, לא היה נסבב דבר בהפקרת הנשים שהפקירו המואבים כי מדין לא היו מובטחים ביציאתם לישראל כי אם המואבים לפי שאמר להם בנבואתו כי לא ירעו ולא ישחיתו להם אלא באחרית הימים דכתיב (כד יד) את אשר יעשה העם הזה לעמך באחרית הימים, ומזה הובטחו לשלוח בנותיהם למחנה העברים ולהתגר עמהם (סנהדרין קו.) כי שלמים הם עמהם, מה שאין כן מדין שלא מצינו שהפקירו מהם אלא מדינית אחת שאמרו ז''ל (מ''ר כאן) שהיא בתו של בלק כי הוא זה הנקרא צור, גם אם לא היה מוראם של מואב מהעם גם שקצו מפני בני ישראל כמו שפירשנו טעם הכפל וכו' לא היו משלימין עם מדין ולהמליך עליהם נסיכם, לזה הקדים ה' הסיבה ואמר **וירא בלק** וגו' **ויגר** וגו' **ויקץ** וגו' וזה היה סיבת **ויאמר מואב** וגו' וישלח מלאכים וגו' והיה מה שהיה:
@775 **ילחכו וגו' את כל סביבותינו**. אולי שלא רצו להראות כל כך מורך הלבב שהם יראים מהם אלא שהם חסים על הסביבות, ואמרו לשון רבים לכלול אותם עמהם, ואומרו **ובלק בן צפור** הם דברי הכתוב, או אפשר שהם דבריהם שאמרו כי דבר זה נוגע גם למדין להיות שבלק בן צפור מלך למואב בעת ההיא ואם כן החרפה נוגעת למדין לצד נסיכם, ודקדק לומר **בעת ההוא** לומר לא לפניו ולא לאחריו, כי אחר שבא בלעם והודיע להם כי לא ירעו ולא ישחיתו למואב שלחו את בלק ולא היה עוד מלך עליהם, וזה לך האות שנמצא את נסיכי מדין ונהרג עמהם:
@776 **וישלח וגו' אל בלעם וגו'**. הוצרך להזכיר שם אביו **בן בעור**, גם להזכיר מקומו **פתורה אשר** וגו' **ארץ בני עמו**, להודיעך הזריזות שעשה בלק הרשע בשליחות זה כדי שיבא לידי גמר תכף ומיד, לזה פירש לשלוחים ואמר **בן בעור** לבל יתחלף בלעם בבלעם, וכדי שלא יתעכבו לחזר אחריו ציין להם מקומו ואמר **פתורה**, ולחשש מקום אחר ששמו פתורה אמר **על הנהר**, והודיעם עוד כי הארץ ההיא היא **ארץ בני עמו** וכלם ידעו אותו גם ידעו דרך הלך בו, כי לפעמים לא ימצא האיש בביתו והם יודיעום מקום אשר ימצאוהו שם:
@776 לק **רוא לו**. נתחכם בתחילת מאמר השליחות לומר כי מה ששולח אחריו הוא להנאת עצמו של בלעם כי הוא רוצה לעשות עמו טובה, והכוונה בזה לרוץ אחר הנאתו בלא עיכוב:
@776 **הנה עם יצא וגו'**. צריך לדעת אומרו **הנה**. גם אומרו **יצא** וכי לא ידוע הוא לכל העולם שיצאו ישראל ומה גם לבלעם שהוצרך להודיעו, גם אומר **הנה כסה** שהיה לו לומר ויכם וגו'. ויתבאר הענין על פי דבריהם ז''ל (שמו''ד פ''א) שאמרו ג' יועצים היו לפרעה כשאמר על ישראל הבה נתחכמה לו ואחד מהם הוא בלעם והוא אשר יעץ עליהם רעה ובכשפיו העמיד כישוף לבל יוכל עבד לברוח ממצרים והיה מובטח כי לעולם לא יצא עם ישראל ממצרים, ולזה שלח לומר לו **הנה עם יצא ממצרים** פירוש הפך הידוע ובטל כח הכשפים, ואפשר כי בלעם היה מבטיח את בלק שלא יצאו ישראל משם עולמית ולזה אמר לו הנה יצא, ואומרו **הנה כסה** את עין הארץ נתכוון גם כן נגד מה שיעץ עליהם במועצותיו הרעים למען ענותו למעטם, גם להרוג זכוריהם ולשחת הבנים הנה הוא הפך הדברים שלא בלבד שלא נתמעט אלא אדרבא נתרבה עד למאד, והוא אומרו **הנה כסה את עין הארץ**:
@776 **ואומרו והוא יושב ממולי**. נתכוין בזה לומר שניכר מתוך מעשיו שמשים פניו למולי להורישני, ותמצא שאמרו רז''ל (מ''ר כאן) שישראל היו מראים עצמן מזויינים בכלי זיין נגד מואב מטעם חציפות הרשום בשם כידוע, ומזה הרגיש כי כונתם להרע להם. וטעמו של בלק ששלח דברים אלו בשליחות לבלעם, לצד שחש שיאמר בלעם למה לי ללכת שמה ויכול אני לעשות המעשים שיש בידי לעשות במקום שהיה בו, גם חשש בלק שירגיש בלעם בכשפיו לדעת כי לא ירעו ולא ישחיתו בגבול מואב ולא ירצה לבא ומשם ישלח לומר להם כי העם לא יצורו אותם ולא יתגרו בם, לזה הקדים בתחילת השליחות ואמר **הנה עם** וגו' **הנה כסה** וגו' לומר שאין לסמוך בענייני עם זה על אשר יגידו עליהם הכשפים שהרי אמרת לא יצא ויצא, ועצה עליהם גם כן לא תעמוד כמו שלא עמדה עצתך להמעיטם שהנה כסה וגו', ולומר לי שלא יתגרו מלחמה במואב והנני רואה שהוא נגד זה שהנה הוא יושב ממולי, לזה לא תסמוך על מה שתשכיל בידיעתך ובא תבא:
@777 **ועתה לכה נא וגו'**, אמר **ועתה** שלא יעכב אפילו שיעור שעה אחת כי כל שעה הם בסכנה מצדם, ואומרו **נא** לשון בקשה וסמך הבקשה לעיקר הפעולה שהיא ארה לי וגו' ודקדק לומר תיבת **לי** שתהיה הארירה בהם לי לצורכי, והכוונה בזה שלא תתעכב הארירה עד אחר שיעשו נקמה בהם ומה שהיה כבר היה אלא שתעשה הפעולה תכף ומיד שבזה תהיה הצלת מואב מהם, ורמז עוד במאמר **לי** לפי שקדם בלעם וברך את בלק כאומרם ז''ל (שם) לזה אמר ארה לי פירוש אפילו לי שכבר אני מבורך לא יועיל זה וצריך לארר אותם, ואם תאמר אינו צריך שכבר אתה מבורך, לזה אמר **כי עצום הוא ממני** כאן כלל ב' דברים, אחד ענין החוזק הטבעי, ואחד ענין הברכה כי עם זה ברכתו עצומה מברכתי, ואומרו **אולי נכה בו** פירוש ואחר כל זה עודני בגדר הספק אולי, וגם גדר ספק זה לא לאבדו אלא להכות בו לגרשו מעלי. גם נתכוון לומר כנגד הבינונים **נכה בו**, וכנגד הצדיקים **ואגרשנו**:
@777 **ובדרך** רמז פיו הכשילו במאמר **ארה לי** לארר את בלק, וכן היה שגרם לו בעצתו מיתת כזבי בתו, גם היה סבה שישוב בלק למדין ושם נפל בחרב דכתיב (לא ח) ואת מלכי מדין הרגו וגו' ואת צור וגו', וזולת הליכת בלעם שגילה למואב כי מובטחים הם מישראל ולא יעשו להם דבר אלא באחרית הימים היה נשאר שם בלק ולא היה חוזר למדין ולא היה נהרג, הרי נתקיים שהלך לארותו לבלק לקיים מה שנאמר (תהלים לז) חרבם תבא בלבם:
@777 **כי ידעתי את וגו'**. יתבאר על פי דבריהם (מ''ר כאן) שאמרו שבלעם ברך את בלק שיהיה מלך, לזה אמר **כי ידעתי את אשר תברך מבו** רך שהרי נתקיימה בו ברכתו, ודבר זה הוא ידוע אצלו לבד לפי שהוא ניסה את הדבר ואינו ידוע לכל כי ברכת בלעם ברכה, ואשר יאור זה ידוע ממה שקלל מואב לסיחון, ויש להעיר בענין זה בשלמא מה שהיו צודקין קללותיו של בלעם יש ב' טעמים בדבר, א' להיותו רע עין, והב' שהיה יודע רגע באפו כמאמרם ז''ל (ברכות ז.) והיה מקלל ברגע הזעם, אבל הברכה אין מציאות שתתקיים מפיו:
@777 **ונראה** כי לעולם ברכת בלעם כברכת חמור אלא שהרשע היה מערים כשהיה רואה באצטגנינות שפלוני יעלה לגדולה וכדומה היה עושה שמברכו וכשבא הדבר ומתברך חושב שברכתו של בלעם גרמה ולא כן הוא אלא מזלו גרם, וכמו כן עשה לבלק שראה בכוכבו שעתיד למלוך במואב וברכו בדבר עצמו לרמותו כי הוא הסובב:
@779 **לינו פה**. דקדק לומר תיבת **פה**, אולי שנתכוון לומר להם שילינו אתו במלונו, וגמר אומר הטעם **והשיבותי** וגו' **כאשר ידבר** וגו', דקדק לומר כאשר ולא אמר אשר ידבר וגו' נתכוון לומר טעם שאומר להם לינו פה עמו כדי שתכף ומיד כאשר ידבר ה' אליו ישיבם דבר מה שלא יהיה כן כשיהיו חוץ למלונו, ואמר **הלילה** אולי שאמר כן לצד צרות עינו שלא נתן להם אכסניא אלא ללילה אחת:
@780 **מי האנשים וגו'**. צריך לדעת למה שאל אותו ה' הממנו יבצר כל דבר, עוד צריך לדעת למה הוצרך לומר תיבת **עמך** ולא הספיק במאמר האלה, עוד צריך לדעת תשובת בלעם שאמר בלק בן צפור וגו' וכי שאלתו יתברך היתה מי שלחם שאלתו היתה מי הם, ורז''ל הרגישו בדקדוק זה ואמרו (ילקוט) וזה לשונם מי האנשים וגו' אמר אותו רשע איני יודע בהם אלא בלק בן צפור שלח אלי עד כאן, פירוש מתוך הדברים שאמר בלק וגו' שלח וגו' מובן שנתכוון לומר איני יודע וגו' אלא בלק שלח וגו'. עוד צריך לדעת למה הוצרך לומר לו מלך מואב ולא הספיק בזכרון שמו, ונראה שכוונת מאמר ה' היא על פי מה שפירשנו בפסוק לינו פה שילינו עמו בחדרו המיוחד לו, לזה בא מאמרו יתברך ואמר לו **מי** וגו' לשון השפלה על דרך אומרו (שמות ג) מי אנכי וגו', כמו כן אומרו **מי האנשים האלה** שהכנסת אותם למקום זה עמך בחדר המיוחד לך לדבר עמך מלאך האלהים, כי יקפיד ה' על כבוד בלעם בערך האומות כיון שהוא נביא עליהם, וכמו שמצינו (מד''ר פ''כ) שהרג את האתון משום כבודו של בלעם, ועיין בפסוק שאחר זה ויאמר אלהים, והבין בלעם דבריו ואמר טעם שעשה להם כבוד זה הוא לפי שהם שלוחי מלך, והוא אומרו **בלק בן צפור** פירוש הידוע לנסיך מרין ועוד לו שהוא **מלך למואב שלח אלי** פירוש האנשים האלה ובשביל כבוד המלכות עשיתי אותם עמי, ובזה נתיישבו כל הדקדוקים:
@780 **עוד** ירצה באומרו **מלך מואב** כי אומה זו לא ניתנה לישראל, ונתחכם במאמר זה כדי שיתרצה ה' לשולחו ולא יעכב על ידו, ולזה לא יעכב על ידו בהליכתו עם שלוחיו:
@782 **הנה העם וגו'**. צריך לדעת למה שינה מדברי בלק כי בלק אמר **הנה עם יצא** והוא אמר **הנה העס היוצא**, ובלק אמר הנה **כסה** והוא אמר **ויכס**, בלק אמר **ועתה** והוא אמר **עתה**, בלק אמר **ארה** והוא אמר **קבה**, בלק אמר **נכה בו** והוא אמר **להלחם בו**, ויתבאר על פי דבריהם ז''ל (מ''ר כאן) שאמרו שבלעם טעה בדעתו כי יש דבר נעלם מה' ח''ו וטעה ממאמר מי האנשים וגו', והגם שפירשנו בו דרך אחר ע' פנים לתורה, וכיון שעינו הטעתו בזה חשב לשנות דברי בלק לפי שנשמע מהם שנאתו של בלעם וכמו שפירשתי במאמר הנה עם יצא, וחש בלעם להיות בעיני ה' שהוא שונא לישראל כי כבר נתפרסם לכל כי עם בני ישראל הם אהובי המקום ומעשה מצרים יוכיח, לזה שינה ואמר **הנה העם היוצא ממצרים** כידוע כי יציאת מצרים מפורסמת לכל העולם היתה, ולשון זה אין נשמע בו מה שפירש במאמר הנה עם יצא שזה יגיד אויבות בלעם, גם אמר **ויכם** וגו' ולא אמר הנה כסה מהטעם עצמו להסתיר הדברים הנשמע מהם היותו שונא כנזכר, לזה לא אמר הנה שיורה הודעת הפך מה שהיה ברצונם וידיעתם בישראל מעצתו כמו שפירשתי, ואומרו **ויכס** פירוש שמודיעו טעם הפחד שבא לו ממנו כי רב הוא:
@782 **ואומרו עתה לכה קבה** פירוש נתכוון לבא בטענה שהדין עם בלק בדבר זה שהגם שהקב''ה נתן לישראל עמון ומואב עדיין לא הגיע זמן הנתינה והדין עמו להלחם בו ולגרשו, והוא אומרו **עתה** פירוש בזמן זה קבה לי להלחם בו לגרשו מעלי, וכפי זה יש טעם בשינוי תיבת עתה שאם היה אומר ועתה יהיה נשמע שהוא המשך מה שקדם לו והוא נתכוון לטענת הזמן שיכול הוא להלחם עמו בו, גם שינוי קבה כי אין כוונתו של בלק שיארר העם סתם שאז ימשך הרע לעם בין בערך מואב בין בערך האומות אלא יפרש בפירוש בלעם שאינו מאררו אלא בערך מלחמת מואב שיהיו ישראל מוכנעים וכו' לפני המואבים, לזה דקדק לומר **קבה לי** פירוש שיפרש הקללה שהיא לערך מואב, גם שינה במאמרו להלחם בו במקום נכה בו לומר שאין חפץ לעשות לו רעה אלא להתגרה עמו במלחמה למנעו מארצו, גם שינה ואמר **וגרשתיו** ובלק אמר **מן הארץ**, אולי בלק נתכוון לגרשו מן [הארץ] הידועה אשר נתן ה' להם כי כשיכניעו ייראו מעלות אל הארץ, ובלעם לחושבו להמתיק ולהטעים דברי בלק כי אינו מבקש אלא הנאת עצמו ובטענה הנשמעת ואינו מאויבי ישראל לזה השמיט תיבת מן הארץ ואמר וגרשתיו פירוש שיגרשנו מעליו:
@783 **ויאמר אלהים אל בלעם**. צריך לדעת למה הוצרך לומר **אל בלעם** ולא הספיק באומרו ויאמר לו. עוד למה הוצרך לומר **לא תלך לא תאור**. עוד למה הוצרך לומר לו הטעם **כי ברוך הוא** ורז''ל אמרו (מ''ר כאן) וזה לשונם אמר לו אקללם במקומי אמר לו לא תאור אמר לו אם כן אברכם אמר לו כי ברוך הוא עד כאן, ונראה לפרש הכתוב לפי מה שפירשתי במאמר מי האנשים וגו' שנתכוון לומר לו למה החשיבם להכניסם עמו בחדרו והשיבו כי בלק וגו', על זה הדרך כי משיבו ה' על ראשון ראשון, למה שהשיב בלק בן צפור וגו' שלח אלי והם שלוחי מלך לזה בא מאמרו יתברך לא תלך עמהם פירוש אינם ראויים ללכת הוא עמהם לפי ערך מעלתו, והודיעו כי בלק זלזל בכבודו ולא שלח לו שרים רבים ונכבדים, והוא מה שנתכוון במאמר ראשון **מי האנשים** לשון פחיתות לא מצד המשלח אלא מצד המשתלח, והוא בלעם לא הבין הכוונה מתחילה, ותמצא שהבין בלעם הדברים ואמר לשרים מאן ה' לתתי להלוך עמכם ויוסף בלק שלוח שרים רבים ונכבדים:
@783 **וטעם** שהחשיבו ה' ועשה לו כבוד זה, מלבד הטעם שכתבתי למעלה בפסוק מי האנשים וגו', נראה עוד לומר טעם בדבר כי ה' נתן לו שכרו שאמר בתחילת תשובתו לזקני מואב והשיבותי אתכם דבר כאשר ידבר ה' אלי, וידוע כי אין הקב''ה מקפח שכר כל בריה ואפילו של אומות העולם, וצא ולמד (סנהדרין צו.) מה שילם הקב''ה לנבוכדנצר על פסיעותיו וכו', וגם כאן שלם לו שכרו וכבדו ואמר לו לא תלך עמהם, ועל פי הדברים יתיישב על נכון מה שדקדקנו אומרו ויאמר ה' **אל בלעם** פירוש מאמר שנוגע לבלעם לכבודו לא תלך עמהם שאין זה כבודך הגם שהיו באים לקרוא לך על דבר שיש לך רשות לעשותו, ולזה דקדק לומר **עמהם**, וכנגד עיקר השליחות אמר לא תאור את העם, ואמר **לא תאור** ולא לקח לשון עצמו שאמר בלעם קבה לי, להודיעו כי ידע גם לשון השליחות ששלח בלק ולשון ארה אמר ועקצו לבלעם ברמז זה שידע ששינה בלשונו, ואמר **כי ברוך הוא** שלא יבין ששני המאמרים שאמר ה' אליו לא תלך ולא תאור טעם אחד להם והוא משום כבודו של בלעם כמו שדייקנו מאומרו אל בלעם ומאומרו תיבת עמהם וכפי זה כשיהיו שרים רבים ונכבדים יעשה רצון בלק וילך ויאור, לזה אמר **כי ברוך** פירוש זה הוא טעם מאמר לא תאר, ולענין ההליכה עמהם הוא שישנו לטעם הקפדת כבודו של בלעם:
@783 **עוד** נראה לפרש הכתוב על זה הדרך לפי שידע ה' כי בלעם חפץ רשע הוא ולבסוף ילך כמו שכן היה שהסכים ה' ושלחו כאשר אבאר הטעם במקומו בעזרת ה', לזה אמר לו ה' **לא תלך עמהם** פירוש עמהם שהחליט לו ההליכה, ואם היה אומר לו לא תלך אין עוד מציאות לחזור ולומר לו קום לך, ודקדק לומר **אל בלעם** נתכוין לתת טעם הדבר, בשביל מחשבת בלעם שרצה לילך לזה הוא שלא החליט לו ההליכה ודקדק לומר עמהם, ואומרו **לא תאור** וגו' **כי ברוך הוא** נתכוין בזה להשיב על מה שדקדק בלעם בדבריו ואמר עתה לכה קבה וגו' כפי מה שפירשתי שנתכוון לומר שטענת מואב טענה שעדיין לא הגיע זמן זכייתם במואב עתה, לזה אמר **לא תאור** וגו', ואם תאמר והלא לא הגיע זמן זכייתם במואב, כי ברוך הוא אין ברוך אלא צדיק כי הצדקות הוא מקור הברכות, והכוונה בזה שאל יחשדם ברשע כי ודאי שלא יכנסו בגדר שעדיין לא הגיעם, ובחר לכנות הצדיק לברוך שנתכוון לכלול גם כן מה שפירשנו בדרך הראשון:
@784 **ויקם בלעם בבקר**. אולי לפי שהיתה בשורה רעה להם לא רצה לגלות להם בלילה לפי מה שאמרנו שהיו במלונו עצמה והמתין עד הבקר, או ירצה שלא קם מתרדמתו עד הבקר, והוא אומרו **ויקם בלעם בבקר** ולא קודם, או אפשר שידבר הכתוב בגנות בלעם ששלחם מהר כדי שימהר לשלוח אחרים נכבדים. או להודיע צרות עינו שמהר לשלחם קודם הגעת זמן האוכל הפך מנדיבות אבי הנערה פלגש בגבעה (שופטים יט) שאמר לחתנו שעמד ללכת בבקר סעד לבך פת לחם ואחר תלכו, כי זה הרשע הוא מקור הצרות עין וקם בבקר לשלחם ואמר להם שילכו לארצם כי חש שיתעכבו בעיר וסעודתם עליו:
@784 **לכו וגו' כי מאן ה' וגו'**. הכחיד חצי דבר ולא אמר להם אלא מאמר ראשון שאמר לו ה' **לא תלך עמהם** לצד פחיתותם ולא אמר להם מאמר **לא תאור** וגו' שבזה חזר בלק ושלח רבים ונכבדים, ואולי שדן הרשע מדברי ה' שנתן הטעם כי ברוך הוא שבא לדייק שבזמן שאינו ברוך יכול לאוררו, ולזה לא החליט להם הדבר עד שישלח הראוים ללכת עמהם אולי יהיה זמן אז שלא יהיה בו ברוך:
@785 **מאן בלעם הלוך עמנו**. חשדוהו בשקרן ותלו הדבר בו שהוא לא נתמלאו עיניו בשיעור כבוד זה, ואולי כי לפי שאמר להם שישיבם דבר תכף שידבר ה' אליו בלילה ולא עשה כן עד הבקר אמרו אין זה כי אם דברי עצמו, או אפשר כי מוחזק היה אשר פיו דבר שוא וימינו ימין וגו':
@786 **ויוסף עוד**. פירוש ששלח את הראשונים והוסיף עליהם אחרים, והוא מה שדקדק גם כן במאמר **מאלה** ולא אמר מהם לומר כי עודם מן המובא בשליחות עם הנוספים עליהם, ונתכוון בזה שלא יכחיש את דיבורו הראשון שתלה הדבר בפחיתות השלוחים שהם יוכיחוהו על פניו:
@786 **עוד** נתכוון במאמר **ויוסף** שהוסיף על מנין ראשון שאם הראשונים היו ג' שלח במנין שני ד' ויותר, וזה אינו נשמע אם היה אומר וישלח עוד שרים רבים וגו', שהייתי אומר שאומר רבים לבל תחשוב ששלח מועטים ממנין ראשון, ואומרו **מאלה** חוזר לתיבת נכבדים לזה אמר ויוסף:
@787 **אל נא תמנע וגו'**. פירוש לפי מה שאמרו שלוחים הראשונים כי דעת עצמו הוא מניעת הליכתו עמהם לזה אמרו לו שיתרצה בשיעור כבוד זה ולא ימנע וגו', והוא לפי שחסר לו ידיעת החשד שחשדוהו שהם דברי עצמו ולא דברי ה' חשב שנתכוון לומר לו שלא יחוש לדברי ה' וילך בלא רצונו, לזה השיב **אם יתן לי בלק** וגו' לא אוכל פירוש הגם שאני אתרצה לעשות כי תכונת רשע היתה לו ועבד מורד באדונו אבל אינו בעל בחירה ורצון בדבר זה:
@790 **ועתה שבו נא וגו'**. אמר לשון בקשה, שחש לבל יעשו כמעשה זקני מדין בפעם אחרת שאמרו ז''ל שחזרו למקומם ולא לנו עמו, (במד''ר פ''כ) ולפי שהאנשים הם רבים ונכבדים היה ירא שילכו להם כשישמעו שבו פה ולא יחליט הליכתו עמהם:
@791 **אם לקרוא לך באו האנשים וגו'**. צריך לדעת למה אמר דבריו בלשון ספק הממנו יפלא כל דבר. עוד למה הסכים ה' על יד הרשע ללכת לקלל שונאיהם של ישראל. עוד צריך לדעת למה חזר בו ה' מדעת ראשונה שעכב על ידו מתחלה מה סבר ולבסוף מה סבר. ונראה כי במה שלפנינו היו לפני ה' ב' דרכים ובכל אחד מהם יש בו מיחוש בלתי הגון, הא' אם יסכים ה' על הליכתו יחשבו העמים ההם שרשותו ביד עצמו ולא ידעו ששלשלת הכלב ביד בעליו ואינו יכול עשות ככל אשר יחפוץ, וה' רצה שיוודע לעיני העמים שאין בלעם ברשות עצמו להרע למי שאין ה' חפץ ברעתו, ואם לא יניחהו ללכת יכנס במיחוש אחר כי יאמר בלעם שהוא ירא ממנו ח''ו לשולחו ולזה מונעו מלכת, אשר על כן נתחכם ה' וסלק ב' המיחושים בדרך נכון, בתחלה אמר אליו **לא תלך** וגו' שבזה הראה לעמים כי אין הכלב רע ברשות עצמו, גם נתחכם ה' בזה לשלם לו שכרו שהקדים לומר לשלוחי בלק כי אינו ברשות עצמו, ומה שכר נתן לו שידע ה' את אשר תקראנה אותו בהליכה זו שמלבד שלא תהיה לו תועלת דכתיב (כד יא) אמרתי כבד אכבדך והנה מנעך ה' מכבוד מלבד זה עוד לו שתסובבהו הליכה זו לנפול בחרב דכתיב (לא ח) ואת בלעם וגו' הרגו בחרב כשהלך לקבל שכרו על עצתו שנתן להם בהליכתו, לזה מנעו ה' מרדת שחת בשכר דבריו ואמר לו לא תלך עמהם כי אין הקב''ה מקפח שכר כל בריה, וזה נוסף על גדר הכבוד שעשה לו בהדרגת השרים כמו שכתבנו למעלה:
@791 **ובשליחות** שניה ששלח בלק באנו לתיקון מיחוש הב' שיאמרו שאין ה' יכול ח''ו למונעו מהרע לישראל בהליכתו ותכנס טעות זה בלב בלעם ויחשוב מחשבות כי לא ישלוט ה' בו שם למונעו מעשות חפצו כי כבר נבחן כי הוא עביט של מי רגלים, לזה אמר אליו **קום לך אתם** ובכל המקום ידי מושלות עליך, ולא אמר לו בהחלט קום לך אלא בדרך זה **אם לקרא לך** וגו' פירוש אם קריאת האנשים יש לך בה הנאה כאן רמזו שאין לו הנאה בהליכה זו, ותלה לו הדבר אם הליכה זו לטובתו כדי שישתדל בקסמיו לדעת תכליתו ומזה ידע את אשר יקראהו ויחדל, ואין כוונת מאמר אם לקרא ספק לפניו אלא תנאי הדבר אם יש לו בו הנאה וכו', ובזה הוסר המיחוש שיאמר בלעם שה' ירא ח''ו ממנו לשולחו שהרי שלחו, גם רמזו אולי ישב ולא ימשך מה שנמשך מהרעה לישראל, גם בזה שלם לו תשלום שכרו כמו שכתבנו ומנעו מנפול בחרב אם נפשו לא תאוה רעה, והוא נפשו נפש רשע ולא שת לבו למה שהעירו ה', ואולי שלזה חרה אפו כשראהו ה' הולך ולא הרגיש במה שהעירו זה יגיד שיצטדק אצלו בודאי שיש לו הנאה וזה אינו יכול להיות אלא אם יחשוב שיעלה בידו הדבר אשר שלחו לו בשבילו, לזה חרה אפו של אלהי ישראל בו, ובזה נתיישבו כל הדקדוקים, ובסמוך יתיישב עוד טעם ויחר אף וגו':
@793 **ויחר אף וגו' כי הולך הוא**. דקדק לומר **הוא**, לומר טעם שחרה אף ה' בו שלא אמר בבקר לשרי בלק שה' נתן לו רשות ללכת אלא השכים בבוקר ויחבוש וגו' וילך עם שרי וגו' שזה יגיד שהליכתו מרצונו ולא הוצרך לרשיון עליון, והוא אומרו **כי הולך הוא** פירוש הוא הולך ברצונו באין רשיון ה' לזה חרה אפו בו. עוד נראה על פי דבריהם ז''ל (זוח''א קסט:) שאמרו בפסוק וילך שפי שמדרך של המשרה עליו כוחות הטומאה להתבודד יחיד, וכאן כשראה ה' שהולך הוא פירוש הוא לבדו היה נפרד משרי בלק ועושה מעשהו זה יגיד שמכין צעדו לעשות כחפצו הארורה, והגם שהיו עמו ב' נעריו אין מעכבין עליו ההתבודדות לצד שהם רגילים עמו ויעשה מעשהו לפניהם, וידע ה' דרכו הרעה וחרה אפו בו. עוד ירצה באומרו **הולך הוא** שידע ה' שרשע זה גבר בו החפץ ללכת מעצמו הגם שלא היה בלק שולח אחריו הוא הולך לרצונו, ובזה גילה עוצם שנאתו לעם ה' ולזה חרה אפו יתברך בו:
@793 **ושני נעריו עמו**. צריך לדעת לאיזה ענין הודיע שהיו עמו ב' נעריו, ורז''ל (תנחומא) אמרו להודיע דרך ארץ וכו', ועדיין קשה למה לא הודיע כן אלא אחר שהזכיר חרון אפו יתברך ויציאת מלאך לשטן לו, ויתבאר על פי דבריהם ז''ל (ברכות מג:) כי לג' אין המזיק נראה להם ואין צריך לומר שלא יזיק, וכאן לפי שיצא שטן לבלעם מלאך המזיקו מודיע הכתוב טעם שלא הזיק גם שלא נגלה אליו לפי שהיה הוא ושני נעריו עמו הרי ג':
@798 **ותרא האתון וגו'**. צריך לדעת כוונת ה' בענין זה שנתגלה המלאך להאתון, גם בהעמדת המלאך ג' פעמים בג' מקומות, ובלחיצת רגלי בלעם, וברביצתה, גם בפתיחת פה האתון, וכל מעשה האמור בענין הוא ענין סתום. ונראה כי כל כוונת ה' בענין זה לא היתה אלא להשפיל גאותו של בזוי זה, לפי שקדם ונהג גבהות לפני ה' כמו שכתבנו למעלה שלא אמר לשרים כי הוא הולך ברשות ה' אלא כאדם העומד ברשות עצמו, לזה בקש לו ה' השפלה שאין למטה ממנה ושחק בו בקלון מכוער ומשונה, ודבר ידוע הוא כי הרכבה החיונית אשר הרכיב ה' בבעלי חיים בלתי מדברים היא משונה מהרכבה החיונית שפעל ה' ועשה בבעלי חיים המדברים, ולזה כשרצה ה' שתפתח האתון את פיה לדבר כבעלי חיים המדברים הוצרך להרכיב בה הרכבה החיונית של בעלי חיים המדברים, והוא מה שפעל ה' במעשה העמדת המלאך בג' מקומות ובראיית האתון המלאך ג' פעמים, כי כח המדבר צריך ג' הכנות קודמות לו והם כח הצומח שהוא בכל הנבראים, וכח המניע, ואחר כך כח המדבר, לזה עמד פעם ראשונה וראתה האתון אותו ופעל בה בכח ראות הרוחני כח אחד ממין הרכבת כח הצומח שבו יתקבל כח המדבר, ועמד פעם ב' וראתה אותו ופעל בה כח המניע המתקבל בו כח המדבר, ובפעם ג' פעל בה כח המדבר, ואז פתח ה' את פיה ודברה דברי הבנה בדרך שואל ומשיב והכלימה את בלעם בדרך ביזוי בפני נעריו וכו', וביזוי שיהיה בדרך זה יש לו קול להיותו דבר תמוה בב' אופנים, אופן א' שתדבד הבהמה, והב' שאדם גדול כבלעם היתה לו אתונו לאשה שוכבת חיקו:
@798 **ונשאר** לדעת למה עמד המלאך בג' מקומות שונות ויכול היה להתראות לה ג' פעמים במקום אחד, ואולי כי עשה לו כנגד ג' דברים שעשה ברשעו, א' שה' אמר אליו פעם אחת **לא תלך לא תאור** והוא לא אמר לשרים מאמר לא תאור וגו' שזה היה סיבה לשלוח אחרים, וכנגד זה נצב פעם אחת בדרך ונטתה האתון מהדרך כשם שהוא נטה מהדרך אשר אמר ה' אליו כנזכר. ב' שה' אמר אליו אם **לקרא לך** וגו' שתנאי הוא הדבר עד שידע בודאי שיש לו הנאה בדבר ובזה רמזו שאין לו הנאה ולא הרגיש, וכנגד זה עמד המלאך במשעול הכרמים ותלחץ האתון רגליו לאמר שלחצו ה' בנועם דבריו להשכיל להטיב לבל ילך. הג' שה' אמר אליו בעת רשיון ההליכה **אך את הדבר** וגו' ודיבור זה הוא מדויק אין לנטות במשמעותו אנה ואנה והוא הרשע הלך בעצה אחרת כמו שדייקנו ממאמר הולך הוא גם מאומרו והוא רוכב וגו' וב' נעריו וגו', והוא מה שעמד המלאך במקום צר אשר אין דרך וגו' ורבצה האתון תחתיו שזה ירמוז לומר שאין ה' חפץ בדבר שהוא חפץ ללכת עליו:
@803 **ויאמר אליו וגו' על מה וגו' הנה וגו'**. צריך לדעת מה טענה היא זאת על מה וגו' על עסקיה רעים, עוד מה טענה במאמר הנה אנכי כיון שלא היה יודע, כמו שהעיד הכתוב ויגל ה' את עיני בלעם הא למדת שסתומים היו עד עתה, ואולי שנתכוון ה' להשפיל גאונו כדי שיודה בפיו ויאמר כי האתון ראתה המלאך ג' פעמים והוא לא ראה, ומזה יתגלה גם כן הפלגת מיעוט השגתו בנסתרות, לזה אמר לו על מה וגמר אומר **הנה אנכי** וגו' **ותראני האתון** כאן תחב חץ בלבו שנתחייב לומר בפיו כי עינים לו ולא יראה כמו שראתה האתון כאומרו לא ידעתי כי אתה נצב לקראתי, וזה היה תכלית הכוונה בדבר המלאך:
@803 **עוד** נתכוון בזה להעירו מה שגרמה לו הליכה זו על דרך אומרם ז''ל (סנהדרין קו.) בלעם מתחילה נזקק לרוח הקודש וכשנזדווג לבלק נסתלקה ממנו ונקרא קוסם, והוא מה שהעירו במה שלא ידע המלאך העומד לפניו מה שלא היה כן קודם לכן שהיה רואה ברוח הקודש, וטעם יציאת המלאך לנגדו, הודיעו במאמר **כי ירט הדרך** וגו', פירוש ירט הדרך כמו שפירוש רמב''ן, ופירוש הדרך דרכו של בלעם שהיה הולך עליו:
@804 **כי עתה גם אתכה וגו'**. אומרו **עתה**, לדבריהם ז''ל (מ''ר כאן) שאמרו שנהרגה האתון ולזה דקדק לומר **גם אתכה** ולא אמר גם הרגתי אתכה ידויק על נכון תיבת עתה, כי לא יוצדק לומר גם אתכה אלא עתה שכבר נהרגה האתון מה שאין כן קודם כי קודם לא היתה מתה האתון כאומרו ואותה החייתי, ואומרו **החייתי** שמשמעותו הוא פועל חדש, להעירך שעתה נהרגת, עוד לומר שהיה עושה לה מעשה נסים שיפגע המלאך ברוכב ונרכב ויהרוג רוכב בשמירת נרכב, ובדרך זה יוצדק ליאמר לשון זה החייתי:
@805 **ויאמר בלעם וגו' חטאתי כי לא וגו'**. אומרו **חטאתי** כנגד מה שרמזו במאמר ירט הדרך וגו', וכנגד אומרו למה הכית וגו' אמר כי לא ידעתי וגו', ואומרו **ועתה** עשה תשובה למה שחשב עשות, וכנגד ההליכה אמר אם רע בעיניך אשובה, ואמר לי נתנוצצה בו נבואה שיש לו יתרון טוב בחזרתו:
@806 **ויאמר מלאך וגו' לך עם האנשים**. צריך לדעת למה דקדק לומר עם האנשים, ורז''ל העירו בזה ואמרו (מ''ר כאן) חלקך עמהם וסופך ליאבד מן העולם, וזה דרך דרש אבל צריך לדעת משמעות הדברים כפי פשטן, עוד צריך לדעת למה לא אמר לו שוב והיה יותר נכון. אכן כוונת הדברים הוא שנתן לו טעם שהוא מסכים על ידו ללכת הוא בשביל האנשים שבאו אחריו ללכת עמהם, שאם לא יסכים על ידו ללכת יחשבו מחשבות כי יחוש ה' לבלעם לעשות דבר הפך מה שיחפוץ ה' עשות ויש חילול ה' בדבר ח''ו, ולפי מה שפירשתי בפסוק כי הולך הוא שהיה הולך יחידי אפשר שרמז לו המלאך שילך עם האנשים ולא שפי, והכוונה לבטל ממנו הכנת הרע אשר היה חושב לעשות בקסמיו, וכן עשה דכתיב וילך בלעם עם שרי בלק:
@806 **ואפס את הדבר וגו' אותו תדבר וגו'**. כאן התנה עליו תנאי אחר מה שלא אמר לו ברשיון ראשון, והוא שברשיון ראשון אסר עליו המעשה דכתיב (לעיל כ') אך את הדבר וגו' אותו תעשה ומזה חשב הרשע מחשבות להרע כי כחו היה במעשה ובדבור, במעשה בכשפיו וקסמיו, גם בעינו הרעה וכמאמרם ז''ל (זוח''ג רב:) בפסוק וישא עיניו וירא את ישראל וגו' שרצה להביט בהם בעין הרע עד שבא הקב''ה וכיסה אותם בצלו דכתיב (כד ב) ותהי עליו רוח ה', ודרשו ז''ל (זוח''א ריא.) עליו על ישראל שלא תשלוט בהם עינו הרעה, ובדיבור לקללם, וכוונת עליון במאמר אותו תעשה נתכוון לאסור עליו גם הדיבור אשר יצא ממנו מעשה, ולא כן הבין הוא לצד תכונתו הרעה, לזה בא מאמר ה' פעם ב' וסתר לועו ואמר לו בפירוש הדיבור דכתיב אותו תדבר, ובזה כלל איסור עצה רעה כנגד ישראל אשר לא כן עשה הרשע בכל פרטי האזהרה, ועיין מאמר רז''ל (מ''ר כאן) בפסוק וישם ה' דבר בפי בלעם שדרשו שנתן בפיו טס של ברזל כשהיה רוצה לדבר רעה היה חונקו, גם מצינו לו שדבר עצה רעה שגרם בה שנפלו מישראל כ''ד אלף, גם בפרט המעשה שנטה עליו לבל יביט בהם בעינו הרעה מצינו שעבר על זה כנזכר לולי ה' שהיה לנו, ומעתה מצאתי טעם למעשה ישראל שהרגוהו כי כפי הדין נתחייב מיתה כי ה' הזהירו בין על המעשה בין על הדיבור בפירוש כנזכר ואזהרת בני נח זו היא מיתתן (סנהדרין נז.):
@807 **ויצא לקראתו אל עיר מואב**. צריך לדעת למה הוצרך לפרט המקום שיצא לקראתו. ונראה כי בא הכתוב לספר פחיתות בלעם בעיני בלק, שהגם ששמע בביאתו לא יצא להקביל פניו כדרך הקבלת פני הגדולים שיוצאים חוץ למחוז אלא דוקא בתוך העיר, והוא אומרו **ויצא לקראתו אל עיר מואב אשר על גבול** וגו', ואומרו **בקצה הגבול** אולי שנתכוון גם כן לומר שאפילו יציאה זו מועטת לא היתה לכבודו אלא לסיבה, כאומרם ז''ל (במד''ר פ''כ) וזה לשונם מה ראה בלק לקדמו לגבולין אמר לו גבולין הללו נקבעו מימי נח שלא תכנס אומה לגבול חברתה והיה מראה לו איך פרצו ועברו גבולות סיחון ועוג עד כאן, וזולת טעם זה לא היה יוצא ממקומו:
@809 **עתה היכול אוכל דבר מאומה**. דקדק לומר **עתה** פירוש אחר דיבור ב' שבא אליו מהמלאך בדרך שנאסר וכפל לו אפילו דיבור כמו שפירשתי בפסוק ואפם את הדבר, וכפל לומר **היכול אוכל** כאן גילה רשעתו שמניעתו היא בב' דרכים, א' מכח האזהרה, והב' שאין הבחירה ביד עצמו בדבר זה, הא למדת שאם לא היתה לו אלא האזהרה והיה בעל בחירה ורצון היה עושה:
@810 **וילך בלעם וגו'**. נתכוין לומר שלא נהג בו כבוד אלא שקדם והלך בלק והוא הלך אחריו, ולזה לא אמר וילכו בלק ובלעם, ואפשר כי לפי ששמע בלק מאמר בלעם שאינו יכול לעשות דבר פנה אליו עורף והלך לו אלא שבלעם נטפל לו מאחוריו והלך עמו, והוא אומרו **וילך בלעם עם בלק**:
@811 **ויזבח בלק וגו'**. נתכוין הכתוב בזה גם להודיע חרפת אדם זה, שלא החשיבו בלק לסעוד עמו אפילו סעודה ראשונה אלא שלח אליו ולשרים וגו', ואולי שדקדק לומר **ולשרים אשר אתו** שלא שלח אלא דבר המספיק לבלעם ולשרים הידועים שהיו אתו ושלל נעריו, וזה יגיד צרות עין בלק בכבוד בלעם. או לפי שחשב בלק כי בלעם יקח כל השלוח לו ויחזק בו כי הוא לו לבדו ולא יתן לשרים וכו' כי היה ידוע שהוא רע עין, לזה כששלח אמר בפירוש כי לא לו לבדו יהיה הטבח השלוח אלא לו ולשרים, ואמר **אשר אתו** אפשר שעשה לפי חשבון השרים שעמו פרט למזדמן שאם יזדמנו שרים אחרים עמו אין מנת בשר להם, ולזה תמצא שאמרו רז''ל (במד''ר פ''כ) שהקפיד בלעם על מיעוט הבשר ואמר למחר אני שולח מארה בנכסיו של זה ולמחר אמר לו בנה לי וגו' ז' פרים וז' אילים:
@812 **ויהי בבקר ויקח בלק וגו' וירא וגו'**. אומרו **ויהי** לשון צער, אולי שעשה מריבה בלעם עם בלק וצערו בדברים על מיעוט הבשר ששלח כמו שכתבתי, ואומרו **ויקח בלק** לקחו בדברים פירוש שריצהו על הדבר, עוד ירצה לפי שהיה בלעם חיגר ברגלו וכפי טבעיות הרגיל בחושי הרכבת בני אדם אדם כזה לא יתכונן בו רגל הצולע ללכת בבקר ומה גם לעלות במות, ואולי כי לזה נתכוון הכתוב בתיבת **ויהי** אוי לו לבלעם וטעם הצער הוא בשביל היות הדבר בבקר, ולפי שלא היה יכול ללכת תכף ומיד היה בלק לוקח אותו בידו וסמכו להעלותו, והוא אומרו ויקח בלק את בלעם ויעלהו במות וגו':
@812 **עוד** נתכוון באומרו **בבקר** להודיעך שנדדה שינת עינו של בלק כי מדרך המלכים להיות על מטותיהן עד ג' שעות כאומרם ז''ל (ברכות ט:) וזה בהיות הבקר עמד ולקח בלעם ויעלהו במות וגו'. עוד טעם **בבקר** על דרך מה שאמרו במסכת ע''ז דף ד' וזה לשונם אימת קא רתח אמר אביי בתלת שעתי קמייתא עד כאן, לזה אמר ויהי בבקר, ודקדק לומר **ויהי** לשון צער פירוש זמן שה' מתכעס על עולמו שהוא בבקר לקח בלעם שהיה בקי בכיוון הרגע. עוד ירצה על דרך אומרם ז''ל (במד''ר פ''כ) וזה לשונם במות בעל זה פעור עד כאן לשונם, וידוע הוא כי פעור עבודתו היא התרזת זבל בפניו, וזה לשון דבריהם ז''ל (סנהדרין סד.) במה עובדים עבודה זרה של פעור אוכלין תרדין ושותין שכר ומתריזין בפניה עד כאן, הרי שעבודת פעור היא בהתרזת המיאוס, ולטעם זה רצה בלק להעלות בלעם לפעור שהיא במות בעל בזמן העבודה שהיא זמן ההפנאה שאדם עושה צרכיו, והוא אומרו **בבקר ויעלהו במות בעל**, ואולי כי בלעם לא היה עובד עבודה זרה זו ולקחו בדברים לעובדה. עוד נראה טעם **בבקר** על פי דבריהם ז''ל (זוהר פ' זו) שאמרו שכשפיו של בלק היו בצפור, וכמו שרמזנו במאמר בן צפור, לזה בחר בלק לעמוד בבקר שאז יצפצף הצפור כידוע ויעלה בידם כשפיו וקסמיו כי זה הוא זמנו:
@812 **ובזה** נראה לתת טעם למה שיש לתמוה בענין במה שאמר הכתוב וירא משם קצה העם והלא אמרו רז''ל (תענית ט.) שהעננים היו מכסים על ישראל ולא היו נראים לעין וכשמת אהרן ונסתלקו העננים נגלו לעין וידע הכנעני מושבם ונלחם עמם וחזרו אחר כך בזכותו של משה כאומרם ז''ל (שם), אם כן ישראל היו מכוסים בענן ואיך יאמר הכתוב וירא משם קצה העם שאדרבה היה צריך ה' להוסיף שמירה על שמירתן לבל תכנם בהם עין רעה של בלעם, אלא ודאי מה שראו קצה העם הוא על ידי כשפים שהיו עושים בצפור הידוע והוא היה מגלה אותם, ויש כח במכשפות לעשות כן כאומרם ז''ל (סנהדדין סז:) למה נקראו מכשפות וכו', והם גילו המכוסה בענן, והודיע הכתוב שלא גילו להם אלא קצה העם לא פינת הצדיקים וגדוליהם:
@813 **בנה לי**. פירוש למה שאני מכוין וחושב בטעם המעשה, שהרשע לא היה רוצה לגלות ידיעתו ותחבולותיו לבלק כי נכרתה האמונה מהם, ועשה בלק כמצותו של בלעם דכתיב ויעש בלק כאשר דבר בלעם פירוש שאמר לו לעשות מעשה למה שיכוין בלעם בדבר, גם נתכוון במאמר **כאשר** פירוש תכף שגמר הדבר ולא שהה:
@814 **ויעל וגו' פר וגו'**. נראה שחוזר לבלעם שבסמוך כי הוא שהעלה הקרבנות ולא בלק, כי הוא לא אמר לו אלא והכן לי בזה שבעה פרים וגו', וצריך לדעת למה עשה בלעם דבר זה בלתי רשיון מה' כי הוא צוה לו אך את הדבר וגו' אותו תעשה, ויש מהמפרשים שרצו לומר כי כן צוה לו המלך, ונסתייעו ממאמר את שבעת המזבחות ערכתי וגו' שהמשמעות יגיד שמשיבו שעשה כאשר אמר לו ה' עד כאן. ודברים אלו אין שכלי הולמם, כי בודאי שלא יחפוץ ה' בזבח רשעים ומה גם שתכלית כוונת המקריבים היא להרע לעם קדושו, ומצאתי שאמרו רז''ל במדרש (רבה כאן) הפך זה, גם בגמרא במסכת סוטה (מז.) אמרו וזה לשונם אמר רב יהודה אמר רב לעולם יעסוק אדם בתורה וכו' אפילו שלא לשמה וכו' שבשכר מ''ב קרבנות שהקריב וכו' עד כאן, ואם הקרבתם היתה במצות ה' מי יאמר שלא היתה הכוונה לקיים מצות המלך ולזה יצתה ממנו רות:
@814 **והנכון** בעיני כי בלעם דן בדעתו שלא נצטווה מה' אלא על המעשה והדברים שיעשה בלעם בהשתדלותו בבחינות וכוחות הטומאה שחוץ ממנו יתברך אבל בהשתדלות אשר ישתדל עמו יתברך כביכול זה לא נאסר לו, ולזה הקריב קרבנותיו לה' שכל מה שיהיה לכבודו יתברך עשה יעשה. ואומרו **את שבעת המזבחות**, בא לראות אם רצה ה' במעשיו או אם הקפיד עליו גם על זה, ונתכוון גם כן להגדיל מעשיו שהראשונים היו בונים מזבח אחד והוא שבעה, ואמר כדרך זה **את שבעת** וגו' כמי שקדם לו הדיבור על זה ולא אמר שבעה מזבחות וגו', וכבר העירו רז''ל (מ''ר כאן) בזה שנתכוון לז' מזבחות שבנו האבות עד כאן, וזה שיעור הכתוב את ז' מזבחות הידועות שבנו האבות אני ערכתי כמותן, והכוונה בזה לא תגדל מעלת עם בני ישראל בשביל האבות הראשונים שבנו ז' מזבח ות:
@817 **וישם ה' דבר בפי וגו'**. מקרא זה כבר קשטוהו ראשונים בפירושם ודרשותם, ומקום הניחו לנו בו. ונראה כי לפי שרצה ה' לגלות עתידות ודברים נפלאים מהטובות אשר יגיעו לישראל, ורצה שיתגלו על ידי בלעם נביא האומות לפרסם מעלת עם קדושו לפני כל האומות (ואמר) [ואשר] תבאנה לישראל מהטובות באחרית הימים וכליון האומות על ידי ישראל לבסוף, וידעו האומות מפי נביאם הדברים ככתבם להרבה תועליות הנמשכות לישראל נגלים ונסתרים, ולפי שאדם זה הוא אדם מובהק בכיעור ותיעוב ושיקוץ לא תנוח עליו הרוח הקדושה המגדת העתידות, גם הדברים מצד עצמן דברי קודש הם ולא יחנו בגוי טמא, לזה נתחכם ה' לעשות תיקון לדבר קדושה לבל תעבור במבוי מטונף ועשה מחיצה בין כח המדבר והדיבור עצמו ובין פי חזיר, והוא מאמר וישם ה' דבר אחד בפי בלעם הציע כח אחד שיכול להתמצע בין שניהם ובזה נעשה פי בלעם גבול בפני עצמו והדבר מפסיק לגבול כח המדבר והדיבור, ואז **כה תדבר** רוח הקודש היא תדבר, ורז''ל בזוהר (ח''ג רי:) אמרו כי תיבת כה תרמוז לבחינה קדושה והמשכיל יבין:
@817 **ואם** תאמר איך תהיה ההבדלה בדבר כזה, צא ולמד אשר יבדיל ה' בין המימות הרבים והעצומים כשיעור מלא נימא (חגיגה טו.). וצא ולמד מבארה של מרים מים תוך מים (שבת לה.) והללו עומדים בפני עצמן והללו בפני עצמן:
@817 **שוב אל בלק**. אמר **שוב** אל בלק חייבו שיאמר הדברים שהוא עתיד לומר לפני בלק להקהות שיניו:
@819 **וישא משלו וגו'**. פירוש כשראה שלא ציוהו ה' שלא לדבר גם לא אמר לו הדברים שיאמר חשב שנתנה לו רשות, ולזה נשא משלו פירוש לומר דבריו שהיה חפץ ונתעקם פיו ולשונו לדבר דברים אחרים, והוא אומרו **ויאמר** פירוש יצתה ממנו אמירה אחרת האמורה בענין. עוד ירצה על זה הדרך שנשא המשל שהיה מוכן אצלו לומר והסיעו ואמר המאמר האמור בענין. עוד ירצה על פי דבריהם ז''ל (מ''ר) שאמרו וזה לשונם מן ארם מן הרמים הייתי והורידני בלק לבאר שחת וכו' עד כאן, ולזה אמר **וישא** פירוש הרים קולו במשל שלו שנעשה למשל ולשנינה שהיה מן הרמים וירד כבודו:
@819 **עוד** יתבאר על פי מה שאמרו ז''ל בענין פרטי הדרגות הנבואה, וכמו שכתבתי קצת מהם בפרשת בהעלתך, (יב ו') כי יש נביא שימעט כחו לקבל דברי נבואה ביושר עד שיהיו בדרך קל שיתלבשו בדברי משלים כפי אשר יוכל שאת, וזה אפילו לנביאי ישראל ומזה נשער לבלעם שצריך משל לנבואתו, לזה אמר וישא משלו, ודקדק לומר **וישא** שהנבואה היא כמשא לרוב ההרגש אשר תעשה ולזה תקרא משא:
@819 **לכה ארה לי יעקב וגו'**. פירוש לפי שיש בישראל ב' הדרגות, גדר הצדיקים, וגדר הבינונים, וכבר כתבנו למעלה בפירוש שליחות בלק שאמר נכה בו ואגרשנו לאחד מהדרכים שנתכוון כנגד הבינונים נכה בו, וכנגד הצדיקים אמר ואגרשנו, כי ידוע היה להם הפלגת מעלת הצדיקים שלא תשלוט בהם כח הטומאה, והוא מה שאמר כאן **ארה לי יעקב** הם הבינונים לשון ארירה, **זועמה ישראל** הם הצדיקים המתכנים ישראל. והזעימה היא למטה מהארירה:
@820 **מה אקוב לא קבה וגו' כי מראש וגו'**. קשה אם ה' קללו לזה מה מקום לקללו בלעם, גם אם זעם בו ה' מה צורך בזעימת בלעם הלא לא קרא לו בלק אלא לקלל למי שאינו מקולל וגו', עוד צריך לדעת מה נתינת טעם במאמר **כי מראש צורים** וגו' למאמר **מה אקוב** וגו'. ולעמוד על כוונת הדברים יש להעיר בעיקר הדבר של האיש המקולל, ממה נפשך אם הוא חייב כפי הדין רעה הבאה עליו באמצעות הקללה על כל פנים לא ינצל ממנה גם כי לא יקולל, ואם הוא כפי משפט אלהים לא עשה דבר שיתחייב עליו ביאת הרע קללתו תשוב על ראש המקלל, בשלמא הברכה לפי שמדה טובה מרובה, גם לעשות ה' רצון ידידיו לברך המתברכים מהם במדת החסד תקובל ברכתו גם למי שאינו ראוי לה כמו מעשיו, מה שאין כן מדה רעה כי לא יריע ה' לאדם חנם חם ושלום:
@820 **אכן** עיקר הדבר הוא לפי שמדתו יתברך להאריך אפו לעוברי רצונו בין לצדיק כשיחטא בין לרשע הגם שירצה לחטוא, ומדה זו היא אחת מי''ג מדות רחמים שנאמרו למשה ונוהגת תמיד זולת בעת **אשר יזעום ה'** דכתיב כי רגע באפו (תהלים ל) אז מתגברים הדינים על הנתבע במשפט באותו זמן ולא תתנהג מדה זו של ארך אפים, וכמו כן כשיקלל אדם את חבירו תסובב הקללה שעונותיו אשר ה' מאריך לו אפו עליהם ימהר ליפרע ממנו, אבל אם אין לו עון לא תועיל קללת המקלל כלום:
@820 **עוד** אשכילך כי כל עושה רשע יפעיל פגם במדה עליונה בענף ההוא שתלויה אותה מצוה שעבר עליה, ולא בכל המדה הוא פוגם אלא בשורש נשמתו, והפגם הוא שתהיה אחיזה לחלק המרוחק לעמוד שם וליהנות ממקור החיים, וחלק זה המרוחק נעוץ סופו בתוך החוטא וראשו יונק ממקום שורש הנפש החוטאת, וזה יהיה כל עוד שלא שב האדם בתשובה או לא נפרע על חטאו, וזה הוא סוד נושא עון שאמרו רז''ל שה' מפרנס הקטיגור הנברא מחטא האדם, וכי הוא זה הנפרע מהאדם עצמו (זוח''ג פ''ג:) כאומרו (ירמיה ב) תיסרך רעתך, וכתיב (ישעי' סד) ותמוגנו ביד וגו', והאיש המקלל יעורר הדין בכח הקללה בעת הזעם למהר להשליט השליט באדם לרע לו:
@820 **עוד** יש לדעת כי חלק הארור יקרא בשם זה קללה וזעימה, וכן קראם הכתוב דכתיב (דברים כ''ח) ישלח ה' וגו' את המארה וגו' ואת המגערת, והם שמות כתות המחבלים, קללה הוא כנגד עבירות חמורות וזעם כנגד עבירות קלות, ולזה כשהיה בלעם רוצה לקלל אומה היה בוחר עת הזעם, ולצד היותם כולם זעומים בשביל מעשיהם הרעים היו דבריו מועילים להם, וחשב בלק כי עם בני ישראל לא יחדל מהם עון וכשפיו יגידו לו כי לא נמלטו מתחלואי הנפש שהוא ענף המרוחק כמו שאמרנו, לזה אמר בלעם **מה אקוב** וגו' פירוש כי בכל ענפי הקדושה שבה נאחזים עם בני ישראל אין בו בשורש העליון שום שליטה מחלק המרוחק שבאמצעותו יעורר הדין עליהם, והנה ב' מדות עליונות שישראל מתיחסים עליהם שם אל ושם הוי''ה ברוך הוא שם אל שכן נקרא יעקב ישראל פירוש ישר אל לשלול אל השורש מקום שהוא בחינת הרע והוא חלק המרוחק, ושם הוי''ה דכתיב (שם לב) כי חלק ה' עמו, והם ב' הדרגות הקדושה שהשיגו ישראל ולזה אמר **מה אקוב לא קבה אל** כי שורש נשמתם שבבחינה זו אין בו רושם מזה חלק הרע כמו שאמרנו למעלה, גם בערך מקום עליון שהם שורשי נשמות הצדיקים שבבחינת שם הוי''ה **לא זעם ה'** פירוש אפילו דקדוקים שה' מדקדק עם הצדיקים לא נמצא שם, ומעתה מה יועילו קללותיו וזעמיו, ותאמר שיחפש בשורש הקודם להם ובענפים הסובבים, לזה בטל טענה זו מטעם שבקש ולא מצא, והוא אומרו **כי מראש צורים אראנו** וגו' פירוש צורים הם האבות כידוע והוא הביט וראה ראש הצורים שהם תרח ואבותיו ולא ראה מקום שממנו יעורר הדינים עליהם:
@820 **ושיעור** הכתוב הוא על זה הדרך כי טעם שאני אומר לא זעם ולא קבה לא שבקשתי בחלק מהם לבד לא כן הוא אלא אני רואה ראש צורים, גם חפש אחר שורש האמהות והוא אומרו ומגבעות אשורנו, ובכל זה לא מצא מקום שיכנס דרך שם, ולהיות שיש להקשות בדבר איך יתכן שלא מצא נגע בראשונים תרח ואבותיו גם בתואל ולבן, לזה אמר **הן עם לבדד ישכון ובגוים לא יתחשב** פירוש לבדד שאין שורשו משורש תרח ואבותיו וממין ענף ההוא אלא לבדד מין מחצב נשמות ישראל אין לו שום קורבה מהמולידים, ואומרו **ובגוים לא יתחשב** פירוש שאפילו עם אותם שנקראים גוים שהם אחיהם ממש והם ישמעאל ועשו ששניהם נקראים גוים, ישמעאל דכתיב (בראשית יז) ונתתיו לגוי גדול, ועשו דכתיב (שם כה) שני גוים, לא יתחשב, וכן אמר ה' לאברהם (שם כא) כי ביצחק יקרא לך זרע למעט ישמעאל ועשו שאינם נחשבים זרעו, מעתה אין מקום לקלל לישראל לא לצדיקים ולא לבינונים, והגם שהיו ביד ישראל עונות עון העגל והמרגלים וכדומה, כבר אמר ה' עליהם לשון סליחה, ואולי כי לטעם זה לא היה ה' מתכעס כל אותם הימים שהיה בלעם רוצה לקלל ח''ו:
@820 **עוד** יכוון באומרו **הן עם** וגו' מתמיה על בלק שרוצה לקלל ישראל ואמר הן עם זה הוא העומד אחר כלות כל האומות יעמוד בדד ישכון וכל האומות אין מבטח להם אפילו שנים רבות ואיך רוצה לעקור אומה המתקיימת עד סוף העולם, ואומרו **ובגוים לא יתחשב** פירוש לא בא לגדר חשבון מעלתם כשיהיו לבדד כי אין דומה להם בכל הגדולות שיגיעו האומות:
@822 **מי מנה עפר יעקב וגו'**. הנה לפי שהרשע היה מתחכם בדעתו ומבקש איזה אופן להרע לישראל כמו שאמר שחפש בהם ובאבותיהם ליכנס דרך שם, בקש גם כן ענף אחר שהוא מיוחד לקליפה שתשלוט בו ותעשה רושם, והוא ענין המספר כאומרם ז''ל (ב''מ מב.) אין הברכה שורה לא בדבר המנוי וכו', ורצה הרשע להכניס עין הרע במספר ולא מצא, ואמר מי מנה עפר שנמשלו לו דכתיב (שם יג) כעפר הארץ, וברכה זו הגם שנאמרה לאברהם לא נתקיימה אלא ביעקב ולזה אמר עפר יעקב:
@822 **עוד** נתכוון לומר שלא הגיע אדם למנותם, אפילו כשרוצים למנות עצמן צוה ה' שלא לפקוד אלא על ידי דבר אחר בשקלים או בטלאים, ואומרו **ומספר את רובע ישראל** למה שהקדמנו שידבר בב' הדרגות בהמון העם שיתכנו בשם יעקב, ובצדיקים אשר בשם ישראל יתכנו, לזה אמר כנגד ההמון **מי מנה עפר יעקב**, וכנגד הצדיקים אמר **ומספר את רובע ישראל** פירוש שיש בהם צדיקים לאין מספר, ותדע שהצדיקים הגם שיהיו מועטים יפליגו במספרם, והרשעים בהפך הגם שיהיו רבים מספרם מועט כאומרם ז''ל (סנהדרין כו.) שאמר ה' לחזקיהו כשאמר לפניו רבים אשר את שבנא וגו' אמר לו אין מנין לרשעים, ודקדק לומר רובע לפי שהצדיקים הם רבוצים באהליהם דכתיב ביששכר (בראשית מט) רובץ בין המשפתים, גם לפי שהשכינה רובעת עליהם, גם יש סוד בדבר שהם יסובבו יחוד וזיווג הע ולמ ו ת:
@822 **עוד** רמז על מה שהיה ה' מפליא עמהם במצרים כשגזדו כל הבן הילוד וגו' שהיו מונים למעוברות מלילה ראשונה שהיתה האשה היהודית טובלת ולא היו מועילים שהיה ה' עושה נפלאות להם לאין מספר כמו שמפוזרים הדברים במאמרם ז''ל (שמו''ר פכ''ג, סוטה יא:) ולא היו יכולין לעמוד על רביעותיהם, והוא אומרו ומספר את רובע ישראל:
@822 **תמות נפשי מות ישרים**. אלו דברי עצמו ולא דברי רוח הקודש, וכבר אמרו ז''ל (ילקוט) כי כשהיה רוצה לדבר דברים שאין היזק לישראל היה ה' מניחו לדבר אשר יחפוץ, ואמר **מות ישרים** ולא אמר כמותם שחוזר על ישראל, הפליג רשע לשאול ענין גדול, שאמרו ז''ל אנשי אמת (זוח''א קכב:) שיש ב' הדרגות בצדיקים בשעת מיתתם, הא' שיוצאת הנפש מן הגוף והולכת באין מסך מבדיל באין מעכב עד מקום האושר העליון, ויש צדיקים שביציאת הנפש לא ישיגו גדר זה ונמנעים מלכת תכף ומיד ומתעכבים עד זמן מה אם יהיה להם איזה חטאים וכדומה, ואפילו חטא כל שהוא יסובב הדבר, ולזה בחר בלעם לשאול גדר העליון שנפשו בשעת מיתה תהיה כמיתת אותם שהולכים ביושר את פניו יתברך באין מסך באין מעכב:
@822 **עוד** אפשר שדבריו גם בזה ברוח הקודש נאמרו, והכוונה בהם היא תמות נפשו מות ביד ישרים שיהרגוהו ישראל כמו שכן היה. עוד ירצה שבהגיעו ליום המיתה יטיב דרכיו ממעשיו הרעים ותועבותיו, כי רשע שבאומות היה, ואתונו שהיתה לו סוכנת כמאמרם ז''ל (ע''ז ד:) תגיד עליו, אלא שנתאוה שבשעת מיתה ישוב ויהיה ישר כישרים שבאומות, ולפי שעמד על מזגו והנה הוא רע בתכלית הרע ונמנע ממנו עשות יושר, לזה שאל דבר שיכול להיות שבשעת דכדוכה של מות יהיה ישר, וכיוצא בזה ראיתי רשעים שאמרו לי בפירוש כי אם היו יודעים שיחזרו בתשובה ותכף ימותו היו עושים אלא שיודעים שאינם יכולים לעמוד בתשובה זמן ארוך כי דבר מלך עליהם מלך זקן וכסיל רחמנא ליצלן, ולא שאל הרשע שימות כמיתת הצדיקים שבישראל כי הוא מן הנמנע שיגיע להשגה זו:
@822 **ותהי אחריתי כמוהו**. חוזר אל העם, אמר זה כנגד עולם הבא שהוא אחרית העולם, ותדע שה' מעמיד בדין גם לצדיקים מי שהוא ראוי לאושר ההוא הנעלם מהמושג לנפש אחר מיתה לזה התפלל על ב' ההדרגות:
@822 **עוד** לפי מה שפירשנו בכוונת מאמר מות ישרים שיהרגוהו ישראל יתבאר מאמר **ותהי אחריתי** וגו' על פי מה שקדם לנו ממאמרי אנשי אמת שאין לך קליפה בעולם שאין בה ניצוץ מהקדושה סוד המחיה אותה, וכבר הארכתי בענין זה בכמה מקומות ובפרשת שלח לך בפסוק כי לחמנו הם וגו' (יד ט), ואותו ניצוץ כשבעליו נהרג על ידי ישראל מתברר הניצוץ ההוא הטוב, ולפעמים ידבק בו אם הוא נקי בלא פסולת, והוא מאמר **תמות נפשי מות ישרים** ובזה תהיה אחריתי כמוהו כי הניצוץ ידבק באיש ישראל והרי הוא כמוהו, ומצינו בדברי המקובלים (ס' הגלגולים להאריז''ל) כי נפשו של בלעם באה בחמורו של רבי פנחם בן יאיר, וזה יורה שנתקן באחריתו, והגם שמת על ידי ישראל היה הניצוץ משוקץ והוצרך להתלבן בגלגולים וליבונים ועמד עד שבא לאתונו של ר' פנחס בן יאיר ומשם עלה למקומו הראשון:
@823 **לקוב אויבי לקחתיך וגו'**. נתרעם בלק על הברכה, לפי שהגם שאמר לו בלעם היכול אוכל דבר וגו' הבין שהכונה היא לענין שאם לא יסכים ה' עליו לקלל לא יקלל אבל הברכה שב ואל תעשה היא ולא יברך, והגם שאמר לו גם כן הדבר אשר ישים אלהים בפי אותו אדבר, חשב שהוא בענין הקללה שאם ה' ישים בפיו לקלל עשה יעשה ככל אות נפשו, אבל אם ישים בפיו ברכה ימנע עצמו ולא יברך כי אינו מהמוסר שיעשה היזק למי ששלח אחריו לברך אויביו שאין זה אלא מקלל את בלק, והוא מה שדקדק בתיבת **לי** שאמר **מה עשית לי** שברכת ישראל קללה היא לו:
@823 **והנה ברכת ברך**. טעם כפל הדבר, יתבאר בהעיר עוד על בלק שהיא מתמיה על בלעם גם עליו יש לתמוה שהמתין לבלעם עד שגמר ברכותיו ולא הספיק כפיו כמו שעשה באחרונה למונעו מלברך עוד, ומי יחוש על זה יותר ממנו. אכן יודע היה בלק כי בלעם ערום יערים להתחכם לקלל ישראל ולזה היה משבח ומברך בהפלגה לומר אחריה השפלות וגנות וקללות, ותמצא שאפילו במין הברכה עצמה היה מתחכם לומר מין ברכה שבו קללה כמו שאמרו במדרש ילמדנו (ילקוט תשע''א) וזה לשונם עם שהרשע מקלסן בקש לגנותן יעויין שם דבריהם, הרי שהיה מתחכם גם בברכה עצמה לקללם, ולכן היה בלק ממתין לבלעם מה יאמר בתכלית וכיון שעמד נתגלה כי מה שהיה מברך לישראל לא היה לתכלית רע אלא לתכלית טוב, והוא אומרו ברכת ברך:
@823 **עוד** נראה שהקפדת בלק היתה על מה ששמע מפי בלעם שנתאוה תאוה להיות כמוהו זה יגיד כי מה שבירך היה מלבו ולברכה יכוין, והוא אומרו **ברכת** ועשית אותם ברכה שאמרת ותהי אחריתי כמוהו, ולזה דקדק לומר ברך מלא פום שמתברכים אחרים להיות כמותם:
@824 **הלא את אשר וגו' אשמור וגו'**. פירוש לא כמו שאתה חושב שאין עלי חיוב כשיבא הדיבור מה' לברך ואסתום פי ולא אדבר, לא כן הוא אלא הרי הוא מותרה לבל ישתוק, ולזה דקדק לשון שמירה על דרך אומרם ז''ל (שבועות לו.) כל השמר פן ואל אינו אלא לא תעשה שהוא מוזהר לבל ידום ואם יעבור חייב מיתה, וזולת מאמר אשמור לא היה נשמע, ומעתה אנוס הוא, ורבותינו ז''ל (במד''ר פ''כ) אמרו שאמר לו ולואי שהיה מת ולא מברך ישראל, הרי שכל מה שהיה מברך אנוס היה ולא מלבו:
@824 **עוד** ירצה ע''ד אומרם ז''ל (ילקוט) טס של ברזל היה עומד בפיו אם היה רוצה לקלל היה מונעו לברך יכול, והוא אומרו **אותו אשמור** כדי שאוכל לדבר שזולת זה היה מתאלם, או אפשר שנתכוין לומר לו כי הוא מיחל ומצפה לשום ה' דברו בפיו לדבר, והוא אומרו **אשר ישים ה' בפי אותו אשמור** פירוש מיחל ומצפה לדבר, כי יטעום טעם גדול אשר אינו כדאי הוא וכל משפחות האומות כידוע כמה ערב לנפש טעם הכח הקדוש אשר מלתו על לשונו, והגם שעשה ה' בפיו דבר ופירשנו לבל יגעו הדברים בפה חזיר, אף על פי כן יטעום טעם בן נותן טעם ויערב לו:
@825 **ויאמר אליו בלק לך נא אתי וגו'**. אמר תיבת **נא**, גם אמר **וקבנו לי** בלשון ודאית, יתבאר על פי דבריהם ז''ל (במד''ר פ''כ) שאמרו שראה שישראל נפרצים שם ששם מת משה עד כאן, והוא לפי שלא ידע טעם הפרצה חשב שהפרצה תהיה בהם, ולפי שידועים היו ישראל שעושים תשובה ומבטלים הגזירות מהר לומר **לך נא** פירוש מהר עתה שאני רואה שהם מחויבים פרצה זו קודם שיעשו תשובה, וקבנו לי החליט הויית הדבר שתשיגם קללות רשע:
@830 **קום בלק וגו'**. קימה זו למה, ורז''ל (שם) אמרו לפי שהיה בלק מצחק בבלעם שאינו ברשות עצמו לזה נתכוין להקניטו ואמר לו קום ושמע, ולדבריהם צריך לדעת למה אמר ושמע בתוספת וא''ו, ואולי שנתכוין לומר לו שיתחיל לשמוע משעת קימה, והוא אומרו **קום ושמע**. או ירצה לפי שאמר ה' לבלעם שוב אל בלק וגו' שהזקיקו לומר הדברים לפני בלק, לזה אם היה אומר קום בלק שמע יהיה נשמע שרצונו לומר שיקום לשמוע כדי שישמע מעומד אבל אין חיוב בשמיעה אם לא ירצה לשמוע יפנה וילך לו, לזה אמר ושמע חיוב בקימה וחיוב בשמיעה:
@830 **עוד** יכוין לומר לו שקימה היא לו שזכה לשמוע דברים הבאים ממקום גבוה, והעירו עוד להטות אזנו עדיו להאזין כל דקדוקי הדברים, ובזה אתה יותר במדרגה מאותו שאתה מחשיבו לאב שהוא צפור הכשפים דכתיב בן צפור, מעתה הוא בנך, והוא אומרו בנו צפור. עוד יתבאר הכתוב לפי מה שהקדמנו כי רשע זה היו בו ב' דברים רעים, הא' שהיה רוצה לקלל ישראל והיה צריך שיבא מלאך לעקם פיו כאמור, והב' שהברכה עצמה שהיתה יוצאה מפיו היה מכוון בה לגנאי והיה צורך לרוח הקודש לפרשה לשבח כמו שכתבנו למעלה, ולפי שחשד בלק לבלעם שהוא חפץ לברך את ישראל, בתחילת דבריו אמר לבלק שיקום על עומדו להתבונן בב' פרטים כדי שלא יחשדנו, וזה ראשונה כנגד מה שהיה אומר בברכתו דברים שאינם כל כך מפורשים לטובה והיתה רוח הקודש מפרשתם לברכה שלימה והוא אומרו **ושמע** בתוספת וא''ו לרמוז שמיעה אחרת, וכנגד מה שהיה רוצה לקלל והמלאך עוקם פיו אמר **האזינה עדי** פירוש שיתקרב ביותר עדיו וישכיל בעקימת שפתיו, שמתעקמין ממבטא אשר יבטא בשפתיו, ובזה העירו כי אנום היה ולא יחשדו כמברך אויביו:
@831 **לא איש וגו' ובן אדם וגו'**. אמר ב' הדרגות כנגד ב' בחינות, הא' אשר יבטיח האדם לזולת על דבר, והב' אשר יחכים אדם עשות דבר בהנהגותיו ועניניו שאין נוגעים לזולת, כנגד מאמר שהוא הבטחת הזולת אמר **לא איש אל ויכזב**, וכנגד מאמר שאינו נוגע לזולת אמר **ובן אדם ויתנחם** שאינו מכזב בזולת אלא ינחם על אשר דבר עשות, ובמה שלפנינו יש ב' דברים אשר דבר ה', א' להקים מלכות ישראל ולהטיב להם, והב' שחשב ה' לעשות רצונו לתת תורתו לעם קדושו והם דברים שנוגעים לו יתברך, וכנגד שניהם אמר לא איש אל ויכזב בהבטחות הטובות אשר הבטיח לאבות ובן אדם ויתנחם ממה שחשב בהנהגות עולמו לתת תורתו לישראל ולהדריכם לקיים מצותיו, ואם כן איך יחשוב לקלל ישראל ונמצא מכזב ח''ו בהבטחותיו לאבות וניחם על מה שחשב עשות:
@831 **ואו' ויכזב ויתנחם** בתוספת וא''ו, כלל בזה ב' הדרגות, א' שאינו איש ולא אדם ועוד לחשוד בו ח''ו דבר שאפילו בנבראים הוא גרעון והוא הכזב והחרטה, ונתכוון בזה שמן הנמנע שיסכים על קללת ישראל עד שיהיו בו ב' דברים איש ויכזב ובן אדם ויתנחם שהגם שהיה ח''ו איש ויכזב עם כל זה לא יתחרט למה שנוגע למה שחשב עשות רצונו באמצעות ישראל, וטעם שפם אחת אמר איש ופעם אחת אמר בן אדם, לפי שהמבטיח להטיב לזולת ישנו בגדר מעלה לזה אמר לשון חשיבות, ובפרט המתחרט על מה שחשב על עצמו אמר ובן אדם:
@831 **ההוא אמר וגו'**. פשט הכתוב חוזר להאדם, ואפשר לפרשו על הקב''ה על זה הדרך כשרוצה לעשות מעשה אינו צריך למעשה אלא במאמר הוא נעשה, והוא אומרו **ההוא** פירוש האל שהזכיר בסמוך אמר פירוש פעולותיו שעשה הוא אמר ותהי, **ולא יעשה** פירוש לא יצטרך למעשה כאומרו (בראשית א) ויאמר וגו' ויהי כן, וכן אמרו במשנה (אבות פ''ה) בעשרה מאמרות נברא העולם, ואומרו **ודבר** וגו' פירוש וכשהמעשה שנעשה במאמרו אינו כל כך קיים, על דרך אומרם שהיה העולם רופף ורועד דכתיב (איוב כו) עמודי שמים ירופפו ויתמהו מגערתו ואמרו חכמינו ז''ל (חגיגה יב.) שגער ה' בהם ונתקיימו, והוא אומרו **ודבר** לשון קושי **ולא יקימנה** פירוש ולא יצטרך לקיימנה אלא בדיבורו הקשה היא מתקיימת ומתחזקת:
@832 **הנה ברך לקחתי וברך וגו'**. לפי מה שפירשנו בפסוק (כ''ג ה') וישם ה' דבר בפי בלעם שעשה בפיו דבר רוחני שיפסיק בין פיו לרוח הקודש המדברת, והוא מה שכוונו רז''ל במאמרם (ילקוט) דבר מלאך. אלא שהם נתנו טעם הדבר כדי למונעו מלקלל ושני הטעמים צודקים, וכפי זה נתכוון במאמר **הנה ברך לקחתי** שהרגיש במה שניתוסף בפיו ובלשונו שיקרא ברך. ועוד וברך כי לא שם הדבר בפיו ונשאר הדבר לרצונו של בלעם אלא וברך פירוש מכריחו לברך והגם שהוא אינו חפץ ולהשיבה אינו יכול, והוא אומרו **ולא אשיבנה** פירוש אינו יכול להחזירה:
@833 **לא הביט און ביעקב**. יתבאר על פי דבריהם ז''ל (רע''מ ח''ג רעה) שאמרו כי על ידי חטא האדם נרשם רושם כח הרע באבר שבו עשאו והיא בחינת הפגם המוזכרת בדבריהם ז''ל, ופירוש און הוא כח הרע הנמשך מהעבירה, על דרך אומרו (משלי ל) לא פעלתי און, וכתיב (תהלים קכה) יוליכם ה' את פועלי האון, ולזה אמר **לא הביט און** שהוא רושם המפעל הרע אינו אפילו ביעקב שהן המון העם שיתכנו בשם יעקב שכלם נשמרים מעשות רע, והגם שיטעו מדרך השכל אינו נקבע בנפשם האון שהוא חלק הרע, על דרך אומרו (שיר ד') כלך יפה ומום אין בך פירוש שאין החטא עושה בו מום קבוע אלא לכלוך העובר על ידי רחיצה והדחה, וכמו שרמזו ז''ל (שהש''ר) במה שאמר הכתוב שחורה אני ונאוה יעיין שם, ואומרו **ולא ראה עמל בישראל** פירוש אפילו פגם שצריך עמל להעבירו אינו באותם שנקראים ישראל שהם הצדיקים:
@833 **או** ירצה אומרו **לא הביט** און הוא חטא המחשבה שגם הוא יקרא און על דרך אומרו (תהלים ס''ו) און אם ראיתי בלבי, שאין ה' מביט אל המחשבה הרעה, ביעקב פירוש שאין עושה ביעקב המחשבה הרעה רושם האון שהיא ענף הרע, ולזה דקדק לומר לשון הבטה שהיא יותר מהראיה פירוש כי הגם כי בראיה ראשונה הוא רואה מחשבה הרעה כשהוא מביט בפנימיות מפעלה אין און, ודקדק לומר **און ביעקב** פירוש שאינו עושה בו החטא ההוא רושם, וזה אפילו בהמון העם אשר בשם יעקב יכונה, וכנגד הצדיקים שבהם אמר **ולא ראה** פירוש אפילו מחשבה בלתי הגונה הנקרא עמל שעמל עמו יצר הרע בכח המחשבה להטותה מדרך השכל והצדיקים לבם חלל בקרבם, והוא אומרו **ולא ראה עמל בישראל**. גם נתכוון לומר שהצדיקים הגם שעושים מצות וכל עסקם בתורה אינם מרגישים שיש להם עמל על דרך אומרו (תהלים עג) עמל הוא בעיני אלא אדרבא כאדם המרויח וכאדם המשתעשע בשעשועים לרוב חשקם בתורה. גם נתכוון על דרך אומרו (משלי ח) אני בינה לי גבורה, כי כשהצדיקים עוסקים בתורה ומתמידין בה אין להם עמל בעסק התורה שאדרבא היא נותנת לו גבורה:
@833 **עוד** ירצה לומר כי באמצעות ב' הדרגות שיש בישראל אין הקב''ה מקפיד על רשע שבעולם מהאומות ובזה אינו מאבדם גם אינו יגע בבריאת עולמו ובנשיאת עול לכל הדברים הצריכין לעולם, והוא אומרו **לא הביט און** שיש בעולם בשביל יעקב, גם אינו רואה עמל שעמל כביכול בסבילת העולם ובמזונותיו ובסיפוק צרכיו הכל אינו חש לו בשביל ישראל, והוא אומרו **בישראל** בשביל ישראל, וכן תמצא שאם ישראל הולכים בדרך התורה והמצות ה' נותן טובו לעולם וניזונים ונהנים גם האומות יחד, ומעתה המבקשים לעקור אומה זו מבקשים לאבד העולם ויושביו. עוד נתכוון באומרו ולא ראה עמל בישראל כי הצדיקים כל צפצופם עושים בו נחת רוח לה' ואינם מיגעים אותו כביכול על דרך אומרו (מלאכי ב) הוגעתם ה' בדבריכם, ולזה אמר ולא ראה עמל בישראל:
@833 ה' **אלהיו עמו ותרועת מלך בו**. פירוש כנגד ב' בחינות שהזכיר, הנקראים בשם יעקב שהם ההמון עם, והמתכנים בשם ישראל שהם הצדיקים, ה' **אלהיו עמו** הם הצדיקים שעושים מאהבה, לזה אמר ה' שהוא שם החסד לומר שאין עבודת הצדיק לצד הדין אלא אוהב הטוב במה שהוא טוב, ודקדק לומר אלהיו שלא תחשוב שאם ה' מייסרהו ישוב אחור, לזה אמר אלהיו שהגם שייסרהו על משמרת אהבתו יעמוד, וכנגד כת ההמון הנקראים בשם יעקב אמר **ותרועת מלך בו** שהוא ירא לצד המשפט:
@833 **עוד** ירצה לומר שבח השגתם שלא בחר ה' לשכן שמו אלא עמם, ועוד שעשה בהם כח עליון שיכולין לאבד כל מה שנותנין בו עיניהם כמלך עולם, והוא אומרו **ותרועת מלך בו** פירוש אין צריכין שה' יאבד קמיהם אלא בהם עצמן יש הדרגה זו. וכן תמצא שהצדיקים כל מקום שנותנים בו עיניהם להשחית בכל הנבראים הם בעלי היכולת:
@833 **עוד** יתבאר על דרך אומרם ז''ל (ברכות סא:) על רבי עקיבא שהיו סורקים בשרו במסרקות של ברזל והיה מאריך באחד וכו', והוא אומרו ה' **אלהיו עמו** פירוש מדבק נפשו בה' אלהיו בתכלית החיבה הגם שתרועת מלך בו בשבט ברזל שסורקין בשרו, ואפילו בזמן עצמו שהשבט בו שהיו סורקים וכו' אף על פי כן ה' אלהיו עמו:
@834 **אל מוציאם ממצרים**. אמר **מוציאם** ולא הוציאם, הגם שרז''ל אמרו (ברכות לח.) דאפיק משמע והוכיחו מכאן אף על פי כן יותר משמע לשון עבר אם היה אומר הוציאם:
@834 **ונראה** על דרך אומרם ז''ל (פסחים קטז:) בכל דור ודור חייב אדם לראות את עצמו כאלו הוא יצא ממצרים, על כן אמרו יודעי פנימיות התורה כי כל ליל פסח מתבררים כוחות הקדושה מהקליפה ונוספים בעם בני ישראל והיא הבחינה עצמה של יציאת מצרים, והוא אומרו **אל מוציאם** כי לא יציאה ראשונה לבד אלא בכל שנה ושנה מוציאם כנזכר, ונתן טעם **כתועפות ראם לו** פירוש כי ה' מוסיף ומחזק אותם לרוממם ואין קץ לרוממות אשר חשב ה' עליהם עד גדר שלא ישאר שום תערובת הרע בקדושה, והוא אומרו **כי לא נחש ביעקב** רמז לבחינת הניחוש גם לבחינת הנקראת נחש שהוא ראש הקליפה ס''מ הרשע הנקרא נחש תעקר ולא ישאר ממנו ביעקב, על דרך אומרו (זכריה י''ג) ואת רוח הטומאה אעביר מן הארץ, ולא קסם הוא בחינת טומאה למטה ממנה, ואז יהיו ישראל בגדר שלמות המעלה ותהיה מעלתם יותר מן המלאכים, והוא מה שגמר אומר **כעת יאמר ליעקב** וגו' ואמרו רז''ל (מד''ד כאן) שהמלאכים ישאלו לישראל מה פעל אל:
@836 **הן עם וגו'**. אומרו **הן**, על דרך אומרם ז''ל (שבת קיט:) מלאך רע עונה אמן בעל כורחו, שבלעם עצמו אמר הן כן יהיה עם זה כלביא יקום וכארי וגו', ואומרו **כלביא** פירוש קימתו ראשונה אינו כשאר העולם שבתחילה להיותו חסר התלמדות המלחמה לא יעשה גבורות אלא כלביא יקום ויעשה נפלאות, כמו שכן היה שהגם שמעודו הוא שבוי בבית הבור מעונה בסבל אנוש אף על פי כן כצאתו את העיר הפליא עשות בסיחון ועוג, אמר עוד **וכארי יתנשא** פירוש על דרך אומרם ז''ל (שם עז:) ג' כל זמן שמזקינין מוסיפין כח ארי וכו', והוא אומרו **יתנשא** שהוא מתנשא ורם בכחו שהגם שיעברו עליו כמה מלחמות לא מפני זה יהיו נחלשים אלא הולכים ומתגברים:
@836 **עוד** ירצה שמלבד כח אשר עשה ה' בהם עוד יהיה בעיני כל האומות במדרגה גדולה לפחד מהם כאומרו (יהושע ב') וגם נמוגו וגו', והוא אומרו **כלביא יקום** זה בערך גבורתו, ובערך מה שיהיה נחשב בעיני העולם **וכארי יתנשא** פירוש יותר ממה שהוא יהיו מנושאים בעיני העולם:
@836 **לא ישכב עד וגו'**. פי' שאין הלילה מפלט לנוס מפניו כי לילה לפניו כיום יאיר, וצא ולמד מיהושע (שם י') שאמר לשמש שתעמוד ולא אץ לבא וכדומה, והוא אומרו **לא ישכב עד יאכל טרף** הא למדת שבזמן שכיבה מתעסק הוא באכילת טרף, ואומרו **ודם חללים ישתה**, לפי שבטבע אנושי כשירבה להפיל חללים תיקר בעיניו נפש הנשארים, לזה אמר אוי להם לאומות כי עם אלה הדם בעיניו כמשקה אשר ישתה ואינו נחשב בעיניהם הדם בגדר הריגה אלא בגדר שתיה, ודקדק לומר **ישתה**, לפי מה שהקדמנו כי על ידי הריגת עכו''ם נדבקים חלקי הקדושה בעם ה' בסוד כי לחמנו הם (י''ד ט') כמו כן אמר כאן ישתה והבן ורז''ל (חולין לה:) למדו מכאן לדם שחשוב משקה:
@837 **גם קב לא תקבנו**. אמר **גם**, וכפל לומר קב תקבנו פירוש לפי שאמר לו בלעם קום בלק וגו' האזינה וגו' ושם רמז לו שהוא חפץ לקלל ומלאך עוקם פיו כמאמרם ז''ל (מד''ר כאן) ג''כ לזה אמר גם קב פירוש מלבד שלא תקללנו בכיוון אלא אפילו להוציא הקללה מפיך בלא זכירת שמם לא תקבנו, מכאן שמתחכם היה בלעם הרשע להוציא מפיו קללה בדרך שלא יענישהו הבורא על זה הדרך שיאמר ארור או מקולל ולא יוציא מפיו שם המקולל והמאורר אלא שבלבו יכוין למה שרוצה, ולטעם זה היה ה' מונעו מלהוציא מפיו קללה ונחתמה בלבו, ואומרו **גם ברך** לפי שאמר לו בלעם שאינו מברכם מרצונו אלא אנוס הוא לברכם לזה אמר לו אם אתה לא תקלל לא תתחייב לברך, וחשב שלא יעקם ה' פיו לברך אלא אם ירצה לקלל, וכפל לומר **גם ברך לא תברכנו** פירוש אפילו ברכה שאינה כפי האמת ברכה כפי דעת בלעם וכוונתו אף גם זאת לא תברכנו:
@838 **ויען בלעם וגו' לאמר**. צריך לדעת אומרו **לאמר** כי למי יאמר בלק, אכן נתכוון לומר כי מה שדבר אליו קודם כוונתו לומר לו שכל אשר ידבר ה' בין קללה בין ברכה אותו אעשה, אם כן הגם שלא אקבנו וידבר ה' לברכם אברכם לקיים דבר ה':
@839 **לכה נא אקחך**. אמר **נא** פירוש עתה שכבר היה מה שהיה ומה שיש לו לברך כבר ברכם, וטעם שעדיין היה מצפה לדבר שראה ב' פעמים שה' חפץ בברכה לישראל, נראה כי חשב שאפשר שהפינה שעמד בלעם פעם אחד וב' היו אנשים צדיקים מה שאין כן עתה שמשים פניו כנגד כל העם מן הסתם יהיו בהם כת אחת בלתי הגונה וחשב אולי ימצא מקום לקוב משם, והוא אומרו **אולי יישר** וגו', ואמר **וקבותו לי** ולא אמר לקבותו, נתכוין בזה שאין צורך שיישר בעיני ה' לקבותו אלא שיישר בעיני ה' שלא למונעך ואז תקבנו משם:
@843 **וירא בלעם כי טוב וגו'**. ולדבריהם ז''ל (מד''ר) שאמרו בפירוש פסוק כי ברוך הוא שאמר ה' לבלעם לא תברכם, נתכוון לומר על זה הדרך טוב בעיני ה' לברך פירוש ה' שהזכיר בסמוך ואינו חוזר על בלעם כי כבר אמר לו ה' כי ברוך הוא ואינו צריך לברכם, והגם שמצינו שהיה מברכם, זה היה להפך קללתו לברכה, ולפי מה שפירשתי בפסוק (כ''ג ה') וישם ה' דבר בפי בלעם לא בלעם היה מברך אלא מלאך היה מברכם בפיו בהפסק דבר לפיו, ואומרו **ולא הלך כפעם** וגו' פירוש החליט שאין תקוה מה' להסכים להרע לישראל גם לא הלך כפעם וגו' משום שאין תוחלת מהנחשים, לזה נתחכם בעצה רעה והוא **וישת אל המדבר פניו** פירוש לראות מה שהכעיסו במדבר אולי דרך שם יוכל לקלל:
@843 **או** יתבאר לשון דיבור כדרך שפירש בזוהר (ח''ג רה:) בפסוק אבינו מת במדבר לשון דיבור, והכוונה לפי שכל העשר נסיונות שניסו ישראל את המקום היו בדיבור, על ים סוף, בעגל, במתאוננים, במרגלים, בעדת קרח, מי מריבה וכו' כולם היו חוטאים בדיבור, וחשב כי בכללות ישראל שהיו לנגד פניו ימצאון רבים מכתות המדברים ודרך שם יקלל:
@843 **עוד** ירצה על פי דבריהם ז''ל (זוח''ב קנז.) שאמרו כי המדבר הוא מקום חנות ס''מ הרשע, ונתכוון לעורר כוחותיו, והוא אומרו וישת אל המדבר פניו ששם הוא ראש הקליפה ס''מ וחיילותיו שונאי עם בני ישראל. ודקדק לומר **פניו**, אולי שתתעורר הקליפה באמצעות הכעם כדרך שתתעורר הקדושה בשמחה ובלב טוב, כי כל אחד יתעורר למינו, והוא אומרו פניו לשון כעס על דרך אומרו (שמות לג) פני ילכו שהוא לשון כעס:
@843 **או** אפשר לפרש הכתוב על זה הדרך **וירא בלעם** כי מי שהוא טוב הוא בעיני ה' ראוי לברך ישראל על דרך אומרו (משלי כב) טוב עין הוא יבורך ואמרו ז''ל (סוטה לח:) לא תקרי יבורך אלא יברך, והכוונה בזה כי הוא להיותו רע עין כידוע לא נתנו ה' לברך כרמוז במאמר כי ברוך הוא, ומזה הרגיש כי נפסל להיותו רע עין והמברך הוא המלאך שמדבר בפיו, לזה חשב שלא ילך כפעם בפעם לקראת נחשים שהוא חלק הרע **וישת אל המדבר** פירוש אשר הוא חונה שם האלהים מקום מחנה שכינה ומרד בשרש נשמתו וחשב שבזה יוכשר להיות טוב ויברך את ישראל, והודיע הכתוב כי לא עשה זה מרצונו ומלבו אלא לפנים הוא שעשה את הדבר הזה שחשב לרמות בוחן לבות, ואולי שדעתו היתה עד שיאמין בו המלאך להסיר חכה מפיו לדבר כחפצו ואז יחשוב מחשבות להתחכם בסדר הברכה עצמה להרע, כמו שכן עשה כאומרם ז''ל (סנהדרין קה:) בפירוש אומרו כנחלים וגו' כאהלים וגו' והיתה רוח הקודש מבטלת מחשבתו ואומרת לא כמו שאתה חושב וגו':
@844 **וישא בלעם וגו'**. הוצרך לומר וישא, גם הוצרך להזכיר שמו ולא סמך על זכרונו בסמוך, לפי מה שקדם לנו שישראל היו מסובבים בעננים ולא היתה עין שולטת בהם, לזה אמר שנשא בלעם וגו' פירוש נשא נביאותו כי הוא היה נביא אומות העולם ומחזה נבואה יחזה, ולזה דקדק לומר בלעם לרמוז נשיאות עין שאינה בזולתו אלא בו ובזה העיר שבמחזה הנבואה הכתוב מדבר, ובזה השיג לראות ישראל שהיו נסתרים בענני הכבוד:
@844 **וירא וגו' לשבטיו ותהי עליו וגו'**. פירוש שראה בהם ב' ענינים גדולים א' שוכן כל שבט ושבט בפני עצמו, ב' **ותהי עליו** וגו' שהיתה שורה שכינה על כל שבט בפני עצמו מלכו בראשו, והטעם שכל שבט יש לו הדרגה בפני עצמו, או לצד הזכות שיש לאחד יותר מחבירו, או לפי המנין, גם רמז בקשר ב' דברים על פי דבריהם ז''ל (ב''ב ס.) שאמרו שבאמצעות שנסדרו ישראל בדרך זה כל שבט בפני עצמו שכנה עליהם שכינה ונעשו מרכבה לה, והוא מה שדקדק לומר **ותהי עליו רוח אלהים**:
@845 **וישא משלו וגו' נאום בלעם וגו' ונאום וגו'**. צריך לדעת למה הוצרך לומר **וישא משלו**. עוד מה צורך לומר **נאום בלעם** פשיטא כי פיו המדבר, עוד למה הוצרך להודיע שם אביו כאן, עור למה הוצרך לסמן עצמו בסימנים שבגופו, גם במאמר שומע וגו' מה נתכוון בזה, ואם לשבח עצמו למה לא שבח בפעם ראשונה. אכן לפי שעד עתה היה מדבר מה שישים ה' בפיו הפך רצונו שהדיבור היה יוצא מפיו בעל כורחו ועתה רצה שיסכים הוא על הדברים היוצאים מפיו כאלו הוא אומר אותם מרצונו הפשוט, וכוונתו בזה גם כן שאם יקלל יבא כח המברך ויברך אבל אם יברך לא יברך כח המברך, ומה גם לפי מה שפירשתי בפסוק וישת אל המדבר פניו וגו' בפירוש ב' שנתכוון להכשיר עצמו לברך ישראל, יתיישב הכתוב על זה הדרך **וישא משלו** פירוש המשל שהוא ממנו ומדעתו, ובזה יתיישבו דברי רז''ל (סנהדרין קה:) שאמרו שהוא אמר כנחלים וגו' בקש לכנותן כנחל שפוסק בימות החמה וכו' ורוח הקודש משיבתו לא כמו שאתה חושב אלא נטיו פירוש כנהר שאינו פוסק והולך, כאהלים פירוש שהם מטולטלים ונעקרים ממקומם ורוח הקודש משיבתו נטע ה' וגו' וכן כל דבריו הם ברכה שפנימיותה קללה, ואם הם דברי רוח הקודש למה תאמר דבר שיש בו דופי, אלא ודאי שהם דברי עצמו:
@845 **ולזה** אמר **וישא משלו ויאמר נאם בלעם** פירוש דברים אלו הם משלי ואינם כשאר הדברים שקדמו שלא היו ממני, ופירש מי הוא המדבר דברים אלו כדי שיוחקו לעולם מי בעל דברים, ואמר ג' סימנים כדרך אומרו במשנה (פאה פ''ז מ''א) כל זית שיש לו שם וכו' בשמו ובמעשיו ובמקומו, כנגד בשמו אמר **בנו בעור**, ואמר בנו ולא אמר בן לומר שהיה אביו למטה ממנו וראוי להיות במדרגת בנו לגבי בחינת ההשגה, או אפשר לומר שלא היה לבעור אלא בלעם לזה אמר בנו פירוש יחידו של בעור, ולכשתמצא לומר שהיו לו אחרים אמר שכולם נחשבים כאין לפניו כאלו אין לו כי אם בלעם, כנגד מעשיו אמר **הגבר שתום העין** שהיה ניכר במעשה עיניו שכל מקום שהיה מסתכל בעיניו היה לוקה, ולכן היה סותם עינו הרעה לבל יזיק, ואפשר שהיתה לו עין השמאלית מיוחדת לזה, ואם נפרש שתום העין הוא לשון פתיחה ירצה שהיה מסומן בפתיחת עינו להרע, כנגד מקומו אמר **שומע אמרי אל** שהיה עומד לנס עמים ואין אדם אחר עומד במקום זה של נבואה:
@845 **עוד** ירצה בהעיר למה אמר ג' פעמים נאום ולא הספיק באחת. אכן לפי שיש בבלעם ג' הדרגות מכוחות הנעלם. א' כח שבא בבריאתו אשר פעל בו המוליד. ב' אשר קנה בכח מעשיו כי האדם ימשוך לנפשו כחות כפי המפעל ממנו. ג' אשר הקנהו ה' לסיבה ידועה להיות נביא לגוים כדי שלא יתרעמו האומות כאמור בדבריהם ז''ל (מד''ר ריש פ' זו), ונתכוון בלעם לומר דבריו בהסכמת כוחותיו יחד, כנגד כח הבא מכח המוליד אמר **נאם בלעם בנו בעור**, ודקדק לומר בנו ולא אמר בן כי אז היה נשמע שמציין מי ילדו והוא נתכוון לומר על החלק שבו ממה שהוא בנו ולא על מה שיש בכחו הן היום. וכנגד חלק אשר קנה בכחו אמר **נאם הגבר** פירוש הגבר מה שקנה בהיותו גבר מעצמו, גם רמז לתעצומותו מלשון גבורה, שתום העין שפקח עיניו כאומרם ז''ל (זוח''ג רח.) שהיה הולך אצל עזא ועזאל ושם קנה כחות הטומאה ונתפתחו עיניו בנסתרות ובמופלאות אחר כמה יגיעות כאמור בדבריהם כמה יגיעות צריך לדבר, וכנגד כח שבו אשר הקנהו ה' לסיבה הידועה אמר **נאם שומע אמרי אל**, וכפל לומר **אמרי אל ומחזה** וגו' כנגד ב' פרטי השגה. א' כשהיה בא לו הדיבור לאזניו. והב' כשהיה נגלה אליו, וכנגד שניהם אמר **נופל וגלוי עינים** פירוש כשהיה חוזה מחזה שדי היה נופל וכשהיה בא לו הדיבור ושומע באזניו לא היה נופל אלא היה גלוי עינים:
@847 **מה טובו אהליך וגו'**. פירוש לפי שיש בישראל כת שקובעים עתים לתורה, וכת שעוסקים בה יתד התקועה, כנגד בעלי עתים אמר **מה טובו אהליך יעקב** כאהל זה שאינו קבוע, וכנגד כת התקועה אמר **משכנותיך ישראל**:
@847 **עוד** נתכוין כנגד ב' זמנים א' שהיו במדבר שהיה ה' ביניהם באהל דכתיב (שמות כו) ועשית וגו' לאהל על המשכן וכנגדו אמר מה טובו אהליך, ב' שהיו בו בישוב דכתיב (מ''א ח') ה' אמר לשכון בערפל וכנגדו אמר משכנותיך ישראל, ואמר לשון רבים לפי שיש הדרגות באהל אהל מועד משכן לפנים מן הפרוכת:
@848 **כנחלים נטיו וגו'**. רז''ל (סנהדרין קה:) דרשו בזה הרבה דרשות ואפשר לפרש הכתוב על זה הדרך שהכתוב מדבר כנגד ד' כתות הצדיקים שבעם ה'. א' הוא כשמואל הנביא שהיה מסבב כל ארץ ישראל ללמד ישראל תורה ומצות בכל שנה ושנה כאומרם ז''ל. (שבת נו.) ב' כת הצדיקים הקבועים לתלמוד תורה ללמוד וללמד ולהורות משפט והיא כת העומדת בלשכת הגזית העוסקת בתורה ובהוראה כידוע, והיא בגדר הראשון עצמו אלא שהמבקש ה' יבא אליהם מוסיף עליהם שמואל שהוא היה מסבב להורותם. ג' כת הלומדת תורה לשמה לעצמה להשכיל ולהבין אמרי נועם, יתירה עליה כת הראשונה שלומדת ומלמדת. ד' היא כת המחזקת ידי הלומדים ויוצאים למלאכתם למצוא טרף אדם, וכנגד ד' כתות אמר ד' דמיונים, כנגד כתו של שמואל אמר **כנחלים נטיו** שהם עושים כנחל הזה שנוטל מימיו ממקום למקום לשתות ממנו כמו כן כת זו שטורחין בעצמן להשקות צמא למים חיים, וכנגד כת ב' אמר **כגנות עלי נהר** כגן הזה שהוא נטוע וכל הרוצה ליהנות יבא ויהנה, גם מוליכים פירות ממנו וזנים הרחוקים כמו כן הם כת נטועה בלשכת הגזית וכל הרוצה ליהנות יבא ויהנה, גם פירותיהם הולכים למרחוק שהבאים לשם מתחכמין מהם ויוצאים להשקות צמאי תורה, וכן כתיב (ישעי' ב) כי מציון תצא תורה וגו', וכנגד כת הג' הלומדין לעצמן ואין בהם כח להשפיע לזולת אמר **כאהלים נטע ה'** כיעקב איש תם יושב אוהלים ללמוד לעצמו, ואמר לשון נטיעה כנטיעה הזאת שכל שהיא מתישנת מוסיף שרשים ואחיזה ביניקתה כמו כן לומדי תורה כל זמן שמאריך בעסק התורה תוסיף להשתרש נפשו בה, וכנגד כת הד' אמר **כארזים עלי מים** ארזים רמז לעשירי עם בעלי קומה בעלי כח וגבורה בעולם הזה אבל אין עושים פירות בתורה לפי שאינם לומדים בתורה:
@848 **וכבר** כתבתי בכמה מקומות כי פרי התורה הוא לבדו יקרא פרי. ועיין מה שפירש בזוהר (ח''ג רב.) בפסוק לא תשחית את עצה וגו' ממנו תאכל וגו' שהכתוב רומז לבעל תורה שהוא עושה פרי וכו' יעויין שם, ואמר **עלי מים** שחוזקם גם כן הוא עלי מים שהיא התורה לפי שמחזיקים ידי האנשים הלומדים בתורה שנמשלה למים ויהנו מהמים עצמם, כי המחזיק ידי לומדי תורה חולק עמהם שכר כידוע, והכוונה בכל המאמר לומר שכל ישראל עומדים בשורש הקדושה זאת התורה ואפילו העוסקים בענין עולם הזה:
@849 **יזל מים וגו'**. הכוונה על פי דבריהם (שמו''ר פכ''ח) כי כל איש ישראל קבל מסיני חלק בתורה, ולזה רמז מורשה ודרשו (פסחים מט:) אל תקרי מורשה אלא מאורשה, ואמר כאן כי כל מה שמחדשים בתורה הוא מדליו ממה שדלה דלה משה שהכל רמוז בתורה שבכתב:
@849 **ואמר** לשון **דלי** לומר כי בערך פינה (בינה) הגדולה אשר עתיד ה' לגלות לישראל בסוף הדורות בימי מלך המשיח שהוא שער החמישים של בינה כל המ''ט הם בגדר דלי בערכו, ואמר כי הגם שעתה הוא דלי זרע ישראל יזכה לקחת מים רבים שהוא שער הנ', והוא אומרו **וזרעו במים רבים**:
@849 **ואמר וירום מאגג מלכו**. כאן גילה מלכות ישראל הקיימת שהתחילה מאגג שהיא מלכות עמלק, ראשונה שעשה שאול ומשם נפסקה מלכות שאול ונתנה לרעהו הטוב שהוא דוד, וטעם שכינה התחלת מלכותו מאגג להעיר סיבת הדבר שהיה מצד אגג פירוש שהניחו שאול חי ולא הרגו, כאמרם ז''ל (מגילה יג.) שבאותה הלילה השריץ אגג זרע עמלק, וזה סיבה לעקירת מלכות שאול ולרומם מלכות בית דוד, **ותנשא מלכותו** היא מלכות המשיח שהוא דוד, דכתיב (יחזקאל לז) ועבדי דוד מלך עליהם ירום ונשא מאוד כאמור בישעיה (נב):
@849 **עוד** ירצה באומרו **וירום מאגג** שתחילת פעולת מלך המשיח היא מלחמת עמלק שכל עמלק בא מאגג כידוע, ואמרו ז''ל (תנחומא ס''פ תצא) שאמר הקדוש ברוך הוא אין הכסא שלם עד שימחה זכר עמלק ותנשא מלכותו על כל העולם:
@850 **אל מוציאו ממצרים וגו'**. פירוש על דרך אומרם ז''ל כי בצאת ישראל ממצרים בררו כל נצוצי הקדושה שהיו בקליפת מצרים, וכבר הקדמנו שתוקף הקדושה היא כשמבררת ענפיה, והוא אומרו **מוציאו** וגו' **כתועפות ראם לו** פירוש לעם, ולזה גם כן רמז במאמר יאכל גוים צריו שהאכילה היא להוציא ניצוץ הקדושה שבו ותהיה נכללת בנפש ישראל בסוד (משלי יג) צדיק אוכל לשובע נפשו, ואומר **ועצמותיהם** פירוש ואפילו בחינה המתעצמת בהם יגרם אותה, ואומרו **וחציו ימחץ** יתבאר על דרך אומרם ז''ל (תנחומא פ' בשלח) בפסוק (ישעי' כד) יפקוד ה' על צבא וגו' שאין הקב''ה מאבד אומה למטה עד שפוקד על שר שלה למעלה, והנה כשהאומה נחלשת לבד לא יאבד השר למעלה אלא ישפילנו ה' וכשהאומה יארע לה כסדום ועמורה אז יאבד שרה למעלה, והוא אומרו **וחציו** פירוש כח מערכתם שהם חצים הלוחמים בעדם והם השרים, **ימחץ** על דרך אומרו (תהלים קי) מחץ ראש על ארץ רבה שיאבדו כח שריהם מלמעלה, ואם נפרש ימחץ לשון טבילה ורחיצה יכוין לומר שאין זורקין חץ שאינו נתקע בהם ונטבל בדמם:
@851 **כרע שכב וגו'**. פירוש אפילו בזמן שכרע פירוש שאינו חוגר כלי זיין ולא עומד למלחמה אלא כורע ויושב לו, ולא זה בלבד אלא אפילו שכב שאינו מרגיש בבאים עליו אף על פי כן אינו חושש כי מי הוא זה שיתקרב אליו להקימו, ואומר **וכלביא** כפל ההדרגות כנגד ב' כתות שבישראל זו למעלה מזו כמו שכתבנו למעלה שהם הצדיקים והב י נוני ס:
@851 **מברכיך ברוך וגו'**. אמר **מברכיך** לשון רבים וברוך לשון יחיד, לא רצה לברך אלא אחד, ונתכוון על עצמו ורעה עינו בשאר המברכים, ואמר **אורריך ארור** נתכוון לומר שאין כל אורריו ארורים, ובא למעט עצמו מהארירה, ואולי כי לרעה נתכוון על זה הדרך מברכיך יתקיימו דבריו ותהיה ברוך, ואורריך יתקיימו דבריו ותהיה וגו', והערים הרשע בזה לקיים אם יקללם אחר כך, ולזה הקדים מאמר ברוך לארור להעמידם בארור חס ושלום, וה' השיב גמולו בראשו ונתקיימה בו הקללה ונתארר בעולם הזה ובעולם הבא כאומרם ז''ל (סנהדרין צ.) בלעם אין לו חלק לעולם הבא:
@852 **ויחר אף וגו' ויספוק וגו'**. פירוש חרה אפו ושכך רוגזו בספיקת כפיו:
@852 **ברכת ברך**. פירוש ברכת ברכה שאין בה קללה והראיה שאמרת מברכיך ברוך ואורריך ארור, ולפי מה שכתבתי שכוונתו להרע, לא הרגיש בלק בכוונה זו:
@853 **ועתה ברח וגו'**. גזר עליו ד' דברים, אחד שלא יתעכב אלא ילך באותה שעה והוא אומרו **ועתה**. ב' שילך במרוצה כבורח והוא אומרו **ברח**. ג' שלא ילך אחר עמו ללותו אלא הוא לבדו והוא אומרו **לך**. ד' שלא ילך מעיר זו לעיר אחרת מערי מואב או מדין אלא למקומו פתורה והוא אומרו **אל מקומך**, ולפי שכל זה הוא זלזול לבלעם והוא הפך מה ששלח לו (כ''ב י''ז) כי כבד אכבדך מאוד, לזה אמר לו אמרתי כבד וגו', ואומרו **והנה מנעך ה' מכבוד** פירוש כל מה שעשה ה' שלא הניחך לקללם אינו אלא לתכלית דבר זה שהוא למנעך מהכבוד, וסתר בלעם טענתו כי שקר בפיו **הלא גם למלאכיך דברתי** וגו' פירוש ואף על פי כן סברת וקבלת ושלחת לי כי כבד אכבדך, וכפל לומר מלאכיך אשר שלחת ולא הספיק באומרו מלאכיך ומובן הדבר שהוא שלחם, נתכוון במאמר **מלאכיך** על המלאכים הראשונים, ואומרו **אשר שלחת** נתכוון אל מלאכים ששלח פעם ב', ואומרו **לאמר** פירוש לא דברתי הדברים לבד אלא צויתים לאמר לך:
@856 **ועתה הנני וגו'**. פירוש הנה הוא מוכן לקיים גזירת מלך ללכת בעת ההיא, ואמר לשון יחיד כנגד מה שרמז לו בתיבת לך כמו שפירשתי, ואמר **לעמי** כנגד מה שאמר לו אל מקומך, אבל כנגד פרט הבריחה לא הודה לו כי לא חש לירא ממנו כי כשפן גדול היה, וצא ולמד (מד''ר) כמה נתעצמו עמו עם בני ישראל בהריגתו ומכל שכן זולתם שלא יוכלו עשות עמו רעה:
@856 **אשר יעשה וגו' באחרית וגו'**. פירוש לפי שרצה לגלות לו שישראל יאבדו ויקעקעו ביצתם של מואב, וגם בלק אפשר שהיה רואה דבר זה בצפור כי עם בני ישראל ימחץ פאתי מואב, לזה אמר לו כי מה שיעשה העם הזה לעמך יהיה באחרית הימים, וטעם שהוצרך להודיעו דבר זה, לפי שבא ליעצו עצת הפקרת בנותיהם כאומרם ז''ל (סנהדדין קו.) בפירוש אומרו לכה איעצך, לזה חש שיאמר איך יתכן שיצאו נשיהם לעם בני ישראל הבאים לאבדם הלא כל היוצא ידקר, לזה הודיעו כי לא ירעו ולא ישחיתו עם הזה לעמך ויכולין נשיהם לצאת למחנה ישראל לעצתו, ודקדק לומר **לעמך** לומר דוקא לעמך שהם מואב שהיה מלך עליהם הוא שלא יעשו להם דבר אלא באחרית הימים, ולמעט בלק כי פתע ישבר, וכמו שכן היה דכתיב (פ' ל''א) ואת מלכי מדין וגו' והוא אחד מהם כאומרם ז''ל (במד''ר פ''כ):
@857 **וישא משלו וגו'**. פירשתי למעלה (שכל דבריו אינם אלא דרך משל, וגם לפי מה שפירשתי שם יכול להתפרש גם כן כאן):
@858 **אראנו ולא עתה וגו'**. כפל הדברים במלות שונות, גם כפל לומר **דרך כוכב** וגו' **וקם שבט** וגו' גם כפל לומר **ומחץ** וגו' **וקרקר** וגו', כל הנבואה במלך המשיח נאמרה, ויתבאר על פי דבריהם ז''ל (סנהדדין צח.) שאמרו בפסוק בעתה אחישנה זכו אחישנה לא זכו בעתה, והוא רחוק מופלג, וזה לך האות הן אנו בתחלת מאה הששית לאלף הששי, וכנגד ב' קצים אלו דבר הכתוב, כנגד אם זכו אמר **אראנו** פירוש לדבר שאני עתיד לומר אבל אינו עתה בזמן זה אלא בזמן אחר ויכול להיות שאינו רחוק כל כך, שאמרו ז''ל (דב''ר פ''ב) אם היו ישראל חוזרים בתשובה כמצטרך היו נגאלים מיד אפילו לא יעבור עליהם אלא יום אחד בגלות דכתיב יענך ה' ביום צרה, וכנגד קץ בעתה אמר **אשורנו** כמו שצופה מרחוק, והוא אומרו **ולא קרוב** כי הקץ של בעתה ארוך עד למאד בעונות, ואומרו **דרך** וגו' פירוש זאת היא הנבואה שאמר עליה אראנו וגו':
@858 **וכפל** הענין ושינוי הלשון, יתבאר ע''פ דבריהם ז''ל (סנהדרין שם) שאמרו שאם תהיה הגאולה באמצעות זכות ישראל יהיה הדבר מופלא במעלה ויתגלה הגואל ישראל מן השמים במופת ואות כאמור בספר הזוהר (ח''א קיט. וח''ג ריב:), מה שאין כן כשתהיה הגאולה מצד הקץ ואין ישראל ראויים לה תהיה באופן אחר ועליה נאמר (זכרי' ט') שהגואל יבא עני ורוכב על חמור, והוא מה שאמר כאן כנגד גאולת אחישנה שהיא באמצעות זכות ישראל שרמז במאמר אראנו ולא עתה אמר **דרך כוכב** שיזרח הגואל מן השמים, גם רמז לכוכב היוצא באמצע השמים לנס מופלא כאמור בספר הזוהר (שם), וכנגד גאולת בעתה שרמז במאמר אשורנו ולא קרוב אמר **וקם שבט מישראל** פירוש שיקום שבט אחד מישראל כדרך הקמים בעולם דרך טבע, על דרך אומרו (דניאל ג) ושפל אנשים יקים עלה, שיבא עני ורוכב על חמור ויקום וימלוך ויעשה מה שנאמר בסמוך:
@858 **וטעם** שיעד גאולת אחישנה שהיא ככוכב ליעקב וגאולת בעתה שהיא עני וכו' לישראל שהם כתות הצדיקים, נתכוון לומר שהמושג לגדר זה של ביאת הגואל ככוכב הוא כשתהיה הגאולה מפאת גדר הבינוני שבישראל שיטיבו מעשיהם ויבא בזכותם, והוא אומרו **דרך כוכב מיעקב**, אבל ביאתו בדרך וקם שבט זה יהיה כשלא יטיבו מעשיהם כת הבינונים ולא יבא אלא מפאת כת הצדיקים שבהם, והוא אומרו **וקם שבט מישראל**:
@858 **עוד** רמז במאמר **דרך כוכב** מיעקב על משיח בן דוד הרמוז בכוכב כנזכר, ואומרו **וקם שבט מישראל** ירמוז על משיח בן אפרים, והכוונה בזה כי אם ישראל יהיו בגדר שיהיו נקראים יעקב לא יאיר להם אלא משיח בן דוד אבל משיח בן אפרים ימות במלחמה ראשונה שיהרגנו רומילוס כאומרם ז''ל (סוכה נב.), אבל אם ישראל יהיו כולן צדיקים שבשם ישראל יתכנו אז אפילו אותו שבט שהוא משיח הבא מאפרים **וקם** פירוש תהיה לו תקומה לפני אויביו ולא יהרגנו רומילום. ותמצא שציוו גדולי ישראל (ע''ח שער העמידה) לכוין בתפלתנו כשאנו אומרים לישועתך קוינו וגו' לבקש רחמים על משיח בן אפרים שלא יהיה נהרג במלחמה:
@858 **ואומרו ומחץ וגו'**. יתבאר על פי דבריהם (ב''ר פמ''ד) שאמרו כי ג' עמים אשר אמר ה' לאברהם לבד מהז' שכבר הגיעו לפרק השג יד ישראל הם עמון ומואב ואדום, והם הרמוזים במאמר קיני קניזי קדמוני, והוא אומרו **ומחץ פאתי מואב** פירוש המשיח האמור יאבד מואב ולא ישאיר לו פאה בכל זויותיו, ולזה דקדק לומר פאתי:
@858 **או** ירמוז שיקדים דוד וימחצם וימדדם ומלך המשיח יאבד פאותיו הנשארים מהם, וכנגד עמון אמר **וקרקר כל בני שת**, ויחסם לשת לפי שהם חשופי שת, ולפי ששמם יש בו מדת בושת אמר וקרקר ולא אמר ומחץ:
@858 **או** יכוון הכתוב לכללות כל האומות שכולן באו משת ומכללם הם עמון, וטעם שפרט מואב לפי שהם שלחו אחריו ועמהם הוא מדבר לזה ביאר הדברים הנוגעים להם בפרטות. ואם תאמר והלא אין לישראל אלא עשרה אומות ולמה אמר כל בני שת, הוא מה שגמר אומר **והיה אדום ירשה** וגו' ומעתה כל בני שת שבאו לזכותם יטהרו לנו באדום, ולזה **וקרקר כל בני שת** ולא אמר ומחץ כי לא יתאבדו כל האומות לעתיד לבא, ועליהם נאמר בנבואה (ישעי' סה) הנער בן מאה שנה וגו':
@860 **אויביו**. פירוש אדום ושעיר, ואומרו **ירשה** פירוש שלא תבנה עוד ולא תהיה להם תקומה כשאר האומות שיחיו מהם כאמור, ונתן טעם לפי שהם אויבי ישראל דכתיב (תהלים קלז) זכור ה' לבני אדום וגו' לזה מכתם יתירה על כל בני שת:
@860 **וישראל עושה חיל**. פירוש באמצעות איבוד אדום ושאר בני שת יעשו ישראל חיל. פירוש אשר בלע ס''מ ושאר העמים יוציאו בולעו מפיו, ולפי שניצוצי הקדושה הם מלוכלכים כשהם תוך הקליפה וכשהם מתבררים ויוצאים ממנה הם נתקנים לזה אמר **עושה חיל** לשון תיקון לחיל אשר היה בלוע בהם:
@861 **וירד מיעקב**. ראב''ע אמר שעל יואב הוא אומר, ורש''י ז''ל פירש על מלך המשיח, ודבריו עיקר כי לדברי ראב''ע היה לו להקדים מאמר זה למאמר והיה אדום ירשה שהוא ענין המשיח, ולדברי רש''י ז''ל הגם שכבר אמר וקרקר כל בני שת וכלל כל שיצאו משת בן אדם הראשון, בא לומר שהגם שישארו מהאומות אחר וקרקר וגו' כמובן גם כן ממשמעות וקרקר שלא יאבד כולם כמאמרם ז''ל (פסחים סח.) אף על פי כן לא תהיה ממשלה מהם אלא מיעקב, והוא אומרו **וירד** פירוש לשון מלכות מיעקב פירוש מיעקב לבד תהיה, ואומרו **והאביד שריד מעיר** פירוש לא מלך לבד הוא שיהיה מיעקב ולא מהם אלא אפילו שריד שהוא ממשלה למטה מהמלכות יאבד מהם ולא ירים מהם עוד ראש:
@862 **ראשית וגו' ואחריתו וגו'**. פירוש ראשית גוים שנצטוו ישראל לאבד לא נצטוו תחלה אלא על עמלק שכן כתיב (שמות י''ז) כתוב זאת זכרון וגו' מחה אמחה את זכר עמלק, וזה היה סמוך ליציאתם ממצרים, והיו לוחמים והולכים בו, שאול עשה בו מה שעשה, בימי מרדכי עשו בו ישראל מה שעשו, ואמר **ואחריתו** וגו' פירוש לא יעמוד על פרק סוף הכליון אלא עדי אובד פירוש עד שהמלך המשיח יאבד האומות אז תהיה אחריתו של עמלק להכרית. או ירצה על זה הדרך **ראשית גוים** פירוש ראשית לשון מעלה וחשיבות הוא עמלק לכל הגוים ויהיה עומד במעלה זו עד שיגיע לפרק כליונו, והוא אומרו **ואחריתו** פירוש גם כי יהיה ראשית גוים עדי אובד, ויש שבח לישראל שיגיע בידם בפרק גדולתו, וכן אמר **וצים מיד כתים** וגו' **וגם הוא עדי אובד** יהיה לישראל למנה:
@863 **וירא את הקיני וגו'**. זה יתרו, וכוונת המאמר היא על דרך אומרם ז''ל (ב''ב טו.) איתן זה אברהם, ואברהם היה גר צדק ראשון ועל שמו נקראים כל הגרים אברהם, ואמרו ז''ל (שמו''ר פכ''ז) שיתרו נתגייר, לזה אמר **איתן מושבך** פירוש מושבך הוא כנגד אברהם שנקרא איתן, ואומרו **ושים בסלע** וגו' פירוש ועוד לך ששמת קנך בסלע פירוש קנך הוא בתו שנתן למשה, ויחס משה לסלע לפי שהיה תקיף בתורה ועז מלך, גם סלע ירמוז לתורה כאמור בספר הזוהר (תיקונים כא) ונקרא משה על שמה:
@864 **כי אם יהיה לבער וגו'**. פירוש נסתכל בקורות אשר יכולין להגיעו לקיני ואמר עד מה פירוש עד מה יהיה שיעור אשר תבואנה עליו מהצרות, **אשור תשבך** פירוש שישלוט עליו אשור שהוא סנחריב ויוליכנו בשביה:
@865 **מי יחיה משומו אל**. רז''ל (סנהדרין קו.) דרשו בזה ב' דרשות יעויין שם דבריהם, ונראה לי הכתוב על פי הקדמה מדברי הזוהר כי סיבת גליות ישראל הוא לברר ניצוצות הקדושה אשר שם נתונים ביושב הארץ ההיא, והוא מה שרמזו בפסוק (קהלת ח) עת אשר ישלוט האדם באדם לרע לו פירוש לרע לו לשולט כי יתברר ממנו חלק הטוב ויגמר בו חלק הרע שיש בשכנגדו בנשלט, וכבר הקדמנו פעמים רבות כי בהעדר חלק הטוב מהאדם זה הוא כליונו כי הוא דבר המעמיד והמחיה כי בחינת הרע מת תקרא, ומעתה יכוין הכתוב על זה הדרך לפי שקדם והזכיר שבית אשור הודיעה רוח הקודש מעשה שבית עם קדושו שהם גולים בארצות, ואמר אוי לאומות **משומו אל** פירוש האויב יסובב להם שימת אלה בתוכם כי כל מקום ישים ה' ישראל שמה הם מוציאים מהם כל ניצוצי הקדושה המעמידם והמחיה אותם, והוא מאמר עצמו עת אשר ישלוט וגו' לרע לו של השולט:
@867 **ויקם בלעם וילך**. פירוש לא פנה לבית אכסנייתו אלא הלך תכף ומיד, והוצרך לומר **וילך וישב למקומו** ולא הספיק לומר וילך למקומו להעירך שהלך בקומו ולא נתעכב, שאם היה אומר ויקם וילך למקומו היתה הכוונה שמודיעך ב' דברים, א' ויקם, ב' וילך למקומו, ואין ידוע אם בקומו הלך לזה אמר ויקם וילך להעירך שהלך בקומו, ומודיעך עוד שחזר למקומו כאשר אמר לו בלק, ואומרו **וגם בלק** הלך וגו' פירוש שלא עמד עמו ללוותו בקומו מלפניו:
@867 **עוד** אפשר שבלק גם הוא לא עמד עוד במלכותו שם לפי שידעו מואב מדברי בלעם כי עם בני ישראל לא יריעו ולא ישחיתו להם אם כן בהבטל הסיבה יבטל המסובב והעמידוהו ממלוך עליהם והלך לדרכו שבא בו למדין, והראיה ששם נמצא במלחמת מדין ונהרג:
@868 **וישב ישראל בשטים וגו'**. צריך לדעת מה צורך בהודעת מאמר זה, ורז''ל (מד''ר ותנחומא) העירו בזה ואמרו כי להודיעך בא כי זה סיבה לזנות וכו' לפי שהמקום מטבעו לעורר טבע התאוה הבהמית, ונראה לפרש שהכתוב יעיד סיבת הזנות שהיתה לפי שיצאו העם לטייל חוץ למחנה ישראל ושם נמצאו בנות מואב, והוא אומרו **וישב ישראל בשטים** פירוש במקום שהיו מטיילים בו חוץ למחניהם, ושטים הוא לשון טיולים כדרך אומרו (יא ח) שטו העם ופירש''י שם וזה לשונו אין שייט אלא לשון טיול, וזה סיבת ויחל העם לזנות:
@868 **ויחל העם לזנות אל בנות מואב**. אומרו **ויחל** לשון חילול שנתחלל לזנות פירוש לפי שזנו אחרי אלהי נכר, ואמר **אל בנות** וגו' פירוש על דרך אומרם ז''ל (מד''ר ותנחומא שם) שהיו תובעים אותם לעבירה והיו אומרים להם השתחוה לזה וגו' והיו משתחוים אל אשר היו אומרים להם בנות מואב, והוא אומרו אל בנות וגו', ודקדק הכתוב לומר **העם**, לשלול הצדיקים אשר בשם ישראל יתכנו:
@869 **ותקראן לעם**. הוצרך להזכיר העם ולא הספיק לומר ותקראן להם, נתכוון לומר שקראו לאותם שלא יצאו לשוט מאהליהם הלכו הם אצלם וקראו להם, או ירצה כי מלבד מה שהיו הולכים אחד אחד הוסיפו לקרוא להם שילכו בכנופיא לזבחי אלהיהן וכו':
@869 **לזבחי אלהיהן**. והגם שאמר (שם) שפעור אין בעבודתו זביחה אלא בהתרזת הלכלוך למול פניו ומן הסתם לא זבחו לו, אולי שהיו עושים שמחה בבשר לכבודו, או אולי שהיו עושים כן כדי להרבות במאכלים להתריז כנגדו בריבוי יציאת הטינוף:
@869 **וישתחוו וגו' ויצמד**. פירוש זו סיבת השתחווייתו שנצמד וגו'. על דרך אומרם ז''ל (שם) שבעל פעור מאניס ע ובדיו:
@871 **וישוב חרון וגו'**. הוצרך להשיב חרון גם אחר עשות משפט, לפי שהבית דין של מטה אין מענישים אלא לעושים בעדים והתראה ואם יעשה ה' משפט יגוף גם עושים בלא עדים ובלא התראה וכשיצא המשחית ישחית גם לחושבי מחשבות רע, לזה אמר להם לעשות משפט ובזה ישוב חרון אפו לבל ישחית עובדיה בלא עדים ובלא וכו' וישובו ויחיו:
@875 **וידקר את שניהם וגו'**. קשה בשלמא דקירת איש ישראל כמשפט ההלכה שקנאים פוגעים בו אבל האשה אינה חייבת מיתה ואינה מצווה, ואם על חששת היותה אשת איש לא היתה נהרגת על הספק, ואפשר שדן בה משפט הבהמה דכתיב (ויקרא כ) ואת הבהמה תהרוגו, וכתיב (יחזקאל כג) אשר בשר חמורים בשרם. ואם תאמר למה לא הרגו ישראל המדינית מקודם כיון שהיו מעם שלא נצטוו עליהם, ואפשר לפי שעדיין לא שלחו להם ישראל קריאת שלום, והגם שלבסוף גם כן לא שלחו להם, זה היה אחר מעשה כי צוה ה' צרור וגו', או אולי שלא היו מכירים אותה וחשבו כי היא מואבית ולא מדינית שהרי לא היו רגילים אצלם להכירם, או היה מלבושם כמלבוש מואב, ואומרו המדינית, הוא דברי הכתוב:
@875 **חסלת פרשת בלק**
@877 **לאמר**. צריך לדעת למי יאמר, אם לפנחם לא היה צריך לומר אחר כך לכן אמור שכבר אמר שיאמר לו הדברים, ועוד סדר הדברים יגיד שלא כן הוא:
@877 **ונראה** שנתכוון בזה שיאמר לישראל דברים הנאמרים בענין, והכוונה כדי שיכירו מפעל טוב שעשה להם פנחס ולא ישנאוהו בשביל הריגת הנשיא ובמה שנמשך מסיבתו שחבט המלאך מהם מה שחבט כאומרם ז''ל (סנהדרין פב:) כאשר אבאר בסמוך:
@878 **פינחס בן אלעזר וגו'**. צריך לדעת למה הוצרך ליחסו, ואולי שנתכוון שיזכרו אבותיו לטובה, ועוד נראה שנתכוון להשלים ישראל עם אהרן שסבב נפילה גדולה מישראל באמצעות העגל דכתיב (שמות לב) ויגוף ה' את העם על אשר עשו את העגל אשר עשה אהרן הרי עמד פנחס בן בנו ופדה נפש כל ישראל כאומרו בסמוך ולא כליתי את בני ישראל, ולזה יחסו עד אהרן, ותמצא שאמרו ז''ל במדרש (תדאר''ר פי''ג) שהיה אהרן עומד ומתקן והיה מלמד כל ישראל תורה ומעשים טובים וכו' עד כאן, הא למדת שהיה נחשב על אהרן הקלקול שגרם במיתת עם רב והיה מבקש לתקן מה שנפרץ, וכאן רמז ה' כי פנחס שלם במדה טובה מרובה:
@878 **השיב את חמתי**. כוונת הודעת דבר זה אולי שבא לומר לו שלא יחשוב שה' השיב את חמתו בלא אמצעות זכות אשר כפה מדת הדין, ויצא מזה שיחשוב משה כי ה' מתנהג בסדר זה, לכן הודיע ה' כי פנחס הוא שהיה סיבה להשיב חמה, והוא אומרו **השיב את חמתי** ולא מעצמה שבה:
@878 **מעל בני ישראל**. פירוש אחר שיצתה החמה והיתה עליהם השיבה מעליהם וזה שבח גדול. עוד נתכוון לומר מעשה הטוב בגדר הפעולה עצמה שהסיר כעס ה' כי הכעם הוא ענף היגון והדאבון ויהיה לה' נחת רוח הרבה מהשבת חמה:
@878 **בקנאו את קנאתי בתוכם**. דקדק לומר **קנאתי**, גם אמר **בתוכם**, בא לתת כח המשיג בו השבת חמה, ואמר שהיתה באמצעות ג' דברים. הא' שקינא בכבודו ובעצמו וסכן בעצמו כאמור בדבריהם, והוא אומרו **בקנאו** בכינוי. ב' שהיתה הקנאה בשביל כבודי לבד לא לאמצעות שום דבר זולתו, וזו היא מצוה שלימה אשר יתרצה ה' בה יותר מכל אשר יעשה האדם, והוא אומרו **את קנאתי** בכינוי להמדבר ברוך הוא. ג' שלא היתה הפעולה שעשה נעלמת מעיני אדם אלא קדש ה' בתוך קהל ועדה, כאומרם ז''ל (סנהדרין פב.) שהיו כל שבט שמעון סביב לאהל אשר שם דקר שניהם והרג נשיאיהם בפניהם, והוא אומרו בתוכם:
@878 **ולא כליתי וגו'**. צריך לדעת למה כתב הסיבה שהיא בקנאו את קנאתי בתוכם באמצע ב' פרטי המסובב שהם השיב את חמתי ולא כליתי וגו' שהיה לו לומר על זה הדרך בקנאו וגו' השיב וגו' ולא כליתי וגו', או על זה הדרך השיב וגו' ולא כליתי וגו' בקנאו וגו', אכן נתכוון להעיר כי השבת החמה אחר שהיתה על בני ישראל גדר זה לא הושג אלא באמצעות ג' הדרגות עליונות הרשומים בענין כמו שפירשתי בפסוק בקנאו וגו', אבל לגבי מניעת הכליון שאמר ולא כליתי אפשר שהיה גם כן ה' משאיר פליטה לעמו הגם שלא היה במעשה כל ג' מעלות האמורות בענין, ובאמצעות תפילת צדיק וכדומה מהזכות יאמר ה' למלאך המשחית רב וגו', גם לפי מה שפירשתי באומרו השיב את חמתי שהוא דבר טוב בגדר הפעולה מצד עצמה בהכרח לומר הכתוב בסדר זה, כי אם היה אומר השיב וגו' ולא כליתי ואחר כך יאמר בקנאו היה נשמע כי תכלית ענין זה של השבת חמה הוא הנמשך ממנו שלא כילה את בני ישראל ואין מובן שיש מפעל טוב בהשבת חמה מצד עצמה, אבל מאומרו השיב את חמתי ואמר סמוך לה סיבת הדבר שהוא בקנאו וגו' זה יגיד שכבר הודיע תכלית מפעל הטוב:
@879 **לכן אמור**. צריך לדעת למה הוצרך לומר לכן אחר שאומר בסמוך תחת אשר קנא שהוא גם כן משמעות מאמר לכן, ובהכרח לומר שהוא לשון שבועה כאומרם ז''ל (שמו''ר פ''ו) אין לכן אלא שבועה דכתיב (ש''א ג') לכן נשבעתי לבית עלי, ועדיין צריך לדעת למה הוצרך לשבועה, ולזה יש לומר כי הוצרך לשבועה לחזק ברית השלום הגם שלא יהיו בניו ראוים לדבר זה יקיים ה' את השב ועה:
@879 **עוד** יתבאר הכתוב על פי דבריהם ז''ל (זבחים קא:) שאמרו כי קודם מעשה זמרי לא נתכהן פנחס לפי שהיה מצוי ולא נמשח ואחר שעשה קנאתו היתה לו הכהונה, והנה יש באופן זה ב' דרכים, א' הוא דרך מחילה, והב' דרך מתנה, דרך מחילה הוא שימחול לו ה' הקנם שקנסו שלא נמשח בזמן משיחת הכהנים, ודרך מתנה הוא שיתן לו הכהונה מחדש כדרך שנתנה לאהרן הגם שאביו ואחיו לא היו כהנים, וכפי הדין יש הפרש בין אם יהיה הדבר דרך מחילה לדרך נתינה, דרך מחילה אינה צריכה קנין ודרך מתנה צריכה קנין וכל עוד שלא קנו מידו לא זכה המקבל במתנה אלא במה שכבר הגיעו:
@879 **עוד** יש בדרך מתנה ב' רעות מה שאין כן אם תהיה דרך מחילה, כי בדרך מחילה אם ימחול לו על הקנס ויחזור לכהונת אהרן אף הוא בטלו המעוררים על כהונתו כדרך שבטלו על כהונת אהרן שממנו בא, מה שאין כן בדרך מתנה שישנם למעוררים עליו כדרך שהיו על אהרן בתחילה, ומה גם שהיה להם שנאה עמו לסיבת הריגת הנשיא וכו', ב' שבדרך מתנה יש מקום לומר שהדבר חידוש ואין לך בו אלא חידושו, מה שאין כן אם יהיה בדרך מחילה וחוזר לכהונת אהרן שחוזר הדבר לשורשו וצאצאיו כמותו, נמצאת אומר כי בג' דרכים דרך המחילה הוא הנאות מדרך המתנה, א' שאין צריך קנין. ב' שאין לחוש למעוררים. ג' שתהיה נמשכת לו וליוצאי חלציו:
@879 **והנה** האדון ה' נראה בעיניו ברוך הוא לרומם מעלת פנחס לעשות הדבר בדרך מתנה שיהיה כהן מצדו ולא מצד הענף שבא ממנו לתפארת לו, והוא אומרו **הנני נותן לו** בדרך מתנה, ותקן אלהי עולם כל הג' דברים שיש בהם פקפוק כשיהיה דרך מתנה כמו שאמרנו, כנגד מה שאמרנו מתנה צריכה קנין אמר לכן לשון שבועה, וכנגד חשש המעוררים אמר **הנני נותן לו את בריתי שלום**, וכנגד מיחוש שאין הדבר אלא לפנחס וחידוש הוא אמר **והיתה לו ולזרעו אחריו** וגו' שמתנה זו נתקיימה בידו בשבועה מפי הבורא שתהיה לו לשלום ולזרעו אחריו כהונת עולם, וכבר העירותיך בב' ובג' מקומות שהכהונה היא נפש הנקראת כן במקום הנשמות, והבטיח ה' את פנחס כי ישתלשל בזרעו ענף זה הקדוש הנקרא כהונה, והוא סוד אומרו כהונת עולם:
@880 **תחת אשר וגו' ויכפר וגו'**. נתן טעם למה שבחר לו יה לזכות הכהונה לפנחס בתורת מתנה מה' ולא מכח אביו, אמר **תחת אשר קנא לאלהיו** הוא עשה לאלהיו וחש על כבודו גם אלהיו ירוממהו באין צורך לו ליהנות ביקרו מיקר אביו, וכנגד מה שאמר שתהיה לו שלום וגם תהיה לזרעו וגו' אמר **ויכפר על בני ישראל** פירוש שעשה שלום בין ישראל ובין אביהם שבשמים והניח לישראל מחמת מלך מלאכי מות לזה יהיה לו ברית השלום מהם, וכשם שההטבה אשר הטיב בכפרת בני ישראל היא הטבה נמשכת שכל דור ודור הבא בא מכח הראשונים אשר כיפר עליהם ולזה כמו כן תהיה נמשכת הטבתו גם כן והיתה לו ולזרעו אחריו ברית כהונת עולם:
@880 **ובדרך** רמז יתבאר על פי דבריהם ז''ל (במד''ר פכ''א) שאמרו פינחס הוא אליהו אשר הוא עתיד לבשר עם בני ישראל בגלות האחרון, וכאן הודיע הכתוב במה זכה למעלה זו להשיב לב בנים על אבות, ואמרו ז''ל (עדיות פ''ח מ''ז) אין אליהו בא אלא להרבות שלום בעולם, והוא אומרו **פינחס** וגו' **השיב** וגו' **בקנאו** וגו' כפל לומר ב' קנאות לרמוז לקנאה שקנא בזמן זה ולקנאה שקנא פעם ב' בימי אחאב כאומרו (מ''א י''ט) קנא קנאתי לה', גם שם כפל לומר קנא קנאתי לרמוז לב' קנאות א' בימי משה וא' בימי אחאב, לכן אמר **הנני נותן לו את בריתי שלום** שהוא הברית שכרת עם האבות לתת להם עשרה עממין, וזה יקרא ברית שלום כי אז יהיה שלום בכל העולם דכתיב (ישעי' יא) ופרה ודוב תרעינה וגו' לא ירעו ולא ישחיתו וגו', ברית זה יהיה לו כי הוא זה אשר יעשה את הדבר הזה והשיב לב בנים על אבות וגו' דכתיב (מלאכי ג) הנה אנכי שולח לכם את אליה וגו', ולזה דקדק לומר **הנני נותן לו** בפרטות ולא שתף עמו זרעו, ואחר כך אמר ברית הכהונה והיתה לו ולזרעו אחריו ברית כהונת עולם, וגמר אומר **תחת** פירוש ב' יעודים אלו הם כנגד ב' דברים שעשה, ברית שלום תחת אשר קנא לאלהיו כאן רמז במה שקנא בימי אחאב על שעזבו אלהים והיו עובדי עבודה זרה, והוא מה שדקדק לומר **לאלהיו** שנתקנא על עבודה זרה שעליה נאמר (דברים ו) כי אל קנא וגו' עד שאמרו כל העם (מ''א י''ח) ה' הוא האלהים וגו' לזה גם כן הוא יבשר ביום ההוא אשר יהיה ה' אחד ושמו אחד שהוא גם כן סוד ה' הוא האלהים, ואומרו **ויכפר** וגו' הוא כנגד יעוד והיתה לו וגו' ברית כהונת כי זה הוא לו חלק אשר כפר על בני ישראל כמו כן יהיה תמיד מכפר עליהם, על דרך אומרו (ויקרא ד) וכפר עליו הכהן:
@881 **ושם איש ישראל**. קשה ממה נפשך אם חפץ ה' לגלות המוכים היה לו להזכירם בשעת מעשה כשאמר (כ''ה ו') והנה איש מבני ישראל שם היה מקום להזכירו ולומר והנה איש וגו' זמרי וגו', וכשהזכיר גם כן המדינית היה לו להזכיר שמה, ואם תורה כסתה עליהם כדרך שכסתה על המקושש בשבת למה נמלך להזכיר שמם והוצרך גם כן להוסיף עוד תיבות יתירות בתורה שאם היה מזכיר שמם למעלה לא היה צריך לומר פ''ב ושם איש וגו' ושם האשה וגו':
@881 **אכן** הנה האדון ברוך הוא אינו חפץ לזלזל אפילו ברשעים לפרסם מי בעלי דברים המתועבים, ומקושש יוכיח, גם במה שלפנינו תראה שלא גילה אותם בשעת מעשה אלא דוקא אחר שהזכיר שבח פנחס אשר פעל ועשה מהמפעל הטוב שקנא לה' וכפר על בני ישראל זכר גם כן כי לא קנא באדם פחות אלא באדם גדול נשיא בית אב עם האשה ראש הקליפות ואביה מלך כאומרו ראש אומות בית אב ונתעבה במיתה בזויה לעין כל, ובכל כיוצא בזה שמו יתברך מתקדש, לזה יחסה לומר בת מלך היא, והגם שיש זלזול לאיש ישראל לא יגרע מצדיק עינו כדרך אומרו (משלי י) זכר צדיק לברכה הגם ששם רשעים ירקב באמצעות כן, ואולי כי להודיעך בא הכתוב שלא השיג השבת החמה וכו' אלא באמצעות דבר זה שעשה הקנאה בנשיא ונתקדש שמו קידוש גדול ונכנעה כח הס''מ ומאם העון כל כך בעיני כל בזה השיב חמה ויכפר וגו' אבל זולת זה הגם שהיה מקנא לה' באדם הדיוט לא היה משיג כל הדרגות הרשומות, ודקדק לומר **ושם האיש** ולא הספיק במאמר ושם המוכה וגו' לפי דרכינו ירצה לשון חשיבות לומר כי היה חשוב ומעולה בישראל ועל כל זה לא נרתע צדיק זה מעשות בו מעשה הנפלא, עוד נראה כי טעם שלא הזכיר ה' שמו למעלה לפי שעדיין לא עשה מעשה אלא חשב לעשות, וכל עוד שלא עשה לא תבזהו התורה להזכיר שמו, ואחר שכבר עשה מעשה פרסם ה' שמו כי מצוה לפרסם הרשעים:
@881 **המוכה אשר הוכה וגו'**. צריך לדעת למה כפל לומר **המוכה אשר הוכה** ולא הספיק באחת מהנה, גם צריך לדעת למה שינה הכתוב מטבע המאמר שהתחיל לדבר בו כשהזכיר שם ישראל שהקדים לומר איש ישראל ואחר כך אמר המאורע המוכה וגו' וכשהזכיר המדינית הקדים המאורע ושם האשה המוכה ואחר כן אמר המדינית:
@881 **אכן** יתבאר הענין על פי דבריהם ז''ל (ברכות יח:) שאמרו שהרשעים בחייהם קרויים מתים, והטעם הוא לפי שכח הרע שהוא בחינת המת דבוקה בהם, וכבר כתבתי בכמה מקומות כי השם שיקרא בו האדם הוא שם הנפש, וה' שם שמות בארץ כאומרם ז''ל (שם ז:) אל תקרי שמות אלא כו', וכשאדם חוטא נפגמה נפשו בדביקת הרע בחינת המרקיב, והוא אומרו (משלי י) ושם רשעים ירקב, ולזה היה רבי מאיר בודק בשם (יומא פג:) לראות אם בעל נפש ישרה הוא, והנה זה אשר בעל ארמית השחית נפשו בפגעו בה והנה הוא מוכה מכת מות קודם שהרגו פנחס, והוא מה שנתכוון הכתוב לומר **ושם איש ישראל המוכה אשר הוכה** וגו', כנגד הכאת הנפש אמר ושם איש ישראל המוכה שמעת אשר געל נפשו ובא עליה הוכה מכת נפש הישראלית שהיא כינוי נפש קדושה הנקראת ישראל, וכנגד הריגתו שהרגו פנחס אמר אשר הוכה את וגו' כאומרו (כ''ה ח') וידקור את שניהם, או על זה הדרך המוכה פירוש שהכהו פנחס, **אשר הוכה את המדינית** הוא הכאת הנפש שרשם בתיבת איש, וידויק על נכון גם כן אומרו **הוכה** את המדינית, כי לפי ששכב אותה הוכה בנפשו, וכפי זה שיעור תיבת אשר הוכה פירוש שכבר הוכה את המדינית פירוש להיותו אתה:
@881 **עוד** רמז באומרו **את המדינית** על דרך אומרו (בראשית לט) ולא שמע אליה לשכב אצלה להיות עמה ואמרו ז''ל (יומא לה) לשכב אצלה בעולם הזה להיות עמה לעולם הבא, והוא אומרו **הוכה את המדינית** שהכאתו היא שיהיה אתה עמה בעולם הבא כי מן הסתם מת שלא מתוך תשובה שהרי דקרו בשעת מעשה, ובזה נתיישב מה שדקדקנו למה כפל המוכה אשר הוכה, גם טעם שהקדים לומר איש ישראל קודם אומרו המוכה כדי שיהיה חוזר אומרו' המוכה על השם לומר שההכאה באה לו גם בשם איש ישראל שהיא ענף הקדושה, ולזה כשהזכיר המדינית לא הזכיר בה אלא הכאה אחת דכתיב ושם האשה המוכה גם לא הקדים זכרונה קודם זכרון ההכאה כי בחייה קרויה מתה ושמה מוכה ועומד כרשום בתיבת מדינית, וכבר כתבנו בכמה מקומות כי שם עובדי כוכבים ומזלות הוא שם הקליפות שכולן הם בחינות המיתה:
@881 **עוד** יתבאר על זה הדרך על פי מה שקדם לנו מדברי המקובלים שלא ידח נדח מכל ניצוצי הקדושה וכלן לבסוף יזכו למקום שממנו באו והגם שיריע איש ישראל אף יצריח נפשו סוף כל סוף יחזור לשורשו, והוא אומרו **ושם איש ישראל** הרי שאפילו אחר מעשה בשם ישראל יכונה הא למדת שלא נעקר משורשו, **המוכה** פירוש שהכה פנחס מודיעך הכתוב שלא הוכה באבדון נפשו אלא אשר הוכה את המדינית פירוש אותו החלק הרע שנדבק בו מאת המדינית שיתכנה אליו שם הכאה הוא שהוכה ומת באמצעות הכאת פנחם, הא למדת שיצא הפסדו מה שהפסיד בעבירה נפרע ממנו העון בהכאתו של פנחס שהרגו ומיתתו כפרתו. או על זה הדרך שלא הוכה בנפשו אלא כשהיה עמה אבל אחר שנבדל ממנה לא נשאר בו רושם החטא כי הוא נבדל במיתה ומיתתו טהרה נפשו, ובזה נתן טעם למה קראו איש ישראל כי אחר הריגה בשם ישראל יכונה, זה כתבתי אם אפשר:
@882 **המדינית**. אמר בה''א הידיעה, נראה לומר כי לא היתה אשה אחרת מדינית במופקרות זולתה, ולזה גם כן בפרשת בלק (כ''ה ו') כשהזכיר ויקרב אל אחיו אמר את המדינית בה''א הידיעה לומר אותה מדינית שהיתה במופקרות, וכפי זה לא הפקירו מדין בנותיהם, ואם היו המדיניות במופקרות היה ה' מצוה עליהם להורגם, וכן תמצא כשאמר הכתוב (שם א') ויחל העם לזנות אל בנות מואב, הא למדת כי המופקרות מואביות היו, וטעם שלא הפקירו מדין בנותיהם, לפי שלא היו בטוחים מהם כמואביות כמו שכתבתי למעלה (כ''ד י''ד) בפסוק אשר יעשה וגו' באחרית הימים, וזו שיצתה טעמה בצדה להיותה בת בלק השונא הגדול אשר שכר עלינו את בלעם בן בעור וקבל עצתו והפקיר בתו, מה שאין כן אנשי מדין קטן וגדול לא הפקירו:
@882 **ובזה** מצאתי נחת במאמר חז''ל (במד''ר פכ''א) שאמרו כי צור שנהרג עם נסיכי מדין הוא בלק ובשביל שהפקיר בתו הורידוהו מגדולתו שהיה ראש לכלם דכתיב ראש אומות ועתה מנאו ג' למלכי מדין, וצריך לדעת מי גילה סוד זה כי צור הוא בלק, ולדברינו יש טעם נכון לומר כן, כיון שלא מצינו אלא מדינית אחת כאן הבן שואל מה נשתנית מדינית זו שיצתה מכל בנות מדין, אלא ודאי כי הוא זה בלק אשר שכר עלינו בלעם ויעצו וקיים עצתו בבתו והוא צור שזלזל בכבודו לקיים עצה רעה של בלעם, ואולי שלא רצו מואב להפקיר בנותיהם עד שקדם בלק שהיה אז מלך עליהם והפקיר בתו, והגם שכתבתי למעלה שלא עמד במלכותו אחר שהודיעם בלעם שלא יריעו ולא ישחיתו למואב, תיכף ומיד קיים העצה והלך לו לעירו ובזה הפקירו מואב בנותיהם, וזולת זה איך יתכן שישתנה צור מכולן:
@882 **אלא** שבא לידי מדרש (ילקוט מטות) וזה לשונם הן הנה מלמד שהיו מכירין אותם ואומרים זה לזה זו היא שחטא עמה פלוני עד כאן, כפי מדרש זה לא אחת ולא שתים היו, ואפשר לומר שמדין לא הפקירו מבנות הגדולים אלא מהמוניהם ולזה הורידו בלק שהפקיר בתו והוא היה מלך, ולדרך זה אומרו **המדינית** פירוש המכובדת שבכולן שלא יצאה ממדין בת מלך אלא היא, ולדרך זה יתאמת לנו מה שפירשתי בסוף פרשת בלק שישראל לא היו מכירין אותם שהרי היו שם מדיניות הרבה, ולא אמר הכתוב (כ''ה א') אלא ויחל העם לזנות אל בנות מואב ולמה לא הזכיר גם בנות מדין, הא למדת שהיו כלן בעיניהם בנות מואב שזולת זה היו הורגים אותם מתחילה ויטלו ממונם או לבסוף אחר מעשה פנחס היה להם להרוג בנות מדין אלא שהיו כל הנשים בחזקת בנות מואב:
@882 **במדין הוא**. מאמר זה קשה המשמעות, אם כוונתו לומר שהוא ראש אומות של מדין היה לו לומר ראש וגו' בית אב למדין, כי שיעור תיבת במדין הוא משמע שמודיענו מקומו ואין ידוע הכוונה בזה. ונראה שהכוונה היא לפי שאמר צור ראש אומות על בלק יאמר האומר והלא בלק מלך מואב היה שהמליכוהו עליהם, לזה הודיעך הכתוב ואמר לא כמו שאתה חושב שנשאר מלך למואב אלא כבר נגרש מהם וחזר למקומו, והוא אומרו **במדיז הוא** פירוש באותו מצב שהיתה מופקרת בתו היה במדין, ועיין מה שפירשתי בפסוק (כ''ד כ''ה) וגם בלק הלך וגו':
@884 **צרור את המדינים וגו'**. צריך לדעת למה כפל **צרור והכיתם**, ורז''ל הרגישו ואמרו (במד''ר פכ''א) כי נתכוון בזה לומר שהגם שצוה ה' (דברים כ') כי תקרב אל עיר וגו' לא תשחית את עצה וגו' זו אומה קלה ובזויה להשחית את עצה וגו' עד כאן, וצריך לדעת מה נקמה היא זו למדין ואדרבה היה להם לקיים, (שם) ואכלת את שלל אויביך שזה הוא להם יותר נקמה ודאבון נפש, וכיוצא בזה מצינו בקללות התורה (ויקרא כו) ואכלוהו אויביכם:
@884 **עוד** צריך לדעת אומרו **כי צוררים** למה הוצרך לנתינת טעם, ולפי דברי רז''ל שאמרו שבא לומר ישחיתו עצה וכו' יש לנו מקום לומר שבא לתת טעם לביטול מצות לא תשחית וגו' במקום הזה כי צוררים, ובתנחומא אמרו וזה לשונם צרור וגו' למה כי צוררים וגו' מכאן אמרו הבא להורגך וכו', ולדברי תנחומא בא הכתוב להודיעך משפט הבא וכו' וזה דרך דרש:
@884 **ונראה** לפרש בהעיר למה צוה ה' מצוה זו שלא בזמנה, כי מצינו שאחר כך הוצרך ה' לצוות לומר (ל''א ב') נקום נקמת בני ישראל מאת המדינים הא למדת כי מאמר זה לא היה בזמן הנקמה:
@884 **אכן** נתכוון ה' במאמר זה לתקנתם של ישראל, לפי שכל אשר יטעום טעם חטא הטבעי השולט באדם שלא לרצונו לו יהיה שלא טעמו אלא בבחינת החושב קשה הוא להפרידו, וכמו שהארכתי בפרט זה בפרשת אחרי מות (ויקרא יח) בפסוק כמעשה ארץ מצרים וגו', וכל עוד שלא נפרד, מהחוטא תאות הדבר ותשוקתו אליו הוא מושלל מהכפרה, וכמו שפירשתי בפרשת בראשית במה שאמר הכתוב (שם ד') ואליך תשוקתו ואתה תמשל בו, ומה שלפנינו עם בני ישראל טעמו עריבת הזנות מהם במעשה מהם במחשבה, גם נדבקו בפעור דכתיב (כ''ה ג') ויצמד ישראל לבעל פעור ואמרו רז''ל (במד''ר פ''כ) שנעשו כצמיד וכו' עד כאן, וחפץ ה' לרפאותם בעצת ה' הנכונה כדי לסלק מעליהם המגפה, שהלא תמצא שהיתה המגפה בישראל עד אשר ספו תמו כל הנצמדים לבעל פעור דכתיב (דברים ד) כי כל האיש אשר הלך אחרי בעל פעור השמידו ה' אלהיך מקרבך, ובהכרח אתה לומר כי לא על הכ''ד אלף שאמר הכתוב (סו''פ בלק) ויהיו המתים וגו' ארבעה וגו' הוא אומר שאלו היו משבט שמעון ומתו על שרצו לשלוח יד בפנחס כמאמרם ז''ל (במד''ר פ''כ) והכתוב אומר אשר הלך אחרי בעל פעור השמידו וגו' הא למדת שהשמיד גם כל הזונים לבד הכ''ד אלף, גם ממה שאמר הכתוב כאן המוכה ביום המגפה על דבר פעור זה יגיד שמתו מישראל לבד אותם שמתו בשביל פנחס שרצו לשלוח בו יד:
@884 **והגם** שנשכיל בעיקר הסיבה אשר סבבה מעשה פנחס, לא היה אלא זנות זמרי כי לא הרג פנחם לזמרי על עבודה זרה, אלא ודאי שהמגפה היתה שולטת בזונים, והגם שאמר הכתוב ויכפר על בני ישראל, פירוש שלא כילה כל העם מהם בשביל מחשבת עבודה זרה מהם בשביל הערבות ולעולם ה' לא ויתר על הזונים ויעץ ה' ואמר צרור את וגו', הכוונה בזה להקדים לשנוא המחטיאים גם להתעיב הערב והטוב הבא מהם לאבד כל עץ נחמד וכל מעיין מתוק וכל טוב הבא מהם על אשר גרמו להם עשות רע, והוא על דרך אומרו (תהלים קל''ט) הלא משנאיך ה' אשנא פירוש משנאיך כאלו אמר משניאיך שגורמים לשנאת בחור בטוב כדרך שדרשו ז''ל (שבת קיד:) בפסוק כל משנאי אהבו מות אל תקרא וכו', ובאמצעות מחשבה זו תהיה מתרחקת תאות העבירה מהם ותהיה להם לזרה כי על העבר שונאים הסובב ויולד בהם טבע אלהיי, ומדה זו מדה סגוליית היא לחפץ בחיים, ובזה יתכפר עון הקודם במחשבת עבודה זרה גם בארס תאות הניאוף ולא יהיה בהם נגף:
@884 **והוא** מאמר הכתוב כאן **צרור את המדינים** פירוש יהיו לכם בגדר צר ואויב לשנאתם ולשנא כל הערב מהם להשחית עצם ולקלקל מעינותיהם זה תמורת מה שהתאוו להם, וזו היא אחד מתקוני התשובה, ואמר **צרור** לשון הווה פירוש יגבירו בהם השנאה עד גדר שיהיה נקבע בהם טבע הצרירות, ואמר **והכיתם** אותם פירוש תחכו ליום נקם שתכו אותם, ולזה לא אמר והכו אותם כי אין זמנו עתה, ואמר **כי צוררים** וגו' הכוונה בזה לומר תנאי הוא הדבר שהשנאה ואויבות שתהיה לכם לא על שסבבו נפילה מישראל שאם כן נאבדה הכוונה של תיקון החטא אלא כי צוררים הם וגו' **על דבר פעור** אשר החטיאו אתכם בעבודה זרה **ועל דבר כזבי** וגו' שגרמו לכם להכשל בזנות, וטעם שתלה פרט זה בכזבי לבד לפי שהיא בת מלך והזכיר הגדולה, גם לפי שזנותה היה בפרסום, ואפשר שעל פיה היו כל המופקרות:
@884 **עוד** אפשר שלזה נתכוון הכתוב במאמר **בת נשיא מדין** שלא היה צריך שכבר אמר בסמוך כזבי בת צור וגו', אלא בא לומר שלהיותה בת מלך יתפסו בשבילה כל האומה, ודקדק ואמר **אחותם** לומר הגם שיציאתה היתה ממואב אחותם פירוש אחותם בעצה שבעצתם של מדין יצתה ויחשב הדבר על כלן, ואומרו **המוכה** לומר שמסרה נפשה עליהם כאח על אחיו, ואומרו **ביום המגפה** וגו' פירוש המגפה שהיתה על דבר פעור הא למדת שביום עצמו נגף ה' ההולכים אחר פעור לבד מהכ''ד אלף שאמר הכתוב שאותם היו כלן משמעון שמתו בשביל פנחס, והכונה בעיקר המאמר להעירם בשנאה טבעית שהיו סיבה לחרות אף ה' בעם, ואין לטעות שהכונה בזה היא שישנאום בשביל המגפה, שכבר אמר כי צוררים וגו' שלא יצררו אותם אלא על דבר פעור וגו':
@887 **ויהי אחרי המגפה וגו'**. צריך לדעת למה עשה תחילת פרשה באמצע הכתוב, ולפי מה שכתבתי למעלה יש טעם נכון, שנתכוון בזה לומר כי באמצעות מצות צרור וגו' כדרך שפירשנו תקנו מחשבת עבודה זרה והטו עצמם לטבע האלהיי ובזה ויהי אחרי המגפה פירוש נסתלקה המגפה שהיתה בישראל באמצעות תיקון זה אשר צוה ה' עשות, ולזה התחיל הפרשה באמצע הכתוב לומר כי מאמר אחרי המגפה מקושר עם מה שלמעלה ממנו, וטעם שלא עשאו פסוק בפני עצמו, נתכוון גם כן לקשרו למטה שאחר המגפה אמר ה' וגו' שאו וגו', נמצאת אומר כי מאמר ויהי אחרי המגפה משמש למעלה להגיד ענין אחד, ולמטה להגיד ענין אחר:
@887 **עוד** נראה לתת טעם שהתחיל הפרשה מאמצע הכתוב על פי דבריהם ז''ל (ילקוט) שאמרו וזה לשונם ויהי אחרי המגפה שאו את ראש וגו' זה הוא שאמר הכתוב אם אמרתי מטה רגלי וגו' בשעה שקבלו ישראל התורה נתקנאו אומות העולם וכו' אמר להם הקדוש ברוך הוא הביאו לי ספר יוחסין שלכם וכו' כשבאו לשטים קלקלו וכו' אמרו האומות העטרה שהיתה בידם בטלה שוים הם לנו זקפן ה' שנגף כל מי שנתקלקל והעמידן על טהרתם עד כאן, לפי זה יש טעם בהפסקה באמצע הפסוק להעיר שהמאמר קשור גם עם מה שלמעלה בענין רעות אשר גרמו מדין על דבר פעור ועל דבר כזבי וגו' וגם **ויהי אחרי המגפה** פירוש לשון צער, והוא מה שרמז בפסוק מטה רגלי שהיו אומות העולם מזלזלים בהם שניטלה העטרה שהיתה בידם, וזלזול זה לא נחלט מישראל כשנסתלקה המגפה מהם עד שמנאם ונמצאו כל אחד מכיר אבותיו עד השבט אז נשאו ראש, והוא אומרו **ויהי** לשון צער גם אחרי המגפה, ולזה ויאמר ה' וגו' שאו, ולא החליט להפסיק לעשותו פסוק בפני עצמו וערבו עם מה שלמטה ממנו לומר כי בשביל מה שרמוז בתיבת ויהי שהוא זלזול האומות הוא שאמר ה' שאו וגו':
@887 **עוד** יש לתת טעם שהתחיל הפרשה מאמצע הכתוב על פי דבריהם ז''ל (במד''ר פכ''ג) שאמרו וזה לשונם כשיצאו ישראל ממצרים ונמסרו למשה נמסרו במנין כשקרב למות החזירם במנין עד כאן, והוא מה שנתכוון בהתחלת הפרשה **ויאמר ה' אל משה** וגו' לומר כי בלא טעם אחרי המגפה יש טעם במנין זה כדי להחזירם במנין כאמור, אלא שהיתה גם כן סיבה אחרת שהיא אחרי המגפה, ונמצאו שתי סיבות המנין נרמזות באמצעות התחלת פרשה באמצע הכתוב:
@889 **וידבר משה וגו' בערבות מואב וגו'**. יש להעיר למה הוצרך לומר **בערבות מואב**, ואם יש צורך בהודעה זו היה לו להזכירו במצות ה' כשאמר ויאמר ה' וגו', ואולי שנתכוין למה שאמרו ז''ל (שם) משל לרועה וכו' כי בהיותם בערבות מואב על ירדן יריחו נגמרה שמירת רועה נאמן והחזירם בחשבון, ולזה גם כן הקדים הכתוב לומר בתחלת הפרשה **ויהי אחרי המגפה** להעיר שאפילו אחר שהיה בהם המגפה באו לכלל חשבון הראשון, ולטעם זה לא אמר הכתוב ענין זה במצות ה' כי דבר זה נוגע למשה להראות שלא הפסידו הצאן על ידו, ואם תאמר והלא רואני כי ה' אמר אליו שאו את ראש, אין כוונתו במאמר זה לקבלם במנין, כי לכשיהיו נמצאים חסרים הרבה אין לו טענה עליו שאינו דומה למציאות הרועה, אלא היתה כוונת ה' כדרך שאמרו ז''ל משל לרועה שנכנם זאב לעדרו והרג בהם וכו', ומצא משה דרך לעשות חפצו בזמן שהיה צריך למנותם, ואומרו תיבת **לאמר** במקום זה שאין להם למי יאמרו, פירוש שאמר להם המכוון הרמוז בערבות מואב שהוא רוצה להחזירם במנין כדי שידעו שלא חסרו ממניינם הראשון על ידו. או ירצה כי הוא מונה אותם על פי הנאמר לו מה' ולא מלבו לבד הוא מונה אותם:
@890 **מבן עשרים שנה**. צריך לדעת למה לא הזכיר המספר שעליו חוזר מאמר מבן עשרים, ואם סמך שעל המספר הוא אומר כאמור בסמוך, אם כן גם מאמר מבן עשרים וגו' היה לו לסמוך שהוזכר בסמוך ולא יצטרך להזכירו, ולפי מה שפירשתי בפסוק שלפני זה שבא המספר בערבות מואב גם כן להראות שלא חסרו על ידו יתחייב הדבר למנות גם הקטנים שזולת זה אין שבח שלא חסרו כי לעולם חסרו אלא שגדלו הגדיים ונעשו תישים, ויש מקום לומר כי לכלן מנה, לזה אמר מבן כ' שנה, ונתן הכתוב טעם לדבר **כאשר צוה ה'** כי אם היה הדבר מצד משה לבד להחזיר הצאן במנין ולא היה דבר ה' אלא לצותו על הדבר דכתיב שאו את ראש וגו' לא היה משה מונה את ישראל לרצונו הגם שיהיה לו טעם בדבר, לזה לא מנה אלא מבן עשרים כאשר צוה וגו':
@890 **ובני ישראל היוצאים מארץ מצרים**. אין ידוע הכוונה במאמר זה, וראב''ע אמר כי ירצה לומר שהיו בספורים רבים מיוצאי מצרים, ואין טעם למה יודיע הכתוב ענין זה, ועוד ודאי שאני יודע שהיו בהם מיוצאי מצרים שלא נגזרה גזירה אלא על היוצאים מבן עשרים, ואולי שכוונת הכתוב היא להודיעך שנמנו ונמצאו בני ישראל כמספר היוצאים מארץ מצרים לא כמספר שבפרשת במדבר, ששם היו שש מאות אלף ושלשת אלפים וחמש מאות וחמשים ומספר זה עלה לשש מאות אלף ואלף ושבע מאות ושלשים שחסר למספר במדבר, ואין חיוב על משה אלא להחזיר במנין שהופקדו אצלו בתחלה והנה הוא מספרם שלם, ושיעור הכתוב הוא על זה הדרך ובני ישראל עלה מניינם למנין היוצאים וגו' ולא למטה מהם. או ירצה על זה הדרך כי מספרם היה כסדר מספר היוצאים מארץ מצרים שמנו למשפחות דכתיב (בראשית מו) בני ראובן חנוך ופלוא בני שמעון ימואל וימין וגו', כמו כן מספר זה היו מונים למשפחות כרשום בענין ולא כדרך שנמנו במדבר סיני שלא הוזכר שם פרטי המשפחות:
@891 **משפחת החנוכי**. רז''ל (ילקוט) אמרו וזה לשונם אמר רב אידי ה''א בריש דתבותא ויו''ד בסופה יה מעיד עליהם שהם בני אבותיהם ומה טעם שבטי יה עדות וגו' עד כאן:
@891 **וראיתי** לתת טעם למה נקבע בהם השם שלא כסדרו ה''א בתחלה ויו''ד בסוף, בהקדים דבריהם ז''ל (תיקונים י') כי כללות נשמות ישראל הם מכסא כבודו יתברך אשר יקרא היכל קדשו ויתכנה בשם אדנ''י, וכפי מה שקדם לנו מאנשי אמת (טוש''ע או''ח סי' ה') כי יתחייב כל המוציא מפיו הזכרת השם לכוין לאותיות המוזכרות בפיו והנעלמות במחשבה, המוזכרות שם אדנ''י, והנעלמות שם הוי''ה, גם יכוין לשילוב האותיות שהוא סוד ה' בהיכל קדשו (תהלים יא), ומעתה בהשתלב ב' שמות יעמדו יחד ב' אותיות ה' י' ה''א קודם ליו''ד, והם האותיות הנרשמות במשפחות בית ישראל החנוכי הפלואי שקודמת ה''א ליו''ד שהם אותיות חותם ה' בהיכל קדשו ויבנה משניהם שם י''ה הרמוז במאמר שבטי יה:
@895 **הוא דתן ואבירם וגו'**. צריך לדעת מה בא ללמדנו במאמר זה, ואם להודיע כי הן הנה האמורים במעשה קרח דבר פשוט הוא שאין לטעות שהיו דתן ואבירם אחרים בני אליאב אחר. ועוד מעיקרא לא היה לו להזכירם והיו כלא היו כשאר המשפחות שספו תמו ולא נמנו. עוד למה האריך בדברים אלו אשר **הצו** וגו' **בהצותם** על ה'. ונראה כי לא בא הכתוב כאן אלא לומר שהן הנה היו סיבה לכל מעשה קרח, כי יחפוץ ה' לפרסם הרשעים שהם סיבה לרשע הנעשה, והוא אומרו **הוא דתן** וגו' **אשר הצו** וגו' פירוש את אחרים על ה' ומשה עבדו, וכן פרש''י, הא למדת שהם המחטיאים העדה הנועדת, ואפשר שגם את קרח הם החטיאוהו, והגם שאמר הכתוב ויקח קרח שנראה שמעצמו עשה, אפשר שהיה למה שקדם לו מהם ולעולם הם הצו אותו. ואומרו **ותפתח** וגו' אחר שהדברים כבר כתובין בפרשת קרח, נתכוין לומר שגם בליעת קרח ואכילת האש ר''ן איש הם היו סיבה למאורע מתחלה ועד סוף, הא למדת שהגם שנקהלו היהודים על משה ועל אהרן היו חוזרים בהם אם לא היו ב' הרשעים:
@895 **וזה** לך האות כי האיש משה לא היה משתדל לרצות אלא להם דכתיב (ט''ז י''ב) וישלח משה לקרא לדתן וגו', וכתיב (שם כ''ה) וילך משה אל דתן וגו' שהרגיש שבהם הדבר תלוי, מעתה נפשות כל המתים תלויים בב' הרשעים ההם, ויש בזה לימוד זכות על קרח ועל הר''ן איש וכן תמצא שאמר הכתוב בפרשת עקב (דברים יא) ואשר עשה לדתן ולאבירם וגו' שאינו מונה המאורע אלא לדתן ואבירם, וכפי זה יכולין אנו להעמיד סברת האומר (סנהדרין קח.) עדת קרח אין להם חלק לעולם הבא בדתן ואבירם, ולהעמיד סברת האומר עליהם אמר הכתוב מוריד שאול ויעל בשאר העדה חוץ מהם:
@897 **ובני קרח לא מתו**. הודיע הכתוב ענין זה כאן ולא במקום עיקר המעשה, גם לא כתבו במקום מספר הלוים כי שם מקום הודעת המתים מהם, לפי מה שכתבנו כי כאן בא אלהים לקבוע העון בדתן ואבירם ולהקל מעל קרח, לזה גמר אומר **ובני קרח לא מתו**, הכוונה שזה יגיד זכות אביהם שלא שטפם חובו כדרך ששטף חובם של דתן ואבירם כל בתיהם להיותם עיקר המ ח לוקת:
@899 **לשאול משפחת וגו'**. רז''ל (במד''ר פכ''א) אמרו וזה לשונם אמר ר' יוחנן ה' שמות נקראו לו זמרי וגו' שאול בן הכנענית וגו', וקשה לדברי המדרש ששאול האמור כאן הוא זמרי למה מיחס ה' שמו על משפחתו המתכנית עליו והלא אמרו ז''ל (יומא ל''ח) בפסוק ושם רשעים ירקב דלא מסקינן בשמייהו עד כאן, ואין צריך לומר להחתימו בשמו יתברך, ולפי אחד מהדרכים שפירשנו בפסוק (כ''ה י''ד) אשר הוכה את המדינית שלא הוכה אלא בהיותה עמה ולא אחר כך, הוא מה שהצדיק ה' במאמרו כאן שהחתים שמו עליו, וכן משמע גם כן מדבריהם ז''ל (במד''ר פכ''א) שאמרו וזה לשונם שאול שהשאיל עצמו לעבירה, וידוע הוא דין השאלה שחוזרת בעינה:
@902 **לאזני**. פירש רש''י אומר אני שזו משפחת אצבון ואין אני יודע וכו' עד כאן. ואין נראה להמציא דבר שאין לו טעם ואינו מדבריהם ז''ל. ועוד קשה שבמדרש ר' תנחומא אמרו וזה לשונם וכשאתה מונה משפחת גד אין שם אצבון כי חסר על הזנות בעצת בלעם עד כאן, אשר על כן היה נראה כי אזני היא משפחה אחרת שיצתה מגד, כי מן הסתם היו בכל שבט ענפים אחרים לבד מאותם שנבנית מהם המשפחה והיו נקראים על אחיהם ולפעמים יגדל הענף ההוא ותקרא המשפחה על שמו, אלא שמצאתי בפסיקתא וזה לשונם אזני זה אצבון שנאמר בפרשת ויגש מלשון אצית והאזין עד כאן, כפי זה הוא השם עצמו ואין הכתוב מקפיד על שינוי השם כשיהיה במשמעו שם הראשון, ורש''י ז''ל רוח הקודש הופיע בו וכוון אל דברי חז''ל:
@905 **בני יהודה**. פרשה זו תרמוז מאורעות עם בני ישראל, ובחר לרמוז ביהודה מהטעם עצמו שאמרו ז''ל (ב''ר פ' צ''ח) למה נקראו ישראל על שם יהודה, אומרו **בני יהודה** הם התולדות יתכנו בשם בנים כידוע, ואומרו **ער ואונן** ירמוז לבית ראשון ובית שני, ער כנגד בית ראשון על דרך אומרו (שיר ה) אני ישנה ולבי ער שהיה הקב''ה בו ער בהשגחה גדולה עמנו בבית המקודש, אונן הוא בית שני וקראו אונן לשון אונאה לפי שהיה חסר דברים העיקרים של בית המקודש ואומרו **וימת ער ואונן** הוא חורבן הבתים, כי סילוק שכינה מהם יקרא מיתה שפרחה הנפש שהיא השכינה ונשאר הבית מת בעונות ומלא טומאת הקליפה הנתונה בו כידוע, גם תמצא שעון שבו מת ער הוא העון עצמו שגרם החורבן שאמרו ז''ל (שבת סב:) שהיו מסריחין על מטותיהם והוא מעשה ער דכתיב (בראשית לח) ושחת ארצה, ועון אונן הוא עון שגרם חורבן בית שני שהיה להם שנאת חנם (יומא ט:) וכמו כן אונן דכתיב בו (שם) לבלתי נתן זרע לאחיו, גם לשון אונאה שהיו מאנים זה את זה, ואומרו **בארץ כנען** רשם מקום המקודש כי הוא בארץ כנען ושם מיתתו שחזר ליכנס ברשות ס''מ הנקרא כנען:
@905 **גם** ירמוז סיבה אחת כללית והיא שישראל לא הורישו הכנעני ונשארו יושבים בה וזה סבב להטותם מדרך המוסר כידוע, והוא מה שרמז במאמר בארץ כנען, ואומרו **ויהיו בני יהודה** ירמוז לצער הבא להם אחר חורבן הבית ווי היו בני יהודה בגלות ביד אויביהם אשרי מי שלא טעם שליטת שונא, ותמצא שבכל השבטים לא הזכיר הכתוב לשון זה של ויהיו אלא כאן, ובבנימין כידוע הטעם שם ואומרו **למשפחותם** כי כל משפחות בית ישראל בכל מקום שהם כל הנקרא בשם יהודה ווי היו:
@905 **ואומרו לשלה** נתכוון למושיע ורב הבא לגאול מגלות האחרון הנקרא שלה, והגם שיעקב קראו שילה לא ישתנה השם בזה, וצא ולמד ממשפחות הרשומות כמה השתנות בשמות, ואולי שרמז בסמיכות מאמר **לשלה** עם מאמר **ויהיו בני יהודה** שצריכין ישראל להצטער בשבילו ולקוות לישועתו, וכמו שאמרו רז''ל במעשה רבי יהושע בן לוי ששאלו המשיח אם ישראל מכירים בצערו וחולים עליו וכו' עד כאן, וכדברי הזוהר (בשלח נה:) בפירוש פסוק קול צופיך נשאו קול וגו', והוא מאמר **ויהיו** פירוש יהיו בווי שהוא הצער למשפחותם בשביל שלה והוא אומרו לשלה וגו', ובזה יהיו **משפחת השלני** פירוש דור שבן דוד בא, ויקראו על שמו דורו של משיח:
@905 **עוד** ירמוז במה שנדקדק אומרו **השלני** ואין אות הנו''ן בבנין השם ואין כן מנהגו להוסיף בשם המשפחה אות חדשה זולת ה''א ויו''ד כאמור בכל הקודמות חנוך משפחת החנוכי וגו', אכן ירמוז למה שאמרו ז''ל (שבת לב:) בפסוק והחזיקו זה בכנף איש יהודי וגו' יעויין שם דבריהם, והוא זה שרמז במאמר **השלני** פירוש שהאומות כלן יאמרו לכל אחד מישראל שלו אני, ואומרו **לפרץ משפחת הפרצי** ירמוז על דרך אומרם (סנהדרין כ:) שהמלך פורץ גדר לעשות לו דרך, והכוונה כי בבא הבא מפרץ יהיו כל ישראל משפחת הפרצי מלכים, ועל אותו זמן הוא שאמרו ז''ל (ב''מ קיג:) כל ישראל בני מלכים, וכן אמר הנביא (ישעיה מט) מלכים יראו וקמו וגו', גם ירמוז על הפרצה הגדולה אשר יפרוץ באומות לאין תכלית, ואומרו **לזרח משפחת הזרחי** ירמוז מה שאמר הכתוב (שם ס') הנה החושך וגו' ועליך יזרח ה' וכתיב והיה לך ה' לאור עולם, והוא אומרו משפחת הזרחי אשר עלינו יזרח ה':
@905 **או** תרמוז הפרשה לג' ענינים שיהיו בעת הפקידה. א' ביאת משיח בן אפרים כמאמרם ז''ל (סוכה נב.) ב' גילוי משיח בן דוד. ג' כשימלוך ה' עלינו. כנגד ביאת משיח בן אפרים אמר **שלה** ורמז שתפגע בו מדת הדין וימות בעונות ישראל, והוא הרמוז בתיבת שלה כדרך אומרו (ש''ב ו) ויכהו שם על השל. וכנגד משיח בן דוד אמר **לפרץ** וגו' כי זה יעשה פרצה באומות וינקום דם צדיק. וכנגד מלכות עולם אמר **לזרח** וגו' רמז לכבוד ה' עלינו יזרח. ואומרו **ויהיו** בני פרץ אמר לשון צער לרמוז על הצרות אשר יהיו בבא הגואל כאומרם בגמרא ייתי ולא אחמיניה מרוב הצער של חבלי משיח, ואומרו **בני פרץ** וגו' פירוש תולדות היוצאות מביאת הגואל הרמוז בפרץ הם ב' דברים, א' שיבנה ה' חצר בית המלך והוא בית המקדש אשר פעל ה' וכוננו ידיו ויהיו ישראל מבני פלטין שלו, והוא אומרו **לחצרון משפחת החצרוני** והבן. הב' **לחמול משפחת החמולי** שיחמול עלינו בכל ענפי החמלה:
@905 **ואומרו אלה משפחות יהודה**. פירוש מה שיהיה להם מהמאורעות גם הרעות גם הטובות, ואומרו לפקודיהם פירוש כשיהיו נפקדים יש פקידה לרעה ויש פקידה לטובה כאמור בדבריהם ז''ל (זוח''א קם.), ושני מיני פקידות נאמרו בכתוב, ואומרו **ששה ושבעים אלף וחמש מאות**, אולי שרמז ה' בזה מתי יהיה תכלית הפקידה טובה הרשומה בסמוך שיזרח עלינו כבוד ה', ואמר עד עבור כל גליות, גלות מצרים, וגלות בבל, וגלות אדום, כנגד גלות מצרים אמר **ששה** לרמוז לגלות מצרים שהיה לששה דורות דכתיב (בראשית טו) ודור רביעי ישובו הנה, ועיין מה שכתבתי שם שג' דורות סבלו גלות לבד מיצחק ויעקב ויהודה הרי ששה כי התחלת הגלות היה משנולד יצחק, וכנגד גלות בבל אמר **ושבעים** דכתיב (ירמי' כט) עד למלאות לבבל ע' שנה, וכגנד גלות אדום שאנו עדיין בו אמר **אלף וחמש מאות**, ואם היו זוכים ישראל היו נמנים קע''ב שנה שנשארו מאלף הד' וכיון שלא זכו יתחיל החשבון מאלף הה' וחמש מאות מאלף הששי, ומקוים אנו כי הוא זה קץ גליותינו ויתקיימו כל היעודים הרשומים ויתחילו ניצוצי גילוי הגאולה בהתחלת חמש מאות הבאים לשלום:
@909 **בני יששכר וגו'**. למה שקדם לנו כי יששכר הוא בן תורה רמזה התורה בשם זה של יששכר כי דוקא זה ישנו לשכר, וכל חוץ ממנו מה יתרון לאדם בכל עמלו, והוא מה שאמרו בברכות בפרק תפלת השחר (כח:) שצריך לברך ביציאתו מבית המדרש מודה אני לפניך וכו' אני עמל והם עמלים אני עמל ומקבל שכר והם עמלים ואינם מקבלים שכר וכו' עד כאן, והטעם כי לא יעמוד קנין המדומה, והגם שיעמוד הבל הוא. עוד ירמוז כי כל מה שיש בעולם הוא שכר לו כי כל מה שברא ה' לא בראו אלא בשבילו כמו שדרשו ז''ל (ב''ר פ''א) בפרשת בראשית וגו' בשביל תורה וכו' ברא שמים וארץ:
@909 **עוד** ירמוז למה שאמרו ז''ל (עוקצין פ''ג) עתיד הקדוש ברוך הוא להנחיל לכל צדיק שלש מאות ועשר עולמות, והוא אומרו יש שכר, **ואומרו לתולע** וגו' רמז הכתוב תנאי השגת התורה בשמות משפחות יששכר, והם מ''ח כאומרם (אבות פ''ו) במשנה שהתורה נקנית בארבעים ושמנה דברים, הנה משמעות תולע יגיד שני פרטים, א' ישים עצמו כעדין זה כאומרם ז''ל (מו''ק טז:) על דוד שנקרא עדינו העצני, ב' שיתעסק בפיו כתולע זה שכחה בפיה כי לעמל פה נברא האדם, וב' דברים אלו כוללים כל ענפי הענוה וכל ענפי הלימור המנויים במ''ח מעלות הנזכרים, ואומרו **לפוה משפחת הפוני**, יש להעיר למה הוסיף אות שאינה נמנית מאותיות השם שהיה לו לומר משפחת הפוי, אלא רמז לשאר מעלות המנויים שם במ''ח שהם מיעוט שיחה מיעוט שחוק ושאר הענפים הדומים לאלו, והוא אומרו **לפוה** משפחת הפוני פירוש פוה הוא לשון פה והוסיף לו אות ו' שהוא סוד עץ חיים שהוא עוסק בה יתר על שאר הפיות, גם רמז בסמיכות אות הוא''ו לאות ה''א לומר סוד חיבור המדות באמצעות עסק התורה. ואומרו **משפחת הפוני** פירוש שצריך לפנותו ממותרות המורגשות גם מהשחוק ומדברים בטלים כי הם מונעים קיום התורה באדם, ומצאתי לחסידי ישראל שכתבו (אלשיך תצוה כ''ח ל''א) כי פה של לומדי תורה דינו ככלי שרת אשר ישרתו בם בקודש כי אין קדושה כקדושת התורה ולזה אסור לדבר בו אפילו דברי חול הגם שאין בהם דברים האסורים, והוא מה שרמז במאמר **לפוה** שהוא פה העמל בתורה שבו שוכן חצי שמו יתברך, **משפחת הפוני** פירוש צריך לפנות מפיו כל חוץ מהגות בתורה ובזה נכללים חלק אחד מהמ''ח מעלות שהם במיעוט שיחה במיעוט שחוק במיעוט תענוג וכדומה להם שבענף המותרות:
@909 **ואומרו לישוב** ירמוז שצריך להרבות בישיבה ולא דרך עראי, גם צריך להתישב בכל פרט ופרט מהתורה עד שיעמוד על עקרו כמצטרך בעומק הלכה כי הוא זה עיקר התורה, ובזה נכללים חלק אחד מהמ''ח מעלות שהם בישוב, ומתישב לבו בתלמודו, שואל ומשיב, המכוין את שמועתו וכו', גם מה שמנו שם שמיעת האוזן, עריכת שפתים, בינת הלב וכו', וכדומה לזה שבענף הבנת השכליות:
@909 **ואומרו לשמרון משפחת השמרוני** ירמוז לתוספת השמירה המתחייב עשות בן תורה יתר על ההמון כאומרם ז''ל (יומא פו.) היכי דמי חילול השם אמר רב כגון אנא דשקילנא בשרא ולא יהיבנא דמי לאלתר עד כאן. מזה יקיש כמה צריך להשתמר בן תורה בכל פרטי המצות, ואמרו ז''ל (חובת הלבבות שער התשובה פ''ה) כי חסידים הראשונים היו שומרים חמשים שערי היתר לבל יכשלו בשער האיסור, והוא אומרו לשמרון משפחת השמרוני, ואומרו **אלה משפחות יששכר לפקודיהם** פירוש פקודיהם פקידה לטוב, ומה היא הפקידה פירוש הכתוב ואמר ארבעה וששים אלף ושלש מאות כאן רמז השגה בב' דברים, הא' שבעולם הזה נעשים מרכבה לשכינה והוא מה שרמז במאמר ארבעה וששים והוא בחינת נקודה אחת הרי ס''ה שהוא מספר אדנ''י, ואמר בסדר זה לומר כי באמצעות הלמדן תתמתק בחינת הדין שחשבונו ס''ד ותהיה נתקנת השכינה במספרה ס''ה כאומרם ז''ל בספר הזוהר (ח''ב ט') בפסוק והאם רובצת על האפרוחים וגו', והשגה שניה היא לעולם הבא כרמוז בשמו שלש מאות ועשר עולמות, והוא מה שרמז במאמר אלף ושלש מאות, וקודם שנעמוד על הכוונה אעיר במאמר רבי יהושע בן לוי (עוקצין פ''ג) שאמר עתיד הקב''ה להנחיל וכו' שלש מאות ועשר עולמות ומוכיח מאומרו (משלי ח) להנחיל אוהבי יש, קשה לדבריו ז''ל אם למספר יכוין הכתוב למה הקדים הכתוב מספר העשר למספר המאות שהיה לו לומר להנחיל אוהבי ש''י, ושמעתי מפי הראשונים טעם ערב, כי מספר זה ירמוז לארבע עולמות כידוע אצילות, בריאה, יצירה, עשיה, וכל אחד כלול מעשר, ומאמר רבי יהושע בן לוי בא ללמד כי הצדיקים יתענגו על רוב שלום בעולם העליון בארבע עולמות אבל אין השגתם בכולם שוה אלא בג' ישיגו כל ההדרגות שישנם בהם והם במספר שלש מאות אבל בעולם העליון שהוא עולם האצילות לא יוכלו להשיג כל צדיק כי אם חלק מעשרה שבה שהיא גם כן עשרה בפרטם כנזכר שכל אחד כלולה מעשר, ויש לך לדעת כי העשר המושג מעולם העליון גדול ומהולל מאוד למעלה מכל השלש מאות, ולזה הקדים הכתוב העשר למאות ואמר להנחיל וגו' י''ש, ועל פי הדברים ירמוז באומרו **אלף** יכוין לחלק הקטן הרמוז ביו''ד ויחד לו מספר זה של אלף כאומרם ז''ל שכל עשר כלולה מעשר ועשר מעשר הרי שנקודה אחת תתכנה לאלף, ואומרו ושלש מאות כפשטה, והוא מה שרמוז בשמו של יששכר יש שכר:
@912 **בני זבולון וגו'**. רמז הכתוב מעשיהם והמושג ממנו, סרד כמו סדר, וכן דרך הכתוב לקרות לכבש כשב, והכוונה בזה שהיה מסדר לפני יששכר כל הצריך לו למזונותיו, ואלון לשון חוזק ורמז על דרך אומרו (משלי ג) עץ חיים היא למחזיקים בה, ואמרו רז''ל (ויק''ר פכ''ה) ללומדיה לא נאמר וכו', ולזה לפי שזבולון היה מחזיק ביד לומדי תורה יחס לו מדה זו, והוא אומרו לאלון:
@938 **וידבר וגו' לאמר**. פירוש לאמר ליהושע והזקנים כי הוא המנחיל את הארץ, ואין לפרש לאמר לישראל כי תיבת לאלה שאמר בסמוך תכחיש זה:
@939 **לאלה תחלק הארץ וגו'**. אומרו **לאלה**, נחלקו רז''ל בפרק יש נוחלין דף קי''ז וזה לשונם ר' יאשיה אמר ליוצאי מצרים נתחלקה שנאמר לשמות מטות אבותם ינחלו אלא מה אני מקיים לאלה וגו' לאלה להוציא את הטפלים פירוש שלא יחלק אלא ליוצאי מצרים מבן עשרים, ור' יונתן אומר לבאי הארץ נתחלקה שנאמר לאלה תחלק הארץ ומה אני מקיים לשמות מטות משונה נחלה זו וכו' וכאן מתים יורשים וכו' עד כאן, לדברי ר' יונתן אומרו לאלה להוציא דברי ר' יאשיה במשמעות פסוק לשמות מטות וגו', וראיתי ברייתא אחת (ספרי) וזה לשונם לאלה בני כשרים וקדושים להוציא רשעים שבהם שלא היה להם חלק ונחלה, והוכיחו הדברים מבני המרגלים ומתלוננים, וסברא זו הולכת לדרכו של ר' יאשיה שאמר ליוצאי מצרים נתחלקה ולזה כשאמר לאלה כאלה שהיו צדיקים כלם למעט הרשעים שהיו ביוצאי מצרים שהם המרגלים שלא נטלו בניהם חלקם:
@939 **ונראה** שאין דרשה זו דלמעט רשעים דוחקת דרשתנו דלמעט יוצאי מצרים פחות מבן עשרים ולא להפך, כי כולן נשמעים יחד ממאמר כאלה כל שאינו כאלה בין במספר בין בצדקות אינו בכלל החלוקה, וראיתי לרש''י ז''ל שפירש לאלה על באי הארץ כסברת ר' יונתן ואמר וזה לשונו לאלה וגו' ולא לפחותים מבן עשרים אף על פי שבאו לכלל עשרים בטרם חלוק הארץ וכו' עד כאן, וקשה הלא לר' יונתן צריך לאלה להשמיענו שהארץ נחלקה לבאי הארץ וכמו שדקדק ר' יונתן באומרו לבאי הארץ נתחלקה הארץ שנאמר לאלה וגו' ומה אני מקיים לשמות וגו' עד כאן, הא למדת שלא הוכרח לומר לבאי הארץ אלא מאומרו לאלה ומכח זה הוצרך לחפש במה יקיים מאמר לשמות וגו' הא למדת שצריך לומר לאלה להודיענו שתחלק הארץ לבאיה:
@939 **והן** אמת כי בעקרן של דברים שאומר רש''י שלא תחלק אלא לבן עשרים אין אני מכריע לחלוק הגם שלא נאמר בדברי רבי יונתן, עם כל זה יכול להיות נכלל בתיבת לאלה ויסבול ב' הדרשות, אלא שאין הכרח לדבר זה דלמא לא בא אלא לשלול ליוצאי מצרים והדבר שקול, אלא דצריך עיון למה לא פירש רש''י כאמיתתן של דברים אליבא דרבי יונתן:
@939 **וראיתי** לרא''ם שפירש דברי רש''י שדייק תיבת לאלה ולא יצא ידי חובת עיונו הזך אפילו בענין הקושיא שיש על רש''י מהברייתא, ואני אומר כי רש''י ז''ל לא נעלם ממנו כוונת דברי ר' יונתן, אלא שנראה לדעתו הזכה מוכרע מתיבת לאלה שלא נתחלקה הארץ אלא לאותם שהיו אז ודווקא אותם שהיו מבן עשרים באותו מספר, ודבר חידוש זה הוא שבא להשמיענו והדבר מובן הוא מעצמו שנתחלקה לבאי הארץ:
@939 **במספר שמות**. פירוש שתהיה החלוקה למספר השמות האמורות שהם חמשים ושבע משפחות, הכוונה שיחלקו הארץ לנ''ז משפחות וכל משפחה כפי מה שהיא, ודרך זה אינו אלא לרבי יונתן, דלרבי יאשיה שסובר ליוצאי מצרים אין לחלק לנ''ז משפחות שהרי צריך לחלק גם לששה משפחות שנחסרו מיוצאי מצרים כאמור בדבריהם ז''ל (במד''ר כ''א) ויטלו חלקם השבט שממנו נחסרו במשפט הנחלה, ואפשר שגם ר' יאשיה יצדיק לומר במספר שמות על המשפחות של יוצאי מצרים:
@940 **לרב תרבה וגו'**. אמרו במסכת בבא בתרא (קיז:) וזה לשונם אמר ליה רב פפא לאביי בשלמא למאן דאמר ליוצאי מצרים היינו דכתיב לרב תרבה וגו' אלא למאן דאמר לבאי הארץ מאי לרב וגו' קשיא עד כאן, פירוש אם החלוקה היא לאותם המנויים בערבות מואב מה מקום לומר לרב וגו', הנה קושיא זו אינה מאיזה דיוק רק שנוכל לומר לא נתן דעתו עליו שהרי מקרא מלא דבר הכתוב, ועוד אין אלו דברי אמורא לדחותן אלא דברי ר' יונתן שהוא תנא, ולפי מה שקדם לנו מכללי התלמוד שכל שיאמר הגמרא קשיא היא עומדת לתירוץ אלא שלא נזדמן להם תירוץ:
@940 **ונראה** לפי מה שפירשתי במה שאמר במספר שמות שחוזר על החמשים ושבעה משפחות ידוייק על נכון אומרו לרב וגו' פירוש שיחלקו נ''ז חלקים ולא חלק כחלק יהיה אלא לרב תרבה נחלתו, המשל משפחה שיש בה כ' אלף תיטול בכפלים מהמשפחה שיש בה עשדה:
@940 **עוד** נראה לפי דרכו של רש''י ז''ל כי רבי יונתן סובר שלא יטלו חלוקה אלא אותם שהיו במספר ערבות מואב, כפי זה בא הכתוב לאם היו לאחד י' בנים בני עשרים ולאחד שמנה בנים ד' מבן עשרים וד' למטה מעשרים ובכניסתן לארץ מי שהיו לו י' בני עשרים מתו לו ד' ומי שהיו לו ד' בשמנה למטה מעשרים הגיעו לכלל עשרים בשעת החלוקה, לזה אמר הכתוב לרב פירוש בזמן המספר תרבה נחלתו פירוש מי שהיו לו י' בני עשרים במספר זה תרבה לו כשיעור עשרה הגם שאין לו אלא ששה, ולמעט בזמן המספר שלא היו לו אלא ד' בני עשרים תמעיט לתת לו כשיעור ד' הגם שיש לו ח' בני עשרים, ואולי שרש''י ז''ל לתרץ קושיא זו נתחכם במאמרו:
@940 **איש לפי פקודיו וגו'**. בספרי אמרו וזה לשונם לפי פקודיו מלמד שלא נתחלקה הארץ אלא לכל שבט ושבט לפי מה שהוא עד כאן, אין בזה סתירה למה שפירשתי בפסוק במספר שמות שנתחלקה לנ''ז משפחות, אפשר שנתחלקה לשבטים ולמשפחות על זה הדרך חלקו הארץ לי''ב חלקים והחלקים לנ''ז חלקים, שבט שיש לו ב' משפחות יטול ב' חלקים, ומי שיש לו ד' יטול ד' חלקים, והחלק יהיה כפי המספר למר מספר יוצאי מצרים ולמר מספר ערבות מואב, ואם תאמר כיון שמחלקים למשפחות למה הוצרכו לחלק לשבטים, הטעם כדי שיהיה כל שבט גורלו בפני עצמו מה שלא יהיה כן אם יחלקו למשפחות שיכול לעשות גורל לשני משפחות שמעון עם משפחות זבולן ולהפך ולא יהיו כל שבט ושבט יחד:
@940 **ובמסכת** בבא בתרא דף קכ''ב אמרו וזה לשונם איבעיא להו ארץ ישראל לשבטים איפליג או לקרקף גברי איפלוג תא שמע בין רב למעט ועוד תניא עתידה ארץ ישראל שתחלק לי''ג שבטים שבתחילה לא נחלקה אלא לי''ב שבטים עד כאן, ונעלם מהש''ם ברייתא בספרי שדרשוה מאיש לפי פקודיו, ומסתברא כי תנא די''ג שבטים גם כן דרשתו מאיש לפי פקודיו כתנא דספרי, ועיין בפסוק בין רב וגו':
@940 **עוד** יתבאר לדרכו של רכי יונתן שסובר לאלה תחלק הארץ שהם באי הארץ, ועדיין אין אני יודע אם דוקא להבאים לכלל עשרים או לכלל באי הארץ ואפילו לאותם שלא הגיעו לכלל עשרים תלמוד לומר לפי פקודיו הא למדת כי דוקא לבני עשרים, ובזה אנו מצדיקים דברי רש''י שפירש בפסוק לאלה ולא מטעמו:
@941 **לשמות מטות אבותם וגו'**. לדברי רבי יאשיה בא הכתוב לשלול פשטיות הנשמע מאומרו לאלה שאין הכוונה היא על הנמנים בערבות מואב אלא פירוש כאלה שהם בני עשרים. ור' יונתן מפרש שבא הכתוב לומר שהגם שחלקו להנמנים בערבות מואב חזרו הם והורישו יוצאי מצרים וחזרו וירשום כאומרם בברייתא (ספרי) וזה לשונם כיוצא בזה אתה אומר בבאי הארץ זה נטל סאה ואלו נטלו ג' סאין והורישו אביהם וירשו המתים את החיים וחזרו וחלקו בשוה, ולדרך זה ידוייק על נכון אומרו **ינחלו** שכינה הדבר לנוחלים מה שאין כן מטבע הדיבור עד עתה כאומרו **תחלק הארץ** ולא אמר יחלקו, וכן אומרו **תרבה נחלתו** וכו' וכן אומרו **יותן נחלתו**, ולא אמר יקח נחלתו, **יחלק את הארץ** ולא אמר יחלקו הארץ, הא למדת שעד עתה היה הכתוב מדבר אשר יעשה בהנחיל אותם ומאמר לשמות וגו' ינחלו הוא מה שיעשו הנוחלים אחר שהגיעתם הנחלה ינחלוה בדרך זה כאילו נחלו אותה אבותיהם מהם וחוזרים ונוחלים אותה מהם, והוא אומרו **ינחלו** כי לא הזכיר נושא המנחיל להלביש הדבר בו:
@942 **בין רב למעט**. במסכת בבא בתרא דף קכ''ב אמרו וזה לשונם אבעיא להו ארץ ישראל לשבטים אפלוג או לקרקף גברי אפלוג תא שמע בין רב למעט ועוד תניא עתידה ארץ ישראל שתחלק לי''ג שבטים שבתחילה לא נחלקה אלא לי''ב וכו' ולא נתחלקה אלא בכסף שנאמר בין רב למעט אמר רבי יהודה סאה ביהודה שוה חמש סאה בגליל עד כאן, וכתב רשב''ם שם וזה לשונו תא שמע בין רב וגו' שיקח כל שבט מה שיתן לו הגורל בין שהיה מגיע לו חלק מרובה כגון שבט שהיה לו אנשים מעט בין שהיה לו חלק מועט כגון שהיו לו אנשים מרובים וכו' דכל השבטים חולקין בשוה וכו' עד כאן, וקשה בדברי הגמרא למה מפשט מהכתוב כיון שאין לו הכרח ממנו שהרי בברייתא שמביא מפרשו לקרוב לירושלים ורחוק ממנה קרוב קוריהו רב רחוק מעט לפי ששוה יותר:
@942 **ועוד** נראים דברי הש''ם סותרים סופם לתחילתם כי מאומרו תא שמע בין רב וגו' מגלה דעתו שסובר שנתחלקה בשוה לשבטים ומאומרו ועוד תניא לא משמע כן שהרי מפרש אומרו בין רב וגו' לריחוק מקום וקירוב מקום, ומכח זה מוכרחים אנו לומר דסובר התלמוד כי תנא דעתידה ארץ ישראל סובר שנתחלקה ארץ ישראל לשבטים בהשואה ולזה העיר הש''ם במאמר תא שמע בין רב למעט לומר דסובר כדברי הברייתא שנתחלקה לשבטים בשוה, ואין דברים אלו צודקים שהרי אם נפרש בין רב למעט בין שבט שנוטל רב לנוטל מעט לשיעור אנשיו מנין לנו לומר ריחוק מקום וקירוב מקום, וכן להפך אם נפרש לריחוק מקום וכו' מנין לומר שנחלקה וכו':
@942 **ועוד** אם נאמר שנחלקה בשוה לשבטים אם כן נעמיד מחלוקת רבי יונתן ורבי יאשיה בחלוקת כל שבט ושבט בפני עצמו למר ליוצאי מצרים ולמר לבאי הארץ, כפי זה מה מקשה הגמרא שם דף קי''ח וזה לשונם בשלמא למאן דאמר ליוצאי מצרים היינו דקא צווחן בני יוסף דכתיב (יהושע י''ז) וידברו בני יוסף אלא למ''ד לבאי הארץ מאי קא צווחי כולהו שקול לטפלים עד כאן, אין אני רואה קושיא כיון שלכל הסברות נטלו בני יוסף בשוה עם השבטים וטענת בני יוסף הוא שהם רבים מכל השבטים ובין להאומר ליוצאי מצרים ובין להאומר לבאי הארץ מחלוקתם היא בחילוק השבט עצמו, אלא ודאי דבין לרבי יונתן בין לרבי יאשיה לא נתחלקה הארץ בהשואה לשבטים, ואין להעמיד תנא דברייתא הפך שניהם, ועוד אם נאמר שנתחלקה לשבטים בשוה יותר היה לו לצעוק שבט יהודה שהרי כפי מספר באי הארץ יש במספר יהודה ע''ו אלף וחמש מאות ומספר מנשה ואפרים יחד פ''ה אלף ומאתים נמצא שאין יתרים שניהם מיהודה אלא שמנה אלפים ושבע מאות ונטלו בכפלים שהרי הם נטלו שני חלקים ויהודה חלק אחד כמו שמבואר שם שלא נתחלקה אלא לי''ב שבטים לבד מלוי שלא נטל חלק בארץ:
@942 **אלא** הנכון בעיני כי לא עלה על דעת הגמרא לומר שנתחלקה לשבטים בשוה כדברי רשב''ם, ופירוש דבריו שאמר תא שמע בין רב למעט ממשמעות הכתוב מוכיח שהחילוק היה לשבטים ממה שהזכיר בגורל בין רב למעט הרי שהחלוקה שהיתה על פי הגורל היה בו חלק רב וחלק מועט, ואם תאמר לקרקף דגברי לא יוצדק ליאמר בין רב למעט, ופירוש רב ומעט הוא בין שבט שיש לו כפי אנשיו הרבה ובין שבט שיש לו כפי אנשיו מועט הכל יהיה על פי הגורל לענין המקום שיטלו בו חלקיהם, ואומרו ועוד תניא עתידה ארץ ישראל וכו' ירצה להביא הדבר ביותר ביאור, לפי שיש לבעל הדין לחלוק ולומר שאין להוכיח מפסוק בין דב למעט אלא לומר שלא נתחלקה לקרקף דגברי אבל עדיין יש להסתפק אם למשפחות או לשבטים לזה אמר ועוד תניא עתידה ארץ ישראל וכו' נתחלקה לי''ב שבטים נמצינו אומרים כי פירוש בין רב למעט לכל הסברות אין נשמע ממנו שיחלקו השבטים בשוה ולא חלקו אלא כפי שיעור הפקודים, וכדברי תנא של ספרי שהבאתי בפסוק איש לפי פקודיו:
@952 **ותקרבנה בנות וגו'**. אומרו **ותקרבנה** ולא הספיק במאמר ותעמודנה וגו' שאמר בסמוך, לומר שלא עמדו לפני משה עד שהתוועדו יחד בעצה הגונה וראו כי יש בפיהם נכונה בטענה הנשמעת כאשר אבאר בעזרת השם ואחר כך עמדו לפני משה וכו'. או ירצה על זה הדרך **ותקרבנה** וגו' **למשפחות מנשה בן יוסף** פירוש שנתועדו לקחת עצה מגדולי השבט ולהמלך עמהם משום דרך ארץ. ואולי שרמז הכתוב באומרו **בנות** לומר שהערתם היתה מה שאמר בסמוך איש לפי פקודיו ואמרו בספרי וזה לשונם יצאו נשים וכו'. או ירצה באומרו **ותקרבנה** וגו' להגיד שביישניות היו וקודם שעמדו לפני משה, נתקרבו לפני גדולי השבטים, והוא אומרו **למשפחות מנשה** ואחר שנתקרבו לבני משפחתם הסירו מסוה הבושה לעמוד לפני משה, ולדברי האומר סרס המקרא ודרשהו לא יכלו לעמוד לפני משה, עד שקדמו לעמוד לפני שלמטה ממנו, ודבר זה ממדת הבושת:
@952 **בנות צלפחד בן חפר וגו'**. צריך לדעת לאיזה ענין יחסם הכתוב ולא סמך על מה שהזכיר בסמוך במספר בני מנשה ושם נאמר צלפחד ושם בנותיו, ורז''ל (ספרי) דרשו דרשות. ואפשר לומר שרשם ה' בזה הטענה שעליה נתקרבו יחד להתוועד, והיא על פי דבריהם ז''ל בבבא בתרא דף קי''ח וזה לשונם בשלמא למאן דאמר ליוצאי מצרים היינו דקא צווחן בנות צלפחד אלא למאן דאמר לבאי הארץ אמאי צווחן הא ליתיה דלישקול ומתרץ לחזרה עד כאן, פירוש שאפילו למאן דאמר לבאי הארץ הוכרח לומר מכח פסוק לשמות מטות אבותם וגו' שבאי הארץ יחזירו הנחלה ליוצאי מצרים וחוזרים ונוחלים ואם כן כשיחזירו בני חפר נחלתם לחפר ויחזרו לנחול מהם יזכו הבנות עמהם בירושת חפר, והיא הטענה הבאה במאמר בנות צלפחד בן חפר, אם החלוקה תהיה למאן דאמר שנחלקה ליוצאי מצרים באים בטענה ליתן להם חלק צלפחד אביהם וחלוקה הנוגעת להם בחפר מוריש מורישם, ולמאן דאמר לבאי הארץ יתבאר על זה הדרך בנות צלפחד והגם שנחלקה הארץ לבאיה אף על פי כן נתועדו לצד טענת היות צלפחד בן חפר וכשתחזור נחלת בני חפר לחפר ויחזור להנחיל יהיה נוגע לבנות חלק יחד עם דודיהן:
@952 **ואומרו בן גלעד בן מכיר** בן מנשה, כבר העירו רז''ל ואמרו בספרי וזה לשונם מגיד הכתוב כשם שצלפחד היה בכור כך היו כולן בכורות עד כאן, וכפי זה יכוין הכתוב להודיע שנתעוררו גם בפרט זה ליטול חלק הבכורה הנוגעת להאבות. עוד אמרו שם וזה לשונם להודיעך שכולן צדיקים שכל מי שיחסו וכו' עד כאן, וכן משמע מדברי רש''י בחומש, ואומרו **ואלה** בתוספת וא''ו לומר מה הראשונים צלפחד חפר מכיר גלעד כלם צדיקים כאומרם ז''ל כמו שכתבתי בסמוך ואלה גם כן צדיקים כמותם:
@952 **ואלה שמות בנותיו**. קשה אומרו **בנותיו** שנראה שלא הזכיר אלא צלפחד ולא הבנות שבזה יוצדק לומר ואלה שמות בנותיו, ולא כן הוא שאדרבא לא הזכיר אלא הבנות בכינוי אביהם ואם כן היה לו לומר ואלה שמותם. ולהבין הכונה אעיר גם כן בסדר שמות הבנות שרואני שאין הכתוב מסדרן בסדר שוה שמזכירם במקום אחר שכן תמצא בפרשת מסעי (ל''ו י''א) שסדרם שלא כסדר זה, ובמסכת בבא בתרא דף ק''כ אמרו וזה לשונם להלן מנאן דרך גדולתן וכאן דרך חכמתן, ופירש רשב''ם להלן הוא בפרשת מסעי בשעת נישואין דרך גדולתן, וכאן פירוש כשבאו לפני משה מנאן דרך חכמתן, ואין הדברים נראים מכמה טעמים, א' במה מסוים הדבר כי מנאן דרך גדולתן בענין הנשואין כי מי יאמר שהכתוב דרך נשואיהן מני להו. ב' למה כשמנאם הכתוב למעלה (כ''ו ל''ג) במספר בני מנשה למה לא מנאן דרך גדולתן ושם אין דבר חכמה ולא תבונה. ג' מדברי התלמוד קשה למה הקדים לומר להלן ואחר כן אמר וכאן וכו' כיון שכונת אומרו להלן הוא האמור לבסוף בפרשת מסעי, גם תיבת להלן פשטה הוא מקודם:
@952 **אכן** הנכון בעיני הוא כי סדר גדולתן הוא סדר האמור במספר בני מנשה והאמור בפסוק ותקרבנה, וסדר חכמתן הוא סדר האמור בפסוק ותהיינה וגו', ולזה אמר הש''ס להלן וכו', פירוש לפי שהש''ס אמר בסמוך צדקניות הם שלא נשאו אלא להגון להם ואמר להלן פירוש בזכרון הקודם לזכרון זה של נישואין, והוא זכרון האמור במספר בני מנשה גם בפסוק ותקרבנה מנאן כסדר גדולתן כי כן ראוי לחוש לומר דרך גדולתן בזכרון ראשון להודעת הוייתן, וכאן פירוש בפסוק ותהיינה שאנו עוסקין בו כאמור מנאן דרך חכמתן, והודיע בהם הכתוב ענין זה של דרך חכמתן בפעם אחרונה שהזכירם, אבל בכל המקומות לא הזכירם אלא כסדר גדולתן, וכפי זה ידוייק דברי הש''ס על נכון:
@952 **ובזה** נבא ליישב מה שהקשינו בכתוב, והוא שנתחכם הכתוב להעיר כי דרך גדולתן מונה אותם ולזה אם היה אומר ואלה שמותם היה צריך לסדרן כסדר חכמתן וסדר חכמתן אינה כן ולזה אמר **ואלה שמות בנותיו** להעירך שסדר הוית בנות מאביהם הוא שמסדר הכתוב, וכן תמצא למעלה במספר בני מנשה שנאמרו גם כן בסדר זה דקדק הכתוב לומר ושם בנות צלפחד להעיר כמו כן, והגם שגם בפסוק ותהיינה אמר הכתוב גם כן בנות צלפחד, שם הקדים זכרונם ואחר כך שם אביהם ואין במשמעותו שסדרן כדרך לידתן אלא כשיקדים זכרון האב ויסמוך לזכרונו זכרונם זה יגיד כי מונה סדר יציאתן ממנו, ועיין מה שכתבתי בפרשת נח בפסוק (א' י') ויולד נח שלשה בנים:
@953 **ותעמדנה לפני משה וגו'**. בפרשת בהעלותך (ט' ו') פירשתי מחלוקת אבא חנן ור' יאשיה, גם למה נחלקו גם במקום זה, ולפי מה שפירשתי שם יתישב אומרו גם כן כל הנשיאים והעדה לב' הסברות, להאומר חולקין כבוד וכו' מכאן אתה למד שאפילו אין רבו חולק לו כבוד מן הסתם אין הנשיאים חולקים כבוד לעם הארץ, ולמאן דאמר אין חולקין וכו' מכאן תתחייב לומר סרס המקרא ודרשהו והבן, וטעם שדברו בזמן שהיו יחד שבטי ישראל, לומר דבריהם בפני כולן כדי שידעו תשובתו להם שלא יערערו אחר כניסתם לארץ:
@953 **ובספר** הזוהר הקדוש פרשת בלק דף ר''ה אמרו וזה לשונם דחב במדברא במלולא לגבי משה חשיבו דמשה אנטיר דבבו ובגין כך קריבו לקמיה דמשה ואלעזר וכל הנשיאים וכל ראשי אבהן וכו' עד כאן, הדברים יגידו שמפרש טעם מאמר הנשיאים וכל העדה הוא שהבנות כנסו אותם לחשש שינטור משה להם איבת אביהם, ומה שאמרו בזוהר וכל ראשי אבהן הוא פירוש אומרו וכל העדה, והוכרח לפרש כן לפי מה שמפרש שהם כנסו אותם לא יתכנסו העדה כולם זולת במאמר משה ובתקיעה בחצוצרות כידוע לזה פירש שהם ראשי האבות, ויש להעיר לדברי הזוהר איך יעלה על דעת הצדקניות לחשוד בכשר כמשה, ואולי שאינו אלא ללמדנו דרך החיים, וכמו שפירש שם בזוהר וזה לשונם מכאן מאן דחייש מן דיינא יקרב אחריני ויסגי בגוברי עד כאן, וכבר אמרו ז''ל (ב''ר קיט:) שהבנות חכמניות היו וצדקניות היו, ולעולם יודעים היו כי משה לא יעוול משפט, או אפשר שחששו כי משה ישפוט בהם כמשפט המתלוננים והמרגלים שלא נטלו בניהם חלק בארץ לפי שדברו בה' ובמשה לזה כנסו כל האמורים לצדד עמו במשפט כדי שלא יטה בדעתו לחובתם, או אפשר שנתחכמו בזה כדי שירגיש משה ויעשה מה שעשה כאמור שם בזוהר שנסתלק מן המשפט והקריבו לפני ה', ונראה שהגם שהיה יודע משה שנוטלות נחלה עם כל זה עשה כן ללמד לדיינים שרואים שנחשדים בדין שיסתלקו וכו' כדרך שעשה הוא, או אפשר שחש להם שיהיו כמתלוננים וסלק עצמו מלצדד במשפטם והקריבו לפני ה':
@954 **אבינו מת במדבר**. טעם אומרו **מת במדבר**, לשלול שלא מת במצרים, והכונה בזה בין למאן דאמר נתחלקה לבאי הארץ בין למאן דאמר נתחלקה ליוצאי מצרים זו היא עיקר טענתם, למאן דאמר ליוצאי מצרים אמרו מת במדבר הרי שהיה מיוצאי מצרים, ודקדקו גם כן בתיבת **במדבר** לומר שהיה מכלל אותם שנגזרה עליהם גזירת במדבר יפלו פגריכם (י''ד כ''ט) הא למדת שהיה בן עשרים כשיצא ממצרים, ולמאן דאמר נתחלקה הארץ לבאיה הרי גם הוא מודה שתחזור ליוצאי מצרים וינחילו בניהם ונוגעת הירושה להם בחזרה:
@954 **עוד** יתבאר על פי דברי הזוהר (ח''ב קנז.) שאמר כי המדבר הוא מקום שליטת ס''מ הרשע, וזו סיבת פרעון עונם תכף ומיד כי לפי שהיו דורסים עליו וכופין אותו לא היו משיגים גדר זה לשלוט עליו עד שהיו מתרפאין מנגע עונם, והוא אומרו **מת במדבר** פירוש בשביל היותו במדבר שזולת זה היה ה' מאריך אפו עד שהיה מתקן מעשיו ולא היה מת:
@954 **עוד** יתבאר על דרך מה שאמרו בזוהר (ח''ג רה:) כי במדבר לשון דיבור כי באו להסיר מלב משה לבל יחשוד אותם שיש בלבם עליו ח''ו שיעוול משפטם, ואמרו **אבינו מת במדבר** פירוש איך יעלה על הדעת שיחשבו דבר זה הלא המה ראו את אשר המית ה' אביהם בשביל שדיבר במשה וזה אות להם להרחיק מחשבות און באיש אלהים, ואמרו ראיה לדבר שמיתת אביהם היתה בשביל שדיבר במשה שהרי לא היה בתוך העדה וגו' ודרשו ז''ל (ספרי) שכללו בדבריהם עדת מרגלים ועדת קרח ומתלוננים והוא לא היה ביניהם הא למדת שלא היה לו אלא חטא הדיבור שהרי כמה כתות של רשע היו ולא נמנה עמהם, והוא מה שגמרו אומר **כי בחטאו** לשון יחיד פירוש חטא אחד היה לו ולא יותר, ואולי כי לזה נתכוונו לדבר דבריהם בפני כל הנשיאים והעדה להשמיעם דברים אלו להגדיל אימת משה בלבם, ואפשר כי לזה נתכוון באומרו לאמר אבינו מת במדבר פירוש טעם ותקרבנה לפני וגו' ולפני וגו' לאמר דבר זה אבינו מת בשביל שדיבר במשה הגם שהיה צדיק גמור ולא היה בידו אלא חטא אחד:
@954 **ובזה** נתישבה תמיהת התוס' שהקשו שם בפרק יש נוחלין (ב''ב קיח:) בדיבור המתחיל ולמאן דאמר לבאי הארץ וכו' שמדברי הגמרא מוכח כי למאן דאמר נתחלקה לבאי הארץ לא נטלו הבנות חלק צלפחד הנוגע לו לעצמו בנחלה אלא הנוגע לו בנחלת חפר כשחזרו לו בניו אם כן למה הוצרכו הבנות לומר והוא לא היה בתוך העדה וגו' והלא אפילו בני העדה של המרגלים נטלו בזכות אבי אביהם, ולדרכנו הוצרכו לומר והוא לא היה וגו' לומר כי בחטאו וגו' כמו שפירשתי וחוץ מדרכינו יש ליישב קושית התוספת שהבנות לא ידעו שלא נקנסו המרגלים ליטול בחזרה בנכסי אביהם וחשבו שפקע מהמרגלים נחלה בארץ כל עיקר לזה הוצרכו לומר והוא לא היה וגו':
@954 **ובנים לא היו לו**. ולא אמרו **אין לו**, יתבאר על דרך אומרם בני בנים הרי הם כבנים, והעלו בגמרא (יבמות סב:) שהוא הדין בני הבנות, לזה אמרו לא היו לו כבר אבל יש תקוה שיהיה לו והם אשר ילדו בנותיו שהם נקראים גם כן בניו:
@955 **למה יגרע**. פירוש על פי מה שאמרו במשנה בפרק יש נוחלין (ב''ב קטז) וזה לשונם בנות צלפחד נטלו ג' חלקים בנחלה חלק אביהם וחלקו עם אחיו בנכסי חפר ושהיה בכור וכו' עד כאן, והוא אומרו **למה יגרע** וגו' כנגד חלק צלפחד, **תנה לנו אחוזה בתוך אחי אבינו** פירוש חלק צלפחד שנוגע לו תוך אחיו בנכסי חפר שהיה מיוצאי מצרים וחלק הבכורה כלול הוא במאמר בתוך אחי וגו', ודרך זה אינו אלא למאן דאמר שהארץ נתחלקה ליוצאי מצרים אבל למאן דאמר לבאיה נתחלקה לא נטלו חלקו של צלפחד עצמו, ויתבאר הכתוב בדרך אחר, על דרך מה שאמרו שם דף קי''ח וזה לשונם אמר ליה רב פפא לאביי בשלמא למאן דאמר ליוצאי מצרים נתחלקה וכו' היינו דכתיב חבלי מנשה עשרה שיתא דשיתא בתי אבות וד' דידהו פירוש אחד חלק צלפחד, ב' חלקו בחפר, ג' בכורתו פי שנים, ד' חלקו בירושת אחיו, אלא למאן אמר לבאי הארץ וכו' ומתרץ תרי אחי אבא הוו ליה עד כאן, מעתה אפילו לסברת מאן דאמר לבאיה נתחלקה נטלו הבנות ב' ירושות ירושת צלפחד דאביו פי שנים וירושת ב' אחיו שמתו, לזה אמרו **למה יגרע** וגו' כנגד ירושת חפר שנוגעת לצלפחד בחזרה, **תנה לנו** וגו' כנגד ירושת האחים שמתו שנוגעת לצלפחד גם כן מצד החזרה:
@955 **עוד** יתבאר הכתוב לב' הסברות בהעיר אומרו **למה יגרע** שם אבינו שהיה לו לומר למה תגרע נחלת אבינו. עוד למה חזרו לומר **כי אין לו** אחר שכבר אמרו ובנים לא היו לו, ויתבאר הכתוב על פי דבריהם ז''ל במסכת בבא בתרא דף קי''ט וזה לשונם תנא בנות צלפחד וכו' חכמניות הן שלפי שעה דברו דאמר ר' שמואל מלמד שהיה משה יושב ודורש בפרשת יבמין שנאמר כי ישבו אחים וגו' אמרו לו אם כבן אנו תן לנו נחלה ואם לא תתיבם אמנו עד כאן, והוא מה שאמר הכתוב כאן **למה יגרע שם אבינו** פירוש זו היא טענת יבום להקים שם המת, ולזה דקדקו בלשונם למה יגרע שם אבינו מתוך משפחתו והגרעון הוא כי אין לו בן וה' צוה כי ישבו אחים וגו' ובן אין לו וגו' יבמה יבא עליה וגו', מה תאמר שהבת כבן תחשב ופוטרת אם כן תנה לנו אחוזה בתוך אחי אבינו, והגם דר' שמואל הקדים במאמר הבנות טענת הנחלה לטענת היבום, לא נתכוין אלא לומר ב' הטענות שאמרו ולא דקדק לומר אותם כסדרן, ודרך זה ישנו בין לסברת ר' יאשיה שאמר הארץ נתחלקה ליוצאי מצרים בין לסברת ר' יונתן שאמר לבאיה נתחלקה, לסברת האומר ליוצאי מצרים שואלים גם חלקו של צלפחד עצמו ושאר חלקים הנוגעים לו מובנים מעצמן ולסברת האומר לבאיה נתחלקה שואלים חלקים הנוגעים לצלפחד בחזרה:
@956 **ויקרב משה וגו'**. אפשר שנתכוין לפי דברי תנא דחכמניות וכו' שהבאתי בפסוק למה יגרע ששפטו אם אנו כבן נירש ואם לאו תתיבם אמנו, כמו כן דבר משה לפני ה', וטעמו שאמר כן לשאם יאמר לו ה' אין להם נחלה יתן לו טעם למה לא תתיבם אמם. עוד יתבאר על פי מה שאמרו בבבא בתרא (קיט:) וזה לשונם אמר רבי חידקא שמעון השקמוני היה לי חבר מתלמידי רבי עקיבא וכך היה אומר יודע היה משה שבנות צלפחד יורשות אבל לא היה יודע אם נוטלות חלק בכורה וראויה היתה פרשת נחלות ליכתב על פי משה אלא שזכו בנות צלפחד ונכתבה על ידן וראויה היתה פרשת מקושש וכו' אלא שנתחייב מקושש ונכתבה על ידו עד כאן, וכתבו התוספות שם בדיבור המתחיל יודע היה משה וכו' אף על פי שלא נאמרה פרשת נחלות יודע היה מטעם אם כבן אנו נירש אם כבת תתיבם אמנו כדלקמן עד כאן:
@956 **וקשה** לדברי ברייתא זו מברייתא (זבחים קטו:) שנחלקו רבי עקיבא ורבי ישמעאל בסדר נתינת התורה שכלם מודים שנאמרו כללות התורה ופרטיה בסיני, ולפי ברייתא זו לא נאמר למשה אם יטלו חלק בכורה אם לא עד שנת הארבעים שהיה בערבות מואב אחר מיתת אהרן שכן אמר הכתוב ולפני אלעזר הא למדת שמת אהרן, בשלמא פרשת מקושש לפי שהיתה בשנה ראשונה כאומרם ז''ל (ספרי ח''א קיג:) נוכל לומר שהיה ה' אומרה למשה בסיני אלא שנתחייב מקושש וכו' מה שאין כן מה שלפנינו, ועוד כפי זה מת אהרן חסר ידיעת התורה בפרט דין זה:
@956 **ונראה** כי לעולם כל משפטי התורה נאמרו למשה בסיני כללות ופרטות וכמו כן פרשת נחלות והיה יודע משה ואהרן שהבנות יטלו גם חלק הבכורה, ומה שאמרו בברייתא לא היה יודע שיטלו חלק הבכורה פירוש בארץ ישראל, הכונה אם תחשב ראוי או מוחזק לפי שאין הבכור נוטל פי שנים אלא במוחזק ולא בראוי, ודבר זה לא בא מחמת חסרון ידיעת ההלכה אלא חסרון ידיעת מציאות זה אם קרוי מוחזק או ראוי, וחסרון ידיעת דבר זה אינו חסרון דיני התורה, וכן מוכיחים הדברים ממה שאמרו שם בגמרא שמקשה מברייתא זו של ר' שמעון השקמוני לרבא שאמר ארץ ישראל מוחזקת היא ואמר ואי סלקא דעתך מוחזקת היא מאי קא מספקא ליה ומתרץ היא גופא מספקא ליה במשמעות דקרא (שמות ו') ונתתי אותה לכם מורשה וגו', פירוש אם פירוש מורשה הוא ירושה וכפי זה הבכור יטול בה פי שנים או דלמא פירוש מורשה הוא שיהיו מורישין אותה, ופשטו ליה ירושה לכם ומורישין לבניהם והיינו דכתיב (שם ט''ו) תביאמו ותטעמו וגו' מלמד שמתנבאים ואינם יודעים מה וכו' עד כאן, הדברים מגידים שהספק היה בארץ לא במשפט הבכורה שכבר נאמרה פרשת נחלות, שאם לא כן מה מקשה התלמוד במה נסתפק משה כיון שעדיין לא נאמרה פרשת נחלות עד אותה שעה:
@956 **ונתבאר** גם כן מהגמרא שגם משפט ארץ ישראל אם היא מוחזקת או ראויה נאמרה בתורה אלא שנסתפק משה בפירוש מורשה, וגם אותו ספק יש לו בירור בתורה מפסוק תביאמו ותטעמו ולא הרגיש בו כאומרו מתנבאים ואינם יודעים וכו', ומעתה אומרו **ויקרב משה את משפטן** הוא טענת הבכורה בארץ, ואמר ליה רחמנא **והעברת את נחלת** וגו' ופירש שם שדורש רמז הבכורה מתיבת והעברת כדכתיב (שם י''ג) והעברת כל פטר רחם, והגם שתמצא שכל ענין הנחלות כתוב כאן, בזמנו נאמר בסיני אלא שנקבע כאן, כדרך שאמרו ז''ל (סנהדדין נט:) בענין מילה וגיד הנשה (חולין ק:) שבסיני נאמרו אלא שנקבעו שם, אלא שנשאר לנו לידע היכן רמזו הבנות בדבריהם טענת הבכורה שאומר שעליה הקריב משה משפטן, ואולי כי אין צורך שישאלו אם הדיין יודע שיש להם זכות מה שלא הוזכר בדבריהם ונסתפק בו ישאל עליו לאלהי המשפט. או אפשר שרמזוה במאמר **למה יגרע שם אבינו** שרצו שיהיה הדבר להם כאלו אביהם הוא הנכנס לארץ והדבר מובן שרצונם לומר שיטלו חלק הבכורה בארץ, ולפי זה אומרו **משפטן** פירוש המשפט שתבעו בחלק הבכורה:
@957 **ויאמר ה' וגו' לאמר**. אומרו **לאמר**, פירוש שלא יחשוב משה כי מאמר כן בנות וגו' הם הדברים הנאמרים למשה שהקריב המשפט ואין צורך לאומרם לזולת לזה אמר לאמר שיאמר כמו כן להם, ואפשר שלא להם לבד אלא לישראל, ולזה לא אמר לאמר להם. או אפשר ממה שאמר אחר כך ואל בני ישראל וגו' גילה כי מה שקדם אין צורך לאומרו כי אם לבנות צלפחד, וכפי זה אומרו לאמר הוא לאמר לבנות:
@958 **כן בנות צלפחד וגו'**. הוצרך לאמר **כן** ולא הספיק במה שפרט המשפטים, לומר שדרך המשפט ששפטו בשכלם לכל הפירושים שפירשנו בין לפי מה שאמר התנא דחכמניות היו ששפטו דין ירושה מדין יבום הצדיק ה' מה שדנו בשכלם בין מה שאמרו מדעת עצמן שנוגע להם חלקי הבכורה וחלק אחיהם, עוד נתחכם ה' לומר כן וגו' להעיר כי כל פרטי הדינים אשר יצו ה' בענין כמו שדרשו ז''ל בברייתא במסכת בבא בתרא (קיח:) וזה לשונם נתן תתן זו נחלת אביהן, בתוך אחי וגו' זו נחלת אבי אביהן, והעברת זו בכורה וכו', ואמר ר''א אף חלק אחי אביהן וכו' דכתיכ נתן תתן וגו' לכל אלו הפרטים נתכוונו בנות צלפחד בדבריהם, והוא אומרו **כז בנות** וגו' וחזר לפרש דברים שכלל במאמר כן, הא למדת שהיתה כוונתם לשאול כל האמור, וכבר רמזנום למעלה בדבריהם, ונתכוון ה' גם כן לרומם הצדקניות החכמניות, ואולי כי לזה נתכוון בתיבת **לאמר** לשון מעלה כדרך אומרו (דברים כו) האמירך היום לרוממם במאמר כן בנות צלפחד דוברות, עוד נתכוין ה' ליחד להם תשובה למשפטן בפני עצמן ולא כללן יחד במצוה אחת עם ישראל כשצוה בסמוך דכתיב ואל בני ישראל תדבר לאמר, להראות את אשר יכבד מכבדיו ועושי רצ ונו:
@964 **וראיתה אותה**. ולא הספיק מה שכבר אמר וראה את הארץ, על דרך אומרם ז''ל (ספרי ח''א קל''ו) שהראהו ה' ראיה נסיית מה שאין כח בשיעור עין טבעיית לראות באור השמש זולת באור הגנוז כידוע, ולזה הבטיחו ואמר לו **וראיתה אותה** כי יאיר לפניו אור החיים, וכמו כן תמצא שאמר הכתוב (שם ל''ד) ויראהו ה' וגו' להעיר על האמור:
@964 **גם אתה כאשר וגו'**. יתבאר על פי דבריהם ז''ל (ילקוט ריש פ' מסעי) שאמרו שאמר אהרן למשה אילו היה יודע כן היה רוצה בדבר מקודם לכן, והוא אומרו **גם אתה** סמוך למאמר **ונאספת** לומר שלא יהיה נרתע מהאסיפה שמבטיחו שגם הוא יחפוץ וירצה ליאסף כשיראה עריבות המושג בשעת מיתה, וזה לך האות כאשר נאסף אהרן אחיך שהוא אמר לך שאם היה יודע וכו' הרי שגם החפץ והרצון יסכימו ליאסף. עוד ירצה להעירו במצוה המוטלת על הצדיקים לעשות בשעת מיתה, והוא שיצדיק עליו את הדין ויחפוץ בגזירת מלך שתתקיים, והוא אומרו **ונאספת** וגו' **גם אתה** פירוש אפילו אתה תסכים ליאסף כדרך אומרו (תהלים לא) בידך אפקיד, ואומרו **כאשר נאסף אהרן** וגו' פירוש על דרך אומרם ז''ל (ילקוט שם) שאמר לו משה לאהרן אהרן אחי מקובל עליך למות אמר לו הן אמר לו נעלה להר מיד עלו וכו' עד כאן, והוא מה שרמז במאמר **כאשר נאסף אהרן** פירוש שהסכים גם הוא על האסיפה, וטעם הדבר שעושה ה' כסדר זה לפי שאינו חפץ ליטול נפש הצדיק אלא ברצונו לרוב חיבת ידידיו, גם שבזה ישלמו האושר השלם כאמור (דברים ו) ובכל נפשך:
@966 **וידבר משה וגו' לאמר**. הנה למה שקדם לנו מדבריהם שלשון דיבור יגיד על מענה קשה כפי זה למה אמר הכתוב **וידבר משה לפני ה'** שאין זה מהמוסר, עוד צריך לדעת אומרו **לאמר** שאין לה משמעות במה שלפנינו, ואפשר כי משה בא בטענת משפט לבל ימות, ולא למה שממנו אלא בשביל ישראל כאשר אבאר מאמריו לזה אמר לשון דיבור, ולפי שבמאמר משה האמורים בענין אינם אלא דברי חיבה ורחמנות על ישראל אין תכלית הדברים עומד בנאמר אלא במתחייב מהמאמר שהוא מניעת המיתה ממנו כאשר אבאר והוא אומרו **לאמר**:
@967 **יפקוד ה' אלהי הרוחות וגו'**. צריך לדעת א' למה בחר כינוי זה מכל כינויי המעלה והשבח הידועים לה'. ב' למה האריך לשון **אשר יצא** וגו' **ואשר יבא ואשר יוציאם ואשר יביאם**. ג' אומרו **ולא תהיה עדת** וגו' מנין יעלה על הדעת שה' יעלים עינו מבניו שיהיו כצאן אשר וגו'. אכן יתבאר הענין על זה הדרך דע כי תכונת השכל ובחירתו ושלילתו רחוקה בגדר הנשתוון בריבוי הנושאים, וכשם שישתנו הנבראים בצורתם ובקומתם ואין ההשתוות בהם כמו כן ויותר מהמה בענין השתנות הנבחר והנשלל בבחינת ההשכל והרצון, נוסף על שינוי פרטי הטבע בתכונת ההרכבה שביסודות וכוחות היולים אשר מהם יולד הבחירה בדומים, וימצא לפעמים ההשתוות בתכונה והוא נעלם, והוא מה שכיוונו רז''ל (נדרים לט:) לומר בן גילו בענין ביקור חולים, ומזה תשער שיושלל בגדר הנמצא שישתוו רבים כהמה ס' ריבוא שהיו בדורו של משה לאחד, והמלך אשר ישים ה' עליהם לא ישתוו ברצונם אליו זולת האיש משה שאמרו ז''ל (תיקונים סט) שהיה שורש כל הנשמות של דור המדבר בסוד אומרו (ישעי' סג) משה עמו, ועיין מה שכתבתי בפסוק (לעיל י''א י''ב) האנכי הריתי וגו', וזו היתה סיבה שהפקיד והנפקדים נמזגו לגדר ההשתוות וכל אחד היה לו כלבבו:
@967 **וזה** הוא גם כן טעם שצוה ה' עשות שופטים לשבטיך וכו' לפי שהשבט יתקרב בתכונה לענפיו, וזה ידע ובחן משה עליו השלום ואמר תשובה למאמר המיתה **יפקד ה'** פירוש ימנה, **אל אלהי הרוחות** פירוש שיודע רוח של כל בשר וגדר תכונתם תמנה אחד שיהיה טבעו שוה בתכונה לכל העדה שיסכים הוא למה שיאמרו הם ויסכימו הם למה שיאמר הוא להם, והוא אומרו **אשר יצא לפניהם** פירוש שיהיה לו הרצון בהם, **ואשר יוציאם** וגו' שיהיה להם הרצון כמוהו לצאת ולבא עמו, ותלה הדבר בו כי הוא המלך, ובחירה כזאת היא מוחלטת השגה מזולתו יתברך כי הוא לבדו יודע תוכן הרוחות וידע רוח שתתמזג עם כלן, ואיש כזה אינו בנמצא זולת אם יהיה אדם כמשה שכל ישראל הם ענפיו והוא שורש לכולם, וזולת זה תהיה עדת ה' כצאן אשר אין להם רועה, ותכלית כוונת דברי משה לה' הוא על זה הדרך אני אעשה כאשר אדוני דובר אבל יתקן דבר זה קודם אם יוכל להכנס בגדר התיקון ואם לא תהיה עדת ה' כצאן וגו', והיוצא מזה הוא ולא ימות כרמוז בתיבת לאמר שאמרנו, ומתוך הדברים אתה למד שאם ימצא איש כזה הנה הוא מסכים גם הוא ליאסף אל עמיו כמאמרו יתברך:
@969 **ויאמר ה' וגו' קח לך וגו' אשר רוח בו**. צריך לדעת אומרו **קח לך**, עוד אומרו **אשר רוח בו** וכי יש אדם שאין בו רוח, עוד צריך לדעת מה זו סמיכה. אכן לפי מה שפירשתי בדברי משה באה התשובה שפירש אומרו קח לך פירוש כחששתך ולדבריך קח את יהושע, ודע שהוא איש אשר רוח בו פירוש אתה ישנך שורש כל הנשמות והוא ישנו בבחינת הרוח, והוא אומרו **אשר רוח בו** פירוש שורש כל רוחות הדור ההוא, וצוה ה' לסמוך ידו להעיר לרוח מהות הנשמה שבמשה, והוא אומרו לבסוף **למען ישמעו כל עדת בני ישראל** סמוכה למאמר ונתת מהודך עליו, לומר שבזה יהיה גם כן כלול משורש הנשמות ובזה ישמעו פירוש יקבלו מאמריו, כל עדת בני ישראל פירוש תהיה גם כן תכונת האנשים השלמים בעלי הנשמה מרוצית ממנו:
@972 **על פיו יצאו וגו'**. פירוש חוזר על ה' האמור בסמוך הוא המוציא והמביא בהודעת האורים והתומים:
@973 **ויעש משה כאשר וגו'**. פירוש סמוך למצות המלך, והגם שה' לא צוה לו כן אלא תשובה למאמרו ואין הכרח שיעשה הדבר תיכף אף על פי כן מיהר עשות מאמר ה':
@974 **ויסמוך וגו' ויצוהו**. פירוש לשון צוותא שהאיר בו הוד הנשמה כמו שפירשתי למעלה במה שכתוב וסמכת, וידויק כפי זה אומרו **כאשר דבר ה' ביד משה** שאין משמעות למאמר זה וכי הדיבור הזה ענין הנתפם ביד, אלא פירוש כי ה' דבר שהשפעת ההוד יהיה ביד משה ליהושע. עוד ירמוז אל המלכות על דרך אומרם ז''ל אין צו אלא מלכות (ש''א י''ג) דכתיב ויצוני ה' לנגיד, וידויק גם כן אומרו כאשר דבר ה' ביד משה פירוש כי המלכות דבר ה' שתהיה ביד משה במקום שמן המשחה:
@976 **צו את בני ישראל וגו'**. צריך לדעת למה סידר פרשת הקרבנות במקום זה אחר מינוי יהושע ולא במקום שצוה על הקרבנות בפרשת אמור, שהרי מצוה זו מוכרח אתה לומר שנהגה משהוקם המשכן ויהושע נסמך בשנת הארבעים, ואולי שבא לומר שאם ירצה יהושע להקריב תמידין ומוספין משלו שאינו רשאי הגם שדין ציבור יש לו כדמוכח מכמה מקומות, לזה סדר מצוה זו אחר מינוי יהושע וצוה בה שתהיה משל ציבור כאומרו צו את בני ישראל וגו' לומר שאין התמידים באים אלא משל ציבור, ולזה כפל לומר **ואמרת אליהם** לעיכוב, ודקדק גם כן באומרו **אליהם** ולא אמר להם, לפי מה שפירשתי בפרשת וירא אליו כי ירצה מיעוט זולתו כמו כן במה שלפנינו העיר אותנו שכוונתו למעט, שוב ראיתי לרז''ל (ילקוט) שאמרו וזה לשונם לפי שהיו ישראל אומרים לשעבר היו המסעות נוהגים והתמידין נוהגים פסקו המסעות פסקו התמידין אמר הקדוש ברוך הוא למשה אמור להם שיהיו נוהגין תמידין עד כאן לשונם, וע' פנים לתורה:
@976 **את קרבני לחמי וגו'**. פירוש לפי שיש בתמידין שלשה מיני קרבן, אחד הקרבת התמיד, ב' עשירית האיפה של מנחת התמיד, שלישי הנסכים, כנגד הקרבת התמיד אמר **קרבני**, וכנגד המנחה אמר **לחמי** שנקראת לחם ושניהם כליל לאישים לזה אמר **לאשי**, וכנגד הנסכים אמר **ריח ניחוחי** שאין בו אלא ריח שהוא אינו לאישים אלא יוצק על היסוד ויורד לשיתין, ובשלשה דברים דקדק לומר בכינוי, קרבני, לחמי, ניחוחי, לומר שכולן של הקדוש ברוך הוא בורא הכל ועדיין ברשותו כאומרו (תהלים כד) לה' הארץ ומלואה ופרשנוהו במקומו, ודקדק גם כן לומר **לאשי** בכינוי, לומר שגם האש היא של הקדוש ברוך הוא, ומעתה מה שישראל מקריבין הוא מנכסיו של הבורא:
@976 **לזה** נתחכם ה' ונתן אזהרה ואמר **תשמרו** לומר שאם לא יעשו הנה הם גוזלים נכסיו ועוברים בלאו, ואומרו **להקריב לי** וגו' פירוש כי מה שיעשו הוא הקרבת חלק מנכסיו לפניו אבל עקרן של נכסים הם של המקום:
@976 **עוד** נתכוון בזה להודיע סוד הקרבן שהוא לקרב ענפי הקדושה שהם חלק ה', והוא מה שנתכוין באומרו **קרבני** בכינוי אליו והבן, ואומרו **לחמי לאשי** פירוש לחם ןה שאני מצוה להביא לאישים סודו הוא קרבני שכשעולה לה' ריח ניחוח מתקרבים כל ניצוצי הקדושה שנתרחקו:
@977 **ואמרת להם זה האשה וגו'**. יחד אמירה אחרת, גם אמר **זה האשה**, לבל יחשבו כי מה שיצו ה' כבש אחד וגו' לתמידין הוא לצד ההסתפקות ולא לשיעור הנגבל בשלילת היותר ממנו והפחות ממנו, לזה יחד אמירה להגביל הדבר ואמר זה האשה זה ולא יותר ממנו את הכבש אחד וגו' ואת הכבש וגו', נמצאת אומר שבפסוק ראשון צו את וגו' נצטוו על התמדת הקרבת התמידין, ובפסוק זה נצטוו על שיעור הקרבת התמידין:
@983 **וביום השבת שני כבשים וגו'**. טעם שמוסף שבת הוא מועט מכל מוספי ראש חודש ומוספי יום טוב והמועדים, הוא סוד לחם משנה, ולזה מוספיו שני כבשים על שני כבשי תמיד, וסוד השביעיות רמוז ביום עצמו כי הוא שביעי מה שאין השביעיות מסוים לא בראש חודש ולא בשאר ימים טובים, והגם שיש שביעי של פסח, אין השביעיות קבוע בו כיום השבת והבן:
@985 **ובראשי חדשיכם**. אמר בכינוי חדשיכם לפי שקידוש החודש תלוי בבית דין של של מטה:
@991 **לחדש הזה**. תיבת **הזה** מיותרת ודרשוה רז''ל (תו''כ כ''ג ו') למעט סוכות ממצה, וכבר פירשתיה בפרשת תזריע:
@1000 **בהקריבכם וגו' בשבועותיכם**. נתכוון לומר כי אין החג על סימן מנחה חדשה לבד אלא גם לתשלום ספירת השבועות, כי הוא תיקון גדול לנשמות עם בני ישראל כאמור בספרי אנשי אמת, ודקדק לומר בשבועותיכם בכינוי, להעיר כי השבעה שבועות הם בחינת שבעה הצדיקים יסודי עם בני ישראל כאמור בספר הזוהר (תיקונים כא):
@1000 **עוד** נתכוין באומרו **בשבועותיכם** לשלול דעת שוטים (מנחות סה:) שסוברים במה שאמר הכתוב ממחרת השבת הוא שבת בראשית לזה אמר **בשבועותיכם** פירוש השבועות שלכם, ואם פירוש מאמר ממחרת השבת שבת כראשית אין שביעיות אלו שלהם אלא שביעיות עולם, כיוצא בדבר מצינו שאמרו בברייתא (שם ע''ב) וזה לשונם ר' יהודה אומר תספור לך יצתה שבת בראשית שספירתה בכל אדם:
@1018 **והקרבתם עולה וגו' לה' פרים וגו'**. נראה כי טעם המעטת הפרים יום יום, לפי שיש ב' סודי שביעיות, האומות הם הרבים שבעים אומות ונמשלו לפרים, וישראל גם כן הם בבחינת השבע בסוד בת שבע (זוח''ג) וכל מעשיהם שביעיות, הקרבנות בכל המוספין שבעה שבעה, ימים טובים שבעה שבעה, השבת סוד שבעה ענפי אילן שבו שורש נשמתן שבעה, צדיקים שבעה, ורמז ה' כנגד האומות הרמוזים בפרים שיהיו מתמעטים והולכים:
@1018 **ורמז** בחשבון זה קבוע ארבעה עשר כבשים לרמוז ב' הדרגות שבישראל שבאים ברמז הכבשים אחד נסתר ואחד נגלה, הנסתר הם הברורים שצריך לברר מהאומות, והנגלה הם המבררים, ולזה כשכלים הפרים זה לך האות שכלה מהם הנסתר ולא ישארו כי אם ישראל למופת ואות, והוא מה שרמז ה' בקרבן יום עצרת שבעה כבשים שהם לבני ישראל צאן קדשים, פר הוא הנשאר מהאומות מענף ישמעאל, איל הוא הנשאר מבני עשו הבא מיצחק והבן סוד הדבר:
@1045 **ככל אשר וגו' את משה**. ולא הספיק לומר אותו ומובן שעל משה הוא אומר, להעירך שהוא מאמר בפני עצמו שהם דברי התורה שמעידה ואומרת שהמאמר ממנו אליהם היה ככל אשר צוה ה' את משה, מה שלא היה נשמע אם היה אומר אותו שאז היה נשמע שהוא גמר מאמר ויאמר משה וגו' ככל אשר צוה ה' אותו, ועדיין אני אומר שהוא חשב כן ומי יאמר שלא טעה בדבריו ולא שינה בהסח הדעת:
@1045 **חסלת פרשת פינחס**
@1046 **אל ראשי המטות וגו'**. צריך לדעת מה נשתנית מצוה זו שפרט בה הכתוב **ראשי המטות**, ורז''ל בספרי אמרו לפי שבמאמר החצוצרות הקדים קריאת העדה לנשיאים חש לומר שהעדה קודמת לנשיאים תלמוד לומר אל ראשי וגו' שהם הקודמים, ובמקום אחר (נדרים עח: ב''ב קכ:) אמרו שבא לומר היתר נדרים ביחיד מומחה, וכל זה דרך דרש ואסמכתות עוד צריך לדעת למה הוצרך לומר **המטות לבני** שלא היה לו לומר אלא אל ראשי מטות בני ישראל, והיה נראה לומר שנתכוון לדבר בסדר זה שלא תאמר שלא באה המצוה אלא לראשי המטות ישראל לבד לזה אמר אל ראשי המטות לבני ישראל, וכאילו אמר לזה ולזה, והגם שלא אמר ולבני, הרבה מקראות מדברים בסדר זה כדרך אומרו (שמות א) ראובן שמעון וגו' וכאילו אמר ושמעון:
@1046 **אלא** שראיתי ברייתא (שם) וזה לשונם תניא יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד נאמר כאן זה הדבר ונאמר בשחוטי חוץ (ויקרא יז) זה הדבר מה להלן וכו' אף זו נאמרה לכלן, אם כן אין משמעות אומרו לבני ישראל ולבני ישראל שהרי הוצרכו בברייתא להוכיח מגזירה שוה וכבר אמרו רז''ל (כריתות ה.) וזה לשונם לעולם אל תהי גזירה שוה קלה בעיניך וכו', עוד צריך לדעת כוונת אומרו **לאמר** כי למי יאמרו בני ישראל, ואם הכוונה היא שראשי המטות יאמרו לבני ישראל, היה לו לומר לאמר לבני ישראל. עוד אומרו **זה** הדבר מה בא למעט בתיבת זה:
@1046 **אכן** יתבאר הכתוב בהקדים מאמרם ז''ל שאמרו (חגיגה י.) וזה לשונם היתר נדרים פורחים באויר עד כאן, ויש להעיר למה עשה ה' ממצוה זו סדר זה מה שלא עשה כן בכל התורה שכל דבר ודבר כתוב יושר וזו פורחת באויר:
@1046 **אכן** הטעם הוא כי לא רצה ה' שיהיה כתוב לעין כל אדם שהנדר והשבועה ישנה בהיתר שבזה יזלזלו בנדרים ובשבועות, ולזה נתחכם ה' והעלים הדבר ומסר ההתר לגדולי ישראל שהם ידעו ויבחינו חילוקי המשפטים שבהתר, אבל בפני כל ההמון יהיו נעולי דלת לקיים כל נדר וכל שבועה כאומרו לא יחל וגומר ככל היוצא מפיו וגו'. וזה הוא שיעור הכתוב **וידבר משה אל ראשי המטות** שהם גדולי ישראל המצוה בשלימות, אבל **לבני ישראל לאמר זה הדבר** פירוש כי לבני ישראל בכללות לא יאמר להם מהדיבור הנאמר לראשי המטות אלא זה הדבר ולא הפורח באויר שנאמר בעל פה לראשי המטות, ובזה נתיישבו כל הדקדוקים:
@1046 **או** ירצה על זה הדרך אל ראשי המטות באה המצוה, **ולבני ישראל לאמר** פירוש כי הנודר והנשבע מבני ישראל יבא ויאמר לראשי המטות והם יגידו למו את שישנו בבל יחל ואת שישנו בהתרה כפי ההלכות שבאו במשפט זה:
@1046 **ואם** תאמר לכל הדרכים הרי הוזכרו גם בני ישראל במצוה זו ולמה הוצרכו רז''ל ללמוד הדבר כנזכר, יש לומר שלא הוצרכו לדון בגזירה שוה, אלא לומר שמשה אמר הדברים מפיו לישראל, אבל להודעת המצוה לישראל לא הוצרכו לגזירה שוה, וזה הוא מה שדקדקו לומר יכול שלא אמר משה פרשה זו אלא לראשי המטות ולא אמרו יכול שלא נאמרה פרשה זו אלא לראשי המטות שאז תהיה הכוונה שלא נאמרה כל עיקר:
@1046 **עוד** יש לומר שזולת גזירה שוה שהודיעה שמצוה זו נוהגת בישראל הייתי יכול לפרש אומרו לבני ישראל כאלו אמר של בני ישראל ויהיה הדבר שקול, ואחר שבאה גזירה שוה שהצדיקה המצוה גם בישראל אנו מישבים הכתוב כדרך האמור, ואין להקשות לפי מה שפירשנו זה הדבר שבא למעט שלא יאמר לכל שהנדרים ניתרים בפה והרי צריכה זה הדבר לגזירה שוה, כי הגזירה שוה גמר לה מתיבת הדבר ופירושינו הוא מתיבת זה לבד הגם שהיה אומר זה אשר צוה ה':
@1046 **ובדרך** רמז יתבאר אומרו לבני ישראל **לאמר זה הדבר** על פי מה שאמרו רז''ל (מ''ר כאן) וזה לשונם לעולם יהיה אדם זהיר בנדרים אלף עיירות היו לו לינאי וכו', הרי שהגם שהיו מקיימין שבועתן נענשו, ואמר הכתוב כאן כי יש נדרים ושבועות שצוה ה' אותם, והוא אומרו **לבני ישראל לאמר** אין לאמר אלא גילוי עריות (סנהדרין נו:) פירוש לחשש העריות זה הדבר אשר צוה ה' איש כי ידור נדר וגו', ודקדק לומר **איש** לרמוז לתגבורת ניגוד התאוה כאומרם ז''ל (רות רבה פ''ו) בפסוק חי ה' שכבי וגו' שנשבע ליצרו, וכן אמרו (חגיגה י.) בפסוק נשבעתי ואקיימה לשמור וגו' כי מצוה לישבע ליצרו:
@1047 **איש כי ידור נדר לה' וגו'**. צריך לדעת למה כפל לומר **ידור נדר או השבע שבועה** ולא הספיק לומר כי ידור לה' או ישבע. עוד למה כפל לומר **לא יחל** וגו' **ככל היוצא מפיו**. אכן לפי שיש ב' מיני נדרים ושבועות, אחד בעניינים הנוגעים לנפש ויתחלק לב' עניינים אחד לעשות מעשה הטוב כגון ללמוד וללמד להקדיש לגמילות חסדים ואחד להרחיק התיעוב להגדיר עצמו לבל ידור בשכונת אשה חשודה לבל ילך בחברת פועלי און וכדומה, ב' בענינים הנוגעים לגוף במעשה שאין בו לא איסור ולא מצוה, וגם זה יתחלק לשני דברים, לאכול ולשתות לדור בדירה זו וכדומה, או שלא לאכול דבר פלוני ושלא ללבוש מלבוש זה וכדומה, ויצו ה' משפטיו כדת מה לעשות, ואמר כי ידור נדר סתם נדר יגיד על המעשה שנדר ללכת למקום פלוני או לעשות איזה דבר, ולפי שיש נדר שהוא לה' ודינו משונה מנדרי חול כאשר יבאר הכתוב לזה פרטו ואמר נדר לה', נמצאת אומר שהזכיר הכתוב ב' מיני נדרים נדרי חול ונדרי קודש:
@1047 **ואומרו** או **השבע שבועה** כנגד העדר המעשה כמו שגמר אומר לאסור איסר על נפשו, ויש גם כן בזה ב' נדרים, נדרי חול כגון לאסור דברים שאין מצוה באיסורם, או לאסור גם כן דברים שהם אסורין כגון בועז שנשבע ליצרו, ונתחכם ה' במה שאמר תיבת **לה'** בין נדר לשבועה להסמיך לה' נדר ושבועה לומר שהכפל שבא בנדר ובשבועה הוא פרט הנוגע לה' ולא כללו בכלל נדרי חול לפי שדינו משונה, והוא מה שגמר אומר **לא יחל דברו ככל היוצא** וגו' פירוש כנגד נדרים שהם דברי חול ושבועות שהם מניעת דברים שאין בהם צורכי מצוה כשבועתו של בועז וכדומה לה אמר לא יחל פירוש הוא לא יחל אבל אחרים מתירים לו וכמו שפירשו רז''ל (שם), וכנגד נדרים שהם נדרי הקדשות ונדרי שמים ושבועות שיש בהם צורכי מצוה אמר ככל **היוצא מפיו יעשה** בזה אין בהם תנאי שאחרים יכולין להתירו אלא הם דברים שאין להם התרה:
@1047 **עוד** נראה לפרש טעם אומרו **לה'** על פי מה שכתב רמב''ם בפרק י''א מהלכות נדרים וזה לשונו קטן בן י''ב שנה שנשבע או שנדר בודקים אותו אם יודע לשם מי נדר וכו' עד כאן, והוא מה שנתכוין ה' במאמר **נדר לה'**, כי לפי שקדם ואמר **איש** בא לתת גדר שיקרא איש לדבר זה ואמר נדר לה' פירוש כשידע לשם מי נדר וכן בשבועה כאומרו או השבע שבועה שהדין כמו כן בשבועה:
@1049 **ושמע אביה את נדרה וגו' וקמו כל נדריה וגו'**. צריך לדעת למה התחיל לדבר לשון יחיד, כאומרו נדרה וגמר אומר לשון רבים כאומרו נדריה, גם מה מרבה בתיבות כל נדריה וכל איסר שלא היה לו לומר אלא וקמו נדריה ואסריה. עוד למה שינה בנדרים אמר **וקמו נדריה** ובאסרים **יקום**, גם לא היה צריך לומר יקום והיה סומך על מאמר וקמו שאמר בתחלה, ויתבאר הכתוב על פי מה שאמרו במסכת נדרים דף פ''ז וזה לשונם המשנה אמרה קונם תאנים וענבים קיים לתאנים כולו קיים הפר לתאנים אינו מופר עד שיפר גם לענבים, אמרה קונם ענבים שאיני טועמת ותאנים שאיני טועמת הרי אלו ב' נדרים עד כאן:
@1049 **ואמרו** בש''ם וזה לשונם מתניתין ר' ישמעאל הוא דתניא אישה יקימנו אמרה קונם תאנים וענבים וכו' קיים לתאנים כלו קיים וכו' הפר לענבים אינו מופר עד שיפר גם לתאנים דברי רבי ישמעאל, רבי עקיבא אומר הרי הוא אומר אישה יקימנו וגו' מה יקימנו ממנו אף יפירנו ממנו, ורבי ישמעאל, מי כתיב יפר ממנו, ורבי עקיבא, מקיש הפרה להקמה, אמר ר' יוחנן זו דברי רבי ישמעאל ורבי עקיבא אבל חכמים אומרים מקיש הקמה להפרה מה הפרה מה שהפר הפר אף הקמה מה שקיים קיים עד כאן, זו היא גירסת הספרים שלפנינו, אבל התום' ורמב''ן והר''ן גורסים אבל חכמים אומרים מה הפרה מה שהפר לא הופר אף וכו', ולפי גירסא זו חכמים ורבי ישמעאל הם בסברא אחת בענין ההפרה שלא הופר, וגירסה זו היא עיקר כמו שהוכיחו מהתוספתא:
@1049 **נמצינו** אומרים ג' סברות, א' היא סברת ר' ישמעאל שהביא רבי במשנה שאם הקים חלק מהנדר הקים הכל ואם הפר חלק מהנדר אינו מופר אפילו חלק שהפר. ב' סברת רבי עקיבא שכל שהקים מקצת או הפר מקצת כאלו הקים או הפר הכל. ג' סברת חכמים שסוברים שבין בהפרה בין בהקמה אין הקמתו והפרתו כלום אלא אם הקים או הפר הכל, ולכל אחד מג' הסברות יתיישב הכתוב על נכון, לסברת ר' ישמעאל שסתם רבי במשנה כמותו יתיישב על זה הדרך אומרו ושמע אביה את נדרה לשון יחיד לומר שבנודרת נדר אחד הכתוב מדבר וכגון שאמרה קונם תאנים וענבים שזה יקרא נדר אחד לאפוקי אם אמרה קונם תאנים שאיני טועמת קונם ענבים וכו' שזה יקרא ב' נדרים:
@1049 **ואומרו והחריש** וגו' **וקמו** כל נדריה פירוש אפילו לא החריש אלא מפרט אחד פירוש שמהתאנים והענבים שנדרה בהם לא החריש אלא לתאנים וקמו כל נדריה פירוש אפילו לענבים, ובזה העירך כי אומרו **והחריש** אין הכוונה מהכל שהרי הוצרך להודיעך בקיום ואמר וקמו כל הא למדת שעד עתה במאמר והחריש לא היינו עסוקים לכל נדריה, ואומרו **וכל איסר** וגו' **יקום** נתכוון בשינוי זה להזכירו בלשון יחיד לגלות שמאמר כל נדריה לא שהם נדרים רבים אלא נדר אחד הוא אלא שכללה בו דברים רבים תאנים וענבים, ובערך הנידרים הוא שאמר לשון רבים, והוא אומרו וכל איסר וגו' יקום, והגם שהמאמר בא באיסר, כבר הודיעך הכתוב שדין הנדר והשבועה שוים:
@1049 **ואומרו יקום** ולא סמך על מאמר וקמו שקדם, שאם כן הייתי מפרש כוונת הכתוב שבא לומר שאם נדרה ונשבעה על ב' דברים יחד והחריש לנדר קיים גם לשבועה, לזה אמר יקום לומר שצריך הקמה לכל אחד מהם, ואומרו **ואם הניא** וגו' כל נדריה פירוש צריך שיפר כל נדריה פירוש אם לא הפר אלא לתאנים אינו מופר עד שיפר גם לענבים, ואומרו **לא יקום** לשון יחיד להעירך שבנדר אחד הכתוב מדבר, לבל תטעה ממאמר נדריה וגו' שאין הכתוב מדבר אלא בנודרת נדרים רבים כדין האמור בסיפא של המשנה שכתבנו למעלה:
@1049 **ולסברת** רבי עקיבא שבהפרת חלק הופר הכל ובהקמת חלק כמו כן הוקם הכל יתבאר על זה הדרך **ושמע אביה את נדרה** וגו' **והחריש** וגו' פירוש אם שמע אפילו חלק מנדרה הגם שלא שמע כל נדרה והחריש לאותו חלק בזה ו **קמו כל נדריה** אפילו חלק שלא שמע, ואומרו **ואם הניא אביה אותה** פירוש אפילו לא הניא הכל אלא חלק אחד כל שאנו קורין בו הניא אותה, ולזה לא הסמיך מאמר כל נדריה למאמר ואם הניא על זה הדרך ואם הניא אביה כל נדריה ביום שמעו, ואז לא היה צריך לומר תיבת אותה, וכפי זה מאמר כל נדריה וגו' נמשך למטה למאמר לא יקום, ואמר **לא יקום** לשון יחיד נתכוון בזה לומר חידוש הדין שאפילו מה שלא הפר הופר:
@1049 **ולדרך** זה יתישב על נכון מאמר **וה' יסלח לה** וגו', פירוש שאם לא הניא אביה אלא לענבים והיא אינה יודעת המשפט שגם לתאנים הועיל הביטול ואכלה תאנים מודיע הכתוב שה' יסלח לה כי צריכה סליחה כיון שלדעתה לא הניא על התאנים, ונתן טעם הסליחה כי הניא אביה אותה פירוש כי הביטול שעשה אביה הועיל גם לזה, והוצרך לומר כן להעירך שהדבר שעליו בא הסליחה הוא על העדר ידיעה זו שממנה יצאה השגגה והבן:
@1049 **ולסברת** חכמים שאמרו שלא תועיל הפרה למקצת ולא הקמה למקצת עד שיפר לכל או יקום לכל יתבאר על זה הדרך ושמע אביה את נדרה אמר לשון יחיד להעירך שהכתוב מדבר בעשתה נדר אחד ולא בעשתה ב' נדרים כמו שפירשתי לסברת רבי ישמעאל ואומרו **והחריש** וגו' **וקמו כל נדריה** מאמר כל נדריה נמשך לפניו ולפני פניו וזה פירושו והחריש לה אביה אימתי יועיל החרישה להקים אם יהיו כל נדריה אבל חלק ממנה לא תועיל לו הקמה:
@1049 **ואומרו ואם הניא** וגו' **כל נדריה** וגו' מאמר כל נדריה נמשך למעלה על זה הדרך **ואם הניא** וגו' אם בהפרתו הניא הכל אז לא יקום פרט מהם, ולהודיעך בא שאם הניא פרט אחד אין אנו קורים בו לא יקום, והגם שנאמר שמאמר כל נדריה נמשך למטה למאמר לא יקום יתבאר על זה הדרך כל נדריה וגו' לא יקום פירוש בזמן שיש כל נדריה בכלל אז ישנו לפרט הא למדת שאין ביטול לפרט לבדו, וכל זה דוקא שעשתה נדר אחד כמו שרשם במאמר ושמע אביה את נדרה, אבל אם עשתה אותם בגדר ב' נדרים אין נתלה זה בזה:
@1057 **ואם הפר יפר וגו'**. טעם שכפל לומר **הפר יפר**, גם ריבוי **כל מוצא**, יתבאר על פי מה שאמרו בנדרים פרק י''א (פ''ב:) וזה לשונם אמר רב יהודה וכו' נדרה מב' ככרות בא' מתענה ובאחת אין מתענה מתוך שהוא מפר למתענה מפר גם לשאינה מתענה עד כאן, והוא מה שנתכוון הכתוב בכפל **ואם הפר יפר** פירוש אם הפר בחלק שיש לו הפרה. יפר לרבות גם חלק שאין לו בו דין הפרה, ואמר **כל מוצא שפתיה** וגו' פירוש טעם שהוא מפר גם חלק שאין בו דין הפרה לפי שהוא כלול עם דבר שיש בו הפרה וכשהוא מפר מפר כלם יחד, ולסברת רב אסי שחלק שם בנדרים וזה לשונו רכ אסי אמר מפר למתענה ואינו מפר לשאינו מתענה עד כאן, יתבאר על זה הדרך אם הפר פירוש דבר שיש בו דין הפרה, יפר פירוש תועיל הפרתו אבל לא חלק שאין בו דין הפרה, ואומרו **כל** וגו' **לנדריה** פירוש אפילו הם כלולים יחד ב' דברים אחד מתענה בו ואחד אין מתענה בו:
@1057 **עוד** יתבאר על פי מה שאמרו שם במשנה דף פ''ז וזה לשונם יודע אני שיש מפירין אבל איני יודע שזה נדר רבי מאיר אומר לא יפר וחכמים אומרים יפר עד כאן, והוא מה שנתכוון הכתוב במאמר **הפר יפר** פירוש אפילו אין לו שגגה אלא בהפרה תועיל לו להפר אחר זמן כשידע שיש מפירין זו כדברי חכמים, ולרבי מאיר יתבאר הכפל לומר שיש מציאות שהגם שלא הפר בזמנו יפר שלא בזמנו וכגון שלא ידע שיש מפירין, ואומרו **לנדריה** לסברת רבי מאיר יתיישב על זה הדרך אימתי אמרתי לך שיכול להפר אחר כך כשלא היתה לו השגגה בנדרים, והוא אומרו **לנדריה** פירוש כשיכיר נדריה, ולסברת חכמים יתבאר אומרו לנדריה הכרת היותה נדריה, הא למדת שבה שגג ואף על פי כן ריבה בו הפרה לומר שיכול להפר לכשידע שהם נדרים:
@1060 **ואם הפר יפר**. פירוש אפילו בנדרים שיש בהם הפרה אם יפר ונשא וגו':
@1062 **וידבר ה' וגו' לאמר נקום וגו'**. קשה אם הדיבור בא לאמר לישראל כנשמע מתיבת לאמר היה לו לומר נקמו נקמתכם מאת וגו', ובמדרש תנחומא אמרו וזה לשונם אין וידבר אלא לשון עז וכו' התחיל משה לפייס הקדוש ברוך הוא על מיתתו ולא נתפייס וכו' אמר לו משה לי ראוי מיתה שראיתי נפלאות וכו' ופייסו ה' בב' דברים אם אתה רוצה לחיות שנים רבות לא יראו ישראל במפלת אויביהם ולא תכבש מדין לפניהם וכו' וכיון שנתפייס משה היה קשה לפני הקדוש ברוך הוא שקנס עליו מיתה וכו' עד כאן, הנה בעל המדרש הרגיש במה שדקדקנו ולדבריו יתיישב הכתוב על נכון, וידבר לשון קושי זה ירמוז לב' מיני קושי, א' למשה על מיתתו, וא' בעיני ה' על שקנם על ידידו המיתה, ותיבת **לאמר** נתכוון לרמוז אל הפיום שפייס ה' למשה להתפייס למות מטעם נקום וגו' כאמור במדרש, או ירצה בתיבת **לאמר** להודיע ריצוי שריצה משה לה' כדי שלא ימות, וענהו ה' נקום וגו' פירוש בשביל שינקום מאויבי ישראל:
@1062 **ולפי** פשט הכתוב יתבאר על זה הדרך וידבר ה' אמר לשון דבור לומר דיבר אליו דבר מלך שלטון כשאר כל הציווים שבתורה, ואומרו **לאמר** כפשטה לאמר לישראל ככל לאמר האמורה בתורה, וכאן צריכה ליאמר יותר מכל המקומות לפי שאמר נקום תבא לו הסברא שהוא לבד יעשה הנקמה כפשט המאמר ואין זה דבר זר כי גבור חיל היה וה' בעזרו, וצא ולמד מיהונתן בן שאול וגו' (ש''א י''ד) ומכל שכן משה גבור הגבורים לז''א אליו לאמר לישראל, ואומרו **נקום** וגו' פירוש לפי שתלה לו ה' מיתתו בנקמת מדין דכתיב אחר תאסף וגו' אמר אליו כי במה שיאמר הדברים הוא להם בזה מעלה עליו הכתוב שהוא הנוקם כי הוא מוסר נפשו ממש על הדבר שהגם שיודע שבאמצעות כן ימות אף על פי כן יאמר לישראל מה שאמר בסמוך אין לך קיום מצות בכל נפשך כזו, ובסמוך יתבאר באופן אחר:
@1063 **נקום נקמת וגו'**. משמעות הכתוב יגיד שהטיל ה' על משה להנקם ממדין, וראינו שאפילו למלחמה לא יצא עמהם, והגם שפירשתי שהנקמה היא האמירה שיאמר להם, על כל זה פשט הכתוב משמע שהוא עצמו ינקום לא שישלח פינחם במקומו, עוד למה תלה אסיפת משה בנקמת מדין:
@1063 **אכן** כונת מאמר נקום סובלת ב' דרכים, א' הוא השתדלות סדר המעשה פירוש התחכמות סדר המלחמה לתועלת הניצחון בין בשיעור הצריך בין בסדר שבו ישיג לאבד קמיו והערכת הלוחמים וכדומה, ב' המלחמה עצמה שהיא פעולת הנקמה, והבין משה פירוש צודק כי כונת נקום וגו' שאמר ה' היא התחכמות סדר הדבר שבאמצעותו תהיה הנקמה, ופירוש זה הצדקתו היא ממה שלא אמר לו ה' בפירוש הלחם במדין שהוא לשון מוכרע, גם לפי שהשכיל במה שלפנינו שהוא צריך להתחכמות בסדר הדבר מטעם כי הנה העם אשר יצו ה' עליהם הנקמה הם עם אשר נכשלו בני ישראל בהם בעריות מהם במעשה מהם במחשבה, והגם שנגף ה' כמה וכמה סוף כל סוף ימנע מהם הנם בהם, ואדרבה יקטרג המקטרג להפילם במלחמותם לצד שמץ העון, וזה ידמה למעשה העגל שהגם שנגף ה' כל עובדיו עם כל זה יצו ה' לבל יכנס כהן גדול לפנים בבגדי זהב, גם צוה (פדר''א פ''ד) שוכני שמים לכסות בכנפיהם את רגליהם שדומים לרגל עגל לבל יתעורר המקטרג, ומכל שכן בעת המלחמה שיתעורר המקטרג על החטא שבא מהם, וצא ולמד (סוטה מד:) שיעור החטא שיחזרו עליו מעורכי המלחמה, וכמו כן יתפסו בכל שהוא מהרהור התיעוב, ואין צריך לומר שיהיו מנועי הנס, ולזה כשאמר ה' למשה נקום אמר ודאי כונת ה' הוא התחכמות בסדר הענין להרים המיחוש האמור, וזו היא עיקר הדבר שתעלה בידם הנקמה, וכמו כן עשה בחכמתו עבד ה' כאשר אבאר בסמוך:
@1063 **ואומרו אחר תאסף אל עמך** נראה כי נתכוין לומר לו שקודם לכן אינו שלם התיקון יאסף אל עמיו, פירוש שיהיה לו מונע בדין וימנענו מגשת נפשו למקום מושבה שיקרא עמיו כידוע עד שיעמידנו במשפט, כי על הכל יביא ה' במשפט וסביביו נשערה מאוד, והמונע הוא לפי שהשלם הזה נתרפה במעשה זמרי ולא עשה דבר כאומרם ז''ל (במד''ר פ''כ) שרפו ידיו והקפיד ה' עליו שלא נקם עד שעמד פנחס, ולזה כשהגיע זמן פטירתו אמר ה' אליו תיקון לדבר זה שנמנע מהתנקם מעושי רשע יקום ויתנקם ממדין שסבבוהו, ואחר שישלים התיקון ליאסף אל עמיו באין שטן ואין וכו', וזה מחסדי אל ואהבתו לידידיו ינחם במעגלי צדק:
@1063 **מאת המדינים**. אומרו **מאת** ולא הספיק לומר מהמדינים, אולי שרמז לזולתם הנמצא אתם והוא בלעם שנמצא שם אז והרגוהו דכתיב (ל''א ח') ואת בלעם וגו'. ואולי כי לזה מיהר ה' הדבר קודם שיחזור בלעם לארצו כי לא היה במדין אלא לקחת שכרו כאומרם ז''ל (סנהדרין קו.) ועומד לחזור, וה' פרש רשת לרגלו וצדו לחרב נוקמת:
@1064 **וידבר וגו' לאמר החלצו וגו'**. צריך לדעת א' אומרו **לאמר** למי יאמרו. ב' אומרו **החלצו** וגו' למה לא צוה כסדר שאמר במלחמת עמלק ליהושע (שמות י''ז) בחר לנו אנשים כמו כן כאן היה לו לצוות לפינחס ששלח עמהם ולא לכללות העם, גם שאין דרך זה נכון כי מי מפים לדעת מי זה הוא שיזרז עצמו לצאת וכל אחד יאמר לא עלי המצוה לעשות. ג' אומרו **ויהיו על מדין** שהיה לו לומר וילחמו במדין כדרך אומרו (שם) הלחם בעמלק. ר' למה שינה מדברי ה' כי ה' אמר אליו נקום נקמת בני ישראל והוא אמר נקמת ה' והיה צריך לדייק מאמר ה'. ה' אומרו **אלף למטה** למה לא שלח כל העם לעשות נקמה בגוים הרשעים ועל מי סמך לשלוח אנשים מועטים י''ב אלף לעם רב, וצא ולמד ריבויים מטפם הנשארים שהיו שנים ושלשים אלף:
@1064 **אכן** לפי מה שהקדמנו כי יש בענין מלחמה זו מיחוש צודק ולזה בא האלהים בנועם דבריו למשה נקום וגו' להעירך סדר המלחמה בסדר שבו יקיים דבר הנקמה אשר צוה ה', לזה נתחכם ולא רצה לבחור אנשים על ידי הזולת כי מי יודע האנשים אשר לא חשבו מחשבות און ולא טעו במכשול אומה זו, ויעץ ואמר להם שיחלצו מהעדה פירוש הם מעצמן כל מי שיודע עצמו שהוא בר לבב ונקי כפים ימסר לחשבון האלף למטה, והוא מה שרמז בתיבת **לאמר** מאמר הנעלם שהוא ענין נקיותם מחטא מדין להבחין בעצמו כל אחד מהנמסרים אם הוא נקי ובר, ואולי כי רמז גם כן בתיבת **לאמר** ענין העריות כאומרם ז''ל (סנהדרין נו:) לאמר זו גילוי עריות שאמר להם שצריכין שיהיו החלוצים נקיים מהחטא, וכמו שגמר אומר אנשים לצבא ואמרו רז''ל (תנחומא) כל אנשים צדיקים והגם שפירשנו במקומות אחרים שאין זה אלא כשתהיה תיבת אנשים יתירה, במה שלפנינו יגיד עליו ריעו מה שדייקנו בענין, ולזה אין להם לחוש למכשול כיון שהיוצאים לצבא צדיקים, ועוד להם שיקראו חסידים כיון שבא לידם עון זה וניצולו ממנו כאומרם ז''ל (זוח''ג קצה:) שלזה יקרא חסיד, באמצעות כן תהיה הנקמה באין מיחוש, ולזה לא רצה שירצו כל ישראל לצבא כי בדרך זה יש מיחוש מניעת הנקמה ואדרבה להיפך כנזכר:
@1064 **ואומרו ויהיו על מדין** יתבאר על פי מה שאמרו אנשי אמת שבחינת הקדושה הוא יסוד העליה ובחינת הקליפה היא סוד הירידה וכשאדם חוטא ונדבק בו חלק הרע תפעיל בו טבעה ויסודה להשפילו, ופרט זה פירשנוהו בפרשת כי תשא את ראש בני ישראל שהחוטא יכוף כאגמון ראשו ועומד בגדר השפלות, והוא אומרו **ויהיו על מדין** פירוש שלא יהיה בהם מהטומאה הסובבת השואתם למדין אלא יהיו בגדר הטוב שעומדים למעלה:
@1064 **ואומרו לתת נקמת ה'** גם זה מההתחכמות להשגת הנקמה שצוה אותם שתהיה כוונת הנקמה לקנאת ה' אשר גרמו ביטול מצותיו ורצונו יתברך ולא להתנקם על המסובב מהחטא שמתו כמה מישראל, כי לכשתהיה הכוונה על זה אין במעשה מצוה להסתייע באמצעותם להנקם מאויב, והגם שה' אמר אליו נקמת בני ישראל, לא אמר אליו שיאמר לישראל לשון זה אלא שדבריו היו עם משה נקום נקמת בני ישראל, ומשה נתחכם לעשות הדבר בדרך זה לקיים הנקמה של ישראל שנצטווה עליה במאמר נקום:
@1064 **עוד** יתבאר הכתוב על זה הדרך שאין צורך שילחמו הם אלא יהיו שם עליהם פירוש בשבילם, והטעם **לתת נקמת ה'** פירוש נקמה שיתנקם ה' במדין באמצעותם על דרך אומרו (שמות יד) ה' ילחם לכם, ואמר הכתוב **וימסרו מאלפי ישראל** פירוש כל מי שהיה יודע בעצמו שעומד בצדקו מסר עצמו לדבר עד שבאו לכלל האלף, והגם שהיו בישראל כהנה וכהנה מהצדיקים, נתחכם ה' כדי שלא לבייש הנשארים שלא יהיו ניכרים:
@1067 **וישלח וגו' אותם ואת פנחס וגו'**. אומרו **וישלח**, נתכוין לעשותן שלוחי מצוה לנקום נקמת ה' ושלוחי מצוה אינן ניזוקין, וכפל לומר אותם פעם ב' לרמוז ששקול פנחם כנגד כלן, וטעם שבחר בפנחם ולא יהושע וכדומה, גם זה מהתחכמות הנקמה כי זה הוא אשר קינא ועשה בהם שפטים מופלאים וסמוך הוא בכח מופלא להשמיד כל האומה הטמאה, גם אפשר שחש משה לקטרוג האנשים למה לא מיחו בזונים הגם שהם נקיים לזה נתחכם ושלח המקנא קנאת ה' במסירת נפשו, ואולי כי הוא מה שדקדק במאמר **אותם ואת פנחס** לומר ישלים זה מה שחסר לזה, ואולי כי דבר זה היה בלב תעלומות חכמה שנקמת מדין צריכה להיות על ידי פנחם, והן האדון חשב לטובה שלא יכלים משה לומר לו בפירוש שלח את פנחם שזה יגיד שנפסל ח''ו הוא מהמעשה, לזה נתחכם ותלה הדבר ביד משה ואמר לו נקום וגו' ומשה מעצמו ידע הנכון עשות וישלח פנחס, ובזה נעשית מחשבת ה' לטובה ולא נכלם משה ידיד ה':
@1069 **ואת מלכי וגו' חמשת וגו'**. טעם שהוצרך הכתוב להזכיר מניינם, לומר שנהרגו יחד זה עם זה וראו זה את זה במפלתן. ואומרו **מלכי מדין** פעם ב' אולי שנתכוין בכפל הדברים לומר שהרגום בידיעה שהם מלכי מדין ולא בהסח הדעת:
@1069 **הרגו בחרב**. הוצרך לומר **הרגו** הגם שמובן הוא שהרגוהו מסמיכות זכרונו עם הנהרגים, יתבאר על פי דבריהם ז''ל (ספרי) שאמרו כי בלעם הלך ממדין לקראת ישראל ליעצם לבל ילחמו במדין ואמר להם ומה כשהייתם כו' עד כאן, הדברים יגידו כי בלעם נהרג קודם הריגת ה' מלכי מדין, והוא מה שנתחכם ה' ויחד לו הריגה בפני עצמו להעירך שלא נהרג עמהם שלא היה מובן כן אם לא היה אומר הרגו, ואומרו **בחרב** לומר שבטלו כשפיו בערך ישראל והרגוהו בגשמי:
@1077 **הן הנה וגו' בדבר בלעם**. צריך לדעת כונת אומרו **הן הנה**, עוד למה האריך לומר בדבר בלעם וגו' על דבר פעור, ויתבאר הדבר בהעיר למה שגגו פינחם וצדיקי עליון שהלכו עמו בדבר זה:
@1077 **אכן** פינחס ואנשי הצבא דנו ופטרום מטעם שהנשים כפופות הן לבעליהם ולאבותיהם ואנוסים המה, והן האדון משה רבינו עליו השלום הרגיש שמטעם זה החיו אותם ובא בטענה הנשמעת ואמר בשלמא אם לא היו עושים אלא מעשה הזנות שבא להם עליו מצות גדוליהם יש לדון אותם לזכות, אלא שהם עשו מעצמן מעשה אחר מה שלא ציוו אותם גדוליהם שהוא מעשה פעור שאמרו רז''ל (במד''ר פ''כ) שהיו מוציאים להם צורת פעור ואומרים להם השתחוה לזה ותהיה נשמעת לו נמצא שמכשול עבודה זרה היה מהם, והוא אומרו **הן הנה** פירוש מדנפשם היו סיבה לבני ישראל, **בדבר בלעם** וגו' פי' באמצעות סיבת עצת בלעם שיעצם להפקיר בנותיהם לזנות, ותמצא שלא אמרו ז''ל שאמר בלעם אלא ענין הזנות כאומרם (שם) אלהיהן של אלו שונא זימה וכו' והם היו סיבה למסר מעל בה' על דבר פעור שלא היו רוצים להשמע להם אלא אם ישתחוו לפעור, **ותהי המגפה בעדת ה'** פירוש בסיבת עבודה זרה ולא בסיבת הזנות, ומי גרם עבודה זרה הן הנה, ואומר ועתה וגו' פירוש יתודו על השגגה ויהרגו וגו':
@1078 **הרוגו**. הוצרך לומר פעם ב' הרוגו, אמר ר' ישמעאל (ספרי) להפסיק וכו', שאם לא כן יהיה מאמר וכל אשה וגו' שקול אם נמשך למעלה או למטה, וקשה שהיה לו להקדים תיבת החיו לכם בפסוק וכל הטף על זה הדרך החיו לכם, ובזה אין צורך לכפול מאמר הרוגו, ואולי שחש לומר כן שאז תהיה הכוונה שהוא מצווה אותם להחיותם, ולא כן מחשבת ה' אלא רשות הוא אומר שאין מצוה להמיתם, ולזה הקדים מאמר וכל הטף וגו' לומר שלא בא אלא להודיע מה יהיה דינם לא לצוות בהם:
@1078 **ועוד** נשאר לנו ליישב מה שקשה עוד למה אמר **הרגו** בתחילת הכתוב ולא הספיק בהרוגו שאמר לבסוף, ואולי שנתכוון להסמיך מאמר הרגו למאמר ועתה לומר שהתשובה הרמוזה בועתה היא במעשה הריגה, וכל עוד שלא הרגו לא קיימו תשובת החטא, או אפשר שנתכוון להסמיך הרגו לטף והרוגו לאשה וכו' לומר שיש מצוה על אלו בפני עצמן ועל אלו בפני עצמן. או נתכוין להסמיך זכרון ההריגה לתיבת ועתה לומר שיהרגום תיכף ומיד:
@1079 **החיו לכם**. פירוש יגיירו אותם שבזה יקראו חיים כדי שיהיו ראויות להם להנשא לחפץ בהם:
@1093 (לב~מג) **ויהי המלקוח וגו' ותהי המחצה וגו' ויהי המכס וגו' ותהי מחצת וגו'**. צריך לדעת למה האריך כל כך בפרטי החשבון בדבר שיכול כל הבא למנות לידע כי כך יעלה למחצה וכן יעלה למכם וגו', גם בענין מחצת העדה לא האריך לומר כל פרטי הסכומים אלא חשבון העולה במחצית המלקוח וגם עליו דן אנכי שלא היה צריך לאומרו, והרמב''ן עליו השלום כתב טעם הדבר שבא להודיע שלא נחסר אחד מזמן המספר לזמן שחצוהו עד כאן, ואין נראה בעיני דבר זה שמה שלא נחסר מהמקנה בזמן מועט שיש בו נם, ומה גם שיצטרך הכתוב לכתוב כל הדברים בשבילו:
@1093 **והנכון** בעיני הוא שהודעת פרטי החשבון במחצית חלק היוצאים בצבא הוא לגלות שהמכם היה מלגיו לא שהיה מונה חמש מאות ונותן אחד לה' מפאת המכם אלא מונה תצ''ט ונותן אחד, ולזה העלה כל פרטי חשבון המכם וממנו תדע שהיו נותנים א' לתצ''ט, והודעת חשבון מחצת העדה בא הכתוב להסיר טעות אחר והוא שיאמר האומר לעולם מכס שנתנו אנשי הצבא היה אחד מת''ק מלבר ואין ראיה מסכום המכס שעלה המכס לומר שאם כן לא היה עולה מכס של של''ז אלף וחמש מאות צאן למספר האמור יש לומר שהיו נותנים אותו המכס ממחצית העדה שבזה יעלה מספר האמור במכס חלק הצבא הגם שיהיה ניתן מלבר, אשר על כן בא הכתוב ומנה מספר חלק העדה ומנאו שלם להסיר מיחוש זה, ולזה לא פרט הכתוב במספר חלק העדה אלא מספר המחצית לצורך מה שכתבתי שהמכם ניתן מלגיו וכל אחד שילם חלקו ממחציתו, והוא גם כן מה שציוהו ה' במאמר ממחציתם תקחו לומר שלא יפרעו המכם אלא ממחציתם וגם אמר אחד מחמש מאות הא למדת שצריך שיהיה המכס מלגיו:
@1110 (מט~נ) **ויאמרו אל משה וגו' ונקרב וגו'**. פירוש מאמר **ויאמרו** וגו' **ולא נפקד** וגו' הוא להסיר מהם חשש מכשול עון כמובן ממין הקרבן אשר הקריבו תכשיטי נשים, ומאמר **ונקרב** וגו' הוא טעם הקרבן שהוא לכפר על הרהור עון, כמאמרם ז''ל בשבת (סד.) ופירשתיהו בחיבורי (חפץ ה'):
@1112 **כל כלי מעשה**. הודיע בזה ריבוי השלל של מדין לבד היה ששה עשר אלף ותש''נ, ואמר עוד **אנשי הצבא בזזו איש לו** אחר שכבר הודיע הכתוב למעלה ביזת אנשי הצבא שבזזו לעצמן, גם אין זה מקום הודעה זו, אלא בא להודיע כי לא כל כלי זהב של מדין היו אלו אלא מה שהביאו הממונים של הצבא מלבד מה שבזזו אנשי הצבא כל אחד לעצמו, והכוונה בזה שמצאו להם עושר גדול:
@1115 **אל אהל מועד זכרון וגו' לפני ה'**. צריך לדעת למה כתב בסדר זה שהפסיק בין זכרון המקום ובין מאמר לפני ה' שהיה לו לומר אל אוהל מועד לפני ה' זכרון לבני ישראל, ויתבאר הכתוב על פי מה שאמרו במסכת כלה וזה לשונם אמר רב אחאי בר יאשיה כל המפנה עצמו מן העבירה אפילו הוא ישראל ראוי הוא להעלות עולה ככהן גדול על גבי המזבח וכו' עד כאן, ומה שלפנינו כל כלי מעשה שהרימו הפקודים היו מהאנשים שפינו עצמן מהעבירה והכלים באו מגוף הדבר, שאמרו ז''ל (שה''ש פסוק שיניד) שכך היה מנהגם באותה מלחמה כשהיו מפשיטים תכשיטיהם היו טחין פניהם בטיט ורפש והיו פורקין נזמיהם מהם שלא יסתכלו בהם, והוא מה שנתכוון במה שסמך מאמר לפני ה' למאמר לבני ישראל כי בני ישראל אלו ראוים להיות לפני ה' כמאמר רב אחאי בר יאשיה והיה הדבר לזכרון:
@1116 **ומקנה רב וגו'**. טעם הודעה זו, להצדיק הכתוב טעם הנמצא בפיהם לשאלת ארץ סיחון ועוג כי אמת הוא, וטעם שהיה להם יותר מכל השבטים להיות שהיו גבורי כח בזזו אנשי הצבא חלק מרובה מכל השבטים:
@1117 **ויאמרו אל משה ואל אלעזר הכהן ואל נשיאי העדה**. צריך לדעת למה לא הספיק להם לדבר למשה לבדו, ואם אין צורך בדבר למה הוצרך הכתוב להזכירם, ואולי שהכוונה היא לומר שהיה הדבר כדרך שצוה ה' עשות בנחלת הארץ, דכתיב בפרשת אלה מסעי (ל''ד י''ז) אלה אשר ינחלו לכם את הארץ אלעזר הכהן ויהושע בן נון ונשיא אחד נשיא אחד וגו' שצריך מלך וכהן גדול והנשיאים והם האמורים כאן, וטעם שהצריך ה' שלשתם לפי שכל אחד יש לו כח אחר, המלך תמצא שכתב רמב''ם בפרק ד' מהלכות מלכים וזה לשונו כל הארץ שכובש הוא שלו ונותן לעבדיו ולאנשי המלחמה כפי מה שיראה עד כאן, הרי שהמלך בידו הכל, אלעזר והנשיאים כשאין רצון המלך לתת אלא לכל אחד הראוי לו כפי החלוקה צריכין כל בעלי החלוקה להזדמן לחלוק, והכהן לדעת אשר יסכים אל עליון באיזה מקום יטול פלוני חלקו, הא למדת שכל הג' צריכין להיות בהסכמת נתינת חלק בארץ כל אחד יש לו כח אחר, ומה גם שיש בזה לצדד שאין דין מלך שנותן למי שירצה אלא אחר חלוקת הארץ וישיבת ישראל בעריהם אבל לא בתחילת הירושה שאין למלך משפט זה, ולכן הוצרכו בני גד ובני ראובן לעמוד גם כן לפני אלעזר והנשיאים, ואומרו **לאמר**, אולי ירצה שיאמרו לישראל כולן דבר שיסכימו עליו, או ירצה אמירה רכה לשון ריצוי:
@1118 (ג~ד) **עטרות וגו' הארץ וגו'**. צריך לדעת א' למה הוצרכו לפרט כל העיירות ולא הספיק במאמר הכללי שאמרו הארץ אשר הכה ה' וגו' ששם כלולים כל הארצות ההם, או היה להם לומר כדרך שהזכירם הכתוב בסמוך בב' כללים דכתיב את ארץ יעזר ואת ארץ גלעד, ב' אומרו **הארץ אשר** וגו' וכי היו לפניהם ארצות אחרים ששמם כמו כן שהוצרכו לסמן אלו, ואם לומר שה' הכה אותם מי לא ידע בזה:
@1118 **אכן** הכוונה היא על זה הדרך כי האנשים האלה השכילו לדבר בסדר שלא יהיה מקום להקשות לשאלתם מה שיש להקשות בענין. א' כיון שהארץ הלזו היא של כללות ישראל מה כוחם לשאול דבר של אחרים. ב' איך יעלה על דעתם שישבו בטח בארץ אשר כבר נכבשה ושאר השבטים יכנסו בסכנת המלחמות העצומות המוכנות להם, וכל אחד מישראל יאמר כדבריכם אדבר גם אני ולא אכנים עצמי בסכנת העמים, וכל זה למה שנוגע לשלילת הרצון ממשה וישראל, לבד מה שיש להתרעם עליהם שבוחרים לשבת חוץ לארץ הקדושה והנבחרת לה':
@1118 **אשר** על כן נתחכמו בני גד ובני ראובן במאמר ראשון ונתנו תשובה לג' דברים הנזכרים המריעים שאלתם במה שאמרו **עטרות** וגו' **הארץ אשר הכה ה'** וגו', כנגד טענה א' שהארץ היא של כללות ישראל יש במאמר זה תשובה לזה שלא לקחו הארץ בדרך טבע לומר הלא לנו היא אלא ה' הוא שהכה יושביה לפניהם ואין זה אלא נכסי שמים ומנכסי גבוה אנו באים לשאול, גם טענה ב' שאחיהם יכנסו בסכנת מלחמות וכו' סתרוה במאמר זה **אשר הכה ה'** פירוש בשלמא אם ירושת הארץ היתה בדרך טבע היתה טענה זו טענה אבל כיון שה' הוא המכה את יושבי הארץ לפניהם מה מקום לחשש סכנת מלחמות, וזה לך האות הארץ אשר הכה ה' לפניהם, וזה סימן לכל הארץ דכתיב בפרשת דברים (ג' כ''א) ואת יהושע צויתי בעת ההיא לאמר עיניך הרואות את כל אשר עשה ה' אלהיכם לשני מלכי האמורי כן יעשה ה' לכל הממלכות אשר אתה עובר שמה, מעתה אין מקום לטענת פחד המלחמה, ונתכוונו גם כן בזה להסיר מיחוש הנופל בשאלתם שיאמרו שלא עשו כן אלא לפחד מלחמת הארץ:
@1118 **גם** טענת מאיסת ארץ הקדושה נתנו תשובה במאמר **אשר הכה ה'** פירוש על דרך מה שכתב רמב''ם בפרק א' מהלכות תרומות וזה לשונו ארץ ישראל האמורה בכל מקום הוא ארץ שכבשה מלך ישראל או נביא מדעת רוב ישראל אבל יחיד מישראל או שבט שהלכו וכבשו לעצמן מקום אפילו מן הארץ שנתנה לאברהם אינה נקראת ארץ ישראל עד כאן, וכתב עוד שם בדין ארצות שכבש דוד וזה לשונו ומפני מה ירדו ממעלת ארץ ישראל מפני שכבש אותם קודם שיכבוש כל ארץ ישראל שנשאר בה מז' עממין עד כאן, ועיקר דין זה הובא בספרי (סוף פ' עקב) שלמדו דין שאר ארצות מארץ ישראל מפסוק (דברים י''א) כל מקום אשר תדרוך כף רגלכם בו לכם יהיה ללמד על מקומות שכיבשו חוץ מארץ ישראל שהוא מן המדבר והלבנון וגו' עד הים האחרון וגו', ולמדו שצריך להקדים ארץ ישראל מרכתיב קודם מאמר כל מקום וירשתם גוים גדולים וגו' שלא תהיה ארץ ישראל מטמאה בגילולים ואתם מכבשים חוצה לארץ וכו' עד כאן, הדברים יגידו שזולת טעם הקדימה כל שכבשוה רוב ישראל דין ארץ ישראל יש לה לכל דבר, והוא מאמר בני גד ובני ראובן **הארץ אשר הכה ה' לפני עדת ישראל** פירוש ארץ זו קדושת הארץ יש לה לטעם שכבשוה לפני עדת ישראל וכיבוש רבים דינה כארץ ישראל לכל דבריה:
@1118 **ולטענת** מה שדייקו בספרי לומר שכיבוש חוץ לארץ קודם כיבוש הארץ אין לו דין ארץ ישראל ואם כן ארץ סיחון ועוג קודם כבישת הארץ היתה, לזה שללו טענה זו במאמר **אשר הכה ה'** פירוש משונה כיבוש זה לפי שהיה במאמר ה' כי הוא אמר אל משה על ארץ סיחון ואת ארצו החל רש כאמור בפרשת דברים (ב'), וגם על ארץ עוג (שם ג') אמר ה' שם בידך נתתי אותו ואת ארצו ואת כל עמו ועשית לו וגו', מעתה ה' הסכים על הקדימה, ויש גם כן טעם בדבר שלא היו לפניהם ב' כבישות אחד של הארץ ואחד של חוץ לארץ והקדימו של חוץ לארץ כדרך שעשה דוד שלקח ארם צובה קודם שהוריש היבוסי כאמור שם לומר למה הנחתם מלכבוש ארץ ישראל קודם, ואדרבה כבישת ארץ סיחון ועוג היתה צורך כיבוש הארץ כדי שיעברו דרך שם לכובשה, וכבר שלחו לו דברי שלום לתת להם מעבר דרך ארצו ולא אבה, מעתה אין תרעומת נגד שאלתם מה' ומישראל:
@1118 **ובזה** יש טעם נכון למה הוצרכו להזכיר פרטי שמות הארץ, כי למה שנתכוונו במאמר אשר הכה ה' לומר שלא באו לשאול אלא מנכסי גבוה אמרו כי כל פרטי המדינות כלם לא כבשום דרך טבע אלא ה' הכה אותם לפניהם, בין למה שבאו להחזיקם בחזקת קדושת הארץ דקדקו להזכיר כל השמות לומר שכל אחת מהם ישנה בקדושת הארץ ומדינה אחרת זולת אלו אינה בכלל, והיוצא מזה כל עיר שבעבר הירדן זולת אלו אין להם דין ארץ ישראל לפי שאינה כיבוש רבים:
@1118 **ואומרו ארץ מקנה היא ולעבדיך מקנה**, נתכוונו להסיר טענה אחרת והיא, אחר שנסכים לכל הטענות שאמרו עדיין כל שבט ושבט מישראל יבא ויאמר הטענות עצמן ליטול את הארץ כי הטענות עצמן צודקות לכל שבט מישראל, לזה אמרו אין שבט אחר צריך לה כמו שצריכין הם לה לפי שהיא ארץ מקנה ולהם יש מקנה רב:
@1120 **ויאמרו וגו' יותן את הארץ וגו'**. הוצרך לומר תיבת **ויאמרו** הגם שהם עודם מדברים ולא היה הפסק לדבריהם, להעירך כי עד עתה היו מסדרים ההצעה שבאמצעותם תתקבל השאלה כדרך שפירשתי למעלה ומכאן הוא מתחיל מאמר השאלה, ואומרו **יותן** ולא אמרו תתן, לפי מה שפירשתי כי כח נחלת הארץ היא במלך וכהן וישראל לזה אמרו יותן פירוש תהיה הנתינה באופן המועיל, או אם ירצה לתת משה לבדו כמשפט המלך שיכול לתת כמו שכתבתי, או בהסכמת אלעזר והנשיאים כדין חלוקת הארץ:
@1120 **אל תעבירנו את הירדן**. הכוונה בזה על דרך אומרם ז''ל (ב''ב קט:) בפסוק והעברתם את נחלתו לבתו שהבת מעברת הנחלה ממקומה, כמו כן נתכוונו לומר שאם לא יתן להם ארץ המקנה הראויה להם הנה הוא מעביר נחלתם ממקומ ה:
@1120 **עוד** נתכוונו להרים מכשול החשד בהם שבוחרים בארץ זו לצד המנוחה לבל יכנסו לארץ אויביהם, ואמרו שטעם דבריהם אינו אלא לפי שאינם רוצים לנחול בעבר הירדן אלא כאן לצד ההכנה שיש להם ולא כדי שלא יטריחו במלחמות יושבי הארץ כי אין להם בזה אלא העברה:
@1120 **עוד** נתכוונו במאמר **אל תעבירנו** לומר כי יש בזה דבר נאות לישראל שיקילו מעליהם עולם ולא יצטרכו לנחל אותם בארץ:
@1120 **עוד** אפשר שנתכוונו לשלול העברתם עם ישראל כדרך שהתנה עליהם משה לבסוף, וסמכו על הטעם שנתנו בתחילת דבריהם שאמרו אשר הכה ה' ואין צורך לעבור כל חלוץ:
@1121 **ויאמר משה וגו' האחיכם יבואו וגו' ולמה תניאון וגו'**. הן האדון משה רבינו השכיל בדברי בני גד ובני ראובן כל מה שרצו לומר כמו שפירשנו, וטען כנגד מה שאמרו שמנכסי גבוה הם שואלים כי העדה לא עשו דבר, גם מה שנתכוונו לטעון כנגד העתיד שאין טורח בדבר כי ה' הוא עושה נפלאות גדולות לבדו, אמר להם האחיכם יבואו למלחמה פירוש אמת כי ה' הוא הנלחם להם אבל על כל פנים צריכין להזדמן במלחמה, והוא מה שדייק **יבואו למלחמה** ולא אמר האחיכם ילחמו לומר שעל הביאה בלבד הוא תמה, ויש בזה סתירה על טענת מלחמה שעברה וגם טענת מלחמה הבאה בארץ שעל כל פנים כל איש ישראל יש להם יגיעה בדבר, ולמה יבקשו הם יגיע כפם של ישראל, וגמר אומר **ואתם תשבו פה**, נתחכם לומר שהגם שהבטחת ה' היא מושגת שאמירת הגבוה כמסירת הדיוט ואין כאן יגיעה, הלא תשכיל ביאת ישראל למלחמה בערך ישיבתכם פה ותראו כי יש הרגש ליגיעת ביאת המלחמה, ואם כן למה תרצו ליטול דבר שהיא יגיעה של ישראל כיון שאין אתם יגיעים עמהם בביאתכם למלחמת הארץ:
@1121 **גם** נתכוון במאמר **תשבו פה** בטענה הנשמעת כי ארץ סיחון ועוג שהם שואלים נתנה ה' כשהיו מקובצים יחד שבטי ישראל שזכות כלן עמד להנחילם הארץ הלזו וכשהם נוטלים חלקם בארץ נגרע מערך זכות הרבים לפי שהם יושבים פה, ובזה סתר טענתם שנתכוונו במאמר אשר הכה ה' שזה יגיד על מלחמות הארץ שאין טורח לישראל כמו שפירשתי למעלה כי לא כן הוא שאין הדבר דומה:
@1122 **ולמה תניאון וגו'**. פירוש מלבד הטענות עוד קובל אני עליכם למה תניאון את לב וגו', פירוש לו יהיה שאין כוונתכם אלא לטעמים האמורים בדבריכם, עם כל זה יש מקום לרוצה לחשוב שטענותיכם הוא ליראת עם הארץ, והגם שאתם שוללים הדברים שאדרבה אתם חושבים הארץ כאלו כבושה לפני ישראל, אפשר שזה עצה ותחבולה לכסות טעם הניכר שהוא ליראת יושבי הארץ, והן הנה דברי המרגלים שאמרו (י''ג ל''א) שחזק הוא ממנו, והוא אומרו כה עשו אבותיכם וגו', עוד נתכוון לומר להם שהיה להם לחוש לחשד זה אחר שכבר קדם מעשה האבות והיה מה שהיה שפחדו עם בני ישראל מעלות אל הארץ ולזה יש מקום לחשוב הדבר עצמו כשיראו שחלק מהשבטים מבקשים לשבת חוץ לארץ:
@1122 **אשר נתז להם ה'**. נתכוון גם בזה כנגד מה שנתכוונו במאמר אשר הכה ה' וגו' לומר שדין הארץ יש לה, אמר להם שעל כל פנים יש הפרש בין הארץ אשר הם באים שמה מארץ אשר הם רוצים, כי הארץ נתן להם ה' מה שאין כן ארץ סיחון ועוג אינה בכלל ארץ שנתן ה' לאברהם, וכדתניא (ספרי ח''ב רצט) וזה לשונם לתת לך פרט לעבר הירדן שנטלת מעצמך, והגם שסברא זו סברת ר' שמעון אבל תנא קמא דורש דרשה אחרת, מדרבי שמעון נשמע לתנא קמא כי מן הסתם אינם חולקים בעיקר הדבר אם ארץ סיחון ועוג היא בכלל מה שנתן ה' לאברהם אם לאו:
@1122 **גם** מצינו שאמרו רז''ל (במד''ר פ''ז) בעשר קדושות שאין עבר הירדן ראוי לבית המקדש ולשכון השכינה, וכן אמר הכתוב (יהושע כ''ב) אם טמאה ארץ אחוזתכם, הא למדת שיש הפרש בין ארץ סיחון ועוג לארץ ישראל, ואפשר כי מטעם זה לא היה בדעת משה לחלקה לשבטים והיה חפץ שיהיו כל ישראל בארץ אשר נתן ה' להם להיותה יותר קדושה, ועיין בפרשת דברים (ג' י''ג) בפסוק ההוא יקרא ארץ רפאים:
@1131 **ויגשו וגו'**. טעם אומרו **ויגשו** הגם ששם היו עומדים לפניו לדבר אליו, אפשר שנהגו בעצמן הרחקה כשכעס עליהם משה ואמר להם קמתם תחת אבותיכם תרבות אנשים חטאים, לזה כשרצו לדבר אמר הכתוב ויגשו:
@1131 **או** לפי שמדברי משה שתלה להם המניעה בדברים שבידם לתקנם לזה היה להם אבירות לב וחזקו ידים רפות לגשת אליו ביותר ממקום שהיו בו כשדברו אליו דברים הראשונים:
@1131 **גדרות צאן וגו'**. קשה למה הוצרכו למאמר זה של גדרות צאן וגו' שלא היה להם לומר אלא תשובה הסותרת השגותיו של משה האמורה בדבריהם בסמוך שהוא אנחנו נחלץ חושים וגו' לא נשוב וגו' עד התנחל, ויתבאר על פי מה שכתב רמב''ם בפרק י''א מהלכות מכירה וזה לשונו המוכר בית לחבירו או נתנו לו במתנה על מנת שילך עמו לירושלים ביום פלוני והחזיק זה בבית קנה כשילך עמו לירושלים באותו יום, אבל אם התנה ואמר לו אם תלך עמי לירושלים ביום פלוני אתן לך בית זה וכו' והלך עמו באותו היום אף על פי שהחזיק בבית אחר שקיים התנאי לא קנה שזה אסמכתא עד כאן, ובפרק א' מהלכות מכירה כתב וזה לשונו כיצד החזקה מכר לו בית מכר לו שדה או שנתן וכו' כיון שנעל או פרץ או גדר כל שהוא והוא שיועיל מעשיו הרי זה קנה עד כאן לשונו:
@1131 **ועל** פי הדינים נתחכמו בני גד ובני ראובן לדבר דבריהם כיון שמה שלפניהם הוא הדבר בתנאי במציאות עצמו שכתב רמב''ם בפרק י''א מהלכות מכירה שהם מקבלים הארץ בתנאי שיעלו עמהם לארץ ישראל, ולזה הקדימו זכיתם בארץ קודם התנאי שהוא מציאות שכתב בו רמב''ם, ואמרו **גדרות צאן נבנה** וגו' פירוש נחזיק בארץ לזכותינו מעכשיו ותנאי הוא הדבר על מנת שנעלה לארץ עם אחינו ביום שיעלו, ואמרו אופן החזקה **גדרות צאן** וגו' נתכוונו לעשות החזקה בכל המקומות במה שיעשו בו גדרות לצאן וערים לטף פירוש יבנו בדרך שיועילו מעשיהם בארצות כמשפט החזקה:
@1131 **ואם** תאמר למה הוצרכו לומר הדברים והיו יכולין להחזיק מעצמן באין צורך הודעה, הנה כתב רמב''ם בפרק א' מהלכות מכירה וזה לשונו במה דברים אמורים שהחזיק בפני המוכר או הנותן אבל שלא בפני המוכר וכו' צריך שיאמר לו לך חזק וקני ואחר כך אם החזיק קנה אף על פי שהוא שלא בפני הבעלים עד כאן, ולזה נתכוונו כאן לומר ענין החזקה לפניהם כדי שיסכימו שזולת זה אין חזקתם חזקה, ולזה כשהסכים משה על הדבר אמר להם **בנו לכם ערים** וגו', והוא מה שכתב רמב''ם שאמר לו לך חזק וקני:
@1131 **ולסברת** רמב''ן וסיעתו שחולקים עם הרמב''ם בדין זה וסוברים שכל שהתנאי קיומו תלוי ביד הלוקח או המקבל מתנה אין בו דין אסמכתא משום שהמקנה גמר והקנה, כפי זה צריך ליישב טעם מאמר בנין הגדרות וערים כי הוא לבל יתחייבו לעבור הירדן עד שיכינו הגדרות ויבנו הערים ואז יחלצו ללכת עמהם, והוא אומרו גדרות צאן נבנה למקננו וערים לטפנו ואחר כך אנחנו נחלץ חושים וגו':
@1132 **וישב טפנו וגו'**. הוצרך לומר זה, גם לא אמרו כן למעלה כשהזכירו וערים לטפנו, נתכוונו לומר שאם ישבו טפם בערים בצורות אז יכולין להוסיף עוד תנאי אחר שלא ישובו לבניהם עד התנחל איש נחלתו פירוש אחר שיעברו שבע שנים של כיבוש ושבע שנים של חילוק, ואם לא יהיו בערי המבצר פירוש ערים בצורות אלא לשמירה כמצטרך לא יהיו בטוחים בהם להתעכב כל כך ארבע עשרה שנה אלא שבע שנים עד שיכבשו את הארץ, ולזה כתב מאמר וישב טפנו בערי המבצר באמצע שני המאמרים שכולם ענין אחד שהם מאמר ואנחנו נחלץ חושים וגו' עד הביאונום אל מקומם ומאמר לא נשוב אל בתינו עד התנחל וגו' ומן הראוי היה לו להסמיך שני המאמרים שהשני גזרה של הראשון ולא להפסיק בשלא כענין, ולדרכנו יתישב על נכון:
@1132 **גם** יתישב למה אמרו ב' גבולים נגדיים, א' עד אשר אם הביאונום וגו, ' וב' עד התנחל, והגם שהא' אמרו לענין נחלץ חושים והב' לענין השבתם לארצם, עם כל זה מפסוק ראשון משמע שלא חייבו עצמן אלא עד הביאם למקומן ולא עד התנחל, ולדברינו עלה על נכון, ואמר להם משה בנו לכם ערים לטפכם, דקדק לומר **לכם**, פירוש למה שברצונכם שהוא לבנות ערי מבצר, וכן היה דכתיב ויבנו את דיבון ואת עטרות וגו' שאלו הם ערי המבצר שהם העיירות הגדולות שהזכירו בשאלתם, ותמצא שלא חזרו לבתיהם עד אחר י''ד שנה של כיבוש וחילוק:
@1134 **כי לא ננחל וגו' כי באה וגו'**. אומרו כי **לא ננחל**, הוא נתינת טעם למה שאמרו בסמוך עד התנחל בני ישראל וגו' שהוציאו עצמן מהנחלה לזה אמרו טעם שאנו מיחסים הנחלה לישראל ולא לנו מטעם כי לא ננחל אתם כי באה וגו' פירוש מטעם שבאה נחלתנו וגו'. או נתכוונו לומר שאחר שקבלו עליהם כל האמור יודע עתה שטעם שאלתם לא מטעם יראתם ממלחמת העמים הוא כמו שבא החשד בדברי משה אלא מטעם שאין להם נחלה בארץ כי ה' נתן להם נחלתם כבר מעבר הירדן מזרחה:
@1135 **ויאמר אליהם משה אם תעשון וגו' אם תחלצו וגו'**. קשה למה כפל לומר **אם תעשון** וגו' **אם תחלצו** וגו' ולא הספיק באחת מהנה, ולכשנדייק לא היה צריך להשיבם אלא יסכים לדבריהם במה שיקרא ליהושע ולאלעזר ויצו אותם כאמור בסמוך, עוד למה דקדק לומר הזה, עוד מה כוונתו באומרו בסמוך לפני ה':
@1135 **אכן** כוונת מאמר משה היא לפי שראה שדעת בני גד ובני ראובן שרוצים לעבור עם ישראל אינו אלא כדי שיתרצו ויחליטו להם נתינת הארצות ולא לתכלית אחר, ודבר זה אין נכון לעשות כן לענין הצלחת המלחמה כי צריכין בני המלחמה שתהיה מלחמתם להנקם מאויבי ה' להכרית להם כל נשמה ותקרא מלחמת חובת מצות ה', וזה לך לשון רמב''ם בפרק ז' מהלכות מלכים כל הנלחם בכל לבו וכו' ותהיה כוונתו לקדש ה' בלבד מובטח לו שלא ימצא לו שום נזק ולא תגיעהו רעה וכו' ויזכה לחיי עולם הבא עד כאן:
@1135 **על** כן האנשים ההמה כיון שאין הולכים אלא להתקיים בידם הארץ יש מיחוש בחליצתם שלא תועיל, ואפשר שיהיו ניזוקים מהם, אשר על כן נתחכם משה ואמר להם **אם תעשון** וגו' **אם תחלצו** וגו', פירוש כנגד מה שאמרו הם ואנחנו נחלץ חושים וגו' אמר אם תעשון את הדבר הזה, ותיבת זה חוזרת למאמר הנאמר בסמוך, וכנגד מה שכוונתן בהליכה לקיום התנאי אמר אם תחלצו לפני ה' למלחמה, דקדק לומר **לפני ה'** כמאמר רמב''ם שכתב שתהיה כוונתו לקדש ה', וכמו שגמר אומר **עד הורישו את אויביו** פירוש אויביו של הקדוש ברוך הוא, ואין לפרש אויביו של ישראל שהרי לא הוזכר בדברי משה מתחילת דבריו עד עתה זכרון ישראל לומר שעליו חוזר מאמר אויביו, אלא ודאי כי לה' חוזרים הדברים שתהיה כוונתם להנקם מאויבי ה' לקדש שמו יתברך, וכפירוש זה הרווחנו גזרת דברי משה שלא נודע מקומה שכל המאמרים הטיל להם וא''ו בתחילתה, ולדברינו הגזרה היא לפני ה':
@1135 **עוד** נתכוון באומרו **אם תחלצו לפני ה'** להשיבם להמובן בדבריהם שאמרו נחלץ וגו' לפני בני ישראל שזה יגיד שישראל צריכין עזר טבעי, לזה אמר אם תחלצו לפני ה' תחלצו פירוש להרבות זכותכם לפני ה' שאין דומה זכות מאה לזכות מאה ואחד:
@1136 **ועבר לכם כל חלוץ**. ולא הספיק מה שאמר אם תחלצו, בא להתנות דבר שלא הוזכרו בדבריהם והוא שיעברו כולם פירוש כל הראוי לחלוץ צבא, אלא שעדיין קשה שהיה לו לומר בפסוק ראשון אם תחלצו כולכם או אם תעברו כולכם חלוצים:
@1136 **אכן** כוונת משה בזה הוא הבטחה והודעת דיוק הנשמע על זה הדרך שאם **תעשו** וגו' **ותחלצו** וגו' מבטיח כי לא יפול מהם אחד ויהיו שלמים וכן רבים, והוא אומרו **ועבר לכם כל חלוץ** פירוש כולם ולא יפקד מהם איש, ומכלל זה אתה שומע שאם לא יעשו האמור הם מוכנים להשחתה, וכפירוש זה מאמר **ועבר** וגו' הוא גזירה לפסוק שקדם לא תנאי במעשה שהתנאי כבר אמר אם תעשון הדבר הזה שפירושו הוא התנאי שהתנו הם כמו שכתבתי למעלה, ואומרו **לפני ה'** לומר שבזה לא יהיה מסך מבדיל בינם ובין ה' כאומרו (ישעי' נט) עונותיכם היו מבדילין ביניכם לבין אלהיכם, שס''מ הרשע וחילותיו הם המבדילים והם המכלים:
@1136 **עוד** נתכוון לומר **לפני ה'** פירוש שהוא המוריש אויביו כמו שגמר אומר עד הורישו פירוש ה' לאויביו מפניו, וכפירוש זה שיעור הכתוב הוא על זה הדרך **אם תחלצו** ותהיה כוונתכם לפני ה' וגו' אז אינכם צריכין למלחמה אלא העברה לבד לפני ה' והוא יוריש אויביו, והוא אומרו ועבר לכם וגו' לפני ה' היוצא להנקם עד הורישו אויביו הא למדת כי הוא המוריש לפני בני ישראל, ודקדק לומר **מפניו**, לפי שה' שוכן בעיר אשר בחר לו ירושלים החביבה ואינו חפץ לראות אויביו לפניו:
@1137 **ונכבשה הארץ**. צריך לדעת למה לא הספיק במאמר עד הורישו שאמר בסמוך, עוד צריך לדעת למה הוצרך לומר **ואחר תשובו** שמובן הוא מאומרו עד הורישו וגו' הרי גבול ההליכה ומובן מעצמו שישובו אחר כך. אכן כוונת משה בזה הוא הבטחת הטובה הנמשכת מקיום הדברים, כי באמצעות מעשה הקודם יובטחו בכמה הבטחות, א' **ונכבשה הארץ** פירוש ודאי שתכבש הארץ לפני ה', ב' **ואחר תשובו** פירוש הבטיח כל המדבר אליהם שלא יפקדו בכל זמן שיהיו בארץ במלחמות הגדולות וישובו שלימים לביתם, והגם שמצינו (ב''ב קכא:) שיאיר בן מנשה נהרג במלחמת העי, חצי המנשה לא היה מאותם שדבר משה עמהם אז כמובן מהכתובים:
@1137 **עוד** הודיעם שבזה יהיו נקיים מה' ומישראל, פירוש מה' כשיעברו למלחמה על דרך שכתבתי שתהיה כוונתם לקדש שם שמים ולא להנאתם בשביל קיום תנאי הארץ, ומישראל לבל יחשדו שטינא היתה בלבם מהמרגלים כמו שאמר להם משה קמתם תחת אבותיכם תרבות אנשים חטאים שכוונתם לשוב מאחרי ה', ואומרו **והיתה הארץ** וגו' הבטיחם שבזה תתקיים בידם הארץ לאחוזה ולא תהיה נגזלת מהם, וממוצא דבר אתה למד שאם לא יעשו כדבר משה יושללו מכל הבטחות הטובות:
@1137 **ואומרו לפני ה'** אפשר שנתכוון להחזיקם בקדושת הארץ מהטעמים עצמן שאמרו הם בתחילת דבריהם, וזה הוא שיעור דבריו **והיתה הארץ הזאת** וגו' הגם שהוא חוצה לארץ תהיה נחשבת לכם **לאחוזה לפני ה'** פירוש תהיה נחשבת אחוזה זו שהיא לפני ה' וזו היא קדושתה שלטעם זה היא שנחשבת הארץ קדושה לפי שהיא לפני ה' באין רצועת חול מפסקת בינה ובין ה' שוכן הבירה:
@1138 **ואם לא תעשון כן הנה חטאתם**. קשה לא היה לו לומר אלא ואם לא תעשון כן לא תהיה הארץ הזאת לכם. אכן כוונת המאמר הוא שאם לא יעשו כדברי משה שצוה אותם שילכו לקיים מצות מלחמת חובה לעשות נקמה באויבי ה' הגם שיעברו חלוצים הנה חטאתם פירוש מה שלפנינו כבר יש בידכם חטא, והוא מה שדקדק לומר חטאתם לה' כבר:
@1138 **ודעו את חטאתכם וגו'**. פירוש מודיעם שמי שיש חטא בידו ימצאהו בשעת הסכנה ויפרע ממנו, והוא אומרו **אשר תמצא אתכם** בפשיטות, וצא ולמד ממאמרם ז''ל (טוש''ע או''ח סי' נד) שחוזרים מעורכי המלחמה על חטא קל אם שח בין ישתבח ליוצר, וכמו כן ימצאם עון זה ויחסרו כל ההצלחות הרשומים בדבריו, גם אז לא יהיו נקיים מה' ומישראל כי מהמקרה הרע אדרבה יצדיקו כי לא נקיים היו, ועיין מה שפרשתי בתשובת בני גד ובני ראובן שאמרו עבדיך יעשו כאשר אדוני מצוה:
@1139 **והיוצא מפיכם תעשו**. הכוונה במאמר זה שלא יבינו שהחליט להם מאמר בנין הערים וגו' על כל פנים אלא תנאי הוא הדבר. או נתכוון להשיב למה שאמרו שאם יבנו ערי מבצר וישבו שם טפם שיתעכבו עד שינחלו ישראל נחלתם בארץ, לזה אמר **והיוצא** וגו' פירוש פרט זה אם לא הייתם אומרים אותו אין צורך בו למיחוש שיש בענין והיה די בעכבתכם שם עד תשלום שבע שני כיבוש ואין צורך להתעכב שם ארבע עשרה שנה, ולפי שאתם אמרתם כן היוצא מפיכם תעשו, ותמצא שלא התנה עליהם משה אלא עד שנכבשה ולא עד שנחלקה כאמור במאמר התנאים לומר שאין תנאי זה מעכב אלא לקיים היוצא מפיהם:
@1140 **ויאמר בני גד וגו' לאמר עבדיך יעשו וגו'**. קשה א' אומרו **לאמר** למי יאמר משה, ב' מה חידוש בדבריהם **עבדיך יעשו** הלא כבר הם קדמו ואמרו מה שצוה אותם משה, ג' אחר שאמרו בדרך כלל עבדיך יעשו כאשר אדוני מצוה למה הוצרכו לומר עוד **טפנו** וגו' **יהיו שם** וגו' **ועבדיך יעברו**, עוד למה כפלו לומר **כאשר אדוני דובר** והלא כבר אמרו עבדיך יעשו כאשר אדוני מצוה, ד' למה שינה בפסוק ראשון אמר **מצוה** ובפסוק ב' אמר **דובר**:
@1140 **אכן** לפי מה שפירשתי בדברי משה שנתכוון לחדש להם שתהיה כוונת עברתם למלחמה כמשפט אוהבי שמו כמו שכתב רמב''ם בפרק ז' מהלכות מלכים, גם בענין פרט הקדמת ערים לטף לבנין גדרות צאן כאומרם ז''ל (מד''ר כאן) שהם חבבו הממון מטף ומשה הפך להם, לזה השיבו יחד כאיש אחד ויאמר בני גד והסכימו למאמר משה בב' הפרטים שחדש להם משה, והתחילו מהסמוך שהוא ענין חיבוב טפם מממונם ואמרו **טפנו** וגו' **וכל בהמתנו** הרי שהקדימו טפם לבהמתם כדברי משה, ואחר כך אמרו גם כן הודאתם עשות בפרט הראשון שתהיה כוונתם במלחמה לפני ה', והוא אומרם ועבדיך יעברו כל חלוץ צבא לפני ה' כאשר אדוני דובר ולא כמו שאמרו בתחילה נחלץ חושים לפני בני ישראל עד הביאונום וגו':
@1140 **והנה** לצד כי ב' דברים אלו יש עליהם חיוב לקיימם בשביל שכך התנה עליהם משה וכל תנאי שבממון קיים הגם שיהיה המתנה איש הדיוט, לזה נתחכמו בתחילת דבריהם ואמרו כי גם בלא חיוב התנאי עליהם לקיים כל דברי משה נביא ה' דכתיב (דברים יח) אליו תשמעון, והוא מה שנתכוונו במאמר ראשון שאמרו **עבדיך יעשו כאשר אדוני מצוה** אותנו לעשות גם בלא טעם שהוא תנאי נתינת הארץ, ולזה אמר תיבת **לאמר** פירוש במאמרך לבד חובה עלינו לעשות מצותך:
@1140 **גם** ירצה לשון עילוי ורוממות כי דבר זה אמרוהו בני גד ובני ראובן לצד מעלת מלך ונביא, ואחר כך פירשו הדברים ואמרו **עבדיך יעשו כאשר אדוני דובר** פירוש גם מלבד חיוב הבא מחמת המצוה יש חובה עלינו לעשות הגם שלא היה הדבר מצוה אלא דיבור כדברים העוברים בין אדם לחבירו בעניני תנאי מקח וממכר זוכה ומזכה בעניני העולם, והכוונה בזה שמקבלים גם כן עליהם הדבר כדברים שמתחייב אדם לחבירו בתנאי הממון שקיימין כראי מ וצק:
@1144 **ויאמר משה וגו' ונתתם להם**. אמר ונתתם להם שנראה כי הם הנותנים ובסמוך אמר הכתוב ויתן להם משה וגו' את ממלכת וגו', לפי שאין החלט הנתינה אלא אחר קיום התנאי לזה אמר ונתתם, ונשאר לדעת למה אמר **ונתתם** שהיה לו לומר תתנו להם, ואולי שרמז להם הדברים עצמן שאמר לבני גד ובני ראובן שאם ילכו יצליחו כל ישראל בין הנוחלים בארץ בין הנוחלים בעבר הירדן, והוא אומרו **אם יעברו** וגו' **ונכבשה** וגו' הצלחת נוחלי הארץ, **ונתתם** וגו' הצלחת נוחלי עבר הירדן, ורמז זה לא היה נשמע אם היה אומר תתנו להם:
@1145 **ואם לא יעברו חלוצים אתכם**. פירוש הגם שיעברו אחר כך יאחזו בתוככם, וטעם אומרו **ונאחזו** בתוספת וא''ו ולא אמר יאחזו, נתכוון לרמוז דיוק הצלחתם הנשמע מפסוק אם יעברו על זה הדרך ואם לא יעברו אין הצלחתם בארץ הלזו ומעצמן יאחזו בתוככם לצד המצר להם בארץ, ונמצאו בטלו המצוה ושלהם לא הגיעם:
@1146 **ויענו בני גד וגו'**. הוצרכו להחזיר הדברים, גם אמר הכתוב **ויענו** ולא אמר ויאמרו, לפי שאמר משה ונתתם להם חשו שאז תתחיל הנתינה לזה ענו ואמרו כי עברתם חלוצים הוא דבר שחייבן לעשותו בדבר מלך שלטון ומלחמת חובה היא להם, והוא אומרו **את אשר דבר ה' לעבדיך כן נעשה** נחנו נחלץ חושים לפני ה' להלחם באויביו, אבל הנתינה היא מעכשיו, והוא אומרו **ואתנו אחו זת נחלתינו**, והם לא הבינו כוונת דברי משה כמו שפירשנוהו, ולזה תכף נתן להם ובזה גילה דעתו כי כוונתו במאמר ונתתם להם היא בידם כמו שפירשתי:
@1146 **או** אפשר שגם משה דעתו היה שלא יתחיל זכותם בה אלא אחר התנאי וכשראה חוזק רצונם במעשה הטוב הסכים ונתנה להם תכף ומיד:
@1146 **חסלת פרשת מטות**
@1158 **אלה מסעי וגו'**. רז''ל (ב''ר פ''ו) אמרו כל מקום שנאמר אלה פסל הקודמים, ובמה שלפנינו לא ראינו שקדמו במאמר מסעות זולתם לומר שנתכוון הכתוב לפוסלם. והיה נראה כי נתכוון לפסול כל מסעות זולתם שישנם בעולם הגם שלא הוזכרו, אלא שרואני שלא היו המסעות לשבח ולואי שלא היו בעולם כי רובם היו ליסורין של עון המרגלים, גם הקודמים היו דרך רחוקה לבל יתנו ראש וישובו דכתיב (שמות יג) ולא נחם אלהים דרך ארץ פלשתים, הא למדת שלא היה לרצון ולסדר הנכון למועדי רגל, גם אמרו רז''ל (ילקוט יתרו רעג) וזה לשונם וכל נתיבותיה שלום בקש הקדוש ברוך הוא ליתן התורה לישראל כשיצאו ממצרים והיו חולקין אלו עם אלו וכו' מה כתיב ויסעו מסוכות ויחנו באיתם היו נוסעים במריבה וחונים במריבה וכו' עד כאן, וכפירוש זה אין במסעות אלו דבר יקר הערך לפסול כל זולתם:
@1158 **ואפשר** כי לפי שיש במסעות אלה האמורים בפרשה ב' הדרגות, א' הם המסעות שהיו בשנה ראשונה קודם גזרת מרגלים, ב' המסעות שעשו בשביל גזרת המרגלים שלא היה בדעת ה' עשות זולת מה שעשו בב' שנים, ומסעות אלו גרועים הם מערך שלאחריהם, וכנגדן נתכוון ה' במאמר אלה לפוסלם, וזה שיעור הכתוב **אלה מסעי** וגו' פירוש האמורים בסמוך הם המסעות הראוים והצריכין וכל זולתם פסולין הם שלא היו אלא יסורין להניעם במדבר בתוכחות של עון המרגלים:
@1158 **עוד** נראה בהעיר למה בחר הכתוב למנות המסעות ולא החניות ומה גם לדבריהם ז''ל (מד''ר כאן) שאמרו משל למלך וכו' כאן ישננו כאן וכו' עד כאן, שזה יותר בזכרון החניות לא במסעות, גם לפי מדרש אחר (תנחומא) שאמרו שהזכיר המסעות לקבוע להם שכר לעתיד לבא דכתיב (ישעי' לה) ישושום מדבר וגו' לפי זה היה ראוי למנות החניות:
@1158 **אכן** יתבאר על פי דברי אנשי אמת (זוח''ב קנז.) שאמרו שהליכת ישראל במדבר היתה לברר ניצוצי הקדושה שאנס איש הבליעל החונה במדבר השמם ששם קנה מקומו מקום נחש שרף ועקרב ודרכו שם עדת ה' להוציא בולעו מפיו, והוא הטעם שהיו ישראל חונים במקום אחד שנה ובמקום אחר י''ב שעות שהוא כפי מה שצריך לבירור הניצוצות שישנם במקום ההוא, ובירור זה אין כח בעולם שיכול עשותו זולת קדושה השלמה ובסוד שלימות מחברת הכללות ומחברת הפרטות, קדושה השלמה היא השכינה וישראל והתורה, ומחברת הפרטות הם ס' ריבוא נשמות קדושות, מחברת הכללות הוא משה רבינו בסוד משה עמו, כי הוא אילן שממנו נוצצו נשמות ס' ריבוא שהיו שם, ונסתייעו בעזר אלהי בשכונת שוכן הבירה ושברו מלתעות עול וביררו בירור עצום:
@1158 **וכפי** זה תכלית המעשה הוא כשנוסעים היו נוסעים עמהם כל הדומה למין הקודש לא בזמן החניה שעדיין לא נעשה עמו דבר, והוא מה שרמז במאמר **אלה מסעי** אלה פסל כל המסעות שבעולם שאין מסע כזה שהיו נוסעים עמהם הון קדוש ויקר שאין ערוך אליו, והגם שקדמו האבות ודרכו מקומות ועשו חלקם בבירורי ניצוצות, לא הגיעו לגדר זה, ואמר הכתוב עצמו טעם עילוי מסעות אלה לפי שהם של בני ישראל **אשר יצאו מארץ מצרים** ונצרפו בכור הברזל שהיא ארץ מצרים כאמור ובזה היו נשמותם ראוים לברר ניצוצי הקדושה בכל המקום אשר יבואו שמה, ועוד **לצבאותם** שהיא שלימות הצבא אשר תשרה עליו השכינה שהוא מספר ס' ריבוא ופחות ממספר זה אינו בגדר השלימות:
@1158 **ותמצא** שאמרו ז''ל (ב''ר פע''א מכילתא יתרו) כי לסיבה זו לא נתן ה' התורה לראשונים שלא היה בהם שלימות הצבא שתשרה עליהם שכינה הנקראת צבאות, גם רמז בתיבת **לצבאותם** השראת שכינה עמהם, הרי לפניך זכרון עם קדוש וזכרון מספר השלם והשראת השכינה, וכנגד מחברת כללות מספר השלם אמר ביד משה ואהרן, משה הוא מחברת מספר השלם, ואהרן הוא שושבין השכינה המקריב ומיחד אליה כל הענפים כידוע בסוד הקרבן:
@1158 **אשר יצאו מארץ מצרים לצבאותם**. לפי מה שפירשנו כי תיבת אלה הגידה על המסעות המובחרים ופסלה מסעות הגרועים סמך הכתוב למאמר אלה מאמר **אשר יצאו** וגו' **לצבאותם** להעירך כי המובחרים הם אותם שקדמו למרגלים שהם בני ישראל שיצאו מארץ מצרים לצבאותם פירוש הצבאות עצמן שיצאו לשלול מסעות שהיו מזמן המרגלים שלא היו לצבאותם שנגזרה גזירה למות במדבר ומאותה שנה עצמה מתו חלק מהם ולא היה בנמצא הצבאות שיצאו ממצרים, ואומרו **ביד משה ואהרן** פירוש המסעות היו בידם דכתיב בפרשת בהעלותך (ט' כ') ועל פי ה' יסעו וגו' על פי ה' ביד משה וסמך עמו אהרן שאהרן הוא התוקע בחצוצרות למסעם לזה שתפו עם משה:
@1159 **ויכתוב משה את מוצאיהם וגו'**. צריך לדעת מה מודיענו הכתוב במאמר זה, אם לומר שמשה כתבם הלא כל התורה משה כתבה והמסעות הכתובים בתורה מכלל התורה, עוד היה לו לומר ויכתוב משה את מסעיהם, עוד למה חזר לומר **ואלה מסעיהם** וגו' והלא כבר אמר אלה מסעי וגו', עוד למה שינה בתחלה הקדים לומר **למוצאיהם** ואחר כך אמר **למסעיהם** ואחר כך הקדים תיבת **למסעיהם** לתיבת **למוצאיהם**:
@1159 **ונראה** שהכתוב נתכוון להודיענו סדר כתיבת המסעות שלא נכתבו ביום אחד אלא על זה הסדר שהתחיל משה לכתוב בפנקסו במצות המלך מיום שיצאו ממצרים על זה הדרך יום שיצאו ממצרים כתב פסוק ויסעו בני ישראל מרעמסס וגו' ב' כתובים הבאים כאחד הכתובים לפנינו עד תיבת שפטים, וכשחנו בסוכות כתב פסוק ויסעו וגו' ויחנו בסוכות, וכשנסעו מסוכות כתב ויסעו מסוכות, וכשחנו באיתם כתב ויחנו באיתם, וכן על זה הדרך היה כותב כל מסע בזמנו עד שהגיעו לערבות מואב, ואחר כך אמר ה' אליו שיסדרם בתורה כדרך שהיו כתובים אצלו, והוא מה שאמר הכתוב **ויכתוב משה את מוצאיהם** פירוש יום שיצאו ממצרים והם ב' הכתובים מויסעו מרעמסס עד תיבת שפטים, ואומרו **למסעיהם** פירוש לסדר כל מסעיהם שנסעו מיום צאתם ממצרים עד סוף המסעות, ואומרו **על פי ה'** לומר שמכתב הראשון עצמו היה על פי ה' הוא אמר אליו שיהיה כותב והולך, ואומרו **ואלה מסעיהם** וגו' פירוש אלה הם המסעות האמורים שכתב משה **למוצאיהם** כל אחד בזמנו ובמקומו וזה העתקה:
@1160 **ויסעו מרעמסס וגומר**. הוצרך לומר זכרון **בחדש הראשון** ב' פעמים הגם שהיה יכול לומר בחמשה עשר יום ומובן הדבר שבחודש הראשון מדבר הכתוב, או על זה הדרך ויסעו בט''ו לחודש הראשון, אולי שרמז מה שאמרו רבותינו ז''ל (שמו''ר פט''ו) כי חודש ניסן הוא זמן שמזלם של ישראל עומד, גם זמן שלימות ההצלחה בו הוא ט''ו בחודש, והוא אומרו **ויסעו** וגו' **בחודש הראשון** שהוא זמן העמדת מזלם, ועוד לתוספת גודל המערכה בט''ו שהוא זמן מילוי הלבנה, ואומרו **לחודש הראשון** לפי שאין גדר זה מורה על רום ההצלחה אלא כשהוא בחודש המוצלח:
@1162 **ויסעו וגו' ויחנו בסוכות**. קשה הלא כבר אמר ויסעו בני ישראל מרעמסם וגו' ולא היה צריך לומר אלא ויחנו בסוכות. ונראה שנתכוין לומר שלא היה מסע אחר בין רעמסם לסוכות, והוא מה שסמך לויסעו ויחנו, וזולת זה אם היה מתחיל ויחנו בסוכות אין הערה לזה, וכמו כן דקדק בכל המסעות להסמיך החניה למסע, חוץ מז' עממין הנמצאין שם, ולזה דקדק לומר **את כל יושבי הארץ** לומר אפילו שאינם מז' עממין. או אפשר שחוזר על אומה שאין כח בהם להורגם שישתדלו להורישם ולא יניחו מהם בארץ:
@1210 **והורשתם את וגו' וישבתם וגו'**. רש''י ז''ל פירש שהמצוה היא והורשתם אבל וישבתם הוא הבטחה, ורמב''ן ז''ל פירש שהמצוה היא וישבתם ומכאן סמכו לומר (כתובות קי.) הכל מעלין לארץ ישראל:
@1210 **ונראה** פשט הכתוב כדברי רש''י ממה שגמר אומר **כי לכם** וגו' **לרשת אותה**, ואם הישיבה היא המצוה היה לו לתלות בעיקר המצוה ולומר כי לכם וגו' לשבת בה:
@1212 **ואם לא תורישו וגו' והיה וגו'**. לדבריהם ז''ל (מגילה י:) שאמרו כל מקום שנאמר והיה הוא לשון שמחה כאן נתכוין לומר שהגם שהם יותירו אותם לצד הרצון והשמחה בהם לצורכיהם הוא מבשרם שיהיו לשיכים וגו':
@1212 **וצרר ו אתכם על הארץ וגו'**. פירוש לא מלבד שיחזיקו בחלק מהארץ שלא זכיתם בו אלא גם חלק שזכיתם בו אתם וישבתם בו וצררו אתכם על חלק שאתם יושבים בו לומר קומו צאו ממנו, ופירוש תיבת **על** כדרך אומרו (כ' כ''ד) על אשר מריתם פי על אשר לא קדשתם (דכרים לב נא):
@1213 **כאשר דמיתי וגו'**. פירוש חשבתי במצותי זו לכם ואתם לא עשיתם ותשאר מחשבתי עומדת בלא קיום וקימה בהם:
@1227 **כי לקחו מטה וגו'**. פירוש נתינת טעם להקודם למה הגביל ה' גבולות הארץ בסדר זה כי לקחו מטה וגו' אבל זולת זה אפשר שהיה ה' מרחיב להם הגבול יותר מהגבולות האמורים בענין:
@1227 **לקחו נחלתם**. הוצרך לכפול מאמר זה פעם ב', לפי שחצי שבט מנשה לא בא עם בני גד ובני ראובן יחד לזה יחד לו לקיחה כפני עצמו, וכפי זה מאמר **לקחו נחלתם** חוזר לחצי שבט מנשה, ולזה הפסיק הכתוב במאמר **לבית אבותם** בין ב' המטות לחצי שבט מנשה, עוד ירצה בכפל הדברים לומר כי מה שלקחו הוא כפי נחלתם באמת כי בא להם נחלתם שם כדבריהם שאמרו באה נחלתינו אלינו:
@1228 **שני המטות וגו' לקחו וגו'**. נתכוין במאמר זה לומר שנחלתם היתה יחד ממשה מעבר הירדן וגו' ולא חלק משה חלק לכל אחד בפני עצמו:
@1232 **למטה יהודה וגו'**. צריך לדעת למה נשתנו מטה יהודה ומטה שמעון ומטה בנימין שלא הזכיר נשיא בהם, ואולי כי להיותם סמוכים לזכרון נשיא אחד נשיא אחד מובן כי הם נשיאים ומשלשה ואילך הופלג זכרון הנשיאות והוצרך הכתוב לזוכרו בכל אחד:
@1232 **וראיתי** בשם רבינו ניסים גאון כי ביהודה לא הוצרך כי ידוע כלב לנשיא, שמעון לא היה ראוי לנשיא משום מעשה זמרי, בנימין אלידד זה אלדד וכבר זכה לנבואה והורדה היא לו לקרות נשיא עד כאן:
@1232 **ואפשר** עוד לומר כי לא יחס נשיאות לכלב על יהודה משום כבוד מלכות שעומדת ממנו, וכמו כן לבנימין משום שממנו מתחלת המלכות בישראל שהוא שאול איש ימיני, ושמעון טעמו נכון כדברי גאון:
@1244 **ונתנו ללוים וגו'**. פירוש הגם שצוה ה' שלא יהיה ללוים חלק ונחלה בארץ אבל בתורת חסד יתנו להם מתנת חנם ממה שהגיעם, כדין שמפרנסים מי שהשיגה (אולי צריך לומר שלא השיגה) ידו, והוא מה שדקדק לומר **ערים לשבת** פירוש לצד ההכרח לשבת בהם וגו', ולזה כפל לומר אחר כך **והיו הערים להם לשבת** להעירך כי מאמר לשבת ראשון היא טעם הנתינה ומאמר והיו הערים להם לשבת הוא לומר לך שצריך שיהיו ראוים לישיבה, ורז''ל אמרו (מכות י''ב. ערכין לג) שבא לומר שהערים יהיו לישיבה שאין עושין עיר מגרש:
@1245 **ולכל חיתם**. פשט הכתוב הוא לכל צרכיהם, אלא שלא היה צריך לומר וכלול הוא בכלל רכושם שאמר הכתוב, ורז''ל במסכת מכות (יב.) פירשו שבא לומר שלא ניתנו אלא לחיים ולא לקבורה שאין קוברין בהם אלא הרוצח שבא בו מאמר ה' כי שם תהיה קבורתו. ולדבריהם ז''ל קשה תיבת ולכל כיון שלא בא מאמר ולכל חיתם אלא למעט קבורת מתים לחיתם היה לו לומר כי ולכל משמע שמרבה בתשמישי המגרש, ומה גם בתוספת וא''ו ולכל חיתם רבוי, ורצה לומר ולכל ריבוי והשכילו שהמיעוט הוא הנשמע מתיבת חיתם עצמה, או לפי שנתכוין למעט הקבורה הוצרך לרבות כל חוץ ממנה, וזה שיעור הכתוב **ולכל** מין תשמיש שהוא לחיים הא למדת שלא מיעט אלא לקבורה, ואם היה אומר לחיתם היה נשמע שמיעט כל שאינו לצורך חיתם לגמרי ויכנסו בגדר האיסור דברים אחרים לבד הקבורה:
@1248 **ואת הערים וגו' את שש ערי המקלט**. מכאן משמע כי השש ערי מקלט הם לגולין ולא ללוים, ומאומרו בפסוק שאחר זה שאמר **כל הערים אשר תתנו ללוים** מ''ח משמע שלזכות הלוים הם גם הששה. ונראה כי נתכוון הכתוב בזה לתת זכות שוה לישראל הגולין וללוים שיד כולן שוה, לכן בפסוק ראשון אמר זכות לגולין שיהיו שש ערי מקלט להם לדור בהם, ובפסוק ב' נתן זכות ללוים, הא למדת שהם של לוים והם של הגולין ואין הגולין מעלין שכר, וכן העלו בסוף הגולין (יג.) לכל הסברות, וסובר אני שבן לוי נדחה מפני ישראל הגולה אם רבו הרצחנים והוצרכו לשש עיירות ידחו הלוים מהם שהרי הקדים הכתוב זכות לגולין:
@1281 **ויצו משה את בני ישראל וגו'**. פירוש שצוה אותם על פי ה' שצוהו לאמר לישראל ומה צוה, כן מטה בני יוסף וגו' פירוש שבאה המצוה מה' שטענתם ודבריהם אמת, והכוונה בזה לכבוד ולתפארת בני יוסף:
@1282 **זה הדבר**. אומרו **זה הדבר**, יתבאר על פי מה שאמרו במסכת בבא בתרא (קכ.) וזה לשונם בנות צלפחד הותרו לינשא לכל מי שירצו שנאמר לטוב בעיניהם אלא מה אני מקיים אך למשפחת אביהן וגו' עצה טובה וכו' עד כאן, והוא אומרו **זה הדבר** פירוש לפי שקדם ואמר כן מטה בני יוסף דוברים שהדין עמם וחזר ופירש שדין זה של בנות צלפחד לא נכלל בגדר גזירת משפט זה, והוא אומרו **זה הדבר אשר צוה ה'** לבנות צלפחד שהרשות בידם לטוב בעיניהם וגו', ודקדק לומר זה לומר ולא אחר שלא עשה ה' מעלה זו ברשיון זה אלא להם, והוא מה שרמז באומרו בנות צלפחד **לאמר** שאין לתיבת לאמר משמעות, ולדרכנו יכוין לומר כי בא האלהים במאמר זה לרומם כבודם:
@1285 **ולא תסוב נחלה ממטה וגו'**. טעם שכפל המאמר עצמו שאמר בסמוך ולא תסוב וגו', לפי מה שכתבתי בסמוך שאין זה אלא עצה טובה, בא מאמר ב' לחיוב לכל בני ישראל שאליהם באה מצות וכל בת יורשת וגו' האמורה קודם לזה:
@1286 **כאשר צוה ה' את משה כן עשו**. צריך לדעת למה שינה הכתוב מאמר זה מסדר הרגיל שמקדים המעשה ואחר כך יאמר כאשר צוה וכאן הקדים מאמר **כאשר** וגו' ואחר כך אמר **כן עשו**:
@1286 **ונראה** כי לפי שה' עשה להם יתרון לבנות צלפחד ומעלה והתיר להם לינשא לכל אדם והוציאם מכלל מצוה הכללית, בא הכתוב להודיענו שהגם שה' עשה הבחירה בידם אף על פי כן לא עשו אלא כמצות המלך לעם בני ישראל, והוא אומרו **כאשר צוה** וגו' פירוש כמצוה הכללית כן עשו ולא כרשיון שנתן להם, ולזה אם היה אומר ויעשו בנות צלפחד וגו' כאשר צוה יהיה נשמע שההודעה באה לומר המעשה שעשו ומודיע במאמר כאשר צוה ה' כסדר הרגיל לומר, אבל מאומרו בתחילה **כאשר צוה ה'** ואחר כך הודעת המעשה זה יגיד כי לא בא להודיע המעשה אלא לשלול רשיון הפך מצוה הכללית והבן:
@1286 **חסלת פרשת מסעי**, **סליק ספר במדבר**
